def _doc_link_from_gestoria_doc_row(doc_row):
    if not doc_row:
        return "", ""
    try:
        row = dict(doc_row) if not isinstance(doc_row, dict) else doc_row
    except Exception:
        return "", ""
    doc_key = _normalize_doc_key_for_ui(row.get("doc_key") or "")
    if not doc_key:
        doc_key = _normalize_doc_key_for_ui(row.get("repo_key") or "")
    doc_url = str(row.get("doc_url") or "").strip()
    if not _is_public_doc_url(doc_url):
        doc_url = ""
    return doc_key, doc_url


def _gestoria_doc_visible_for_user(conn, session, empresa_id):
    if workspace_actor_is_privileged(conn, session):
        return True
    ok, _ = enforce_empresa_membership(conn, session, empresa_id)
    return bool(ok)


def _s3_grant_key(session, key, *, ttl_seconds=None, conn=None):
    if not session:
        return
    uid = str(session.get("user_id") or "").strip()
    if not uid:
        return
    safe = _normalize_s3_key(key)
    if not safe:
        return
    ttl = int(ttl_seconds or S3_GRANT_TTL_SECONDS)
    ttl = max(60, min(24 * 3600, ttl))
    expires = time.time() + ttl
    try:
        with S3_GRANTS_LOCK:
            bucket = S3_GRANTS.get(uid)
            if not bucket:
                bucket = {}
                S3_GRANTS[uid] = bucket
            bucket[safe] = expires
            # best-effort cleanup
            for k, exp in list(bucket.items()):
                if exp and exp < time.time():
                    bucket.pop(k, None)
            if len(bucket) > 512:
                # keep newest-ish by expiry
                items = sorted(bucket.items(), key=lambda it: float(it[1] or 0), reverse=True)[:512]
                S3_GRANTS[uid] = {k: exp for k, exp in items}
    except Exception:
        return
    if not conn:
        return
    try:
        ensure_s3_grants_table(conn)
        conn.execute(
            """
            INSERT INTO s3_grants (user_id, key, expires_at, created_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(user_id, key) DO UPDATE SET
              expires_at=excluded.expires_at
            """,
            (uid, safe, float(expires), float(time.time())),
        )
    except Exception:
        return


def _s3_key_granted(session, key, *, conn=None):
    if not session:
        return False
    uid = str(session.get("user_id") or "").strip()
    safe = _normalize_s3_key(key)
    if not uid or not safe:
        return False
    now_ts = time.time()
    try:
        with S3_GRANTS_LOCK:
            bucket = S3_GRANTS.get(uid) or {}
            exp = bucket.get(safe)
            if exp and exp > now_ts:
                return True
            if exp:
                bucket.pop(safe, None)
    except Exception:
        return False
    if not conn:
        return False
    try:
        ensure_s3_grants_table(conn)
        row = conn.execute(
            "SELECT expires_at FROM s3_grants WHERE user_id = ? AND key = ?",
            (uid, safe),
        ).fetchone()
        exp = float(row[0] if row else 0)
        if exp and exp > now_ts:
            try:
                with S3_GRANTS_LOCK:
                    bucket = S3_GRANTS.get(uid) or {}
                    bucket[safe] = exp
                    S3_GRANTS[uid] = bucket
            except Exception:
                pass
            return True
        if exp:
            try:
                conn.execute("DELETE FROM s3_grants WHERE user_id = ? AND key = ?", (uid, safe))
            except Exception:
                pass
    except Exception:
        return False
    return False


def _s3_key_visible_for_user(conn, session, key):
    """
    Autoriza acceso a un objeto S3 si:
    - El usuario es privilegiado, o
    - El key fue emitido por este servidor para este usuario recientemente (grant), o
    - El key está referenciado en registros DB accesibles por el usuario (multi-tenant).
    """
    if not S3_SCOPE_ENFORCE:
        return True, ""
    if workspace_actor_is_privileged(conn, session):
        return True, ""
    uid = str((session or {}).get("user_id") or "").strip()
    safe_key = _normalize_s3_key(key)
    if not uid or not safe_key:
        return False, "No autorizado"
    if _s3_key_granted(session, safe_key, conn=conn):
        return True, ""

    cache_key = (uid, safe_key)
    now_ts = time.time()
    try:
        with S3_AUTH_CACHE_LOCK:
            cached = S3_AUTH_CACHE.get(cache_key)
            if cached and cached[0] > now_ts:
                return bool(cached[1]), "" if cached[1] else "No autorizado"
    except Exception:
        cached = None

    s3_url_value = f"s3://{safe_key}"
    ok = False
    try:
        # 1) Workspace tables con workspace_id directo
        row = conn.execute(
            """
            SELECT 1
            FROM workspace_documentos_inbox q
            JOIN workspace_miembros m ON m.workspace_id = q.workspace_id AND m.usuario_id = ?
            WHERE q.doc_key = ? OR q.doc_url = ?
            LIMIT 1
            """,
            (uid, safe_key, s3_url_value),
        ).fetchone()
        ok = bool(row)
    except Exception:
        ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM workspace_rrhh_documentos d
                JOIN workspace_miembros m ON m.workspace_id = d.workspace_id AND m.usuario_id = ?
                WHERE d.doc_key = ? OR d.doc_url = ?
                LIMIT 1
                """,
                (uid, safe_key, s3_url_value),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM workspace_rrhh_gastos g
                JOIN workspace_miembros m ON m.workspace_id = g.workspace_id AND m.usuario_id = ?
                WHERE g.doc_key = ? OR g.doc_url = ?
                LIMIT 1
                """,
                (uid, safe_key, s3_url_value),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM workspace_registro_personal p
                JOIN workspace_miembros m ON m.workspace_id = p.workspace_id AND m.usuario_id = ?
                WHERE p.foto_url = ? OR p.foto_url = ?
                LIMIT 1
                """,
                (uid, safe_key, s3_url_value),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False

    # 1b) Fincas (comunidades y presupuestos)
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM workspace_fincas_comunidades c
                JOIN workspace_miembros m ON m.workspace_id = c.workspace_id AND m.usuario_id = ?
                WHERE c.foto_edificio_key = ? OR c.foto_edificio_key = ?
                LIMIT 1
                """,
                (uid, safe_key, s3_url_value),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            # calculo_json guarda el key como string (p.ej. {"edificio_foto_key":"..."}). Usamos LIKE para compatibilidad.
            like_plain = f'%\"edificio_foto_key\"%\"{safe_key}\"%'
            like_s3 = f'%\"edificio_foto_key\"%\"{s3_url_value}\"%'
            row = conn.execute(
                """
                SELECT 1
                FROM workspace_presupuestos p
                JOIN workspace_miembros m ON m.workspace_id = p.workspace_id AND m.usuario_id = ?
                WHERE (p.calculo_json LIKE ? OR p.calculo_json LIKE ?)
                LIMIT 1
                """,
                (uid, like_plain, like_s3),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False

    # 2) Tablas por empresa_id → workspace_empresas → workspace_miembros
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM gestoria_docs d
                JOIN workspace_empresas we ON we.empresa_id = d.empresa_id
                JOIN workspace_miembros m ON m.workspace_id = we.workspace_id AND m.usuario_id = ?
                WHERE d.doc_key = ? OR d.doc_url = ?
                LIMIT 1
                """,
                (uid, safe_key, s3_url_value),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM gestoria_facturas f
                JOIN workspace_empresas we ON we.empresa_id = f.empresa_id
                JOIN workspace_miembros m ON m.workspace_id = we.workspace_id AND m.usuario_id = ?
                WHERE f.doc_key = ?
                LIMIT 1
                """,
                (uid, safe_key),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM gestoria_import_documentos d
                JOIN workspace_empresas we ON we.empresa_id = d.empresa_id
                JOIN workspace_miembros m ON m.workspace_id = we.workspace_id AND m.usuario_id = ?
                WHERE d.doc_key = ?
                LIMIT 1
                """,
                (uid, safe_key),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM seguros s
                JOIN workspace_empresas we ON we.empresa_id = s.empresa_id
                JOIN workspace_miembros m ON m.workspace_id = we.workspace_id AND m.usuario_id = ?
                WHERE s.poliza_key = ?
                LIMIT 1
                """,
                (uid, safe_key),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok:
        try:
            row = conn.execute(
                """
                SELECT 1
                FROM inmueble_docs idoc
                JOIN inmuebles i ON i.id = idoc.inmueble_id
                JOIN workspace_empresas we ON we.empresa_id = i.empresa_id
                JOIN workspace_miembros m ON m.workspace_id = we.workspace_id AND m.usuario_id = ?
                WHERE idoc.url = ?
                LIMIT 1
                """,
                (uid, s3_url_value),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False
    if not ok and safe_key.startswith("company_logos/"):
        try:
            # Logos de empresas: visibles para miembros del workspace vinculado a esa empresa.
            row = conn.execute(
                """
                SELECT 1
                FROM empresas e
                JOIN workspace_empresas we ON we.empresa_id = e.id
                JOIN workspace_miembros m ON m.workspace_id = we.workspace_id AND m.usuario_id = ?
                WHERE e.logo_url = ? OR e.logo_url = ? OR e.logo_url LIKE ?
                LIMIT 1
                """,
                (uid, s3_url_value, safe_key, f"%/{safe_key}"),
            ).fetchone()
            ok = bool(row)
        except Exception:
            ok = False

    try:
        with S3_AUTH_CACHE_LOCK:
            S3_AUTH_CACHE[cache_key] = (now_ts + 120.0, bool(ok))
            # cleanup best-effort
            if len(S3_AUTH_CACHE) > 5000:
                for k, (exp, _ok) in list(S3_AUTH_CACHE.items())[:1000]:
                    if exp < now_ts:
                        S3_AUTH_CACHE.pop(k, None)
    except Exception:
        pass
    return bool(ok), "" if ok else "No autorizado"

def load_env_file():
    if not ENV_PATH.exists():
        return
    try:
        with ENV_PATH.open("r", encoding="utf-8") as handle:
            for line in handle:
                raw = line.strip()
                if not raw or raw.startswith("#") or "=" not in raw:
                    continue
                key, value = raw.split("=", 1)
                key = key.strip()
                value = value.strip().strip('"').strip("'")
                if key and key not in os.environ:
                    os.environ[key] = value
    except Exception:
        return

