def ensure_auth_sessions_table(conn):
    # Persist auth sessions in DB so Render restarts / multi-worker deployments don't invalidate cookies.
    # This keeps login stable across deploys and avoids sporadic 401s (especially noticeable when entrando al CRM).
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS auth_sessions (
          token TEXT PRIMARY KEY,
          user_id TEXT NOT NULL,
          usuario TEXT,
          nombre TEXT,
          apellido TEXT,
          rol TEXT,
          email TEXT,
          servicio TEXT,
          expires_at REAL NOT NULL,
          created_at REAL NOT NULL
        )
        """
    )
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_auth_sessions_expires_at ON auth_sessions (expires_at)")
    except Exception:
        pass


def ensure_login_rate_limits_table(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS login_rate_limits (
          key TEXT PRIMARY KEY,
          attempts INTEGER NOT NULL DEFAULT 0,
          window_started_at REAL NOT NULL,
          locked_until REAL NOT NULL DEFAULT 0,
          created_at REAL NOT NULL,
          updated_at REAL NOT NULL
        )
        """
    )
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_login_rate_limits_locked_until ON login_rate_limits (locked_until)")
    except Exception:
        pass


def ensure_crm_stage_events_schema(conn):
    """
    Tabla de eventos de etapa (embudo/conversión) para CRM Inmobiliario.
    Se crea de forma perezosa para no romper DBs existentes.
    """
    if not conn:
        return
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS crm_stage_events (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          captacion_id TEXT,
          inmueble_id TEXT,
          from_etapa TEXT,
          to_etapa TEXT NOT NULL,
          usuario TEXT,
          responsable TEXT,
          created_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id)
        )
        """
    )
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_crm_stage_events_empresa_created ON crm_stage_events (empresa_id, created_at)")
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_crm_stage_events_empresa_responsable_created ON crm_stage_events (empresa_id, responsable, created_at)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_crm_stage_events_empresa_to_etapa_created ON crm_stage_events (empresa_id, to_etapa, created_at)"
        )
    except Exception:
        pass


def ensure_empresa_aliases_schema(conn):
    if not conn:
        return
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS empresa_aliases (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          source TEXT NOT NULL,
          alias TEXT NOT NULL,
          alias_norm TEXT NOT NULL,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (source, alias_norm),
          FOREIGN KEY (empresa_id) REFERENCES empresas(id)
        )
        """
    )
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_empresa_aliases_empresa_id ON empresa_aliases (empresa_id)")
    except Exception:
        pass


def resolve_empresa_id_from_alias(conn, alias: str, *, source: str = "onedrive") -> str:
    """
    Resuelve `empresa_id` a partir de un alias externo (p.ej. nombre de carpeta OneDrive).
    - Primero: tabla `empresa_aliases` (match exacto por alias_norm).
    - Fallback conservador: si hay 1 match único por nombre de empresa (contains), se devuelve y se auto-registra el alias.
    """
    if not conn:
        return ""
    raw = str(alias or "").strip()
    if not raw:
        return ""
    ensure_empresa_aliases_schema(conn)
    source_key = (source or "onedrive").strip().lower() or "onedrive"
    alias_norm = normalize_lookup_text(raw)
    if not alias_norm:
        return ""
    row = conn.execute(
        """
        SELECT empresa_id
        FROM empresa_aliases
        WHERE source = ? AND alias_norm = ?
        LIMIT 1
        """,
        (source_key, alias_norm),
    ).fetchone()
    if row and row.get("empresa_id"):
        return str(row["empresa_id"]).strip()

    empresas = conn.execute("SELECT id, nombre FROM empresas WHERE COALESCE(activo, 1) = 1").fetchall()
    candidates = []
    for e in empresas or []:
        try:
            nombre_norm = normalize_lookup_text(e["nombre"] or "")
        except Exception:
            continue
        if not nombre_norm:
            continue
        if alias_norm == nombre_norm or alias_norm in nombre_norm:
            candidates.append(str(e["id"]).strip())
    if len(candidates) != 1:
        return ""
    empresa_id = candidates[0]
    try:
        conn.execute(
            """
            INSERT OR IGNORE INTO empresa_aliases (
              id, empresa_id, source, alias, alias_norm, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, datetime('now'), datetime('now')
            )
            """,
            (os.urandom(16).hex(), empresa_id, source_key, raw, alias_norm),
        )
    except Exception:
        pass
    return empresa_id


def _session_user_label(session):
    if not session:
        return ""
    usuario = str(session.get("usuario") or "").strip()
    if usuario:
        return usuario
    nombre = str(session.get("nombre") or "").strip()
    apellido = str(session.get("apellido") or "").strip()
    return " ".join([chunk for chunk in (nombre, apellido) if chunk]).strip()


def log_crm_stage_event(
    conn,
    empresa_id,
    inmueble_id,
    captacion_id,
    to_etapa,
    now="now",
    from_etapa=None,
    session=None,
    responsable=None,
):
    if not conn:
        return
    eid = str(empresa_id or "").strip()
    to_value = str(to_etapa or "").strip()
    if not eid or not to_value:
        return
    ensure_crm_stage_events_schema(conn)
    usuario = _session_user_label(session) or "Sistema"
    resp_value = str(responsable or "").strip()
    if not resp_value:
        resp_value = usuario if usuario != "Sistema" else ""
    conn.execute(
        """
        INSERT INTO crm_stage_events (
          id, empresa_id, captacion_id, inmueble_id, from_etapa, to_etapa, usuario, responsable, created_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            eid,
            str(captacion_id or "").strip() or None,
            str(inmueble_id or "").strip() or None,
            str(from_etapa or "").strip() or None,
            to_value,
            usuario,
            resp_value or None,
            now,
        ),
    )


