def infer_empresa_id_for_payload(conn, payload):
    """
    Best-effort para reducir errores por `empresa_id requerido` cuando el frontend no envía contexto.
    Solo completa `empresa_id` si se puede inferir desde `empresa_nombre` o `servicio`.
    """
    if not isinstance(payload, dict):
        return ""
    current = str(payload.get("empresa_id") or "").strip()
    if current:
        return current
    # Service-first: si viene workspace_id, evitamos bloquear endpoints legacy que aún exigen empresa_id.
    # Usamos una empresa técnica única (Verifika2) como fallback; el aislamiento real lo hace workspace_id.
    try:
        ws_id = str(payload.get("workspace_id") or "").strip()
    except Exception:
        ws_id = ""
    if ws_id:
        try:
            platform_eid = get_platform_empresa_id(conn)
            if platform_eid:
                return str(platform_eid).strip()
        except Exception:
            pass
    nombre = str(payload.get("empresa_nombre") or payload.get("empresa") or "").strip()
    if nombre:
        try:
            row = conn.execute(
                "SELECT id FROM empresas WHERE nombre = ? AND COALESCE(activo, 1) = 1 LIMIT 1",
                (nombre,),
            ).fetchone()
        except Exception:
            row = None
        if row:
            try:
                return str(row["id"] or "").strip()
            except Exception:
                return str(row[0] or "").strip()
    servicio_raw = str(payload.get("servicio") or "").strip()
    servicio_key = normalize_service_key(servicio_raw)
    if servicio_key == "hipotecas":
        servicio_key = "financiaciones"
    candidates = WORKSPACE_SERVICE_COMPANY_SUGGESTIONS.get(servicio_key, []) if servicio_key else []
    for name in candidates or []:
        try:
            row = conn.execute(
                "SELECT id FROM empresas WHERE nombre = ? AND COALESCE(activo, 1) = 1 LIMIT 1",
                (name,),
            ).fetchone()
        except Exception:
            row = None
        if row:
            try:
                return str(row["id"] or "").strip()
            except Exception:
                return str(row[0] or "").strip()
    return ""


def resolve_empresa_ids_for_request(conn, *, empresa_id="", workspace_id=""):
    """
    Compat: muchos endpoints legacy iban acotados por `empresa_id` y devolvían 400 si faltaba.
    En modo tenant preferimos scoping por `workspace_id`; cuando el endpoint aún no está migrado
    a workspace-first, devolvemos la lista de empresas vinculadas al workspace.

    Devuelve una lista (posiblemente vacía) de empresa_ids a usar en filtros SQL.
    """
    eid = str(empresa_id or "").strip()
    if eid:
        return [eid]
    ws = str(workspace_id or "").strip()
    if not ws:
        return []
    try:
        ids = fetch_workspace_company_ids(conn, ws)
    except Exception:
        ids = []
    out = []
    for item in ids or []:
        val = str(item or "").strip()
        if val:
            out.append(val)
    return out

