def normalize_postal_code(value):
    code = re.sub(r"\D", "", str(value or ""))[:5]
    if len(code) == 4:
        code = f"0{code}"
    return code if len(code) == 5 else ""

def normalize_phone(value):
    if not value:
        return ""
    digits = re.sub(r"\D+", "", str(value))
    if not digits:
        return ""
    if digits.startswith("34") and len(digits) > 9:
        digits = digits[-9:]
    if len(digits) == 9:
        return digits
    return ""

def parse_services_param(raw):
    if not raw:
        return []
    # Compat: algunos flujos guardan servicios como "Gestoría - Administración Fincas" o con separador "·".
    parts = re.split(r"(?:\s+-\s+|[|,;/·]+)", str(raw))
    services = [p.strip().lower() for p in parts if p and p.strip()]
    aliases = {
        "gestoria": "gestoría",
        "administracion fincas": "administración fincas",
        "administracion de fincas": "administración de fincas",
        "administracion_fincas": "administración de fincas",
        "administracion_de_fincas": "administración de fincas",
        "administración fincas": "administración de fincas",
        "administración_de_fincas": "administración de fincas",
        "admin fincas": "fincas",
        "admin de fincas": "fincas",
        "admin_de_fincas": "fincas",
        "fincas": "administración de fincas",
        "administración de fincas": "fincas",
        "inversion": "inversión",
        "direccion": "dirección",
    }
    expanded = []
    for service in services:
        expanded.append(service)
        if service in aliases:
            expanded.append(aliases[service])
    return list(dict.fromkeys(expanded))


