def canonicalize_ramo(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    key = normalize_lookup_text(raw)
    if not key:
        return ""
    canonical_by_key = {normalize_lookup_text(item): item for item in LEGAL_RAMOS_CANONICAL}
    if key in canonical_by_key:
        return canonical_by_key[key]
    # Basura típica OCR/legal: párrafos completos o fragmentos normativos.
    noisy_markers = (
        "EXPECTATIVA RAZONABLE",
        "DIRECCION GENERAL DE SEGUROS",
        "SE CONSIDERARA ACEPTADA",
        "PRODUCTOS COMERCIALIZADOS",
        "ENTRE LOS QUE ESTA EL SEGURO",
        "FEC EFECTO PERIODO PAGO ENVIO DOC",
    )
    if len(key) > 42 or any(marker in key for marker in noisy_markers):
        return ""
    if key in ("S", "RC", "R C", "R C PYME", "RESPONSABILIDAD CIVIL PROFESIONAL"):
        return "Responsabilidad civil"
    if key in ("IT", "INCAPACIDAD TEMPORAL", "INCAPACIDAD PERMANENTE"):
        return "Accidentes"
    if "PROFESIONAL" in key:
        return "Responsabilidad civil"
    if "RESPONSABILIDAD CIVIL" in key:
        return "Responsabilidad civil"
    if key in (
        "ALQUILER",
        "IMPAGO ALQUILER",
        "PROTECCION ALQUILER",
        "PROTECCION DE ALQUILER",
        "PAGO ALQUILER",
        "HOGAR ALQUILER",
    ):
        return "Protección de pagos"
    if (
        "IMPAGO" in key
        or "PROTECCION PAGO" in key
        or "PROTECCION DE PAGO" in key
        or "PROTECCION DE PAGOS" in key
    ):
        return "Protección de pagos"
    if "DEFENSA JURIDICA" in key or key.startswith("ARAG"):
        return "Defensa jurídica"
    if "SALUD" in key or "ASISTENCIA SANITARIA" in key or "DKV INTEGRAL" in key:
        return "Salud"
    if "DECESOS" in key:
        return "Decesos"
    if "ACCIDENT" in key:
        return "Accidentes"
    if "VIDA" in key:
        return "Vida"
    if "AHORRO" in key:
        return "Ahorro"
    if "VIAJE" in key or "VIAJES" in key or "VIAJEROS" in key:
        return "Viaje"
    if "CAZA" in key:
        return "Caza"
    if "COMUNIDAD" in key:
        return "Comunidad"
    if "COMERCIO" in key or "PYME" in key or key == "LOCAL":
        return "Comercio"
    if "HOGAR" in key:
        return "Hogar"
    if (
        "AUTO" in key
        or "AUTOMOVIL" in key
        or "AUTOMOVILES" in key
        or "VEHICULO" in key
        or "MOTO" in key
        or "MOTOR" in key
    ):
        return "Auto"
    # Si no coincide pero no es ruido OCR, se conserva para no perder edición manual.
    return raw


def infer_ramo_from_source_hint(source_hint: str) -> str:
    """
    Dado un nombre/clave de archivo (S3 key, filename, etc.) intenta inferir un ramo canónico.
    Solo devuelve ramos del catálogo LEGAL_RAMOS_CANONICAL (para no distorsionar KPIs).
    """
    key = normalize_lookup_text(source_hint or "")
    if not key:
        return ""
    # Nota: usamos canonicalize_ramo para aprovechar aliases ("RC", "IMPAGO", "MOTO"...)
    for token in (
        "IMPAGO",
        "PROTECCION",
        "PROTECCIÓN",
        "DEFENSA",
        "JURID",
        "ARAG",
        "SALUD",
        "SANIT",
        "DKV",
        "DECESOS",
        "ACCIDENT",
        "VIDA",
        "AHORRO",
        "VIAJE",
        "COMUNIDAD",
        "COMERCIO",
        "PYME",
        "LOCAL",
        "OFICINA",
        "MULTIRRIESGO",
        "HOGAR",
        "AUTO",
        "AUTOMOV",
        "VEHIC",
        "MOTO",
        "MOTOR",
        "RESPONSABILIDAD",
        "RC",
    ):
        if token in key:
            guessed = canonicalize_ramo(token)
            if guessed:
                return guessed
    guessed = canonicalize_ramo(source_hint or "")
    if not guessed:
        return ""
    canonical_keys = {normalize_lookup_text(item) for item in LEGAL_RAMOS_CANONICAL}
    return guessed if normalize_lookup_text(guessed) in canonical_keys else ""
def seguros_comision_tipo_from_produccion(produccion):
    value = normalize_lookup_text(produccion or "")
    if "cambio" in value:
        return "cartera"
    return "nueva produccion"


def parse_seguros_comision_ramo_tipo(value):
    raw = str(value or "").strip()
    match = re.match(r"^(.*)\[(.*)\]\s*$", raw)
    if not match:
        return {"ramo": raw, "tipo": ""}
    return {"ramo": str(match.group(1) or "").strip(), "tipo": str(match.group(2) or "").strip()}


def _safe_iso_date(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    if len(raw) >= 10 and raw[4] == "-" and raw[7] == "-":
        return raw[:10]
    parsed = parse_iso_date(raw)
    return parsed.isoformat() if parsed else ""


def score_seguros_comision_match(rule, compania_key, ramo_key, tipo_key):
    row_comp = normalize_company_key(rule.get("compania") or "")
    if not row_comp or row_comp != compania_key:
        return -1
    parsed = parse_seguros_comision_ramo_tipo(rule.get("ramo") or "")
    row_ramo = normalize_lookup_text(parsed.get("ramo") or "")
    row_tipo = normalize_lookup_text(parsed.get("tipo") or "")
    score = 10
    if row_ramo and ramo_key:
        if row_ramo == ramo_key:
            score += 60
        elif ramo_key in row_ramo or row_ramo in ramo_key:
            score += 35
        else:
            score -= 20
    if row_tipo == tipo_key and row_tipo:
        score += 30
    elif "general" in row_tipo:
        score += 10
    elif "variable" in row_tipo:
        score += 5
    elif row_tipo:
        score -= 10
    return score


def pick_seguros_comision_rule(rules, compania, ramo, *, produccion="", fecha_ref=""):
    compania_key = normalize_company_key(compania or "")
    if not compania_key:
        return None
    tipo_key = normalize_lookup_text(seguros_comision_tipo_from_produccion(produccion))
    ramo_key = normalize_lookup_text(ramo or "")
    fecha_ref = _safe_iso_date(fecha_ref)

    best = None
    best_score = -1
    for rule in rules or []:
        if fecha_ref:
            desde = _safe_iso_date(rule.get("vigencia_desde") or "")
            hasta = _safe_iso_date(rule.get("vigencia_hasta") or "")
            if desde and fecha_ref < desde:
                continue
            if hasta and fecha_ref > hasta:
                continue
        score = score_seguros_comision_match(rule, compania_key, ramo_key, tipo_key)
        if score > best_score:
            best_score = score
            best = rule
    if not best or best_score < 20:
        return None
    try:
        pct = float(best.get("porcentaje"))
    except Exception:
        return None
    if not math.isfinite(pct):
        return None
    return {"pct": pct, "source": f"{best.get('compania') or ''} · {best.get('ramo') or ''}".strip()}


def infer_tipo_vigencia(ramo, explicit=None):
    value = normalize_lookup_text(explicit or "")
    if value in ("TEMPORAL_NO_RENOVABLE", "TEMPORAL", "UN_USO", "NO_RENOVABLE"):
        return "temporal_no_renovable"
    if value in ("ANUAL_RENOVABLE", "RENOVABLE", "ANUAL"):
        return "anual_renovable"
    ramo_key = normalize_lookup_text(ramo or "")
    if any(token in ramo_key for token in ("VIAJE", "VIAJES", "CAZA EVENTUAL")):
        return "temporal_no_renovable"
    return "anual_renovable"


def extract_seguro_smart_payload(payload):
    if not isinstance(payload, dict):
        return {}
    incoming_smart = {}
    raw_smart_payload = payload.get("datos_ramo_json")
    if raw_smart_payload:
        try:
            parsed_smart = (
                json.loads(raw_smart_payload)
                if isinstance(raw_smart_payload, str)
                else raw_smart_payload
            )
            if isinstance(parsed_smart, dict):
                incoming_smart.update(
                    {
                        str(k): v
                        for k, v in parsed_smart.items()
                        if str(v or "").strip() != ""
                    }
                )
        except Exception:
            pass
    for key in SEGURO_SMART_FIELDS:
        val = payload.get(key)
        if val is None:
            continue
        text = str(val).strip()
        if not text:
            continue
        incoming_smart[key] = val
    return incoming_smart


def merge_seguro_smart_data(conn, seguro_id, incoming_smart, now):
    if not seguro_id or not incoming_smart:
        return
    row = conn.execute("SELECT datos_ramo_json FROM seguros WHERE id = ?", (seguro_id,)).fetchone()
    raw_existing = ""
    if row:
        if hasattr(row, "keys"):
            raw_existing = row["datos_ramo_json"]
        else:
            raw_existing = row[0]
    try:
        existing_smart = json.loads(raw_existing) if raw_existing else {}
        if not isinstance(existing_smart, dict):
            existing_smart = {}
    except Exception:
        existing_smart = {}
    merged = dict(existing_smart)
    merged.update(incoming_smart)
    updates = {"datos_ramo_json": json.dumps(merged, ensure_ascii=False)}
    # Campos "rápidos" (filtrado/búsqueda) fuera del JSON, sin romper compat.
    for key in ("matricula", "direccion_riesgo", "referencia_catastral"):
        val = incoming_smart.get(key)
        if val is None:
            continue
        text = str(val).strip()
        if not text:
            continue
        updates[key] = text
    set_clause = ", ".join([f"{key} = ?" for key in updates])
    values = list(updates.values()) + [now, seguro_id]
    conn.execute(f"UPDATE seguros SET {set_clause}, updated_at = datetime(?) WHERE id = ?", values)


def log_seguro_event(conn, seguro_row, event_type, now, motivo="", payload=None):
    if not seguro_row:
        return
    payload_json = ""
    if payload:
        try:
            payload_json = json.dumps(payload, ensure_ascii=False)
        except Exception:
            payload_json = str(payload)
    conn.execute(
        """
        INSERT INTO seguros_eventos (
          id, seguro_id, cliente_id, empresa_id, tipo, fecha, motivo, payload_json, created_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            seguro_row.get("id") if isinstance(seguro_row, dict) else seguro_row["id"],
            (seguro_row.get("cliente_id") if isinstance(seguro_row, dict) else seguro_row["cliente_id"]),
            (seguro_row.get("empresa_id") if isinstance(seguro_row, dict) else seguro_row["empresa_id"]),
            event_type,
            (seguro_row.get("fecha_efecto") if isinstance(seguro_row, dict) else seguro_row["fecha_efecto"]) or now[:10],
            motivo or "",
            payload_json,
            now,
        ),
    )

def _seguro_row_to_dict(row):
    if not row:
        return {}
    if isinstance(row, dict):
        return dict(row)
    try:
        if hasattr(row, "keys"):
            return {k: row[k] for k in row.keys()}
    except Exception:
        pass
    return {}


def _next_seguro_version_no(conn, seguro_id):
    try:
        row = conn.execute(
            "SELECT COALESCE(MAX(version_no), 0) AS max_no FROM seguros_versiones WHERE seguro_id = ?",
            (seguro_id,),
        ).fetchone()
        return int(row_value(row, "max_no", 0) or 0) + 1
    except Exception:
        return 1


def save_seguro_version(conn, seguro_row, now, *, motivo="", created_by=""):
    if not seguro_row:
        return None
    seguro_id = (seguro_row.get("id") if isinstance(seguro_row, dict) else seguro_row["id"]) or ""
    if not str(seguro_id).strip():
        return None
    payload = _seguro_row_to_dict(seguro_row)
    version_no = _next_seguro_version_no(conn, seguro_id)
    version_id = os.urandom(16).hex()
    try:
        snapshot_json = json.dumps(payload, ensure_ascii=False)
    except Exception:
        snapshot_json = "{}"
    conn.execute(
        """
        INSERT INTO seguros_versiones (
          id, seguro_id, version_no, motivo, snapshot_json, created_by, created_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, datetime(?)
        )
        """,
        (
            version_id,
            seguro_id,
            version_no,
            (motivo or "").strip() or None,
            snapshot_json,
            (created_by or "").strip() or None,
            now,
        ),
    )
    return {"id": version_id, "seguro_id": seguro_id, "version_no": version_no}


def create_seguro_movimiento(conn, seguro_row, now, *, tipo, subtipo="", fecha_movimiento="", fecha_efecto="", fecha_vencimiento="", prima_neta=None, prima_total=None, comision=None, doc_key="", doc_url="", notas="", payload=None, created_by=""):
    if not seguro_row:
        return None
    seguro_id = (seguro_row.get("id") if isinstance(seguro_row, dict) else seguro_row["id"]) or ""
    if not str(seguro_id).strip():
        return None
    movimiento_id = os.urandom(16).hex()
    payload_json = None
    if payload not in (None, "", {}):
        try:
            payload_json = json.dumps(payload, ensure_ascii=False)
        except Exception:
            payload_json = str(payload)
    prima_neta_val = parse_money_value(prima_neta)
    prima_total_val = parse_money_value(prima_total)
    comision_val = parse_money_value(comision)
    comision_pct = None
    try:
        if abs(prima_total_val) > 0.0001 and abs(comision_val) > 0.0001:
            comision_pct = round((float(comision_val) / float(prima_total_val)) * 100.0, 6)
    except Exception:
        comision_pct = None
    conn.execute(
        """
        INSERT INTO seguros_movimientos (
          id, seguro_id, empresa_id, cliente_id, tipo, subtipo,
          fecha_movimiento, fecha_efecto, fecha_vencimiento,
          prima_neta, prima_total, comision, comision_pct,
          doc_key, doc_url, notas, payload_json,
          created_by, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            movimiento_id,
            seguro_id,
            (seguro_row.get("empresa_id") if isinstance(seguro_row, dict) else seguro_row["empresa_id"]),
            (seguro_row.get("cliente_id") if isinstance(seguro_row, dict) else seguro_row["cliente_id"]),
            (tipo or "").strip(),
            (subtipo or "").strip() or None,
            (fecha_movimiento or "").strip() or None,
            (fecha_efecto or "").strip() or None,
            (fecha_vencimiento or "").strip() or None,
            prima_neta_val if abs(prima_neta_val) > 0.0001 else None,
            prima_total_val if abs(prima_total_val) > 0.0001 else None,
            comision_val if abs(comision_val) > 0.0001 else None,
            comision_pct,
            (doc_key or "").strip() or None,
            (doc_url or "").strip() or None,
            (notas or "").strip() or None,
            payload_json,
            (created_by or "").strip() or None,
            now,
            now,
        ),
    )
    return {"id": movimiento_id, "seguro_id": seguro_id}


def normalize_seguro_estado_value(value):
    return runtime_normalize_seguro_estado_value(value)

def seguro_estado_requires_pdf(value: object) -> bool:
    estado = normalize_seguro_estado_value(value or "")
    norm = normalize_lookup_text(estado or "")
    if not norm:
        return False
    if "CONTRAT" in norm:
        return True
    if "VIGOR" in norm:
        return True
    if norm in {"ACTIVA", "VIGENTE"}:
        return True
    return False


def resolve_seguro_pdf_from_movimientos(conn, seguro_id: str) -> tuple[str, str]:
    """
    Devuelve (doc_key, doc_url) desde `seguros_movimientos` si existe algún PDF asociado.
    Útil cuando el PDF se adjuntó como movimiento pero aún no está reflejado en `seguros.poliza_key/url`.
    """
    try:
        row = conn.execute(
            """
            SELECT COALESCE(doc_key, '') AS doc_key, COALESCE(doc_url, '') AS doc_url
            FROM seguros_movimientos
            WHERE seguro_id = ?
              AND (COALESCE(TRIM(doc_key), '') <> '' OR COALESCE(TRIM(doc_url), '') <> '')
            ORDER BY COALESCE(updated_at, created_at) DESC, created_at DESC
            LIMIT 1
            """,
            (seguro_id,),
        ).fetchone()
        if not row:
            return ("", "")
        return (str(row["doc_key"] or "").strip(), str(row["doc_url"] or "").strip())
    except Exception:
        return ("", "")


def can_transition_seguro_estado(current_value, target_value):
    return runtime_can_transition_seguro_estado(current_value, target_value)


def upsert_seguro_comision_contabilidad(conn, seguro_row, now, movimiento="emision", fecha=None, importe=None):
    if not seguro_row:
        return None
    seguro_id = (seguro_row.get("id") if isinstance(seguro_row, dict) else seguro_row["id"]) or ""
    empresa_id = (seguro_row.get("empresa_id") if isinstance(seguro_row, dict) else seguro_row["empresa_id"]) or ""
    if not seguro_id or not empresa_id:
        return None
    cliente_id = (seguro_row.get("cliente_id") if isinstance(seguro_row, dict) else seguro_row["cliente_id"]) or None
    cliente_ids_json = json.dumps([cliente_id], ensure_ascii=False) if cliente_id else None
    poliza_numero = (seguro_row.get("poliza_numero") if isinstance(seguro_row, dict) else seguro_row["poliza_numero"]) or ""
    comision_src = importe
    if comision_src in (None, ""):
        comision_src = seguro_row.get("comision") if isinstance(seguro_row, dict) else seguro_row["comision"]
    comision = round(parse_money_value(comision_src), 2)
    if abs(comision) < 0.005:
        return None
    fecha_base = fecha
    if not fecha_base:
        fecha_base = seguro_row.get("fecha_efecto") if isinstance(seguro_row, dict) else seguro_row["fecha_efecto"]
    fecha_iso = ""
    parsed_fecha = parse_iso_date(fecha_base)
    if parsed_fecha:
        fecha_iso = parsed_fecha.isoformat()
    if not fecha_iso:
        return None
    is_renovacion = normalize_lookup_text(movimiento) in ("RENOVACION", "RENOVAR", "RENEW")
    if not is_renovacion:
        bucket = seguro_estado_bucket_value(seguro_row)
        if bucket != "en_vigor":
            return None
    gestion = "Comisión renovación" if is_renovacion else "Comisión emisión"
    concepto = "Comisión renovación póliza" if is_renovacion else "Comisión emisión póliza"
    if poliza_numero:
        concepto = f"{concepto} {poliza_numero}"
    existing = conn.execute(
        """
        SELECT id
        FROM gestoria_contabilidad
        WHERE seguro_id = ?
          AND fecha = ?
          AND LOWER(COALESCE(gestion, '')) = LOWER(?)
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (seguro_id, fecha_iso, gestion),
    ).fetchone()
    notas = f"Auto CRM Seguros · {gestion.lower()}."
    if existing:
        conn.execute(
            """
            UPDATE gestoria_contabilidad
            SET empresa_id = ?, cliente_id = ?, cliente_ids_json = ?, poliza_numero = ?, concepto = ?, tipo = ?, importe = ?, notas = ?,
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                empresa_id,
                cliente_id,
                cliente_ids_json,
                poliza_numero,
                concepto,
                "Ingreso",
                comision,
                notas,
                now,
                existing["id"],
            ),
        )
        return existing["id"]
    record_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_contabilidad (
          id, empresa_id, cliente_id, cliente_ids_json, seguro_id, poliza_numero, fecha, concepto, gestion, tipo, importe, notas,
          created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            record_id,
            empresa_id,
            cliente_id,
            cliente_ids_json,
            seguro_id,
            poliza_numero,
            fecha_iso,
            concepto,
            gestion,
            "Ingreso",
            comision,
            notas,
            now,
            now,
        ),
    )
    return record_id


def resolve_seguro_contabilidad_link(conn, seguro_id):
    seguro_id = str(seguro_id or "").strip()
    if not seguro_id:
        return "", None
    row = conn.execute(
        "SELECT poliza_numero, cliente_id FROM seguros WHERE id = ? LIMIT 1",
        (seguro_id,),
    ).fetchone()
    if not row:
        return "", None
    poliza_numero = (row["poliza_numero"] or "").strip()
    cliente_id = (row["cliente_id"] or "").strip() or None
    return poliza_numero, cliente_id


def parse_cliente_ids_payload(raw_value):
    if raw_value in (None, ""):
        return []
    items = raw_value
    if isinstance(raw_value, str):
        text = raw_value.strip()
        if not text:
            return []
        if text.startswith("["):
            try:
                parsed = json.loads(text)
                if isinstance(parsed, list):
                    items = parsed
                else:
                    items = [parsed]
            except Exception:
                items = [part.strip() for part in text.split(",")]
        else:
            items = [part.strip() for part in text.split(",")]
    elif not isinstance(raw_value, (list, tuple, set)):
        items = [raw_value]
    out = []
    for item in items:
        value = str(item or "").strip()
        if value and value not in out:
            out.append(value)
    return out


def seguros_contabilidad_where_clause(alias="gc"):
    p = alias.strip() or "gc"
    return (
        f"(({p}.seguro_id IS NOT NULL AND TRIM({p}.seguro_id) <> '') "
        f"OR ({p}.poliza_numero IS NOT NULL AND TRIM({p}.poliza_numero) <> '') "
        f"OR UPPER(COALESCE({p}.notas, '')) LIKE 'AUTO CRM SEGUROS%' "
        f"OR UPPER(COALESCE({p}.notas, '')) LIKE '[SEGUROS]%' "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) IN ('COMISION EMISION', 'COMISION RENOVACION', 'REGULARIZACION', 'REGULARIZACIÓN', 'EXTORNO') "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) LIKE 'COMISI% EMISI%' "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) LIKE 'COMISI% RENOVA%')"
    )


def compute_seguros_contabilidad_totals(conn, empresa_id, year=None):
    where = [ "gc.empresa_id = ?", seguros_contabilidad_where_clause("gc") ]
    values = [empresa_id]
    if year:
        where.append("substr(NULLIF(gc.fecha, ''), 1, 4) = ?")
        values.append(str(year))
    rows = conn.execute(
        f"""
        SELECT gc.tipo, gc.importe, gc.gestion
        FROM gestoria_contabilidad gc
        WHERE {' AND '.join(where)}
        """,
        values,
    ).fetchall()
    ingresos = 0.0
    gastos = 0.0
    for row in rows:
        amount = parse_money_value(row["importe"])
        if normalize_lookup_text(row["tipo"]) == "GASTO":
            gastos += amount
        else:
            ingresos += amount
    return {"ingresos": round(ingresos, 2), "gastos": round(gastos, 2)}


def compute_fincas_seguros_dashboard_payload(conn, empresa_id, year, uploaded_only):
    empresa_id = str(empresa_id or "").strip()
    year = str(year or "").strip()
    is_pg = db_is_postgres_enabled()
    if not year:
        try:
            if is_pg:
                year = str(datetime.now().year)
            else:
                year = conn.execute("SELECT strftime('%Y','now','localtime') AS y").fetchone()["y"]
        except Exception:
            year = str(datetime.now().year)

    uploaded_clause = uploaded_policy_filter("s")
    uploaded_param = resolve_uploaded_only_param(
        conn,
        uploaded_only,
        empresa_id=empresa_id,
        table="seguros",
        uploaded_clause=uploaded_policy_filter(),
        strict=True,
    )

    estado_bucket_expr = seguro_estado_bucket_expr("s")
    in_vigor_expr = in_vigor_policy_filter("s")
    # En este CRM, durante la fase inicial queremos que la base de cálculo del dashboard
    # sea "pólizas subidas" (PDF asociado). Si se pide `uploaded_only=1`, tratamos todas
    # esas pólizas como "en vigor" aunque el campo `estado` histórico viniera como
    # presupuesto/contratada/rechazada, porque aún no se está trabajando ese flujo.
    if uploaded_only:
        estado_bucket_expr = "'en_vigor'"
        in_vigor_expr = "1=1"
    fecha_efecto_date = seguro_date_sql("fecha_efecto", "s")
    if is_pg:
        efecto_as_date = f"CAST({fecha_efecto_date} AS DATE)"
        created_as_date = "CAST(s.created_at AS DATE)"
        year_expr = f"COALESCE(TO_CHAR({efecto_as_date}, 'YYYY'), TO_CHAR({created_as_date}, 'YYYY'))"
        month_expr = f"COALESCE(TO_CHAR({efecto_as_date}, 'YYYY-MM'), TO_CHAR({created_as_date}, 'YYYY-MM'))"
    else:
        year_expr = f"COALESCE(STRFTIME('%Y', {fecha_efecto_date}), STRFTIME('%Y', s.created_at))"
        month_expr = f"COALESCE(STRFTIME('%Y-%m', {fecha_efecto_date}), STRFTIME('%Y-%m', s.created_at))"
    compania_expr = "LOWER(TRIM(COALESCE(s.compania, '')))"
    exclude_sin_seguro = f"({compania_expr} != 'sin seguro')"

    def _money_sql(expr):
        # Normaliza importes almacenados como:
        # - REAL/NUMERIC (ej: 1234.56)
        # - Texto con formato ES (ej: "7.397,96 €")
        # Mantiene el '.' decimal cuando no hay ',' en el valor (caso numérico / "1234.56").
        # Si hay ',', asumimos formato ES y eliminamos puntos de miles.
        # Si no hay ',' pero hay '.' en grupos de miles (ej: "20.000"), eliminamos esos puntos.
        base = f"COALESCE(CAST({expr} AS TEXT), '')"
        stripped = f"REPLACE(REPLACE({base}, '€', ''), ' ', '')"
        eu = f"REPLACE(REPLACE({stripped}, '.', ''), ',', '.')"
        us = f"REPLACE({stripped}, ',', '')"
        dot_count = f"(LENGTH({stripped}) - LENGTH(REPLACE({stripped}, '.', '')))"
        backend = getattr(conn, "__crm_backend__", "") or ""
        if backend == "postgres":
            # Postgres: no soporta `GLOB`. Usamos regex y RIGHT() para detectar sufijo de 3 dígitos (miles).
            looks_like_dot_thousands = (
                f"({stripped} LIKE '%.%' AND {stripped} NOT LIKE '%,%' AND {dot_count} >= 1 "
                f"AND RIGHT({stripped}, 3) ~ '^[0-9]{{3}}$')"
            )
        else:
            looks_like_dot_thousands = (
                f"({stripped} LIKE '%.%' AND {stripped} NOT LIKE '%,%' AND {dot_count} >= 1 "
                f"AND SUBSTR({stripped}, -3) GLOB '[0-9][0-9][0-9]')"
            )
        dot_thousands = f"REPLACE({stripped}, '.', '')"
        normalized = (
            f"CASE "
            f"WHEN {stripped} LIKE '%,%' THEN {eu} "
            f"WHEN {looks_like_dot_thousands} THEN {dot_thousands} "
            f"ELSE {us} END"
        )
        return f"CAST(NULLIF({normalized}, '') AS REAL)"

    def _count_buckets(where_extra_sql, params_extra):
        return conn.execute(
            f"""
            SELECT
              SUM(CASE WHEN {estado_bucket_expr} = 'presupuesto' THEN 1 ELSE 0 END) AS presupuesto,
              SUM(CASE WHEN {estado_bucket_expr} = 'contratada' THEN 1 ELSE 0 END) AS contratada,
              SUM(CASE WHEN {estado_bucket_expr} = 'en_vigor' THEN 1 ELSE 0 END) AS en_vigor,
              SUM(CASE WHEN {estado_bucket_expr} = 'rechazada' THEN 1 ELSE 0 END) AS rechazada
            FROM seguros s
            WHERE s.empresa_id = ?
              AND ({uploaded_clause} OR ? = 0)
              AND {exclude_sin_seguro}
              {where_extra_sql}
            """,
            [empresa_id, uploaded_param, *params_extra],
        ).fetchone()

    current_row = _count_buckets("AND " + year_expr + " = ?", [year])
    totals_row = _count_buckets("", [])

    presupuesto = int(row_value(current_row, "presupuesto", 0) or 0)
    contratada = int(row_value(current_row, "contratada", 0) or 0)
    en_vigor = int(row_value(current_row, "en_vigor", 0) or 0)
    rechazada = int(row_value(current_row, "rechazada", 0) or 0)
    aceptadas = contratada + en_vigor
    total_cerradas = aceptadas + rechazada
    conversion = (aceptadas / total_cerradas * 100.0) if total_cerradas else 0.0

    presupuesto_total = int(row_value(totals_row, "presupuesto", 0) or 0)
    contratada_total = int(row_value(totals_row, "contratada", 0) or 0)
    en_vigor_total = int(row_value(totals_row, "en_vigor", 0) or 0)
    rechazada_total = int(row_value(totals_row, "rechazada", 0) or 0)
    aceptadas_total = contratada_total + en_vigor_total
    total_cerradas_total = aceptadas_total + rechazada_total
    conversion_total = (aceptadas_total / total_cerradas_total * 100.0) if total_cerradas_total else 0.0

    series_rows = conn.execute(
        f"""
        SELECT
          {year_expr} AS year,
          SUM(CASE WHEN {estado_bucket_expr} = 'presupuesto' THEN 1 ELSE 0 END) AS presupuesto,
          SUM(CASE WHEN {estado_bucket_expr} = 'contratada' THEN 1 ELSE 0 END) AS contratada,
          SUM(CASE WHEN {estado_bucket_expr} = 'en_vigor' THEN 1 ELSE 0 END) AS en_vigor,
          SUM(CASE WHEN {estado_bucket_expr} = 'rechazada' THEN 1 ELSE 0 END) AS rechazada
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {year_expr} IS NOT NULL
        GROUP BY {year_expr}
        ORDER BY {year_expr}
        """,
        (empresa_id, uploaded_param),
    ).fetchall()
    series_payload = []
    for row in series_rows:
        row_dict = dict(row)
        accepted_row = int(row_dict.get("contratada") or 0) + int(row_dict.get("en_vigor") or 0)
        closed_row = accepted_row + int(row_dict.get("rechazada") or 0)
        row_dict["conversion"] = (accepted_row / closed_row * 100.0) if closed_row else 0.0
        series_payload.append(row_dict)

    month_rows = conn.execute(
        f"""
        SELECT
          {month_expr} AS month,
          SUM(CASE WHEN {estado_bucket_expr} = 'en_vigor' THEN 1 ELSE 0 END) AS altas
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {year_expr} = ?
          AND {month_expr} IS NOT NULL
        GROUP BY {month_expr}
        ORDER BY {month_expr}
        """,
        (empresa_id, uploaded_param, year),
    ).fetchall()
    series_en_vigor_mes = []
    acumulado = 0
    for row in month_rows:
        altas = int(row_value(row, "altas", 0) or 0)
        acumulado += altas
        series_en_vigor_mes.append(
            {
                "month": row_value(row, "month", "") or "",
                "altas": altas,
                "acumulado": acumulado,
            }
        )

    # Series adicionales para medir "entrada" de pólizas:
    # - Por mes de efecto (fecha_efecto)
    # - Por mes de creación (created_at)
    if is_pg:
        effect_month_expr = f"TO_CHAR(CAST({fecha_efecto_date} AS DATE), 'YYYY-MM')"
        created_month_expr = "TO_CHAR(CAST(s.created_at AS DATE), 'YYYY-MM')"
    else:
        effect_month_expr = f"STRFTIME('%Y-%m', {fecha_efecto_date})"
        created_month_expr = "STRFTIME('%Y-%m', s.created_at)"
    effect_month_rows = conn.execute(
        f"""
        SELECT
          {effect_month_expr} AS month,
          COUNT(*) AS total
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {year_expr} = ?
          AND {effect_month_expr} IS NOT NULL
        GROUP BY {effect_month_expr}
        ORDER BY {effect_month_expr}
        """,
        (empresa_id, uploaded_param, year),
    ).fetchall()
    created_month_rows = conn.execute(
        f"""
        SELECT
          {created_month_expr} AS month,
          COUNT(*) AS total
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND SUBSTR({created_month_expr}, 1, 4) = ?
          AND {created_month_expr} IS NOT NULL
        GROUP BY {created_month_expr}
        ORDER BY {created_month_expr}
        """,
        (empresa_id, uploaded_param, year),
    ).fetchall()
    series_polizas_mes_efecto = [{"month": row_value(r, "month", "") or "", "total": int(row_value(r, "total", 0) or 0)} for r in effect_month_rows]
    series_polizas_mes_creacion = [{"month": row_value(r, "month", "") or "", "total": int(row_value(r, "total", 0) or 0)} for r in created_month_rows]

    # KPIs "cartera" (en vigor) deben basarse en pólizas activas, no en el año de efecto.
    responsables = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.colaborador), ''), 'Sin asignar') AS label,
          COUNT(*) AS total
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {in_vigor_expr}
        GROUP BY 1
        ORDER BY total DESC
        """,
        (empresa_id, uploaded_param),
    ).fetchall()

    # Comisionado debe basarse en Contabilidad (ingresos), no en el campo `seguros.comision`.
    # Se enlaza con la póliza para agrupar por compañía/ramo cuando es posible.
    comision_companias = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.compania), ''), 'Sin compañía') AS label,
          SUM(COALESCE({_money_sql('gc.importe')}, 0)) AS total
        FROM gestoria_contabilidad gc
        LEFT JOIN seguros s
          ON s.empresa_id = gc.empresa_id
         AND (
           (gc.seguro_id IS NOT NULL AND TRIM(gc.seguro_id) <> '' AND s.id = gc.seguro_id)
           OR (gc.poliza_numero IS NOT NULL AND TRIM(gc.poliza_numero) <> '' AND TRIM(s.poliza_numero) = TRIM(gc.poliza_numero))
         )
        WHERE gc.empresa_id = ?
          AND {seguros_contabilidad_where_clause('gc')}
          AND substr(NULLIF(gc.fecha, ''), 1, 4) = ?
          AND LOWER(TRIM(COALESCE(gc.tipo, ''))) <> 'gasto'
          AND ({uploaded_clause} OR ? = 0)
          AND ({exclude_sin_seguro} OR s.id IS NULL)
        GROUP BY 1
        ORDER BY total DESC
        """,
        (empresa_id, year, uploaded_param),
    ).fetchall()

    comision_ramos = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo') AS label,
          SUM(COALESCE({_money_sql('gc.importe')}, 0)) AS total
        FROM gestoria_contabilidad gc
        LEFT JOIN seguros s
          ON s.empresa_id = gc.empresa_id
         AND (
           (gc.seguro_id IS NOT NULL AND TRIM(gc.seguro_id) <> '' AND s.id = gc.seguro_id)
           OR (gc.poliza_numero IS NOT NULL AND TRIM(gc.poliza_numero) <> '' AND TRIM(s.poliza_numero) = TRIM(gc.poliza_numero))
         )
        WHERE gc.empresa_id = ?
          AND {seguros_contabilidad_where_clause('gc')}
          AND substr(NULLIF(gc.fecha, ''), 1, 4) = ?
          AND LOWER(TRIM(COALESCE(gc.tipo, ''))) <> 'gasto'
          AND ({uploaded_clause} OR ? = 0)
          AND ({exclude_sin_seguro} OR s.id IS NULL)
        GROUP BY 1
        ORDER BY total DESC
        """,
        (empresa_id, year, uploaded_param),
    ).fetchall()

    prima_companias = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.compania), ''), 'Sin compañía') AS label,
          SUM(COALESCE({_money_sql('s.prima_total')}, 0)) AS total
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {in_vigor_expr}
        GROUP BY 1
        ORDER BY total DESC
        """,
        (empresa_id, uploaded_param),
    ).fetchall()

    prima_ramos = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo') AS label,
          SUM(COALESCE({_money_sql('s.prima_total')}, 0)) AS total
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {in_vigor_expr}
        GROUP BY 1
        ORDER BY total DESC
        """,
        (empresa_id, uploaded_param),
    ).fetchall()

    fecha_venc_date = seguro_date_sql("fecha_vencimiento", "s")
    if is_pg:
        fecha_venc_eff = f"COALESCE(CAST({fecha_venc_date} AS DATE), (CAST({fecha_efecto_date} AS DATE) + INTERVAL '1 year')::date)"
        month_venc_expr = f"TO_CHAR(CAST({fecha_venc_eff} AS DATE), 'YYYY-MM')"
    else:
        fecha_venc_eff = f"COALESCE({fecha_venc_date}, DATE({fecha_efecto_date}, '+1 year'))"
        month_venc_expr = f"STRFTIME('%Y-%m', {fecha_venc_eff})"
    renov_series = conn.execute(
        f"""
        SELECT
          {month_venc_expr} AS month,
          SUM(CASE WHEN {estado_bucket_expr} = 'en_vigor' THEN 1 ELSE 0 END) AS renovaciones,
          SUM(CASE WHEN {estado_bucket_expr} = 'anulada' THEN 1 ELSE 0 END) AS anulaciones
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {month_venc_expr} IS NOT NULL
          AND SUBSTR({month_venc_expr}, 1, 4) = ?
        GROUP BY {month_venc_expr}
        ORDER BY {month_venc_expr}
        """,
        (empresa_id, uploaded_param, year),
    ).fetchall()

    oportunidades_abiertas = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo') AS label,
          COUNT(*) AS total
        FROM seguros s
        WHERE s.empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
          AND {exclude_sin_seguro}
          AND {year_expr} = ?
          AND {estado_bucket_expr} = 'presupuesto'
        GROUP BY 1
        ORDER BY total DESC
        """,
        (empresa_id, uploaded_param, year),
    ).fetchall()

    cont = compute_seguros_contabilidad_totals(conn, empresa_id, year=year)
    ingresos = float(cont.get("ingresos") or 0.0)
    gastos = float(cont.get("gastos") or 0.0)
    rentabilidad = ingresos - gastos
    margen_rentabilidad = (rentabilidad / ingresos * 100.0) if ingresos else 0.0

    current = {
        "year": year,
        "presupuesto": presupuesto,
        "contratada": contratada,
        "en_vigor": en_vigor,
        "rechazada": rechazada,
        "aceptadas": aceptadas,
        "conversion": conversion,
        "presupuesto_total": presupuesto_total,
        "contratada_total": contratada_total,
        "en_vigor_total": en_vigor_total,
        "rechazada_total": rechazada_total,
        "aceptadas_total": aceptadas_total,
        "conversion_total": conversion_total,
        "rentabilidad": round(rentabilidad, 2),
        "margen_rentabilidad": round(margen_rentabilidad, 2),
    }

    return {
        "current": current,
        "series": series_payload,
        "series_en_vigor_mes": series_en_vigor_mes,
        "series_polizas_mes_efecto": series_polizas_mes_efecto,
        "series_polizas_mes_creacion": series_polizas_mes_creacion,
        "responsables": [dict(r) for r in responsables],
        "comision_companias": [dict(r) for r in comision_companias],
        "comision_ramos": [dict(r) for r in comision_ramos],
        "prima_companias": [dict(r) for r in prima_companias],
        "prima_ramos": [dict(r) for r in prima_ramos],
        "renovaciones_anulaciones_mes": [dict(r) for r in renov_series],
        "oportunidades_abiertas": [dict(r) for r in oportunidades_abiertas],
    }


def compute_fincas_seguros_dashboard_payload_multi(conn, empresa_ids, year, uploaded_only):
    ids = [str(eid or "").strip() for eid in list(empresa_ids or []) if str(eid or "").strip()]
    if not ids:
        return compute_fincas_seguros_dashboard_payload(conn, "", year, uploaded_only)

    payloads = [compute_fincas_seguros_dashboard_payload(conn, eid, year, uploaded_only) for eid in ids]

    def merge_by_label(rows):
        merged = {}
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            label = str(row.get("label") or "").strip() or "Sin asignar"
            try:
                merged[label] = float(merged.get(label) or 0) + float(row.get("total") or 0)
            except Exception:
                continue
        out = [{"label": k, "total": v} for k, v in merged.items()]
        out.sort(key=lambda x: (-float(x.get("total") or 0), str(x.get("label") or "").lower()))
        return out

    def merge_by_key(rows, key_field, numeric_fields):
        merged = {}
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            key = str(row.get(key_field) or "").strip()
            if not key:
                continue
            bucket = merged.setdefault(key, {key_field: key})
            for field in numeric_fields:
                try:
                    bucket[field] = float(bucket.get(field) or 0) + float(row.get(field) or 0)
                except Exception:
                    bucket[field] = float(bucket.get(field) or 0)
        out = list(merged.values())
        out.sort(key=lambda x: str(x.get(key_field) or ""))
        return out

    current = {"year": str(year or "").strip()}
    for p in payloads:
        row = p.get("current") or {}
        for key in (
            "presupuesto",
            "contratada",
            "en_vigor",
            "rechazada",
            "presupuesto_total",
            "contratada_total",
            "en_vigor_total",
            "rechazada_total",
        ):
            current[key] = int(current.get(key) or 0) + int(row.get(key) or 0)
    current["aceptadas"] = int(current.get("contratada") or 0) + int(current.get("en_vigor") or 0)
    current["aceptadas_total"] = int(current.get("contratada_total") or 0) + int(current.get("en_vigor_total") or 0)
    closed_year = current["aceptadas"] + int(current.get("rechazada") or 0)
    closed_total = current["aceptadas_total"] + int(current.get("rechazada_total") or 0)
    current["conversion"] = (current["aceptadas"] / closed_year * 100.0) if closed_year else 0.0
    current["conversion_total"] = (current["aceptadas_total"] / closed_total * 100.0) if closed_total else 0.0

    ingresos = 0.0
    gastos = 0.0
    for eid in ids:
        cont = compute_seguros_contabilidad_totals(conn, eid, year=str(year or "").strip() or None)
        ingresos += float(cont.get("ingresos") or 0.0)
        gastos += float(cont.get("gastos") or 0.0)
    rentabilidad = round(ingresos - gastos, 2)
    current["rentabilidad"] = rentabilidad
    current["margen_rentabilidad"] = round((rentabilidad / ingresos * 100.0) if ingresos else 0.0, 2)

    series_rows = []
    month_rows = []
    responsables_rows = []
    comision_comp_rows = []
    comision_ramo_rows = []
    prima_comp_rows = []
    prima_ramo_rows = []
    renov_rows = []
    opp_rows = []
    for p in payloads:
        series_rows.extend([dict(item) for item in (p.get("series") or []) if isinstance(item, dict)])
        month_rows.extend([dict(item) for item in (p.get("series_en_vigor_mes") or []) if isinstance(item, dict)])
        responsables_rows.extend([dict(item) for item in (p.get("responsables") or []) if isinstance(item, dict)])
        comision_comp_rows.extend([dict(item) for item in (p.get("comision_companias") or []) if isinstance(item, dict)])
        comision_ramo_rows.extend([dict(item) for item in (p.get("comision_ramos") or []) if isinstance(item, dict)])
        prima_comp_rows.extend([dict(item) for item in (p.get("prima_companias") or []) if isinstance(item, dict)])
        prima_ramo_rows.extend([dict(item) for item in (p.get("prima_ramos") or []) if isinstance(item, dict)])
        renov_rows.extend([dict(item) for item in (p.get("renovaciones_anulaciones_mes") or []) if isinstance(item, dict)])
        opp_rows.extend([dict(item) for item in (p.get("oportunidades_abiertas") or []) if isinstance(item, dict)])

    series = merge_by_key(series_rows, "year", ["presupuesto", "contratada", "en_vigor", "rechazada"])
    for item in series:
        accepted = int(item.get("contratada") or 0) + int(item.get("en_vigor") or 0)
        closed = accepted + int(item.get("rechazada") or 0)
        item["conversion"] = (accepted / closed * 100.0) if closed else 0.0
        for k in ("presupuesto", "contratada", "en_vigor", "rechazada"):
            item[k] = int(item.get(k) or 0)

    months = merge_by_key(month_rows, "month", ["altas"])
    acumulado = 0
    for item in months:
        altas = int(item.get("altas") or 0)
        acumulado += altas
        item["altas"] = altas
        item["acumulado"] = acumulado

    renov = merge_by_key(renov_rows, "month", ["renovadas", "anuladas"])
    oportunidades = merge_by_label(opp_rows)[:12]

    return {
        "current": current,
        "series": series,
        "series_en_vigor_mes": months,
        "responsables": merge_by_label(responsables_rows),
        "comision_companias": merge_by_label(comision_comp_rows),
        "comision_ramos": merge_by_label(comision_ramo_rows),
        "prima_companias": merge_by_label(prima_comp_rows),
        "prima_ramos": merge_by_label(prima_ramo_rows),
        "renovaciones_anulaciones_mes": renov,
        "oportunidades_abiertas": oportunidades,
    }


def compute_seguros_data_quality(conn, empresa_id, *, uploaded_only=False, limit=3000):
    """
    Calidad del dato (Seguros): reglas y alertas para asegurar KPIs fiables.
    """
    empresa_id = str(empresa_id or "").strip()
    try:
        limit_val = int(str(limit or "").strip() or "3000")
    except Exception:
        limit_val = 3000
    limit_val = max(1, min(15000, limit_val))

    uploaded_clause = uploaded_policy_filter()
    uploaded_param = resolve_uploaded_only_param(
        conn,
        bool(uploaded_only),
        empresa_id=empresa_id,
        table="seguros",
        uploaded_clause=uploaded_clause,
        strict=False,
    )

    # Determina columnas disponibles para evitar romper en DBs antiguas.
    available_cols = set()
    try:
        if db_is_postgres_enabled():
            col_rows = conn.execute(
                """
                SELECT column_name
                FROM information_schema.columns
                WHERE table_schema = 'public' AND table_name = 'seguros'
                """
            ).fetchall()
            for r in col_rows or []:
                name = str(row_value(r, "column_name") or row_value(r, 0) or "").strip()
                if name:
                    available_cols.add(name)
        else:
            col_rows = conn.execute("PRAGMA table_info(seguros)").fetchall()
            for r in col_rows or []:
                # PRAGMA: (cid, name, type, notnull, dflt_value, pk)
                name = str(row_value(r, "name") or row_value(r, 1) or "").strip()
                if name:
                    available_cols.add(name)
    except Exception:
        available_cols = set()

    base_select_cols = [
        "id",
        "empresa_id",
        "cliente_id",
        "tomador",
        "compania",
        "ramo",
        "poliza_numero",
        "fecha_efecto",
        "fecha_vencimiento",
        "estado",
        "estado_poliza",
        "created_at",
        "updated_at",
    ]
    optional_select_cols = [
        "matricula",
        "direccion_riesgo",
        "referencia_catastral",
    ]
    if available_cols:
        select_cols = [c for c in base_select_cols if c in available_cols] + [c for c in optional_select_cols if c in available_cols]
    else:
        # Fallback best-effort (para backends sin introspección).
        select_cols = base_select_cols + optional_select_cols

    rows = conn.execute(
        f"""
        SELECT
          {', '.join(select_cols)}
        FROM seguros
        WHERE empresa_id = ?
          AND ({uploaded_clause} OR ? = 0)
        ORDER BY COALESCE(updated_at, created_at) DESC
        LIMIT {limit_val}
        """,
        (empresa_id, uploaded_param),
    ).fetchall()
    rows_dict = [dict(r) for r in rows]

    today = datetime.now().date()
    issues = []
    counts = {}

    def add_issue(rule_key, label, severity, row, *, details=None, missing_fields=None):
        counts[rule_key] = int(counts.get(rule_key) or 0) + 1
        payload = {
            "rule_key": rule_key,
            "label": label,
            "severity": severity,
            "seguro_id": row.get("id") or "",
            "cliente_id": row.get("cliente_id") or "",
            "tomador": row.get("tomador") or "",
            "compania": row.get("compania") or "",
            "ramo": row.get("ramo") or "",
            "poliza_numero": row.get("poliza_numero") or "",
            "fecha_efecto": row.get("fecha_efecto") or "",
            "fecha_vencimiento": row.get("fecha_vencimiento") or "",
            "estado_bucket": seguro_estado_bucket_value(row, today=today),
        }
        if details:
            payload["details"] = details
        if missing_fields:
            payload["missing_fields"] = missing_fields
        issues.append(payload)

    default_ramo_required = {
        "Auto": [("matricula", "Matrícula")],
        "Hogar": [("direccion_riesgo", "Dirección del riesgo")],
        "Hogar alquiler": [("direccion_riesgo", "Dirección del riesgo")],
        "Comunidad": [("direccion_riesgo", "Dirección del riesgo")],
        "Comercio": [("direccion_riesgo", "Dirección del riesgo")],
    }

    # Reglas configurables desde BD (si existe la tabla).
    # Estructura: (compania_key, ramo_label) -> [(field_key, field_label), ...]
    configured_required = {}
    try:
        cfg_rows = conn.execute(
            """
            SELECT compania_key, ramo_key, field_key, field_label
            FROM seguros_quality_rules
            WHERE empresa_id = ? AND COALESCE(enabled, 1) = 1
            """,
            (empresa_id,),
        ).fetchall()
        for cfg in cfg_rows or []:
            company_key = normalize_lookup_text(row_value(cfg, "compania_key") or row_value(cfg, 0) or "")
            raw_ramo = str(row_value(cfg, "ramo_key") or row_value(cfg, 1) or "").strip()
            ramo_label = canonicalize_ramo(raw_ramo) or raw_ramo
            field_key = str(row_value(cfg, "field_key") or row_value(cfg, 2) or "").strip()
            if not ramo_label or not field_key:
                continue
            field_label = str(row_value(cfg, "field_label") or row_value(cfg, 3) or "").strip() or field_key
            configured_required.setdefault((company_key, ramo_label), []).append((field_key, field_label))
    except Exception:
        configured_required = {}

    def resolve_required_fields(company_key, ramo_label):
        if not ramo_label:
            return []
        ck = normalize_lookup_text(company_key or "")
        # 1) Regla específica compañía+ramo
        fields = configured_required.get((ck, ramo_label))
        if fields:
            return fields
        # 2) Regla genérica por ramo (compañía vacía)
        fields = configured_required.get(("", ramo_label))
        if fields:
            return fields
        # 3) Fallback defaults en código
        fields = default_ramo_required.get(ramo_label) or []
        if available_cols:
            fields = [(f, lbl) for (f, lbl) in fields if f in available_cols]
        return fields

    duplicates = {}
    for row in rows_dict:
        bucket = seguro_estado_bucket_value(row, today=today)
        in_vigor = bucket == "en_vigor"
        poliza_raw = str(row.get("poliza_numero") or "").strip()
        poliza_key = normalize_poliza_key(poliza_raw)
        compania_key = normalize_lookup_text(row.get("compania") or "")
        ramo_label = canonicalize_ramo(row.get("ramo")) or (row.get("ramo") or "").strip()

        if in_vigor and not poliza_key:
            add_issue("en_vigor_sin_numero", "En vigor sin nº de póliza", "warning", row)

        efecto = parse_iso_date(row.get("fecha_efecto"))
        venc = parse_iso_date(row.get("fecha_vencimiento"))
        if efecto and venc and venc < efecto:
            add_issue(
                "vencimiento_antes_efecto",
                "Vencimiento anterior a la fecha de efecto",
                "error",
                row,
                details=f"Efecto {efecto.isoformat()} > Vencimiento {venc.isoformat()}",
            )
        if in_vigor and venc and venc < today:
            add_issue(
                "en_vigor_vencida",
                "En vigor con vencimiento pasado",
                "error",
                row,
                details=f"Vencida el {venc.isoformat()} (hoy {today.isoformat()})",
            )

        if poliza_key:
            dup_key = f"{compania_key}::{poliza_key}" if compania_key else poliza_key
            duplicates.setdefault(dup_key, []).append(
                {
                    "seguro_id": row.get("id") or "",
                    "cliente_id": row.get("cliente_id") or "",
                    "tomador": row.get("tomador") or "",
                    "compania": row.get("compania") or "",
                    "ramo": row.get("ramo") or "",
                    "poliza_numero": poliza_raw,
                    "estado_bucket": bucket,
                }
            )

        required = resolve_required_fields(compania_key, ramo_label)
        if available_cols:
            required = [(f, lbl) for (f, lbl) in required if f in available_cols]
        missing = []
        for field, label in required:
            if not str(row.get(field) or "").strip():
                missing.append(label)
        if missing:
            add_issue(
                "faltan_campos_ramo",
                f"Faltan campos mínimos ({ramo_label})",
                "warning",
                row,
                missing_fields=missing,
            )

    duplicate_groups = []
    for key, items in duplicates.items():
        if len(items) <= 1:
            continue
        counts["duplicados_poliza_numero"] = int(counts.get("duplicados_poliza_numero") or 0) + 1
        company_part = key.split("::", 1)[0] if "::" in key else ""
        poliza_part = key.split("::", 1)[1] if "::" in key else key
        duplicate_groups.append(
            {
                "rule_key": "duplicados_poliza_numero",
                "label": "Duplicado por nº de póliza",
                "severity": "warning",
                "compania_key": company_part,
                "poliza_key": poliza_part,
                "total": len(items),
                "items": items[:50],
            }
        )
    duplicate_groups.sort(key=lambda g: (-int(g.get("total") or 0), str(g.get("compania_key") or "")))

    rules_catalog = [
        {"key": "en_vigor_sin_numero", "label": "En vigor sin nº de póliza", "severity": "warning"},
        {"key": "en_vigor_vencida", "label": "En vigor con vencimiento pasado", "severity": "error"},
        {"key": "vencimiento_antes_efecto", "label": "Vencimiento anterior a efecto", "severity": "error"},
        {"key": "duplicados_poliza_numero", "label": "Duplicados por nº de póliza", "severity": "warning"},
        {"key": "faltan_campos_ramo", "label": "Campos mínimos por ramo", "severity": "warning"},
    ]
    rules = []
    for rule in rules_catalog:
        rules.append({**rule, "count": int(counts.get(rule["key"]) or 0)})

    issues.sort(
        key=lambda it: (
            0 if str(it.get("severity") or "").lower() == "error" else 1,
            str(it.get("label") or ""),
        )
    )

    return {
        "empresa_id": empresa_id,
        "limit": limit_val,
        "uploaded_only": 1 if uploaded_param else 0,
        "summary": {k: int(v or 0) for k, v in counts.items()},
        "rules": rules,
        "issues": issues[:800],
        "duplicate_groups": duplicate_groups[:200],
    }


def normalize_auto_seguro_commission_assignments(conn, now=None):
    now = now or datetime.now(timezone.utc).isoformat()
    try:
        rows = conn.execute(
            """
            SELECT gc.id, gc.cliente_id, gc.cliente_ids_json, gc.notas, gc.seguro_id, s.cliente_id AS seguro_cliente_id
            FROM gestoria_contabilidad gc
            LEFT JOIN seguros s ON s.id = gc.seguro_id
            WHERE gc.seguro_id IS NOT NULL AND TRIM(gc.seguro_id) <> ''
              AND UPPER(COALESCE(gc.notas, '')) LIKE 'AUTO CRM SEGUROS%'
            """
        ).fetchall()
    except Exception:
        return 0
    updated = 0
    for row in rows:
        seguro_cliente_id = str(row["seguro_cliente_id"] or "").strip()
        if not seguro_cliente_id:
            continue
        assigned = parse_cliente_ids_payload(row["cliente_ids_json"])
        if not assigned and row["cliente_id"]:
            assigned = [str(row["cliente_id"]).strip()]
        if len(assigned) == 1 and assigned[0] == seguro_cliente_id:
            continue
        conn.execute(
            """
            UPDATE gestoria_contabilidad
            SET cliente_id = ?, cliente_ids_json = ?, updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                seguro_cliente_id,
                json.dumps([seguro_cliente_id], ensure_ascii=False),
                now,
                row["id"],
            ),
        )
        updated += 1
    return updated


def find_existing_seguro_id(conn, empresa_id, poliza_numero, compania, exclude_id=None):
    poliza_norm = normalize_poliza_key(poliza_numero)
    if not poliza_norm:
        return ""
    compania_norm = normalize_company_key(compania)
    rows = conn.execute(
        "SELECT id, poliza_numero, compania, estado FROM seguros WHERE empresa_id = ?",
        (empresa_id,),
    ).fetchall()
    for row in rows:
        row_id = row["id"]
        if exclude_id and row_id == exclude_id:
            continue
        estado_key = normalize_lookup_text(row["estado"] or "")
        if "MIGRADO LEGADO" in estado_key or "LEGACY" in estado_key:
            continue
        row_poliza = normalize_poliza_key(row["poliza_numero"])
        if not row_poliza or row_poliza != poliza_norm:
            continue
        row_comp = normalize_company_key(row["compania"])
        if compania_norm and row_comp and compania_norm != row_comp:
            continue
        return row_id
    return ""


def find_reusable_hipoteca_open_record(
    conn,
    empresa_id,
    *,
    cliente=None,
    cliente_id=None,
    fecha_encargo=None,
    precio=None,
    importe_hipoteca=None,
    banco=None,
    oficina=None,
    exclude_id=None,
):
    cols = table_columns(conn, "hipotecas") or set()
    if not empresa_id or "empresa_id" not in cols:
        return None
    where = ["empresa_id = ?"]
    values = [empresa_id]
    if "estado" in cols:
        where.append("LOWER(TRIM(COALESCE(estado, ''))) IN (?, ?, ?)")
        values.extend(["estudio", "encargo", "pendiente"])
    fecha_encargo_text = str(fecha_encargo or "").strip()
    if fecha_encargo_text and "fecha_encargo" in cols:
        where.append("NULLIF(TRIM(COALESCE(fecha_encargo, '')), '') = NULLIF(TRIM(?), '')")
        values.append(fecha_encargo_text)
    precio_val = parse_optional_float(precio)
    if precio_val is not None and "precio" in cols:
        where.append("precio = ?")
        values.append(precio_val)
    importe_val = parse_optional_float(importe_hipoteca)
    if importe_val is not None and "importe_hipoteca" in cols:
        where.append("importe_hipoteca = ?")
        values.append(importe_val)
    rows = conn.execute(
        f"""
        SELECT *
        FROM hipotecas
        WHERE {" AND ".join(where)}
        ORDER BY COALESCE(NULLIF(updated_at, ''), NULLIF(created_at, '')) DESC
        """,
        values,
    ).fetchall()
    cliente_id_norm = str(cliente_id or "").strip()
    cliente_norm = normalize_lookup_text(cliente)
    banco_norm = normalize_lookup_text(banco)
    oficina_norm = normalize_lookup_text(oficina)
    for row in rows or []:
        row_id = str(row_value(row, "id") or "").strip()
        if exclude_id and row_id == str(exclude_id or "").strip():
            continue
        row_cliente_id = str(row_value(row, "cliente_id") or "").strip() if "cliente_id" in cols else ""
        row_cliente_norm = normalize_lookup_text(row_value(row, "cliente") or "") if "cliente" in cols else ""
        if cliente_id_norm:
            if row_cliente_id:
                if row_cliente_id != cliente_id_norm:
                    continue
            elif cliente_norm:
                if row_cliente_norm != cliente_norm:
                    continue
            else:
                continue
        elif cliente_norm:
            if row_cliente_norm != cliente_norm:
                continue
        else:
            continue
        if banco_norm and "banco" in cols:
            row_banco_norm = normalize_lookup_text(row_value(row, "banco") or "")
            if row_banco_norm and row_banco_norm != banco_norm:
                continue
        if oficina_norm:
            row_oficina_raw = ""
            if "oficina" in cols:
                row_oficina_raw = str(row_value(row, "oficina") or "").strip()
            if not row_oficina_raw and "inmobiliaria_compra" in cols:
                row_oficina_raw = str(row_value(row, "inmobiliaria_compra") or "").strip()
            row_oficina_norm = normalize_lookup_text(row_oficina_raw)
            if row_oficina_norm and row_oficina_norm != oficina_norm:
                continue
        return row
    return None


def normalize_lookup_text(value):
    if not value:
        return ""
    text = str(value)
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    text = text.upper()
    text = re.sub(r"[^A-Z0-9]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def normalize_simple(value):
    if not value:
        return ""
    text = str(value)
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    return text.lower().strip()


def service_sql_match_clause(alias, services):
    """Build a tolerant SQL service filter for free-text `clientes_empresas.servicio` labels."""
    normalized = [normalize_service_key(s) for s in (services or []) if str(s or "").strip()]
    normalized = [s for s in normalized if s]
    clauses = []
    values = []
    for service in normalized:
        if service == "gestoria":
            clauses.append(
                f"(LOWER(COALESCE({alias}.servicio, '')) IN (?, ?) "
                f"OR LOWER(COALESCE({alias}.servicio, '')) LIKE ?)"
            )
            values.extend(["gestoria", "gestoría", "%gestor%"])
        elif service == "fincas":
            clauses.append(
                f"(LOWER(COALESCE({alias}.servicio, '')) LIKE ? "
                f"OR LOWER(COALESCE({alias}.servicio, '')) LIKE ?)"
            )
            values.extend(["%finca%", "%administraci%n%"])
        elif service == "financiaciones":
            clauses.append(
                f"(LOWER(COALESCE({alias}.servicio, '')) IN (?, ?) "
                f"OR LOWER(COALESCE({alias}.servicio, '')) LIKE ?)"
            )
            values.extend(["financiaciones", "hipotecas", "%financi%"])
        else:
            clauses.append(f"LOWER(COALESCE({alias}.servicio, '')) = ?")
            values.append(service)
    if not clauses:
        return "", []
    return "(" + " OR ".join(clauses) + ")", values


def gestoria_service_sql_condition(alias):
    return (
        f"(LOWER(COALESCE({alias}.servicio, '')) IN "
        "('gestoria', 'gestoría', 'administracion fincas', 'administración fincas') "
        f"OR LOWER(COALESCE({alias}.servicio, '')) LIKE '%gestor%' "
        f"OR LOWER(COALESCE({alias}.servicio, '')) LIKE '%finca%')"
    )


def normalizeSimple(value):
    """Compat: older codepaths used normalizeSimple."""
    return normalize_lookup_text(value)


def normalize_action_key(value):
    if not value:
        return ""
    text = str(value).strip()
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    text = text.lower()
    text = re.sub(r"[^a-z0-9]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    return text


def looks_like_invoice_document(nombre="", clasificacion="", tipo=""):
    haystack = " ".join([str(nombre or ""), str(clasificacion or ""), str(tipo or "")]).strip()
    norm = normalize_lookup_text(haystack)
    if not norm:
        return False
    keywords = (
        "FACTURA",
        "TICKET",
        "RECIBO",
        "GASTO",
        "ALBARAN",
        "ALBARÁN",
    )
    return any(k in norm for k in keywords)


def audit_event(conn, empresa_id, entidad, entidad_id, accion, usuario=None, detalles=None, now=None):
    if not conn or not entidad or not accion:
        return None
    detail_value = detalles
    if isinstance(detalles, (dict, list)):
        try:
            detail_value = json.dumps(detalles, ensure_ascii=False)
        except Exception:
            detail_value = str(detalles)
    try:
        conn.execute(
            """
            INSERT INTO auditoria (
              id, empresa_id, entidad, entidad_id, accion, usuario, detalles, created_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                entidad,
                entidad_id,
                accion,
                usuario or "Sistema",
                detail_value,
                now or "now",
            ),
        )
    except Exception:
        # La auditoría no debe romper el flujo (tests unitarios usan schemas parciales).
        return None
    return True


