def get_legal_topic_operations(area, topic_key):
    area_key = normalize_legal_area(area)
    topic = str(topic_key or "").strip()
    payload = LEGAL_TOPIC_OPERATIONS.get(area_key, {}).get(topic, {})
    if not isinstance(payload, dict):
        payload = {}
    return {
        "documents": [item for item in list(payload.get("documents") or []) if str(item or "").strip()],
        "workflows": [item for item in list(payload.get("workflows") or []) if str(item or "").strip()],
        "clauses": [item for item in list(payload.get("clauses") or []) if str(item or "").strip()],
        "impact_score": float(payload.get("impact_score") or 0),
    }


def normalize_workspace_slug(value):
    text = normalize_lookup_text(value or "").lower().replace(" ", "-")
    text = re.sub(r"[^a-z0-9\-]+", "", text)
    text = re.sub(r"\-+", "-", text).strip("-")
    return text or "workspace"


def normalize_service_key(value):
    raw = str(value or "")
    text = normalize_lookup_text(raw)
    if not text:
        return ""
    aliases = {
        "GESTORIA": "gestoria",
        "SEGUROS": "seguros",
        "INMOBILIARIA": "inmobiliaria",
        "FINANCIACIONES": "financiaciones",
        "HIPOTECAS": "financiaciones",
        "ADMINISTRACION FINCAS": "fincas",
        "ADMINISTRACION DE FINCAS": "fincas",
        "ADMIN DE FINCAS": "fincas",
        "FINCAS": "fincas",
    }
    if text in aliases:
        return aliases[text]
    # Compat: en algunos sitios guardamos el "servicio" como etiqueta larga (p.ej. nombre comercial)
    # en vez de clave ("Fincas Velazquez", "Financiaciones Modernia", "Administración Fincas - X", ...).
    # Para no romper permisos ni scoping, inferimos por palabras clave.
    try:
        if "FINCAS" in text or "COMUNIDAD" in text:
            return "fincas"
        if "GESTOR" in text:
            return "gestoria"
        if "SEGURO" in text:
            return "seguros"
        if "INMOB" in text or "COMPRAVENTA" in text or "ALQUILER" in text:
            return "inmobiliaria"
        if "FINANC" in text or "HIPOTEC" in text or "LCCI" in text:
            return "financiaciones"
    except Exception:
        pass
    return text.lower().strip()


def normalize_procedencia_canal_key(value):
    return normalize_lookup_text(value or "")


def procedencia_is_internal_colaborador(canal):
    key = normalize_procedencia_canal_key(canal)
    return key in {"COLABORADOR INTERNO", "INTERNO", "USUARIO"}


def procedencia_is_cliente_referido(canal):
    key = normalize_procedencia_canal_key(canal)
    return key in {"CLIENTE REFERIDO", "CLIENTE RELACIONADO", "REFERIDO"}


def validate_procedencia_fields(conn, canal="", user_id="", cliente_id="", actor_user_id="", self_cliente_id=""):
    """
    Valida y normaliza procedencia/canal.

    - Si canal == 'Colaborador interno' => requiere user_id (o actor_user_id).
    - Si canal == 'Cliente referido' => requiere cliente_id (distinto de self_cliente_id y existente).
    - Si no hay canal pero sí user_id/cliente_id => infiere canal.
    - Para cualquier otro canal => limpia user_id/cliente_id para evitar incoherencias.
    """
    canal = str(canal or "").strip()
    user_id = str(user_id or "").strip()
    cliente_id = str(cliente_id or "").strip()
    actor_user_id = str(actor_user_id or "").strip()
    self_cliente_id = str(self_cliente_id or "").strip()

    if not canal:
        if user_id:
            canal = "Colaborador interno"
        elif cliente_id:
            canal = "Cliente referido"

    if procedencia_is_internal_colaborador(canal):
        if not user_id:
            user_id = actor_user_id
        if not user_id:
            raise ValueError("Selecciona el colaborador interno.")
        try:
            exists = conn.execute("SELECT 1 FROM usuarios WHERE id = ? LIMIT 1", (user_id,)).fetchone()
            if not exists:
                raise ValueError("Colaborador interno no válido.")
        except sqlite3.OperationalError:
            # Dataset legacy sin tabla usuarios: no bloqueamos.
            pass
        return canal, user_id, ""

    if procedencia_is_cliente_referido(canal):
        if not cliente_id:
            raise ValueError("Selecciona el cliente referido.")
        if self_cliente_id and cliente_id == self_cliente_id:
            raise ValueError("El cliente referido no puede ser el propio cliente.")
        try:
            exists = conn.execute("SELECT 1 FROM clientes WHERE id = ? LIMIT 1", (cliente_id,)).fetchone()
            if not exists:
                raise ValueError("Cliente referido no válido.")
        except sqlite3.OperationalError:
            pass
        return canal, "", cliente_id

    return canal, "", ""


def ensure_workspace_core_tables(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspaces (
          id TEXT PRIMARY KEY,
          nombre TEXT NOT NULL UNIQUE,
          slug TEXT NOT NULL UNIQUE,
          estado TEXT NOT NULL DEFAULT 'Activo',
          plan TEXT NOT NULL DEFAULT 'Enterprise',
          kind TEXT NOT NULL DEFAULT 'Directo',
          descripcion TEXT,
          logo_url TEXT,
          primary_color TEXT,
          accent_color TEXT,
          kiosk_pin_hash TEXT,
          kiosk_pin_required INTEGER NOT NULL DEFAULT 0,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_empresas (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          empresa_id TEXT NOT NULL,
          rol TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, empresa_id)
        )
        """
    )
    # Nuevo modelo: "empresa" dentro del workspace (tenant) como entidad operativa.
    # Mantiene `legacy_empresa_id` para compatibilidad mientras migramos endpoints antiguos.
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_companies (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          legacy_empresa_id TEXT,
          nombre TEXT NOT NULL,
          nif TEXT,
          direccion TEXT,
          logo_url TEXT,
          primary_color TEXT,
          accent_color TEXT,
          activo INTEGER NOT NULL DEFAULT 1,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, legacy_empresa_id)
        )
        """
    )
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_workspace_companies_ws ON workspace_companies (workspace_id, activo, nombre)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_workspace_companies_legacy ON workspace_companies (legacy_empresa_id)")
    except Exception:
        pass
    ensure_column(conn, "workspace_companies", "legacy_empresa_id", "legacy_empresa_id TEXT")
    ensure_column(conn, "workspace_companies", "nif", "nif TEXT")
    ensure_column(conn, "workspace_companies", "direccion", "direccion TEXT")
    ensure_column(conn, "workspace_companies", "logo_url", "logo_url TEXT")
    ensure_column(conn, "workspace_companies", "primary_color", "primary_color TEXT")
    ensure_column(conn, "workspace_companies", "accent_color", "accent_color TEXT")
    ensure_column(conn, "workspace_companies", "activo", "activo INTEGER NOT NULL DEFAULT 1")
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_modulos (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          modulo_key TEXT NOT NULL,
          modulo_nombre TEXT NOT NULL,
          categoria TEXT,
          enabled INTEGER NOT NULL DEFAULT 1,
          sort_order INTEGER NOT NULL DEFAULT 0,
          config_json TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, modulo_key)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_miembros (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          usuario_id TEXT NOT NULL,
          rol TEXT NOT NULL DEFAULT 'Miembro',
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, usuario_id)
        )
        """
    )
    ensure_column(conn, "workspaces", "descripcion", "descripcion TEXT")
    ensure_column(conn, "workspaces", "logo_url", "logo_url TEXT")
    ensure_column(conn, "workspaces", "primary_color", "primary_color TEXT")
    ensure_column(conn, "workspaces", "accent_color", "accent_color TEXT")
    ensure_column(conn, "workspaces", "kind", "kind TEXT NOT NULL DEFAULT 'Directo'")
    ensure_column(conn, "workspaces", "kiosk_pin_hash", "kiosk_pin_hash TEXT")
    ensure_column(conn, "workspaces", "kiosk_pin_required", "kiosk_pin_required INTEGER NOT NULL DEFAULT 0")
    ensure_column(conn, "workspace_modulos", "config_json", "config_json TEXT")
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_links (
          id TEXT PRIMARY KEY,
          source_workspace_id TEXT NOT NULL,
          target_workspace_id TEXT NOT NULL,
          link_type TEXT NOT NULL,
          role TEXT,
          enabled INTEGER NOT NULL DEFAULT 1,
          notes TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (source_workspace_id, target_workspace_id, link_type)
        )
        """
    )
    ensure_column(conn, "workspace_links", "role", "role TEXT")
    ensure_column(conn, "workspace_links", "enabled", "enabled INTEGER NOT NULL DEFAULT 1")
    ensure_column(conn, "workspace_links", "notes", "notes TEXT")
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_workspace_links_source ON workspace_links (source_workspace_id, enabled, link_type)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_workspace_links_target ON workspace_links (target_workspace_id, enabled, link_type)")
    except Exception:
        pass

    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_servicio_empresas (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          servicio_key TEXT NOT NULL,
          empresa_id TEXT NOT NULL,
          enabled INTEGER NOT NULL DEFAULT 1,
          is_default INTEGER NOT NULL DEFAULT 0,
          sort_order INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, servicio_key, empresa_id)
        )
        """
    )
    try:
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_workspace_servicio_empresas_ws_service_enabled ON workspace_servicio_empresas (workspace_id, servicio_key, enabled)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_workspace_servicio_empresas_ws_service_default ON workspace_servicio_empresas (workspace_id, servicio_key, is_default)"
        )
    except Exception:
        pass

def ensure_workspace_membership_backfill(conn):
    """
    Best-effort para despliegues legacy:
    - Si hay fichas de personal con usuario_id, damos acceso a esos usuarios al workspace.
    - Si no hay ningún miembro y solo existe 1 workspace, damos acceso a todos los usuarios activos.
    Diseñado para no romper instalaciones existentes cuando se activa APP_WORKSPACE_MEMBERSHIP_ENFORCE.
    """
    try:
        now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
        ws_rows = conn.execute("SELECT id FROM workspaces").fetchall()
        workspaces = [str(row_value(row, "id") or row_value(row, 0) or "").strip() for row in (ws_rows or [])]
        workspaces = [ws for ws in workspaces if ws]
        if not workspaces:
            return
        # 1) Backfill desde RRHH/personas (lo más preciso).
        try:
            pairs = conn.execute(
                """
                SELECT DISTINCT workspace_id, usuario_id
                FROM workspace_registro_personal
                WHERE COALESCE(usuario_id, '') != ''
                """
            ).fetchall()
        except Exception:
            pairs = []
        for row in pairs or []:
            ws_id = str(row_value(row, "workspace_id") or row_value(row, 0) or "").strip()
            uid = str(row_value(row, "usuario_id") or row_value(row, 1) or "").strip()
            if not ws_id or not uid:
                continue
            ensure_workspace_member(conn, ws_id, uid, role="Miembro", now=now)
        # 2) Si sigue vacío y solo hay 1 workspace, mantenemos comportamiento legacy.
        try:
            # Considera "vacío" si no hay ningún miembro válido (usuario existente y activo).
            any_member = conn.execute(
                """
                SELECT 1
                FROM workspace_miembros mem
                JOIN usuarios u ON u.id = mem.usuario_id
                WHERE COALESCE(u.activo, 1) = 1
                LIMIT 1
                """
            ).fetchone()
        except Exception:
            any_member = None
        if not any_member and len(workspaces) == 1:
            try:
                users = conn.execute("SELECT id, rol, servicio FROM usuarios WHERE COALESCE(activo, 1) = 1").fetchall()
            except Exception:
                users = []
            ws_id = workspaces[0]
            for u in users or []:
                uid = str(row_value(u, "id") or row_value(u, 0) or "").strip()
                if not uid:
                    continue
                # Promueve admins a Owner para facilitar arranque.
                role = "Owner" if workspace_session_is_privileged({"rol": row_value(u, "rol") or "", "servicio": row_value(u, "servicio") or ""}) else "Miembro"
                ensure_workspace_member(conn, ws_id, uid, role=role, now=now)
    except Exception:
        return


def bootstrap_default_workspace(conn):
    now = datetime.now(timezone.utc).isoformat()
    default_slug = normalize_workspace_slug(DEFAULT_WORKSPACE_NAME)
    default_logo_url = "/assets/verifika2/verifika2_wordmark_check_green_transparent.png"
    default_primary = "#0B1D33"
    default_accent = "#F2C14E"
    workspace = conn.execute(
        "SELECT id FROM workspaces WHERE nombre = ? OR slug = ? LIMIT 1",
        (DEFAULT_WORKSPACE_NAME, default_slug),
    ).fetchone()
    if workspace:
        workspace_id = str(row_value(workspace, "id") or row_value(workspace, 0) or "").strip()
        conn.execute(
            """
            UPDATE workspaces
            SET descripcion = COALESCE(NULLIF(descripcion, ''), ?),
                logo_url = COALESCE(NULLIF(logo_url, ''), ?),
                primary_color = COALESCE(NULLIF(primary_color, ''), ?),
                accent_color = COALESCE(NULLIF(accent_color, ''), ?),
                estado = COALESCE(NULLIF(estado, ''), 'Activo'),
                plan = COALESCE(NULLIF(plan, ''), 'Enterprise'),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                f"Tenant inicial del producto {PLATFORM_NAME} y primer caso operativo del grupo.",
                default_logo_url,
                default_primary,
                default_accent,
                now,
                workspace_id,
            ),
        )
    else:
        # Migración suave: si existe un workspace legacy (p. ej. "modernia") lo renombramos en lugar de crear uno nuevo.
        legacy = conn.execute(
            """
            SELECT id, nombre, slug
            FROM workspaces
            WHERE slug IN ('modernia', 'grupomodernia', 'grupo-modernia')
               OR LOWER(nombre) IN ('modernia', 'grupo modernia', 'grupomodernia', 'grupo-modernia')
            ORDER BY created_at ASC
            LIMIT 1
            """
        ).fetchone()
        if legacy:
            workspace_id = str(row_value(legacy, "id") or row_value(legacy, 0) or "").strip()
            conn.execute(
                """
                UPDATE workspaces
                SET nombre = ?,
                    slug = ?,
                    descripcion = COALESCE(NULLIF(descripcion, ''), ?),
                    logo_url = COALESCE(NULLIF(logo_url, ''), ?),
                    primary_color = COALESCE(NULLIF(primary_color, ''), ?),
                    accent_color = COALESCE(NULLIF(accent_color, ''), ?),
                    estado = COALESCE(NULLIF(estado, ''), 'Activo'),
                    plan = COALESCE(NULLIF(plan, ''), 'Enterprise'),
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    DEFAULT_WORKSPACE_NAME,
                    default_slug,
                    f"Tenant inicial del producto {PLATFORM_NAME} y primer caso operativo del grupo.",
                    default_logo_url,
                    default_primary,
                    default_accent,
                    now,
                    workspace_id,
                ),
            )
        else:
            workspace_id = os.urandom(16).hex()
            conn.execute(
                """
                INSERT INTO workspaces (
                  id, nombre, slug, estado, plan, descripcion, logo_url, primary_color, accent_color, created_at, updated_at
                ) VALUES (?, ?, ?, 'Activo', 'Enterprise', ?, ?, ?, ?, datetime(?), datetime(?))
                """,
                (
                    workspace_id,
                    DEFAULT_WORKSPACE_NAME,
                    default_slug,
                    f"Tenant inicial del producto {PLATFORM_NAME} y primer caso operativo del grupo.",
                    default_logo_url,
                    default_primary,
                    default_accent,
                    now,
                    now,
                ),
            )

    empresas = conn.execute("SELECT id FROM empresas ORDER BY nombre").fetchall()
    for row in empresas:
        empresa_id = str(row_value(row, "id") or row_value(row, 0) or "").strip()
        conn.execute(
            """
            INSERT OR IGNORE INTO workspace_empresas (
              id, workspace_id, empresa_id, rol, created_at, updated_at
            ) VALUES (?, ?, ?, 'operativa', datetime(?), datetime(?))
            """,
            (os.urandom(16).hex(), workspace_id, empresa_id, now, now),
        )
    for module in WORKSPACE_MODULE_CATALOG:
        conn.execute(
            """
            INSERT OR IGNORE INTO workspace_modulos (
              id, workspace_id, modulo_key, modulo_nombre, categoria, enabled, sort_order, config_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, 1, ?, '{}', datetime(?), datetime(?))
            """,
            (
                os.urandom(16).hex(),
                workspace_id,
                module["key"],
                module["nombre"],
                module["categoria"],
                module["sort_order"],
                now,
                now,
            ),
        )

def ensure_workspace_catalog_modules(conn):
    # Garantiza que workspaces existentes reciban nuevos módulos del catálogo.
    now = datetime.now(timezone.utc).isoformat()
    workspace_rows = conn.execute("SELECT id FROM workspaces").fetchall()
    for ws in workspace_rows:
        ws_id = str(row_value(ws, "id") or row_value(ws, 0) or "").strip()
        if not ws_id:
            continue
        for module in WORKSPACE_MODULE_CATALOG:
            conn.execute(
                """
                INSERT OR IGNORE INTO workspace_modulos (
                  id, workspace_id, modulo_key, modulo_nombre, categoria, enabled, sort_order, config_json, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, 1, ?, '{}', datetime(?), datetime(?))
                """,
                (
                    os.urandom(16).hex(),
                    ws_id,
                    module["key"],
                    module["nombre"],
                    module["categoria"],
                    module["sort_order"],
                    now,
                    now,
                ),
            )


def is_gestoria_dashboard_active_state(value):
    state = normalize_lookup_text(value or "")
    return state in {"ALTA", "ACTIVO", "ACTIVA"}


GESTORIA_TRABAJO_CATEGORY_KEYS = {
    "laboral",
    "fiscal",
    "contable",
    "registro",
    "sociedades",
    "rentas",
    "trafico",
    "herencias",
    "expedientes",
    "tasaciones",
    "otros",
}


def normalize_gestoria_trabajo_category(value):
    key = str(value or "").strip().lower()
    return key if key in GESTORIA_TRABAJO_CATEGORY_KEYS else ""


def classify_gestoria_trabajo_category(tipo_trabajo):
    text = normalize_lookup_text(tipo_trabajo or "")
    if not text:
        return "otros"
    if "HERENC" in text:
        return "herencias"
    if "TRAFIC" in text or "TRANSFER" in text or "MATRICUL" in text:
        return "trafico"
    if "TASACI" in text:
        return "tasaciones"
    if "RENTA" in text or "MODELO 100" in text or "DECLARACION" in text:
        return "rentas"
    if (
        "EXPEDIENT" in text
        or "ADMINISTRAT" in text
        or "IMV" in text
        or "BECA" in text
        or "BRECHA" in text
        or "CONDOMINIO" in text
    ):
        return "expedientes"
    if "LABOR" in text:
        return "laboral"
    if "FISCAL" in text or "HACIENDA" in text or "AEAT" in text or ("MODELO" in text and "MODELO 100" not in text):
        return "fiscal"
    if "CONTAB" in text:
        return "contable"
    if "REGISTRO" in text or "MERCANTIL" in text:
        return "registro"
    if "CONSTITUCION" in text or "SOCIEDAD" in text:
        return "sociedades"
    return "otros"


