def normalize_gestoria_trabajo_tipo_key(value):
    raw = str(value or "").strip().lower()
    raw = re.sub(r"[^a-z0-9]+", "_", raw).strip("_")
    return raw[:80]


def ensure_gestoria_trabajo_tipos(conn, empresa_id, now=None):
    empresa_id = str(empresa_id or "").strip()
    if not empresa_id:
        return
    now_val = now or "now"
    try:
        row = conn.execute(
            "SELECT COUNT(1) AS total FROM gestoria_trabajo_tipos WHERE empresa_id = ?",
            (empresa_id,),
        ).fetchone()
        if int(row_value(row, "total", 0) or 0) > 0:
            return
    except Exception:
        return
    for item in DEFAULT_GESTORIA_TRABAJO_TIPOS:
        try:
            conn.execute(
                """
                INSERT INTO gestoria_trabajo_tipos (
                  id, empresa_id, tipo_key, nombre, categoria, activo, orden, color, sla_dias, iva_pct, precio_base,
                  plantilla_json, created_at, updated_at
                ) VALUES (
                  ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?, NULL, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    empresa_id,
                    item.get("tipo_key"),
                    item.get("nombre"),
                    normalize_gestoria_trabajo_category(item.get("categoria")) or "otros",
                    item.get("orden"),
                    item.get("color"),
                    item.get("sla_dias"),
                    float(item.get("iva_pct") or 21.0),
                    float(item.get("precio_base") or 0.0),
                    now_val,
                    now_val,
                ),
            )
        except Exception:
            continue


def fetch_gestoria_trabajo_tipos(conn, empresa_id, include_inactive=False):
    empresa_id = str(empresa_id or "").strip()
    if not empresa_id:
        return []
    where = ["empresa_id = ?"]
    values = [empresa_id]
    if not include_inactive:
        where.append("COALESCE(activo, 1) = 1")
    rows = conn.execute(
        f"""
        SELECT id, empresa_id, tipo_key, nombre, categoria, activo, orden, color, sla_dias, iva_pct, precio_base, plantilla_json,
               created_at, updated_at
        FROM gestoria_trabajo_tipos
        WHERE {" AND ".join(where)}
        ORDER BY COALESCE(orden, 0) ASC, LOWER(COALESCE(nombre, '')) ASC
        """,
        values,
    ).fetchall()
    return [dict(r) for r in rows]


def is_active_service_state(value, fecha_fin=None):
    state = normalize_lookup_text(value or "")
    if state and state in {"INACTIVO", "BAJA", "CANCELADO", "ANULADO", "FINALIZADO"}:
        return False
    end_date = parse_iso_date(fecha_fin)
    if end_date and end_date < datetime.now(timezone.utc).date():
        return False
    return True


def parse_iso_date(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    head = raw.split("T", 1)[0].split(" ", 1)[0]
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d/%m/%Y", "%d-%m-%Y", "%d/%m/%y", "%d-%m-%y"):
        try:
            return datetime.strptime(head, fmt).date()
        except Exception:
            continue
    return None


def parse_datetime_value(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        pass
    parsed_date = parse_iso_date(raw)
    if parsed_date:
        return datetime.combine(parsed_date, datetime.min.time(), tzinfo=timezone.utc)
    return None


def parse_date_to_timestamp(value):
    if isinstance(value, (int, float)):
        try:
            return float(value)
        except Exception:
            return None
    dt = parse_datetime_value(value)
    if not dt:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    try:
        return float(dt.timestamp())
    except Exception:
        return None


def _parse_iso_dt_utc(value):
    """
    Parseo best-effort de timestamps ISO y normaliza a UTC.
    Devuelve datetime con tzinfo o None.
    """
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        dt = None
    if dt is None:
        parsed_date = parse_iso_date(raw)
        if not parsed_date:
            return None
        return datetime.combine(parsed_date, datetime.min.time(), tzinfo=timezone.utc)
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    try:
        return dt.astimezone(timezone.utc)
    except Exception:
        return dt


def add_year_to_date(value):
    base = parse_iso_date(value)
    if not base:
        return ""
    try:
        return base.replace(year=base.year + 1).isoformat()
    except ValueError:
        # 29/02 -> 28/02 en años no bisiestos
        return base.replace(month=2, day=28, year=base.year + 1).isoformat()


def parse_money_value(value):
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip()
    if not text:
        return 0.0
    text = re.sub(r"[^0-9,\.\-]+", "", text)
    if not text or text in ("-", ".", ","):
        return 0.0
    has_comma = "," in text
    has_dot = "." in text
    if has_comma and has_dot:
        # es-ES: dots thousands, comma decimals (ej: 20.000,50)
        text = text.replace(".", "").replace(",", ".")
    elif has_comma:
        # Coma como decimal (ej: 20000,50)
        text = text.replace(",", ".")
    elif has_dot:
        # Si los puntos parecen miles (ej: 20.000), los eliminamos.
        parts = text.split(".")
        if len(parts) > 1:
            last = parts[-1]
            groups_ok = all(len(p) == 3 for p in parts[1:])
            if groups_ok and len(last) == 3:
                text = "".join(parts)
        # Si no, mantenemos el punto como decimal (ej: 20000.50)
    if not text or text in ("-", "."):
        return 0.0
    try:
        return float(text)
    except ValueError:
        return 0.0


def _money_decimal2(value):
    if value in (None, ""):
        return Decimal("0.00")
    try:
        return Decimal(str(parse_money_value(value))).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except Exception:
        return Decimal("0.00")


def parse_optional_float(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip()
    if not text:
        return None
    text = re.sub(r"[^0-9,\.\-]+", "", text)
    if not text or text in ("-", ".", ","):
        return None
    has_comma = "," in text
    has_dot = "." in text
    if has_comma and has_dot:
        text = text.replace(".", "").replace(",", ".")
    elif has_comma:
        text = text.replace(",", ".")
    elif has_dot:
        parts = text.split(".")
        if len(parts) > 1:
            last = parts[-1]
            groups_ok = all(len(p) == 3 for p in parts[1:])
            if groups_ok and len(last) == 3:
                text = "".join(parts)
    if not text or text in ("-", "."):
        return None
    try:
        return float(text)
    except ValueError:
        return None


def parse_optional_int(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return 1 if value else 0
    if isinstance(value, int):
        return int(value)
    if isinstance(value, float):
        return int(value)
    text = str(value).strip()
    if not text:
        return None
    text = re.sub(r"[^0-9\-]+", "", text)
    if not text or text == "-":
        return None
    try:
        return int(text)
    except ValueError:
        return None


def infer_habitaciones_from_subtipologia(value):
    text = str(value or "").strip()
    if not text:
        return None
    upper = re.sub(r"\s+", " ", text.upper()).strip()
    # Ejemplos: "3 dormitorios", "2 hab.", "4 HABITACIONES + despacho".
    m = re.search(
        r"\b(\d{1,2})\s*(?:DORMITORIOS?|DORM\.?|HABITACIONES?|HAB\.?)\b",
        upper,
    )
    if not m:
        return None
    try:
        val = int(m.group(1))
    except Exception:
        return None
    return val if val > 0 else None


def parse_boolish(value):
    raw = str(value or "").strip().lower()
    if not raw:
        return 0
    return 1 if raw in {"1", "true", "yes", "si", "sí", "on"} else 0


