def resolve_hipoteca_accounting_date(row):
    estado = normalize_lookup_text((row.get("estado") if isinstance(row, dict) else row["estado"]) or "")
    fecha_firma_raw = (row.get("fecha_firma") if isinstance(row, dict) else row["fecha_firma"]) or ""
    fecha_firma = parse_iso_date(fecha_firma_raw)
    if fecha_firma:
        return fecha_firma
    if estado not in {"INDEMNIZACION", "INDEMNIZACIÓN"}:
        return None
    fecha_encargo_raw = (row.get("fecha_encargo") if isinstance(row, dict) else row["fecha_encargo"]) or ""
    fecha_encargo = parse_iso_date(fecha_encargo_raw)
    if fecha_encargo:
        return fecha_encargo
    created_raw = (row.get("created_at") if isinstance(row, dict) else row["created_at"]) or ""
    created_dt = parse_datetime_value(created_raw)
    if created_dt:
        return created_dt.date()
    updated_raw = (row.get("updated_at") if isinstance(row, dict) else row["updated_at"]) or ""
    updated_dt = parse_datetime_value(updated_raw)
    if updated_dt:
        return updated_dt.date()
    return None


def iterate_month_starts(start_date, end_date):
    current = start_date.replace(day=1)
    end = end_date.replace(day=1)
    while current <= end:
        yield current
        year = current.year + (1 if current.month == 12 else 0)
        month = 1 if current.month == 12 else current.month + 1
        current = current.replace(year=year, month=month, day=1)


def build_hipoteca_fixed_cost_entries(now=None):
    ref = parse_datetime_value(now) if now else None
    ref_date = (ref.date() if ref else datetime.now(timezone.utc).date()).replace(day=1)
    start_date = parse_iso_date(HIPOTECA_FIXED_COSTS_START)
    if not start_date or start_date > ref_date:
        return []
    entries = []
    for month_start in iterate_month_starts(start_date, ref_date):
        fecha = month_start.isoformat()
        entries.append(
            {
                "fecha": fecha,
                "gestion": "Nómina Juan",
                "tipo": "Gasto",
                "importe": HIPOTECA_JUAN_MONTHLY_COST,
                "concepto": "Coste laboral Juan",
                "notas": f"{HIPOTECA_ACCOUNTING_FIXED_COSTS_PREFIX} · nómina juan.",
            }
        )
        entries.append(
            {
                "fecha": fecha,
                "gestion": "Gestoría",
                "tipo": "Gasto",
                "importe": HIPOTECA_GESTORIA_MONTHLY_COST,
                "concepto": "Gasto gestoría",
                "notas": f"{HIPOTECA_ACCOUNTING_FIXED_COSTS_PREFIX} · gestoría.",
            }
        )
    for fecha, importe in HIPOTECA_ANNUAL_INSURANCE_PAYMENTS:
        fecha_iso = parse_iso_date(fecha)
        if not fecha_iso or fecha_iso > ref_date:
            continue
        entries.append(
            {
                "fecha": fecha_iso.isoformat(),
                "gestion": "Seguro anual",
                "tipo": "Gasto",
                "importe": round(parse_money_value(importe), 2),
                "concepto": "Seguro anual",
                "notas": f"{HIPOTECA_ACCOUNTING_FIXED_COSTS_PREFIX} · seguro anual.",
            }
        )
    return entries


def hipotecas_contabilidad_where_clause(alias="gc"):
    p = alias.strip() or "gc"
    return (
        f"(({p}.hipoteca_id IS NOT NULL AND TRIM({p}.hipoteca_id) <> '') "
        f"OR UPPER(COALESCE({p}.notas, '')) LIKE 'AUTO CRM HIPOTECAS%' "
        f"OR UPPER(COALESCE({p}.notas, '')) LIKE '[HIPOTECAS]%' "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) IN ("
        f"'COMISION CLIENTE', 'COMISIÓN CLIENTE', 'CESION BANCO', 'CESIÓN BANCO', "
        f"'GESTORIA', 'GESTORÍA', 'CESION JUAN', 'CESIÓN JUAN', "
        f"'SEGUROS Y COMISION JUAN', 'SEGUROS Y COMISIÓN JUAN', "
        f"'CESION A INMOBILIARIAS', 'CESIÓN A INMOBILIARIAS', 'NOMINA JUAN', 'NÓMINA JUAN'))"
    )


def compute_hipotecas_contabilidad_totals(conn, empresa_id, year=None):
    where = ["gc.empresa_id = ?", hipotecas_contabilidad_where_clause("gc")]
    values = [empresa_id]
    if year:
        where.append("substr(NULLIF(gc.fecha, ''), 1, 4) = ?")
        values.append(str(year))
    rows = conn.execute(
        f"""
        SELECT gc.tipo, gc.importe, gc.gestion
        FROM gestoria_contabilidad gc
        WHERE {' AND '.join(where)}
        """,
        values,
    ).fetchall()
    ingresos = 0.0
    gastos = 0.0
    comision_cliente = 0.0
    for row in rows:
        amount = parse_money_value(row["importe"])
        if normalize_lookup_text(row["tipo"]) == "GASTO":
            gastos += amount
        else:
            ingresos += amount
            gestion = normalize_lookup_text(row["gestion"])
            if gestion in ("COMISION CLIENTE", "COMISIÓN CLIENTE"):
                comision_cliente += amount
    resultado = round(ingresos - gastos, 2)
    rentabilidad_ratio = round(resultado / gastos, 4) if abs(gastos) >= 0.005 else None
    return {
        "ingresos": round(ingresos, 2),
        "gastos": round(gastos, 2),
        "comision_cliente": round(comision_cliente, 2),
        "resultado": resultado,
        "rentabilidad_ratio": rentabilidad_ratio,
    }


def compute_hipotecas_commission_series(conn, empresa_id):
    rows = conn.execute(
        f"""
        SELECT substr(NULLIF(gc.fecha, ''), 1, 4) AS year, SUM(COALESCE(gc.importe, 0)) AS total
        FROM gestoria_contabilidad gc
        WHERE gc.empresa_id = ?
          AND {hipotecas_contabilidad_where_clause("gc")}
          AND LOWER(TRIM(COALESCE(gc.gestion, ''))) IN ('comision cliente', 'comisión cliente')
          AND LOWER(TRIM(COALESCE(gc.tipo, ''))) <> 'gasto'
          AND substr(NULLIF(gc.fecha, ''), 1, 4) IS NOT NULL
        GROUP BY substr(NULLIF(gc.fecha, ''), 1, 4)
        ORDER BY substr(NULLIF(gc.fecha, ''), 1, 4)
        """,
        (empresa_id,),
    ).fetchall()
    return [dict(row) for row in rows]


def compute_hipotecas_commission_by_bank(conn, empresa_id, year=None):
    where = [
        "gc.empresa_id = ?",
        hipotecas_contabilidad_where_clause("gc"),
        "h.id = gc.hipoteca_id",
        "h.banco IS NOT NULL",
        "TRIM(h.banco) <> ''",
        "LOWER(TRIM(COALESCE(gc.gestion, ''))) IN ('comision cliente', 'comisión cliente')",
        "LOWER(TRIM(COALESCE(gc.tipo, ''))) <> 'gasto'",
    ]
    values = [empresa_id]
    if year:
        where.append("substr(NULLIF(gc.fecha, ''), 1, 4) = ?")
        values.append(str(year))
    rows = conn.execute(
        f"""
        SELECT h.banco AS label, SUM(COALESCE(gc.importe, 0)) AS total
        FROM gestoria_contabilidad gc
        JOIN hipotecas h ON h.id = gc.hipoteca_id
        WHERE {' AND '.join(where)}
        GROUP BY h.banco
        """,
        values,
    ).fetchall()
    return {str(row["label"] or "").strip(): round(parse_money_value(row["total"]), 2) for row in rows}


def build_hipoteca_dashboard_entity_rows(entity_total_rows, entity_year_rows):
    def normalize_bank_label(value: object) -> str:
        raw = str(value or "").strip()
        norm = normalize_lookup_text(raw)
        if not norm:
            return raw
        rules = (
            ("sabadell", "Banco Sabadell"),
            ("santander", "Banco Santander"),
            ("bbva", "BBVA"),
            ("caixabank", "CaixaBank"),
            ("bankinter", "Bankinter"),
            ("unicaja", "Unicaja Banco"),
            ("abanca", "Abanca"),
            ("ibercaja", "Ibercaja Banco"),
            ("kutxabank", "Kutxabank"),
            ("cajamar", "Cajamar Caja Rural"),
            ("openbank", "Openbank"),
            ("ing", "ING"),
            ("myinvestor", "MyInvestor"),
            ("caja rural de granada", "Caja Rural de Granada"),
            ("laboral kutxa", "Laboral Kutxa"),
            ("deutsche bank", "Deutsche Bank España"),
        )
        for needle, canonical in rules:
            if needle and needle in norm:
                return canonical
        return raw

    def merge_bank_rows(rows):
        merged = {}
        aliases = {}
        for r in rows or []:
            if not isinstance(r, dict):
                continue
            raw_label = str(r.get("label") or "").strip()
            canonical = normalize_bank_label(raw_label)
            bucket = merged.get(canonical)
            if not bucket:
                bucket = {"label": canonical, "total": 0}
                merged[canonical] = bucket
            try:
                bucket["total"] += int(r.get("total") or 0)
            except Exception:
                bucket["total"] += 0
            aliases.setdefault(canonical, set()).add(raw_label)
        out = sorted(list(merged.values()), key=lambda x: int(x.get("total") or 0), reverse=True)
        return out, aliases

    entity_total_merged, entity_total_aliases = merge_bank_rows([dict(r) for r in (entity_total_rows or [])])
    entity_year_merged, entity_year_aliases = merge_bank_rows([dict(r) for r in (entity_year_rows or [])])
    entity_total_map = {str(row["label"]): dict(row) for row in entity_total_merged}
    return {
        "series_entidades": entity_total_merged[:8],
        "entity_total_map": entity_total_map,
        "entity_year_rows": entity_year_merged[:12],
        "entity_total_aliases": entity_total_aliases,
        "entity_year_aliases": entity_year_aliases,
    }


def resolve_hipoteca_contabilidad_link(conn, hipoteca_id):
    hipoteca_id = str(hipoteca_id or "").strip()
    if not hipoteca_id:
        return {"cliente": "", "banco": "", "fecha_firma": "", "cliente_id": None}
    try:
        row = conn.execute(
            "SELECT cliente, cliente_id, banco, fecha_firma FROM hipotecas WHERE id = ? LIMIT 1",
            (hipoteca_id,),
        ).fetchone()
    except sqlite3.OperationalError as exc:
        if "no such column: cliente_id" not in str(exc).lower():
            raise
        row = conn.execute(
            "SELECT cliente, banco, fecha_firma FROM hipotecas WHERE id = ? LIMIT 1",
            (hipoteca_id,),
        ).fetchone()
    if not row:
        return {"cliente": "", "banco": "", "fecha_firma": "", "cliente_id": None}
    cliente_nombre = str(row["cliente"] or "").strip()
    cliente_id = str(row["cliente_id"] or "").strip() or None if "cliente_id" in row.keys() else None
    if not cliente_id and cliente_nombre:
        cliente_row = conn.execute(
            "SELECT id FROM clientes WHERE UPPER(COALESCE(nombre, '')) = UPPER(?) ORDER BY created_at DESC LIMIT 1",
            (cliente_nombre,),
        ).fetchone()
        if cliente_row:
            cliente_id = cliente_row["id"]
    return {
        "cliente": cliente_nombre,
        "banco": str(row["banco"] or "").strip(),
        "fecha_firma": str(row["fecha_firma"] or "").strip(),
        "cliente_id": cliente_id,
    }


def canonicalize_hipoteca_bank_name(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    brand = resolve_hipoteca_bank_brand(raw)
    return str(brand.get("name") or raw).strip() or raw


def format_export_money(value):
    amount = parse_money_value(value)
    return f"{amount:,.2f} €".replace(",", "X").replace(".", ",").replace("X", ".")


def format_export_date(value):
    parsed = parse_iso_date(value)
    if not parsed:
        return str(value or "").strip()
    return parsed.strftime("%d/%m/%Y")


def hipoteca_export_filename_part(value):
    raw = normalize_person_name(value or "") or "hipoteca"
    normalized = unicodedata.normalize("NFD", raw)
    normalized = "".join(ch for ch in normalized if unicodedata.category(ch) != "Mn")
    normalized = re.sub(r"[^A-Za-z0-9]+", "_", normalized).strip("_").lower()
    return normalized or "hipoteca"


