def _hipoteca_cliente_export_label(field_name):
    raw = str(field_name or "").strip()
    if not raw:
        return "Cliente"
    label = HIPOTECA_CLIENT_EXPORT_LABELS.get(raw)
    if label:
        return f"Cliente · {label}"
    return f"Cliente · {raw.replace('_', ' ').strip().title()}"


def _clean_hipoteca_export_value(value):
    if isinstance(value, str):
        return value.strip()
    if value is None:
        return ""
    return value


def _build_hipoteca_cliente_fields(conn, cliente_id):
    cliente_id = str(cliente_id or "").strip()
    if not cliente_id:
        return {}
    cliente_row = conn.execute(
        "SELECT * FROM clientes WHERE id = ? LIMIT 1",
        (cliente_id,),
    ).fetchone()
    if not cliente_row:
        return {}
    cliente_fields = {}
    for key in cliente_row.keys():
        cliente_fields[key] = _clean_hipoteca_export_value(cliente_row[key])
    return cliente_fields


def build_hipoteca_export_row(conn, row):
    cliente_id = str(row["cliente_id"] or "").strip()
    cliente = str(row["cliente"] or "").strip()
    cliente_nif = ""
    cliente_direccion = ""
    cliente_telefono = ""
    cliente_email = ""
    cliente_fields = {}
    if cliente_id:
        cliente_fields = _build_hipoteca_cliente_fields(conn, cliente_id)
        cliente_row = cliente_fields if cliente_fields else None
        if cliente_row:
            cliente = str(cliente_row.get("nombre") or "").strip() or cliente
            cliente_nif = str(cliente_row.get("nif") or "").strip()
            cliente_direccion = str(cliente_row.get("direccion") or "").strip()
            cliente_telefono = str(cliente_row.get("telefono") or "").strip()
            cliente_email = str(cliente_row.get("email") or "").strip()
    return {
        "id": str(row["id"] or "").strip(),
        "cliente": cliente,
        "cliente_id": cliente_id,
        "cliente_nif": cliente_nif,
        "cliente_direccion": cliente_direccion,
        "cliente_telefono": cliente_telefono,
        "cliente_email": cliente_email,
        "cliente_fields": cliente_fields,
        "fecha_encargo": str(row["fecha_encargo"] or "").strip(),
        "fecha_firma": str(row["fecha_firma"] or "").strip(),
        "tipo_hipoteca": str(row["tipo_hipoteca"] or "").strip(),
        "importe_hipoteca": parse_money_value(row["importe_hipoteca"]),
        "precio": parse_money_value(row["precio"]),
        "porcentaje": parse_money_value(row["porcentaje"]),
        "entrada": parse_money_value(row["entrada"]),
        "banco": canonicalize_hipoteca_bank_name(row["banco"]),
        "honorarios": parse_money_value(row["comision"]),
        "cesion": parse_money_value(row["cesion"]),
        "comision_juan": parse_money_value(row["comision_juan"]),
        "comision_modernia": parse_money_value(row["comision_modernia"]),
        "inmobiliaria": str(row["inmobiliaria_compra"] or row["oficina"] or "").strip(),
        "estado": str(row["estado"] or "").strip(),
        "oficina": str(row["oficina"] or "").strip(),
        "asesor": str(row["asesor"] or "").strip(),
        "encargo": str(row["encargo"] or "").strip(),
        "anio": str(row["anio"] or "").strip(),
    }


def normalize_hipoteca_estado(value):
    return re.sub(r"\s+", " ", str(value or "").strip().lower())


HIPOTECA_BDT_STATE_ORDER = (
    "Pendiente",
    "Estudio",
    "Encargo",
    "Firmada",
    "Rechazada",
    "Cancelada",
    "Indemnización",
)


def extract_hipoteca_bdt_year(row):
    raw_year = str(row_value(row, "anio", "") or row_value(row, "año", "") or row_value(row, "year", "") or "").strip()
    if re.fullmatch(r"\d{4}", raw_year):
        return raw_year
    for key in ("fecha_firma", "fecha_encargo", "fecha", "created_at", "updated_at"):
        raw = str(row_value(row, key, "") or "").strip()
        if not raw:
            continue
        parsed = parse_iso_date(raw)
        if parsed:
            return str(parsed.year)
        match = re.search(r"\b(19\d{2}|20\d{2})\b", raw)
        if match:
            return match.group(1)
    return ""


def collect_hipoteca_bdt_filter_options(rows):
    years = []
    states = []
    seen_years = set()
    seen_states = set()
    for row in rows or []:
        year = extract_hipoteca_bdt_year(row)
        if year and year not in seen_years:
            seen_years.add(year)
            years.append(year)
        estado = str(row_value(row, "estado", "") or "").strip()
        estado_key = normalize_hipoteca_estado(estado)
        if estado and estado_key and estado_key not in seen_states:
            seen_states.add(estado_key)
            states.append(estado)
    years.sort(key=lambda value: int(value), reverse=True)
    state_rank = {normalize_hipoteca_estado(value): idx for idx, value in enumerate(HIPOTECA_BDT_STATE_ORDER)}
    states.sort(key=lambda value: (state_rank.get(normalize_hipoteca_estado(value), 999), value.casefold()))
    return {"years": years, "states": states}


def hipoteca_signed_export_year(row):
    parsed = parse_iso_date(row["fecha_firma"])
    if parsed:
        return str(parsed.year)
    raw_year = str(row["anio"] or "").strip()
    return raw_year if re.fullmatch(r"\d{4}", raw_year) else ""


def is_hipoteca_signed_for_export(row):
    if not parse_iso_date(row["fecha_firma"]):
        return False
    return normalize_hipoteca_estado(row["estado"]) in ("firmada", "firmado")


def collect_hipotecas_firmadas_export_rows(conn, empresa_id, selected_year=None):
    year_filter = str(selected_year or "").strip()
    raw_rows = conn.execute(
        """
        SELECT *
        FROM hipotecas
        WHERE empresa_id = ?
        ORDER BY COALESCE(NULLIF(fecha_firma, ''), NULLIF(fecha_encargo, ''), created_at) DESC, created_at DESC
        """,
        (empresa_id,),
    ).fetchall()
    items = []
    for raw in raw_rows:
        if not is_hipoteca_signed_for_export(raw):
            continue
        declarativo_year = hipoteca_signed_export_year(raw)
        if year_filter and declarativo_year != year_filter:
            continue
        item = build_hipoteca_export_row(conn, raw)
        item["anio_declarativo"] = declarativo_year
        items.append(item)
    items.sort(
        key=lambda item: (
            parse_iso_date(item.get("fecha_firma")) or datetime.min.date(),
            item.get("cliente") or "",
        ),
        reverse=True,
    )
    return items


def collect_hipotecas_firmadas_rows(conn, empresa_id, selected_year=None):
    year_filter = str(selected_year or "").strip()
    raw_rows = conn.execute(
        """
        SELECT *
        FROM hipotecas
        WHERE empresa_id = ?
        ORDER BY COALESCE(NULLIF(fecha_firma, ''), NULLIF(fecha_encargo, ''), created_at) DESC, created_at DESC
        """,
        (empresa_id,),
    ).fetchall()
    items = []
    for raw in raw_rows:
        if not is_hipoteca_signed_for_export(raw):
            continue
        declarativo_year = hipoteca_signed_export_year(raw)
        if year_filter and declarativo_year != year_filter:
            continue
        items.append(raw)
    return items


def hipoteca_export_year(row):
    return extract_hipoteca_bdt_year(row)


def collect_hipotecas_export_rows(
    conn,
    empresa_id,
    selected_year=None,
    selected_estado=None,
    selected_order="desc",
    signed_only=False,
    record_ids=None,
):
    empresa_id = str(empresa_id or "").strip()
    if not empresa_id:
        return []
    raw_rows = conn.execute(
        """
        SELECT *
        FROM hipotecas
        WHERE empresa_id = ?
        ORDER BY COALESCE(NULLIF(fecha_firma, ''), NULLIF(fecha_encargo, ''), updated_at, created_at) DESC
        """,
        (empresa_id,),
    ).fetchall()
    record_id_set = {
        str(item or "").strip()
        for item in (record_ids or [])
        if str(item or "").strip()
    }
    year_filter = str(selected_year or "").strip()
    estado_filter = normalize_hipoteca_estado(selected_estado)
    items = []
    for raw in raw_rows:
        row_id = str(row_value(raw, "id") or "").strip()
        if record_id_set and row_id not in record_id_set:
            continue
        if signed_only and not is_hipoteca_signed_for_export(raw):
            continue
        if year_filter and hipoteca_export_year(raw) != year_filter:
            continue
        if estado_filter and normalize_hipoteca_estado(row_value(raw, "estado")) != estado_filter:
            continue
        items.append(raw)
    return sort_hipoteca_export_rows(items, order=selected_order)


def build_hipotecas_export_pdf_filename(mode="listado", selected_year=None, selected_estado=None, count=None):
    mode_key = normalize_lookup_text(mode)
    if mode_key in {"FICHAS", "FICHA"}:
        return build_hipotecas_fichas_pdf_filename({"year": selected_year, "estado": selected_estado}, count=count)
    if mode_key in {"FIRMADAS", "FIRMADA"}:
        return build_hipotecas_firmadas_pdf_filename(selected_year, count=count)
    return build_hipotecas_bdt_listado_pdf_filename({"year": selected_year, "estado": selected_estado}, count=count)


def build_hipotecas_export_pdf(conn, rows, mode="listado", selected_year=None, selected_estado=None, selected_order="desc"):
    mode_key = normalize_lookup_text(mode)
    filters = {
        "year": str(selected_year or "").strip(),
        "estado": str(selected_estado or "").strip(),
        "order": str(selected_order or "desc").strip() or "desc",
    }
    if mode_key in {"FICHAS", "FICHA", "FIRMADAS", "FIRMADA"}:
        if mode_key in {"FIRMADAS", "FIRMADA"} and not filters["estado"]:
            filters["estado"] = "Firmada"
        return build_hipotecas_fichas_pdf(conn, rows, filters=filters)
    return build_hipotecas_bdt_listado_pdf(conn, rows, filters=filters)


def build_hipotecas_firmadas_excel_workbook(items, selected_year=None, brand_name=None, brand_logo_url=None):
    wb = Workbook()
    summary = wb.active
    summary.title = "Resumen declarativo"

    try:
        from openpyxl.drawing.image import Image as OpenpyxlImage
        from openpyxl.styles import Alignment, Border, Font, PatternFill, Side
        from openpyxl.utils import get_column_letter
    except Exception:
        OpenpyxlImage = None
        Alignment = Border = Font = PatternFill = Side = None
        get_column_letter = None

    def _resolve_excel_logo_path(raw_logo_url=None):
        raw = str(raw_logo_url or "").strip()
        candidates = []
        if raw.startswith("/assets/"):
            candidates.append(ASSETS / raw.replace("/assets/", "", 1))
        elif raw.startswith("assets/"):
            candidates.append(ASSETS / raw)
        elif raw:
            candidate = Path(raw)
            if candidate.exists():
                candidates.append(candidate)
        candidates.append(ASSETS / "verifika2" / "verifika2_wordmark_check_green.png")
        candidates.append(ASSETS / "verifika2" / "verifika2_wordmark_check_green_transparent.png")
        for candidate in candidates:
            if candidate and candidate.exists():
                return candidate
        return None

    year_label = str(selected_year or "").strip() or "Histórico"
    brand_label = str(brand_name or "").strip() or "Verifika²"
    logo_path = _resolve_excel_logo_path(brand_logo_url)

    summary.sheet_view.showGridLines = False
    summary.freeze_panes = "A10"
    summary.row_dimensions[1].height = 28
    summary.row_dimensions[2].height = 22
    summary.row_dimensions[3].height = 22
    summary.row_dimensions[4].height = 22
    summary.row_dimensions[5].height = 22
    summary.row_dimensions[6].height = 22
    summary.row_dimensions[7].height = 22
    summary.row_dimensions[8].height = 22
    summary.merge_cells("A1:G1")
    summary["A1"] = f"{brand_label} · Declarativo anual · Hipotecas firmadas"

    if OpenpyxlImage is not None and logo_path is not None:
        try:
            logo_img = OpenpyxlImage(str(logo_path))
            logo_img.width = 228
            logo_img.height = 62
            summary.add_image(logo_img, "I1")
        except Exception:
            pass

    summary["A2"] = "Ejercicio"
    summary["B2"] = year_label
    summary["A3"] = "Operaciones"
    summary["B3"] = len(items)
    summary["A4"] = "Volumen hipotecario"
    summary["B4"] = sum(float(item.get("importe_hipoteca") or 0) for item in items)
    summary["A5"] = "Honorarios"
    summary["B5"] = sum(float(item.get("honorarios") or 0) for item in items)
    summary["A6"] = "Cesión inmobiliaria"
    summary["B6"] = sum(float(item.get("cesion") or 0) for item in items)
    summary["A7"] = "Cesión Juan"
    summary["B7"] = sum(float(item.get("comision_juan") or 0) for item in items)
    summary["A8"] = "Margen oficina"
    summary["B8"] = sum(float(item.get("comision_modernia") or 0) for item in items)

    month_headers = ("Mes firma", "Operaciones", "Volumen", "Honorarios")
    for col_idx, value in enumerate(month_headers, start=1):
        summary.cell(row=10, column=col_idx, value=value)
    month_totals = {}
    for item in items:
        fecha = parse_iso_date(item.get("fecha_firma"))
        month_key = fecha.strftime("%Y-%m") if fecha else "Sin fecha"
        entry = month_totals.setdefault(
            month_key,
            {"total": 0, "volumen": 0.0, "honorarios": 0.0},
        )
        entry["total"] += 1
        entry["volumen"] += float(item.get("importe_hipoteca") or 0)
        entry["honorarios"] += float(item.get("honorarios") or 0)
    month_row = 11
    for month_key in sorted(month_totals.keys()):
        bucket = month_totals[month_key]
        summary.cell(row=month_row, column=1, value=month_key)
        summary.cell(row=month_row, column=2, value=bucket["total"])
        summary.cell(row=month_row, column=3, value=bucket["volumen"])
        summary.cell(row=month_row, column=4, value=bucket["honorarios"])
        month_row += 1

    bank_headers = ("Entidad", "Operaciones", "Volumen", "Honorarios")
    for col_idx, value in enumerate(bank_headers, start=6):
        summary.cell(row=10, column=col_idx, value=value)
    bank_totals = {}
    for item in items:
        bank_key = str(item.get("banco") or "Sin entidad").strip() or "Sin entidad"
        entry = bank_totals.setdefault(
            bank_key,
            {"total": 0, "volumen": 0.0, "honorarios": 0.0},
        )
        entry["total"] += 1
        entry["volumen"] += float(item.get("importe_hipoteca") or 0)
        entry["honorarios"] += float(item.get("honorarios") or 0)
    bank_row = 11
    for bank_key, bucket in sorted(bank_totals.items(), key=lambda pair: (-pair[1]["total"], pair[0])):
        summary.cell(row=bank_row, column=6, value=bank_key)
        summary.cell(row=bank_row, column=7, value=bucket["total"])
        summary.cell(row=bank_row, column=8, value=bucket["volumen"])
        summary.cell(row=bank_row, column=9, value=bucket["honorarios"])
        bank_row += 1

    detail = wb.create_sheet("Operaciones firmadas")
    base_detail_headers = [
        ("Año declarativo", "anio_declarativo"),
        ("Fecha firma", "fecha_firma"),
        ("Cliente", "cliente"),
        ("DNI", "cliente_nif"),
        ("Teléfono", "cliente_telefono"),
        ("Email", "cliente_email"),
        ("Dirección", "cliente_direccion"),
        ("Banco", "banco"),
        ("Tipo hipoteca", "tipo_hipoteca"),
        ("Importe hipoteca", "importe_hipoteca"),
        ("Precio compra", "precio"),
        ("% financiación", "porcentaje"),
        ("Entrada", "entrada"),
        ("Honorarios", "honorarios"),
        ("Cesión inmobiliaria", "cesion"),
        ("Cesión Juan", "comision_juan"),
        ("Margen oficina", "comision_modernia"),
        ("Inmobiliaria", "inmobiliaria"),
        ("Oficina", "oficina"),
        ("Asesor", "asesor"),
        ("Fecha encargo", "fecha_encargo"),
        ("Encargo", "encargo"),
        ("Estado", "estado"),
        ("ID operación", "id"),
    ]
    client_field_names = []
    seen_client_fields = set()
    for item in items or []:
        client_fields = item.get("cliente_fields") if isinstance(item, dict) else None
        if not isinstance(client_fields, dict):
            continue
        for field_name in client_fields.keys():
            raw_field = str(field_name or "").strip()
            if not raw_field or raw_field in HIPOTECA_CLIENT_EXPORT_SKIP_FIELDS:
                continue
            if raw_field in seen_client_fields:
                continue
            seen_client_fields.add(raw_field)
            client_field_names.append(raw_field)

    detail_headers = base_detail_headers + [
        (_hipoteca_cliente_export_label(field_name), ("cliente_fields", field_name))
        for field_name in client_field_names
    ]

    def _detail_value(item, source_key):
        if isinstance(source_key, tuple) and len(source_key) == 2 and source_key[0] == "cliente_fields":
            client_fields = item.get("cliente_fields") if isinstance(item, dict) else None
            if isinstance(client_fields, dict):
                return client_fields.get(source_key[1], "")
            return ""
        if isinstance(item, dict):
            return item.get(source_key, "")
        return ""

    def _detail_source_name(source_key):
        if isinstance(source_key, tuple) and len(source_key) == 2:
            return str(source_key[1] or "")
        return str(source_key or "")

    detail.append([header for header, _ in detail_headers])
    for item in items:
        detail.append([_detail_value(item, source_key) for _, source_key in detail_headers])

    def style_header_row(sheet, row_idx):
        for cell in sheet[row_idx]:
            font = shallow_copy(cell.font)
            font.bold = True
            font.color = "FFFFFF"
            fill = shallow_copy(cell.fill)
            fill.fill_type = "solid"
            fill.fgColor = "123024"
            alignment = shallow_copy(cell.alignment)
            alignment.horizontal = "center"
            cell.font = font
            cell.fill = fill
            cell.alignment = alignment

    style_header_row(summary, 10)
    style_header_row(detail, 1)
    summary["A1"].font = Font(color="FFFFFF", bold=True, size=16) if Font else summary["A1"].font
    summary["A1"].fill = PatternFill("solid", fgColor="123024") if PatternFill else summary["A1"].fill
    summary["A1"].alignment = Alignment(horizontal="left", vertical="center") if Alignment else summary["A1"].alignment
    summary["A1"].border = Border(bottom=Side(style="thin", color="C8A24A")) if Border and Side else summary["A1"].border

    if Border and Side and PatternFill and Font and Alignment:
        soft_fill = PatternFill("solid", fgColor="F8FAFC")
        accent_fill = PatternFill("solid", fgColor="EEF4FF")
        box_border = Border(
            left=Side(style="thin", color="D8E1EA"),
            right=Side(style="thin", color="D8E1EA"),
            top=Side(style="thin", color="D8E1EA"),
            bottom=Side(style="thin", color="D8E1EA"),
        )
        label_font = Font(color="102131", bold=True, size=11)
        value_font = Font(color="123024", bold=True, size=11)
        for row_idx in range(2, 9):
            label_cell = summary.cell(row=row_idx, column=1)
            value_cell = summary.cell(row=row_idx, column=2)
            label_cell.border = box_border
            value_cell.border = box_border
            label_cell.fill = soft_fill
            value_cell.fill = accent_fill
            label_cell.font = label_font
            value_cell.font = value_font
            label_cell.alignment = Alignment(horizontal="left", vertical="center")
            value_cell.alignment = Alignment(horizontal="right", vertical="center")
        for row_idx in range(11, max(month_row, 12)):
            for col_idx in range(1, 5):
                cell = summary.cell(row=row_idx, column=col_idx)
                cell.border = box_border
                if row_idx % 2 == 0:
                    cell.fill = soft_fill
        for row_idx in range(11, max(bank_row, 12)):
            for col_idx in range(6, 10):
                cell = summary.cell(row=row_idx, column=col_idx)
                cell.border = box_border
                if row_idx % 2 == 0:
                    cell.fill = soft_fill
        for row_idx in range(2, detail.max_row + 1):
            for col_idx in range(1, detail.max_column + 1):
                cell = detail.cell(row=row_idx, column=col_idx)
                cell.border = box_border
                if row_idx % 2 == 0:
                    cell.fill = soft_fill

    for cell in ("B4", "B5", "B6", "B7", "B8"):
        summary[cell].number_format = '#,##0.00 "€"'
    for row_idx in range(11, max(month_row, 12)):
        summary.cell(row=row_idx, column=3).number_format = '#,##0.00 "€"'
        summary.cell(row=row_idx, column=4).number_format = '#,##0.00 "€"'
    for row_idx in range(11, max(bank_row, 12)):
        summary.cell(row=row_idx, column=8).number_format = '#,##0.00 "€"'
        summary.cell(row=row_idx, column=9).number_format = '#,##0.00 "€"'

    money_source_names = {
        "importe_hipoteca",
        "precio",
        "porcentaje",
        "entrada",
        "honorarios",
        "cesion",
        "comision_juan",
        "comision_modernia",
    }
    date_source_names = {
        "fecha_firma",
        "fecha_encargo",
        "fecha_nacimiento",
        "created_at",
        "updated_at",
    }
    for row_idx in range(2, detail.max_row + 1):
        for col_idx, (_, source_key) in enumerate(detail_headers, start=1):
            cell = detail.cell(row=row_idx, column=col_idx)
            source_name = _detail_source_name(source_key)
            if source_name in money_source_names:
                cell.number_format = '#,##0.00'
                continue
            if source_name in date_source_names or "fecha" in source_name.lower() or source_name.endswith("_at"):
                parsed = parse_iso_date(cell.value)
                if parsed:
                    cell.value = parsed
                    cell.number_format = "DD/MM/YYYY"
    widths = {
        "A": 16,
        "B": 14,
        "C": 30,
        "D": 16,
        "E": 16,
        "F": 28,
        "G": 36,
        "H": 22,
        "I": 18,
        "J": 18,
        "K": 18,
        "L": 14,
        "M": 14,
        "N": 14,
        "O": 16,
        "P": 14,
        "Q": 16,
        "R": 24,
        "S": 20,
        "T": 18,
        "U": 14,
        "V": 18,
        "W": 16,
        "X": 18,
    }
    for col, width in widths.items():
        detail.column_dimensions[col].width = width
    if get_column_letter is not None and len(detail_headers) > len(base_detail_headers):
        for idx, (label, _) in enumerate(detail_headers[len(base_detail_headers):], start=len(base_detail_headers) + 1):
            col_letter = get_column_letter(idx)
            detail.column_dimensions[col_letter].width = max(16, min(34, len(str(label)) + 2))
    for col, width in {"A": 22, "B": 14, "C": 18, "D": 18, "F": 24, "G": 12, "H": 18, "I": 12, "J": 18}.items():
        summary.column_dimensions[col].width = width

    for sheet in (summary, detail):
        sheet.sheet_view.showGridLines = False
    detail.freeze_panes = "A2"
    last_col = get_column_letter(detail.max_column) if get_column_letter is not None else "X"
    detail.auto_filter.ref = f"A1:{last_col}{max(detail.max_row, 1)}"
    return wb


def build_hipotecas_listado_excel_workbook(items, selected_year=None, brand_name=None, brand_logo_url=None):
    normalized_items = []
    for item in items or []:
        normalized_item = dict(item or {})
        normalized_item["anio_declarativo"] = str(
            normalized_item.get("anio_declarativo")
            or normalized_item.get("anio")
            or ""
        ).strip()
        normalized_items.append(normalized_item)
    wb = build_hipotecas_firmadas_excel_workbook(
        normalized_items,
        selected_year,
        brand_name=brand_name,
        brand_logo_url=brand_logo_url,
    )
    if wb.sheetnames:
        summary = wb[wb.sheetnames[0]]
        summary.title = "Resumen listado"
        summary["A1"] = f"{str(brand_name or '').strip() or 'Verifika²'} · Listado anual · Hipotecas"
    if len(wb.sheetnames) > 1:
        detail = wb[wb.sheetnames[1]]
        detail.title = "Operaciones listado"
        detail["A1"] = "Año"
    return wb


_safe_json_object = runtime_security_utils._safe_json_object


def _get_nested(obj, path, default=""):
    cur = obj
    for part in str(path or "").split("."):
        if not part:
            continue
        if not isinstance(cur, dict) or part not in cur:
            return default
        cur = cur.get(part)
    return cur if cur is not None else default


def _set_nested(obj, path, value):
    cur = obj
    parts = [p for p in str(path or "").split(".") if p]
    if not parts:
        return
    for part in parts[:-1]:
        nxt = cur.get(part)
        if not isinstance(nxt, dict):
            nxt = {}
            cur[part] = nxt
        cur = nxt
    cur[parts[-1]] = value


def _is_financiado(value):
    return str(normalize_lookup_text(value) or "").strip().lower() in {
        "si",
        "sí",
        "s",
        "true",
        "1",
        "financiado",
        "financiada",
    }


def _round2(value):
    try:
        return round(float(value or 0), 2)
    except Exception:
        return 0.0


def compute_hipoteca_liquidacion_print_data(export_row, liquidacion_raw):
    liq = liquidacion_raw if isinstance(liquidacion_raw, dict) else {}
    comprador = liq.get("comprador") if isinstance(liq.get("comprador"), dict) else {}
    gastos_cv = comprador.get("gastos_compraventa") if isinstance(comprador.get("gastos_compraventa"), dict) else {}
    hip = comprador.get("hipoteca") if isinstance(comprador.get("hipoteca"), dict) else {}
    entregas = comprador.get("entregas") if isinstance(comprador.get("entregas"), dict) else {}
    prestamo = liq.get("prestamo") if isinstance(liq.get("prestamo"), dict) else {}
    vendedor = liq.get("vendedor") if isinstance(liq.get("vendedor"), dict) else {}
    vendedor_ded = vendedor.get("deducciones") if isinstance(vendedor.get("deducciones"), dict) else {}
    vendedor_vendedores = vendedor.get("vendedores") if isinstance(vendedor.get("vendedores"), dict) else {}
    cuadre = liq.get("cuadre") if isinstance(liq.get("cuadre"), dict) else {}
    cuadre_cheq1 = cuadre.get("cheque1") if isinstance(cuadre.get("cheque1"), dict) else {}
    cuadre_cheq2 = cuadre.get("cheque2") if isinstance(cuadre.get("cheque2"), dict) else {}
    cuadre_gastos = cuadre.get("gastos_escrituras") if isinstance(cuadre.get("gastos_escrituras"), dict) else {}
    notaria = liq.get("notaria") if isinstance(liq.get("notaria"), dict) else {}

    # Defaults desde ficha (si el JSON está incompleto).
    precio_base = parse_money_value(export_row.get("precio") or 0)
    hipoteca_base = parse_money_value(export_row.get("importe_hipoteca") or 0)
    if not str(comprador.get("precio_compra") or "").strip() and precio_base:
        comprador["precio_compra"] = precio_base
    if not str(comprador.get("escriturado") or "").strip() and (comprador.get("precio_compra") or precio_base):
        comprador["escriturado"] = comprador.get("precio_compra") or precio_base
    if not str(hip.get("capital") or "").strip() and hipoteca_base:
        hip["capital"] = hipoteca_base
    if not str(entregas.get("prestamo_concedido") or "").strip() and hipoteca_base:
        entregas["prestamo_concedido"] = hipoteca_base

    precio = parse_money_value(comprador.get("precio_compra") or comprador.get("escriturado") or 0)
    escriturado = parse_money_value(comprador.get("escriturado") or precio or 0)

    # Totales gastos compraventa.
    gastos_cv_notaria = parse_money_value(gastos_cv.get("notaria") or 0)
    gastos_cv_registro = parse_money_value(gastos_cv.get("registro") or 0)
    gastos_cv_itp = parse_money_value(gastos_cv.get("itp") or 0)
    gastos_cv_gestoria = parse_money_value(gastos_cv.get("gestoria") or 0)
    total_cv = _round2(gastos_cv_notaria + gastos_cv_registro + gastos_cv_itp + gastos_cv_gestoria)
    gastos_cv["total"] = total_cv

    # Gastos constitución hipoteca.
    hip_notaria_impuestos_gestoria = parse_money_value(hip.get("notaria_impuestos_gestoria") or 0)
    hip_com_apertura = parse_money_value(hip.get("comision_apertura") or 0)
    hip_cuota_socio = parse_money_value(hip.get("cuota_socio") or 0)
    hip_com_cheques = parse_money_value(hip.get("comision_cheques") or 0)
    hip_seg_proteccion = parse_money_value(hip.get("seguro_proteccion_pago") or 0)
    hip_seg_hogar = parse_money_value(hip.get("seguro_hogar") or 0)
    hip_seg_vida = parse_money_value(hip.get("seguro_vida") or 0)

    prot_fin = _is_financiado(hip.get("seguro_proteccion_financiado") or "No")
    hogar_fin = _is_financiado(hip.get("seguro_hogar_financiado") or "No")
    vida_fin = _is_financiado(hip.get("seguro_vida_financiado") or "No")

    prot_cash = 0.0 if prot_fin else hip_seg_proteccion
    hogar_cash = 0.0 if hogar_fin else hip_seg_hogar
    vida_cash = 0.0 if vida_fin else hip_seg_vida

    total_hip_cash = _round2(
        hip_notaria_impuestos_gestoria + hip_com_apertura + hip_cuota_socio + hip_com_cheques + prot_cash
    )
    hip["total_gastos"] = total_hip_cash
    total_bloque = _round2(
        hip_notaria_impuestos_gestoria
        + hip_com_apertura
        + hip_cuota_socio
        + hip_com_cheques
        + hip_seg_proteccion
        + hip_seg_hogar
        + hip_seg_vida
    )
    hip["total_bloque"] = total_bloque
    total_necesario = _round2(total_hip_cash + hogar_cash + vida_cash)
    hip["total_necesario"] = total_necesario

    gestion_inmo = parse_money_value(comprador.get("gestion_inmobiliaria") or 0)
    gestion_fin = parse_money_value(comprador.get("gestion_financiacion") or 0)
    suma_total_necesaria = _round2(precio + total_cv + total_necesario + gestion_inmo + gestion_fin)
    comprador["suma_total_necesaria"] = suma_total_necesaria

    # Entregas
    senal = parse_money_value(entregas.get("senal") or 0)
    transf_modernia = parse_money_value(entregas.get("transf_modernia") or 0)
    prestamo_concedido = parse_money_value(entregas.get("prestamo_concedido") or 0)
    ingresar_actual = entregas.get("ingresar_banco")
    ingresar_banco = None
    if isinstance(ingresar_actual, (int, float)):
        ingresar_banco = float(ingresar_actual)
    else:
        ingresar_actual_raw = str(ingresar_actual or "").strip()
        if ingresar_actual_raw:
            ingresar_banco = parse_money_value(ingresar_actual_raw) or 0.0
    if ingresar_banco is None:
        # A ingresar en banco autocalculado como Excel (solo si está vacío).
        base = max(suma_total_necesaria - prestamo_concedido - senal - transf_modernia, 0)
        ingresar_banco = float((int((base + 99) // 100) * 100)) if base > 0 else 0.0
    entregas["ingresar_banco"] = _round2(ingresar_banco)

    suma_entregada = _round2(senal + transf_modernia + ingresar_banco)
    comprador["suma_total_entregada"] = suma_entregada

    sobran = _round2(prestamo_concedido + suma_entregada - suma_total_necesaria)
    comprador["sobran_en_cuenta"] = sobran

    # Vendedor (replica Excel).
    if not str(vendedor.get("precio_vivienda") or "").strip() and precio:
        vendedor["precio_vivienda"] = precio
    if not str(vendedor_ded.get("senal") or "").strip() and senal:
        vendedor_ded["senal"] = senal

    vend_precio = parse_money_value(vendedor.get("precio_vivienda") or 0)
    vend_senal = parse_money_value(vendedor_ded.get("senal") or 0)
    vend_can_eco = parse_money_value(vendedor_ded.get("cancelacion_economica") or 0)
    vend_can_reg = parse_money_value(vendedor_ded.get("cancelacion_registral") or 0)
    vend_ibi = parse_money_value(vendedor_ded.get("deuda_ibi") or 0)
    vend_plus = parse_money_value(vendedor_ded.get("plusvalia") or 0)
    vend_ret = parse_money_value(vendedor_ded.get("retencion_no_residente") or 0)
    vend_gest_nr = parse_money_value(vendedor_ded.get("gestion_no_residente") or 0)

    subtotal_pte = _round2(vend_precio - vend_senal - vend_can_eco - vend_can_reg - vend_ibi - vend_plus)
    vendedor["subtotal_pte_percibir"] = subtotal_pte
    total_percibir = _round2(subtotal_pte - vend_ret - vend_gest_nr)
    vendedor["total_a_percibir"] = total_percibir

    # Cuadre cheques (autorrelleno desde comprador/vendedor).
    cuadre["prestamo_concedido"] = _round2(prestamo_concedido)
    cuadre["ingreso_en_cuenta"] = _round2(ingresar_banco)
    cuadre["cancelacion_economica"] = _round2(vend_can_eco)
    cuadre["retencion_cancelacion_registral"] = _round2(vend_can_reg)
    cuadre["retencion_ibi"] = _round2(vend_ibi)
    cuadre["retencion_no_residente"] = _round2(vend_ret)
    cuadre["gestion_no_residente"] = _round2(vend_gest_nr)

    cuadre_gastos["compraventa"] = _round2(total_cv)
    cuadre_gastos["hipoteca"] = _round2(hip_notaria_impuestos_gestoria)
    cuadre_gastos["com_apertura"] = _round2(hip_com_apertura)
    cuadre["comision_cheques"] = _round2(hip_com_cheques)
    cuadre["cuota_socio"] = _round2(hip_cuota_socio)

    # Seguros (cuadre de cheques): por defecto, suma de los seguros NO financiados.
    if not str(cuadre.get("seguros") or "").strip():
        cuadre["seguros"] = _round2(prot_cash + hogar_cash + vida_cash)

    seguros_cuadre = parse_money_value(cuadre.get("seguros") or 0)

    # Beneficiarios por defecto (OMF vendedor/es).
    v1 = vendedor_vendedores.get("v1") if isinstance(vendedor_vendedores.get("v1"), dict) else {}
    v2 = vendedor_vendedores.get("v2") if isinstance(vendedor_vendedores.get("v2"), dict) else {}
    v1_name = str(v1.get("nombre") or "").strip()
    v2_name = str(v2.get("nombre") or "").strip()
    if not str(cuadre_cheq1.get("beneficiario") or "").strip() and v1_name:
        cuadre_cheq1["beneficiario"] = f"OMF {v1_name}"
    if not str(cuadre_cheq2.get("beneficiario") or "").strip() and v2_name:
        cuadre_cheq2["beneficiario"] = f"OMF {v2_name}"

    # Reparto por defecto de cheques con el total_a_percibir (si están vacíos).
    cheq1_has = str(cuadre_cheq1.get("importe") or "").strip() != ""
    cheq2_has = str(cuadre_cheq2.get("importe") or "").strip() != ""
    v2_exists = bool(v2_name)
    if total_percibir > 0:
        if not cheq1_has and not cheq2_has:
            if v2_exists:
                half = _round2(total_percibir / 2)
                cuadre_cheq1["importe"] = half
                cuadre_cheq2["importe"] = _round2(total_percibir - half)
            else:
                cuadre_cheq1["importe"] = _round2(total_percibir)
        elif v2_exists and cheq1_has and not cheq2_has:
            cuadre_cheq2["importe"] = _round2(total_percibir - parse_money_value(cuadre_cheq1.get("importe") or 0))
        elif v2_exists and not cheq1_has and cheq2_has:
            cuadre_cheq1["importe"] = _round2(total_percibir - parse_money_value(cuadre_cheq2.get("importe") or 0))

    # Importes de cheques (ya con reparto por defecto aplicado, si tocaba).
    cheq1_imp = parse_money_value(cuadre_cheq1.get("importe") or 0)
    cheq2_imp = parse_money_value(cuadre_cheq2.get("importe") or 0)

    # Total salidas en el cuadre (Excel): cheques + deducciones + gastos + seguros.
    total_salidas = _round2(
        cheq1_imp
        + cheq2_imp
        + parse_money_value(cuadre.get("cancelacion_economica") or 0)
        + parse_money_value(cuadre.get("retencion_cancelacion_registral") or 0)
        + parse_money_value(cuadre.get("retencion_ibi") or 0)
        + parse_money_value(cuadre.get("retencion_no_residente") or 0)
        + parse_money_value(cuadre.get("gestion_no_residente") or 0)
        + parse_money_value(cuadre_gastos.get("compraventa") or 0)
        + parse_money_value(cuadre_gastos.get("hipoteca") or 0)
        + parse_money_value(cuadre_gastos.get("com_apertura") or 0)
        + parse_money_value(cuadre.get("comision_cheques") or 0)
        + parse_money_value(cuadre.get("cuota_socio") or 0)
        + seguros_cuadre
    )
    cuadre["total_salidas"] = total_salidas

    sobran_cuadre = _round2(prestamo_concedido + ingresar_banco - total_salidas)
    cuadre["sobran_en_cuenta"] = sobran_cuadre

    total_medios_pago = _round2(senal + vend_can_eco + vend_can_reg + vend_ibi + vend_ret + vend_gest_nr + cheq1_imp + cheq2_imp)
    cuadre["total_medios_pago"] = total_medios_pago
    cuadre["diferencia_medios_pago"] = _round2(escriturado - total_medios_pago)

    # Flags de cuadre: el sobrante debe cuadrar (comprador vs cuadre).
    sobrante_delta = _round2(sobran - sobran_cuadre)
    sobrante_ok = abs(sobrante_delta) <= 0.01

    # Persist computed back into structure for rendering.
    comprador["precio_compra"] = precio
    comprador["escriturado"] = escriturado
    comprador["gastos_compraventa"] = gastos_cv
    comprador["hipoteca"] = hip
    comprador["entregas"] = entregas
    liq["comprador"] = comprador
    liq["prestamo"] = prestamo
    vendedor["deducciones"] = vendedor_ded
    vendedor["vendedores"] = vendedor_vendedores
    liq["vendedor"] = vendedor
    cuadre["cheque1"] = cuadre_cheq1
    cuadre["cheque2"] = cuadre_cheq2
    cuadre["gastos_escrituras"] = cuadre_gastos
    liq["cuadre"] = cuadre
    liq["notaria"] = notaria

    return {
        "liq": liq,
        "flags": {
            "proteccion_financiado": prot_fin,
            "hogar_financiado": hogar_fin,
            "vida_financiado": vida_fin,
            "cuadre_sobrante_ok": sobrante_ok,
            "cuadre_sobrante_delta": sobrante_delta,
        },
    }


def render_hipoteca_print_html(payload, auto_print=False, section=None):
    cliente = html.escape(payload["cliente"] or "Cliente")
    banco = html.escape(payload["banco"] or "-")
    tipo = html.escape(payload["tipo_hipoteca"] or "-")
    asesor = html.escape(payload["asesor"] or "-")
    inmobiliaria = html.escape(payload["inmobiliaria"] or "-")
    estado = html.escape(payload["estado"] or "-")
    fecha_encargo = html.escape(format_export_date(payload["fecha_encargo"]) or "-")
    fecha_firma = html.escape(format_export_date(payload["fecha_firma"]) or "-")
    importe = html.escape(format_export_money(payload["importe_hipoteca"]))
    precio = html.escape(format_export_money(payload["precio"]))
    entrada = html.escape(format_export_money(payload["entrada"]))
    liq_payload = payload.get("liquidacion_print") if isinstance(payload.get("liquidacion_print"), dict) else {}
    liq = liq_payload.get("liq") if isinstance(liq_payload.get("liq"), dict) else {}
    flags = liq_payload.get("flags") if isinstance(liq_payload.get("flags"), dict) else {}
    print_script = (
        "<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));</script>"
        if auto_print
        else ""
    )
    section_key = normalize_lookup_text(section or "").lower()
    filter_script = ""
    if section_key and section_key not in {"all", "todo", "todas"}:
        filter_script = f"""
<script>
(function () {{
  function applyHipotecaPrintSectionFilter() {{
    try {{
      const norm = (value) => String(value || "")
        .trim()
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\\u0300-\\u036f]/g, "");
      const params = new URLSearchParams(window.location.search || "");
      const fromUrl = norm(params.get("section"));
      const fromServer = norm({json.dumps(section_key)});
      const section = fromUrl || fromServer;
      if (!section || ["all", "todo", "todas"].includes(section)) return;
      const allowed = new Set(["comprador", "vendedor", "cheques", "notaria"]);
      if (!allowed.has(section)) return;
      document.querySelectorAll(".page-break").forEach((el) => {{
        el.style.display = "none";
      }});
      document.querySelectorAll("[data-print-section]").forEach((el) => {{
        const key = norm(el.getAttribute("data-print-section"));
        if (key !== section) el.style.display = "none";
      }});
    }} catch (e) {{}}
  }}
  // Importante: el HTML se genera en servidor y este script vive en <head>.
  // Esperamos a que el DOM esté listo para que el filtro realmente encuentre los paneles.
  if (document.readyState === "loading") {{
    window.addEventListener("DOMContentLoaded", applyHipotecaPrintSectionFilter, {{ once: true }});
  }} else {{
    applyHipotecaPrintSectionFilter();
  }}
}})();
</script>
"""

    def money(value):
        return html.escape(format_export_money(parse_money_value(value or 0)))

    def num(value, decimals=4):
        amount = parse_money_value(value)
        if amount is None:
            return "-"
        text = f"{amount:,.{int(decimals)}f}".replace(",", "X").replace(".", ",").replace("X", ".")
        if "," in text:
            text = text.rstrip("0").rstrip(",")
        return html.escape(text)

    cliente_inmueble = _safe_json_object(payload.get("cliente_inmueble_json") or "{}")

    def fallback_text(primary, nested_path=None, default="-"):
        raw = str(primary or "").strip()
        if raw:
            return raw
        if nested_path:
            nested_value = _get_nested(cliente_inmueble or {}, nested_path, default)
            nested_text = str(nested_value or "").strip()
            if nested_text:
                return nested_text
        return default

    comprador = liq.get("comprador") if isinstance(liq.get("comprador"), dict) else {}
    gastos_cv = comprador.get("gastos_compraventa") if isinstance(comprador.get("gastos_compraventa"), dict) else {}
    hip = comprador.get("hipoteca") if isinstance(comprador.get("hipoteca"), dict) else {}
    entregas = comprador.get("entregas") if isinstance(comprador.get("entregas"), dict) else {}
    prestamo = liq.get("prestamo") if isinstance(liq.get("prestamo"), dict) else {}
    vendedor = liq.get("vendedor") if isinstance(liq.get("vendedor"), dict) else {}
    vendedor_ded = vendedor.get("deducciones") if isinstance(vendedor.get("deducciones"), dict) else {}
    vendedor_vendedores = vendedor.get("vendedores") if isinstance(vendedor.get("vendedores"), dict) else {}
    vend_v1 = vendedor_vendedores.get("v1") if isinstance(vendedor_vendedores.get("v1"), dict) else {}
    vend_v2 = vendedor_vendedores.get("v2") if isinstance(vendedor_vendedores.get("v2"), dict) else {}
    cuadre = liq.get("cuadre") if isinstance(liq.get("cuadre"), dict) else {}
    cuadre_cheq1 = cuadre.get("cheque1") if isinstance(cuadre.get("cheque1"), dict) else {}
    cuadre_cheq2 = cuadre.get("cheque2") if isinstance(cuadre.get("cheque2"), dict) else {}
    cuadre_gastos = cuadre.get("gastos_escrituras") if isinstance(cuadre.get("gastos_escrituras"), dict) else {}
    notaria = liq.get("notaria") if isinstance(liq.get("notaria"), dict) else {}

    porcentaje_val = parse_optional_float(payload.get("porcentaje"))
    porcentaje_text = "-"
