def _hipoteca_ficha_row_text(row, key, default=""):
    if row is None:
        return default
    try:
        if isinstance(row, dict):
            value = row.get(key)
        elif hasattr(row, "keys") and key in row.keys():
            value = row[key]
        else:
            return default
    except Exception:
        return default
    text = str(value or "").strip()
    return text or default


def _hipoteca_ficha_bool_text(value):
    raw = str(value or "").strip()
    if not raw:
        return "—"
    normalized = normalize_lookup_text(raw)
    if normalized in {"SI", "S", "TRUE", "1", "YES", "Y"}:
        return "Sí"
    if normalized in {"NO", "FALSE", "0", "N"}:
        return "No"
    return raw


def _hipoteca_ficha_money(value, default="—"):
    if value in (None, ""):
        return default
    try:
        amount = parse_money_value(value)
    except Exception:
        amount = None
    if amount is None:
        text = str(value or "").strip()
        return text or default
    return format_eur(amount)


def _hipoteca_ficha_num(value, decimals=2, default="—"):
    if value in (None, ""):
        return default
    parsed = parse_optional_float(value)
    if parsed is None:
        text = str(value or "").strip()
        return text or default
    try:
        amount = float(parsed)
    except Exception:
        text = str(value or "").strip()
        return text or default
    raw = f"{amount:,.{int(decimals)}f}".replace(",", "X").replace(".", ",").replace("X", ".")
    if int(decimals) > 0:
        raw = raw.rstrip("0").rstrip(",")
    return raw


def _hipoteca_ficha_json_lines(raw_value):
    text = str(raw_value or "").strip()
    if not text:
        return ["{}"]
    try:
        parsed = json.loads(text)
    except Exception:
        return text.splitlines() or [text]
    try:
        return json.dumps(parsed, ensure_ascii=False, indent=2, sort_keys=True).splitlines()
    except Exception:
        return text.splitlines() or [text]


def _hipoteca_ficha_intervinientes_text(cliente_inmueble):
    intervinientes = _get_nested(cliente_inmueble or {}, "intervinientes", [])
    if not isinstance(intervinientes, list):
        return "—"
    parts = []
    for item in intervinientes:
        if not isinstance(item, dict):
            continue
        rol = str(item.get("rol") or item.get("tipo") or "Interviniente").strip()
        nombre = str(item.get("nombre") or item.get("name") or "").strip()
        nif = str(item.get("nif") or item.get("dni") or "").strip()
        chunk = " · ".join([part for part in [rol, nombre, nif] if part])
        if chunk:
            parts.append(chunk)
    return " | ".join(parts) if parts else "—"


def build_hipoteca_ficha_payload(conn, row):
    payload = build_hipoteca_export_row(conn, row)
    payload["empresa_id"] = _hipoteca_ficha_row_text(row, "empresa_id")
    payload["created_at"] = _hipoteca_ficha_row_text(row, "created_at")
    payload["updated_at"] = _hipoteca_ficha_row_text(row, "updated_at")
    payload["cliente_inmueble_json"] = _hipoteca_ficha_row_text(row, "cliente_inmueble_json")
    payload["hipoteca_detalle_json"] = _hipoteca_ficha_row_text(row, "hipoteca_detalle_json")
    payload["liquidacion_json"] = _hipoteca_ficha_row_text(row, "liquidacion_json")
    liquidacion_raw = _safe_json_object(payload.get("liquidacion_json") or "{}")
    payload["liquidacion_print"] = compute_hipoteca_liquidacion_print_data(payload, liquidacion_raw)
    return payload


def build_hipoteca_ficha_pdf_filename(payload, section=None):
    payload = payload or {}
    parts = ["ficha_hipoteca"]
    for value in (
        slugify_text(payload.get("cliente") or ""),
        slugify_text(payload.get("banco") or ""),
        slugify_text(payload.get("id") or ""),
    ):
        if value:
            parts.append(value)
            break
    else:
        parts.append("documento")
    section_key = slugify_text(section or "")
    if section_key and section_key not in {"all", "todo", "todas"}:
        parts.append(section_key)
    filename = "_".join(part for part in parts if part).strip("_")[:160] or "ficha_hipoteca"
    return f"{filename}.pdf"


def build_hipotecas_fichas_pdf_filename(filters=None, count=None):
    filters = filters or {}
    parts = ["fichas_hipotecas"]
    year = slugify_text(filters.get("year") or "")
    estado = slugify_text(filters.get("estado") or "")
    if year:
        parts.append(year)
    if estado:
        parts.append(estado)
    if count:
        parts.append(str(int(count)))
    filename = "_".join(part for part in parts if part).strip("_")[:160] or "fichas_hipotecas"
    return f"{filename}.pdf"


def build_hipotecas_firmadas_pdf_filename(selected_year=None, count=None):
    parts = ["hipotecas_firmadas"]
    year = slugify_text(str(selected_year or "").strip())
    if year:
        parts.append(year)
    if count:
        parts.append(str(int(count)))
    filename = "_".join(part for part in parts if part).strip("_")[:160] or "hipotecas_firmadas"
    return f"{filename}.pdf"


def build_hipotecas_bdt_listado_pdf_filename(filters=None, count=None):
    filters = filters or {}
    parts = ["hipotecas_listado"]
    year = slugify_text(filters.get("year") or "")
    estado = slugify_text(filters.get("estado") or "")
    order = normalize_hipoteca_pdf_sort_order(filters.get("order") or filters.get("sort_order") or "desc")
    if year:
        parts.append(year)
    if estado:
        parts.append(estado)
    if order:
        parts.append(order)
    if count:
        parts.append(str(int(count)))
    filename = "_".join(part for part in parts if part).strip("_")[:160] or "hipotecas_listado"
    return f"{filename}.pdf"


build_hipoteca_ficha_pdf = runtime_hipotecas_pdf.build_hipoteca_ficha_pdf
