def seguros_sync_activation_action(conn, seguro_row, now):
    if not seguro_row:
        return
    seguro_id = str(seguro_row["id"] or "").strip()
    if not seguro_id:
        return
    empresa_id = str(seguro_row["empresa_id"] or "").strip()
    cliente_id = str(seguro_row["cliente_id"] or "").strip() or None
    fecha_efecto = str(seguro_row["fecha_efecto"] or "").strip()
    efecto_dt = parse_iso_date(fecha_efecto)
    estado_key = normalize_lookup_text(seguro_row["estado"] or "")
    in_vigor = any(token in estado_key for token in ("EN VIGOR", "VIGENTE", "ACTIVA", "ACTIVO"))
    existing = conn.execute(
        """
        SELECT id, estado
        FROM acciones
        WHERE servicio = 'Seguros'
          AND tipo = 'Activar póliza'
          AND notas LIKE ?
        LIMIT 1
        """,
        (f"%{seguro_id}%",),
    ).fetchone()
    today = datetime.now(timezone.utc).date()
    if now:
        try:
            now_dt = datetime.fromisoformat(str(now).replace("Z", "+00:00"))
            today = now_dt.date()
        except Exception:
            pass
    should_be_pending = (
        bool(efecto_dt)
        and efecto_dt > today
        and not in_vigor
    )
    if should_be_pending:
        notas = f"Activar póliza por entrada en vigor ({seguro_row['poliza_numero'] or 'sin número'}). Poliza ID: {seguro_id}"
        if existing:
            conn.execute(
                """
                UPDATE acciones
                SET empresa_id = ?, cliente_id = ?, cliente_nombre = ?, fecha = ?, tipo = 'Activar póliza',
                    estado = 'Pendiente', notas = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    empresa_id,
                    cliente_id,
                    seguro_row["tomador"] or "",
                    fecha_efecto,
                    notas,
                    now,
                    existing["id"],
                ),
            )
            return
        conn.execute(
            """
            INSERT INTO acciones (
              id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
              fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                "Seguros",
                cliente_id,
                None,
                seguro_row["tomador"] or "",
                fecha_efecto,
                None,
                "Activar póliza",
                None,
                "Pendiente",
                notas,
                None,
                now,
                now,
            ),
        )
        return
    if existing:
        conn.execute(
            "UPDATE acciones SET estado = 'Hecho', updated_at = datetime(?) WHERE id = ?",
            (now, existing["id"]),
        )

def normalize_header(value):
    return re.sub(r"[^a-z0-9]", "", str(value or "").lower())

def load_postal_catalog(conn):
    if not POSTAL_CATALOG_PATH.exists():
        return
    count_row = conn.execute("SELECT COUNT(*) AS total FROM postal_catalogo").fetchone()
    total = 0
    if count_row:
        try:
            total = count_row["total"]
        except (TypeError, KeyError, IndexError):
            total = count_row[0]
    if total:
        return
    encodings = ("utf-8-sig", "latin-1")
    for encoding in encodings:
        try:
            with POSTAL_CATALOG_PATH.open("r", encoding=encoding, newline="") as handle:
                reader = csv.DictReader(handle)
                if not reader.fieldnames:
                    return
                headers = {normalize_header(name): name for name in reader.fieldnames}
                cp_key = next(
                    (headers[k] for k in headers if k in ("codigopostal", "codigo_postal", "postalcode", "cp", "codigo")),
                    None,
                )
                pob_key = next(
                    (headers[k] for k in headers if k in ("poblacion", "municipio", "municipionombre", "localidad", "ciudad", "nombre")),
                    None,
                )
                prov_key = next(
                    (headers[k] for k in headers if k in ("provincia", "provincianombre", "province")),
                    None,
                )
                if not cp_key:
                    return
                batch = []
                seen = set()
                for row in reader:
                    cp_raw = row.get(cp_key, "")
                    cp = normalize_postal_code(cp_raw)
                    if not cp:
                        continue
                    poblacion = (row.get(pob_key, "") if pob_key else "") or ""
                    poblacion = str(poblacion).strip()
                    provincia = (row.get(prov_key, "") if prov_key else "") or ""
                    provincia = str(provincia).strip()
                    if not provincia:
                        provincia = POSTAL_PROVINCES.get(cp[:2], "")
                    key = (cp, poblacion, provincia)
                    if key in seen:
                        continue
                    seen.add(key)
                    batch.append(key)
                    if len(batch) >= 5000:
                        conn.executemany(
                            "INSERT INTO postal_catalogo (codigo_postal, poblacion, provincia) VALUES (?, ?, ?)",
                            batch,
                        )
                        batch = []
                if batch:
                    conn.executemany(
                        "INSERT INTO postal_catalogo (codigo_postal, poblacion, provincia) VALUES (?, ?, ?)",
                        batch,
                    )
            return
        except UnicodeDecodeError:
            continue


# --- Simuladores fiscales (IIVTNU / plusvalía municipal) ---

_IIVTNU_POSTAL_CACHE_LOCK = threading.Lock()
_IIVTNU_POSTAL_CACHE = None  # {"cp_to": {cp: ine}, "ine_to": {ine: name}, "prov_to": {ine: provincia}}
_IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE = None  # contents of `data/catalogos/iivtnu_tipo_gravamen_malaga.min.json`
_IIVTNU_TIPO_GRAVAMEN_ANDALUCIA_CACHE = None  # contents of `data/catalogos/iivtnu_tipo_gravamen_andalucia.min.json`
_IIVTNU_TIPO_GRAVAMEN_CAPITALES_CACHE = None  # contents of `data/catalogos/iivtnu_tipo_gravamen_capitales.min.json`
_IIVTNU_PARAMS_SPAIN_HACIENDA_EXCEL2022_CACHE = None  # contents of `data/catalogos/iivtnu_params_spain_hacienda_excel2022.min.json`
_IIVTNU_INE_MUNICIPIOS_CACHE_LOCK = threading.Lock()
_IIVTNU_INE_MUNICIPIOS_CACHE = None  # {"ine_to":{}, "prov_to":{}, "nameprov_to":{}}


def ensure_iivtnu_schema(conn):
    if not conn:
        return
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS iivtnu_municipios (
          ine TEXT PRIMARY KEY,
          nombre TEXT NOT NULL,
          provincia TEXT,
          comunidad TEXT,
          es_capital INTEGER DEFAULT 0,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS iivtnu_param_sets (
          id TEXT PRIMARY KEY,
          municipio_ine TEXT NOT NULL,
          vigente_desde TEXT,
          vigente_hasta TEXT,
          tipo_gravamen_pct REAL,
          coeficientes_json TEXT,
          bonificaciones_json TEXT,
          source_url TEXT,
          source_label TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (municipio_ine) REFERENCES iivtnu_municipios(ine)
        );
        """
    )
    conn.execute("CREATE INDEX IF NOT EXISTS idx_iivtnu_param_sets_municipio ON iivtnu_param_sets(municipio_ine);")
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_iivtnu_param_sets_vigencia ON iivtnu_param_sets(municipio_ine, vigente_desde, vigente_hasta);"
    )


def _iivtnu_norm_text(value):
    raw = str(value or "").strip().lower()
    if not raw:
        return ""
    raw = unicodedata.normalize("NFD", raw)
    raw = "".join(ch for ch in raw if unicodedata.category(ch) != "Mn")
    raw = raw.replace("’", "").replace("'", "")
    raw = raw.replace("-", " ")
    raw = re.sub(r"\s+", " ", raw)
    return raw.strip()


def _iivtnu_postal_variants(nombre):
    raw = str(nombre or "").strip()
    if not raw:
        return []
    out = [raw]
    if "," in raw:
        base, art = [p.strip() for p in raw.split(",", 1)]
        if _iivtnu_norm_text(art) in {"el", "la", "los", "las"}:
            out.append(f"{art} {base}".strip())
            out.append(f"{base} ({art})".strip())
    return out


def _iivtnu_load_postal_cache():
    global _IIVTNU_POSTAL_CACHE
    if _IIVTNU_POSTAL_CACHE is not None:
        return _IIVTNU_POSTAL_CACHE
    with _IIVTNU_POSTAL_CACHE_LOCK:
        if _IIVTNU_POSTAL_CACHE is not None:
            return _IIVTNU_POSTAL_CACHE
        cache = {"cp_to": {}, "ine_to": {}, "prov_to": {}}
        if POSTAL_CATALOG_PATH.exists():
            encodings = ("utf-8-sig", "utf-8", "latin-1")
            for encoding in encodings:
                try:
                    with POSTAL_CATALOG_PATH.open("r", encoding=encoding, newline="") as handle:
                        reader = csv.DictReader(handle)
                        if not reader.fieldnames:
                            break
                        headers = {normalize_header(name): name for name in reader.fieldnames}
                        cp_key = next(
                            (headers[k] for k in headers if k in ("codigopostal", "codigo_postal", "postalcode", "cp", "codigo")),
                            None,
                        )
                        ine_key = next(
                            (headers[k] for k in headers if k in ("municipioid", "municipio_id", "ine", "ineid", "idmunicipio")),
                            None,
                        )
                        nombre_key = next(
                            (
                                headers[k]
                                for k in headers
                                if k in ("municipionombre", "municipio_nombre", "municipio", "poblacion", "localidad", "ciudad", "nombre")
                            ),
                            None,
                        )
                        if not cp_key or not ine_key:
                            break
                        for row in reader:
                            cp = normalize_postal_code(row.get(cp_key, ""))
                            ine = str(row.get(ine_key, "") or "").strip()
                            if not cp or not ine:
                                continue
                            ine = ine.zfill(5)
                            cache["cp_to"][cp] = ine
                            nombre = str(row.get(nombre_key, "") if nombre_key else "").strip()
                            if nombre and ine not in cache["ine_to"]:
                                cache["ine_to"][ine] = nombre
                                cache["prov_to"][ine] = POSTAL_PROVINCES.get(cp[:2], "")
                    break
                except UnicodeDecodeError:
                    continue
        _IIVTNU_POSTAL_CACHE = cache
        return _IIVTNU_POSTAL_CACHE


def _iivtnu_load_tipo_gravamen_malaga():
    global _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE
    if _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE is not None:
        return _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE
    try:
        if not IIVTNU_TIPO_GRAVAMEN_MALAGA_PATH.exists():
            _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE = {}
            return _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE
        data = json.loads(IIVTNU_TIPO_GRAVAMEN_MALAGA_PATH.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            data = {}
    except Exception:
        data = {}
    _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE = data
    return _IIVTNU_TIPO_GRAVAMEN_MALAGA_CACHE


def _iivtnu_load_ine_municipios_cache():
    global _IIVTNU_INE_MUNICIPIOS_CACHE
    if _IIVTNU_INE_MUNICIPIOS_CACHE is not None:
        return _IIVTNU_INE_MUNICIPIOS_CACHE
    with _IIVTNU_INE_MUNICIPIOS_CACHE_LOCK:
        if _IIVTNU_INE_MUNICIPIOS_CACHE is not None:
            return _IIVTNU_INE_MUNICIPIOS_CACHE
        cache = {"ine_to": {}, "prov_to": {}, "nameprov_to": {}}
        try:
            if not INE_MUNICIPIOS_2026_PATH.exists():
                _IIVTNU_INE_MUNICIPIOS_CACHE = cache
                return _IIVTNU_INE_MUNICIPIOS_CACHE
            with INE_MUNICIPIOS_2026_PATH.open("r", encoding="utf-8", newline="") as handle:
                reader = csv.DictReader(handle)
                for row in reader:
                    ine = str(row.get("municipio_id") or "").strip().zfill(5)
                    nombre = str(row.get("nombre") or "").strip()
                    provincia = str(row.get("provincia_nombre") or row.get("provincia") or "").strip()
                    if not ine or not nombre:
                        continue
                    if not provincia:
                        prov_id = str(row.get("provincia_id") or "").strip().zfill(2)
                        provincia = POSTAL_PROVINCES.get(prov_id, "") if prov_id else ""
                    cache["ine_to"][ine] = nombre
                    cache["prov_to"][ine] = provincia or ""
                    key = (_iivtnu_norm_text(nombre), _iivtnu_norm_text(provincia))
                    if key[0] and key[1] and key not in cache["nameprov_to"]:
                        cache["nameprov_to"][key] = ine
                    # Variantes “Apellido, Artículo” → “Artículo Apellido”.
                    for v in _iivtnu_postal_variants(nombre):
                        k2 = (_iivtnu_norm_text(v), _iivtnu_norm_text(provincia))
                        if k2[0] and k2[1] and k2 not in cache["nameprov_to"]:
                            cache["nameprov_to"][k2] = ine
        except Exception:
            pass
        _IIVTNU_INE_MUNICIPIOS_CACHE = cache
        return _IIVTNU_INE_MUNICIPIOS_CACHE


