def _iivtnu_coef_table_from_list(coefs_list):
    if not isinstance(coefs_list, list) or len(coefs_list) != 21:
        return None
    keys = ["lt1"] + [str(i) for i in range(1, 20)] + ["20+"]
    out = {}
    for k, raw in zip(keys, coefs_list):
        try:
            v = float(raw)
        except Exception:
            v = 0.0
        if v < 0 or v > 1:
            v = 0.0
        out[k] = float(v)
    return out


