def _iivtnu_seed_spain_municipios(conn, now_iso=None, min_count=8000):
    if not conn:
        return
    now_iso = str(now_iso or datetime.now(timezone.utc).isoformat())
    try:
        ensure_iivtnu_schema(conn)
    except Exception:
        return
    # Si no existe la tabla aún (DB legacy sin schema), aborta.
    try:
        conn.execute("SELECT 1 FROM iivtnu_municipios LIMIT 1").fetchone()
    except Exception:
        return
    try:
        row = conn.execute("SELECT COUNT(1) FROM iivtnu_municipios").fetchone()
        current = int((row[0] if row else 0) or 0)
    except Exception:
        current = 0
    if current >= int(min_count or 0):
        return

    ine_cache = _iivtnu_load_ine_municipios_cache()
    ine_to = ine_cache.get("ine_to") or {}
    prov_to = ine_cache.get("prov_to") or {}
    for ine, nombre in sorted(ine_to.items()):
        ine = str(ine).zfill(5)
        provincia = str(prov_to.get(ine) or "").strip()
        comunidad = _iivtnu_provincia_to_comunidad(provincia)
        es_capital = 1 if _iivtnu_norm_text(nombre) and _iivtnu_norm_text(nombre) == _iivtnu_norm_text(provincia) else 0
        try:
            conn.execute(
                """
                INSERT INTO iivtnu_municipios (ine, nombre, provincia, comunidad, es_capital, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (ine, str(nombre), provincia, comunidad, es_capital, now_iso, now_iso),
            )
        except Exception:
            pass


def _iivtnu_is_andalucia_province(value: object) -> bool:
    prov = _iivtnu_norm_text(value)
    if not prov:
        return False
    return prov in _IIVTNU_ANDALUCIA_PROVINCES_NORM


def _iivtnu_seed_andalucia(conn, now_iso=None):
    if not conn:
        return
    now_iso = str(now_iso or datetime.now(timezone.utc).isoformat())
    try:
        ensure_iivtnu_schema(conn)
    except Exception:
        return
    # Si no existe la tabla aún (DB legacy sin schema), aborta.
    try:
        conn.execute("SELECT 1 FROM iivtnu_municipios LIMIT 1").fetchone()
    except Exception:
        return
    try:
        existing = conn.execute("SELECT 1 FROM iivtnu_municipios WHERE comunidad = 'Andalucía' LIMIT 1").fetchone()
    except Exception:
        existing = None
    if existing:
        return

    ine_cache = _iivtnu_load_ine_municipios_cache()
    ine_to = ine_cache.get("ine_to") or {}
    prov_to = ine_cache.get("prov_to") or {}
    for ine, nombre in sorted(ine_to.items()):
        provincia = prov_to.get(str(ine).zfill(5)) or ""
        if not _iivtnu_is_andalucia_province(provincia):
            continue
        es_capital = 1 if _iivtnu_norm_text(nombre) == _iivtnu_norm_text(provincia) else 0
        try:
            conn.execute(
                """
                INSERT INTO iivtnu_municipios (ine, nombre, provincia, comunidad, es_capital, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (str(ine).zfill(5), str(nombre), str(provincia), "Andalucía", es_capital, now_iso, now_iso),
            )
        except Exception:
            pass


def _iivtnu_parse_uploaded_pdf(body, content_type=""):
    ctype = str(content_type or "").strip()
    if "multipart/form-data" not in ctype.lower():
        raise ValueError("Content-Type debe ser multipart/form-data")
    import email.policy  # lazy import: `email.policy` no existe hasta importar

    envelope = f"Content-Type: {ctype}\r\nMIME-Version: 1.0\r\n\r\n".encode("utf-8", "ignore") + (body or b"")
    msg = email.message_from_bytes(envelope, policy=email.policy.default)
    file_bytes = None
    filename = ""
    for part in msg.walk():
        if part.is_multipart():
            continue
        cd = str(part.get("Content-Disposition") or "")
        if "form-data" not in cd.lower():
            continue
        if "name=\"file\"" not in cd and "name=file" not in cd:
            continue
        filename = str(part.get_filename() or "").strip()
        file_bytes = part.get_payload(decode=True)
        break
    if not file_bytes:
        raise ValueError("No se encontró el campo file")
    return _iivtnu_extract_from_pdf(file_bytes, filename=filename)


def parse_multipart_form_data(body, content_type=""):
    ctype = str(content_type or "").strip()
    if "multipart/form-data" not in ctype.lower():
        raise ValueError("Content-Type debe ser multipart/form-data")
    import email.policy

    envelope = f"Content-Type: {ctype}\r\nMIME-Version: 1.0\r\n\r\n".encode("utf-8", "ignore") + (body or b"")
    msg = email.message_from_bytes(envelope, policy=email.policy.default)
    fields = {}
    files = []
    for part in msg.walk():
        if part.is_multipart():
            continue
        cd = str(part.get("Content-Disposition") or "")
        if "form-data" not in cd.lower():
            continue
        name = str(part.get_param("name", header="Content-Disposition") or "").strip()
        filename = str(part.get_filename() or "").strip()
        payload = part.get_payload(decode=True) or b""
        if filename:
            files.append(
                {
                    "field": name,
                    "filename": filename,
                    "content_type": str(part.get_content_type() or ""),
                    "bytes": payload,
                }
            )
        elif name:
            fields[name] = payload.decode("utf-8", "ignore").strip()
    return fields, files


def safe_extract_invoice_uploads(files, target_dir: Path) -> tuple[int, list[str]]:
    import zipfile
    import hashlib

    allowed = {".pdf", ".png", ".jpg", ".jpeg"}
    target_dir.mkdir(parents=True, exist_ok=True)
    saved = 0
    skipped = []
    seen_hashes = set()

    def safe_name(value):
        raw = str(value or "documento").replace("\\", "/").split("/")[-1].strip()
        raw = re.sub(r"[^A-Za-z0-9._() áéíóúÁÉÍÓÚñÑ-]+", "_", raw)
        return raw[:180] or "documento"

    def unique_path(base_dir: Path, filename: str) -> Path:
        name = safe_name(filename)
        candidate = base_dir / name
        if not candidate.exists():
            return candidate
        stem = candidate.stem
        suffix = candidate.suffix
        for idx in range(2, 10000):
            candidate = base_dir / f"{stem} ({idx}){suffix}"
            if not candidate.exists():
                return candidate
        return base_dir / f"{stem}-{os.urandom(4).hex()}{suffix}"

    def register_blob(blob: bytes, label: str) -> bool:
        digest = hashlib.sha256(blob or b"").hexdigest()
        if digest in seen_hashes:
            skipped.append(f"{label} (duplicado)")
            return False
        seen_hashes.add(digest)
        return True

    for item in files or []:
        filename = str(item.get("filename") or "").strip()
        payload = item.get("bytes") or b""
        suffix = Path(filename).suffix.lower()
        if not payload:
            continue
        if suffix == ".zip":
            try:
                with zipfile.ZipFile(BytesIO(payload)) as zf:
                    for member in zf.infolist():
                        if member.is_dir():
                            continue
                        member_name = str(member.filename or "").replace("\\", "/")
                        parts = [part for part in member_name.split("/") if part not in {"", ".", ".."}]
                        if not parts or Path(parts[-1]).suffix.lower() not in allowed:
                            skipped.append(member_name)
                            continue
                        try:
                            member_payload = zf.read(member)
                        except Exception:
                            skipped.append(member_name)
                            continue
                        if not register_blob(member_payload, member_name):
                            continue
                        relative_parent = Path(*parts[:-1]) if len(parts) > 1 else Path()
                        dest_parent = (target_dir / relative_parent).resolve()
                        if target_dir.resolve() not in dest_parent.parents and dest_parent != target_dir.resolve():
                            skipped.append(member_name)
                            continue
                        dest_parent.mkdir(parents=True, exist_ok=True)
                        dest = unique_path(dest_parent, parts[-1])
                        dest.write_bytes(member_payload)
                        saved += 1
            except Exception as exc:
                skipped.append(f"{filename}: {type(exc).__name__}")
            continue
        if suffix not in allowed:
            skipped.append(filename)
            continue
        if not register_blob(payload, filename):
            continue
        dest = unique_path(target_dir, filename)
        dest.write_bytes(payload)
        saved += 1
    return saved, skipped


def _iivtnu_detect_doc_type(text_upper: str) -> str:
    upper = str(text_upper or "").upper()
    # Evita falsos positivos (p.ej. cartas de pago de otros tributos con NRC).
    is_iivtnu_context = any(
        token in upper
        for token in (
            "INCREMENTO DEL VALOR",
            "TERRENOS DE NATURALEZA URBANA",
            "NATURALEZA URBANA",
            "IIVTNU",
            "PLUSVALIA",
            "PLUSVALÍA",
            "GESTRISAM",
            "IMPOST INCREMENT VALOR TERRENYS",
        )
    ) or (
        "MODELO 004" in upper
        or "MOD. 004" in upper
        or "MOD.004" in upper
        or "MOD. 004-" in upper
        or bool(re.search(r"\bMODELO\b\s*[:\-]?\s*004\b", upper, flags=re.IGNORECASE | re.MULTILINE))
    )
    if "PROGRAMA DE AYUDA AL CÁLCULO" in upper or "PROGRAMA DE AYUDA AL CALCULO" in upper:
        return "simulacion_ayuda"
    if "ESTIMACIÓN DEL IMPORTE A PAGAR" in upper or "ESTIMACION DEL IMPORTE A PAGAR" in upper:
        return "simulacion_ayuda"
    if "GUÍA DE AUTOLIQUIDACIÓN" in upper or "GUIA DE AUTOLIQUIDACION" in upper:
        return "guia_autoliquidacion"
    if ("CARTA DE PAGO" in upper or "NRC" in upper) and is_iivtnu_context:
        return "carta_pago"
    if "DOCUMENTO DE PAGO" in upper and (
        "Nº DE LIQUIDACIÓN" in upper
        or "Nº DE LIQUIDACION" in upper
        or "REFERENCIA A.E.B." in upper
        or "CONCEPTO TRIBUTARIO" in upper
    ):
        return "carta_pago"
    if "SOLICITUD ESPECIFICA" in upper and ("INEXISTENCIA" in upper or "INCREMENTO" in upper):
        return "solicitud_inexistencia_incremento"
    if "AUTOLIQUIDACI" in upper and is_iivtnu_context:
        return "autoliquidacion"
    return ""


def _iivtnu_is_refcat_like(value: object) -> bool:
    v = str(value or "").strip().upper()
    if len(v) < 14 or len(v) > 20:
        return False
    if v.isalpha():
        return False
    digits = sum(1 for ch in v if ch.isdigit())
    if digits < 6:
        return False
    return True


def _iivtnu_pick_refcat(text_upper: str) -> str:
    upper = str(text_upper or "").upper()
    # Preferir siempre el campo etiquetado.
    m = re.search(
        r"REFERENCIA\s+CAT(?:ASTRAL)?\s*[:\-]?\s*([0-9A-Z]{14,20})",
        upper,
        flags=re.IGNORECASE | re.MULTILINE,
    )
    if m:
        cand = str(m.group(1) or "").strip().upper()
        if _iivtnu_is_refcat_like(cand):
            return cand

    try:
        candidates = re.findall(r"\b[0-9A-Z]{14,20}\b", upper, flags=re.IGNORECASE | re.MULTILINE)
    except Exception:
        candidates = []
    best = ""
    best_score = -1
    for cand in candidates:
        c = str(cand or "").strip().upper()
        if not _iivtnu_is_refcat_like(c):
            continue
        score = 0
        score += 2 * sum(1 for ch in c if ch.isdigit())
        score += 1 * sum(1 for ch in c if ch.isalpha())
        if any(ch.isalpha() for ch in c[4:12]):
            score += 10
        if score > best_score:
            best_score = score
            best = c
    return best


def _iivtnu_extract_from_text(text: str, filename: str = "") -> dict:
    clean = re.sub(r"[ \t]+", " ", text or "")
    clean = re.sub(r"\n{2,}", "\n", clean).strip()
    upper = clean.upper()

    MONEY_RE = r"([0-9]+(?:\.[0-9]{3})*,[0-9]{1,2})"

    def pick_first(patterns, text_in):
        for pat in patterns:
            m = re.search(pat, text_in, flags=re.IGNORECASE | re.MULTILINE)
            if m:
                return str(m.group(1) or "").strip()
        return ""

    def pick_number(patterns, text_in):
        raw = pick_first(patterns, text_in)
        if not raw:
            return None
        # OCR/PDF: a veces viene decimal con punto (p.ej. 21.5) y `parse_optional_float`
        # lo interpreta como miles. Normalizamos a coma decimal en ese caso.
        raw_norm = str(raw or "").strip()
        if "." in raw_norm and "," not in raw_norm:
            if re.match(r"^\d+\.\d{1,2}$", raw_norm):
                raw_norm = raw_norm.replace(".", ",")
        return parse_optional_float(raw_norm)

    def pick_date_near(patterns, text_in, window=160):
        for pat in patterns:
            m = re.search(pat, text_in, flags=re.IGNORECASE | re.MULTILINE)
            if not m:
                continue
            chunk = text_in[m.end() : m.end() + window]
            dm = re.search(r"([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})", chunk, flags=re.IGNORECASE | re.MULTILINE)
            if dm:
                return str(dm.group(1) or "").strip()
        return ""

    def pick_value_after_label(label_regex, min_value=0.0, max_hits=6, window=360, strategy="mode"):
        try:
            hits = list(re.finditer(label_regex, upper, flags=re.IGNORECASE | re.MULTILINE))
        except Exception:
            hits = []
        candidates = []
        for m in hits[:max_hits]:
            chunk = upper[m.end() : m.end() + window]
            try:
                nums = re.findall(MONEY_RE, chunk, flags=re.IGNORECASE | re.MULTILINE)
            except Exception:
                nums = []
            for raw in nums[:12]:
                val = parse_optional_float(raw or "")
                if val is None:
                    continue
                try:
                    fv = float(val)
                except Exception:
                    continue
                if fv >= float(min_value or 0.0):
                    candidates.append(fv)
        if not candidates:
            return None
        strat = str(strategy or "mode").strip().lower()
        if strat in ("first", "first_above_min", "first_match"):
            try:
                return float(candidates[0])
            except Exception:
                return None
        if strat in ("last", "last_match"):
            try:
                return float(candidates[-1])
            except Exception:
                return None
        if strat in ("max", "largest", "highest"):
            try:
                return float(max(candidates))
            except Exception:
                return None
        if strat in ("min", "smallest", "lowest"):
            try:
                return float(min(candidates))
            except Exception:
                return None
        try:
            from collections import Counter

            return float(Counter(round(v, 2) for v in candidates).most_common(1)[0][0])
        except Exception:
            try:
                return float(max(candidates))
            except Exception:
                return None

    doc_type = _iivtnu_detect_doc_type(upper)
    municipio = pick_first(
        [
            r"AYUNTAMIENTO\s+DE\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s\.\-]{2,40}?)(?:\s+(?:DISPONE|ORGANISMO|GESTI|SERVICIO|NIF|CIF|AREA|ÁREA)\b|$)",
            r"AYUNTAMIENTO\s+DE\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s\.\-]{2,40})",
            r"AJUNTAMENT\s+DE\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s\.\-]{2,40}?)(?:\s+(?:EXEMPLAR|CONTRIBUENT|ORGANISME|NIF|CIF)\b|$)",
            r"AJUNTAMENT\s+DE\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s\.\-]{2,40})",
        ],
        upper,
    )
    municipio = municipio.title().strip() if municipio else ""
    if municipio and " Exemplar" in municipio:
        municipio = municipio.split(" Exemplar", 1)[0].strip()

    cp_norm = ""
    # Evita capturar trozos de importes (p.ej. 18190,74) como código postal.
    try:
        cp_candidates = []
        for m in re.finditer(r"\b([0-9]{5})\b", clean or ""):
            cp = str(m.group(1) or "")
            if not cp:
                continue
            tail = (clean or "")[m.end() : m.end() + 3]
            # Si el token continúa como decimal monetario (',74' o '.74'), lo descartamos.
            if tail and tail[0] in (",", ".") and len(tail) >= 3 and tail[1:3].isdigit():
                continue
            cp_candidates.append(cp)
    except Exception:
        cp_candidates = []
    if cp_candidates:
        try:
            postal = _iivtnu_load_postal_cache()
            known = set((postal.get("cp_to") or {}).keys())
            valid = [c for c in cp_candidates if c in known]
            prefer = [c for c in valid if str(c).startswith("29")]
            cp_norm = prefer[0] if prefer else (valid[0] if valid else cp_candidates[0])
        except Exception:
            cp_norm = cp_candidates[0]
    cp_norm = normalize_postal_code(cp_norm)

    refcat = _iivtnu_pick_refcat(upper)

    fecha_adq_raw = pick_first(
        [
            r"FECHA\s+ADQUISIC(?:IÓ|IO)N\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"ADQUISIC(?:IÓ|IO)N\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})\s{0,40}FECHA\s+TRANSMISI(?:Ó|O)N\s+ANTERIOR",
            r"F\.?\s*TRANS\.?\s*ANT\.?\s*(?:\(%\))?\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
        ],
        upper,
    )
    fecha_tx_raw = pick_first(
        [
            r"FECHA\s+TRANSMISI(?:Ó|O)N\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"TRANSMISI(?:Ó|O)N\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"DEVENGO\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"FECHA\s+TRANSMISI(?:Ó|O)N\s+EFECTIVA\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"TRANSMISI(?:Ó|O)N\s+ACTUAL[\s\S]{0,240}?\b(?:COMPRAVENTA|COMPRA[\-\s]*VENTA|DONACI(?:Ó|O)N|HERENCIA|EXPROPIACI(?:Ó|O)N|PERMUTA|AUTO|ADJUDICACI(?:Ó|O)N)\b\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"FECHA\s+DOCUMENTO\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            r"([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})\s{0,40}FECHA\s+TRANSMISI(?:Ó|O)N\s+ACTUAL",
            r"D\.?\s*MERITACI(?:Ó|O)\s*(?:ACTUAL)?\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
        ],
        upper,
    )
    if not fecha_adq_raw:
        fecha_adq_raw = pick_first(
            [
                r"F\.\s*ADQUIS\.\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
                r"FECHA\s+ADQ\.\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})",
            ],
            upper,
        )
    # OCR: la etiqueta puede existir pero la fecha va en otra celda (líneas posteriores).
    if not fecha_tx_raw:
        fecha_tx_raw = pick_date_near(
            [r"FECHA\s+DOCUMENTO", r"FECHA\s+REGISTRO", r"FECHA\s+TRANSMISI(?:Ó|O)N", r"DEVENGO"],
            upper,
        )
    if not fecha_adq_raw:
        fecha_adq_raw = pick_date_near([r"FECHA\s+ADQUISIC(?:IÓ|IO)N", r"ADQUISIC(?:IÓ|IO)N"], upper)
    fecha_adq_dt = parse_iso_date(fecha_adq_raw)
    fecha_tx_dt = parse_iso_date(fecha_tx_raw)
    # Heurística: si no se detecta adquisición, suele aparecer en una tabla sin etiqueta clara.
    # Elegimos la fecha más antigua < devengo.
    if not fecha_adq_dt and fecha_tx_dt:
        try:
            candidates = re.findall(r"\b([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})\b", clean or "")
        except Exception:
            candidates = []
        dt_candidates = []
        for raw in candidates:
            d = parse_iso_date(raw)
            if not d:
                continue
            if d < fecha_tx_dt:
                dt_candidates.append(d)
        if dt_candidates:
            fecha_adq_dt = min(dt_candidates)
    fecha_adq = fecha_adq_dt.isoformat() if fecha_adq_dt else ""
    fecha_tx = fecha_tx_dt.isoformat() if fecha_tx_dt else ""

    valor_suelo = pick_number(
        [
            r"VALOR\s+CAT(?:ASTRAL)?\s+DEL\s+SUELO\s*[:\-]?\s*([0-9\.,]+)",
            r"V\.?\s*C\.?\s*SUELO\s*[:\-]?\s*([0-9\.,]+)",
            r"V\.?\s*SUEL[OA]\s*[:\-]?\s*([0-9\.,]+)",
            r"\bVC\s+S[OÒ]L\s*[:\-]?\s*([0-9\.,]+)",
            # Preferir importes con coma decimal (evita capturar FINCA REGISTRAL / IDs).
            rf"VALOR\s+SUELO\s*[:\-]?\s*{MONEY_RE}",
            rf"{MONEY_RE}[ \t]{{0,40}}VALOR\s+SUELO\b",
            r"VALOR\s+SUELO\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    # OCR/tabla: escoger el primer importe tras "VALOR SUELO" (evita % e IDs). Si existe VC total, filtra.
    vc_for_filter = None
    valor_suelo_reducido = pick_number(
        [
            r"VALOR\s+REDUCIDO\s*\(?A\)?\s*[:\-]?\s*([0-9\.,]+)",
            r"VALOR\s+REDUCIDO\s*[:\-]?\s*([0-9\.,]+)",
            r"\(A\)\s*[:\-]?\s*([0-9\.,]+)\s{0,40}VALOR\s+REDUCIDO",
        ],
        upper,
    )
    # OCR: evitar confundir IDs (p.ej. finca registral) con un valor monetario reducido.
    if valor_suelo_reducido is not None:
        try:
            v = float(valor_suelo_reducido)
        except Exception:
            v = None
        if v is not None and v >= 10000 and abs(v - int(v)) < 1e-9:
            valor_suelo_reducido = None
    coef_reduccion = pick_number(
        [
            r"COEF(?:ICIENTE)?\s*(?:DE\s*)?REDUCCI(?:Ó|O)N\s*[:\-]?\s*([0-9\.,]+)",
            r"COEF\.?\s*REDUCCI(?:Ó|O)N\s*[:\-]?\s*([0-9\.,]+)",
            r"([0-9\.,]+)\s{0,40}COEF(?:ICIENTE)?\s+REDUCCI(?:Ó|O)N",
        ],
        upper,
    )
    valor_catastral_total = pick_number(
        [
            r"VALOR\s+CAT(?:ASTRAL)?\s+TOTAL\s*[:\-]?\s*([0-9\.,]+)",
            r"V\.?\s*C\.?\s*TOTAL\s*[:\-]?\s*([0-9\.,]+)",
            r"VALOR\s+CAT(?:ASTRAL)?\s*(?!DEL\s+SUELO)(?!DEL\s+SOLAR)\s*\(TOTAL\)\s*[:\-]?\s*([0-9\.,]+)",
            r"V\.?\s*CAT(?:ASTRAL)?\s*[:\-]?\s*([0-9\.,]+)",
            r"\bVC\s+S[OÒ]L\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    vc_hint = pick_value_after_label(
        r"(?:^|\n)\s*(?:A\s*\|\s*)?VALOR\s+CATASTRAL\b",
        min_value=500.0,
        max_hits=6,
        window=420,
        strategy="first",
    )
    if vc_hint is not None:
        if valor_catastral_total is None:
            valor_catastral_total = vc_hint
        else:
            try:
                current = float(valor_catastral_total or 0.0)
            except Exception:
                current = 0.0
            if vc_hint >= 1000 and (current <= 0 or abs(vc_hint - current) > max(1.0, current * 0.15)):
                valor_catastral_total = vc_hint
    if valor_catastral_total is not None:
        try:
            vc_for_filter = float(valor_catastral_total)
        except Exception:
            vc_for_filter = None

    suelo_hint = pick_value_after_label(
        r"(?:^|\n)\s*(?:B\s*\|\s*)?VALOR\s+SUELO\b",
        min_value=500.0,
        max_hits=8,
        window=420,
        strategy="first",
    )
    if suelo_hint is None:
        suelo_hint = pick_value_after_label(
            r"VALOR\s+SUELO\b(?!\s+(?:REDUCIDO|SOBRE))",
            min_value=500.0,
            max_hits=10,
            window=420,
        )
    if suelo_hint is not None and vc_for_filter:
        if suelo_hint > vc_for_filter * 1.05:
            suelo_hint = None
    if suelo_hint is not None:
        if valor_suelo is None:
            valor_suelo = suelo_hint
        else:
            try:
                current = float(valor_suelo or 0.0)
            except Exception:
                current = 0.0
            if suelo_hint >= 1000 and (current <= 0 or abs(suelo_hint - current) > max(1.0, current * 0.15)):
                valor_suelo = suelo_hint
    # Si no hay coeficiente y el valor reducido es idéntico al suelo, no lo consideramos "reducido".
    if coef_reduccion is None and valor_suelo is not None and valor_suelo_reducido is not None:
        try:
            vs = float(valor_suelo or 0.0)
            vr = float(valor_suelo_reducido or 0.0)
        except Exception:
            vs = None
            vr = None
        if vs is not None and vr is not None and vs > 0:
            if abs(vs - vr) <= max(0.01, vs * 0.0001):
                valor_suelo_reducido = None
    participacion_pct = pick_number(
        [
            r"([0-9\.,]+)\s*%+\s*%PARTICIPACI(?:Ó|O)N",
            r"%\s*PARTICIPACI(?:Ó|O)N\s*[:\-]?\s*([0-9\.,]+)",
            r"PARTICIPACI(?:Ó|O)N\s*%\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    porcentaje_suelo = pick_number(
        [
            r"%\s*VALOR\s+SUELO\s+SOBRE\s+VALOR\s+CATASTRAL\s*\(B/A\)\s*[:\-]?\s*([0-9\.,]+)",
            r"\(B/A\)\s*[:\-]?\s*([0-9\.,]+)\s*$",
            r"PROP\.?\s*%+\s*[:\-]?\s*([0-9\.,]+)",
            r"PROPIEDAD\s*%+\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    base_imponible = pick_number(
        [
            rf"BASE\s+IMPONIBLE\s*[:\-]?\s*{MONEY_RE}",
            r"BASE\s+IMPONIBLE\s*[:\-]?\s*([0-9\.,]+)",
            r"BI[\-\s]*M[ÉE]T\.?\s*OBJ\s*[:\-]?\s*([0-9\.,]+)",
            r"BI[\-\s]*M[ÉE]T\.?\s*OBJ\.\s*[:\-]?\s*([0-9\.,]+)",
            r"\bB\.?\s*IMPOSABLE\b\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    if base_imponible is not None:
        try:
            bi_val = float(base_imponible)
        except Exception:
            bi_val = None
        if bi_val is not None and bi_val < 10:
            bi_hint = pick_value_after_label(
                r"(?:^|\n)\s*BASE\s+IMPONIBLE\b",
                min_value=10.0,
                max_hits=10,
                window=420,
                strategy="first",
            )
            if bi_hint is not None and bi_hint > bi_val * 2:
                base_imponible = bi_hint
    tipo_gravamen_pct = pick_number(
        [
            r"TIPO\s+DE\s+GRAVAMEN\s*\(?%\)?\s*[:\-]?\s*([0-9\.,]+)",
            r"TIPO\s+IMPOSITIVO\s*\(?%\)?\s*[:\-]?\s*([0-9\.,]+)",
            r"([0-9\.,]+)\s{0,40}TIPO\s+DE\s+GRAVAMEN",
            r"TIPO\s*%+\s*[:\-]?\s*([0-9\.,]+)",
            r"TIPO\s+GRAVAMEN\s*[:\-]?\s*([0-9\.,]+)",
            r"TIPO\s+GRAVAMEN\s*\(?%\)?\s*[:\-]?\s*([0-9\.,]+)",
            r"\bTIPUS\s*%+\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    cuota = pick_number(
        [
            r"CUOTA\s+(?:TRIBUTARIA|(?:I|Í)NTEGRA)\s*[:\-]?\s*([0-9\.,]+)",
            r"CUOTA\s*[:\-]?\s*([0-9\.,]+)",
            r"([0-9\.,]+)[ \t]{0,40}CUOTA\s+TRIBUTARIA",
            r"CUOTA\s+(?:I|Í)NTEGRA\s*[:\-]?\s*([0-9\.,]+)",
            # Catalán (Palma): evita capturar la fecha de la fila de tabla (QUOTA INT \n 06/06/2016 ...).
            r"\bQUOTA\s+INT\b\s*(?:T\s*)?[:\-]\s*([0-9\.,]+)",
            r"\bQUOTA\s+INT\s+T\b\s*[:\-]\s*([0-9\.,]+)",
        ],
        upper,
    )
    bonificacion_pct = pick_number(
        [
            # Importante: evitar capturar el importe de cuota/total cuando el PDF muestra “Bonificación %” sin valor.
            r"BONIFICACI(?:Ó|O)N\s*\(?%\)?\s*[:\-]?\s*([0-9\.,]+)",
            r"\bBON\.\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    bonificacion_importe = pick_number(
        [
            r"BONIFICACI(?:Ó|O)N\s*\(?IMPORTE\)?\s*[:\-]?\s*([0-9\.,]+)",
            r"IMPORTE\s+BONIFICACI(?:Ó|O)N\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    recargo_importe = pick_number(
        [
            r"RECARGO\s*[:\-]?\s*([0-9\.,]+)",
            r"IMPORTE\s+RECARGO\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    intereses_importe = pick_number(
        [
            r"INTERESES\s+(?:DE\s+DEMORA)?\s*[:\-]?\s*([0-9\.,]+)",
            r"IMPORTE\s+INTERESES\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    total = pick_number(
        [
            r"IMPORTE\s+TOTAL\s*[:\-]?\s*([0-9\.,]+)",
            r"TOTAL\s+A\s+INGRESAR\s*[:\-]?\s*([0-9\.,]+)",
            r"([0-9\.,]+)[ \t]{0,40}IMPORTE\s+TOTAL",
            r"\bQUOTA\s+LIQ\b\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    # Palma (Catalán): tabla en una línea con coeficiente, base, tipo y cuota; el header puede venir pegado (B.IMPOSABLETIPUS%).
    if (base_imponible is None or tipo_gravamen_pct is None) and ("QUOTA INT" in upper and "TIPUS" in upper):
        try:
            lines = [ln.strip() for ln in clean.splitlines() if str(ln or "").strip()]
        except Exception:
            lines = []
        def _parse_token(token: str):
            raw_tok = str(token or "").strip()
            if "." in raw_tok and "," not in raw_tok and re.match(r"^\d+\.\d{1,2}$", raw_tok):
                raw_tok = raw_tok.replace(".", ",")
            return parse_optional_float(raw_tok)

        for ln in lines:
            uln = ln.upper()
            if "PD" not in uln:
                continue
            if not re.search(r"\b[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}\b", uln):
                continue
            parts = ln.split()
            # ejemplo: 06/06/2016 100 PD 8A 0.19 3456,24 21.5 743,09
            coef_idx = None
            for i, tok in enumerate(parts):
                if not re.match(r"^[0-9]+[.,][0-9]+$", tok):
                    continue
                # coef suele ser <= 1
                val = _parse_token(tok)
                if val is None:
                    continue
                try:
                    fv = float(val)
                except Exception:
                    continue
                if 0 < fv <= 1.0:
                    coef_idx = i
                    break
            if coef_idx is None or coef_idx + 3 >= len(parts):
                continue
            base_tok = parts[coef_idx + 1]
            tipo_tok = parts[coef_idx + 2]
            cuota_tok = parts[coef_idx + 3]
            if base_imponible is None:
                base_imponible = _parse_token(base_tok)
            if tipo_gravamen_pct is None:
                tipo_gravamen_pct = _parse_token(tipo_tok)
            if cuota is None:
                cuota = _parse_token(cuota_tok)
            break
    # "Programa de ayuda" (Málaga) suele venir en formato tabla con cabeceras y una fila de importes.
    if doc_type == "simulacion_ayuda" and (
        base_imponible is None
        or tipo_gravamen_pct is None
        or cuota is None
        or total is None
        or (base_imponible is not None and total is not None and abs(float(base_imponible) - float(total)) < 1e-6)
    ):
        try:
            lines = [ln for ln in (clean or "").splitlines() if str(ln or "").strip()]
        except Exception:
            lines = []
        for idx, line in enumerate(lines):
            u = str(line or "").upper()
            if "BASE IMPONIBLE" not in u or "CUOTA" not in u or "IMPORTE TOTAL" not in u:
                continue
            if "TIPO" not in u:
                continue
            for j in range(idx + 1, min(idx + 6, len(lines))):
                cand = str(lines[j] or "").strip()
                if not cand:
                    continue
                nums = re.findall(MONEY_RE, cand.upper(), flags=re.IGNORECASE | re.MULTILINE)
                if len(nums) < 3:
                    continue
                vals = []
                for raw in nums[:4]:
                    v = parse_optional_float(raw)
                    if v is None:
                        continue
                    try:
                        vals.append(float(v))
                    except Exception:
                        continue
                if len(vals) < 3:
                    continue
                # Esperado: base, tipo, cuota, total
                if vals[0] <= 0:
                    continue
                base_imponible = vals[0]
                tipo_gravamen_pct = vals[1]
                cuota = vals[2]
                if len(vals) >= 4:
                    total = vals[3]
                else:
                    total = vals[2]
                break
            if tipo_gravamen_pct is not None and cuota is not None:
                break

    valor_transmision = pick_number(
        [
            r"V\.?\s*TRANSMIS(?:IÓ|IO)N\.?\s*[:\-]?\s*([0-9\.,]+)",
            r"V\.?\s*TRANSMIS\.?\s*[:\-]?\s*([0-9\.,]+)",
            r"VALOR\s+TRANSMISI(?:Ó|O)N\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    valor_adquisicion = pick_number(
        [
            r"V\.?\s*ADQUIS(?:ICIÓ|ICIO)N\.?\s*[:\-]?\s*([0-9\.,]+)",
            r"V\.?\s*ADQUIS\.?\s*[:\-]?\s*([0-9\.,]+)",
            r"VALOR\s+ADQUISIC(?:IÓ|IO)N\s*[:\-]?\s*([0-9\.,]+)",
        ],
        upper,
    )
    derecho_transmitido = pick_first([r"DCHO\.?\s*TRANSM\.?\s*[:\-]?\s*([A-ZÁÉÍÓÚÑ\s\-]{3,20})"], upper)
    clase_trans = pick_first([r"CLASE\s+TRANS\.?\s*[:\-]?\s*([A-ZÁÉÍÓÚÑ\-]+)"], upper)
    subdivision_pct = pick_number([r"SUBDIV\.?\s*[:\-]?\s*([0-9\.,]+)"], upper)
    utm = pick_first([r"\bU\.?T\.?M\.?\s*[:\-]?\s*([0-9]{6,8}/[0-9A-Z]{5,8})"], upper)
    ref_aeb = pick_first([r"REFERENCIA\s+A\.?E\.?B\.?\s*[:\-]?\s*([0-9]{10,80})"], upper)
    num_liquidacion = pick_first(
        [
            r"N[ºO]\s+DE\s+LIQUIDACI(?:Ó|O)N\s*/\s*AUTOLIQUIDACI(?:Ó|O)N\s*[:\-]?\s*([0-9]{6,})",
            r"N[ºO]\s+DE\s+LIQUIDACI(?:Ó|O)N\s*/\s*AUTOLIQUIDACI(?:Ó|O)N\s*\n\s*([0-9]{6,})",
        ],
        upper,
    )

    nrc = pick_first([r"\bNRC\b\s*[:\-]?\s*([0-9A-Z]{16,24})"], upper).strip().upper()
    modelo = pick_first([r"\bMODELO\b\s*[:\-]?\s*([0-9]{3})"], upper)
    ejercicio = pick_first([r"\bEJERCICIO\b\s*[:\-]?\s*([0-9]{4})"], upper)
    fecha_pago_raw = pick_first(
        [r"\bFECHA\s+DE\s+PAGO\b\s*[:\-]?\s*([0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{2,4})"],
        upper,
    )
    fecha_pago_dt = parse_iso_date(fecha_pago_raw)
    fecha_pago = fecha_pago_dt.isoformat() if fecha_pago_dt else ""

    # Normalizaciones rápidas (evita falsos positivos OCR).
    if bonificacion_pct is not None:
        try:
            bonificacion_pct = float(bonificacion_pct)
        except Exception:
            bonificacion_pct = None
    if bonificacion_pct is not None and (bonificacion_pct < 0 or bonificacion_pct > 100.0):
        bonificacion_pct = None

    if tipo_gravamen_pct is not None:
        try:
            tipo_gravamen_pct = float(tipo_gravamen_pct)
        except Exception:
            tipo_gravamen_pct = None
    # Los tipos municipales suelen estar acotados (p.ej. 30% máx.); >60% casi seguro es OCR erróneo.
    if tipo_gravamen_pct is not None and (tipo_gravamen_pct < 0 or tipo_gravamen_pct > 60.0):
        tipo_gravamen_pct = None

    # Heurística (Gestrisam / Málaga): en algunas “solicitudes” el % de participación aparece en la fila t1 con la fecha.
    if participacion_pct is None and fecha_adq_dt:
        try:
            d1 = fecha_adq_dt.strftime("%d/%m/%Y")
            d2 = fecha_adq_dt.strftime("%d-%m-%Y")
            m = re.search(rf"\\bT1\\b[\\s\\S]{{0,120}}{re.escape(d1)}[\\s\\S]{{0,80}}\\b([0-9\\.,]+)\\b", upper)
            if not m:
                m = re.search(rf"\\bT1\\b[\\s\\S]{{0,120}}{re.escape(d2)}[\\s\\S]{{0,80}}\\b([0-9\\.,]+)\\b", upper)
            if m:
                cand = parse_optional_float(m.group(1))
                if cand is not None:
                    try:
                        cand = float(cand)
                    except Exception:
                        cand = None
                if cand is not None and 0 < cand <= 100:
                    participacion_pct = cand
        except Exception:
            pass

    # Heurística: si falta % participación pero tenemos base y valor suelo (método objetivo), inferirla.
    # Nota: sólo cuando el derecho transmitido parece pleno (o no consta).
    if (
        participacion_pct is None
        and valor_suelo is not None
        and base_imponible is not None
        and fecha_adq_dt
        and fecha_tx_dt
        and (not derecho_transmitido or "PLENO" in str(derecho_transmitido).upper())
    ):
        try:
            vs = float(valor_suelo or 0.0)
            bi = float(base_imponible or 0.0)
        except Exception:
            vs = 0.0
            bi = 0.0
        if vs > 0 and bi > 0:
            try:
                coef_table, _coef_src = _iivtnu_max_coefs_for_devengo(fecha_tx_dt)
                info = _iivtnu_objective_coef(fecha_adq_dt, fecha_tx_dt, coef_table or {})
                coef_obj = float(info.get("coef_objetivo") or 0.0)
            except Exception:
                coef_obj = 0.0
            if coef_obj and coef_obj > 0:
                implied = (bi / (vs * coef_obj)) * 100.0
                # tolerancia amplia; muchos casos son 50/33,33/25/100.
                if 0 < implied <= 100.0:
                    implied_round = round(implied, 2)
                    if abs(implied_round - round(implied_round)) <= 0.15:
                        implied_round = float(round(implied_round))
                    participacion_pct = implied_round

    municipio_ine = ""
    provincia = ""
    try:
        postal = _iivtnu_load_postal_cache()
        municipio_ine = str((postal.get("cp_to") or {}).get(cp_norm) or "").strip()
        if municipio_ine:
            provincia = str((postal.get("prov_to") or {}).get(municipio_ine) or "").strip()
    except Exception:
        municipio_ine = ""
        provincia = ""
    if not municipio_ine and municipio:
        try:
            target = _iivtnu_norm_text(municipio)
            ine_cache = _iivtnu_load_ine_municipios_cache()
            found = (ine_cache.get("nameprov_to") or {}).get((target, _iivtnu_norm_text(provincia))) if provincia else ""
            if not found:
                # Si no tenemos provincia, intentamos match por nombre exacto en toda España
                # (si el nombre es único) y, si no lo es, resolvemos por Andalucía si es único ahí.
                candidates = []
                for (name_norm, prov_norm), ine in (ine_cache.get("nameprov_to") or {}).items():
                    if name_norm == target:
                        candidates.append((prov_norm, ine))
                unique_all = sorted({ine for _p, ine in candidates})
                if len(unique_all) == 1:
                    found = unique_all[0]
                else:
                    unique_and = sorted({ine for p, ine in candidates if p in _IIVTNU_ANDALUCIA_PROVINCES_NORM})
                    if len(unique_and) == 1:
                        found = unique_and[0]
            if found:
                municipio_ine = str(found).zfill(5)
                provincia = str((ine_cache.get("prov_to") or {}).get(municipio_ine) or "").strip()
            else:
                # Fallback legacy: catálogo postal (puede estar incompleto).
                postal = _iivtnu_load_postal_cache()
                for ine, nombre in (postal.get("ine_to") or {}).items():
                    for cand in _iivtnu_postal_variants(nombre):
                        if _iivtnu_norm_text(cand) == target:
                            municipio_ine = str(ine).zfill(5)
                            provincia = str((postal.get("prov_to") or {}).get(ine) or "").strip()
                            break
                    if municipio_ine:
                        break
        except Exception:
            pass

    out = {
        "filename": str(filename or "").strip(),
        "doc_type": doc_type,
        "municipio": municipio or "",
        "municipio_ine": municipio_ine or "",
        "provincia": provincia or "",
        "codigo_postal": cp_norm or "",
        "referencia_catastral": refcat or "",
        "fecha_adquisicion": fecha_adq,
        "fecha_transmision": fecha_tx,
        "valor_suelo": valor_suelo,
        "valor_suelo_reducido": valor_suelo_reducido,
        "coef_reduccion": coef_reduccion,
        "valor_catastral_total": valor_catastral_total,
        "valor_transmision": valor_transmision,
        "valor_adquisicion": valor_adquisicion,
        "participacion_pct": participacion_pct,
        "porcentaje_suelo": porcentaje_suelo,
        "base_imponible": base_imponible,
        "tipo_gravamen_pct": tipo_gravamen_pct,
        "cuota_tributaria": cuota,
        "bonificacion_pct": bonificacion_pct,
        "bonificacion_importe": bonificacion_importe,
        "recargo_importe": recargo_importe,
        "intereses_importe": intereses_importe,
        "importe_total": total,
        "nrc": nrc or "",
        "modelo": modelo or "",
        "ejercicio": ejercicio or "",
        "fecha_pago": fecha_pago or "",
        "utm": utm or "",
        "referencia_aeb": ref_aeb or "",
        "numero_liquidacion": num_liquidacion or "",
        "clase_transmision": str(clase_trans or "").strip(),
        "derecho_transmitido": str(derecho_transmitido or "").strip(),
        "subdivision_pct": subdivision_pct,
    }
    if out.get("importe_total") is None and out.get("cuota_tributaria") is not None:
        try:
            cuota_val = float(out.get("cuota_tributaria") or 0.0)
        except Exception:
            cuota_val = 0.0
        try:
            bonif_val = float(out.get("bonificacion_importe") or 0.0)
        except Exception:
            bonif_val = 0.0
        try:
            recargo_val = float(out.get("recargo_importe") or 0.0)
        except Exception:
            recargo_val = 0.0
        try:
            intereses_val = float(out.get("intereses_importe") or 0.0)
        except Exception:
            intereses_val = 0.0
        calc_total = cuota_val - max(0.0, bonif_val) + max(0.0, recargo_val) + max(0.0, intereses_val)
        if calc_total > 0:
            out["importe_total"] = round(calc_total + 1e-9, 2)
    out["_text_hint"] = clean[:1200]
    return out


def _iivtnu_extract_from_pdf(pdf_bytes, filename=""):
    if not pdf_bytes:
        return {}
    raw_text = ""

    def score_extract(out: dict) -> float:
        if not isinstance(out, dict):
            return 0.0
        keys = (
            "doc_type",
            "municipio",
            "codigo_postal",
            "referencia_catastral",
            "fecha_adquisicion",
            "fecha_transmision",
            "valor_suelo",
            "valor_catastral_total",
            "base_imponible",
            "tipo_gravamen_pct",
            "cuota_tributaria",
            "importe_total",
            "nrc",
            "modelo",
            "ejercicio",
        )
        present = 0
        for k in keys:
            v = out.get(k)
            if v is None:
                continue
            if isinstance(v, str) and not v.strip():
                continue
            if isinstance(v, (int, float)) and float(v) == 0.0 and k not in ("bonificacion_pct",):
                continue
            present += 1
        bonus = 0.0
        if str(out.get("doc_type") or "").strip():
            bonus += 0.5
        # Penalizaciones: campos incoherentes típicos de pypdf en PDFs con tablas (mejorar selección vs pdftotext/OCR).
        try:
            bonif = float(out.get("bonificacion_pct") or 0.0)
        except Exception:
            bonif = 0.0
        if bonif > 100.0:
            bonus -= 2.0
        try:
            tipo = float(out.get("tipo_gravamen_pct") or 0.0)
        except Exception:
            tipo = 0.0
        if tipo > 60.0:
            bonus -= 2.0
        try:
            doc = str(out.get("doc_type") or "").strip().lower()
        except Exception:
            doc = ""
        if doc in ("autoliquidacion", "simulacion_ayuda", "guia_autoliquidacion"):
            # Si hay cuota pero falta base, suele ser un fallo de extracción de tablas.
            try:
                cuota_val = float(out.get("cuota_tributaria") or 0.0)
            except Exception:
                cuota_val = 0.0
            if cuota_val > 0 and out.get("base_imponible") in (None, "", 0, 0.0):
                bonus -= 1.5
        # Penalización: incoherencia base/tipo/cuota cuando parecen estar presentes.
        try:
            base = float(out.get("base_imponible") or 0.0)
            tipo = float(out.get("tipo_gravamen_pct") or 0.0)
            cuota = float(out.get("cuota_tributaria") or 0.0)
            if base > 0 and tipo > 0 and cuota > 0:
                implied = base * (tipo / 100.0)
                if abs(implied - cuota) > max(2.0, cuota * 0.25):
                    bonus -= 2.0
        except Exception:
            pass
        return float(present) + bonus

    best = {}
    best_score = -1e9

    # 1) Intento rápido sin binarios externos (pypdf).
    if PdfReader is not None:
        try:
            reader = PdfReader(BytesIO(pdf_bytes))
            pages = list(reader.pages or [])
            texts = []
            max_pages = min(12, len(pages))
            for idx in range(max_pages):
                try:
                    texts.append(pages[idx].extract_text() or "")
                except Exception:
                    texts.append("")
            raw_text = "\n".join(texts).strip()
        except Exception:
            raw_text = ""
    if raw_text and len(raw_text.strip()) >= 30:
        out = _iivtnu_extract_from_text(raw_text, filename=filename)
        s = score_extract(out)
        if s > best_score:
            best = out
            best_score = s

    # 2) Fallback: pdftotext / OCR (tesseract) para PDFs escaneados o cuando pypdf no extrae bien tablas/columnas.
    need_fallback = (not raw_text or len(raw_text.strip()) < 150) or (best_score < 11.0)
    try:
        doc = str((best or {}).get("doc_type") or "").strip().lower()
    except Exception:
        doc = ""
    if doc in ("autoliquidacion", "simulacion_ayuda", "guia_autoliquidacion") and best:
        # pypdf a veces desordena tablas: si hay cuota pero falta base o valor suelo, probamos fallback.
        try:
            cuota_val = float(best.get("cuota_tributaria") or 0.0)
        except Exception:
            cuota_val = 0.0
        if cuota_val > 0 and (best.get("base_imponible") is None or best.get("valor_suelo") is None):
            need_fallback = True
    if need_fallback:
        try:
            with tempfile.TemporaryDirectory() as tmpdir:
                path = os.path.join(tmpdir, "iivtnu.pdf")
                with open(path, "wb") as handle:
                    handle.write(pdf_bytes)
                text2, _err, _method = extract_pdf_text(path)
                if text2 and len(text2.strip()) >= 30:
                    out2 = _iivtnu_extract_from_text(text2, filename=filename)
                    s2 = score_extract(out2)
                    if s2 > best_score:
                        best = out2
                        best_score = s2
        except Exception:
            pass

    return best or _iivtnu_extract_from_text(raw_text or "", filename=filename)


def _iivtnu_upsert_param_set(
    conn,
    municipio_ine,
    devengo_dt,
    tipo_gravamen_pct,
    bonificaciones_json=None,
    source_label: str = "",
    source_url: str = "",
):
    if not conn:
        raise ValueError("conn requerido")
    ensure_iivtnu_schema(conn)
    ine = str(municipio_ine or "").strip().zfill(5)
    if not ine:
        raise ValueError("municipio_ine requerido")
    if not isinstance(devengo_dt, date):
        raise ValueError("devengo inválido")
    try:
        tipo = float(tipo_gravamen_pct)
    except Exception:
        tipo = 0.0
    if tipo <= 0:
        raise ValueError("tipo_gravamen_pct inválido")
    year = int(devengo_dt.year)
    vigente_desde = f"{year}-01-01"
    vigente_hasta = f"{year}-12-31"
    coef_table, coef_source = _iivtnu_max_coefs_for_devengo(devengo_dt)
    coef_json = json.dumps(
        {"schema": "iivtnu_max_coef", "coeficientes": coef_table, "coef_source": coef_source},
        ensure_ascii=False,
        separators=(",", ":"),
    )
    now_iso = datetime.now(timezone.utc).isoformat()

    row = conn.execute(
        """
        SELECT id FROM iivtnu_param_sets
        WHERE municipio_ine = ? AND COALESCE(vigente_desde,'') = ? AND COALESCE(vigente_hasta,'') = ?
        LIMIT 1
        """,
        (ine, vigente_desde, vigente_hasta),
    ).fetchone()
    if row:
        pid = row["id"] if isinstance(row, dict) else row[0]
        conn.execute(
            """
            UPDATE iivtnu_param_sets
            SET tipo_gravamen_pct = ?,
                coeficientes_json = ?,
                bonificaciones_json = ?,
                source_url = ?,
                source_label = ?,
                updated_at = ?
            WHERE id = ?
            """,
            (float(tipo), coef_json, bonificaciones_json, str(source_url or ""), str(source_label or ""), now_iso, str(pid)),
        )
        return {"action": "updated", "id": str(pid), "vigente_desde": vigente_desde, "vigente_hasta": vigente_hasta}

    pid = str(uuid.uuid4())
    conn.execute(
        """
        INSERT INTO iivtnu_param_sets (
          id, municipio_ine, vigente_desde, vigente_hasta,
          tipo_gravamen_pct, coeficientes_json, bonificaciones_json,
          source_url, source_label, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            pid,
            ine,
            vigente_desde,
            vigente_hasta,
            float(tipo),
            coef_json,
            bonificaciones_json,
            str(source_url or ""),
            str(source_label or ""),
            now_iso,
            now_iso,
        ),
    )
    return {"action": "inserted", "id": pid, "vigente_desde": vigente_desde, "vigente_hasta": vigente_hasta}


# --- Simuladores fiscales ---
#
# Nota de alcance:
# - IRPF (residente): calcula una estimación de la cuota sobre la base del ahorro usando la escala estatal+autonómica.
# - IRNR (no residente, sin EP): para ganancias patrimoniales de transmisión de inmuebles aplica el tipo vigente por devengo
#   y muestra la retención/ingreso a cuenta (habitualmente 3%) como referencia (no sustituye al modelo 210).

IRPF_BASE_AHORRO_SCALE = {
    # Escala total (estatal + autonómica) para la base liquidable del ahorro.
    # 2015 (reforma): 19,5 / 21,5 / 23,5
    2015: [
        (0.0, 6000.0, 0.195),
        (6000.0, 50000.0, 0.215),
        (50000.0, None, 0.235),
    ],
    # 2016–2020: 19 / 21 / 23
    2016: [(0.0, 6000.0, 0.19), (6000.0, 50000.0, 0.21), (50000.0, None, 0.23)],
    2017: [(0.0, 6000.0, 0.19), (6000.0, 50000.0, 0.21), (50000.0, None, 0.23)],
    2018: [(0.0, 6000.0, 0.19), (6000.0, 50000.0, 0.21), (50000.0, None, 0.23)],
    2019: [(0.0, 6000.0, 0.19), (6000.0, 50000.0, 0.21), (50000.0, None, 0.23)],
    2020: [(0.0, 6000.0, 0.19), (6000.0, 50000.0, 0.21), (50000.0, None, 0.23)],
    # 2021–2022: nuevo tramo 26% desde 200k
    2021: [
        (0.0, 6000.0, 0.19),
        (6000.0, 50000.0, 0.21),
        (50000.0, 200000.0, 0.23),
        (200000.0, None, 0.26),
    ],
    2022: [
        (0.0, 6000.0, 0.19),
        (6000.0, 50000.0, 0.21),
        (50000.0, 200000.0, 0.23),
        (200000.0, None, 0.26),
    ],
    # 2023–2024: 27% desde 200k, 28% desde 300k
    2023: [
        (0.0, 6000.0, 0.19),
        (6000.0, 50000.0, 0.21),
        (50000.0, 200000.0, 0.23),
        (200000.0, 300000.0, 0.27),
        (300000.0, None, 0.28),
    ],
    2024: [
        (0.0, 6000.0, 0.19),
        (6000.0, 50000.0, 0.21),
        (50000.0, 200000.0, 0.23),
        (200000.0, 300000.0, 0.27),
        (300000.0, None, 0.28),
    ],
    # 2025+: último tramo 30%
    2025: [
        (0.0, 6000.0, 0.19),
        (6000.0, 50000.0, 0.21),
        (50000.0, 200000.0, 0.23),
        (200000.0, 300000.0, 0.27),
        (300000.0, None, 0.30),
    ],
}


def _irnr_capital_gains_rate_for_devengo(devengo: date) -> float:
    """
    IRNR sin EP: tipo para ganancias patrimoniales (transmisiones) según devengo.
    Referencia AEAT (cambio en 2015 y tipo 19% desde 2016).
    """
    if not devengo:
        return 0.19
    if devengo.year < 2015:
        raise ValueError("IRNR: ejercicio anterior a 2015 no soportado en el simulador")
    if devengo.year == 2015:
        # Hasta 11/07/2015: 20% · Desde 12/07/2015: 19,5%
        cutoff = date(2015, 7, 12)
        return 0.20 if devengo < cutoff else 0.195
    return 0.19


CCAA_LABELS = {
    "AN": "Andalucía",
    "AR": "Aragón",
    "AS": "Asturias",
    "IB": "Illes Balears",
    "CN": "Canarias",
    "CB": "Cantabria",
    "CM": "Castilla-La Mancha",
    "CL": "Castilla y León",
    "CT": "Cataluña",
    "VC": "Comunitat Valenciana",
    "EX": "Extremadura",
    "GA": "Galicia",
    "MD": "Comunidad de Madrid",
    "MC": "Región de Murcia",
    "NC": "Navarra",
    "PV": "País Vasco",
    "RI": "La Rioja",
    "CE": "Ceuta",
    "ML": "Melilla",
}


def _normalize_ccaa(value: object) -> str:
    raw = str(value or "").strip().upper()
    if raw in CCAA_LABELS:
        return raw
    # Permite nombres (básico).
    key = normalize_simple(raw)
    for code, label in CCAA_LABELS.items():
        if normalize_simple(label) == key:
            return code
    return "AN"


def _irpf_savings_scale_for_year(year):
    y = int(year or 0)
    if y in IRPF_BASE_AHORRO_SCALE:
        return y, IRPF_BASE_AHORRO_SCALE[y], False
    first = min(IRPF_BASE_AHORRO_SCALE.keys())
    if y and y < first:
        raise ValueError(f"IRPF: ejercicio {y} no soportado (mínimo {first})")
    last = max(IRPF_BASE_AHORRO_SCALE.keys())
    return last, IRPF_BASE_AHORRO_SCALE[last], True


def _irpf_tax_progressive(base, brackets):
    try:
        base_val = float(base or 0.0)
    except Exception:
        base_val = 0.0
    base_val = max(0.0, base_val)
    cuota = 0.0
    for lo, hi, rate in brackets:
        if base_val <= lo:
            break
        upper = hi if hi is not None else base_val
        tramo = min(base_val, upper) - lo
        if tramo > 0:
            cuota += tramo * float(rate)
        if hi is None or base_val <= upper:
            break
    return round(cuota + 1e-9, 2)


def _irpf_days_inclusive(start: date, end: date) -> int:
    if not start or not end:
        return 0
    if end < start:
        return 0
    # AEAT: "días transcurridos" suele ser diferencia de fechas (excluye el día inicial).
    return (end - start).days


def _safe_calendar_date(year: int, month: int, day: int) -> date:
    try:
        return date(int(year), int(month), int(day))
    except Exception:
        pass
    # Ajuste típico 29/02 -> 28/02
    try:
        if int(month) == 2 and int(day) == 29:
            return date(int(year), 2, 28)
    except Exception:
        pass
    return date(int(year), 1, 1)


def _irpf_years_to_1996_rounded_up(acq: date) -> int:
    """
    DT 9ª LIRPF: años hasta 31-12-1996, redondeado por exceso.
    """
    if not acq:
        return 0
    end = date(1996, 12, 31)
    if acq > end:
        return 0
    years = end.year - acq.year
    candidate = _safe_calendar_date(acq.year + years, acq.month, acq.day)
    if candidate > end:
        years = max(0, years - 1)
        candidate = _safe_calendar_date(acq.year + years, acq.month, acq.day)
    if end > candidate:
        years += 1
    return max(0, int(years))


def _irpf_abatimiento_reduction_pct(tipo: str, years_to_1996: int) -> float:
    """
    DT 9ª LIRPF (Ley 35/2006): porcentajes reductores por año > 2 y reglas de no sujeción.
    tipo:
      - "inmueble": bienes inmuebles / derechos sobre los mismos (11,11%)
      - "valores_cotizados": acciones admitidas a negociación (25%)
      - "otros": resto (14,28%)
    """
    t = str(tipo or "").strip().lower() or "inmueble"
    y = int(years_to_1996 or 0)
    if y <= 2:
        return 0.0
    if t == "valores_cotizados":
        if y > 5:
            return 100.0
        return min(100.0, (y - 2) * 25.0)
    if t == "otros":
        if y > 8:
            return 100.0
        return min(100.0, (y - 2) * 14.28)
    # inmueble (default)
    if y > 10:
        return 100.0
    return min(100.0, (y - 2) * 11.11)


def _irpf_apply_abatimiento_dt9(
    *,
    acq: date,
    devengo: date,
    ganancia_total: float,
    ganancia_sujeta: float,
    valor_transmision_calc: float,
    vt2_override=None,
    vt1_acumulado_2015: float,
    tipo_elemento: str,
    force: bool = False,
) -> tuple[float, dict]:
    """
    Aplica el régimen transitorio DT 9ª (coeficientes de abatimiento).
    Devuelve: (ganancia_computable_sujeta, detalle_abatimiento)
    Nota: se aplica sobre la ganancia sujeta y no exenta (doctrina DGT / AEAT).
    """
    tipo_norm = str(tipo_elemento or "").strip().lower() or "inmueble"
    if tipo_norm in ("acciones_cotizadas", "acciones", "cotizadas"):
        tipo_norm = "valores_cotizados"
    detail = {
        "aplicable": 0,
        "motivo": "",
        "tipo_elemento": tipo_norm,
        "vt1_acumulado_2015": round(float(vt1_acumulado_2015 or 0.0) + 1e-9, 2),
        "vt2_valor_transmision": round(float(valor_transmision_calc or 0.0) + 1e-9, 2),
        "vt2_override": None if vt2_override is None else round(float(vt2_override or 0.0) + 1e-9, 2),
        "limite_400k": 400000.0,
    }

    try:
        g_total = float(ganancia_total or 0.0)
    except Exception:
        g_total = 0.0
    try:
        g_sujeta = float(ganancia_sujeta or 0.0)
    except Exception:
        g_sujeta = 0.0
    g_total = round(g_total + 1e-9, 2)
    g_sujeta = round(max(0.0, g_sujeta) + 1e-9, 2)

    if g_sujeta <= 0:
        detail["motivo"] = "Sin ganancia sujeta"
        return g_sujeta, detail
    if not acq or not devengo:
        detail["motivo"] = "Fechas inválidas"
        return g_sujeta, detail

    cutoff_acq = date(1994, 12, 31)
    if not force and acq >= cutoff_acq:
        detail["motivo"] = "No aplica: adquisición >= 31/12/1994"
        return g_sujeta, detail

    # Parte de la ganancia generada antes de 20-01-2006: reparto lineal por días (19-01-2006 inclusive)
    pre_end = min(date(2006, 1, 19), devengo)
    # Denominador: días transcurridos entre adquisición y transmisión sin contar ninguno de los dos días.
    days_total = max(0, _irpf_days_inclusive(acq, devengo) - 1)
    # Numerador: días transcurridos entre adquisición y 19-01-2006 (excluye adquisición, incluye 19/01/2006).
    days_pre = _irpf_days_inclusive(acq, pre_end)
    if days_total <= 0 or days_pre <= 0:
        detail["motivo"] = "Sin tramo pre-20/01/2006"
        return g_sujeta, detail
    ratio_pre = min(1.0, max(0.0, days_pre / float(days_total)))

    # Ajuste a ganancia sujeta (si hay exención parcial, imputamos proporcionalmente)
    ratio_sujeta = 1.0
    if g_total > 0:
        ratio_sujeta = min(1.0, max(0.0, g_sujeta / float(g_total)))

    g_pre_total = round(g_total * ratio_pre + 1e-9, 2)
    g_pre_sujeta = round(max(0.0, g_pre_total * ratio_sujeta) + 1e-9, 2)
    g_post_sujeta = round(max(0.0, g_sujeta - g_pre_sujeta) + 1e-9, 2)

    if g_pre_sujeta <= 0:
        detail["motivo"] = "Sin ganancia pre-20/01/2006 sujeta"
        return g_sujeta, detail

    # Límite conjunto 400.000€ desde 01-01-2015 (Ley 26/2014). Para transmisiones previas no aplica.
    vt2_default = max(0.0, float(valor_transmision_calc or 0.0))
    vt2 = vt2_default
    try:
        vt2o = None if vt2_override is None else float(vt2_override)
    except Exception:
        vt2o = None
    if vt2o is not None and vt2o > 0:
        vt2 = vt2o
    detail["vt2_usado_400k"] = round(float(vt2) + 1e-9, 2)
    vt1 = max(0.0, float(vt1_acumulado_2015 or 0.0))
    susceptible = g_pre_sujeta
    susceptible_vt2 = vt2
    if devengo >= date(2015, 1, 1):
        if vt1 >= 400000.0:
            susceptible = 0.0
        else:
            remaining = 400000.0 - vt1
            if vt2 <= 0.0:
                susceptible = 0.0
            elif vt1 + vt2 <= 400000.0:
                susceptible = g_pre_sujeta
            else:
                ratio_cap = max(0.0, min(1.0, remaining / vt2))
                susceptible = g_pre_sujeta * ratio_cap
                susceptible_vt2 = remaining

    years_1996 = _irpf_years_to_1996_rounded_up(acq)
    pct = _irpf_abatimiento_reduction_pct(detail.get("tipo_elemento"), years_1996)
    reduction = round(max(0.0, susceptible) * (pct / 100.0) + 1e-9, 2)

    g_pre_reduced = round(max(0.0, g_pre_sujeta - reduction) + 1e-9, 2)
    g_computable = round(max(0.0, g_post_sujeta + g_pre_reduced) + 1e-9, 2)

    detail.update(
        {
            "aplicable": 1 if reduction > 0 else 0,
            "motivo": "OK" if reduction > 0 else "Sin reducción (pct=0 o límite)",
            "days_total": int(days_total),
            "days_pre_2006": int(days_pre),
            "ratio_pre_2006": round(ratio_pre + 1e-12, 8),
            "ganancia_total": g_total,
            "ganancia_sujeta": g_sujeta,
            "ganancia_pre_2006_total": g_pre_total,
            "ganancia_pre_2006_sujeta": g_pre_sujeta,
            "ganancia_post_2006_sujeta": g_post_sujeta,
            "ganancia_susceptible_reduccion": round(max(0.0, susceptible) + 1e-9, 2),
            "vt2_susceptible": round(max(0.0, susceptible_vt2) + 1e-9, 2),
            "years_to_1996_rounded_up": int(years_1996),
            "pct_reduccion": round(float(pct) + 1e-12, 4),
            "reduccion_importe": reduction,
            "ganancia_pre_2006_reducida": g_pre_reduced,
            "ganancia_computable": g_computable,
        }
    )
    return g_computable, detail


def _irpf_ganancia_simulate(payload: dict) -> dict:
    if not isinstance(payload, dict):
        raise ValueError("payload inválido")
    acq = parse_iso_date(payload.get("fecha_adquisicion") or "")
    devengo = parse_iso_date(payload.get("fecha_transmision") or "")
    if not acq or not devengo:
        raise ValueError("Fechas inválidas")
    if devengo <= acq:
        raise ValueError("La fecha de transmisión debe ser posterior a la de adquisición")

    def _money(key: str) -> float:
        try:
            return float(parse_money_value(payload.get(key) or 0) or 0.0)
        except Exception:
            return 0.0

    participacion_pct = parse_optional_float(payload.get("participacion_pct") or None)
    if participacion_pct is None:
        participacion_pct = 100.0
    try:
        participacion_pct = float(participacion_pct)
    except Exception:
        participacion_pct = 100.0
    participacion_pct = max(0.0, min(100.0, participacion_pct))
    factor = participacion_pct / 100.0

    valor_adq = _money("valor_adquisicion")
    gastos_adq = _money("gastos_adquisicion")
    mejoras = _money("inversiones_mejoras")
    amort = _money("amortizacion_deducida")
    valor_tx = _money("valor_transmision")
    gastos_tx = _money("gastos_transmision")
    plusvalia = _money("plusvalia_municipal")

    def _sum_money(keys: list[str]) -> float:
        total = 0.0
        for k in keys:
            total += _money(k)
        return round(max(0.0, total) + 1e-9, 2)

    adq_impuestos_total = _sum_money(["gastos_adq_itp", "gastos_adq_iva", "gastos_adq_ajd"])
    if adq_impuestos_total <= 0:
        adq_impuestos_total = _money("gastos_adq_itp_iva_ajd")

    adq_desglose_total = _sum_money(
        [
            "gastos_adq_agencia",
            "gastos_adq_abogado",
            "gastos_adq_tasacion",
            "gastos_adq_notaria",
            "gastos_adq_registro",
            "gastos_adq_notaria_registro",
            "gastos_adq_gestoria",
            "gastos_adq_hipoteca",
            "gastos_adq_otros",
        ]
    )
    adq_desglose_total = round(max(0.0, adq_desglose_total + adq_impuestos_total) + 1e-9, 2)
    tx_desglose_total = _sum_money(
        [
            "gastos_tx_agencia",
            "gastos_tx_abogado",
            "gastos_tx_cert_energetico",
            "gastos_tx_notaria",
            "gastos_tx_registro",
            "gastos_tx_notaria_registro",
            "gastos_tx_cancelacion",
            "gastos_tx_cancelacion_registral",
            "gastos_tx_hipoteca",
            "gastos_tx_otros",
        ]
    )
    adq_mode = str(payload.get("gastos_adquisicion_mode") or "").strip().lower()
    tx_mode = str(payload.get("gastos_transmision_mode") or "").strip().lower()
    if adq_mode == "desglose" and adq_desglose_total > 0:
        gastos_adq = adq_desglose_total
    if tx_mode == "desglose" and tx_desglose_total > 0:
        gastos_tx = tx_desglose_total

    # Amortización (auto) si el inmueble estuvo alquilado (o afecto) y hay base.
    amort_auto = 0.0
    amort_auto_days = 0
    amort_auto_base_manual = _money("amortizacion_base")
    amort_auto_pct = parse_optional_float(payload.get("amortizacion_pct") or 3.0)
    if amort_auto_pct is None:
        amort_auto_pct = 3.0
    try:
        amort_auto_pct = float(amort_auto_pct)
    except Exception:
        amort_auto_pct = 3.0
    amort_auto_pct = max(0.0, min(10.0, amort_auto_pct))
    alquilado_flag = bool(payload.get("inmueble_alquilado") or False)
    amort_mode = str(payload.get("amortizacion_mode") or "").strip().lower()
    amort_auto_base_coste = 0.0
    amort_auto_base_catastral = 0.0
    amort_auto_base = 0.0

    if (amort_mode == "auto" or alquilado_flag) and amort <= 0 and amort_auto_pct > 0:
        vc_total = _money("valor_catastral_total")
        pct_suelo = parse_optional_float(payload.get("porcentaje_suelo") or payload.get("porcentaje_suelo_pct") or None)
        if pct_suelo is not None:
            try:
                pct_suelo = float(pct_suelo)
            except Exception:
                pct_suelo = None
        if pct_suelo is not None:
            pct_suelo = max(0.0, min(100.0, pct_suelo))
        constr_factor = None
        if vc_total > 0 and pct_suelo is not None:
            constr_factor = max(0.0, min(1.0, 1.0 - (pct_suelo / 100.0)))
            amort_auto_base_catastral = round(vc_total * constr_factor + 1e-9, 2)
            coste_total = max(0.0, (valor_adq + gastos_adq + mejoras))
            amort_auto_base_coste = round(coste_total * constr_factor + 1e-9, 2)

        # Base final (construcción): mayor entre manual, coste (sin suelo) y catastral (sin suelo).
        bases = [amort_auto_base_manual]
        if amort_auto_base_coste > 0:
            bases.append(amort_auto_base_coste)
        if amort_auto_base_catastral > 0:
            bases.append(amort_auto_base_catastral)
        amort_auto_base = round(max(bases) + 1e-9, 2) if bases else 0.0

    if (amort_mode == "auto" or alquilado_flag) and amort <= 0 and amort_auto_base > 0 and amort_auto_pct > 0:
        start = parse_iso_date(payload.get("fecha_inicio_alquiler") or "") or acq
        end = parse_iso_date(payload.get("fecha_fin_alquiler") or "") or devengo
        if end > devengo:
            end = devengo
        if start < acq:
            start = acq
        if end > start:
            amort_auto_days = int((end - start).days)
            amort_auto = round(
                float(amort_auto_base) * (float(amort_auto_pct) / 100.0) * (float(amort_auto_days) / 365.0) + 1e-9,
                2,
            )
            amort = max(0.0, amort_auto)

    valor_adquisicion_calc = max(0.0, (valor_adq + gastos_adq + mejoras - amort) * factor)
    valor_transmision_calc = max(0.0, (valor_tx - gastos_tx - plusvalia) * factor)
    ganancia = round(valor_transmision_calc - valor_adquisicion_calc + 1e-9, 2)

    regimen = str(payload.get("regimen_fiscal") or payload.get("regimen") or "irpf").strip().lower()
    if regimen not in ("irpf", "irnr"):
        regimen = "irpf"

    vivienda_habitual = bool(payload.get("vivienda_habitual") or False)
    exencion_mayor_65 = bool(payload.get("exencion_mayor_65") or False)
    dependencia_grado = str(payload.get("dependencia_grado") or "").strip().lower()
    reinversion = parse_optional_float(payload.get("importe_reinvertido") or None)
    reinversion_comprometida = parse_optional_float(payload.get("importe_comprometido_reinvertir") or None)
    if reinversion is not None:
        try:
            reinversion = float(reinversion)
        except Exception:
            reinversion = None
    if reinversion_comprometida is not None:
        try:
            reinversion_comprometida = float(reinversion_comprometida)
        except Exception:
            reinversion_comprometida = None
    prestamo_pendiente = _money("prestamo_pendiente")

    exento = 0.0
    exencion_motivo = ""
    edad = None
    if regimen == "irpf":
        # Exención >65 / dependencia (siempre ligada a vivienda habitual).
        fecha_nacimiento = parse_iso_date(payload.get("fecha_nacimiento") or "")
        if fecha_nacimiento:
            try:
                edad = int((devengo - fecha_nacimiento).days // 365.2425)
            except Exception:
                edad = None
        es_dependiente = dependencia_grado in ("severa", "gran", "gran_dependencia", "severe", "great")
        es_mayor_65 = (edad is not None and edad >= 65)
        if (exencion_mayor_65 or es_mayor_65 or es_dependiente) and vivienda_habitual and ganancia > 0:
            exento = ganancia
            if es_dependiente and not (exencion_mayor_65 or es_mayor_65):
                exencion_motivo = "Exención dependencia (vivienda habitual)"
            elif es_mayor_65 and not exencion_mayor_65:
                exencion_motivo = "Exención >65 vivienda habitual (auto por fecha nacimiento)"
            else:
                exencion_motivo = "Exención >65 vivienda habitual (forzada)"
        elif vivienda_habitual and ganancia > 0:
            reinv_total = 0.0
            if reinversion is not None and reinversion > 0:
                reinv_total += float(reinversion)
            if reinversion_comprometida is not None and reinversion_comprometida > 0:
                reinv_total += float(reinversion_comprometida)
            importe_obtenido = 0.0
            if reinv_total > 0:
                # AEAT: "importe total obtenido" = valor transmisión (en los términos del art. 35 LIRPF) - principal pendiente.
                importe_obtenido = max(0.0, (valor_tx - gastos_tx - plusvalia - prestamo_pendiente) * factor)
            ratio = 0.0
            if importe_obtenido > 0:
                ratio = max(0.0, min(1.0, reinv_total / importe_obtenido))
            exento = round(ganancia * ratio + 1e-9, 2)
            exencion_motivo = "Exención reinversión (proporcional)"

    ganancia_sujeta = round(max(0.0, ganancia - exento) + 1e-9, 2)
    ganancia_computable = ganancia_sujeta
    abatimiento_detail = {"aplicable": 0, "motivo": "No calculado"}
    year = int((payload.get("ejercicio") or devengo.year) or devengo.year)
    ccaa = _normalize_ccaa(payload.get("ccaa") or payload.get("comunidad_autonoma") or "AN")

    if regimen == "irpf" and ganancia_sujeta > 0:
        ab_mode = str(payload.get("abatimiento_mode") or payload.get("abatimiento") or "auto").strip().lower()
        if ab_mode in ("0", "no", "off", "false", "n", "disabled"):
            abatimiento_detail = {"aplicable": 0, "motivo": "Desactivado"}
        else:
            tipo_elemento = str(
                payload.get("abatimiento_tipo")
                or payload.get("abatimiento_tipo_bien")
                or payload.get("tipo_elemento")
                or "inmueble"
            ).strip().lower()
            vt1 = parse_optional_float(payload.get("abatimiento_vt1_acumulado_2015") or payload.get("abatimiento_vt1") or 0.0)
            if vt1 is None:
                vt1 = 0.0
            try:
                vt1 = float(vt1)
            except Exception:
                vt1 = 0.0
            vt2_override = parse_optional_float(payload.get("abatimiento_vt2_override") or payload.get("abatimiento_vt2") or None)
            if vt2_override is not None:
                try:
                    vt2_override = float(vt2_override)
                except Exception:
                    vt2_override = None
            force = ab_mode in ("force", "si", "yes", "on", "true", "1")

            mejoras_fecha = parse_iso_date(payload.get("fecha_mejoras") or payload.get("mejoras_fecha") or "")
            valor_tx_mejoras = _money("valor_transmision_mejoras")
            use_mejoras_split = bool(mejoras_fecha and valor_tx_mejoras > 0 and mejoras > 0 and mejoras_fecha != acq)

            if use_mejoras_split:
                valor_tx_mejoras = min(valor_tx_mejoras, max(0.0, valor_tx))
                valor_tx_principal = max(0.0, valor_tx - valor_tx_mejoras)

                valor_transmision_principal_calc = max(0.0, (valor_tx_principal - gastos_tx - plusvalia) * factor)
                valor_transmision_mejoras_calc = max(0.0, valor_tx_mejoras * factor)

                valor_adquisicion_principal_calc = max(0.0, (valor_adq + gastos_adq - amort) * factor)
                valor_adquisicion_mejoras_calc = max(0.0, mejoras * factor)

                ganancia_principal = round(valor_transmision_principal_calc - valor_adquisicion_principal_calc + 1e-9, 2)
                ganancia_mejoras = round(valor_transmision_mejoras_calc - valor_adquisicion_mejoras_calc + 1e-9, 2)

                ratio_sujeta_total = 0.0
                if ganancia > 0:
                    ratio_sujeta_total = max(0.0, min(1.0, ganancia_sujeta / float(ganancia)))

                ganancia_principal_sujeta = round(max(0.0, ganancia_principal) * ratio_sujeta_total + 1e-9, 2)
                ganancia_mejoras_sujeta = round(max(0.0, ganancia_mejoras) * ratio_sujeta_total + 1e-9, 2)

                comp_principal, det_principal = _irpf_apply_abatimiento_dt9(
                    acq=acq,
                    devengo=devengo,
                    ganancia_total=ganancia_principal,
                    ganancia_sujeta=ganancia_principal_sujeta,
                    valor_transmision_calc=valor_transmision_principal_calc,
                    vt2_override=vt2_override,
                    vt1_acumulado_2015=vt1,
                    tipo_elemento=tipo_elemento,
                    force=force,
                )
                comp_mejoras, det_mejoras = _irpf_apply_abatimiento_dt9(
                    acq=mejoras_fecha,
                    devengo=devengo,
                    ganancia_total=ganancia_mejoras,
                    ganancia_sujeta=ganancia_mejoras_sujeta,
                    valor_transmision_calc=valor_transmision_mejoras_calc,
                    vt2_override=None,
                    vt1_acumulado_2015=0.0,
                    tipo_elemento=tipo_elemento,
                    force=force,
                )

                ganancia_computable = round(max(0.0, comp_principal + comp_mejoras) + 1e-9, 2)
                reduccion_total = round(
                    float((det_principal or {}).get("reduccion_importe") or 0.0)
                    + float((det_mejoras or {}).get("reduccion_importe") or 0.0)
                    + 1e-9,
                    2,
                )
                abatimiento_detail = {
                    "aplicable": 1 if reduccion_total > 0 else 0,
                    "motivo": "OK" if reduccion_total > 0 else "Sin reducción",
                    "split_mejoras": 1,
                    "fecha_mejoras": str(mejoras_fecha or ""),
                    "valor_transmision_mejoras_calc": round(float(valor_transmision_mejoras_calc or 0.0) + 1e-9, 2),
                    "reduccion_importe": reduccion_total,
                    "ganancia_computable": ganancia_computable,
                    "componentes": [
                        {"id": "principal", "abatimiento": det_principal},
                        {"id": "mejoras", "abatimiento": det_mejoras},
                    ],
                }
            else:
                ganancia_computable, abatimiento_detail = _irpf_apply_abatimiento_dt9(
                    acq=acq,
                    devengo=devengo,
                    ganancia_total=ganancia,
                    ganancia_sujeta=ganancia_sujeta,
                    valor_transmision_calc=valor_transmision_calc,
                    vt2_override=vt2_override,
                    vt1_acumulado_2015=vt1,
                    tipo_elemento=tipo_elemento,
                    force=force,
                )

    base_ahorro = round(max(0.0, ganancia_computable) + 1e-9, 2)

    days_total = int((devengo - acq).days)
    ganancia_diaria = round((ganancia / days_total) + 1e-12, 6) if days_total > 0 else 0.0
    ganancia_sujeta_diaria = round((ganancia_sujeta / days_total) + 1e-12, 6) if days_total > 0 else 0.0
    exento_pct = round((float(exento) / float(ganancia)) * 100.0 + 1e-12, 4) if ganancia > 0 else 0.0

    cuota = 0.0
    scale_year = ""
    assumed = 0
    tipo_gravamen_pct = None
    retencion_pct = None
    retencion_importe = None
    cuota_neta = None

    if regimen == "irnr":
        rate = _irnr_capital_gains_rate_for_devengo(devengo)
        cuota = round(base_ahorro * float(rate) + 1e-9, 2)
        tipo_gravamen_pct = round(float(rate) * 100.0 + 1e-12, 3)
        # Retención/ingreso a cuenta típico en transmisión de inmuebles por no residente.
        retencion_pct = parse_optional_float(payload.get("retencion_pct") or payload.get("retencion_pct_override") or 3.0)
        if retencion_pct is None:
            retencion_pct = 3.0
        try:
            retencion_pct = float(retencion_pct)
        except Exception:
            retencion_pct = 3.0
        retencion_pct = max(0.0, min(100.0, retencion_pct))
        retencion_importe = round(max(0.0, valor_tx * factor) * (retencion_pct / 100.0) + 1e-9, 2)
        cuota_neta = round(cuota - retencion_importe + 1e-9, 2)
    else:
        scale_year, brackets, assumed = _irpf_savings_scale_for_year(year)
        cuota = _irpf_tax_progressive(base_ahorro, brackets)

    return {
        "ok": True,
        "params": {
            "ejercicio": year,
            "regimen_fiscal": regimen,
            "ccaa": ccaa,
            "ccaa_label": CCAA_LABELS.get(ccaa, ccaa),
            "escala_ejercicio": scale_year,
            "escala_asumida": 1 if assumed else 0,
            "tipo_gravamen_pct": tipo_gravamen_pct,
            "retencion_pct": retencion_pct,
            "abatimiento_mode": str(payload.get("abatimiento_mode") or payload.get("abatimiento") or "auto").strip().lower(),
        },
        "result": {
            "participacion_factor": round(factor + 1e-12, 6),
            "days_transcurridos": days_total,
            "ganancia_diaria": ganancia_diaria,
            "ganancia_sujeta_diaria": ganancia_sujeta_diaria,
            "exento_pct": exento_pct,
            "valor_adquisicion_calc": round(valor_adquisicion_calc + 1e-9, 2),
            "valor_transmision_calc": round(valor_transmision_calc + 1e-9, 2),
            "ganancia_patrimonial": ganancia,
            "ganancia_sujeta": ganancia_sujeta,
            "ganancia_patrimonial_computable": round(ganancia_computable + 1e-9, 2),
            "exento": round(exento + 1e-9, 2),
            "exencion_motivo": exencion_motivo,
            "edad_transmision": edad,
            "amortizacion_deducida_aplicada": round(float(amort or 0.0) + 1e-9, 2),
            "amortizacion_auto": round(float(amort_auto or 0.0) + 1e-9, 2),
            "amortizacion_auto_days": int(amort_auto_days or 0),
            "amortizacion_auto_base": round(float(amort_auto_base or 0.0) + 1e-9, 2),
            "amortizacion_auto_base_manual": round(float(amort_auto_base_manual or 0.0) + 1e-9, 2),
            "amortizacion_auto_base_coste": round(float(amort_auto_base_coste or 0.0) + 1e-9, 2),
            "amortizacion_auto_base_catastral": round(float(amort_auto_base_catastral or 0.0) + 1e-9, 2),
            "amortizacion_auto_pct": round(float(amort_auto_pct or 0.0) + 1e-12, 6),
            "base_ahorro_sujeta": base_ahorro,
            "cuota_ahorro_estimada": cuota,
            "retencion_importe": retencion_importe,
            "cuota_neta": cuota_neta,
            "abatimiento": abatimiento_detail,
        },
    }


def build_irpf_ganancia_report_pdf(payload: dict, simulate_out: dict) -> bytes:
    payload = payload or {}
    simulate_out = simulate_out or {}
    params = simulate_out.get("params") or {}
    result = simulate_out.get("result") or {}

    ejercicio = params.get("ejercicio")
    escala = params.get("escala_ejercicio")
    assumed = bool(params.get("escala_asumida"))
    regimen = str(params.get("regimen_fiscal") or payload.get("regimen_fiscal") or "irpf").strip().lower() or "irpf"
    tipo_gravamen_pct = params.get("tipo_gravamen_pct")
    retencion_pct = params.get("retencion_pct")

    def _money_float(value: object) -> float:
        try:
            return float(parse_money_value(value or 0) or 0.0)
        except Exception:
            return 0.0

    def yn(value: object) -> str:
        return "Sí" if bool(value) else "No"

    def money(value: object) -> str:
        raw = "" if value is None else str(value)
        if not raw.strip():
            return "—"
        try:
            parsed = parse_money_value(value)
        except Exception:
            parsed = None
        if parsed is None:
            return raw.strip()
        return format_eur(parsed)

    def pct(value: object) -> str:
        val = parse_optional_float(value)
        if val is None:
            return ""
        try:
            val = float(val)
        except Exception:
            return ""
        return f"{val:.2f}%".replace(".", ",")

    def date_text(value: object) -> str:
        return str(value or "").strip()

    importe_a_pagar = result.get("cuota_ahorro_estimada")
    if regimen == "irnr" and result.get("cuota_neta") is not None:
        importe_a_pagar = result.get("cuota_neta")
    resumen_cards = {
        "kind": "kpi_cards",
        "columns": 3,
        "items": [
            {"label": "Días transcurridos", "value": str(result.get("days_transcurridos") or "—")},
            {"label": "Ganancia patrimonial", "value": money(result.get("ganancia_patrimonial"))},
            {"label": "Ganancia diaria", "value": money(result.get("ganancia_diaria"))},
            {"label": "Exenta", "value": money(result.get("exento"))},
            {"label": "Sujeta", "value": money(result.get("ganancia_sujeta"))},
            {"label": "Importe a pagar (estimado)", "value": money(importe_a_pagar), "accent": True},
        ],
    }

    # Gráficos (2): puente de cálculo + barra exenta vs sujeta.
    participacion_pct = parse_optional_float(payload.get("participacion_pct") or 100.0)
    if participacion_pct is None:
        participacion_pct = 100.0
    try:
        participacion_pct = float(participacion_pct)
    except Exception:
        participacion_pct = 100.0
    participacion_pct = max(0.0, min(100.0, participacion_pct))
    factor = participacion_pct / 100.0

    def _sum_money(keys: list[str]) -> float:
        total = 0.0
        for k in keys:
            total += _money_float(payload.get(k))
        return round(max(0.0, total) + 1e-9, 2)

    # Totales coherentes con el simulador (si el modo es "desglose", suma conceptos).
    gastos_adq_total = _money_float(payload.get("gastos_adquisicion"))
    gastos_tx_total = _money_float(payload.get("gastos_transmision"))
    mejoras = _money_float(payload.get("inversiones_mejoras"))
    amort = _money_float(payload.get("amortizacion_deducida")) or float(result.get("amortizacion_deducida_aplicada") or 0.0)
    plusvalia = _money_float(payload.get("plusvalia_municipal"))
    valor_adq = _money_float(payload.get("valor_adquisicion"))
    valor_tx = _money_float(payload.get("valor_transmision"))

    adq_impuestos_total = _sum_money(["gastos_adq_itp", "gastos_adq_iva", "gastos_adq_ajd"])
    if adq_impuestos_total <= 0:
        adq_impuestos_total = _money_float(payload.get("gastos_adq_itp_iva_ajd"))
    adq_desglose_total = _sum_money(
        [
            "gastos_adq_agencia",
            "gastos_adq_abogado",
            "gastos_adq_tasacion",
            "gastos_adq_notaria",
            "gastos_adq_registro",
            "gastos_adq_notaria_registro",
            "gastos_adq_gestoria",
            "gastos_adq_hipoteca",
            "gastos_adq_otros",
        ]
    )
    adq_desglose_total = round(max(0.0, adq_desglose_total + adq_impuestos_total) + 1e-9, 2)
    tx_desglose_total = _sum_money(
        [
            "gastos_tx_agencia",
            "gastos_tx_abogado",
            "gastos_tx_cert_energetico",
            "gastos_tx_notaria",
            "gastos_tx_registro",
            "gastos_tx_notaria_registro",
            "gastos_tx_cancelacion",
            "gastos_tx_cancelacion_registral",
            "gastos_tx_hipoteca",
            "gastos_tx_otros",
        ]
    )
    adq_mode = str(payload.get("gastos_adquisicion_mode") or "").strip().lower()
    tx_mode = str(payload.get("gastos_transmision_mode") or "").strip().lower()
    if adq_mode == "desglose" and adq_desglose_total > 0:
        gastos_adq_total = adq_desglose_total
    if tx_mode == "desglose" and tx_desglose_total > 0:
        gastos_tx_total = tx_desglose_total

    waterfall_steps: list[dict] = []

    def _push_step(label: str, value: float) -> None:
        if not label:
            return
        try:
            v = float(value)
        except Exception:
            v = 0.0
        if abs(v) < 1e-9:
            return
        waterfall_steps.append({"label": label, "value": round(v + 1e-9, 2)})

    # Puente: suma aditiva que aproxima la fórmula del simulador.
    _push_step("Valor transm.", +(valor_tx * factor))
    _push_step("Gastos transm.", -(gastos_tx_total * factor))
    _push_step("Plusvalía", -(plusvalia * factor))
    _push_step("Valor adq.", -(valor_adq * factor))
    _push_step("Gastos adq.", -(gastos_adq_total * factor))
    _push_step("Mejoras", -(mejoras * factor))
    _push_step("Amortiz.", +(amort * factor))

    waterfall_label = "Puente de cálculo (ganancia bruta)"
    if abs(participacion_pct - 100.0) > 1e-6:
        try:
            waterfall_label += f" · participación {participacion_pct:.0f}%"
        except Exception:
            pass
    waterfall_chart = {"kind": "waterfall", "label": waterfall_label, "steps": waterfall_steps}

    exento_val = _money_float(result.get("exento"))
    sujeta_val = _money_float(result.get("ganancia_sujeta"))
    split_bar = {
        "kind": "split_bar",
        "label": "Exenta vs sujeta",
        "items": [
            {"label": "Exenta", "value": round(max(0.0, exento_val) + 1e-9, 2)},
            {"label": "Sujeta", "value": round(max(0.0, sujeta_val) + 1e-9, 2)},
        ],
    }

    def _money_num(raw: object):
        try:
            parsed = parse_money_value(raw)
        except Exception:
            parsed = None
        if parsed is None:
            return None
        try:
            return float(parsed)
        except Exception:
            return None

    def _push_money(lines: list, label: str, raw: object, *, keep_zero: bool = False) -> None:
        val = _money_num(raw)
        if val is None:
            return
        if (not keep_zero) and abs(val) < 1e-9:
            return
        lines.append((label, format_eur(val)))

    def _push_text(lines: list, label: str, raw: object) -> None:
        text = str(raw or "").strip()
        if not text:
            return
        lines.append((label, text))

    # Informe compacto: solo totales + campos relevantes (sin ruido).
    input_lines: list[tuple[str, str]] = []
    input_lines.append(("Régimen fiscal", "IRNR (no residente)" if regimen == "irnr" else "IRPF (residente)"))
    input_lines.append(
        (
            "CCAA aplicable",
            CCAA_LABELS.get(_normalize_ccaa(payload.get("ccaa") or "AN"), _normalize_ccaa(payload.get("ccaa") or "AN")),
        )
    )
    _push_text(input_lines, "Ejercicio", ejercicio)
    input_lines.append(("% participación", pct(payload.get("participacion_pct") or 100)))
    _push_text(input_lines, "Fecha adquisición", date_text(payload.get("fecha_adquisicion")))
    _push_text(input_lines, "Fecha transmisión (devengo)", date_text(payload.get("fecha_transmision")))
    _push_money(input_lines, "Valor adquisición", payload.get("valor_adquisicion"), keep_zero=True)
    _push_money(input_lines, "Valor transmisión", payload.get("valor_transmision"), keep_zero=True)

    _push_money(input_lines, "Gastos adquisición (total)", payload.get("gastos_adquisicion"))
    _push_money(input_lines, "Gastos transmisión (total)", payload.get("gastos_transmision"))

    impuestos_adq = (
        (_money_num(payload.get("gastos_adq_itp")) or 0.0)
        + (_money_num(payload.get("gastos_adq_iva")) or 0.0)
        + (_money_num(payload.get("gastos_adq_ajd")) or 0.0)
    )
    if abs(impuestos_adq) < 1e-9:
        impuestos_adq = _money_num(payload.get("gastos_adq_itp_iva_ajd")) or 0.0
    if impuestos_adq > 0:
        input_lines.append(("Impuestos adquisición (ITP+IVA+AJD)", format_eur(impuestos_adq)))

    # Extras solo si están informados
    _push_money(input_lines, "Plusvalía municipal", payload.get("plusvalia_municipal"))
    _push_money(input_lines, "Mejoras / inversiones", payload.get("inversiones_mejoras"))
    _push_money(input_lines, "Amortización deducida", payload.get("amortizacion_deducida"))
    _push_money(input_lines, "Préstamo pendiente (reinversión)", payload.get("prestamo_pendiente"))

    if bool(payload.get("vivienda_habitual") or False):
        input_lines.append(("Vivienda habitual", "Sí"))
    if str(payload.get("dependencia_grado") or "").strip():
        input_lines.append(("Dependencia", str(payload.get("dependencia_grado") or "").strip()))
    if bool(payload.get("exencion_mayor_65") or False):
        input_lines.append(("Exención >65 (forzar)", "Sí"))
    _push_money(input_lines, "Importe reinvertido", payload.get("importe_reinvertido"))
    _push_money(input_lines, "Comprometido a reinvertir", payload.get("importe_comprometido_reinvertir"))
    output_lines = []
    if regimen == "irnr":
        output_lines.append(("Tipo gravamen IRNR", f"{tipo_gravamen_pct:.3f}%" if tipo_gravamen_pct is not None else "—"))
        output_lines.append(("Retención a cuenta", f"{float(retencion_pct or 0):.2f}%" if retencion_pct is not None else "—"))
    else:
        output_lines.append(("Escala usada", str(escala or "")))
        output_lines.append(("Escala asumida", "Sí" if assumed else "No"))
    _push_money(output_lines, "Valor adquisición (calc.)", result.get("valor_adquisicion_calc"), keep_zero=True)
    _push_money(output_lines, "Valor transmisión (calc.)", result.get("valor_transmision_calc"), keep_zero=True)
    _push_money(output_lines, "Ganancia patrimonial (bruta)", result.get("ganancia_patrimonial"), keep_zero=True)
    _push_money(output_lines, "Exento", result.get("exento"))
    if _money_num(result.get("exento")) and (_money_num(result.get("exento")) or 0) > 0:
        _push_text(output_lines, "Motivo exención", result.get("exencion_motivo"))
    _push_money(output_lines, "Ganancia sujeta (post-exención)", result.get("ganancia_sujeta"), keep_zero=True)
    _push_money(output_lines, "Abatimiento (DT 9ª) · Reducción", (result.get("abatimiento") or {}).get("reduccion_importe"))
    _push_money(output_lines, "Base ahorro sujeta", result.get("base_ahorro_sujeta"), keep_zero=True)
    _push_money(output_lines, "Importe a pagar (estimado)", importe_a_pagar, keep_zero=True)
    if regimen == "irnr":
        _push_money(output_lines, "Retención (importe)", result.get("retencion_importe"))
        _push_money(output_lines, "Cuota neta (cuota - retención)", result.get("cuota_neta"))

    empresa = str(payload.get("empresa_nombre") or "").strip() or "Grupo Modernia"
    ref = str(payload.get("referencia") or payload.get("inmueble_ref") or payload.get("expediente") or "").strip()
    subtitle_parts = [empresa]
    if ref:
        subtitle_parts.append(ref)
    subtitle_parts.append(f"Generado: {format_export_date(datetime.now(timezone.utc).date().isoformat())}")
    subtitle = " · ".join([p for p in subtitle_parts if p])

    footer = [
        "Estimación determinista generada por el CRM. Revisar antes de presentar/firmar.",
        "No sustituye asesoramiento fiscal profesional ni contempla todos los supuestos (mejoras por fecha, valores cotizados especiales, convenios, etc.).",
    ]
    brand = str(payload.get("brand_logo_url") or "").strip() or "/assets/grupo_modernia_logo.png"
    sections = [("Resumen", resumen_cards)]
    # Solo añadimos gráficos si hay datos suficientes.
    if waterfall_steps:
        sections.append(("Gráfico · Ganancia", waterfall_chart))
    if (exento_val + sujeta_val) > 0:
        sections.append(("Gráfico · Exención", split_bar))
    sections.extend(
        [
            ("Datos de entrada", input_lines),
            ("Resultado", output_lines),
        ]
    )
    pdf_bytes = build_modernia_branded_document_pdf(
        "Informe IRPF/IRNR · Ganancia patrimonial",
        subtitle,
        sections,
        footer_lines=footer,
        company={},
        brand_logo_url=brand,
    )
    return pdf_bytes or b""


def build_irpf_ganancia_compare_report_pdf(payload: dict) -> bytes:
    payload = payload or {}
    scenarios = payload.get("scenarios")
    if not isinstance(scenarios, list) or not scenarios:
        raise ValueError("scenarios requerido")

    def money(value: object) -> str:
        raw = "" if value is None else str(value)
        if not raw.strip():
            return "—"
        try:
            parsed = parse_money_value(value)
        except Exception:
            parsed = None
        if parsed is None:
            return raw.strip()
        return format_eur(parsed)

    def _money_num(value: object) -> float:
        try:
            return float(parse_money_value(value or 0) or 0.0)
        except Exception:
            return 0.0

    def _push_money(lines: list, label: str, raw: object, *, keep_zero: bool = False) -> None:
        val = _money_num(raw)
        if val is None:
            return
        if (not keep_zero) and abs(val) < 1e-9:
            return
        lines.append((label, format_eur(val)))

    def _push_text(lines: list, label: str, raw: object) -> None:
        text = str(raw or "").strip()
        if not text:
            return
        lines.append((label, text))

    empresa = str(payload.get("empresa_nombre") or "").strip() or "Grupo Modernia"
    ref = str(payload.get("referencia") or payload.get("inmueble_ref") or payload.get("expediente") or "").strip()
    subtitle_parts = [empresa]
    if ref:
        subtitle_parts.append(ref)
    subtitle_parts.append(f"Generado: {format_export_date(datetime.now(timezone.utc).date().isoformat())}")
    subtitle = " · ".join([p for p in subtitle_parts if p])

    brand = str(payload.get("brand_logo_url") or "").strip() or "/assets/grupo_modernia_logo.png"
    footer = [
        "Estimación determinista generada por el CRM. Revisar antes de presentar/firmar.",
        "Comparativa basada en los datos introducidos en cada escenario. No contempla todos los supuestos.",
    ]

    compare_lines = []
    sections = []
    for idx, scenario in enumerate(scenarios):
        if not isinstance(scenario, dict):
            continue
        slot_label = str(scenario.get("slot") or "").strip().upper()
        if slot_label and len(slot_label) > 6:
            slot_label = slot_label[:6]
        base_name = str(scenario.get("nombre") or scenario.get("name") or "").strip() or f"Escenario {idx + 1}"
        name = f"{slot_label} · {base_name}" if slot_label else base_name
        sp = scenario.get("payload") if isinstance(scenario.get("payload"), dict) else {}
        # Hereda metadatos del informe si no vienen en el escenario.
        if isinstance(sp, dict):
            if payload.get("empresa_nombre") and not sp.get("empresa_nombre"):
                sp["empresa_nombre"] = payload.get("empresa_nombre")
            if payload.get("referencia") and not sp.get("referencia"):
                sp["referencia"] = payload.get("referencia")
            if payload.get("brand_logo_url") and not sp.get("brand_logo_url"):
                sp["brand_logo_url"] = payload.get("brand_logo_url")
        try:
            out = _irpf_ganancia_simulate(sp)
        except ValueError as exc:
            raise ValueError(f"{name}: {str(exc)}") from exc
        params = out.get("params") or {}
        result = out.get("result") or {}
        regimen = str(params.get("regimen_fiscal") or sp.get("regimen_fiscal") or "irpf").strip().lower() or "irpf"
        escala = params.get("escala_ejercicio")
        assumed = bool(params.get("escala_asumida"))
        tipo_gravamen_pct = params.get("tipo_gravamen_pct")
        retencion_pct = params.get("retencion_pct")
        importe = result.get("cuota_ahorro_estimada")
        if regimen == "irnr" and result.get("cuota_neta") is not None:
            importe = result.get("cuota_neta")
        compare_lines.append(
            (
                name,
                " · ".join(
                    [
                        f"Ganancia {money(result.get('ganancia_patrimonial'))}",
                        f"Exento {money(result.get('exento'))}",
                        f"Sujeta {money(result.get('ganancia_sujeta'))}",
                        f"A pagar {money(importe)}",
                    ]
                ),
            )
        )
        resumen_cards = {
            "kind": "kpi_cards",
            "columns": 3,
            "items": [
                {"label": "Días", "value": str(result.get("days_transcurridos") or "—")},
                {"label": "Ganancia", "value": money(result.get("ganancia_patrimonial"))},
                {"label": "Exento", "value": money(result.get("exento"))},
                {"label": "Sujeta", "value": money(result.get("ganancia_sujeta"))},
                {"label": "Base ahorro", "value": money(result.get("base_ahorro_sujeta"))},
                {"label": "A pagar (estimado)", "value": money(importe), "accent": True},
            ],
        }
        input_lines = []
        try:
            _push_text(input_lines, "Régimen fiscal", ("IRNR (no residente)" if regimen == "irnr" else "IRPF (residente)"))
            _push_text(input_lines, "Fecha adquisición", str(sp.get("fecha_adquisicion") or "").strip())
            _push_text(input_lines, "Fecha transmisión (devengo)", str(sp.get("fecha_transmision") or "").strip())
            _push_money(input_lines, "Valor adquisición", sp.get("valor_adquisicion"), keep_zero=True)
            _push_money(input_lines, "Valor transmisión", sp.get("valor_transmision"), keep_zero=True)
            _push_money(input_lines, "Gastos adquisición (total)", sp.get("gastos_adquisicion"))
            _push_money(input_lines, "Gastos transmisión (total)", sp.get("gastos_transmision"))
            _push_money(input_lines, "Plusvalía municipal", sp.get("plusvalia_municipal"))
            _push_money(input_lines, "Mejoras / inversiones", sp.get("inversiones_mejoras"))
            _push_money(input_lines, "Amortización deducida", sp.get("amortizacion_deducida"))
            if bool(sp.get("vivienda_habitual") or False):
                input_lines.append(("Vivienda habitual", "Sí"))
            if str(sp.get("dependencia_grado") or "").strip():
                input_lines.append(("Dependencia", str(sp.get("dependencia_grado") or "").strip()))
            if bool(sp.get("exencion_mayor_65") or False):
                input_lines.append(("Exención >65 (forzar)", "Sí"))
            _push_money(input_lines, "Importe reinvertido", sp.get("importe_reinvertido"))
            _push_money(input_lines, "Comprometido a reinvertir", sp.get("importe_comprometido_reinvertir"))
        except Exception:
            input_lines = input_lines or []

        output_lines = []
        try:
            if regimen == "irnr":
                output_lines.append(("Tipo gravamen IRNR", f"{tipo_gravamen_pct:.3f}%" if tipo_gravamen_pct is not None else "—"))
                output_lines.append(("Retención a cuenta", f"{float(retencion_pct or 0):.2f}%" if retencion_pct is not None else "—"))
            else:
                output_lines.append(("Escala usada", str(escala or "")))
                output_lines.append(("Escala asumida", "Sí" if assumed else "No"))
            _push_money(output_lines, "Valor adquisición (calc.)", result.get("valor_adquisicion_calc"), keep_zero=True)
            _push_money(output_lines, "Valor transmisión (calc.)", result.get("valor_transmision_calc"), keep_zero=True)
            _push_money(output_lines, "Ganancia patrimonial (bruta)", result.get("ganancia_patrimonial"), keep_zero=True)
            _push_money(output_lines, "Exento", result.get("exento"))
            if (_money_num(result.get("exento")) or 0.0) > 0:
                _push_text(output_lines, "Motivo exención", result.get("exencion_motivo"))
            _push_money(output_lines, "Ganancia sujeta (post-exención)", result.get("ganancia_sujeta"), keep_zero=True)
            _push_money(output_lines, "Abatimiento (DT 9ª) · Reducción", (result.get("abatimiento") or {}).get("reduccion_importe"))
            _push_money(output_lines, "Base ahorro sujeta", result.get("base_ahorro_sujeta"), keep_zero=True)
            _push_money(output_lines, "A pagar (estimado)", importe, keep_zero=True)
            if regimen == "irnr":
                _push_money(output_lines, "Retención (importe)", result.get("retencion_importe"))
                _push_money(output_lines, "Cuota neta (cuota - retención)", result.get("cuota_neta"))
        except Exception:
            output_lines = output_lines or []

        sections.append((f"Escenario · {name} · Resumen", resumen_cards))
        if input_lines:
            sections.append((f"Escenario · {name} · Datos de entrada", input_lines))
        if output_lines:
            sections.append((f"Escenario · {name} · Resultado", output_lines))

    if not sections:
        raise ValueError("No hay escenarios válidos para comparar")

    sections.insert(0, ("Comparativa", compare_lines))
    pdf_bytes = build_modernia_branded_document_pdf(
        "Informe comparativo IRPF/IRNR · Ganancia patrimonial",
        subtitle,
        sections,
        footer_lines=footer,
        company={},
        brand_logo_url=brand,
    )
    return pdf_bytes or b""


def build_fiscal_venta_report_pdf(payload: dict, irpf_out: dict, iivtnu_out: dict) -> bytes:
    payload = payload or {}
    irpf_out = irpf_out or {}
    iivtnu_out = iivtnu_out or {}

    irpf_payload = payload.get("irpf_payload") if isinstance(payload.get("irpf_payload"), dict) else {}
    iivtnu_payload = payload.get("iivtnu_payload") if isinstance(payload.get("iivtnu_payload"), dict) else {}

    irpf_params = irpf_out.get("params") or {}
    irpf_result = irpf_out.get("result") or {}
    iiv_params = iivtnu_out.get("params") or {}
    iiv_result = iivtnu_out.get("result") or {}

    ccaa = _normalize_ccaa(payload.get("ccaa") or irpf_params.get("ccaa") or irpf_payload.get("ccaa") or "AN")
