def import_category_is_expense(category):
    return normalize_lookup_text(category or "") in {
        "SEGURO LOCAL",
        "SEGURO RC",
        "ALQUILER LOCAL",
        "SALARIOS",
        "SUMINISTROS",
        "LOPD",
        "PRL",
        "CANAL DE DENUNCIAS",
        "SEGURO CONVENIO",
        "GESTORIA",
        "SALUD",
        "ILT",
    }


def import_number_is_suspicious(value):
    token = normalize_lookup_text(value or "")
    if not token:
        return False
    if token in {"PAGADO", "EMITIDA", "CALLE", "SIMPLIFICADA", "FACTURA", "GAPP", "ORIGINAL"}:
        return True
    if not any(ch.isdigit() for ch in token):
        return True
    if re.fullmatch(r"\d{1,2}", token):
        return True
    if re.fullmatch(r"\d{4}", token):
        return True
    return False


def import_vendor_is_suspicious(value):
    token = normalize_lookup_text(value or "")
    if not token:
        return True
    if token in {"Q", "QO", "ORIGINAL", "PAGADO", "EMITIDA", "MES FEBRERO"}:
        return True
    letters = re.sub(r"[^A-Z]", "", token)
    if len(letters) <= 2:
        return True
    return False


def import_vat_is_implausible(base, cuota_iva, total):
    base = float(base or 0.0)
    cuota_iva = float(cuota_iva or 0.0)
    total = float(total or 0.0)
    if cuota_iva < 0:
        return True
    if cuota_iva <= 0:
        return False
    if total > 0 and cuota_iva > total + 0.01:
        return True
    if base > 0:
        if cuota_iva / max(base, 0.01) > 0.30:
            return True
        if total > 0 and abs((base + cuota_iva) - total) > max(1.0, total * 0.15):
            return True
    return False


def validate_import_document_for_apply(document_row):
    if not isinstance(document_row, dict):
        document_row = dict(document_row)
    reasons = []
    categoria = str(document_row.get("categoria_detectada") or "").strip()
    tipo = str(document_row.get("tipo_detectado") or "compra").strip().lower()
    numero = str(document_row.get("numero_detectado") or "").strip()
    tercero = str(document_row.get("tercero_detectado") or "").strip()
    base = parse_money_value(document_row.get("base_detectada"))
    cuota_iva = parse_money_value(document_row.get("cuota_iva_detectada"))
    total = parse_money_value(document_row.get("total_detectado"))
    if import_category_is_expense(categoria) and tipo == "venta":
        reasons.append("tipo_venta_en_gasto")
    if total <= 0 and base <= 0:
        reasons.append("importe_invalido")
    if import_vat_is_implausible(base, cuota_iva, total):
        reasons.append("iva_inverosimil")
    if import_number_is_suspicious(numero):
        reasons.append("numero_dudoso")
    if import_vendor_is_suspicious(tercero):
        reasons.append("proveedor_dudoso")
    return reasons


def describe_import_record(record):
    numero = str(record.get("numero_detectado") or record.get("numero") or "").strip()
    tercero = str(record.get("tercero_detectado") or record.get("tercero") or "").strip()
    categoria = str(record.get("categoria_detectada") or record.get("categoria_excel") or "").strip()
    archivo = str(record.get("archivo_nombre") or record.get("archivo") or "").strip()
    concept_parts = [part for part in (numero, tercero or categoria or archivo) if part]
    return " · ".join(concept_parts) or "Factura importada"


def ensure_gestoria_import_schema(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_lotes (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          origen TEXT,
          estado TEXT NOT NULL,
          periodo TEXT,
          carpeta_origen TEXT,
          template_path TEXT,
          total_documentos INTEGER NOT NULL DEFAULT 0,
          total_ok INTEGER NOT NULL DEFAULT 0,
          total_revisar INTEGER NOT NULL DEFAULT 0,
          total_duplicado INTEGER NOT NULL DEFAULT 0,
          total_error INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_documentos (
          id TEXT PRIMARY KEY,
          lote_id TEXT NOT NULL,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          factura_id TEXT,
          tercero_id TEXT,
          gestoria_doc_id TEXT,
          archivo_nombre TEXT NOT NULL,
          archivo_hash TEXT,
          doc_key TEXT,
          numero_detectado TEXT,
          fecha_detectada TEXT,
          tercero_detectado TEXT,
          nif_detectado TEXT,
          base_detectada REAL,
          cuota_iva_detectada REAL,
          total_detectado REAL,
          tipo_detectado TEXT,
          categoria_detectada TEXT,
          subcategoria_detectada TEXT,
          cuenta_sugerida TEXT,
          cuenta_tercero_sugerida TEXT,
          confianza_categoria REAL,
          confianza_extraccion REAL,
          estado_revision TEXT NOT NULL,
          motivos_revision TEXT,
          regla_aplicada TEXT,
          ocr_metodo TEXT,
          ocr_error TEXT,
          raw_text TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (lote_id) REFERENCES gestoria_import_lotes(id),
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id),
          FOREIGN KEY (factura_id) REFERENCES gestoria_facturas(id),
          FOREIGN KEY (tercero_id) REFERENCES gestoria_terceros(id),
          FOREIGN KEY (gestoria_doc_id) REFERENCES gestoria_docs(id)
        )
        """
    )
    conn.execute(
        """
        CREATE UNIQUE INDEX IF NOT EXISTS idx_gestoria_import_documentos_lote_archivo
        ON gestoria_import_documentos (lote_id, archivo_nombre)
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_documentos_estado
        ON gestoria_import_documentos (estado_revision)
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_documentos_hash
        ON gestoria_import_documentos (archivo_hash)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_reglas (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          ambito TEXT NOT NULL,
          prioridad INTEGER NOT NULL DEFAULT 100,
          activo INTEGER NOT NULL DEFAULT 1,
          proveedor_match TEXT,
          proveedor_nif_match TEXT,
          texto_match TEXT,
          categoria_forzada TEXT,
          tercero_nombre_forzado TEXT,
          tercero_nif_forzado TEXT,
          cuenta_gasto_forzada TEXT,
          cuenta_tercero_forzada TEXT,
          iva_pct_forzado REAL,
          auto_ok INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_reglas_scope
        ON gestoria_import_reglas (empresa_id, cliente_id, activo, prioridad)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_eventos (
          id TEXT PRIMARY KEY,
          lote_id TEXT NOT NULL,
          documento_id TEXT,
          factura_id TEXT,
          tipo TEXT NOT NULL,
          detalle TEXT,
          payload_json TEXT,
          created_at TEXT NOT NULL,
          FOREIGN KEY (lote_id) REFERENCES gestoria_import_lotes(id),
          FOREIGN KEY (documento_id) REFERENCES gestoria_import_documentos(id),
          FOREIGN KEY (factura_id) REFERENCES gestoria_facturas(id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_eventos_lote
        ON gestoria_import_eventos (lote_id, created_at)
        """
    )
    # Compat: el importador usa campos de deduplicación/hash en `gestoria_facturas`.
    # En datasets legacy/tests la tabla puede existir sin estas columnas.
    try:
        ensure_column(conn, "gestoria_facturas", "archivo_hash", "archivo_hash TEXT")
    except Exception:
        pass
    try:
        ensure_column(conn, "gestoria_facturas", "dedupe_key", "dedupe_key TEXT")
    except Exception:
        pass


def log_gestoria_import_event(conn, lote_id, tipo, now, documento_id=None, factura_id=None, detalle=None, payload=None):
    conn.execute(
        """
        INSERT INTO gestoria_import_eventos (
          id, lote_id, documento_id, factura_id, tipo, detalle, payload_json, created_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            lote_id,
            documento_id,
            factura_id,
            tipo,
            detalle,
            json.dumps(payload, ensure_ascii=False) if payload is not None else None,
            now,
        ),
    )


def refresh_gestoria_import_lote_totals(conn, lote_id, now):
    summary = conn.execute(
        """
        SELECT
          COUNT(*) AS total_documentos,
          SUM(CASE WHEN estado_revision = 'OK' THEN 1 ELSE 0 END) AS total_ok,
          SUM(CASE WHEN estado_revision = 'REVISAR' THEN 1 ELSE 0 END) AS total_revisar,
          SUM(CASE WHEN estado_revision = 'DUPLICADO' THEN 1 ELSE 0 END) AS total_duplicado,
          SUM(CASE WHEN estado_revision = 'ERROR' THEN 1 ELSE 0 END) AS total_error
        FROM gestoria_import_documentos
        WHERE lote_id = ?
        """,
        (lote_id,),
    ).fetchone()
    if not summary:
        summary = {
            "total_documentos": 0,
            "total_ok": 0,
            "total_revisar": 0,
            "total_duplicado": 0,
            "total_error": 0,
        }
    total_ok = int(summary["total_ok"] or 0)
    total_revisar = int(summary["total_revisar"] or 0)
    total_duplicado = int(summary["total_duplicado"] or 0)
    total_error = int(summary["total_error"] or 0)
    if total_error > 0:
        estado = "con_errores"
    elif total_revisar > 0:
        estado = "pendiente_revision"
    elif total_ok > 0:
        estado = "preparado"
    else:
        estado = "vacio"
    extra = conn.execute(
        """
        SELECT
          COUNT(DISTINCT CASE WHEN COALESCE(tercero_id, '') <> '' THEN tercero_id END) AS total_terceros,
          COUNT(DISTINCT CASE WHEN COALESCE(cuenta_sugerida, '') <> '' THEN cuenta_sugerida END) AS total_cuentas,
          COUNT(DISTINCT CASE WHEN COALESCE(factura_id, '') <> '' THEN factura_id END) AS total_facturas_vinculadas
        FROM gestoria_import_documentos
        WHERE lote_id = ?
        """,
        (lote_id,),
    ).fetchone()
    total_terceros = int((extra["total_terceros"] if extra else 0) or 0)
    total_cuentas = int((extra["total_cuentas"] if extra else 0) or 0)
    total_asientos = int(summary["total_documentos"] or 0)
    total_pendientes = max(0, total_revisar + total_duplicado + total_error)
    valoracion_json = json.dumps(
        {
            "estado": estado,
            "asientos": total_asientos,
            "terceros": total_terceros,
            "cuentas": total_cuentas,
            "pendientes": total_pendientes,
            "facturas_vinculadas": int((extra["total_facturas_vinculadas"] if extra else 0) or 0),
        },
        ensure_ascii=False,
    )
    conn.execute(
        """
        UPDATE gestoria_import_lotes
        SET total_documentos = ?,
            total_ok = ?,
            total_revisar = ?,
            total_duplicado = ?,
            total_error = ?,
            valoracion_estado = COALESCE(valoracion_estado, ?),
            valoracion_json = ?,
            valoracion_total_asientos = ?,
            valoracion_total_terceros = ?,
            valoracion_total_cuentas = ?,
            valoracion_total_pendientes = ?,
            estado = ?,
            updated_at = datetime(?)
        WHERE id = ?
        """,
        (
            int(summary["total_documentos"] or 0),
            total_ok,
            total_revisar,
            total_duplicado,
            total_error,
            estado,
            valoracion_json,
            total_asientos,
            total_terceros,
            total_cuentas,
            total_pendientes,
            estado,
            now,
            lote_id,
        ),
    )
    row = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
    return dict(row) if row else None


def upsert_gestoria_import_document(conn, lote_id, empresa_id, default_cliente_id, record, now):
    archivo_nombre = str(record.get("archivo_nombre") or record.get("archivo") or "").strip()
    if not archivo_nombre:
        raise ValueError("archivo_nombre requerido")
    existing = conn.execute(
        """
        SELECT id, factura_id, tercero_id, gestoria_doc_id, created_at
        FROM gestoria_import_documentos
        WHERE lote_id = ? AND archivo_nombre = ?
        LIMIT 1
        """,
        (lote_id, archivo_nombre),
    ).fetchone()
    document_id = existing["id"] if existing else os.urandom(16).hex()
    cliente_id = str(record.get("cliente_id") or default_cliente_id or "").strip() or None
    categoria = str(record.get("categoria_detectada") or record.get("categoria_excel") or "").strip()
    tipo = str(record.get("tipo_detectado") or record.get("tipo") or "compra").strip().lower() or "compra"
    estado = normalize_import_review_state(record.get("estado_revision"))
    motivos = normalize_import_reasons(record.get("motivos_revision"))
    cuenta_sugerida = str(record.get("cuenta_sugerida") or "").strip() or map_import_category_to_account(categoria)
    cuenta_tercero = str(record.get("cuenta_tercero_sugerida") or "").strip()
    numero = str(record.get("numero_detectado") or record.get("numero") or "").strip()
    fecha = str(record.get("fecha_detectada") or record.get("fecha") or "").strip()
    tercero = str(record.get("tercero_detectado") or record.get("tercero") or "").strip()
    nif = str(record.get("nif_detectado") or record.get("nif") or "").strip().upper()
    base = round(parse_money_value(record.get("base_detectada") if "base_detectada" in record else record.get("base_imponible")), 2)
    cuota_iva = round(parse_money_value(record.get("cuota_iva_detectada") if "cuota_iva_detectada" in record else record.get("cuota_iva")), 2)
    total = round(parse_money_value(record.get("total_detectado") if "total_detectado" in record else record.get("total")), 2)
    if total <= 0:
        total = round(parse_money_value(record.get("importe_agregado")), 2)
    confianza_categoria = parse_confidence_value(record.get("confianza_categoria"))
    confianza_extraccion = parse_confidence_value(record.get("confianza_extraccion"))
    if confianza_extraccion <= 0:
        confianza_extraccion = 1.0 if total > 0 else 0.0
    raw_text = str(record.get("raw_text") or record.get("descripcion") or "").strip()
    archivo_hash = str(record.get("archivo_hash") or "").strip() or None
    # Detección de duplicados (soft): por hash de archivo y por firma de factura.
    # Esto permite importación incremental sin ir generando duplicados cuando el cliente sube
    # documentos poco a poco.
    try:
        if archivo_hash and estado != "DUPLICADO":
            dup_doc = conn.execute(
                """
                SELECT id
                FROM gestoria_import_documentos
                WHERE empresa_id = ? AND archivo_hash = ? AND id != ?
                LIMIT 1
                """,
                (empresa_id, archivo_hash, document_id),
            ).fetchone()
            if dup_doc:
                estado = "DUPLICADO"
                motivos = normalize_import_reasons((motivos + ",duplicado_hash") if motivos else "duplicado_hash")
    except Exception:
        pass
    try:
        if estado != "DUPLICADO":
            firma = compute_gestoria_factura_dedupe_key(
                empresa_id=empresa_id,
                cliente_id=cliente_id,
                tipo=tipo,
                tercero_nif=nif,
                tercero_nombre=tercero,
                numero=numero,
                fecha_emision=fecha,
                total=total,
                base=base,
                cuota_iva=cuota_iva,
            )
            if firma:
                dup_fact = conn.execute(
                    """
                    SELECT id
                    FROM gestoria_facturas
                    WHERE empresa_id = ? AND COALESCE(cliente_id, '') = COALESCE(?, '') AND dedupe_key = ?
                    LIMIT 1
                    """,
                    (empresa_id, cliente_id or "", firma),
                ).fetchone()
                if dup_fact:
                    estado = "DUPLICADO"
                    motivos = normalize_import_reasons((motivos + ",duplicado_factura") if motivos else "duplicado_factura")
    except Exception:
        pass
    values = (
        document_id,
        lote_id,
        empresa_id,
        cliente_id,
        existing["factura_id"] if existing else None,
        existing["tercero_id"] if existing else None,
        existing["gestoria_doc_id"] if existing else None,
        archivo_nombre,
        archivo_hash,
        str(record.get("doc_key") or "").strip() or None,
        numero or None,
        fecha or None,
        tercero or None,
        nif or None,
        base,
        cuota_iva,
        total,
        tipo,
        categoria or None,
        str(record.get("subcategoria_detectada") or record.get("subcategoria") or "").strip() or None,
        cuenta_sugerida or None,
        cuenta_tercero or None,
        confianza_categoria,
        confianza_extraccion,
        estado,
        motivos or None,
        str(record.get("regla_aplicada") or record.get("motivo_categoria") or "").strip() or None,
        str(record.get("ocr_metodo") or "").strip() or None,
        str(record.get("ocr_error") or "").strip() or None,
        raw_text or None,
        existing["created_at"] if existing else now,
        now,
    )
    if getattr(conn, "__crm_backend__", "") == "postgres":
        conn.execute(
            """
            INSERT INTO gestoria_import_documentos (
              id, lote_id, empresa_id, cliente_id, factura_id, tercero_id, gestoria_doc_id,
              archivo_nombre, archivo_hash, doc_key, numero_detectado, fecha_detectada,
              tercero_detectado, nif_detectado, base_detectada, cuota_iva_detectada,
              total_detectado, tipo_detectado, categoria_detectada, subcategoria_detectada,
              cuenta_sugerida, cuenta_tercero_sugerida, confianza_categoria, confianza_extraccion,
              estado_revision, motivos_revision, regla_aplicada, ocr_metodo, ocr_error, raw_text,
              created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            ON CONFLICT (id) DO UPDATE SET
              lote_id = EXCLUDED.lote_id,
              empresa_id = EXCLUDED.empresa_id,
              cliente_id = EXCLUDED.cliente_id,
              factura_id = EXCLUDED.factura_id,
              tercero_id = EXCLUDED.tercero_id,
              gestoria_doc_id = EXCLUDED.gestoria_doc_id,
              archivo_nombre = EXCLUDED.archivo_nombre,
              archivo_hash = EXCLUDED.archivo_hash,
              doc_key = EXCLUDED.doc_key,
              numero_detectado = EXCLUDED.numero_detectado,
              fecha_detectada = EXCLUDED.fecha_detectada,
              tercero_detectado = EXCLUDED.tercero_detectado,
              nif_detectado = EXCLUDED.nif_detectado,
              base_detectada = EXCLUDED.base_detectada,
              cuota_iva_detectada = EXCLUDED.cuota_iva_detectada,
              total_detectado = EXCLUDED.total_detectado,
              tipo_detectado = EXCLUDED.tipo_detectado,
              categoria_detectada = EXCLUDED.categoria_detectada,
              subcategoria_detectada = EXCLUDED.subcategoria_detectada,
              cuenta_sugerida = EXCLUDED.cuenta_sugerida,
              cuenta_tercero_sugerida = EXCLUDED.cuenta_tercero_sugerida,
              confianza_categoria = EXCLUDED.confianza_categoria,
              confianza_extraccion = EXCLUDED.confianza_extraccion,
              estado_revision = EXCLUDED.estado_revision,
              motivos_revision = EXCLUDED.motivos_revision,
              regla_aplicada = EXCLUDED.regla_aplicada,
              ocr_metodo = EXCLUDED.ocr_metodo,
              ocr_error = EXCLUDED.ocr_error,
              raw_text = EXCLUDED.raw_text,
              created_at = EXCLUDED.created_at,
              updated_at = EXCLUDED.updated_at
            """,
            values,
        )
    else:
        conn.execute(
            """
            INSERT OR REPLACE INTO gestoria_import_documentos (
              id, lote_id, empresa_id, cliente_id, factura_id, tercero_id, gestoria_doc_id,
              archivo_nombre, archivo_hash, doc_key, numero_detectado, fecha_detectada,
              tercero_detectado, nif_detectado, base_detectada, cuota_iva_detectada,
              total_detectado, tipo_detectado, categoria_detectada, subcategoria_detectada,
              cuenta_sugerida, cuenta_tercero_sugerida, confianza_categoria, confianza_extraccion,
              estado_revision, motivos_revision, regla_aplicada, ocr_metodo, ocr_error, raw_text,
              created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            values,
        )
    return document_id


def compute_gestoria_factura_dedupe_key(
    *,
    empresa_id="",
    cliente_id="",
    tipo="",
    tercero_nif="",
    tercero_nombre="",
    numero="",
    fecha_emision="",
    total=0.0,
    base=0.0,
    cuota_iva=0.0,
) -> str:
    empresa_id = str(empresa_id or "").strip()
    if not empresa_id:
        return ""
    total_value = round(parse_money_value(total), 2)
    if total_value <= 0:
        return ""
    fecha_emision = str(fecha_emision or "").strip()
    if not fecha_emision:
        return ""
    numero = str(numero or "").strip()
    tercero_nif = str(tercero_nif or "").strip().upper()
    tercero_nombre = str(tercero_nombre or "").strip()
    if not (numero or tercero_nif or tercero_nombre):
        return ""
    payload = "|".join(
        [
            normalize_lookup_text(empresa_id),
            normalize_lookup_text(str(cliente_id or "")),
            normalize_lookup_text(str(tipo or "")),
            normalize_lookup_text(tercero_nif),
            normalize_lookup_text(tercero_nombre),
            normalize_lookup_text(numero),
            normalize_lookup_text(fecha_emision),
            f"{total_value:.2f}",
            f"{round(parse_money_value(base), 2):.2f}",
            f"{round(parse_money_value(cuota_iva), 2):.2f}",
        ]
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def ensure_factura_doc_link(
    conn,
    *,
    empresa_id,
    cliente_id,
    factura_id,
    doc_key="",
    doc_url="",
    nombre="",
    fecha="",
    estado="Recibido",
    notas="",
    calidad_ocr=None,
    campos_ocr="",
    now,
):
    empresa_id = str(empresa_id or "").strip()
    factura_id = str(factura_id or "").strip()
    if not empresa_id or not factura_id:
        return None
    doc_key = str(doc_key or "").strip()
    doc_url = str(doc_url or "").strip()
    if not doc_key and not doc_url:
        return None
    where = ["empresa_id = ?", "LOWER(COALESCE(referencia_tipo, '')) = 'facturas'"]
    values = [empresa_id]
    if cliente_id:
        where.append("cliente_id = ?")
        values.append(str(cliente_id).strip())
    key_or_url = []
    if doc_key:
        key_or_url.append("doc_key = ?")
        values.append(doc_key)
    if doc_url:
        key_or_url.append("doc_url = ?")
        values.append(doc_url)
    if key_or_url:
        where.append(f"({' OR '.join(key_or_url)})")
    exists = conn.execute(
        f"SELECT id FROM gestoria_docs WHERE {' AND '.join(where)} LIMIT 1",
        values,
    ).fetchone()
    if exists:
        conn.execute(
            """
            UPDATE gestoria_docs
            SET referencia_id = COALESCE(?, referencia_id),
                repo_key = COALESCE(NULLIF(?, ''), repo_key),
                nombre = COALESCE(NULLIF(?, ''), nombre),
                tipo = COALESCE(NULLIF(?, ''), tipo),
                fecha = COALESCE(NULLIF(?, ''), fecha),
                estado = COALESCE(NULLIF(?, ''), estado),
                notas = COALESCE(NULLIF(?, ''), notas),
                doc_key = COALESCE(NULLIF(?, ''), doc_key),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                calidad_ocr = COALESCE(NULLIF(?, ''), calidad_ocr),
                campos_ocr = COALESCE(NULLIF(?, ''), campos_ocr),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                factura_id,
                "factura",
                nombre or "Factura",
                "Factura",
                fecha or "",
                estado or "",
                notas or "",
                doc_key or "",
                doc_url or "",
                str(calidad_ocr or ""),
                str(campos_ocr or ""),
                now,
                exists["id"],
            ),
        )
        return exists["id"]
    doc_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_docs (
          id, empresa_id, cliente_id, repo_key, referencia_tipo, referencia_id,
          nombre, tipo, fecha, estado, notas, doc_key, doc_url,
          calidad_ocr, campos_ocr, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            doc_id,
            empresa_id,
            str(cliente_id or "").strip() or None,
            "factura",
            "facturas",
            factura_id,
            nombre or "Factura",
            "Factura",
            fecha or "",
            estado or "Recibido",
            notas or "",
            doc_key or None,
            doc_url or None,
            str(calidad_ocr or "") if calidad_ocr is not None else None,
            str(campos_ocr or ""),
            now,
            now,
        ),
    )
    return doc_id


def reconcile_gestoria_factura_asiento(conn, factura_row, now, *, auto_link=True, lookback_days=7, historico_cerrado=False):
    if not factura_row:
        return None
    if not isinstance(factura_row, dict):
        factura_row = dict(factura_row)
    factura_id = str(factura_row.get("id") or "").strip()
    empresa_id = str(factura_row.get("empresa_id") or "").strip()
    cliente_id = str(factura_row.get("cliente_id") or "").strip()
    if not factura_id or not empresa_id:
        return None
    factura = conn.execute(
        """
        SELECT
          f.*,
          COALESCE(t.nombre, '') AS tercero_nombre,
          COALESCE(t.nif, '') AS tercero_nif,
          COALESCE(t.cuenta_contable, '') AS tercero_cuenta
        FROM gestoria_facturas f
        LEFT JOIN gestoria_terceros t ON t.id = f.tercero_id
        WHERE f.id = ?
        LIMIT 1
        """,
        (factura_id,),
    ).fetchone()
    if not factura:
        return None
    existing_asiento = conn.execute(
        "SELECT id, fecha, concepto, referencia, diario FROM gestoria_asientos WHERE factura_id = ? LIMIT 1",
        (factura_id,),
    ).fetchone()
    existing_asiento_is_auto = bool(existing_asiento and str(existing_asiento["diario"] or "").strip().upper() == "FACT")
    if existing_asiento and not (historico_cerrado and existing_asiento_is_auto):
        try:
            learn_gestoria_factura_rule(conn, factura, existing_asiento, None, now=now)
        except Exception:
            pass
        return {
            "ok": True,
            "factura_id": factura_id,
            "asiento_id": existing_asiento["id"],
            "matched": True,
            "linked": True,
            "score": 100,
            "reason": "ya_vinculada",
        }

    def _create_auto_asiento_from_factura():
        parsed_factura = {
            "tipo": str(factura["tipo"] or "compra").strip().lower() or "compra",
            "numero": str(factura["numero"] or "").strip(),
            "fecha": fecha_factura or str(factura["fecha_emision"] or "").strip(),
            "nif": str(factura["tercero_nif"] or "").strip().upper(),
            "tercero": str(factura["tercero_nombre"] or "").strip(),
            "base_imponible": round(parse_money_value(factura["base_imponible"] or 0.0), 2),
            "base_exenta": round(parse_money_value(factura["base_exenta"] or 0.0), 2),
            "base_no_sujeta": round(parse_money_value(factura["base_no_sujeta"] or 0.0), 2),
            "cuota_iva": round(parse_money_value(factura["cuota_iva"] or 0.0), 2),
            "cuota_irpf": round(parse_money_value(factura["cuota_irpf"] or 0.0), 2),
            "total": round(parse_money_value(factura["total"] or 0.0), 2),
            "iva_pct": round(parse_money_value(factura["iva_pct"] or 0.0), 2),
            "tipo_operacion": str(factura["tipo_operacion"] or "").strip().lower(),
            "descripcion": str(factura["descripcion"] or factura["numero"] or "Factura").strip(),
            "raw_text": str(factura["raw_text"] or "").strip(),
        }
        tercero_id = str(factura["tercero_id"] or "").strip() or None
        counterpart_account = str(factura["tercero_cuenta"] or "").strip()
        if not counterpart_account:
            third_type = "cliente" if parsed_factura["tipo"] == "venta" else ("proveedor" if parsed_factura["numero"] else "acreedor")
            tercero_id, counterpart_account = ensure_gestoria_tercero(
                conn,
                empresa_id,
                parsed_factura.get("nif"),
                parsed_factura.get("tercero"),
                third_type,
                now,
            )
        if not counterpart_account:
            counterpart_account = "430" if parsed_factura["tipo"] == "venta" else "400"
        lines, total_debe, total_haber = build_invoice_asiento(parsed_factura, counterpart_account)
        factura_id_new = factura_id
        asiento_id = os.urandom(16).hex()
        referencia = parsed_factura["numero"] or factura_id_new
        conn.execute(
            """
            INSERT INTO gestoria_asientos (
              id, empresa_id, cliente_id, factura_id, fecha, concepto, diario, referencia,
              total_debe, total_haber, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                asiento_id,
                empresa_id,
                cliente_id or None,
                factura_id_new,
                parsed_factura["fecha"] or fecha_factura or now[:10],
                parsed_factura["descripcion"] or "Factura",
                "FACT",
                referencia,
                total_debe,
                total_haber,
                now,
                now,
            ),
        )
        for item in lines:
            conn.execute(
                """
                INSERT INTO gestoria_asiento_lineas (
                  id, asiento_id, tercero_id, cuenta, descripcion, debe, haber,
                  impuesto_tipo, impuesto_pct, created_at, updated_at
                ) VALUES (
                  ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    asiento_id,
                    tercero_id,
                    item.get("cuenta"),
                    item.get("descripcion"),
                    item.get("debe") or 0.0,
                    item.get("haber") or 0.0,
                    item.get("impuesto"),
                    item.get("porcentaje"),
                    now,
                    now,
                ),
            )
        try:
            learn_gestoria_factura_rule(conn, factura, {"id": asiento_id, "fecha": parsed_factura["fecha"]}, lines, now=now)
        except Exception:
            pass
        try:
            conn.execute(
                "UPDATE gestoria_facturas SET asiento_auto = 1, updated_at = datetime(?) WHERE id = ?",
                (now, factura_id_new),
            )
        except Exception:
            pass
        return {
            "ok": True,
            "factura_id": factura_id_new,
            "asiento_id": asiento_id,
            "matched": False,
            "linked": True,
            "created": True,
            "score": 0,
            "reason": "auto_creado",
            "asiento_fecha": parsed_factura["fecha"] or fecha_factura or "",
            "asiento_referencia": referencia,
            "asiento_concepto": parsed_factura["descripcion"] or "Factura",
        }

    fecha_factura = str(factura["fecha_emision"] or "").strip()
    factura_total = round(parse_money_value(factura["total"] or 0), 2)
    factura_numero = str(factura["numero"] or "").strip()
    factura_tipo = normalize_service_key(factura["tipo"] or "")
    factura_nif = normalize_lookup_text(factura["tercero_nif"] or "")
    factura_nombre = normalize_lookup_text(factura["tercero_nombre"] or "")
    factura_raw_lookup = normalize_lookup_text(
        " ".join(
            [
                str(factura["raw_text"] or ""),
                factura_nombre or "",
                factura_numero or "",
            ]
        )
    )
    guessed_fields = guess_gestoria_invoice_fields_from_raw_text(factura["raw_text"] or "")
    guessed_fecha = str(guessed_fields.get("fecha") or "").strip()
    guessed_numero = str(guessed_fields.get("numero") or "").strip()
    guessed_total = round(parse_money_value(guessed_fields.get("total") or 0), 2) if guessed_fields.get("total") not in (None, "") else 0.0
    if guessed_fecha and (
        not fecha_factura
        or fecha_factura[:4] not in {"2023", "2024"}
        or fecha_factura.startswith("2025")
        or fecha_factura.startswith("2026")
    ):
        fecha_factura = guessed_fecha
    if guessed_numero and (not factura_numero or len(factura_numero) < 2):
        factura_numero = guessed_numero
    if guessed_total > 0:
        ratio_ok = factura_total <= 0
        if factura_total > 0:
            ratio = guessed_total / factura_total if factura_total else 0
            ratio_ok = 0.5 <= ratio <= 2.0
        if ratio_ok:
            factura_total = guessed_total
    match_threshold = 28 if historico_cerrado else 50
    fecha_desde = ""
    fecha_hasta = ""
    if fecha_factura:
        try:
            dt_fact = datetime.strptime(fecha_factura[:10], "%Y-%m-%d")
            fecha_desde = (dt_fact - timedelta(days=max(0, int(lookback_days or 0)))).strftime("%Y-%m-%d")
            fecha_hasta = (dt_fact + timedelta(days=max(0, int(lookback_days or 0)))).strftime("%Y-%m-%d")
        except Exception:
            fecha_desde = fecha_factura
            fecha_hasta = fecha_factura
    where = [
        "a.empresa_id = ?",
        "COALESCE(a.factura_id, '') = ''",
    ]
    values = [empresa_id]
    if cliente_id:
        where.append("COALESCE(a.cliente_id, '') = ?")
        values.append(cliente_id)
    if historico_cerrado:
        where.append("COALESCE(a.diario, '') <> 'FACT'")
    if fecha_desde:
        where.append("a.fecha >= ?")
        values.append(fecha_desde)
    if fecha_hasta:
        where.append("a.fecha <= ?")
        values.append(fecha_hasta)
    if factura_total > 0:
        tolerance = max(1.0, round(factura_total * 0.03, 2))
        where.append("(ABS(COALESCE(a.total_debe, 0) - ?) <= ? OR ABS(COALESCE(a.total_haber, 0) - ?) <= ?)")
        values.extend([factura_total, tolerance, factura_total, tolerance])
    candidates = conn.execute(
        f"""
        SELECT a.id, a.fecha, a.concepto, a.referencia, a.total_debe, a.total_haber, a.diario
        FROM gestoria_asientos a
        WHERE {' AND '.join(where)}
        ORDER BY a.fecha ASC, a.created_at ASC
        LIMIT 200
        """,
        values,
    ).fetchall()

    def _candidate_score(asiento_row, line_rows):
        score = 0
        asiento_total = round(max(parse_money_value(asiento_row["total_debe"] or 0), parse_money_value(asiento_row["total_haber"] or 0)), 2)
        if factura_total > 0 and asiento_total > 0:
            diff = abs(factura_total - asiento_total)
            if diff <= 0.01:
                score += 70
            elif diff <= max(0.5, factura_total * 0.005):
                score += 55
            elif diff <= max(2.0, factura_total * 0.02):
                score += 40
            elif diff <= max(5.0, factura_total * 0.05):
                score += 20
        fecha_asiento = str(asiento_row["fecha"] or "").strip()
        if fecha_factura and fecha_asiento:
            try:
                d1 = datetime.strptime(fecha_factura[:10], "%Y-%m-%d")
                d2 = datetime.strptime(fecha_asiento[:10], "%Y-%m-%d")
                days = abs((d1 - d2).days)
                if days == 0:
                    score += 18
                elif days <= 1:
                    score += 14
                elif days <= 3:
                    score += 10
                elif days <= 7:
                    score += 5
            except Exception:
                pass
        ref_text = normalize_lookup_text(" ".join([asiento_row["concepto"] or "", asiento_row["referencia"] or ""]))
        if factura_numero and factura_numero and factura_numero.upper() in ref_text:
            score += 20
        if factura_numero and factura_numero.upper().replace("/", "") in ref_text.replace("/", ""):
            score += 10
        if factura_raw_lookup:
            raw_tokens = [tok for tok in re.split(r"\s+", factura_raw_lookup) if len(tok) >= 4]
            ref_tokens = set(re.split(r"\s+", ref_text))
            overlap_tokens = set(raw_tokens) & ref_tokens
            overlap = len(overlap_tokens)
            if overlap:
                score += min(18, overlap * 6)
                if overlap >= 2:
                    score += 4
                if any(len(tok) >= 8 for tok in overlap_tokens):
                    score += 6
            for keyword in ("APPLE", "WIBER", "AMAZON", "REPSOL", "TELEFONICA", "CULLIGAN", "THUNDERBIRD", "THUNDERBIRD"):
                if keyword in factura_raw_lookup and keyword in ref_text:
                    score += 12
                    break
        tercero_text = ""
        tercero_nif_line = ""
        cuenta_tercero = ""
        cuenta_gasto_ingreso = ""
        for line in line_rows:
            tercero_text = tercero_text or normalize_lookup_text(line.get("tercero_nombre") or "")
            tercero_nif_line = tercero_nif_line or normalize_lookup_text(line.get("tercero_nif") or "")
            cuenta = str(line.get("cuenta") or "").strip()
            if not cuenta_tercero and cuenta.startswith(("4", "5")):
                cuenta_tercero = cuenta
            if not cuenta_gasto_ingreso and cuenta.startswith(("6", "7")):
                cuenta_gasto_ingreso = cuenta
        if factura_nif and tercero_nif_line and factura_nif == tercero_nif_line:
            score += 15
        if factura_nombre and tercero_text and (factura_nombre in tercero_text or tercero_text in factura_nombre):
            score += 8
        if factura_tipo == "venta" and cuenta_tercero.startswith("430"):
            score += 5
        if factura_tipo == "compra" and cuenta_tercero.startswith("400"):
            score += 5
        if factura_tipo == "venta" and cuenta_gasto_ingreso.startswith("7"):
            score += 5
        if factura_tipo == "compra" and cuenta_gasto_ingreso.startswith("6"):
            score += 5
        return score

    best = None
    best_lines = []
    best_score = 0
    for asiento_row in candidates:
        line_rows = conn.execute(
            """
            SELECT
              l.cuenta,
              l.descripcion,
              l.debe,
              l.haber,
              l.impuesto_tipo,
              l.impuesto_pct,
              COALESCE(t.nombre, '') AS tercero_nombre,
              COALESCE(t.nif, '') AS tercero_nif,
              COALESCE(t.cuenta_contable, '') AS tercero_cuenta
            FROM gestoria_asiento_lineas l
            LEFT JOIN gestoria_terceros t ON t.id = l.tercero_id
            WHERE l.asiento_id = ?
            ORDER BY l.created_at ASC
            """,
            (asiento_row["id"],),
        ).fetchall()
        line_dicts = [dict(r) for r in line_rows]
        score = _candidate_score(asiento_row, line_dicts)
        if score > best_score:
            best = dict(asiento_row)
            best_lines = line_dicts
            best_score = score

    if historico_cerrado and best_score < match_threshold:
        broad_where = [
            "a.empresa_id = ?",
            "COALESCE(a.factura_id, '') = ''",
            "COALESCE(a.diario, '') <> 'FACT'",
        ]
        broad_values = [empresa_id]
        if cliente_id:
            broad_where.append("COALESCE(a.cliente_id, '') = ?")
            broad_values.append(cliente_id)
        broad_candidates = conn.execute(
            f"""
            SELECT a.id, a.fecha, a.concepto, a.referencia, a.total_debe, a.total_haber, a.diario
            FROM gestoria_asientos a
            WHERE {' AND '.join(broad_where)}
            ORDER BY a.fecha ASC, a.created_at ASC
            LIMIT 500
            """,
            broad_values,
        ).fetchall()
        for asiento_row in broad_candidates:
            line_rows = conn.execute(
                """
                SELECT
                  l.cuenta,
                  l.descripcion,
                  l.debe,
                  l.haber,
                  l.impuesto_tipo,
                  l.impuesto_pct,
                  COALESCE(t.nombre, '') AS tercero_nombre,
                  COALESCE(t.nif, '') AS tercero_nif,
                  COALESCE(t.cuenta_contable, '') AS tercero_cuenta
                FROM gestoria_asiento_lineas l
                LEFT JOIN gestoria_terceros t ON t.id = l.tercero_id
                WHERE l.asiento_id = ?
                ORDER BY l.created_at ASC
                """,
                (asiento_row["id"],),
            ).fetchall()
            line_dicts = [dict(r) for r in line_rows]
            score = _candidate_score(asiento_row, line_dicts)
            if score > best_score:
                best = dict(asiento_row)
                best_lines = line_dicts
                best_score = score

    if not best:
        if historico_cerrado:
            return {
                "ok": True,
                "factura_id": factura_id,
                "asiento_id": None,
                "matched": False,
                "linked": False,
                "score": 0,
                "reason": "historico_sin_match",
            }
        return _create_auto_asiento_from_factura()

    linked = False
    if auto_link and best_score >= match_threshold:
        updated = conn.execute(
            """
            UPDATE gestoria_asientos
            SET factura_id = ?, updated_at = datetime(?)
            WHERE id = ?
              AND COALESCE(factura_id, '') = ''
            """,
            (factura_id, now, best["id"]),
        ).rowcount
        linked = updated == 1
    if best and best_score >= match_threshold:
        try:
            learn_gestoria_factura_rule(conn, factura, best, best_lines, now=now)
        except Exception:
            pass
    if best_score < match_threshold:
        if historico_cerrado:
            if existing_asiento and existing_asiento_is_auto:
                return {
                    "ok": True,
                    "factura_id": factura_id,
                    "asiento_id": existing_asiento["id"],
                    "matched": False,
                    "linked": False,
                    "score": best_score,
                    "reason": "historico_sin_match",
                    "asiento_fecha": existing_asiento["fecha"] or "",
                    "asiento_referencia": existing_asiento["referencia"] or "",
                    "asiento_concepto": existing_asiento["concepto"] or "",
                }
            return {
                "ok": True,
                "factura_id": factura_id,
                "asiento_id": best["id"],
                "matched": False,
                "linked": False,
                "score": best_score,
                "reason": "historico_sin_match",
                "asiento_fecha": best.get("fecha") or "",
                "asiento_referencia": best.get("referencia") or "",
                "asiento_concepto": best.get("concepto") or "",
            }
        return _create_auto_asiento_from_factura()
    if historico_cerrado and existing_asiento and existing_asiento_is_auto and best["id"] != existing_asiento["id"]:
        try:
            conn.execute(
                "UPDATE gestoria_asientos SET factura_id = NULL, updated_at = datetime(?) WHERE id = ?",
                (now, existing_asiento["id"]),
            )
        except Exception:
            pass
    return {
        "ok": True,
        "factura_id": factura_id,
        "asiento_id": best["id"],
        "matched": True,
        "linked": linked,
        "score": best_score,
        "reason": "auto" if linked else "sugerido",
        "asiento_fecha": best.get("fecha") or "",
        "asiento_referencia": best.get("referencia") or "",
        "asiento_concepto": best.get("concepto") or "",
    }


def learn_gestoria_factura_rule(conn, factura_row, asiento_row=None, line_rows=None, now=None):
    if not factura_row:
        return None
    if not isinstance(factura_row, dict):
        factura_row = dict(factura_row)
    empresa_id = str(factura_row.get("empresa_id") or "").strip()
    if not empresa_id:
        return None
    cliente_id = str(factura_row.get("cliente_id") or "").strip() or None
    tercero_nombre = str(factura_row.get("tercero_nombre") or factura_row.get("tercero") or "").strip()
    tercero_nif = str(factura_row.get("tercero_nif") or "").strip().upper()
    factura_numero = str(factura_row.get("numero") or "").strip()
    factura_tipo = normalize_service_key(factura_row.get("tipo") or "")
    factura_iva = round(parse_money_value(factura_row.get("iva_pct") or 0), 2) if factura_row.get("iva_pct") else None
    factura_exento = round(parse_money_value(factura_row.get("base_exenta") or factura_row.get("exento") or 0), 2) if (factura_row.get("base_exenta") or factura_row.get("exento")) else None
    factura_no_sujeta = round(parse_money_value(factura_row.get("base_no_sujeta") or 0), 2) if factura_row.get("base_no_sujeta") else None
    factura_tipo_operacion = str(factura_row.get("tipo_operacion") or "").strip().lower()
    cuenta_tercero = str(factura_row.get("tercero_cuenta") or "").strip()
    cuenta_gasto = ""
    texto_match = " ".join(
        [
            tercero_nombre,
            tercero_nif,
            factura_numero,
            str(factura_row.get("descripcion") or ""),
            str(factura_row.get("doc_key") or ""),
            str(factura_exento or ""),
            str(factura_no_sujeta or ""),
            factura_tipo_operacion,
        ]
    ).strip()
    if line_rows:
        for line in line_rows:
            cuenta = str((line or {}).get("cuenta") or "").strip()
            if not cuenta_tercero and cuenta.startswith(("4", "5")):
                cuenta_tercero = cuenta
            if not cuenta_gasto and cuenta.startswith(("6", "7")):
                cuenta_gasto = cuenta
            texto_match = " ".join([texto_match, str((line or {}).get("descripcion") or "")]).strip()
    if asiento_row:
        texto_match = " ".join(
            [
                texto_match,
                str((asiento_row or {}).get("referencia") or ""),
                str((asiento_row or {}).get("concepto") or ""),
            ]
        ).strip()
    now = now or datetime.utcnow().isoformat()
    existing = conn.execute(
        """
        SELECT id
        FROM gestoria_import_reglas
        WHERE empresa_id = ?
          AND COALESCE(cliente_id, '') = COALESCE(?, '')
          AND ambito = 'factura'
          AND (
            (COALESCE(proveedor_nif_match, '') <> '' AND COALESCE(proveedor_nif_match, '') = COALESCE(?, ''))
            OR (COALESCE(proveedor_match, '') <> '' AND COALESCE(proveedor_match, '') = COALESCE(?, ''))
          )
        LIMIT 1
        """,
        (empresa_id, cliente_id or "", tercero_nif, tercero_nombre),
    ).fetchone()
    values = (
        tercero_nombre or None,
        tercero_nif or None,
        texto_match[:500] or None,
        factura_tipo or None,
        tercero_nombre or None,
        tercero_nif or None,
        cuenta_gasto or None,
        cuenta_tercero or None,
        factura_iva,
        1,
        f"Aprendida desde conciliación factura {'/' + factura_numero if factura_numero else ''}".strip(),
        now,
    )
    if existing:
        conn.execute(
            """
            UPDATE gestoria_import_reglas
            SET proveedor_match = COALESCE(NULLIF(?, ''), proveedor_match),
                proveedor_nif_match = COALESCE(NULLIF(?, ''), proveedor_nif_match),
                texto_match = COALESCE(NULLIF(?, ''), texto_match),
                categoria_forzada = COALESCE(NULLIF(?, ''), categoria_forzada),
                tercero_nombre_forzado = COALESCE(NULLIF(?, ''), tercero_nombre_forzado),
                tercero_nif_forzado = COALESCE(NULLIF(?, ''), tercero_nif_forzado),
                cuenta_gasto_forzada = COALESCE(NULLIF(?, ''), cuenta_gasto_forzada),
                cuenta_tercero_forzada = COALESCE(NULLIF(?, ''), cuenta_tercero_forzada),
                iva_pct_forzado = COALESCE(?, iva_pct_forzado),
                auto_ok = CASE WHEN ? = 1 THEN 1 ELSE auto_ok END,
                notas = COALESCE(NULLIF(?, ''), notas),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (*values, existing["id"]),
        )
        return {"id": existing["id"], "updated": True}
    rule_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_import_reglas (
          id, empresa_id, cliente_id, ambito, prioridad, activo,
          proveedor_match, proveedor_nif_match, texto_match, categoria_forzada,
          tercero_nombre_forzado, tercero_nif_forzado, cuenta_gasto_forzada, cuenta_tercero_forzada,
          iva_pct_forzado, auto_ok, notas, created_at, updated_at
        ) VALUES (
          ?, ?, ?, 'factura', 100, 1,
          ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (rule_id, empresa_id, cliente_id, *values, now),
    )
    return {"id": rule_id, "updated": False}


def _extract_matricula_from_campos_ocr(campos_ocr):
    raw = str(campos_ocr or "").strip()
    if not raw:
        return ""
    try:
        payload = json.loads(raw)
        if isinstance(payload, dict):
            val = payload.get("matricula") or payload.get("MATRICULA") or payload.get("Matrícula") or ""
            return str(val or "").strip()
    except Exception:
        pass
    m = re.search(r"([0-9]{4}\s*[A-Z]{3})", raw.upper())
    if m:
        return m.group(1)
    return ""


def _normalize_plate_for_db(value):
    raw = re.sub(r"[^A-Z0-9]", "", str(value or "").upper())
    if not raw:
        return ""
    if re.match(r"^\d{4}[A-Z]{3}$", raw):
        return f"{raw[:4]} {raw[4:]}"
    if 5 <= len(raw) <= 10 and re.search(r"[A-Z]", raw) and re.search(r"\d", raw):
        return raw
    return ""


def _maybe_update_seguro_matricula(conn, seguro_row, campos_ocr, now):
    if not seguro_row:
        return
    try:
        seguro_id = seguro_row["id"]
        ramo = (seguro_row.get("ramo") or "") if hasattr(seguro_row, 'get') else (seguro_row["ramo"] or "")
        ramo_key = normalize_lookup_text(ramo)
        is_auto = any(token in ramo_key for token in ("AUTO", "MOTO", "VEHICULO", "AUTOMOVIL"))
        if not is_auto:
            return
        current = (seguro_row.get("matricula") or "") if hasattr(seguro_row, 'get') else ""
        if str(current).strip():
            return
        val = _extract_matricula_from_campos_ocr(campos_ocr)
        plate = _normalize_plate_for_db(val)
        if not plate:
            return
        conn.execute(
            "UPDATE seguros SET matricula = ?, updated_at = datetime(?) WHERE id = ? AND (matricula IS NULL OR TRIM(matricula) = '')",
            (plate, now, seguro_id),
        )
    except Exception:
        return


def apply_gestoria_import_document(conn, document_row, now):
    if not isinstance(document_row, dict):
        document_row = dict(document_row)
    reasons = validate_import_document_for_apply(document_row)
    if reasons:
        raise ValueError(",".join(reasons))
    tipo = str(document_row["tipo_detectado"] or "compra").strip().lower() or "compra"
    numero = str(document_row["numero_detectado"] or "").strip()
    fecha = str(document_row["fecha_detectada"] or "").strip() or datetime.now().strftime("%Y-%m-%d")
    tercero_nombre = str(document_row["tercero_detectado"] or "").strip() or str(document_row["archivo_nombre"] or "").strip()
    tercero_nif = str(document_row["nif_detectado"] or "").strip().upper()
    categoria = str(document_row["categoria_detectada"] or "").strip()
    descripcion = describe_import_record(document_row)
    base = round(parse_money_value(document_row["base_detectada"]), 2)
    cuota_iva = round(parse_money_value(document_row["cuota_iva_detectada"]), 2)
    total = round(parse_money_value(document_row["total_detectado"]), 2)
    if total <= 0 and base > 0 and cuota_iva > 0:
        total = round(base + cuota_iva, 2)
    if base <= 0 and total > 0 and cuota_iva > 0:
        base = round(max(0.0, total - cuota_iva), 2)
    iva_pct = 0.0
    if base > 0 and cuota_iva > 0:
        iva_pct = round((cuota_iva / base) * 100.0, 2)
    third_type = "cliente" if tipo == "venta" else ("proveedor" if numero else "acreedor")
    tercero_id, counterpart_account = ensure_gestoria_tercero(
        conn,
        document_row["empresa_id"],
        tercero_nif,
        tercero_nombre,
        third_type,
        now,
    )
    if document_row["cuenta_tercero_sugerida"]:
        counterpart_account = str(document_row["cuenta_tercero_sugerida"]).strip() or counterpart_account
        conn.execute(
            """
            UPDATE gestoria_terceros
            SET cuenta_contable = COALESCE(NULLIF(?, ''), cuenta_contable),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (counterpart_account, now, tercero_id),
        )
    concepto = descripcion
    if categoria and categoria not in normalize_lookup_text(concepto):
        concepto = f"{concepto} · {categoria}" if concepto else categoria
    parsed_factura = {
        "tipo": tipo,
        "numero": numero,
        "fecha": fecha,
        "nif": tercero_nif,
        "tercero": tercero_nombre,
        "base_imponible": base,
        "base_exenta": 0.0,
        "base_no_sujeta": 0.0,
        "cuota_iva": cuota_iva,
        "cuota_irpf": 0.0,
        "total": total,
        "iva_pct": iva_pct,
        "descripcion": concepto,
        "raw_text": document_row["raw_text"] or "",
    }
    try:
        parsed_doc = parse_invoice_text(document_row.get("raw_text") or "")
        if parsed_doc:
            parsed_factura["base_exenta"] = float(parsed_doc.get("base_exenta") or parsed_doc.get("exento") or 0.0)
            parsed_factura["base_no_sujeta"] = float(parsed_doc.get("base_no_sujeta") or 0.0)
            parsed_factura["tipo_operacion"] = str(parsed_doc.get("tipo_operacion") or "").strip()
    except Exception:
        pass
    archivo_hash = str(document_row.get("archivo_hash") or "").strip() or None
    dedupe_key = compute_gestoria_factura_dedupe_key(
        empresa_id=document_row["empresa_id"],
        cliente_id=document_row["cliente_id"],
        tipo=tipo,
        tercero_nif=tercero_nif,
        tercero_nombre=tercero_nombre,
        numero=numero,
        fecha_emision=fecha,
        total=total,
        base=base,
        cuota_iva=cuota_iva,
    )
    try:
        dup = None
        if archivo_hash:
            dup = conn.execute(
                """
                SELECT id
                FROM gestoria_facturas
                WHERE empresa_id = ? AND COALESCE(cliente_id, '') = COALESCE(?, '') AND archivo_hash = ?
                LIMIT 1
                """,
                (document_row["empresa_id"], document_row["cliente_id"] or "", archivo_hash),
            ).fetchone()
        if not dup and dedupe_key:
            dup = conn.execute(
                """
                SELECT id
                FROM gestoria_facturas
                WHERE empresa_id = ? AND COALESCE(cliente_id, '') = COALESCE(?, '') AND dedupe_key = ?
                LIMIT 1
                """,
                (document_row["empresa_id"], document_row["cliente_id"] or "", dedupe_key),
            ).fetchone()
        if dup:
            dup_id = str(dup["id"]).strip()
            asiento = conn.execute(
                "SELECT id FROM gestoria_asientos WHERE factura_id = ? LIMIT 1",
                (dup_id,),
            ).fetchone()
            conn.execute(
                """
                UPDATE gestoria_import_documentos
                SET estado_revision = 'DUPLICADO',
                    motivos_revision = COALESCE(NULLIF(TRIM(COALESCE(motivos_revision, '') || ',duplicado_factura'), ''), 'duplicado_factura'),
                    factura_id = COALESCE(factura_id, ?),
                    tercero_id = COALESCE(tercero_id, ?),
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (dup_id, tercero_id, now, document_row["id"]),
            )
            ensure_factura_doc_link(
                conn,
                empresa_id=document_row["empresa_id"],
                cliente_id=document_row["cliente_id"],
                factura_id=dup_id,
                doc_key=document_row.get("doc_key") or "",
                nombre=document_row.get("archivo_nombre") or (numero or "Factura"),
                fecha=fecha,
                estado="Recibido",
                notas=f"Importador facturas · lote {document_row['lote_id']} · documento {document_row['id']}",
                campos_ocr=_factura_campos_ocr_payload(parsed_factura),
                now=now,
            )
            return {
                "factura_id": dup_id,
                "asiento_id": (asiento["id"] if asiento else None),
                "tercero_id": tercero_id,
                "duplicate_of": dup_id,
                "lineas": [],
                "totales": {"debe": 0.0, "haber": 0.0},
            }
    except Exception:
        pass
    lines, total_debe, total_haber = build_invoice_asiento(parsed_factura, counterpart_account)
    forced_account = str(document_row["cuenta_sugerida"] or "").strip() or map_import_category_to_account(categoria)
    if forced_account:
        for item in lines:
            cuenta = str(item.get("cuenta") or "").strip()
            if tipo == "venta":
                if cuenta.startswith("7"):
                    item["cuenta"] = forced_account
            else:
                if cuenta.startswith("6"):
                    item["cuenta"] = forced_account
    factura_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_facturas (
          id, empresa_id, cliente_id, tercero_id, tipo, numero, fecha_emision, descripcion,
          base_imponible, base_exenta, base_no_sujeta, cuota_iva, cuota_irpf, total, iva_pct,
          tipo_operacion, estado_ocr, doc_key, raw_text,
          archivo_hash, dedupe_key, import_documento_id, origen_importacion, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            factura_id,
            document_row["empresa_id"],
            document_row["cliente_id"],
            tercero_id,
            tipo,
            numero or None,
            fecha,
            concepto,
            base,
            float(parsed_factura.get("base_exenta") or 0.0),
            float(parsed_factura.get("base_no_sujeta") or 0.0),
            cuota_iva,
            0.0,
            total,
            iva_pct,
            parsed_factura.get("tipo_operacion") or "",
            "importado",
            document_row["doc_key"],
            document_row["raw_text"],
            archivo_hash,
            dedupe_key or None,
            document_row["id"],
            "gestoria_import",
            now,
            now,
        ),
    )
    try:
        ensure_factura_doc_link(
            conn,
            empresa_id=document_row["empresa_id"],
            cliente_id=document_row["cliente_id"],
            factura_id=factura_id,
            doc_key=document_row.get("doc_key") or "",
            nombre=document_row.get("archivo_nombre") or (numero or "Factura"),
            fecha=fecha,
            estado="Recibido",
            notas=f"Importador facturas · lote {document_row['lote_id']} · documento {document_row['id']}",
            campos_ocr=_factura_campos_ocr_payload(parsed_factura),
            now=now,
        )
    except Exception:
        pass
    asiento_id = os.urandom(16).hex()
    referencia = numero or factura_id
    conn.execute(
        """
        INSERT INTO gestoria_asientos (
          id, empresa_id, cliente_id, factura_id, fecha, concepto, diario, referencia,
          total_debe, total_haber, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            asiento_id,
            document_row["empresa_id"],
            document_row["cliente_id"],
            factura_id,
            fecha,
            concepto,
            "FACT",
            referencia,
            total_debe,
            total_haber,
            now,
            now,
        ),
    )
    for item in lines:
        conn.execute(
            """
            INSERT INTO gestoria_asiento_lineas (
              id, asiento_id, tercero_id, cuenta, descripcion, debe, haber,
              impuesto_tipo, impuesto_pct, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                asiento_id,
                tercero_id,
                item.get("cuenta"),
                item.get("descripcion"),
                item.get("debe") or 0.0,
                item.get("haber") or 0.0,
                item.get("impuesto"),
                item.get("porcentaje"),
                now,
                now,
            ),
        )
    conn.execute(
        """
        INSERT INTO gestoria_contabilidad (
          id, empresa_id, cliente_id, cliente_ids_json, fecha, concepto, gestion, tipo, importe, notas, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            document_row["empresa_id"],
            document_row["cliente_id"],
            json.dumps([document_row["cliente_id"]], ensure_ascii=False) if document_row["cliente_id"] else None,
            fecha,
            concepto,
            "Contable",
            "Ingreso" if tipo == "venta" else "Gasto",
            total,
            f"Importador facturas · lote {document_row['lote_id']} · documento {document_row['id']} · asiento {asiento_id}",
            now,
            now,
        ),
    )
    conn.execute(
        """
        UPDATE gestoria_import_documentos
        SET factura_id = ?, tercero_id = ?, updated_at = datetime(?)
        WHERE id = ?
        """,
        (factura_id, tercero_id, now, document_row["id"]),
    )
    return {
        "factura_id": factura_id,
        "asiento_id": asiento_id,
        "tercero_id": tercero_id,
        "lineas": lines,
        "totales": {"debe": total_debe, "haber": total_haber},
    }


def apply_gestoria_import_lote(conn, lote_id, empresa_id, now, limit=None):
    sql = """
        SELECT *
        FROM gestoria_import_documentos
        WHERE lote_id = ?
          AND empresa_id = ?
          AND estado_revision = 'OK'
          AND factura_id IS NULL
        ORDER BY fecha_detectada ASC, created_at ASC
    """
    values = [lote_id, empresa_id]
    if limit:
        sql += " LIMIT ?"
        values.append(int(limit))
    rows = conn.execute(sql, values).fetchall()
    applied = []
    errors = []
    for row in rows:
        try:
            result = apply_gestoria_import_document(conn, row, now)
            applied.append({"documento_id": row["id"], **result})
            log_gestoria_import_event(
                conn,
                lote_id,
                "aplicado",
                now,
                documento_id=row["id"],
                factura_id=result["factura_id"],
                detalle="Documento aplicado a factura/asiento",
                payload={"archivo_nombre": row["archivo_nombre"], "factura_id": result["factura_id"], "asiento_id": result["asiento_id"]},
            )
        except Exception as exc:
            conn.execute(
                """
                UPDATE gestoria_import_documentos
                SET estado_revision = 'ERROR',
                    motivos_revision = COALESCE(NULLIF(TRIM(COALESCE(motivos_revision, '') || ',error_aplicacion'), ''), 'error_aplicacion'),
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (now, row["id"]),
            )
            errors.append({"documento_id": row["id"], "archivo_nombre": row["archivo_nombre"], "error": str(exc)})
            log_gestoria_import_event(
                conn,
                lote_id,
                "error_aplicacion",
                now,
                documento_id=row["id"],
                detalle=str(exc),
                payload={"archivo_nombre": row["archivo_nombre"]},
            )
    lote = refresh_gestoria_import_lote_totals(conn, lote_id, now)
    pending_ok = conn.execute(
        """
        SELECT COUNT(*) AS n
        FROM gestoria_import_documentos
        WHERE lote_id = ?
          AND empresa_id = ?
          AND estado_revision = 'OK'
          AND factura_id IS NULL
        """,
        (lote_id, empresa_id),
    ).fetchone()
    pending_ok_count = int((pending_ok["n"] if pending_ok else 0) or 0)
    if lote and pending_ok_count == 0 and int(lote.get("total_ok") or 0) > 0 and not errors:
        conn.execute(
            """
            UPDATE gestoria_import_lotes
            SET estado = 'aplicado',
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (now, lote_id),
        )
        lote = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
        lote = dict(lote) if lote else None
    return {"applied": applied, "errors": errors, "lote": lote}

def process_seguros_ocr(payload, conn, *, session=None):
    raw_bytes, mime, payload_hint = decode_seguros_payload(payload, conn=conn, session=session)
    fast_mode = str(payload.get("fast_mode") or "").strip().lower() in ("1", "true", "yes", "on")
    tmp_path = None
    text = ""
    err_detail = ""
    method = ""
    source_hint = " ".join(
        [
            str(payload.get("filename") or ""),
            str(payload.get("s3_key") or ""),
            str(payload.get("source_hint") or ""),
            str(payload_hint or ""),
        ]
    ).strip()
    hinted_company = detect_company_from_metadata(source_hint)
    required_keys = ("tomador", "poliza_numero", "compania", "fecha_efecto")
    ai_used = False
    ai_error = ""
    field_sources = {}
    candidate_fields = []
    def candidate_score(quality):
        if not isinstance(quality, dict):
            return 0
        required_valid = len(quality.get("required_valid") or [])
        required_filled = len(quality.get("required_filled") or [])
        confidence = float(quality.get("confidence") or 0)
        return required_valid * 100 + required_filled * 10 + int(confidence * 100)
    try:
        suffix = ".pdf"
        if mime and mime.startswith("image/"):
            if "png" in mime:
                suffix = ".png"
            else:
                suffix = ".jpg"
        with tempfile.NamedTemporaryFile(suffix=suffix, delete=False) as tmp_file:
            tmp_file.write(raw_bytes)
            tmp_path = tmp_file.name
        fields = {}
        if mime == "application/pdf":
            text, err_detail, method = extract_pdf_text(tmp_path)
            if not text:
                raise RuntimeError(err_detail or "No se pudo extraer texto")
            fields = parse_poliza_text(text, source_hint=source_hint, hinted_company=hinted_company)
            candidate_fields.append(("pdf_text", normalize_extracted_fields(fields), 1.0))
        else:
            method = "vision" if external_ocr_available() else "tesseract"
            image_text = ""
            image_err = ""
            if external_ocr_available():
                vision_bytes = prepare_image_bytes_for_vision(tmp_path)
                if vision_bytes:
                    image_text, image_err = ocr_image_external(vision_bytes)
            if not image_text:
                image_text, image_err = ocr_pdf_first_page(tmp_path)
            text = image_text or ""
            if image_err and not err_detail:
                err_detail = image_err
            if not text:
                raise RuntimeError(err_detail or "No se pudo extraer texto")
            fields = parse_poliza_text(text, source_hint=source_hint, hinted_company=hinted_company)
            candidate_fields.append(("image_text", normalize_extracted_fields(fields), 1.02))
        best_quality = compute_ocr_quality(fields, required_keys)
        if (not fast_mode) and (
            not any(str(value or "").strip() for value in fields.values()) or (
            not fields.get("poliza_numero")
            or not fields.get("tomador")
            or not fields.get("compania")
            or not fields.get("fecha_efecto")
            )
        ):
            ocr_text, ocr_err = ("", "")
            if mime == "application/pdf":
                ocr_text, ocr_err = ocr_pdf_all_pages(tmp_path, use_external=external_ocr_available())
            if ocr_text:
                ocr_fields = parse_poliza_text(ocr_text, source_hint=source_hint, hinted_company=hinted_company)
                candidate_fields.append(("ocr_all_pages", normalize_extracted_fields(ocr_fields), 1.05))
                ocr_quality = compute_ocr_quality(ocr_fields, required_keys)
                if candidate_score(ocr_quality) >= candidate_score(best_quality):
                    fields = ocr_fields
                    best_quality = ocr_quality
                    text = ocr_text
                    method = "vision" if external_ocr_available() else "tesseract"
            elif ocr_err and not err_detail:
                err_detail = ocr_err
        doc_text = ""
        missing_required = any(not fields.get(key) for key in required_keys)
        if (missing_required or candidate_score(best_quality) < 250) and docai_available() and not fast_mode:
            doc_text, doc_fields, doc_err = ocr_image_docai(raw_bytes, mime)
            if doc_err and not err_detail:
                err_detail = doc_err
            doc_mapped = map_docai_poliza_fields(doc_fields)
            doc_parsed = parse_poliza_text(doc_text, source_hint=source_hint, hinted_company=hinted_company) if doc_text else {}
            candidate_fields.append(("docai_fields", normalize_extracted_fields(doc_mapped), 1.1))
            candidate_fields.append(("docai_parsed", normalize_extracted_fields(doc_parsed), 1.05))
            merged = dict(fields)
            for key, value in doc_mapped.items():
                if value and not merged.get(key):
                    merged[key] = value
            for key, value in doc_parsed.items():
                if value and not merged.get(key):
                    merged[key] = value
            merged_quality = compute_ocr_quality(merged, required_keys)
            if candidate_score(merged_quality) >= candidate_score(best_quality):
                fields = merged
                best_quality = merged_quality
            if doc_text and doc_text.strip():
                method = "docai"
        missing_required = any(not fields.get(key) for key in required_keys)
        need_zones = missing_required or (not fast_mode and candidate_score(best_quality) < 320)
        if need_zones:
            zones_text, zones_err = ocr_poliza_key_regions(tmp_path, use_external=external_ocr_available())
            if zones_text:
                zones_fields = parse_poliza_text(
                    zones_text,
                    source_hint=source_hint,
                    hinted_company=hinted_company,
                )
                candidate_fields.append(("zones", normalize_extracted_fields(zones_fields), 1.08))
                zones_merged = merge_fields(fields, zones_fields)
                zones_quality = compute_ocr_quality(zones_merged, required_keys)
                if candidate_score(zones_quality) >= candidate_score(best_quality):
                    fields = zones_merged
                    best_quality = zones_quality
                    if method:
                        method = f"{method}+zones"
                    else:
                        method = "zones"
            elif zones_err and not err_detail:
                err_detail = zones_err
        if hinted_company and not fields.get("compania"):
            fields["compania"] = hinted_company
        missing_required = any(not fields.get(key) for key in required_keys)
        if fast_mode and missing_required:
            # Último intento rápido sin OCR externo ni IA para evitar latencia alta.
            quick_text, quick_err = ocr_pdf_all_pages(tmp_path, use_external=False)
            if quick_text:
                quick_fields = parse_poliza_text(quick_text, source_hint=source_hint, hinted_company=hinted_company)
                quick_merged = merge_fields(fields, quick_fields)
                quick_quality = compute_ocr_quality(quick_merged, required_keys)
                if candidate_score(quick_quality) >= candidate_score(best_quality):
                    fields = quick_merged
                    best_quality = quick_quality
                    text = quick_text
                    method = "tesseract"
            elif quick_err and not err_detail:
                err_detail = quick_err
            missing_required = any(not fields.get(key) for key in required_keys)
        if (not fast_mode) and openai_available() and (missing_required or candidate_score(best_quality) < 320):
            ai_text = text or ""
            if doc_text and doc_text.strip():
                ai_text = f"{ai_text}\n\n{doc_text}".strip()
            if tmp_path and OCR_OPENAI_VISION_PAGES > 0:
                image_urls, vision_img_err = pdf_to_png_data_urls(
                    tmp_path,
                    max_pages=OCR_OPENAI_VISION_PAGES,
                    dpi=OCR_OPENAI_VISION_DPI,
                )
                if image_urls:
                    ai_vision_fields, ai_vision_err = call_openai_extract_seguro_vision(
                        image_urls,
                        text=ai_text,
                        source_hint=source_hint,
                        hinted_company=hinted_company,
                    )
                    if ai_vision_err:
                        ai_error = ai_vision_err
                    elif ai_vision_fields:
                        ai_used = True
                        candidate_fields.append(("openai_vision", normalize_extracted_fields(ai_vision_fields), 1.18))
                        merged = dict(fields)
                        for key, value in ai_vision_fields.items():
                            if value and not str(merged.get(key) or "").strip():
                                merged[key] = value
                        ai_quality = compute_ocr_quality(merged, required_keys)
                        if candidate_score(ai_quality) >= candidate_score(best_quality):
                            fields = merged
                            best_quality = ai_quality
                elif vision_img_err and not ai_error:
                    ai_error = vision_img_err
            if ai_text:
                ai_fields, ai_error_msg = call_openai_extract_seguro(
                    ai_text,
                    source_hint=source_hint,
                    hinted_company=hinted_company,
                )
                if ai_error_msg:
                    ai_error = ai_error_msg
                elif ai_fields:
                    ai_used = True
                    candidate_fields.append(("openai_text", normalize_extracted_fields(ai_fields), 0.98))
                    merged = dict(fields)
                    for key, value in ai_fields.items():
                        if value and not str(merged.get(key) or "").strip():
                            merged[key] = value
                    ai_quality = compute_ocr_quality(merged, required_keys)
                    if candidate_score(ai_quality) >= candidate_score(best_quality):
                        fields = merged
                        best_quality = ai_quality
        if (not fast_mode) and OCR_EXPERT_MODE and candidate_fields:
            expert_fields, expert_sources = blend_ocr_field_candidates(candidate_fields, required_keys)
            expert_quality = compute_ocr_quality(expert_fields, required_keys)
            if candidate_score(expert_quality) >= candidate_score(best_quality):
                fields = expert_fields
                best_quality = expert_quality
                field_sources = expert_sources
        # Post-fix final para AXA Profesional: evita valores del mediador y fechas truncadas.
        company_key = normalize_company_key(fields.get("compania") or hinted_company or "")
        text_upper = normalize_lookup_text(text)
        if ("AXA" in company_key) and ("AXA PROFESIONAL" in text_upper or "POLIZA DE SEGURO DE PROFESIONAL" in text_upper):
            def _norm_date_local(value):
                raw = str(value or "").strip()
                raw = raw.replace(".", "/").replace("-", "/")
                raw = re.sub(r"\s+", "", raw)
                return raw
            def _clean_name_local(value):
                raw = normalize_person_name(value or "")
                raw = re.sub(r"\s{2,}", " ", raw).strip(" ,;:-")
                return raw
            fields["ramo"] = "Profesional"
            pol = re.search(r"p[oó]liza\s*(?:n[º°o]|no\.?)\s*([0-9]{2})[- ]?([0-9]{7,})", text, re.IGNORECASE)
            if pol:
                fields["poliza_numero"] = f"{pol.group(1)}-{pol.group(2)}"
            dates = re.search(
                r"Datos\s+de\s+la\s+Poliza[\s\S]{0,900}?Fecha\s+efecto[\s\S]{0,200}?Fecha\s+vencimiento[\s\S]{0,220}?([0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})[\s\S]{0,120}?([0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})",
                text,
                re.IGNORECASE,
            )
            if dates:
                fields["fecha_efecto"] = _norm_date_local(dates.group(1))
                fields["fecha_vencimiento"] = _norm_date_local(dates.group(2))
            tom = re.search(r"Tomador\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s]{6,}?)\s+Producto", text, re.IGNORECASE)
            if tom:
                fields["tomador"] = _clean_name_local(tom.group(1))
            if not fields.get("tomador") or len((fields.get("tomador") or "").split()) < 3:
                aseg = re.search(r"Nombre\s+del\s+asegurado\s*[\r\n]+\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s]{8,})", text, re.IGNORECASE)
                if aseg:
                    fields["tomador"] = _clean_name_local(aseg.group(1))
            if normalize_phone(fields.get("telefono") or "") == "900909014":
                fields["telefono"] = ""
            if "fincasvelazquez" in str(fields.get("email") or "").lower():
                fields["email"] = ""
            dir_norm = normalize_lookup_text(fields.get("direccion") or "")
            if "DOMICILIO SOCIAL" in dir_norm or "MEDIADOR" in dir_norm or "PALMA DE MALLORCA" in dir_norm:
                fields["direccion"] = ""
            if not fields.get("direccion"):
                addr = re.search(r"\b(CL\s+calle[^\n]{5,160}?\d{5}\s+[A-ZÁÉÍÓÚÑ]{3,})", text, re.IGNORECASE)
                if addr:
                    fields["direccion"] = re.sub(r"\s+", " ", addr.group(1)).strip()
        if ("ALLIANZ" in company_key) and ("CERTIFICADO DE SEGURO" in text_upper or "ALLIANZ R C PYME" in text_upper or "ALLIANZ R.C.PYME" in text_upper):
            if not fields.get("ramo"):
                fields["ramo"] = "Responsabilidad civil"
            allianz_general = re.search(
                r"Datos\s+Generales([\s\S]{0,2200}?)Datos\s+del\s+Asegurado",
                text,
                re.IGNORECASE,
            )
            allianz_scope = allianz_general.group(1) if allianz_general else text
            pol = re.search(r"P[oó]liza\s*n[º°o]\s*:\s*([0-9]{6,12})", text, re.IGNORECASE)
            if pol:
                fields["poliza_numero"] = pol.group(1).strip()
            dur = re.search(
                r"Duraci[oó]n\s*:\s*Desde[\s\S]{0,220}?del\s+(\d{1,2}/\d{1,2}/\d{4})[\s\S]{0,240}?hasta[\s\S]{0,220}?del\s+(\d{1,2}/\d{1,2}/\d{4})",
                text,
                re.IGNORECASE,
            )
            if dur:
                fields["fecha_efecto"] = dur.group(1)
                fields["fecha_vencimiento"] = dur.group(2)
            m = re.search(
                r"Datos\s+Generales\s*\n\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s,.'\-]{5,})\s*\n\s*Tomador\s+del\s+Seguro",
                text,
                re.IGNORECASE,
            )
            if m:
                name = normalize_person_name(m.group(1))
                name = re.sub(r"\s+", " ", name).strip(" ,;:-")
                if name and len(name.split()) >= 2:
                    fields["tomador"] = name
            # Si tomador quedó como una dirección, priorizar razón social del bloque general.
            tomador_norm = normalize_lookup_text(fields.get("tomador") or "")
            looks_address = (
                " CL " in f" {tomador_norm} "
                or " CALLE " in f" {tomador_norm} "
                or " AVDA " in f" {tomador_norm} "
                or " AVD " in f" {tomador_norm} "
            )
            if looks_address or not fields.get("tomador"):
                lines = [ln.strip() for ln in allianz_scope.splitlines() if ln.strip()]
                for idx, ln in enumerate(lines):
                    if re.search(r"Tomador\s+del", ln, re.IGNORECASE):
                        if idx > 0:
                            candidate = re.sub(r"\s+", " ", lines[idx - 1]).strip(" ,;:-")
                            if candidate and len(candidate.split()) >= 2:
                                fields["tomador"] = candidate
                        break
            nif_line = re.search(r"\bNIF\s*:\s*([A-Z0-9.\-]{8,16})", allianz_scope, re.IGNORECASE)
            if nif_line:
                fields["nif"] = re.sub(r"[^A-Z0-9]", "", nif_line.group(1).upper())
                fields["dni"] = fields["nif"]
            if fields.get("fecha_efecto") and fields.get("fecha_vencimiento") and fields["fecha_efecto"] == fields["fecha_vencimiento"]:
                fields["fecha_vencimiento"] = add_year_to_date(fields["fecha_efecto"])
        doc_type = classify_seguros_document(text)
        if doc_type == "otro" and doc_text:
            doc_type = classify_seguros_document(doc_text)
        ocr_quality = compute_ocr_quality(fields, required_keys)
        if field_sources:
            ocr_quality["field_sources"] = field_sources
        cliente_match = False
        cliente_id = None
        tomador = (fields.get("tomador") or "").strip()
        nif = (fields.get("nif") or fields.get("dni") or "").strip()
        if tomador or nif:
            if nif:
                nif_norm = re.sub(r"\s+", "", nif).upper()
                row = conn.execute(
                    "SELECT id FROM clientes WHERE REPLACE(UPPER(nif), ' ', '') = ?",
                    (nif_norm,),
                ).fetchone()
                if row:
                    cliente_id = row["id"]
                    cliente_match = True
            if not cliente_match and tomador:
                nombre_norm = re.sub(r"\s+", " ", tomador).strip().upper()
                row = conn.execute(
                    "SELECT id FROM clientes WHERE TRIM(UPPER(nombre)) = ?",
                    (nombre_norm,),
                ).fetchone()
                if row:
                    cliente_id = row["id"]
                    cliente_match = True
        return {
            "fields": fields,
            "text": text,
            "language": detect_ocr_lang(),
            "method": method,
            "doc_type": doc_type,
            "ocr_quality": ocr_quality,
            "cliente_id": cliente_id,
            "cliente_match": cliente_match,
            "ai_used": ai_used,
            "ai_error": ai_error,
        }
    finally:
        if tmp_path and os.path.exists(tmp_path):
            os.unlink(tmp_path)


def process_gestoria_factura_ocr(payload, conn, empresa_id, now="now", *, session=None):
    if not empresa_id:
        raise ValueError("empresa_id requerido")
    cliente_id = (payload.get("cliente_id") or "").strip() or None
    tipo_factura = (payload.get("tipo_factura") or payload.get("tipo") or "").strip().lower()
    if tipo_factura not in ("compra", "venta"):
        tipo_factura = "compra"
    doc_bytes, mime, source_hint = decode_document_payload(payload, conn=conn, session=session)
    tmp_path = None
    text = ""
    err_detail = ""
    method = "tesseract"
    try:
        suffix = ".pdf"
        if mime.startswith("image/"):
            ext = mime.split("/", 1)[1] or "jpg"
            suffix = f".{ext}"
        with tempfile.NamedTemporaryFile(suffix=suffix, delete=False) as tmp_file:
            tmp_file.write(doc_bytes)
            tmp_path = tmp_file.name
        if mime.startswith("image/"):
            if external_ocr_available():
                text, err_detail = ocr_image_external(doc_bytes)
                method = "vision" if text else "tesseract"
            if not text:
                text, err_detail = ocr_image_file(tmp_path)
                method = "tesseract"
            if docai_available():
                doc_text, _doc_fields, doc_err = ocr_image_docai(doc_bytes, mime)
                if doc_text and len(doc_text) > len(text or ""):
                    text = doc_text
                    method = "docai"
                elif doc_err and not err_detail:
                    err_detail = doc_err
        else:
            text, err_detail, method = extract_pdf_text(tmp_path)
            if not text:
                text, page_err = ocr_pdf_all_pages(tmp_path, use_external=external_ocr_available())
                if text:
                    method = "ocr_all_pages"
                elif page_err and not err_detail:
                    err_detail = page_err
        if not text:
            raise ValueError(err_detail or "No se pudo extraer texto de la factura")
        parsed_factura = parse_invoice_text(text)
        if not parsed_factura:
            raise ValueError("No se pudieron extraer datos de factura")
        parsed_factura["tipo"] = tipo_factura
        for key_src, key_dst in (
            ("numero", "numero"),
            ("fecha", "fecha"),
            ("nif", "nif"),
            ("tercero", "tercero"),
        ):
            incoming = str(payload.get(key_src) or "").strip()
            if incoming:
                parsed_factura[key_dst] = incoming
        for num_key in ("base_imponible", "cuota_iva", "cuota_irpf", "total", "iva_pct"):
            incoming = payload.get(num_key)
            if incoming not in (None, ""):
                parsed_factura[num_key] = round(parse_decimal_eu(incoming), 2)
        if not parsed_factura.get("fecha"):
            parsed_factura["fecha"] = datetime.now().strftime("%Y-%m-%d")
        third_type = "cliente" if tipo_factura == "venta" else ("proveedor" if parsed_factura.get("numero") else "acreedor")
        tercero_id, counterpart_account = ensure_gestoria_tercero(
            conn,
            empresa_id,
            parsed_factura.get("nif"),
            parsed_factura.get("tercero"),
            third_type,
            now,
        )
        doc_key = (payload.get("s3_key") or "").strip()
        archivo_hash = hashlib.sha256(doc_bytes).hexdigest() if doc_bytes else ""
        dedupe_key = compute_gestoria_factura_dedupe_key(
            empresa_id=empresa_id,
            cliente_id=cliente_id,
            tipo=tipo_factura,
            tercero_nif=parsed_factura.get("nif"),
            tercero_nombre=parsed_factura.get("tercero"),
            numero=parsed_factura.get("numero"),
            fecha_emision=parsed_factura.get("fecha"),
            total=parsed_factura.get("total") or 0.0,
            base=parsed_factura.get("base_imponible") or 0.0,
            cuota_iva=parsed_factura.get("cuota_iva") or 0.0,
        )
        try:
            dup = None
            if archivo_hash:
                dup = conn.execute(
                    """
                    SELECT id, COALESCE(doc_key, '') AS doc_key
                    FROM gestoria_facturas
                    WHERE empresa_id = ? AND COALESCE(cliente_id, '') = COALESCE(?, '') AND archivo_hash = ?
                    LIMIT 1
                    """,
                    (empresa_id, cliente_id or "", archivo_hash),
                ).fetchone()
            if not dup and dedupe_key:
                dup = conn.execute(
                    """
                    SELECT id, COALESCE(doc_key, '') AS doc_key
                    FROM gestoria_facturas
                    WHERE empresa_id = ? AND COALESCE(cliente_id, '') = COALESCE(?, '') AND dedupe_key = ?
                    LIMIT 1
                    """,
                    (empresa_id, cliente_id or "", dedupe_key),
                ).fetchone()
            if dup:
                dup_id = str(dup["id"]).strip()
                existing_doc_key = str((dup["doc_key"] or "")).strip()
                if doc_key and not existing_doc_key:
                    conn.execute(
                        "UPDATE gestoria_facturas SET doc_key = ?, archivo_hash = ?, dedupe_key = ?, updated_at = datetime(?) WHERE id = ?",
                        (doc_key, archivo_hash or None, dedupe_key or None, now, dup_id),
                    )
                asiento = conn.execute(
                    "SELECT id FROM gestoria_asientos WHERE factura_id = ? LIMIT 1",
                    (dup_id,),
                ).fetchone()
                try:
                    ensure_factura_doc_link(
                        conn,
                        empresa_id=empresa_id,
                        cliente_id=cliente_id,
                        factura_id=dup_id,
                        doc_key=doc_key,
                        nombre=(payload.get("filename") or parsed_factura.get("numero") or "Factura"),
                        fecha=parsed_factura.get("fecha") or "",
                        estado="Recibido",
                        notas="OCR factura (duplicado)",
                        calidad_ocr=None,
                        campos_ocr=_factura_campos_ocr_payload(parsed_factura),
                        now=now,
                    )
                except Exception:
                    pass
                return {
                    "factura_id": dup_id,
                    "asiento_id": (asiento["id"] if asiento else None),
                    "tercero_id": tercero_id,
                    "duplicate_of": dup_id,
                    "ocr_method": method,
                }
        except Exception:
            pass

        factura_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO gestoria_facturas (
              id, empresa_id, cliente_id, tercero_id, tipo, numero, fecha_emision, descripcion,
              base_imponible, base_exenta, base_no_sujeta, cuota_iva, cuota_irpf, total, iva_pct,
              tipo_operacion, estado_ocr, doc_key, raw_text,
              archivo_hash, dedupe_key,
              created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                factura_id,
                empresa_id,
                cliente_id,
                tercero_id,
                tipo_factura,
                parsed_factura.get("numero"),
                parsed_factura.get("fecha"),
                parsed_factura.get("descripcion"),
                parsed_factura.get("base_imponible") or 0.0,
                parsed_factura.get("base_exenta") or 0.0,
                parsed_factura.get("base_no_sujeta") or 0.0,
                parsed_factura.get("cuota_iva") or 0.0,
                parsed_factura.get("cuota_irpf") or 0.0,
                parsed_factura.get("total") or 0.0,
                parsed_factura.get("iva_pct") or 0.0,
                parsed_factura.get("tipo_operacion") or "",
                "ok",
                doc_key,
                parsed_factura.get("raw_text") or text,
                archivo_hash or None,
                dedupe_key or None,
                now,
                now,
            ),
        )
        try:
            ensure_factura_doc_link(
                conn,
                empresa_id=empresa_id,
                cliente_id=cliente_id,
                factura_id=factura_id,
                doc_key=doc_key,
                nombre=(payload.get("filename") or parsed_factura.get("numero") or "Factura"),
                fecha=parsed_factura.get("fecha") or "",
                estado="Recibido",
                notas="OCR factura",
                calidad_ocr=None,
                campos_ocr=_factura_campos_ocr_payload(parsed_factura),
                now=now,
            )
        except Exception:
            pass
        lines, total_debe, total_haber = build_invoice_asiento(parsed_factura, counterpart_account)
        asiento_id = os.urandom(16).hex()
        referencia = parsed_factura.get("numero") or factura_id
        concepto = parsed_factura.get("descripcion") or "Factura OCR"
        conn.execute(
            """
            INSERT INTO gestoria_asientos (
              id, empresa_id, cliente_id, factura_id, fecha, concepto, diario, referencia,
              total_debe, total_haber, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                asiento_id,
                empresa_id,
                cliente_id,
                factura_id,
                parsed_factura.get("fecha"),
                concepto,
                "FACT",
                referencia,
                total_debe,
                total_haber,
                now,
                now,
            ),
        )
        for item in lines:
            conn.execute(
                """
                INSERT INTO gestoria_asiento_lineas (
                  id, asiento_id, tercero_id, cuenta, descripcion, debe, haber,
                  impuesto_tipo, impuesto_pct, created_at, updated_at
                ) VALUES (
                  ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    asiento_id,
                    tercero_id,
                    item.get("cuenta"),
                    item.get("descripcion"),
                    item.get("debe") or 0.0,
                    item.get("haber") or 0.0,
                    item.get("impuesto"),
                    item.get("porcentaje"),
                    now,
                    now,
                ),
            )
        conn.execute(
            """
            INSERT INTO gestoria_contabilidad (
              id, empresa_id, cliente_id, cliente_ids_json, fecha, concepto, gestion, tipo, importe, notas, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                cliente_id,
                json.dumps([cliente_id], ensure_ascii=False) if cliente_id else None,
                parsed_factura.get("fecha"),
                concepto,
                "Contable",
                "Ingreso" if tipo_factura == "venta" else "Gasto",
                parsed_factura.get("total") or 0.0,
                f"Factura OCR {referencia} · asiento {asiento_id}",
                now,
                now,
            ),
        )
        return {
            "ok": True,
            "factura_id": factura_id,
            "asiento_id": asiento_id,
            "ocr_method": method,
            "parsed": parsed_factura,
            "lineas": lines,
            "totales": {"debe": total_debe, "haber": total_haber},
            "source_hint": source_hint,
        }
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


def _parse_date_ddmmyyyy_to_iso(raw: object) -> str:
    text = str(raw or "").strip()
    if not text:
        return ""
    text = text.replace("-", "/").replace(".", "/")
    match = re.search(r"([0-9]{2})/([0-9]{2})/([0-9]{4})", text)
    if not match:
        return ""
    try:
        return datetime(int(match.group(3)), int(match.group(2)), int(match.group(1))).date().isoformat()
    except Exception:
        return ""


def _score_renta_ocr_text(text: str) -> int:
    normalized = normalize_lookup_text(text or "")
    if not normalized:
        return 0
    score = min(len(normalized), 2600) // 13
    for token, weight in (
        ("AGENCIA TRIBUTARIA", 30),
        ("MODELO 100", 60),
        ("IMPUESTO SOBRE LA RENTA", 55),
        ("RESULTADO DE LA DECLARACION", 35),
        ("CODIGO SEGURO DE VERIFICACION", 25),
        ("CSV", 12),
        ("BORRADOR", 10),
        ("PRESENTACION REALIZADA", 20),
    ):
        if token in normalized:
            score += weight
    return max(0, min(300, int(score)))


def _parse_renta_pdf_fields(text: str) -> dict:
    raw = str(text or "")
    if not raw.strip():
        return {}
    normalized = normalize_lookup_text(raw)
    fields: dict[str, object] = {}

    def _code_pat(code_value: str) -> str:
        digits = re.sub(r"\D", "", str(code_value or "").strip())
        if not digits:
            return ""
        try:
            code_num = int(digits)
        except Exception:
            return ""
        core = str(code_num)
        # El OCR puede confundir dígitos con letras parecidas (0/O, 1/I/L, 5/S, 8/B, 2/Z).
        # Aceptamos esas variantes SOLO para localizar el código de casilla.
        digit_map = {
            "0": "[0O]",
            "1": "[1IL]",
            "2": "[2Z]",
            "5": "[5S]",
            "8": "[8B]",
        }
        core_pat = "".join(digit_map.get(ch, ch) for ch in core)
        return rf"(?:\[)?[0O]*{core_pat}(?:\])?"

    def _normalize_nif(value: str) -> str:
        return re.sub(r"[^0-9A-Z]", "", str(value or "").upper().strip())

    def _extract_nifs() -> tuple[str, list[str]]:
        # Nuevo extractor tolerante a OCR: separadores, letras omitidas, etc.
        primary, ordered = _find_best_nif_in_text(raw)
        if primary:
            return primary, ordered
        # Fallback: intenta con el texto normalizado.
        primary2, ordered2 = _find_best_nif_in_text(normalized)
        return primary2, ordered2

    def _extract_amount_by_code(code_value: str):
        """
        OCR/Extractores de PDF no siempre respetan el layout de la AEAT.
        Aceptamos:
        - importe ANTES de la casilla (p.ej. "12.345,67 0505")
        - casilla ANTES del importe (p.ej. "0505 12.345,67")
        - códigos sin ceros a la izquierda (p.ej. "505" en vez de "0505")
        """
        code_text = str(code_value or "").strip()
        if not code_text:
            return None
        # Normalizamos a número cuando es posible (para admitir 505 / 0505).
        digits = re.sub(r"\D", "", code_text)
        if not digits:
            return None
        try:
            int(digits)
        except Exception:
            return None
        code_pat = _code_pat(code_text)
        if not code_pat:
            return None
        # Evita capturar el siguiente "código casilla" cuando el OCR deja algo como
        # "28.993,17 0022" en la misma línea.
        amount_pat = r"([\-]?(?:[0-9]{1,3}(?:[\\. ][0-9]{3})*(?:,[0-9]{2})?|[0-9]+(?:,[0-9]{2})?))"
        # 1) Importe antes de la casilla
        # Importante: probamos primero "código -> importe" para evitar falsos positivos como
        # "MODELO 100\n0505 ..." donde el "100" podría enganchar con el 0505.
        for pat in (
            rf"(?:^|\s){code_pat}[ \t]*{amount_pat}(?:\s|$)",
            # Variante: "Casilla 505: 12.345,67"
            rf"CASILLA[ \t]*{code_pat}[^0-9\-]{{0,10}}{amount_pat}",
            # Importe antes del código (misma línea o separación corta)
            rf"{amount_pat}[ \t]+{code_pat}(?:\s|$)",
        ):
            m = re.search(pat, raw, re.IGNORECASE)
            if not m:
                continue
            # En los dos primeros patrones, el grupo 1 es el importe. En el tercero, también.
            value = parse_optional_float(m.group(1))
            if value is None:
                continue
            return round(float(value), 2)
        return None

    def _normalize_casilla_code(value: object) -> str:
        raw_code = str(value or "").strip().upper()
        # Normaliza confusiones comunes de OCR dentro del código de casilla.
        raw_code = raw_code.translate(
            str.maketrans(
                {
                    "O": "0",
                    "I": "1",
                    "L": "1",
                    "Z": "2",
                    "S": "5",
                    "B": "8",
                }
            )
        )
        digits = re.sub(r"\D", "", raw_code)
        if not digits:
            return ""
        try:
            code_num = int(digits)
        except Exception:
            return ""
        if code_num < 10 or code_num > 9999:
            return ""
        return str(code_num).zfill(4)

    def _extract_all_casillas_money() -> dict[str, float]:
        # No usamos \s+ para no unir líneas (evita emparejar una casilla con el importe de la línea anterior).
        amount_pat = r"([\-]?(?:[0-9]{1,3}(?:[\\. ][0-9]{3})*(?:,[0-9]{2})?|[0-9]+(?:,[0-9]{2})?))"
        code_any_pat = r"((?:\[)?[0O]*[0-9OILZSB]{3,4}(?:\])?)"
        out: dict[str, float] = {}
        patterns = (
            rf"(?<![0-9]){code_any_pat}[ \t]+{amount_pat}",
            rf"{amount_pat}[ \t]+{code_any_pat}(?![0-9])",
            rf"CASILLA[ \t]*{code_any_pat}[^0-9\-]{{0,10}}{amount_pat}",
        )
        for pat in patterns:
            for m in re.finditer(pat, raw, re.IGNORECASE):
                groups = m.groups() or ()
                if len(groups) < 2:
                    continue
                if pat.startswith("(?<![0-9])"):
                    code_raw, amt_raw = groups[0], groups[1]
                elif pat.startswith("CASILLA"):
                    code_raw, amt_raw = groups[0], groups[1]
                else:
                    amt_raw, code_raw = groups[0], groups[1]
                code = _normalize_casilla_code(code_raw)
                if not code:
                    continue
                # Evita falsos positivos tipo "MODELO 100 0432 ..." descartando enteros sin separador.
                if not re.search(r"[\\.,]", str(amt_raw or "")):
                    continue
                value = parse_optional_float(amt_raw)
                if value is None:
                    continue
                value = round(float(value), 2)
                prev = out.get(code)
                if prev is None or abs(value) > abs(prev):
                    out[code] = value
        return out

    match = re.search(r"Ejercicio\s*(20[0-9]{2})", raw, re.IGNORECASE)
    if match:
        fields["ejercicio"] = match.group(1)
    match = re.search(r"Expediente/Referencia[^\n\r]*?:\s*([A-Z0-9]+)", raw, re.IGNORECASE)
    if match:
        fields["expediente"] = match.group(1)
    match = re.search(r"(?:C[oó]digo Seguro de Verificaci[oó]n|CSV)\s*:?\s*([A-Z0-9]{8,})", raw, re.IGNORECASE)
    if match:
        fields["csv"] = match.group(1)

    casillas = {
        "rendimientos_trabajo_total": "0012",
        "seguridad_social": "0013",
        "rendimiento_neto_trabajo": "0022",
        "rendimiento_neto_reducido": "0025",
        "base_imponible_general": "0432",
        "base_imponible_ahorro": "0460",
        "base_liquidable_general": "0500",
        "casilla_505": "0505",
        "base_liquidable_ahorro": "0510",
        "cuota_resultante_autoliquidacion": "0595",
        "pagos_a_cuenta_total": "0609",
        "resultado_declaracion": "0670",
    }
    for key, code in casillas.items():
        value = _extract_amount_by_code(code)
        if value is None:
            continue
        fields[key] = value

    casillas_all = _extract_all_casillas_money()
    if casillas_all:
        fields["casillas"] = casillas_all
        for key, code in casillas.items():
            if key in fields:
                continue
            code_norm = _normalize_casilla_code(code)
            if code_norm and code_norm in casillas_all:
                fields[key] = casillas_all[code_norm]

    if "resultado_declaracion" not in fields:
        match = re.search(
            r"RESULTADO DE LA DECLARACI[OÓ]N[^\n\r]{0,80}?([\-]?[0-9][0-9\.,]*)",
            normalized,
            re.IGNORECASE,
        )
        if match:
            # Evita falsos positivos: en algunos OCR aparece el texto "resultado de la declaración"
            # dentro de bloques de "cuotas" (no el resultado final 0670).
            try:
                tail = normalized[match.end() : match.end() + 140]
                if "CUOTA" in tail or "BASE LIQUIDABLE" in tail or "CORRESPONDIENTE" in tail:
                    match = None
            except Exception:
                pass
        if match:
            value = parse_optional_float(match.group(1))
            if value is not None:
                fields["resultado_declaracion"] = round(float(value), 2)

    if "resultado_declaracion" not in fields:
        # Algunos modelos (o determinadas páginas) muestran:
        # "Resultado a ingresar o devolver: -709,00"
        match = re.search(
            r"Resultado\s+a\s+ingresar\s+o\s+devolver\s*:?\s*([\-]?[0-9][0-9\.,]*)",
            raw,
            re.IGNORECASE,
        )
        if match:
            value = parse_optional_float(match.group(1))
            if value is not None:
                fields["resultado_declaracion"] = round(float(value), 2)

    # Fecha de presentación (si está disponible en el PDF).
    # Primero intentamos formatos explícitos que suelen aparecer en la misma línea.
    presentacion = ""
    match = re.search(
        r"Presentaci[oó]n realizada el\s*:?\s*([0-9]{2}[/-][0-9]{2}[/-][0-9]{4})",
        raw,
        re.IGNORECASE,
    )
    if match:
        presentacion = _parse_date_ddmmyyyy_to_iso(match.group(1))
    if not presentacion:
        match = re.search(
            r"Presentad[ao]\s+el\s*:?\s*([0-9]{2}[/-][0-9]{2}[/-][0-9]{4})",
            raw,
            re.IGNORECASE,
        )
        if match:
            presentacion = _parse_date_ddmmyyyy_to_iso(match.group(1))
    if presentacion:
        fields["presentacion_fecha"] = presentacion

    def _compact_spaces(value: object) -> str:
        return " ".join(str(value or "").strip().split())

    def _find_ibans(text_value: str) -> list[str]:
        raw_value = str(text_value or "")
        if not raw_value:
            return []
        # IBAN España: ES + 22 dígitos (total 24 chars). Aceptamos separadores y espacios.
        candidates = re.findall(r"\bES[0-9][0-9 \-]{20,32}\b", raw_value, flags=re.IGNORECASE)
        out = []
        seen = set()
        for cand in candidates:
            iban = re.sub(r"[^A-Z0-9]", "", cand.upper())
            if not re.fullmatch(r"ES[0-9]{22}", iban):
                continue
            if iban in seen:
                continue
            seen.add(iban)
            out.append(iban)
            if len(out) >= 8:
                break
        return out

    def _extract_date_after(label_pat: str, *, max_distance: int = 320) -> str:
        """
        Extrae una fecha dd/mm/yyyy (o dd-mm-yyyy) que aparezca después de una etiqueta.
        Devuelve ISO yyyy-mm-dd o "" si no se encuentra.
        """
        m = re.search(label_pat, raw, re.IGNORECASE)
        if not m:
            return ""
        # La fecha puede estar en la misma línea (a la derecha) o en líneas posteriores.
        snippet = raw[m.start() : m.start() + max_distance]
        if len(snippet) < max_distance:
            snippet = snippet + raw[m.end() : m.end() + max_distance]
        m2 = re.search(r"([0-9]{2}[/-][0-9]{2}[/-][0-9]{4})", snippet)
        if not m2:
            return ""
        return _parse_date_ddmmyyyy_to_iso(m2.group(1))

    # Fallback (usa helper): buscar fecha cerca de etiquetas típicas si aún no se detectó.
    if "presentacion_fecha" not in fields:
        for pat in (
            r"Fecha\s+de\s+presentaci[oó]n",
            r"Fecha\s+presentaci[oó]n",
            r"Presentaci[oó]n\s*:",
        ):
            presentacion = _extract_date_after(pat)
            if presentacion:
                fields["presentacion_fecha"] = presentacion
                break

    def _extract_estado_civil() -> str:
        # Ejemplo típico: "Estado civil (el 31-12-2025) ... Casado/a [o007]"
        m2 = re.search(r"Estado civil", raw, re.IGNORECASE)
        window = raw[m2.start() : m2.start() + 420] if m2 else ""
        if not window:
            return ""
        # Captura el literal de estado civil.
        m3 = re.search(
            r"\b(Casado/a|Soltero/a|Divorciado/a|Viudo/a|Separado/a(?:\s+legalmente)?)\b",
            window,
            re.IGNORECASE,
        )
        if not m3:
            return ""
        return _compact_spaces(m3.group(0))

    def _extract_hijos_count():
        # Heurística conservadora: busca "hijos" cerca de un dígito.
        for pat in (
            r"(?:N[ºo]|N[úu]mero)?\s*de\s*hijos[^0-9]{0,20}([0-9]{1,2})",
            r"Hijos[^0-9]{0,20}([0-9]{1,2})\b",
        ):
            m = re.search(pat, raw, re.IGNORECASE)
            if not m:
                continue
            try:
                v = int(m.group(1))
            except Exception:
                continue
            if 0 <= v <= 20:
                return v
        return None

    def _extract_dni_meta() -> tuple[str, str, int]:
        """
        Intenta detectar metadatos del documento (Modelo 100):
        - fecha de expedición del DNI (ISO)
        - fecha de caducidad del DNI (ISO) o "" si no se detecta
        - flag DNI permanente (0/1)

        Nota: en muchos PDFs estos campos no están presentes; este extractor es best-effort.
        """
        expedicion = ""
        caducidad = ""
        permanente = 0

        # 1) Detecta "PERMANENTE" cerca de DNI/NIF.
        # Algunos OCR devuelven bloques tipo "DNI ... PERMANENTE" o "Caducidad DNI: PERMANENTE".
        for m in re.finditer(r"\b(CADUCIDAD|DNI|NIF|NIE)\b", raw, flags=re.IGNORECASE):
            start = max(0, m.start() - 80)
            end = min(len(raw), m.end() + 260)
            ctx = raw[start:end]
            if re.search(r"\bPERMANENT[EA]\b", ctx, flags=re.IGNORECASE):
                permanente = 1
                break

        # 2) Caducidad: intenta etiquetas explícitas.
        for pat in (
            r"Fecha\s+de\s+caducidad(?:\s+del\s+(?:DNI|NIF|NIE|documento))?",
            r"Caducidad(?:\s+del\s+(?:DNI|NIF|NIE|documento))?",
            r"Caduca(?:\s+el)?",
            r"DNI\s+caducidad",
        ):
            cad = _extract_date_after(pat)
            if cad:
                caducidad = cad
                break

        # 3) Expedición: intenta etiquetas explícitas.
        for pat in (
            r"Fecha\s+de\s+expedici[oó]n(?:\s+del\s+(?:DNI|NIF|NIE|documento))?",
            r"Expedici[oó]n(?:\s+del\s+(?:DNI|NIF|NIE|documento))?",
            r"Expedido(?:\s+el)?",
        ):
            exp = _extract_date_after(pat)
            if exp:
                expedicion = exp
                break

        return expedicion, caducidad, permanente

    def _extract_presentador_block() -> tuple[str, str]:
        """
        Algunos Modelo 100 incluyen el bloque del presentador con:
        - NIF del presentador
        - Apellidos y Nombre / Razón social

        En muchos casos el presentador ES el contribuyente (cliente), así que lo usamos como fallback
        cuando no podemos localizar "Primer declarante" con claridad.
        """
        m = re.search(
            r"Presentador\s+NIF\s+Presentador\s*:?\s*([A-Z0-9][A-Z0-9 .-]{6,20})",
            raw,
            re.IGNORECASE,
        )
        presentador_nif = _normalize_nif(m.group(1)) if m else ""
        m2 = re.search(
            r"Presentador\s+NIF\s+Presentador[\s\S]{0,260}?Apellidos\s+y\s+Nombre\s*/\s*Raz[oó]n\s+social\s*:?\s*([^\n\r]{3,120})",
            raw,
            re.IGNORECASE,
        )
        presentador_nombre = ""
        if m2:
            presentador_nombre = _compact_spaces(m2.group(1))
            presentador_nombre = re.split(r"\bEn\s+calidad\b", presentador_nombre, flags=re.IGNORECASE)[0].strip()
        return presentador_nif, presentador_nombre

    def _extract_cliente_nombre() -> str:
        # 1) Intento directo: etiqueta estándar de AEAT (suele aparecer junto a presentador o declarante).
        m = re.search(
            r"Apellidos\s+y\s+Nombre\s*/\s*Raz[oó]n\s+social\s*:?\s*([^\n\r]{3,120})",
            raw,
            re.IGNORECASE,
        )
        if m:
            candidate = _compact_spaces(m.group(1))
            candidate = re.split(r"\bEn\s+calidad\b", candidate, flags=re.IGNORECASE)[0].strip()
            if candidate:
                return candidate
        # 2) Fallback: usa el bloque del presentador si existe.
        _p_nif, p_nombre = _extract_presentador_block()
        if p_nombre:
            return p_nombre
        return ""

    presentador_nif, presentador_nombre = _extract_presentador_block()
    if presentador_nif:
        fields["presentador_nif"] = presentador_nif
    if presentador_nombre:
        fields["presentador_nombre"] = presentador_nombre

    cliente_nombre = _extract_cliente_nombre()
    if cliente_nombre:
        fields["cliente_nombre"] = cliente_nombre
        fields["cliente_nombre_source"] = "ocr"

    # Campos relevantes adicionales.
    estado_civil = _extract_estado_civil()
    if estado_civil:
        fields["estado_civil"] = estado_civil

    fecha_nac = _extract_date_after(r"Fecha de nacimiento(?!\s+del\s+c[óo]nyuge)")
    if fecha_nac:
        fields["cliente_fecha_nacimiento"] = fecha_nac
        fields["cliente_fecha_nacimiento_source"] = "ocr"
    conyuge_fecha_nac = _extract_date_after(r"Fecha de nacimiento del c(?:[óo]nyuge|[eé]nyuge)")
    if conyuge_fecha_nac:
        fields["conyuge_fecha_nacimiento"] = conyuge_fecha_nac

    hijos_count = _extract_hijos_count()
    if hijos_count is not None:
        fields["hijos_count"] = hijos_count

    dni_expedicion, dni_caducidad, dni_permanente = _extract_dni_meta()
    if dni_expedicion:
        fields["dni_expedicion"] = dni_expedicion
    if dni_caducidad:
        fields["dni_caducidad"] = dni_caducidad
    if dni_permanente:
        fields["dni_permanente"] = 1

    ibans = _find_ibans(raw)
    if ibans:
        fields["cuentas_detectadas"] = ibans

    nif_primary, nif_list = _extract_nifs()
    if nif_primary:
        fields["nif_detectado"] = nif_primary
        # Conveniencia: muchas partes del sistema esperan `cliente_nif`.
        if _RENTA_NIF_RE.search(nif_primary):
            fields.setdefault("cliente_nif", nif_primary)
            fields.setdefault("cliente_nif_source", "ocr")
    if nif_list:
        fields["nifs_detectados"] = nif_list

    return fields


_NOMINA_MONTHS = {
    "ENERO": 1,
    "FEBRERO": 2,
    "MARZO": 3,
    "ABRIL": 4,
    "MAYO": 5,
    "JUNIO": 6,
    "JULIO": 7,
    "AGOSTO": 8,
    "SEPTIEMBRE": 9,
    "SETIEMBRE": 9,
    "OCTUBRE": 10,
    "NOVIEMBRE": 11,
    "DICIEMBRE": 12,
}


def _parse_nomina_pdf_fields(text: str) -> dict:
    raw = str(text or "")
    if not raw.strip():
        return {}
    upper = raw.upper()
    fields: dict[str, object] = {}

    def _find_amount_near(label_patterns) -> float:
        pats = label_patterns if isinstance(label_patterns, (list, tuple)) else [label_patterns]
        for pat in pats:
            for m in re.finditer(pat, raw, flags=re.IGNORECASE):
                # recorta un contexto corto (misma línea o 200 chars).
                start = max(0, m.start() - 60)
                end = min(len(raw), m.end() + 220)
                ctx = raw[start:end]
                # Busca el último importe plausible del contexto.
                candidates = re.findall(r"[-]?(?:\d{1,3}(?:[.\s]\d{3})*(?:,\d{2})|\d+(?:,\d{2}))", ctx)
                if not candidates:
                    continue
                amt = parse_money_value(candidates[-1])
                if amt > 0:
                    return round(float(amt), 2)
        return 0.0

    # Periodo: MM/YYYY o MesNombre YYYY
    m = re.search(r"\b(?:PERIODO|PER[ÍI]ODO|LIQUIDACI[ÓO]N|DEVENGO)\b[^\n\r]{0,80}?(\d{1,2})\s*[\/\-]\s*(\d{4})", upper)
    if m:
        try:
            fields["month"] = int(m.group(1))
            fields["year"] = int(m.group(2))
        except Exception:
            pass
    if not fields.get("year"):
        # Caso típico del modelo: "Periodo de liquidación: del ... de Abril ... de 2026"
        mline = re.search(
            r"\bPERIODO\s+DE\s+LIQUIDACI[ÓO]N\b[^\n\r]{0,260}",
            upper,
            flags=re.IGNORECASE,
        )
        if mline:
            segment = mline.group(0)
            year_m = re.search(r"\b((?:19|20)\d{2})\b", segment)
            months = re.findall(r"\b(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|SETIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b", segment)
            if year_m and months:
                try:
                    fields["year"] = int(year_m.group(1))
                except Exception:
                    pass
                if not fields.get("month"):
                    fields["month"] = int(_NOMINA_MONTHS.get(months[-1].strip().upper(), 0) or 0)

        m2 = re.search(r"\b(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|SETIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b[^\n\r]{0,120}?((?:19|20)\d{2})\b", upper)
        if m2:
            fields["month"] = int(_NOMINA_MONTHS.get(m2.group(1).strip().upper(), 0) or 0)
            try:
                fields["year"] = int(m2.group(2))
            except Exception:
                pass

    # NIF/DNI del empleado: prioriza etiquetas.
    nif = ""
    m3 = re.search(r"\b(?:DNI|NIF|N\.I\.F\.|NIF/NIE|NIE)\b\s*[:\-]?\s*([A-Z0-9][A-Z0-9\-\.\s]{6,20})", upper)
    if m3:
        nif_primary, _nif_list = _find_best_nif_in_text(m3.group(1))
        nif = normalize_nif(nif_primary or m3.group(1))
    if not nif:
        # fallback: primer candidato de NIF en el texto.
        nifs = re.findall(r"\b(?:[ABCDEFGHJNPQRSUVW]\d{7}[0-9A-J]|\d{8}[A-Z])\b", upper, flags=re.IGNORECASE)
        nif = normalize_nif(nifs[0]) if nifs else ""
    if nif:
        fields["empleado_nif"] = nif

    # Nombre empleado: etiquetas típicas.
    name = ""
    for pat in (
        r"\b(?:TRABAJADOR|EMPLEADO|NOMBRE\s+Y\s+APELLIDOS|APELLIDOS\s+Y\s+NOMBRE)\b\s*[:\-]\s*([^\n\r]{4,120})",
        r"\bAPELLIDOS\b\s*[:\-]\s*([^\n\r]{2,80})\s+\bNOMBRE\b\s*[:\-]\s*([^\n\r]{2,60})",
    ):
        mname = re.search(pat, raw, flags=re.IGNORECASE)
        if not mname:
            continue
        if mname.lastindex == 2:
            candidate = f"{mname.group(1)} {mname.group(2)}"
        else:
            candidate = mname.group(1)
        candidate = re.sub(r"\\s+", " ", str(candidate or "")).strip()
        candidate = re.split(r"\b(?:NIF|DNI|NIE)\b", candidate, flags=re.IGNORECASE)[0].strip()
        if len(candidate) >= 6:
            name = candidate
            break
    if name:
        fields["empleado_nombre"] = name

    # Importes.
    neto = _find_amount_near(
        [
            r"\bL[ÍI]QUIDO\s+A\s+PERCIBIR\b",
            r"\bNETO\s+A\s+PERCIBIR\b",
            r"\bTOTAL\s+A\s+PERCIBIR\b",
            r"\bL[ÍI]QUIDO\b",
        ]
    )
    if neto > 0:
        fields["neto"] = neto
    bruto = _find_amount_near(
        [
            r"\bTOTAL\s+DEVENG(?:ADO|OS)\b",
            r"\bTOTAL\s+DEVENGOS\b",
            r"\bTOTAL\s+DEVENGADO\b",
            r"\bTOTAL\s+DEVENG\b",
            r"\bTOTAL\s+SALARIAL\b",
            # fallback (menos fiable)
            r"\bDEVENGOS\b",
            r"\bBRUTO\b",
        ]
    )
    if bruto > 0:
        fields["bruto"] = bruto
    # Heurística: si el bruto sale por debajo del neto (fallback de DEVENGOS), intenta base IRPF.
    try:
        neto_val = float(fields.get("neto") or 0) if "neto" in fields else 0.0
        bruto_val = float(fields.get("bruto") or 0) if "bruto" in fields else 0.0
        if neto_val > 0 and (bruto_val <= 0 or bruto_val < (neto_val - 0.01)):
            bruto2 = _find_amount_near(
                [
                    r"\bBASE\s+SUJETA\s+A\s+RETENCI[ÓO]N\s+DEL\s+IRPF\b",
                    r"\bBASE\s+IRPF\b",
                    r"\bBASE\s+SUJETA\b",
                ]
            )
            if bruto2 > 0:
                fields["bruto"] = bruto2
    except Exception:
        pass

    # IRPF %.
    m_irpf = re.search(r"\bIRPF\b[^\n\r]{0,80}?([0-9]{1,2}(?:[\.,][0-9]{1,2})?)\s*%", raw, flags=re.IGNORECASE)
    if m_irpf:
        try:
            fields["irpf_pct"] = round(parse_money_value(m_irpf.group(1)), 4)
        except Exception:
            pass

    # Seguridad social (trabajador/empresa): best-effort.
    ss_trab = _find_amount_near([r"\bSEGURIDAD\s+SOCIAL\b[^\n\r]{0,60}?TRAB", r"\bAPORTACI[ÓO]N\s+TRABAJADOR\b"])
    if ss_trab > 0:
        fields["ss_trabajador"] = ss_trab
    ss_emp = _find_amount_near([r"\bSEGURIDAD\s+SOCIAL\b[^\n\r]{0,60}?EMP", r"\bAPORTACI[ÓO]N\s+EMPRESA\b"])
    # Fallback: algunas nóminas no imprimen "Seguridad social empresa", pero sí el bloque
    # "APORTACIÓN DE LA EMPRESA" con varias líneas cuya última columna suma el coste SS empresa.
    if ss_emp <= 0 and "APORTACIÓN DE LA EMPRESA" in upper:
        try:
            start = upper.find("APORTACIÓN DE LA EMPRESA")
            segment = raw[start : start + 2200] if start >= 0 else raw
            total = 0.0
            for line in segment.splitlines():
                # Coge el último importe de cada línea con importes.
                amounts = re.findall(r"[-]?(?:\d{1,3}(?:[.\s]\d{3})*(?:,\d{2})|\d+(?:,\d{2}))", line)
                if len(amounts) < 2:
                    continue
                last_amt = parse_money_value(amounts[-1])
                if last_amt and float(last_amt) > 0:
                    total += float(last_amt)
            if total > 0:
                ss_emp = round(total, 2)
        except Exception:
            pass
    if ss_emp > 0:
        fields["ss_empresa"] = ss_emp

    return fields


def _detect_nif_in_nomina_page(text: str) -> str:
    raw = str(text or "")
    if not raw.strip():
        return ""
    parsed = _parse_nomina_pdf_fields(raw)
    nif = normalize_nif(parsed.get("empleado_nif") or "")
    if nif:
        return nif
    upper = raw.upper()
    candidates = re.findall(r"\b(?:[ABCDEFGHJNPQRSUVW]\d{7}[0-9A-J]|\d{8}[A-Z])\b", upper)
    if candidates:
        return normalize_nif(candidates[0])
    return ""


def split_nominas_pdf_by_nif(pdf_bytes: bytes) -> list[dict]:
    """
    Divide un PDF que contiene varias nóminas (una por empleado) en PDFs por NIF.
    Agrupa páginas contiguas: si una página no tiene NIF, se asume que pertenece al último NIF visto.
    Retorna una lista de items: {nif, pages:[idxs], pdf_bytes}.
    """
    blob = pdf_bytes or b""
    if not blob.startswith(b"%PDF"):
        return []
    try:
        from pypdf import PdfReader, PdfWriter
    except Exception:
        return []
    out: list[dict] = []
    reader = PdfReader(BytesIO(blob))
    current_nif = ""
    current_pages: list[int] = []

    def _flush():
        nonlocal current_nif, current_pages
        if not current_pages:
            current_nif = ""
            return
        writer = PdfWriter()
        for idx in current_pages:
            try:
                writer.add_page(reader.pages[idx])
            except Exception:
                pass
        buf = BytesIO()
        try:
            writer.write(buf)
        except Exception:
            current_pages = []
            current_nif = ""
            return
        out.append({"nif": current_nif, "pages": list(current_pages), "pdf_bytes": buf.getvalue()})
        current_pages = []
        current_nif = ""

    for idx, page in enumerate(reader.pages):
        text = ""
        try:
            text = page.extract_text() or ""
        except Exception:
            text = ""
        nif = _detect_nif_in_nomina_page(text)
        if nif and current_pages and nif != current_nif:
            _flush()
        if nif:
            current_nif = nif
        if not current_nif:
            continue
        current_pages.append(idx)
    _flush()
    return [it for it in out if it.get("nif") and it.get("pdf_bytes")]

def ocr_nomina_from_s3(s3_key: str, *, filename: str = "") -> dict:
    key = str(s3_key or "").strip()
    if not key:
        return {"error": "s3_key requerido", "status": "error", "confidence": 0.0}
    payload = {"s3_key": key, "filename": filename or "nomina.pdf"}
    raw_bytes, mime, _hint = decode_document_payload(payload, conn=None, session=None)
    if not raw_bytes:
        return {"error": "No se pudo leer el archivo", "status": "error", "confidence": 0.0}
    if not mime:
        mime = "application/pdf" if raw_bytes.startswith(b"%PDF") else "application/octet-stream"
    if mime != "application/pdf":
        return {"error": "Formato no soportado (solo PDF)", "status": "error", "confidence": 0.0}
    tmp_path = ""
    try:
        with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp:
            tmp.write(raw_bytes)
            tmp.flush()
            tmp_path = tmp.name
        text, err_detail, _method = extract_pdf_text(tmp_path)
        if (not text or len(str(text).strip()) < 40) and not err_detail:
            text2, ocr_err = ocr_pdf_all_pages(tmp_path, use_external=external_ocr_available())
            if text2 and len(text2.strip()) > len(str(text or "").strip()):
                text = text2
            if ocr_err and not err_detail:
                err_detail = ocr_err
        parsed = _parse_nomina_pdf_fields(text or "")
        score = 0
        if parsed.get("empleado_nif"):
            score += 3
        if parsed.get("neto"):
            score += 3
        if parsed.get("bruto"):
            score += 1
        if parsed.get("year") and parsed.get("month"):
            score += 2
        if parsed.get("empleado_nombre"):
            score += 1
        confidence = max(0.0, min(1.0, score / 9.0))
        status = "ok" if (parsed.get("empleado_nif") and parsed.get("neto") and parsed.get("year") and parsed.get("month")) else ("partial" if parsed else "empty")
        if err_detail and not text:
            return {"error": err_detail, "status": "error", "confidence": 0.0, "text": "", "fields": {}}
        return {
            "ok": True,
            "status": status,
            "confidence": confidence,
            "text": (text or "")[:220000],
            "fields": parsed,
        }
    except Exception as exc:
        return {"error": str(exc) or "OCR nómina falló", "status": "error", "confidence": 0.0}
    finally:
        try:
            if tmp_path:
                os.unlink(tmp_path)
        except Exception:
            pass


def _should_run_rrhh_nomina_ocr(payload: dict) -> bool:
    tipo = str(payload.get("tipo") or "").strip().lower()
    if tipo in {"nómina", "nomina"}:
        return True
    return False


def _fetch_rrhh_nominas_ocr(conn, workspace_id: str, persona_id: str, *, ejercicio: str = "") -> list[dict]:
    ws = str(workspace_id or "").strip()
    pid = str(persona_id or "").strip()
    year = str(ejercicio or "").strip()
    if year and not re.match(r"^20[0-9]{2}$", year):
        year = ""
    if not ws or not pid:
        return []
    rows = conn.execute(
        """
        SELECT
          id,
          tipo,
          nombre,
          fecha_emision,
          created_at,
          doc_key,
          doc_url,
          nomina_ocr_status,
          nomina_ocr_confidence,
          nomina_ocr_error,
          nomina_ocr_json,
          nomina_ocr_updated_at
        FROM workspace_rrhh_documentos
        WHERE workspace_id = ?
          AND persona_id = ?
          AND LOWER(COALESCE(tipo,'')) IN ('nómina','nomina')
        ORDER BY COALESCE(fecha_emision, created_at) DESC
        """,
        (ws, pid),
    ).fetchall()
    out: list[dict] = []
    for row in rows or []:
        payload = dict(row)
        ocr_json = payload.get("nomina_ocr_json") or ""
        fields = {}
        try:
            parsed = json.loads(ocr_json) if ocr_json else {}
            fields = parsed.get("fields") or {}
        except Exception:
            fields = {}
        y = str(fields.get("year") or "").strip()
        if year and y and y != year:
            continue
        payload["nomina_fields"] = fields
        out.append(payload)
    return out


def compute_workspace_rrhh_economicos_dashboard(conn, workspace_id, empresa_id, persona_id, ejercicio=""):
    ws = str(workspace_id or "").strip()
    pid = str(persona_id or "").strip()
    eid = str(empresa_id or "").strip()
    year = str(ejercicio or "").strip()
    if year and not re.match(r"^20[0-9]{2}$", year):
        year = ""
    if not ws or not pid:
        return {"kpis": {}, "services": {}}

    nominas = _fetch_rrhh_nominas_ocr(conn, ws, pid, ejercicio=year)
    coste_total = 0.0
    neto_total = 0.0
    for n in nominas:
        f = n.get("nomina_fields") or {}
        bruto = float(parse_money_value(f.get("bruto") or 0) or 0)
        ss_emp = float(parse_money_value(f.get("ss_empresa") or 0) or 0)
        neto = float(parse_money_value(f.get("neto") or 0) or 0)
        coste_total += bruto + ss_emp
        neto_total += neto

    service_keys = ["renta", "seguros", "hipotecas", "gestoria", "fincas"]
    services = {}
    pending = {"total": 0, "services": {}, "top": []}
    service_payloads = {}
    facturado_total = 0.0
    comision_total = 0.0
    comision_cobrada = 0.0
    items_count = 0
    cobradas_count = 0

    manual_all = fetch_workspace_rrhh_productividad_manual(conn, ws, pid, service="", ejercicio=year)
    for it in manual_all or []:
        st = str(it.get("estado_cobro") or ("cobrado" if int(it.get("cobrada") or 0) == 1 else "pendiente")).strip().lower()
        items_count += 1
        if st == "cobrado":
            cobradas_count += 1
        base = float(parse_money_value(it.get("importe_base") or 0) or 0)
        com = float(parse_money_value(it.get("comision") or 0) or 0)
        facturado_total += base
        comision_total += com
        if st == "cobrado":
            comision_cobrada += com
        if st != "cobrado":
            pending["total"] += 1
            pending["services"].setdefault("manual", {"pendientes": 0})
            pending["services"]["manual"]["pendientes"] += 1
            if len(pending["top"]) < 10:
                pending["top"].append(
                    {
                        "service": "manual",
                        "label": str(it.get("cliente_nombre") or it.get("descripcion") or "Apunte manual").strip() or "Apunte manual",
                        "meta": str(it.get("fecha") or "").strip(),
                        "kind": "cobro",
                    }
                )

    for sk in service_keys:
        try:
            payload = compute_workspace_rrhh_productividad(conn, ws, eid, pid, sk, ejercicio=year)
        except Exception:
            payload = {"kpis": {}, "items": []}
        service_payloads[sk] = payload
        k = payload.get("kpis") or {}
        facturado_total += float(parse_money_value(k.get("facturado_total") or 0) or 0)
        comision_total += float(parse_money_value(k.get("comision_total") or 0) or 0)
        for it in payload.get("items") or []:
            st = str(it.get("estado_cobro") or ("cobrado" if int(it.get("cobrada") or 0) == 1 else "pendiente")).strip().lower()
            items_count += 1
            if st == "cobrado":
                cobradas_count += 1
            com = float(parse_money_value(it.get("comision") or 0) or 0)
            if st == "cobrado":
                comision_cobrada += com

            is_pending = False
            kind = "cobro"
            if sk == "renta":
                estado = str(it.get("estado_presentacion") or "").strip()
                if estado and estado.lower() != "presentada":
                    is_pending = True
                    kind = "cierre"
                elif int(it.get("cobrada") or 0) != 1:
                    is_pending = True
                    kind = "cobro"
            elif sk in {"seguros", "hipotecas"}:
                if int(it.get("cobrada") or 0) != 1:
                    is_pending = True
                    kind = "cobro"
            elif sk in {"gestoria", "fincas"}:
                if int(it.get("pendientes") or 0) > 0:
                    is_pending = True
                    kind = "cobro"
            else:
                if st != "cobrado":
                    is_pending = True
                    kind = "cobro"

            if is_pending:
                pending["total"] += 1
                svc_row = pending["services"].setdefault(sk, {"pendientes": 0})
                svc_row["pendientes"] += 1
                if len(pending["top"]) < 10:
                    label = (
                        str(it.get("cliente_nombre") or it.get("cliente") or "").strip()
                        or str(it.get("cliente_nif") or "").strip()
                        or str(it.get("poliza_numero") or it.get("banco") or it.get("cliente_id") or "").strip()
                        or "Expediente"
                    )
                    meta = str(
                        it.get("fecha")
                        or it.get("presentacion_fecha")
                        or it.get("fecha_firma")
                        or it.get("ejercicio")
                        or ""
                    ).strip()
                    pending["top"].append({"service": sk, "label": label, "meta": meta, "kind": kind})
        services[sk] = {"kpis": k}

    beneficio = facturado_total - coste_total
    rentabilidad_pct = (beneficio / coste_total) * 100.0 if coste_total > 0 else 0.0

    # Serie mensual (para gráficos): coste laboral vs comisiones y cobertura (comisión cobrada / coste).
    series = {
        "labels": [],
        "coste": [],
        "comision_total": [],
        "comision_cobrada": [],
        "indice_rentabilidad_pct": [],
    }
    if year:
        by_month = {m: {"coste": 0.0, "comision_total": 0.0, "comision_cobrada": 0.0} for m in range(1, 13)}

        for n in nominas:
            f = n.get("nomina_fields") or {}
            try:
                m = int(f.get("month") or 0)
            except Exception:
                m = 0
            if m < 1 or m > 12:
                continue
            bruto = float(parse_money_value(f.get("bruto") or 0) or 0)
            ss_emp = float(parse_money_value(f.get("ss_empresa") or 0) or 0)
            by_month[m]["coste"] += bruto + ss_emp

        def _month_from_date(raw):
            s = str(raw or "").strip()
            if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
                try:
                    return int(s[5:7])
                except Exception:
                    return 0
            return 0

        def _add_item(it):
            st = str(it.get("estado_cobro") or ("cobrado" if int(it.get("cobrada") or 0) == 1 else "pendiente")).strip().lower()
            m = _month_from_date(it.get("fecha_cobro") or it.get("fecha") or it.get("presentacion_fecha") or it.get("fecha_firma"))
            if m < 1 or m > 12:
                return
            com = float(parse_money_value(it.get("comision") or 0) or 0)
            by_month[m]["comision_total"] += com
            if st == "cobrado":
                by_month[m]["comision_cobrada"] += com

        for it in manual_all or []:
            _add_item(it)
        for payload in service_payloads.values():
            for it in payload.get("items") or []:
                _add_item(it)

        for m in range(1, 13):
            series["labels"].append(f"{year}-{m:02d}")
            coste = float(by_month[m]["coste"] or 0)
            com_t = float(by_month[m]["comision_total"] or 0)
            com_c = float(by_month[m]["comision_cobrada"] or 0)
            series["coste"].append(round(coste, 2))
            series["comision_total"].append(round(com_t, 2))
            series["comision_cobrada"].append(round(com_c, 2))
            idx = (com_c / coste) * 100.0 if coste > 0 else 0.0
            series["indice_rentabilidad_pct"].append(round(idx, 2))

    return {
        "kpis": {
            "ejercicio": year or "",
            "facturado_total": round(facturado_total, 2),
            "comision_total": round(comision_total, 2),
            "comision_cobrada": round(comision_cobrada, 2),
            "coste_total": round(coste_total, 2),
            "nomina_neto_total": round(neto_total, 2),
            "beneficio": round(beneficio, 2),
            "rentabilidad_pct": round(rentabilidad_pct, 2),
            "items": int(items_count),
            "cobradas": int(cobradas_count),
        },
        "services": services,
        "pending": pending,
        "series": series,
    }


def _render_rrhh_memoria_pdf(*, persona_nombre: str, ejercicio: str, kpis: dict, by_month: dict) -> bytes:
    if not rl_canvas or not rl_colors:
        raise ValueError("PDF no disponible (reportlab no instalado)")
    name = str(persona_nombre or "").strip() or "Trabajador"
    year = str(ejercicio or "").strip() or str(datetime.now().year)

    def eur(v):
        try:
            return f"{float(v):,.2f} €".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "0,00 €"

    def pct(v):
        try:
            return f"{float(v):.2f}%".replace(".", ",")
        except Exception:
            return "0,00%"

    buf = BytesIO()
    c = rl_canvas.Canvas(buf, pagesize=(595.28, 841.89))  # A4
    w, h = 595.28, 841.89
    margin = 36

    # Header
    c.setFillColor(rl_colors.HexColor("#0b1b2a"))
    c.rect(0, h - 86, w, 86, stroke=0, fill=1)
    c.setFillColor(rl_colors.white)
    c.setFont("Helvetica-Bold", 16)
    c.drawString(margin, h - 42, "Memoria económica")
    c.setFont("Helvetica", 11)
    c.drawString(margin, h - 62, f"{name} · Ejercicio {year}")

    # KPI cards
    cards = [
        ("Facturado", eur(kpis.get("facturado_total", 0))),
        ("Comisión cobrada", eur(kpis.get("comision_cobrada", 0))),
        ("Coste (nómina)", eur(kpis.get("coste_total", 0))),
        ("Beneficio", eur(kpis.get("beneficio", 0))),
        ("Rentabilidad", pct(kpis.get("rentabilidad_pct", 0))),
    ]
    c.setFillColor(rl_colors.black)
    c.setFont("Helvetica-Bold", 11)
    c.drawString(margin, h - 120, "KPIs")
    x0 = margin
    y0 = h - 160
    card_w = (w - margin * 2 - 12) / 2
    card_h = 46
    gap = 12
    c.setFont("Helvetica", 9)
    for i, (label, value) in enumerate(cards):
        col = i % 2
        row = i // 2
        x = x0 + col * (card_w + gap)
        y = y0 - row * (card_h + gap)
        c.setFillColor(rl_colors.HexColor("#f6f7f9"))
        c.roundRect(x, y, card_w, card_h, 8, stroke=0, fill=1)
        c.setFillColor(rl_colors.HexColor("#172b3a"))
        c.setFont("Helvetica", 9)
        c.drawString(x + 12, y + card_h - 16, label)
        c.setFont("Helvetica-Bold", 12)
        c.drawString(x + 12, y + 14, value)

    # Chart: Comision cobrada vs Coste (por mes)
    c.setFillColor(rl_colors.HexColor("#172b3a"))
    c.setFont("Helvetica-Bold", 11)
    c.drawString(margin, h - 330, "Evolución mensual (comisión cobrada vs coste nómina)")
    chart_x = margin
    chart_y = h - 620
    chart_w = w - margin * 2
    chart_h = 250
    c.setFillColor(rl_colors.HexColor("#ffffff"))
    c.roundRect(chart_x, chart_y, chart_w, chart_h, 10, stroke=1, fill=1)

    series = []
    for m in range(1, 13):
        r = by_month.get(m) or {}
        com_c = float(r.get("comision_cobrada") or 0)
        coste = float(r.get("nomina_bruto") or 0) + float(r.get("nomina_ss_empresa") or 0)
        series.append((m, com_c, coste))
    max_val = max([v for _m, a, b in series for v in (a, b)] + [1.0])
    inner_pad = 18
    bx0 = chart_x + inner_pad
    by0 = chart_y + inner_pad
    bw = chart_w - inner_pad * 2
    bh = chart_h - inner_pad * 2
    bar_gap = 6
    pair_w = bw / 12
    bar_w = (pair_w - bar_gap) / 2
    c.setStrokeColor(rl_colors.HexColor("#e3e7ee"))
    for i in range(6):
        yy = by0 + (bh * i / 5)
        c.line(bx0, yy, bx0 + bw, yy)
    for i, (m, com_c, coste) in enumerate(series):
        px = bx0 + i * pair_w
        h1 = (com_c / max_val) * bh
        h2 = (coste / max_val) * bh
        c.setFillColor(rl_colors.HexColor("#2f80ed"))
        c.rect(px, by0, bar_w, h1, stroke=0, fill=1)
        c.setFillColor(rl_colors.HexColor("#f2994a"))
        c.rect(px + bar_w + bar_gap, by0, bar_w, h2, stroke=0, fill=1)
        c.setFillColor(rl_colors.HexColor("#5b6b7a"))
        c.setFont("Helvetica", 7)
        c.drawCentredString(px + pair_w / 2, chart_y + 6, f"{m:02d}")

    c.setFillColor(rl_colors.HexColor("#2f80ed"))
    c.setFont("Helvetica", 8)
    c.drawString(chart_x + 16, chart_y + chart_h - 14, "■ Comisión cobrada")
    c.setFillColor(rl_colors.HexColor("#f2994a"))
    c.drawString(chart_x + 140, chart_y + chart_h - 14, "■ Coste nómina")

    c.showPage()
    c.save()
    return buf.getvalue()


def process_renta_ocr_job(payload, conn):
    raw_bytes, mime, payload_hint = decode_seguros_payload(payload, conn=None, session=None)
    tmp_path = None
    text = ""
    err_detail = ""
    method = ""
    source_hint = " ".join(
        [
            str(payload.get("filename") or ""),
            str(payload.get("s3_key") or ""),
            str(payload.get("source_hint") or ""),
            str(payload_hint or ""),
        ]
    ).strip()
    try:
        suffix = ".pdf"
        if mime and mime.startswith("image/"):
            suffix = ".png" if "png" in mime else ".jpg"
        with tempfile.NamedTemporaryFile(suffix=suffix, delete=False) as tmp_file:
            tmp_file.write(raw_bytes)
            tmp_path = tmp_file.name
        if mime == "application/pdf":
            # OCR de renta: prioriza rutas rápidas (1-2 páginas) para evitar jobs muy lentos.
            text, err_detail, method = extract_renta_pdf_text(tmp_path, source_hint=source_hint)
        else:
            method = "vision" if external_ocr_available() else "tesseract"
            image_text = ""
            image_err = ""
            if external_ocr_available():
                vision_bytes = prepare_image_bytes_for_vision(tmp_path)
                if vision_bytes:
                    image_text, image_err = ocr_image_external(vision_bytes)
            if not image_text:
                image_text, image_err = ocr_pdf_first_page(tmp_path)
            text = image_text or ""
            if image_err and not err_detail:
                err_detail = image_err
        if not text:
            # Degradación controlada: si no hay OCR disponible (p.ej. Render sin tesseract y sin Vision),
            # no fallamos el job: devolvemos campos vacíos para que el flujo "carga rápida" guarde el PDF
            # y permita asignación manual.
            parsed_fields = {}
            if err_detail:
                parsed_fields["ocr_error"] = str(err_detail)[:240]
            parsed_fields["nif_detectado"] = ""
            parsed_fields["ocr_score"] = 0
            parsed_fields["ocr_method"] = method or ("vision" if external_ocr_available() else "tesseract")
            if source_hint:
                parsed_fields["ocr_source_hint"] = source_hint
            return {"fields": parsed_fields, "ocr_method": parsed_fields["ocr_method"], "ocr_score": 0}

        parsed_fields = _parse_renta_pdf_fields(text)
        if not isinstance(parsed_fields, dict):
            parsed_fields = {}
        # Fallback extra: si el parser no detectó NIF pero hay texto OCR, intenta extraerlo
        # directamente (tolerante a separadores/saltos de línea).
        if not str(parsed_fields.get("nif_detectado") or "").strip():
            nif_primary, nif_list = _find_best_nif_in_text(text)
            if nif_primary:
                parsed_fields["nif_detectado"] = nif_primary
            if nif_list:
                parsed_fields["nifs_detectados"] = nif_list
        score = _score_renta_ocr_text(text)
        parsed_fields["ocr_score"] = score
        parsed_fields["ocr_method"] = method or ("vision" if external_ocr_available() else "tesseract")
        if err_detail:
            parsed_fields["ocr_error"] = str(err_detail)[:240]
        if source_hint:
            parsed_fields["ocr_source_hint"] = source_hint
        return {
            "fields": parsed_fields,
            "ocr_method": parsed_fields.get("ocr_method") or method,
            "ocr_score": score,
        }
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


def _update_workspace_inbox_ocr(conn, workspace_id, document_id, fields, now="now"):
    if not workspace_id or not document_id:
        return False
    allowed = ("estado", "ocr_job_id", "ocr_status", "ocr_error", "ocr_method", "factura_id", "asiento_id")
    updates = []
    values = []
    for key in allowed:
        if key in fields:
            updates.append(f"{key} = ?")
            values.append(fields.get(key))
    if not updates:
        return False
    values.extend([now, document_id, workspace_id])
    conn.execute(
        f"""
        UPDATE workspace_documentos_inbox
        SET {", ".join(updates)}, updated_at = datetime(?)
        WHERE id = ? AND workspace_id = ?
        """,
        values,
    )
    return True


def process_workspace_factura_ocr_job(payload, conn, now="now"):
    workspace_id = str(payload.get("workspace_id") or "").strip()
    document_id = str(payload.get("document_id") or payload.get("document_inbox_id") or "").strip()
    empresa_id = str(payload.get("empresa_id") or "").strip()
    cliente_id = (payload.get("cliente_id") or "").strip() or None
    s3_key = (payload.get("s3_key") or "").strip()
    enriched = dict(payload)
    if workspace_id and document_id:
        row = conn.execute(
            """
            SELECT empresa_id, cliente_id, doc_key, nombre, clasificacion
            FROM workspace_documentos_inbox
            WHERE id = ? AND workspace_id = ?
            LIMIT 1
            """,
            (document_id, workspace_id),
        ).fetchone()
        if row:
            if not empresa_id:
                empresa_id = str(row["empresa_id"] or "").strip()
            if not cliente_id:
                cliente_id = str(row["cliente_id"] or "").strip() or None
            if not s3_key:
                s3_key = str(row["doc_key"] or "").strip()
            if not enriched.get("filename"):
                enriched["filename"] = str(row["nombre"] or "").strip()
            if not enriched.get("source_hint"):
                enriched["source_hint"] = str(row["clasificacion"] or "").strip()
    if not empresa_id:
        raise ValueError("empresa_id no disponible para OCR de factura")
    if not s3_key and not (enriched.get("file_base64") or enriched.get("data")):
        raise ValueError("Documento sin doc_key/s3_key")
    if not enriched.get("s3_key") and s3_key:
        enriched["s3_key"] = s3_key
    if not enriched.get("cliente_id") and cliente_id:
        enriched["cliente_id"] = cliente_id
    if workspace_id and document_id:
        _update_workspace_inbox_ocr(
            conn,
            workspace_id,
            document_id,
            {"estado": "OCR procesando", "ocr_status": "processing"},
            now=now,
        )
    try:
        result = process_gestoria_factura_ocr(enriched, conn, empresa_id=empresa_id, now=now)
    except Exception as exc:
        if workspace_id and document_id:
            _update_workspace_inbox_ocr(
                conn,
                workspace_id,
                document_id,
                {"estado": "Revisar", "ocr_status": "error", "ocr_error": str(exc)},
                now=now,
            )
        raise
    if workspace_id and document_id:
        estado_final = "Duplicado" if (result.get("duplicate_of") or "") else "Procesado"
        _update_workspace_inbox_ocr(
            conn,
            workspace_id,
            document_id,
            {
                "estado": estado_final,
                "ocr_status": "done",
                "ocr_error": None,
                "ocr_method": result.get("ocr_method"),
                "factura_id": result.get("factura_id"),
                "asiento_id": result.get("asiento_id"),
            },
            now=now,
        )
    return result


def enqueue_ocr_job(db_path, kind, payload):
    job_id = os.urandom(16).hex()
    now = datetime.now(timezone.utc).isoformat()
    conn = open_sqlite_conn(db_path, with_row_factory=False)
    conn.execute(
        """
        INSERT INTO ocr_jobs (id, kind, status, payload_json, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (job_id, kind, "pending", json.dumps(payload), now, now),
    )
    conn.commit()
    conn.close()
    return job_id


def fetch_next_ocr_job(conn):
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=OCR_JOB_STALE_MINUTES)).isoformat()
    row = conn.execute(
        """
        SELECT id, kind, payload_json
        FROM ocr_jobs
        WHERE status = 'pending'
           OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
        ORDER BY created_at ASC
        LIMIT 1
        """,
        (cutoff,),
    ).fetchone()
    return row


def claim_next_ocr_job(conn):
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=OCR_JOB_STALE_MINUTES)).isoformat()
    now = datetime.now(timezone.utc).isoformat()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT id, kind, payload_json
            FROM ocr_jobs
            WHERE status = 'pending'
               OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
            ORDER BY created_at ASC
            LIMIT 1
            """,
            (cutoff,),
        ).fetchone()
        if not row:
            conn.commit()
            return None
        updated = conn.execute(
            """
            UPDATE ocr_jobs
            SET status = 'processing', error = NULL, started_at = ?, updated_at = ?
            WHERE id = ?
              AND (
                status = 'pending'
                OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
              )
            """,
            (now, now, row["id"], cutoff),
        ).rowcount
        conn.commit()
        if updated == 1:
            return row
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    return None


def update_ocr_job(conn, job_id, status, result=None, error=None):
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        """
        UPDATE ocr_jobs
        SET status = ?, result_json = COALESCE(?, result_json), error = ?, updated_at = ?,
            started_at = CASE
                WHEN ? = 'processing' THEN ?
                WHEN started_at IS NULL THEN ?
                ELSE started_at
            END,
            finished_at = CASE WHEN ? IN ('done','error') THEN ? ELSE finished_at END
        WHERE id = ?
        """,
        (
            status,
            json.dumps(result) if result is not None else None,
            error,
            now,
            status,
            now,
            now,
            status,
            now,
            job_id,
        ),
    )


def ocr_worker_loop(jobs_db_path, main_db_path):
    while True:
        jobs_conn = None
        job_id = None
        try:
            jobs_conn = open_sqlite_conn(jobs_db_path, with_row_factory=True)
            row = claim_next_ocr_job(jobs_conn)
            if not row:
                jobs_conn.close()
                time.sleep(0.6)
                continue
            job_id = row["id"]
            kind = row["kind"]
            payload = json.loads(row["payload_json"] or "{}")
            main_conn = None
            try:
                # En Postgres, get_db ignora main_db_path y abre pool Postgres con compat SQLite.
                main_conn = get_db(main_db_path)
                if kind == "seguros":
                    result = process_seguros_ocr(payload, main_conn)
                elif kind == "factura":
                    result = process_workspace_factura_ocr_job(payload, main_conn, now="now")
                elif kind == "renta":
                    result = process_renta_ocr_job(payload, main_conn)
                    now = datetime.now(timezone.utc).isoformat()
                    cliente_id = str(payload.get("cliente_id") or "").strip()
                    entry_id = str(payload.get("entry_id") or "").strip()
                    doc_id = str(payload.get("doc_id") or "").strip()
                    extracted = (result or {}).get("fields") or {}
                    if cliente_id and entry_id and extracted:
                        cg_row = main_conn.execute(
                            "SELECT renta_detalles FROM cliente_gestoria WHERE cliente_id = ?",
                            (cliente_id,),
                        ).fetchone()
                        renta_payload = parse_renta_detalles_payload(cg_row["renta_detalles"] if cg_row else "")
                        entries = sanitize_renta_entries(renta_payload.get("entries") or [])
                        current_entry = next(
                            (item for item in entries if str(item.get("id") or "").strip() == entry_id),
                            None,
                        )
                        if current_entry:
                            updated = dict(current_entry)
                            for key in (
                                "rendimientos_trabajo_total",
                                "base_imponible_general",
                                "base_imponible_ahorro",
                                "base_liquidable_general",
                                "base_liquidable_ahorro",
                                "casilla_505",
                                "cuota_resultante_autoliquidacion",
                                "pagos_a_cuenta_total",
                                "resultado_declaracion",
                                "presentacion_fecha",
                                "dni_expedicion",
                                "dni_caducidad",
                                "dni_permanente",
                                "csv",
                                "expediente",
                            ):
                                if key not in extracted:
                                    continue
                                value = extracted.get(key)
                                if value in (None, "", [], {}):
                                    continue
                                existing = updated.get(key)
                                if existing in (None, "", [], {}):
                                    updated[key] = value
                                    continue
                                if isinstance(value, (int, float)):
                                    prev = coerce_renta_money(existing)
                                    if (prev is None or abs(prev) < 0.0001) and abs(float(value)) >= 0.0001:
                                        updated[key] = value
                            casillas_in = extracted.get("casillas")
                            if isinstance(casillas_in, dict) and casillas_in:
                                prev = updated.get("casillas") if isinstance(updated.get("casillas"), dict) else {}
                                merged = dict(prev or {})
                                for code, amt in casillas_in.items():
                                    code_key = str(code or "").strip()
                                    if not code_key:
                                        continue
                                    try:
                                        value_num = float(amt)
                                    except Exception:
                                        continue
                                    prev_val = merged.get(code_key)
                                    if prev_val is None:
                                        merged[code_key] = round(value_num, 2)
                                        continue
                                    try:
                                        prev_num = float(prev_val)
                                    except Exception:
                                        merged[code_key] = round(value_num, 2)
                                        continue
                                    if abs(value_num) > abs(prev_num):
                                        merged[code_key] = round(value_num, 2)
                                if merged:
                                    updated["casillas"] = merged
                            updated["ocr_status"] = "done"
                            updated["ocr_method"] = str(extracted.get("ocr_method") or "").strip()
                            updated["ocr_score"] = extracted.get("ocr_score")
                            upsert_cliente_renta_entry(main_conn, cliente_id, updated, now)
                            if doc_id:
                                try:
                                    campos = [
                                        k
                                        for k in (
                                            "casilla_505",
                                            "resultado_declaracion",
                                            "base_imponible_general",
                                            "base_imponible_ahorro",
                                            "base_liquidable_general",
                                            "base_liquidable_ahorro",
                                            "rendimientos_trabajo_total",
                                            "cuota_resultante_autoliquidacion",
                                            "pagos_a_cuenta_total",
                                            "dni_expedicion",
                                            "dni_caducidad",
                                            "dni_permanente",
                                            "csv",
                                            "expediente",
                                        )
                                        if extracted.get(k) not in (None, "", [], {})
                                    ]
                                    main_conn.execute(
                                        """
                                        UPDATE gestoria_docs
                                        SET calidad_ocr = ?, campos_ocr = ?, updated_at = datetime(?)
                                        WHERE id = ?
                                        """,
                                        (
                                            f"Renta OCR ({(result or {}).get('ocr_method') or 'tesseract'})",
                                            ",".join(campos),
                                            now,
                                            doc_id,
                                        ),
                                    )
                                except Exception:
                                    pass
                else:
                    raise RuntimeError("Tipo OCR no soportado")
                try:
                    main_conn.commit()
                except Exception:
                    pass
            finally:
                try:
                    if main_conn is not None:
                        main_conn.close()
                except Exception:
                    pass
            update_ocr_job(jobs_conn, job_id, "done", result=result, error=None)
            jobs_conn.commit()
            jobs_conn.close()
        except Exception as exc:
            try:
                if jobs_conn and job_id:
                    update_ocr_job(jobs_conn, job_id, "error", result=None, error=str(exc))
                    jobs_conn.commit()
            except Exception:
                pass
            try:
                if jobs_conn:
                    jobs_conn.close()
            except Exception:
                pass
            time.sleep(1.0)

def preprocess_image_for_ocr(src_path, out_path=None):
    tmp_base = tempfile.gettempdir()
    created = False
    if not out_path:
        tmp_file = tempfile.NamedTemporaryFile(suffix=".png", delete=False, dir=tmp_base)
        out_path = tmp_file.name
        tmp_file.close()
        created = True
    magick = shutil.which("magick") or shutil.which("convert")
    if magick and os.path.exists(magick):
        try:
            run_subprocess(
                [
                    magick,
                    src_path,
                    "-colorspace",
                    "Gray",
                    "-density",
                    "300",
                    "-resize",
                    "2500x2500",
                    "-deskew",
                    "40%",
                    "-sharpen",
                    "0x1",
                    "-contrast-stretch",
                    "1%x1%",
                    out_path,
                ],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
                text=True,
            )
            return out_path, created
        except Exception:
            pass
    try:
        run_subprocess(
            ["sips", "-s", "format", "png", src_path, "--out", out_path],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        try:
            run_subprocess(
                ["sips", "-Z", "2400", out_path, "--out", out_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            pass
        return out_path, created
    except Exception:
        return src_path, created

def ocr_image_file(image_path):
    lang = detect_ocr_lang()
    tesseract_cmd = resolve_tesseract_cmd()
    # Si OCR externo está disponible, lo intentamos primero para evitar depender del PATH de tesseract
    # (especialmente en entornos tipo launchd/worker).
    if external_ocr_available():
        try:
            vision_bytes = prepare_image_bytes_for_vision(image_path)
            if vision_bytes:
                text, err = ocr_image_external(vision_bytes)
                if text and text.strip():
                    return text, ""
                if err and not (tesseract_cmd and os.path.exists(tesseract_cmd)):
                    return "", err
        except Exception:
            pass
    if not tesseract_cmd or not os.path.exists(tesseract_cmd):
        return "", "tesseract no encontrado (configura OCR_TESSERACT_CMD o instala tesseract)"
    env = os.environ.copy()
    if os.path.isdir(TESSDATA_DIR):
        env["TESSDATA_PREFIX"] = TESSDATA_DIR
    tmp_base = tempfile.gettempdir()
    with tempfile.TemporaryDirectory(dir=tmp_base) as tmpdir:
        processed, created = preprocess_image_for_ocr(image_path)
        variants = [processed]
        magick = shutil.which("magick") or shutil.which("convert")
        if magick and os.path.exists(magick) and os.path.exists(processed):
            for idx, extra in enumerate(
                (
                    ["-threshold", "55%", "-despeckle"],
                    ["-adaptive-threshold", "15x15+10%", "-sharpen", "0x1.2"],
                )
            ):
                out_variant = os.path.join(tmpdir, f"ocr_var_{idx}.png")
                try:
                    run_subprocess(
                        [magick, processed, *extra, out_variant],
                        check=True,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.PIPE,
                        text=True,
                    )
                    if os.path.exists(out_variant):
                        variants.append(out_variant)
                except Exception:
                    continue
        def run_tesseract(psm, source_path):
            result = run_subprocess(
                [
                    tesseract_cmd,
                    source_path,
                    "stdout",
                    "-l",
                    lang,
                    "--oem",
                    "1",
                    "--psm",
                    str(psm),
                    "-c",
                    "user_defined_dpi=300",
                    "-c",
                    "preserve_interword_spaces=1",
                ],
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=env,
                text=True,
            )
            return result.stdout or ""
        try:
            candidates = []
            for source_path in variants:
                for psm in OCR_TESSERACT_PSMS:
                    try:
                        candidates.append(run_tesseract(psm, source_path))
                    except subprocess.CalledProcessError:
                        continue
            if not candidates:
                return "", "tesseract: sin salida"
            best = max(candidates, key=lambda t: (len(t.strip()), sum(ch.isdigit() for ch in t)))
            return best, ""
        except subprocess.CalledProcessError as err:
            return "", f"tesseract: {err.stderr.strip()}"
        except Exception as err:
            return "", f"tesseract: {err}"
        finally:
            if created and processed and os.path.exists(processed):
                try:
                    os.unlink(processed)
                except Exception:
                    pass

