def ensure_inmueble_doc_cliente_link(conn, inmueble_row, doc_row, cliente_id, now):
    if not inmueble_row or not doc_row or not cliente_id:
        return None
    tables = {
        row["name"]
        for row in conn.execute("SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('gestoria_docs', 'inmuebles')")
    }
    if "gestoria_docs" not in tables or "inmuebles" not in tables:
        return None
    empresa_id = str(inmueble_row["empresa_id"] or "").strip()
    doc_url = str(doc_row["url"] or "").strip()
    if not empresa_id or not doc_url:
        return None
    referencia_id = str(doc_row["id"] or "").strip()
    existing = conn.execute(
        """
        SELECT id
        FROM gestoria_docs
        WHERE cliente_id = ?
          AND empresa_id = ?
          AND LOWER(COALESCE(referencia_tipo, '')) = 'inmobiliaria'
          AND (
            referencia_id = ?
            OR doc_url = ?
          )
        LIMIT 1
        """,
        (cliente_id, empresa_id, referencia_id, doc_url),
    ).fetchone()
    nombre = str(doc_row["nombre"] or doc_row["tipo"] or "Documento inmobiliario").strip()
    estado = str(doc_row["estado"] or "Vigente").strip()
    fecha = str(doc_row["updated_at"] or doc_row["created_at"] or "").strip()
    if len(fecha) >= 10:
        fecha = fecha[:10]
    notas_parts = [
        str(inmueble_row["direccion"] or "").strip(),
        str(inmueble_row["referencia_catastral"] or "").strip(),
        str(doc_row["tipo"] or "").strip(),
    ]
    notas = " · ".join(part for part in notas_parts if part)
    if existing:
        conn.execute(
            """
            UPDATE gestoria_docs
            SET referencia_id = ?,
                nombre = COALESCE(NULLIF(?, ''), nombre),
                tipo = COALESCE(NULLIF(?, ''), tipo),
                fecha = COALESCE(NULLIF(?, ''), fecha),
                estado = COALESCE(NULLIF(?, ''), estado),
                notas = COALESCE(NULLIF(?, ''), notas),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                referencia_id,
                nombre,
                "Inmobiliaria",
                fecha,
                estado,
                notas,
                doc_url,
                now,
                existing["id"],
            ),
        )
        return existing["id"]
    doc_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_docs (
          id, empresa_id, cliente_id, referencia_tipo, referencia_id,
          nombre, tipo, fecha, estado, notas, doc_url,
          created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            doc_id,
            empresa_id,
            cliente_id,
            "inmobiliaria",
            referencia_id,
            nombre,
            "Inmobiliaria",
            fecha or None,
            estado or "Vigente",
            notas or None,
            doc_url,
            now,
            now,
        ),
    )
    return doc_id


def sync_inmueble_docs_for_inmueble(conn, inmueble_id, now):
    if not inmueble_id:
        return {"linked": 0, "removed": 0}
    tables = {
        row["name"]
        for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('inmuebles', 'inmueble_propietarios', 'inmueble_docs', 'gestoria_docs')"
        )
    }
    required = {"inmuebles", "inmueble_propietarios", "inmueble_docs", "gestoria_docs"}
    if not required.issubset(tables):
        return {"linked": 0, "removed": 0}
    inmueble = conn.execute(
        "SELECT * FROM inmuebles WHERE id = ? LIMIT 1",
        (inmueble_id,),
    ).fetchone()
    if not inmueble:
        return {"linked": 0, "removed": 0}
    owner_ids = [
        str(row["cliente_id"] or "").strip()
        for row in conn.execute(
            "SELECT cliente_id FROM inmueble_propietarios WHERE inmueble_id = ?",
            (inmueble_id,),
        ).fetchall()
        if str(row["cliente_id"] or "").strip()
    ]
    docs_rows = conn.execute(
        """
        SELECT id, nombre, url, tipo, estado, created_at, updated_at
        FROM inmueble_docs
        WHERE inmueble_id = ?
        ORDER BY created_at DESC
        """,
        (inmueble_id,),
    ).fetchall()
    doc_ids = [str(row["id"] or "").strip() for row in docs_rows if str(row["id"] or "").strip()]
    removed = 0
    if doc_ids:
        placeholders = ",".join(["?"] * len(doc_ids))
        values = ["inmobiliaria", *doc_ids]
        if owner_ids:
            owner_placeholders = ",".join(["?"] * len(owner_ids))
            query = (
                f"DELETE FROM gestoria_docs WHERE LOWER(COALESCE(referencia_tipo, '')) = ? "
                f"AND referencia_id IN ({placeholders}) AND cliente_id NOT IN ({owner_placeholders})"
            )
            values.extend(owner_ids)
        else:
            query = (
                f"DELETE FROM gestoria_docs WHERE LOWER(COALESCE(referencia_tipo, '')) = ? "
                f"AND referencia_id IN ({placeholders})"
            )
        cursor = conn.execute(query, values)
        removed = cursor.rowcount if cursor.rowcount is not None and cursor.rowcount >= 0 else 0
    linked = 0
    if owner_ids:
        ensure_cliente_servicio_link(conn, owner_ids[0], inmueble["empresa_id"], "inmobiliaria", now)
    for cliente_id in owner_ids:
        ensure_cliente_servicio_link(conn, cliente_id, inmueble["empresa_id"], "inmobiliaria", now)
        for row in docs_rows:
            if ensure_inmueble_doc_cliente_link(conn, inmueble, row, cliente_id, now):
                linked += 1
    return {"linked": linked, "removed": removed}


def autolink_inmueble_docs_for_cliente(conn, cliente_id, empresa_id, now):
    if not cliente_id or not empresa_id:
        return {"linked": 0, "removed": 0}
    tables = {
        row["name"]
        for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('inmuebles', 'inmueble_propietarios', 'inmueble_docs', 'gestoria_docs')"
        )
    }
    required = {"inmuebles", "inmueble_propietarios", "inmueble_docs", "gestoria_docs"}
    if not required.issubset(tables):
        return {"linked": 0, "removed": 0}
    inmueble_ids = [
        str(row["inmueble_id"] or "").strip()
        for row in conn.execute(
            """
            SELECT ip.inmueble_id
            FROM inmueble_propietarios ip
            JOIN inmuebles i ON i.id = ip.inmueble_id
            WHERE ip.cliente_id = ? AND i.empresa_id = ?
            """,
            (cliente_id, empresa_id),
        ).fetchall()
        if str(row["inmueble_id"] or "").strip()
    ]
    linked = 0
    removed = 0
    for inmueble_id in inmueble_ids:
        result = sync_inmueble_docs_for_inmueble(conn, inmueble_id, now)
        linked += int(result.get("linked") or 0)
        removed += int(result.get("removed") or 0)
    if inmueble_ids:
        ensure_cliente_servicio_link(conn, cliente_id, empresa_id, "inmobiliaria", now)
    return {"linked": linked, "removed": removed}


def ensure_captacion_for_inmueble(conn, empresa_id, inmueble_id, now):
    if not inmueble_id:
        return None
    captacion = conn.execute(
        """
        SELECT *
        FROM captaciones
        WHERE empresa_id = ? AND inmueble_id = ?
        ORDER BY updated_at DESC, created_at DESC
        LIMIT 1
        """,
        (empresa_id, inmueble_id),
    ).fetchone()
    if captacion:
        return captacion
    inmueble = conn.execute(
        "SELECT * FROM inmuebles WHERE id = ? AND empresa_id = ? LIMIT 1",
        (inmueble_id, empresa_id),
    ).fetchone()
    if not inmueble:
        return None
    captacion_id = os.urandom(16).hex()
    situacion = str(inmueble["estado"] or "Noticia").strip() or "Noticia"
    etapa = "Encargo" if normalize_lookup_text(situacion) == "encargo" else situacion
    conn.execute(
        """
        INSERT INTO captaciones (
          id, empresa_id, inmueble_id, propietario, tipo_inmueble, direccion, codigo_postal, poblacion, provincia,
          zona, m2, anio_construccion, habitaciones, banos, precio_objetivo, precio_valoracion, etapa, situacion_comercial,
          created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            captacion_id,
            empresa_id,
            inmueble_id,
            None,
            inmueble["tipo_inmueble"],
            inmueble["direccion"],
            inmueble["codigo_postal"],
            inmueble["poblacion"],
            inmueble["provincia"],
            inmueble["zona"],
            inmueble["m2"],
            inmueble["anio_construccion"] if "anio_construccion" in inmueble.keys() else None,
            inmueble["habitaciones"],
            inmueble["banos"],
            inmueble["precio_objetivo"],
            inmueble["precio_valoracion"],
            etapa,
            situacion,
            now,
            now,
        ),
    )
    return conn.execute(
        "SELECT * FROM captaciones WHERE id = ? LIMIT 1",
        (captacion_id,),
    ).fetchone()


def sync_inmueble_stage_for_action(conn, inmueble_id, destino, now):
    destino_norm = normalize_lookup_text(destino or "").lower()
    destino_key = (
        destino_norm.replace("/", "_")
        .replace("-", "_")
        .replace(" ", "_")
        .replace("__", "_")
        .strip("_")
    )
    destino_label = {
        "inmueble": "Inmueble",
        "noticia": "Noticia",
        "valoracion": "Valoración",
        "adquisicion": "Adquisición",
        "encargo": "Encargo",
        "propuesta": "Propuesta",
        "reservado": "Reservado",
        "arras": "Contrato de arras",
        "vendido": "Vendido",
        "compraventa": "Vendido",
        "cerrado_negativamente": "Cerrado negativamente",
        "alquiler": "Alquiler",
    }.get(destino_key) or {
        "inmueble": "Inmueble",
        "noticia": "Noticia",
        "valoracion": "Valoración",
        "adquisicion": "Adquisición",
        "encargo": "Encargo",
        "propuesta": "Propuesta",
        "reservado": "Reservado",
        "arras": "Contrato de arras",
        "vendido": "Vendido",
        "compraventa": "Vendido",
        "cerrado negativamente": "Cerrado negativamente",
        "alquiler": "Alquiler",
    }.get(destino_norm)
    if not inmueble_id or not destino_label:
        return
    inmueble = conn.execute(
        "SELECT id, empresa_id FROM inmuebles WHERE id = ? LIMIT 1",
        (inmueble_id,),
    ).fetchone()
    if not inmueble:
        return
    captacion = ensure_captacion_for_inmueble(conn, inmueble["empresa_id"], inmueble_id, now)
    if captacion:
        # Compat: instalaciones legacy pueden no tener `noticia_verificada` en Postgres aún.
        # Intentamos setearlo en Encargo, y si falla (columna ausente), hacemos el update básico.
        if destino_label == "Encargo":
            try:
                conn.execute(
                    """
                    UPDATE captaciones
                    SET etapa = ?, situacion_comercial = ?, noticia_verificada = 1, updated_at = datetime(?)
                    WHERE id = ?
                    """,
                    (destino_label, destino_label, now, captacion["id"]),
                )
            except Exception:
                conn.execute(
                    """
                    UPDATE captaciones
                    SET etapa = ?, situacion_comercial = ?, updated_at = datetime(?)
                    WHERE id = ?
                    """,
                    (destino_label, destino_label, now, captacion["id"]),
                )
        else:
            conn.execute(
                """
                UPDATE captaciones
                SET etapa = ?, situacion_comercial = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (destino_label, destino_label, now, captacion["id"]),
            )
    conn.execute(
        """
        UPDATE inmuebles
        SET estado = ?, updated_at = datetime(?)
        WHERE id = ?
        """,
        (destino_label, now, inmueble_id),
    )
    inmueble = conn.execute(
        "SELECT empresa_id FROM inmuebles WHERE id = ? LIMIT 1",
        (inmueble_id,),
    ).fetchone()
    audit_event(
        conn,
        str(inmueble["empresa_id"] or "").strip() if inmueble else None,
        "inmueble",
        inmueble_id,
        "Cambio de estado",
        detalles={"destino": destino_label, "origen": "workflow"},
        now=now,
    )
    try:
        resp_row = conn.execute(
            """
            SELECT
              COALESCE(
                NULLIF(TRIM(c.asesor), ''),
                NULLIF(TRIM(c.responsable), ''),
                NULLIF(TRIM(i.asesor), ''),
                NULLIF(TRIM(i.responsable), ''),
                ''
              ) AS responsable
            FROM inmuebles i
            LEFT JOIN captaciones c ON c.inmueble_id = i.id
            WHERE i.id = ?
            ORDER BY COALESCE(NULLIF(c.updated_at, ''), c.created_at) DESC
            LIMIT 1
            """,
            (inmueble_id,),
        ).fetchone()
        responsable = str((resp_row["responsable"] if resp_row else "") or "").strip()
    except Exception:
        responsable = ""
    try:
        ensure_inmueble_checklist_defaults_if_empty(conn, inmueble_id, destino_label, now, responsable=responsable)
    except Exception:
        pass
    try:
        ensure_pending_inmueble_stage_actions(conn, str(inmueble["empresa_id"] or "").strip(), inmueble_id, destino_label, now, responsable=responsable)
    except Exception:
        pass


def archive_pending_inmueble_actions(conn, empresa_id, inmueble_id, now, usuario=None, reason=None):
    empresa_id = str(empresa_id or "").strip()
    inmueble_id = str(inmueble_id or "").strip()
    if not empresa_id or not inmueble_id:
        return 0
    servicio = "inmobiliaria"
    motivo = str(reason or "").strip() or "Archivado manual"
    pending = conn.execute(
        """
        SELECT id
        FROM acciones
        WHERE empresa_id = ?
          AND servicio = ?
          AND inmueble_id = ?
          AND LOWER(COALESCE(estado, '')) = 'pendiente'
        """,
        (empresa_id, servicio, inmueble_id),
    ).fetchall()
    if not pending:
        return 0
    conn.execute(
        """
        UPDATE acciones
        SET
          estado = 'Cancelada',
          resultado_cierre = CASE
            WHEN resultado_cierre IS NULL OR TRIM(resultado_cierre) = '' THEN ?
            ELSE resultado_cierre
          END,
          updated_at = datetime(?)
        WHERE empresa_id = ?
          AND servicio = ?
          AND inmueble_id = ?
          AND LOWER(COALESCE(estado, '')) = 'pendiente'
        """,
        (motivo, now, empresa_id, servicio, inmueble_id),
    )
    audit_event(
        conn,
        empresa_id,
        "inmueble",
        inmueble_id,
        "Archivar acciones pendientes",
        usuario=usuario,
        detalles={"archived": len(pending), "motivo": motivo},
        now=now,
    )
    return len(pending)


def retire_inmueble_from_portal(conn, empresa_id, inmueble_id, now, usuario=None, reason=None):
    empresa_id = str(empresa_id or "").strip()
    inmueble_id = str(inmueble_id or "").strip()
    if not inmueble_id:
        return False
    try:
        ensure_column(conn, "inmuebles", "portal_publicado", "portal_publicado INTEGER NOT NULL DEFAULT 0")
        ensure_column(conn, "inmuebles", "portal_retirado_at", "portal_retirado_at TEXT")
    except Exception:
        pass
    row = conn.execute(
        "SELECT id, empresa_id, portal_publicado FROM inmuebles WHERE id = ? LIMIT 1",
        (inmueble_id,),
    ).fetchone()
    if not row:
        return False
    if not empresa_id:
        empresa_id = str(row["empresa_id"] or "").strip()
    if int(row["portal_publicado"] or 0) != 1:
        return False
    conn.execute(
        """
        UPDATE inmuebles
        SET portal_publicado = 0,
            portal_retirado_at = ?,
            updated_at = datetime(?)
        WHERE id = ?
        """,
        (now, now, inmueble_id),
    )
    audit_event(
        conn,
        empresa_id or None,
        "inmueble",
        inmueble_id,
        "Retirar del portal",
        usuario=usuario,
        detalles={"motivo": str(reason or "").strip() or "Cierre de encargo"},
        now=now,
    )
    return True


def ensure_inmueble_cierres_schema(conn):
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS inmueble_cierres (
              id TEXT PRIMARY KEY,
              empresa_id TEXT NOT NULL,
              inmueble_id TEXT NOT NULL,
              tipo TEXT NOT NULL,
              fecha_cierre TEXT,
              importe_final REAL,
              honorarios REAL,
              numero_citas INTEGER,
              motivo_cierre TEXT,
              nuevo_propietario_id TEXT,
              nuevo_propietario_nombre TEXT,
              nuevo_propietario_nif TEXT,
              nuevo_propietario_telefono TEXT,
              nuevo_propietario_email TEXT,
              operacion_id TEXT,
              notas TEXT,
              usuario TEXT,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL
            )
            """
        )
    except Exception:
        pass
    for col_name, col_sql in {
        "honorarios": "honorarios REAL",
        "motivo_cierre": "motivo_cierre TEXT",
        "nuevo_propietario_id": "nuevo_propietario_id TEXT",
        "nuevo_propietario_nombre": "nuevo_propietario_nombre TEXT",
        "nuevo_propietario_nif": "nuevo_propietario_nif TEXT",
        "nuevo_propietario_telefono": "nuevo_propietario_telefono TEXT",
        "nuevo_propietario_email": "nuevo_propietario_email TEXT",
        "operacion_id": "operacion_id TEXT",
    }.items():
        try:
            ensure_column(conn, "inmueble_cierres", col_name, col_sql)
        except Exception:
            pass
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_inmueble_cierres_inmueble ON inmueble_cierres (inmueble_id, created_at)")
    except Exception:
        pass


def create_operacion_for_inmueble_cierre(conn, empresa_id, inmueble_id, tipo_label, now, *, fecha_cierre=None, importe_final=None, honorarios=None, numero_citas=None, nuevo_propietario_id=None, nuevo_propietario=None, notas=None):
    if tipo_label not in {"Vendido", "Alquiler"}:
        return None
    inmueble = conn.execute("SELECT * FROM inmuebles WHERE id = ? LIMIT 1", (inmueble_id,)).fetchone()
    if not inmueble:
        return None
    captacion = conn.execute(
        """
        SELECT *
        FROM captaciones
        WHERE inmueble_id = ? AND empresa_id = ?
        ORDER BY COALESCE(NULLIF(updated_at, ''), created_at) DESC
        LIMIT 1
        """,
        (inmueble_id, empresa_id),
    ).fetchone()
    propietarios = get_inmueble_propietarios(conn, inmueble_id)
    prop1 = propietarios[0] if propietarios else {}
    prop2 = propietarios[1] if len(propietarios) > 1 else {}
    fecha = str(fecha_cierre or "").strip() or now
    parsed_fecha = parse_iso_date(fecha)
    anio = parsed_fecha.year if parsed_fecha else None
    mes = iso_month_label(fecha)
    precio_encargo = parse_money_value(row_value(captacion, "precio_objetivo", None))
    if not precio_encargo:
        precio_encargo = parse_money_value(row_value(inmueble, "precio_objetivo", None))
    importe_num = float(importe_final or 0) if importe_final is not None else None
    honorarios_num = float(honorarios or 0) if honorarios is not None else None
    fecha_encargo = str(row_value(captacion, "fecha", "") or row_value(captacion, "fecha_encargo", "") or "").strip() or None
    dias_hasta_venta = None
    if fecha_encargo:
        start = parse_iso_date(fecha_encargo)
        end = parse_iso_date(fecha)
        if start and end:
            try:
                dias_hasta_venta = max((end - start).days, 0)
            except Exception:
                dias_hasta_venta = None
    direccion = (
        str(row_value(inmueble, "direccion", "") or "").strip()
        or str(row_value(captacion, "direccion", "") or "").strip()
        or str(row_value(inmueble, "referencia", "") or "").strip()
    )
    responsable = (
        str(row_value(captacion, "asesor", "") or "").strip()
        or str(row_value(captacion, "responsable", "") or "").strip()
        or str(row_value(inmueble, "asesor", "") or "").strip()
        or str(row_value(inmueble, "responsable", "") or "").strip()
    )
    oficina = str(row_value(captacion, "oficina", "") or row_value(inmueble, "oficina", "") or "").strip()
    nuevo_propietario = nuevo_propietario or {}
    op_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO operaciones_inmobiliarias (
          id, empresa_id, tipo_operacion, estado, origen, origen_inmueble, anio, mes,
          inmueble_id, direccion, referencia_catastral,
          propietario1_id, propietario1_nombre, propietario1_nif, propietario1_telefono, propietario1_email,
          propietario2_id, propietario2_nombre, propietario2_nif, propietario2_telefono, propietario2_email,
          contraparte1_id, contraparte_nombre, contraparte_nif, contraparte_telefono, contraparte_email,
          fecha_encargo, fecha_escritura, fecha_operacion, precio_encargo, precio_escritura, precio_renta,
          dias_hasta_venta, num_visitas, honorarios, agente, responsable_gestion, oficina,
          estado_documental, notas, datos_extraidos_json, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            op_id,
            empresa_id,
            "alquiler" if tipo_label == "Alquiler" else "venta",
            "Cerrada",
            "cierre_encargo",
            "CRM inmobiliario",
            anio,
            mes,
            inmueble_id,
            direccion or None,
            str(row_value(inmueble, "referencia_catastral", "") or "").strip() or None,
            prop1.get("id"),
            prop1.get("nombre"),
            prop1.get("nif"),
            prop1.get("telefono"),
            prop1.get("email"),
            prop2.get("id"),
            prop2.get("nombre"),
            prop2.get("nif"),
            prop2.get("telefono"),
            prop2.get("email"),
            nuevo_propietario_id,
            str(nuevo_propietario.get("nombre") or "").strip() or None,
            str(nuevo_propietario.get("nif") or "").strip() or None,
            str(nuevo_propietario.get("telefono") or "").strip() or None,
            str(nuevo_propietario.get("email") or "").strip() or None,
            fecha_encargo,
            fecha if tipo_label == "Vendido" else None,
            fecha,
            precio_encargo or None,
            importe_num if tipo_label == "Vendido" else None,
            importe_num if tipo_label == "Alquiler" else None,
            dias_hasta_venta,
            int(numero_citas) if numero_citas is not None else None,
            honorarios_num,
            responsable or None,
            responsable or None,
            oficina or None,
            "Pendiente de cierre documental",
            str(notas or "").strip() or None,
            json.dumps({"cierre_tipo": tipo_label, "fuente": "inmueble_encargo_close"}, ensure_ascii=False),
            now,
            now,
        ),
    )
    if tipo_label == "Alquiler":
        try:
            conn.execute(
                """
                INSERT INTO alquileres (
                  id, empresa_id, fecha, direccion, propietario, telefono, precio, comision,
                  importe_comision, total, inquilino, telefono2, agente, numero_alquileres, tipo, oficina,
                  created_at, updated_at
                ) VALUES (
                  ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    empresa_id,
                    fecha,
                    direccion or None,
                    prop1.get("nombre"),
                    prop1.get("telefono"),
                    importe_num,
                    str(honorarios_num or "") if honorarios_num is not None else None,
                    honorarios_num,
                    honorarios_num,
                    str(nuevo_propietario.get("nombre") or "").strip() or None,
                    str(nuevo_propietario.get("telefono") or "").strip() or None,
                    responsable or None,
                    1,
                    "Cierre encargo",
                    oficina or None,
                    now,
                    now,
                ),
            )
        except Exception:
            pass
    return op_id


def close_inmueble_encargo_positive(conn, empresa_id, inmueble_id, now, usuario=None, fecha_cierre=None, importe_final=None, numero_citas=None, tipo=None, notas=None, archive_pending=True, honorarios=None, motivo_cierre=None, nuevo_propietario=None):
    empresa_id = str(empresa_id or "").strip()
    inmueble_id = str(inmueble_id or "").strip()
    if not empresa_id or not inmueble_id:
        return {"ok": False, "error": "empresa_id e inmueble_id requeridos"}
    tipo_norm = normalize_lookup_text(tipo or "").lower()
    tipo_key = (
        tipo_norm.replace("/", "_")
        .replace("-", "_")
        .replace(" ", "_")
        .replace("__", "_")
        .strip("_")
    )
    tipo_label = {
        "vendido": "Vendido",
        "compraventa": "Vendido",
        "alquiler": "Alquiler",
        "cerrado_negativamente": "Cerrado negativamente",
        "cerrado negativamente": "Cerrado negativamente",
    }.get(tipo_key) or {
        "vendido": "Vendido",
        "alquiler": "Alquiler",
        "cerrado negativamente": "Cerrado negativamente",
    }.get(tipo_norm) or str(tipo or "").strip()
    if tipo_label not in {"Vendido", "Alquiler", "Cerrado negativamente"}:
        # fallback razonable por tipo_operacion
        row = conn.execute("SELECT tipo_operacion FROM inmuebles WHERE id = ? LIMIT 1", (inmueble_id,)).fetchone()
        op = normalize_lookup_text((row["tipo_operacion"] if row else "") or "")
        tipo_label = "Alquiler" if op == "alquiler" else "Vendido"
    ensure_inmueble_cierres_schema(conn)
    nuevo_propietario = nuevo_propietario or {}
    nuevo_propietario_id = None
    if tipo_label in {"Vendido", "Alquiler"}:
        nuevo_propietario_id = ensure_cliente_for_inmobiliaria(
            conn,
            empresa_id,
            nuevo_propietario.get("nombre"),
            nuevo_propietario.get("nif"),
            now,
            {
                "telefono": nuevo_propietario.get("telefono"),
                "email": nuevo_propietario.get("email"),
            },
        )
    operacion_id = create_operacion_for_inmueble_cierre(
        conn,
        empresa_id,
        inmueble_id,
        tipo_label,
        now,
        fecha_cierre=fecha_cierre,
        importe_final=importe_final,
        honorarios=honorarios,
        numero_citas=numero_citas,
        nuevo_propietario_id=nuevo_propietario_id,
        nuevo_propietario=nuevo_propietario,
        notas=notas,
    )
    cierre_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO inmueble_cierres (
          id, empresa_id, inmueble_id, tipo, fecha_cierre, importe_final, honorarios, numero_citas,
          motivo_cierre, nuevo_propietario_id, nuevo_propietario_nombre, nuevo_propietario_nif,
          nuevo_propietario_telefono, nuevo_propietario_email, operacion_id, notas, usuario, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            cierre_id,
            empresa_id,
            inmueble_id,
            tipo_label,
            str(fecha_cierre or "").strip() or None,
            float(importe_final) if importe_final is not None else None,
            float(honorarios) if honorarios is not None else None,
            int(numero_citas) if numero_citas is not None else None,
            str(motivo_cierre or "").strip() or None,
            nuevo_propietario_id,
            str(nuevo_propietario.get("nombre") or "").strip() or None,
            str(nuevo_propietario.get("nif") or "").strip() or None,
            str(nuevo_propietario.get("telefono") or "").strip() or None,
            str(nuevo_propietario.get("email") or "").strip() or None,
            operacion_id,
            str(notas or "").strip() or None,
            str(usuario or "").strip() or None,
            now,
            now,
        ),
    )
    if nuevo_propietario_id and tipo_label == "Vendido":
        conn.execute("DELETE FROM inmueble_propietarios WHERE inmueble_id = ?", (inmueble_id,))
        ensure_inmueble_propietario_link(conn, inmueble_id, nuevo_propietario_id, now)
    portal_retired = retire_inmueble_from_portal(
        conn,
        empresa_id,
        inmueble_id,
        now,
        usuario=usuario,
        reason=f"Cierre {tipo_label}",
    )
    final_stage = "Noticia" if tipo_label == "Alquiler" else "Inmueble"
    # Registra el cierre y deja la ficha en la fase operativa correspondiente, conservando el histórico.
    sync_inmueble_stage_for_action(conn, inmueble_id, tipo_label, now)
    sync_inmueble_stage_for_action(conn, inmueble_id, final_stage, now)
    archived = 0
    if archive_pending:
        try:
            archived = archive_pending_inmueble_actions(conn, empresa_id, inmueble_id, now, usuario=usuario, reason=f"Cierre {tipo_label}")
        except Exception:
            archived = 0
    audit_event(
        conn,
        empresa_id,
        "inmueble",
        inmueble_id,
        "Cierre de encargo",
        usuario=usuario,
        detalles={
            "tipo": tipo_label,
            "fecha_cierre": str(fecha_cierre or "").strip() or "",
            "importe_final": float(importe_final) if importe_final is not None else None,
            "numero_citas": int(numero_citas) if numero_citas is not None else None,
            "honorarios": float(honorarios) if honorarios is not None else None,
            "motivo_cierre": str(motivo_cierre or "").strip() or "",
            "nuevo_propietario_id": nuevo_propietario_id,
            "operacion_id": operacion_id,
            "archived": archived,
            "portal_retired": portal_retired,
            "estado_final": final_stage,
        },
        now=now,
    )
    return {
        "ok": True,
        "tipo": tipo_label,
        "archived": archived,
        "portal_retired": portal_retired,
        "cierre_id": cierre_id,
        "operacion_id": operacion_id,
        "nuevo_propietario_id": nuevo_propietario_id,
        "estado_final": final_stage,
    }


