def upsert_inmueble_generated_doc(conn, inmueble_id, tipo, nombre, url, now):
    if not inmueble_id or not tipo or not url:
        return None
    existing = conn.execute(
        """
        SELECT id
        FROM inmueble_docs
        WHERE inmueble_id = ? AND tipo = ? AND url = ?
        LIMIT 1
        """,
        (inmueble_id, tipo, url),
    ).fetchone()
    if existing:
        conn.execute(
            """
            UPDATE inmueble_docs
            SET nombre = ?, updated_at = datetime(?)
            WHERE id = ?
            """,
            (nombre or tipo, now, existing["id"]),
        )
        sync_inmueble_docs_for_inmueble(conn, inmueble_id, now)
        return existing["id"]
    doc_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO inmueble_docs (
          id, inmueble_id, nombre, url, tipo, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (doc_id, inmueble_id, nombre or tipo, url, tipo, now, now),
    )
    sync_inmueble_docs_for_inmueble(conn, inmueble_id, now)
    return doc_id


def persist_generated_inmueble_pdf(
    conn,
    inmueble_id,
    tipo,
    nombre,
    pdf_bytes,
    filename_base,
    now,
    replace_existing=False,
    empresa_id=None,
    usuario=None,
    plantilla_clave=None,
    origen_tipo=None,
    origen_id=None,
    payload_json=None,
):
    if not inmueble_id or not tipo or not pdf_bytes:
        return None
    folder = UPLOADS / "inmuebles" / "generated"
    folder.mkdir(parents=True, exist_ok=True)
    safe_base = slugify_text(filename_base or nombre or tipo)[:80] or "documento_inmueble"
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S")
    existing = conn.execute(
        """
        SELECT id, version, url
        FROM inmueble_docs
        WHERE inmueble_id = ? AND tipo = ? AND url LIKE '/uploads/inmuebles/generated/%'
        ORDER BY version DESC, updated_at DESC, created_at DESC
        LIMIT 1
        """,
        (inmueble_id, tipo),
    ).fetchone()
    next_version = int(existing["version"] or 1) + 1 if existing else 1
    doc_id = os.urandom(16).hex()
    filename = f"{safe_base}_{timestamp}_{doc_id[:8]}.pdf"
    file_path = folder / filename
    file_path.write_bytes(pdf_bytes)
    url = f"/uploads/inmuebles/generated/{filename}"
    if replace_existing and existing:
        conn.execute(
            """
            UPDATE inmueble_docs
            SET estado = 'Reemplazado', updated_at = datetime(?)
            WHERE id = ?
            """,
            (now, existing["id"]),
        )
    payload_text = payload_json
    if isinstance(payload_json, (dict, list)):
        payload_text = json.dumps(payload_json, ensure_ascii=False)
    conn.execute(
        """
        INSERT INTO inmueble_docs (
          id, inmueble_id, nombre, url, tipo, estado, version, plantilla_clave, origen_tipo, origen_id,
          payload_json, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, 'Vigente', ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            doc_id,
            inmueble_id,
            nombre or tipo,
            url,
            tipo,
            next_version,
            plantilla_clave or slugify_text(tipo) or None,
            origen_tipo,
            origen_id,
            payload_text,
            now,
            now,
        ),
    )
    try:
        audit_event(
            conn,
            empresa_id,
            "inmueble_docs",
            doc_id,
            "Generar documento",
            usuario=usuario,
            detalles={
                "inmueble_id": inmueble_id,
                "tipo": tipo,
                "version": next_version,
                "estado": "Vigente",
                "plantilla_clave": plantilla_clave or slugify_text(tipo),
                "origen_tipo": origen_tipo,
                "origen_id": origen_id,
                "replace_existing": bool(replace_existing),
            },
            now=now,
        )
    except Exception:
        pass
    try:
        sync_inmueble_docs_for_inmueble(conn, inmueble_id, now)
    except Exception:
        pass
    return {"id": doc_id, "url": url, "path": str(file_path), "version": next_version, "estado": "Vigente"}


def ensure_inmueble_signature_schema(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS inmueble_signature_requests (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          inmueble_id TEXT,
          doc_id TEXT,
          doc_url TEXT,
          doc_nombre TEXT,
          signer_nombre TEXT,
          signer_nif TEXT,
          signer_email TEXT,
          signer_telefono TEXT,
          purpose TEXT,
          status TEXT NOT NULL DEFAULT 'pending',
          token_hash TEXT NOT NULL,
          otp_hash TEXT,
          otp_required INTEGER NOT NULL DEFAULT 0,
          expires_at TEXT,
          sent_at TEXT,
          opened_at TEXT,
          signed_at TEXT,
          rejected_at TEXT,
          signed_name TEXT,
          signed_nif TEXT,
          acceptance_text TEXT,
          signature_data_url TEXT,
          evidence_json TEXT,
          document_sha256 TEXT,
          signed_doc_id TEXT,
          signed_doc_url TEXT,
          created_by TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS inmueble_signature_events (
          id TEXT PRIMARY KEY,
          request_id TEXT NOT NULL,
          event TEXT NOT NULL,
          ip TEXT,
          user_agent TEXT,
          details_json TEXT,
          created_at TEXT NOT NULL
        )
        """
    )
    try:
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_inmueble_signature_token ON inmueble_signature_requests (token_hash)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_inmueble_signature_inmueble ON inmueble_signature_requests (inmueble_id, created_at)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_inmueble_signature_events_req ON inmueble_signature_events (request_id, created_at)")
    except Exception:
        pass


