def _signature_request_row_by_token(conn, token):
    ensure_inmueble_signature_schema(conn)
    token_hash = hash_signature_token(token)
    return conn.execute(
        "SELECT * FROM inmueble_signature_requests WHERE token_hash = ? LIMIT 1",
        (token_hash,),
    ).fetchone()


def _signature_url_to_local_path(url):
    raw = str(url or "").strip()
    if not raw.startswith("/uploads/"):
        return None
    candidate = (UPLOADS.parent / raw.lstrip("/")).resolve()
    try:
        uploads_root = UPLOADS.resolve()
        if uploads_root in candidate.parents or candidate == uploads_root:
            return candidate
    except Exception:
        return None
    return None


def compute_signature_document_sha256(url):
    path = _signature_url_to_local_path(url)
    if not path or not path.exists() or not path.is_file():
        return ""
    h = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def record_signature_event(conn, request_id, event, handler=None, details=None, now=None):
    if not request_id or not event:
        return
    now_value = now or datetime.now(timezone.utc).isoformat()
    ip = ""
    ua = ""
    if handler is not None:
        try:
            ip = _get_client_ip(handler)
        except Exception:
            ip = ""
        try:
            ua = str(handler.headers.get("User-Agent") or "")[:500]
        except Exception:
            ua = ""
    details_text = ""
    if details:
        try:
            details_text = json.dumps(details, ensure_ascii=False)
        except Exception:
            details_text = str(details)
    conn.execute(
        """
        INSERT INTO inmueble_signature_events (id, request_id, event, ip, user_agent, details_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?, datetime(?))
        """,
        (os.urandom(16).hex(), request_id, event, ip, ua, details_text, now_value),
    )


signature_request_public_payload = runtime_public_links.signature_request_public_payload


def create_inmueble_signature_request(
    conn,
    *,
    empresa_id,
    inmueble_id,
    doc_id="",
    doc_url="",
    doc_nombre="",
    signer_nombre="",
    signer_nif="",
    signer_email="",
    signer_telefono="",
    purpose="",
    otp_required=False,
    expires_days=15,
    created_by="",
    now=None,
):
    ensure_inmueble_signature_schema(conn)
    now_value = now or datetime.now(timezone.utc).isoformat()
    doc_row = None
    if doc_id:
        doc_row = conn.execute(
            """
            SELECT d.id, d.inmueble_id, d.nombre, d.url, i.empresa_id
            FROM inmueble_docs d
            JOIN inmuebles i ON i.id = d.inmueble_id
            WHERE d.id = ?
            LIMIT 1
            """,
            (doc_id,),
        ).fetchone()
        if not doc_row:
            raise ValueError("Documento no encontrado")
        empresa_id = str(doc_row["empresa_id"] or empresa_id or "").strip()
        inmueble_id = str(doc_row["inmueble_id"] or inmueble_id or "").strip()
        doc_url = str(doc_row["url"] or doc_url or "").strip()
        doc_nombre = str(doc_row["nombre"] or doc_nombre or "").strip()
    if not empresa_id or not inmueble_id:
        raise ValueError("empresa_id e inmueble_id requeridos")
    if not doc_url and not doc_id:
        raise ValueError("Documento requerido")
    try:
        days = max(1, min(90, int(expires_days or 15)))
    except Exception:
        days = 15
    expires_at = (datetime.now(timezone.utc) + timedelta(days=days)).isoformat()
    token = make_signature_token()
    otp = f"{secrets.randbelow(1000000):06d}" if otp_required else ""
    request_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO inmueble_signature_requests (
          id, empresa_id, inmueble_id, doc_id, doc_url, doc_nombre,
          signer_nombre, signer_nif, signer_email, signer_telefono, purpose,
          status, token_hash, otp_hash, otp_required, expires_at, sent_at,
          document_sha256, created_by, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?, ?, datetime(?), ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            request_id,
            empresa_id,
            inmueble_id,
            doc_id or None,
            doc_url or "",
            doc_nombre or "Documento",
            signer_nombre or "",
            signer_nif or "",
            signer_email or "",
            signer_telefono or "",
            purpose or "Firma electrónica interna",
            hash_signature_token(token),
            hash_signature_token(otp) if otp else "",
            1 if otp_required else 0,
            expires_at,
            now_value,
            compute_signature_document_sha256(doc_url),
            created_by or "",
            now_value,
            now_value,
        ),
    )
    record_signature_event(conn, request_id, "created", details={"otp_required": bool(otp_required)}, now=now_value)
    return {
        "id": request_id,
        "token": token,
        "public_url": build_public_fragment_url("firma_inmo", token),
        "otp": otp,
        "expires_at": expires_at,
    }


def send_inmueble_signature_email(conn, request_row, *, token, otp="", base_url="", reminder=False, now=None):
    row = dict(request_row) if request_row else {}
    email = normalize_email(row.get("signer_email") or "")
    if not email:
        return {"sent": False, "reason": "sin_email"}
    if not (os.environ.get("SMTP_HOST") or "").strip():
        record_signature_event(
            conn,
            row.get("id"),
            "email_skipped",
            details={"reason": "smtp_no_configurado", "email": _mask_email(email)},
            now=now,
        )
        return {"sent": False, "reason": "smtp_no_configurado"}
    base = resolve_public_link_base_url(base_url)
    full_url = build_public_fragment_url("firma_inmo", token, base_url=base)
    subject = "Recordatorio de firma electrónica" if reminder else "Solicitud de firma electrónica"
    doc_name = str(row.get("doc_nombre") or "documento").strip()
    signer = str(row.get("signer_nombre") or "").strip()
    otp_line = f"\nCódigo OTP: {otp}\n" if otp else ""
    text_body = (
        f"Hola {signer or ''},\n\n"
        f"Tienes pendiente la firma electrónica del documento: {doc_name}.\n\n"
        f"Accede desde este enlace:\n{full_url}\n"
        f"{otp_line}\n"
        "Si no esperabas esta solicitud, contacta con la oficina.\n"
    )
    html_body = (
        f"<p>Hola {html.escape(signer or '')},</p>"
        f"<p>Tienes pendiente la firma electrónica del documento: <strong>{html.escape(doc_name)}</strong>.</p>"
        f"<p><a href=\"{html.escape(full_url)}\">Abrir solicitud de firma</a></p>"
        f"{f'<p><strong>Código OTP:</strong> {html.escape(str(otp))}</p>' if otp else ''}"
        "<p>Si no esperabas esta solicitud, contacta con la oficina.</p>"
    )
    try:
        send_mail_smtp(subject, email, text_body, html_body=html_body)
        event = "email_reminder_sent" if reminder else "email_sent"
        record_signature_event(conn, row.get("id"), event, details={"email": _mask_email(email)}, now=now)
        return {"sent": True, "email": _mask_email(email), "url": full_url}
    except Exception as exc:
        record_signature_event(
            conn,
            row.get("id"),
            "email_failed",
            details={"email": _mask_email(email), "error": str(exc)[:300]},
            now=now,
        )
        return {"sent": False, "reason": str(exc)}


def _mask_phone(value):
    digits = re.sub(r"\D+", "", str(value or ""))
    if len(digits) <= 4:
        return "*" * len(digits)
    return "*" * max(0, len(digits) - 4) + digits[-4:]


def send_signature_webhook_message(conn, request_row, *, token, otp="", base_url="", channel="sms", reminder=False, now=None):
    row = dict(request_row) if request_row else {}
    phone = str(row.get("signer_telefono") or "").strip()
    if not phone:
        return {"sent": False, "reason": "sin_telefono", "channel": channel}
    channel_key = "SIGNATURE_WHATSAPP_WEBHOOK_URL" if channel == "whatsapp" else "SIGNATURE_SMS_WEBHOOK_URL"
    url = str(os.environ.get(channel_key) or "").strip()
    if not url:
        record_signature_event(
            conn,
            row.get("id"),
            f"{channel}_skipped",
            details={"reason": "webhook_no_configurado", "phone": _mask_phone(phone)},
            now=now,
        )
        return {"sent": False, "reason": "webhook_no_configurado", "channel": channel}
    base = resolve_public_link_base_url(base_url)
    full_url = build_public_fragment_url("firma_inmo", token, base_url=base)
    message = f"Firma pendiente: {row.get('doc_nombre') or 'documento'}. Enlace: {full_url}"
    if otp:
        message += f" OTP: {otp}"
    payload = {
        "to": phone,
        "channel": channel,
        "message": message,
        "url": full_url,
        "otp": otp or "",
        "request_id": row.get("id") or "",
        "reminder": bool(reminder),
    }
    headers = {"Content-Type": "application/json", "User-Agent": "Verifika2Signature/1.0"}
    secret = str(os.environ.get("SIGNATURE_WEBHOOK_SECRET") or "").strip()
    if secret:
        headers["Authorization"] = f"Bearer {secret}"
    try:
        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=15) as resp:
            status = getattr(resp, "status", 200)
            if status >= 400:
                raise RuntimeError(f"HTTP {status}")
        record_signature_event(
            conn,
            row.get("id"),
            f"{channel}_sent",
            details={"phone": _mask_phone(phone), "reminder": bool(reminder)},
            now=now,
        )
        return {"sent": True, "phone": _mask_phone(phone), "channel": channel, "url": full_url}
    except Exception as exc:
        record_signature_event(
            conn,
            row.get("id"),
            f"{channel}_failed",
            details={"phone": _mask_phone(phone), "error": str(exc)[:300]},
            now=now,
        )
        return {"sent": False, "reason": str(exc), "channel": channel}


