def fin_sync_stage(conn, asesoramiento_id, stage, now):
    if not asesoramiento_id or not stage:
        return
    conn.execute(
        "UPDATE asesoramientos_financiacion SET estado = ?, updated_at = datetime(?) WHERE id = ?",
        (stage, now, asesoramiento_id),
    )


def ensure_fin_followup_action(
    conn,
    empresa_id,
    asesoramiento_id,
    cliente_id,
    cliente_nombre,
    responsable,
    action_type,
    notas,
    now,
):
    if not empresa_id or not asesoramiento_id or not action_type:
        return None
    exists = conn.execute(
        """
        SELECT id
        FROM acciones
        WHERE servicio = 'financiaciones'
          AND asesoramiento_id = ?
          AND tipo = ?
          AND LOWER(COALESCE(estado, '')) = 'pendiente'
        LIMIT 1
        """,
        (asesoramiento_id, action_type),
    ).fetchone()
    if exists:
        return exists["id"]
    next_id = os.urandom(16).hex()
    next_date = datetime.now().strftime("%Y-%m-%d")
    conn.execute(
        """
        INSERT INTO acciones (
          id, empresa_id, servicio, cliente_id, inmueble_id, asesoramiento_id, cliente_nombre,
          fecha, hora, tipo, responsable, estado, notas, created_at, updated_at
        ) VALUES (
          ?, ?, 'financiaciones', ?, NULL, ?, ?, ?, '10:00', ?, ?, 'Pendiente', ?, datetime(?), datetime(?)
        )
        """,
        (
            next_id,
            empresa_id,
            cliente_id,
            asesoramiento_id,
            cliente_nombre or "",
            next_date,
            action_type,
            responsable or "",
            notas or "",
            now,
            now,
        ),
    )
    audit_event(
        conn,
        empresa_id,
        "accion",
        next_id,
        "Crear acción de seguimiento",
        detalles={"servicio": "financiaciones", "tipo": action_type, "asesoramiento_id": asesoramiento_id},
        now=now,
    )
    return next_id


def convert_fin_asesoramiento_to_hipoteca(conn, empresa_id, row, now):
    if not row:
        return None
    precio_inmueble = None
    inmueble_id = ""
    try:
        inmueble_id = str(row["inmueble_id"] or "").strip()
    except Exception:
        inmueble_id = str(getattr(row, "get", lambda *_: None)("inmueble_id") or "").strip()
    if inmueble_id:
        inm = None
        try:
            inm = conn.execute(
                """
                SELECT precio_objetivo, precio_encargo, precio_pedido_cliente, precio_valoracion
                FROM inmuebles
                WHERE id = ?
                LIMIT 1
                """,
                (inmueble_id,),
            ).fetchone()
        except Exception:
            inm = None
        if inm:
            for key in ("precio_objetivo", "precio_encargo", "precio_pedido_cliente", "precio_valoracion"):
                try:
                    val = inm[key]
                except Exception:
                    val = None
                if val not in (None, "", 0, 0.0):
                    precio_inmueble = val
                    break

    # Backfill desde OCR (notas_ocr): ayuda cuando el asesoramiento se crea desde docs tipo
    # "Liquidación comprador" / "Contrato de intermediación" y faltan campos clave.
    ocr_text = ""
    try:
        ocr_text = str(row["notas_ocr"] or "")
    except Exception:
        ocr_text = ""
    ocr_clean = re.sub(r"\s+", " ", (ocr_text or "").replace("\u00a0", " ")).strip()
    ocr_fields = {}

    def _pick_float(patterns):
        for pat in patterns:
            m = re.search(pat, ocr_clean, re.IGNORECASE)
            if not m:
                continue
            val = parse_optional_float(m.group(1))
            if val is None:
                continue
            try:
                val = float(val)
            except Exception:
                continue
            if val > 0:
                return val
        return None

    ocr_precio = _pick_float(
        [
            r"PRECIO\s+DE\s+COMPRAVENTA.*?(?:ESCRITURADO|ESCRITURAC[IO]N|ESCRIT\w*)\s*[:\-]?\s*([0-9\.,]+)",
            r"PRECIO\s+DE\s+COMPRAVENTA\s*[:\-]?\s*([0-9\.,]+)",
            r"\bESCRITURADO\s*[:\-]?\s*([0-9\.,]+)",
        ]
    )
    ocr_importe = _pick_float(
        [
            r"IMPORTE\s+DEL\s+PRESTAMO\s*[:\-]?\s*(?:MAXIMO\s*)?([0-9\.,]+)",
            r"PRESTAMO\s+CONCEDID[OA]\s*[:\-]?\s*([0-9\.,]+)",
            r"\bCAPITAL\s*[:\-]?\s*([0-9\.,]+)",
        ]
    )
    ocr_tipo_interes = ""
    for pat in (
        r"\bTIPO\s+SALIDA\s*[:\-]?\s*([0-9]{1,2}[\\.,][0-9]{1,3})\s*%?",
        r"\bTIPO\s+BONIFICADO\s*[:\-]?\s*([0-9]{1,2}[\\.,][0-9]{1,3})\s*%?",
        r"\bINTERES\s*[:\-]?\s*([0-9]{1,2}[\\.,][0-9]{1,3})\s*%?",
    ):
        m = re.search(pat, ocr_clean, re.IGNORECASE)
        if m:
            ocr_tipo_interes = f"{m.group(1).strip()}%"
            break

    cliente1_id = row["cliente1_id"]
    if not cliente1_id and ocr_clean:
        ocr_fields = parse_asesoramiento_text(ocr_text)
        cliente1_id = ensure_cliente_for_financiacion(
            conn,
            empresa_id,
            ocr_fields.get("cliente1_nombre"),
            ocr_fields.get("cliente1_dni"),
            now,
            {"telefono": ocr_fields.get("cliente1_telefono"), "email": ocr_fields.get("cliente1_email")},
        )
    if cliente1_id and not str(row["cliente1_id"] or "").strip():
        try:
            conn.execute(
                "UPDATE asesoramientos_financiacion SET cliente1_id = ?, updated_at = datetime(?) WHERE id = ?",
                (cliente1_id, now, row["id"]),
            )
        except Exception:
            pass
    cliente_nombre = str(row["cliente1_nombre"] or "").strip()
    if not cliente_nombre and ocr_fields:
        cliente_nombre = str(ocr_fields.get("cliente1_nombre") or "").strip()
    if row["cliente2_nombre"]:
        cliente_nombre = f"{cliente_nombre} / {row['cliente2_nombre']}".strip(" /")
    fecha = row["fecha"] or ""
    try:
        anio = int(fecha.split("/")[-1]) if "/" in fecha else int(fecha.split("-")[0])
    except Exception:
        anio = None
    existing = find_reusable_hipoteca_open_record(
        conn,
        empresa_id,
        cliente=cliente_nombre,
        cliente_id=cliente1_id,
        fecha_encargo=fecha,
        precio=precio_inmueble if precio_inmueble not in (None, "", 0, 0.0) else ocr_precio,
        importe_hipoteca=ocr_importe,
    )
    if existing:
        conn.execute(
            "UPDATE asesoramientos_financiacion SET estado = ?, updated_at = datetime(?) WHERE id = ?",
            ("Convertido", now, row["id"]),
        )
        return existing["id"]
    hipoteca_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO hipotecas (
          id, empresa_id, cliente, cliente_id, banco, precio, importe_hipoteca, porcentaje,
          entrada, comision, oficina, fecha_encargo, encargo, tipo_hipoteca,
          fecha_firma, cesion, comision_juan, comision_modernia, inmobiliaria_compra,
          asesor, estado, anio, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            hipoteca_id,
            empresa_id,
            cliente_nombre,
            cliente1_id,
            None,
            precio_inmueble if precio_inmueble not in (None, "", 0, 0.0) else ocr_precio,
            ocr_importe,
            None,
            None,
            None,
            None,
            fecha,
            None,
            ocr_tipo_interes or None,
            None,
            None,
            None,
            None,
            row["inmobiliaria_asesor"],
            row["asesor"],
            "Pendiente",
            anio,
            now,
            now,
        ),
    )
    conn.execute(
        "UPDATE asesoramientos_financiacion SET estado = ?, updated_at = datetime(?) WHERE id = ?",
        ("Convertido", now, row["id"]),
    )
    audit_event(
        conn,
        empresa_id,
        "hipoteca",
        hipoteca_id,
        "Convertir asesoramiento en hipoteca",
        detalles={"asesoramiento_id": row["id"], "cliente_id": row["cliente1_id"]},
        now=now,
    )
    return hipoteca_id


def apply_fin_action_workflow(conn, empresa_id, action_row, now):
    if not action_row:
        return None
    asesoramiento_id = str(action_row["asesoramiento_id"] or "").strip()
    if not asesoramiento_id:
        return None
    current = conn.execute(
        "SELECT * FROM asesoramientos_financiacion WHERE id = ? LIMIT 1",
        (asesoramiento_id,),
    ).fetchone()
    if not current:
        return None
    tipo = normalize_fin_action_type(action_row["tipo"])
    resultado = str(action_row["resultado_cierre"] or "").strip()
    next_stage = ""
    next_action = ""
    next_note = ""
    if tipo == "primera_llamada":
        if resultado == "Cita concertada":
            next_stage = "Asesoramiento"
            next_action = "Reunión de asesoramiento"
            next_note = "Cita concertada desde la primera llamada."
        elif resultado == "No interesado":
            next_stage = "Descartada"
    elif tipo == "reunion_asesoramiento":
        if resultado == "Realizada":
            next_stage = "Estudio"
            next_action = "Estudio financiero"
            next_note = "Analizar viabilidad y ratios."
        elif resultado == "Pendiente documentación":
            next_stage = "Documentación"
            next_action = "Solicitud documentación"
            next_note = "Completar documentación antes del estudio."
        elif resultado == "No viable":
            next_stage = "Descartada"
    elif tipo == "solicitud_documentacion":
        if resultado == "Completa":
            next_stage = "Estudio"
            next_action = "Estudio financiero"
            next_note = "Documentación completa para analizar."
        else:
            next_stage = "Documentación"
    elif tipo == "estudio_financiero":
        if resultado == "Viable":
            next_stage = "Bancos"
            next_action = "Presentación bancaria"
            next_note = "Enviar expediente a entidades."
        elif resultado == "Pendiente documentación":
            next_stage = "Documentación"
            next_action = "Solicitud documentación"
            next_note = "Falta documentación para terminar el estudio."
        elif resultado == "No viable":
            next_stage = "Descartada"
    elif tipo == "presentacion_bancaria":
        if resultado == "Presentada":
            next_stage = "Bancos"
            next_action = "Seguimiento bancario"
            next_note = "Hacer seguimiento de entidades."
        elif resultado == "Pendiente completar":
            next_stage = "Documentación"
            next_action = "Solicitud documentación"
            next_note = "Completar expediente antes de enviar."
    elif tipo == "seguimiento_bancario":
        if resultado == "Tasación solicitada":
            next_stage = "Tasación"
            next_action = "Tasación"
            next_note = "Controlar cita, encargo y resultado de tasación."
        elif resultado == "Aprobada":
            next_stage = "FEIN / Acta"
            next_action = "FEIN / Acta"
            next_note = "Revisar FEIN, acta notarial y pre-firma."
        elif resultado == "Denegada":
            next_stage = "Descartada"
    elif tipo == "tasacion_fin":
        if resultado == "Tasación OK":
            next_stage = "FEIN / Acta"
            next_action = "FEIN / Acta"
            next_note = "Avanzar a FEIN y acta."
        elif resultado == "Incidencia":
            next_stage = "Tasación"
    elif tipo == "fein_acta":
        if resultado == "Firmable":
            next_stage = "Firma"
            next_action = "Firma hipoteca"
            next_note = "Preparar firma hipotecaria."
        elif resultado == "Pendiente":
            next_stage = "FEIN / Acta"
    elif tipo == "firma_hipoteca":
        if resultado == "Firmada":
            convert_fin_asesoramiento_to_hipoteca(conn, empresa_id, current, now)
            return "Convertido"
        elif resultado == "Cancelada":
            next_stage = "Descartada"
        elif resultado == "Pospuesta":
            next_stage = "Firma"
    if next_stage:
        fin_sync_stage(conn, asesoramiento_id, next_stage, now)
    if next_action:
        ensure_fin_followup_action(
            conn,
            empresa_id,
            asesoramiento_id,
            current["cliente1_id"],
            current["cliente1_nombre"],
            action_row["responsable"],
            next_action,
            next_note,
            now,
        )
    return next_stage or normalize_fin_stage(current["estado"])


def get_inmueble_propietarios(conn, inmueble_id):
    if not inmueble_id:
        return []
    rows = conn.execute(
        """
        SELECT c.id, c.nombre, c.nif, c.telefono, c.email
        FROM inmueble_propietarios ip
        JOIN clientes c ON c.id = ip.cliente_id
        WHERE ip.inmueble_id = ?
        ORDER BY c.nombre
        """,
        (inmueble_id,),
    ).fetchall()
    return [dict(row) for row in rows]


def create_owner_portal_code(owner_name, owner_contact, listing_ids):
    hub_url = (os.environ.get("LEAD_HUB_URL") or os.environ.get("LEADS_WEBHOOK_URL") or "").strip()
    hub_token = (os.environ.get("LEAD_HUB_TOKEN") or os.environ.get("LEADS_WEBHOOK_TOKEN") or "").strip()
    if not hub_url or not hub_token:
        raise RuntimeError("lead_hub_not_configured")
    try:
        origin = urllib.parse.urlparse(hub_url)
        base = f"{origin.scheme}://{origin.netloc}".rstrip("/")
    except Exception:
        base = ""
    if not base:
        raise RuntimeError("lead_hub_url_invalid")
    clean_listing_ids = [str(item or "").strip() for item in (listing_ids or []) if str(item or "").strip()]
    if not clean_listing_ids:
        raise RuntimeError("missing_listing_ids")
    payload = {
        "name": str(owner_name or "").strip() or None,
        "contact": str(owner_contact or "").strip() or None,
        "listing_ids": clean_listing_ids,
    }
    req = urllib.request.Request(
        f"{base}/v1/owners/create_code",
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {hub_token}",
            "User-Agent": "Verifika2CRM/1.0",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            raw = resp.read().decode("utf-8")
            data = json.loads(raw) if raw else {}
    except urllib.error.HTTPError as exc:
        body = ""
        try:
            body = exc.read().decode("utf-8")
        except Exception:
            body = ""
        raise RuntimeError(f"lead_hub_failed:{getattr(exc, 'code', '')}:{body[:200]}")
    except Exception as exc:
        raise RuntimeError(f"lead_hub_failed:{exc}")
    if not isinstance(data, dict) or not data.get("ok") or not data.get("code"):
        raise RuntimeError(str((data or {}).get("error") if isinstance(data, dict) else "") or "lead_hub_failed")
    return data


def ensure_inmueble_servicios_schema(conn):
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS inmueble_servicios (
              id TEXT PRIMARY KEY,
              inmueble_id TEXT NOT NULL,
              servicio TEXT NOT NULL,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL,
              UNIQUE(inmueble_id, servicio),
              FOREIGN KEY (inmueble_id) REFERENCES inmuebles(id)
            );
            """
        )
    except Exception:
        # Best-effort: if DDL fails we still want the request to return a controlled error.
        return
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_inmueble_servicios_inmueble ON inmueble_servicios(inmueble_id);")
    except Exception:
        pass


def get_inmueble_servicios(conn, inmueble_id):
    if not inmueble_id:
        return []
    ensure_inmueble_servicios_schema(conn)
    try:
        rows = conn.execute(
            """
            SELECT servicio
            FROM inmueble_servicios
            WHERE inmueble_id = ?
            ORDER BY servicio
            """,
            (inmueble_id,),
        ).fetchall()
    except Exception:
        return []
    return [str(row_value(r, "servicio", "") or "").strip() for r in rows if str(row_value(r, "servicio", "") or "").strip()]


def resolve_inmobiliaria_contact_candidate(conn, empresa_id, payload, *, role_prefix="", demanda_id="", inmueble_id=""):
    nombre = normalize_person_name(payload.get(f"{role_prefix}_nombre")) if role_prefix else ""
    nif = normalize_nif(payload.get(f"{role_prefix}_nif")) if role_prefix else ""
    telefono = str(payload.get(f"{role_prefix}_telefono") or "").strip() if role_prefix else ""
    email = normalize_email(payload.get(f"{role_prefix}_email")) if role_prefix else ""
    cliente_id = None
    if role_prefix and (nombre or nif or telefono or email):
        cliente_id = ensure_cliente_for_inmobiliaria(
            conn,
            empresa_id,
            nombre,
            nif,
            datetime.now(timezone.utc).isoformat(),
            {"telefono": telefono, "email": email},
        )
        return {
            "cliente_id": cliente_id,
            "nombre": nombre,
            "nif": nif,
            "telefono": telefono,
            "email": email,
        }

    if demanda_id:
        demanda = conn.execute(
            """
            SELECT d.cliente_id, c.nombre, c.nif, c.telefono, c.email
            FROM demandas d
            LEFT JOIN clientes c ON c.id = d.cliente_id
            WHERE d.id = ? AND d.empresa_id = ?
            LIMIT 1
            """,
            (demanda_id, empresa_id),
        ).fetchone()
        if not demanda:
            demanda = conn.execute(
                """
                SELECT d.cliente_id, c.nombre, c.nif, c.telefono, c.email
                FROM demandas d
                LEFT JOIN clientes c ON c.id = d.cliente_id
                WHERE d.id = ?
                LIMIT 1
                """,
                (demanda_id,),
            ).fetchone()
        if demanda and (demanda["cliente_id"] or demanda["nombre"]):
            return {
                "cliente_id": demanda["cliente_id"],
                "nombre": str(demanda["nombre"] or "").strip(),
                "nif": normalize_nif(demanda["nif"]),
                "telefono": str(demanda["telefono"] or "").strip(),
                "email": normalize_email(demanda["email"]),
            }

    if inmueble_id:
        rows = conn.execute(
            """
            SELECT DISTINCT d.cliente_id, c.nombre, c.nif, c.telefono, c.email
            FROM visitas v
            JOIN demandas d ON d.id = v.demanda_id
            LEFT JOIN clientes c ON c.id = d.cliente_id
            WHERE v.empresa_id = ?
              AND v.inmueble_id = ?
              AND d.cliente_id IS NOT NULL
            ORDER BY v.created_at DESC
            """,
            (empresa_id, inmueble_id),
        ).fetchall()
        if not rows:
            rows = conn.execute(
                """
                SELECT DISTINCT d.cliente_id, c.nombre, c.nif, c.telefono, c.email
                FROM visitas v
                JOIN demandas d ON d.id = v.demanda_id
                LEFT JOIN clientes c ON c.id = d.cliente_id
                WHERE v.inmueble_id = ?
                  AND d.cliente_id IS NOT NULL
                ORDER BY v.created_at DESC
                """,
                (inmueble_id,),
            ).fetchall()
        unique = []
        seen = set()
        for row in rows:
            key = str(row["cliente_id"] or "").strip()
            if not key or key in seen:
                continue
            seen.add(key)
            unique.append(row)
        if len(unique) == 1:
            row = unique[0]
            return {
                "cliente_id": row["cliente_id"],
                "nombre": str(row["nombre"] or "").strip(),
                "nif": normalize_nif(row["nif"]),
                "telefono": str(row["telefono"] or "").strip(),
                "email": normalize_email(row["email"]),
            }
    return {
        "cliente_id": None,
        "nombre": "",
        "nif": "",
        "telefono": "",
        "email": "",
    }


def normalize_inmobiliaria_address(value):
    return re.sub(r"\s+", " ", normalize_lookup_text(value or "")).strip()


