def extract_catastro_public_summary_from_html(html_text, reference=""):
    if not html_text:
        return {}
    clean_ref = clean_catastro_reference(reference)
    # Nota: el HTML público del Catastro cambia con frecuencia (comillas, acentos y etiquetas).
    # Mantenemos regex tolerantes y, si falla, el flujo de sync aún debe generar PDF "parcial".
    parcel_match = re.search(
        r"PARCELA\s+CATASTRAL\s+([A-Z0-9]+).*?"
        r"title=(?:'|\")Tipo\s+de\s+parcela(?:'|\")>(.*?)</span>.*?"
        r"title=(?:'|\")Localizaci(?:ó|o)n(?:'|\")>(.*?)</span>.*?"
        r"title=(?:'|\")Superficie\s+gr[aá]fica(?:'|\")>(.*?)</span>",
        html_text,
        re.I | re.S,
    )
    parcel = {}
    if parcel_match:
        parcel = {
            "referencia_parcela": clean_catastro_reference(parcel_match.group(1)),
            "tipo_parcela": _strip_html_fragment(parcel_match.group(2)),
            "localizacion_parcela": _strip_html_fragment(parcel_match.group(3)),
            "superficie_grafica_m2": _parse_catastro_number(parcel_match.group(4)),
        }
    pattern = re.compile(
        r"CargarBien\((?:'|\")[^'\"]*(?:'|\"),(?:'|\")[^'\"]*(?:'|\"),(?:'|\")[^'\"]*(?:'|\"),(?:'|\")(?P<ref>[A-Z0-9]+)(?:'|\").*?"
        r"title=(?:'|\")Localizaci(?:ó|o)n(?:'|\")>(?P<location>.*?)</span>.*?"
        r"title=(?:'|\")Uso(?:'|\")>(?P<use>.*?)</span>.*?"
        r"title=(?:'|\")Superficie\s+construida(?:'|\")>(?P<surface>.*?)</span>.*?"
        r"title=(?:'|\")Coeficiente\s+de\s+participaci(?:ó|o)n(?:'|\")>(?P<coef>.*?)</span>.*?"
        r"title=(?:'|\")A(?:ñ|n)o\s+construcci(?:ó|o)n(?:'|\")>(?P<year>\d{4})</span>",
        re.I | re.S,
    )
    items = []
    for match in pattern.finditer(html_text):
        ref = clean_catastro_reference(match.group("ref"))
        location = _strip_html_fragment(match.group("location"))
        use_label = _strip_html_fragment(match.group("use"))
        items.append(
            {
                "referencia_catastral": ref,
                "localizacion": location,
                "uso": use_label,
                "superficie_construida_m2": _parse_catastro_number(match.group("surface")),
                "coef_participacion": _strip_html_fragment(match.group("coef")),
                "anio_construccion": int(match.group("year")) if match.group("year") else None,
            }
        )
    if clean_ref:
        exact = next((item for item in items if item["referencia_catastral"] == clean_ref), None)
        if exact:
            return {**parcel, **exact}
    if len(items) == 1:
        return {**parcel, **items[0]}
    return {**parcel, "items": items}


def fetch_catastro_public_summary(reference):
    rc1, rc2, clean_ref = split_catastro_reference(reference)
    if not rc1 or not rc2:
        raise ValueError("referencia catastral incompleta")
    query = {"RC1": rc1, "RC2": rc2}
    source_url = f"{CATRASTRO_PUBLIC_LIST_URL}?{urllib.parse.urlencode(query)}"
    with urllib.request.urlopen(source_url, timeout=10) as response:
        html_text = response.read().decode("utf-8", errors="ignore")
    summary = extract_catastro_public_summary_from_html(html_text, clean_ref) or {}
    # Si el HTML cambia o hay varios bienes, no abortamos: generamos ficha PDF parcial y dejamos trazabilidad.
    # Intentamos seleccionar la coincidencia exacta (por los primeros 14 chars) si hay lista de items.
    items = summary.get("items") if isinstance(summary.get("items"), list) else []
    if items and clean_ref:
        needle = clean_ref[:14]
        def _matches(item_ref: str) -> bool:
            if not item_ref:
                return False
            if item_ref == clean_ref:
                return True
            if len(item_ref) >= 14 and item_ref[:14] == needle:
                return True
            return False

        exact = None
        for item in items:
            ref_item = clean_catastro_reference(item.get("referencia_catastral"))
            if _matches(ref_item):
                exact = item
                break
        if exact:
            parcel = {k: summary.get(k) for k in ("referencia_parcela", "tipo_parcela", "localizacion_parcela", "superficie_grafica_m2") if k in summary}
            summary = {**parcel, **exact}
        elif len(items) == 1:
            parcel = {k: summary.get(k) for k in ("referencia_parcela", "tipo_parcela", "localizacion_parcela", "superficie_grafica_m2") if k in summary}
            summary = {**parcel, **items[0]}
    # Asegura referencia en el resumen, aunque sea parcial.
    if clean_ref and not clean_catastro_reference(summary.get("referencia_catastral")):
        summary["referencia_catastral"] = clean_ref
    summary["source_url"] = source_url
    return summary, html_text


def build_catastro_sync_updates(inmueble, summary):
    inmueble = dict(inmueble or {})
    summary = summary or {}
    updates = {}
    ref = clean_catastro_reference(summary.get("referencia_catastral"))
    if ref:
        updates["referencia_catastral"] = ref
    surface = summary.get("superficie_construida_m2")
    if surface not in (None, ""):
        updates["m2"] = surface
    year = summary.get("anio_construccion")
    if year:
        updates["anio_construccion"] = int(year)
    inferred_type = infer_inmueble_type_from_catastro_use(summary.get("uso"), inmueble.get("tipo_inmueble"))
    if inferred_type:
        updates["tipo_inmueble"] = inferred_type
    if not str(inmueble.get("codigo_postal") or "").strip():
        code_match = re.search(r"\b(\d{5})\b", str(summary.get("localizacion") or ""))
        if code_match:
            updates["codigo_postal"] = code_match.group(1)
    return updates


def apply_catastro_summary_to_inmueble(conn, inmueble_id, inmueble, summary, now):
    updates = build_catastro_sync_updates(inmueble, summary)
    if not updates:
        return {}
    set_clause = ", ".join([f"{key} = ?" for key in updates])
    conn.execute(
        f"UPDATE inmuebles SET {set_clause}, updated_at = datetime(?) WHERE id = ?",
        [*updates.values(), now, inmueble_id],
    )
    cap_shared = {key: updates[key] for key in ("tipo_inmueble", "m2", "anio_construccion") if key in updates}
    if cap_shared:
        cap_set = ", ".join([f"{key} = ?" for key in cap_shared])
        conn.execute(
            f"UPDATE captaciones SET {cap_set}, updated_at = datetime(?) WHERE inmueble_id = ?",
            [*cap_shared.values(), now, inmueble_id],
        )
    return updates


def sync_catastro_for_inmueble(conn, inmueble_id, now, usuario=None):
    inmueble = conn.execute("SELECT * FROM inmuebles WHERE id = ? LIMIT 1", (inmueble_id,)).fetchone()
    if not inmueble:
        raise ValueError("Inmueble no encontrado")
    reference = clean_catastro_reference(inmueble["referencia_catastral"])
    if not reference:
        lookup = lookup_catastro_reference_by_address(
            provincia=str(inmueble["provincia"] or "").strip(),
            municipio=str(inmueble["poblacion"] or "").strip(),
            direccion=str(inmueble["direccion"] or "").strip(),
            codigo_postal=str(inmueble["codigo_postal"] or "").strip(),
        )
        if not lookup.get("match_unique") or not lookup.get("referencia_catastral"):
            raise RuntimeError("No se pudo obtener una referencia catastral única para este inmueble")
        reference = clean_catastro_reference(lookup.get("referencia_catastral"))
    summary, raw_html = fetch_catastro_public_summary(reference)
    updates = apply_catastro_summary_to_inmueble(conn, inmueble_id, dict(inmueble), summary, now)
    inmueble = conn.execute("SELECT * FROM inmuebles WHERE id = ? LIMIT 1", (inmueble_id,)).fetchone()
    empresa = conn.execute("SELECT * FROM empresas WHERE id = ? LIMIT 1", (inmueble["empresa_id"],)).fetchone()
    pdf_bytes = build_inmueble_catastro_sheet_pdf(dict(empresa) if empresa else {}, dict(inmueble), summary)
    safe_ref = slugify_text(inmueble["direccion"] or summary.get("referencia_catastral") or inmueble_id)[:50] or inmueble_id
    filename = f"ficha_catastro_{safe_ref}.pdf"
    doc = persist_generated_inmueble_pdf(
        conn,
        inmueble_id,
        "Ficha Catastro",
        f"Ficha Catastro · {inmueble['direccion'] or safe_ref}",
        pdf_bytes,
        filename.replace(".pdf", ""),
        now,
        replace_existing=True,
        empresa_id=inmueble["empresa_id"],
        usuario=usuario,
        plantilla_clave="catastro_ficha",
        origen_tipo="catastro",
        origen_id=summary.get("referencia_catastral") or reference,
        payload_json={"summary": summary},
    )
    return {
        "summary": summary,
        "updates": updates,
        "document": doc,
        "pdf_bytes": pdf_bytes,
        "filename": filename,
        "html_size": len(raw_html or ""),
    }


def lookup_catastro_reference_by_address(*, provincia="", municipio="", direccion="", codigo_postal=""):
    direccion = str(direccion or "").strip()
    if not direccion:
        raise ValueError("dirección requerida")
    provincia = normalize_person_name(provincia)
    municipio = normalize_person_name(municipio)
    parts = parse_inmobiliaria_address_for_catastro(direccion)
    if not parts["calle"]:
        raise ValueError("no se pudo interpretar la calle")
    if not parts["numero"]:
        raise ValueError("añade número en la dirección para buscar en Catastro")
    query = {
        "Provincia": provincia,
        "Municipio": municipio,
        "Sigla": parts["sigla"],
        "Calle": parts["calle"],
        "Numero": parts["numero"],
        "Bloque": parts["bloque"],
        "Escalera": parts["escalera"],
        "Planta": parts["planta"],
        "Puerta": parts["puerta"],
    }
    last_error = ""
    direct_candidates = []

    def _candidate_matches_requested_number(candidate, requested_number):
        label = str((candidate or {}).get("label") or "").strip()
        number = str(requested_number or "").strip()
        if not label or not number:
            return False
        try:
            return bool(re.search(rf"\b{re.escape(number)}[A-Z]?\b", label))
        except Exception:
            return False

    def _filter_candidates_by_number(candidates, requested_number):
        items = list(candidates or [])
        if not requested_number:
            return items
        return [item for item in items if _candidate_matches_requested_number(item, requested_number)]

    for base_url in CATRASTRO_LOOKUP_URLS:
        url = f"{base_url}?{urllib.parse.urlencode(query)}"
        try:
            with urllib.request.urlopen(url, timeout=8) as response:
                xml_text = response.read().decode("utf-8", errors="ignore")
            parsed = extract_catastro_candidates_from_xml(xml_text, fallback_label=direccion)
            if parsed["candidates"]:
                unique_refs = []
                seen_refs = set()
                for item in parsed["candidates"]:
                    ref = item["referencia_catastral"]
                    if ref in seen_refs:
                        continue
                    seen_refs.add(ref)
                    unique_refs.append(item)
                unique_refs = _filter_candidates_by_number(unique_refs, parts["numero"])
                if len(unique_refs) == 1 and not parsed["messages"]:
                    return {
                        "ok": True,
                        "direccion_consultada": direccion,
                        "direccion_normalizada": " ".join(
                            part for part in [parts["sigla"], parts["calle"], parts["numero"]] if part
                        ).strip(),
                        "codigo_postal": codigo_postal or "",
                        "provincia": provincia or "",
                        "municipio": municipio or "",
                        "candidates": unique_refs,
                        "referencia_catastral": unique_refs[0]["referencia_catastral"],
                        "match_unique": True,
                        "source_url": url,
                        "messages": parsed["messages"],
                    }
                direct_candidates = unique_refs
            if parsed["messages"]:
                last_error = "; ".join(parsed["messages"])
        except Exception as exc:
            last_error = str(exc)
            continue
    try:
        for street_query in build_catastro_street_queries(parts):
            _, street_xml = _fetch_catastro_xml(
                CATRASTRO_STREET_SEARCH_URL,
                {
                    "Provincia": provincia,
                    "Municipio": municipio,
                    "TipoVia": street_query["TipoVia"],
                    "NombreVia": street_query["NombreVia"],
                },
            )
            street_candidates = extract_catastro_streets_from_xml(street_xml)
            if not street_candidates:
                continue
            all_candidates = []
            seen_refs = set()
            for street in street_candidates[:8]:
                street_label = " ".join(part for part in [street.get("tipo_via"), street.get("nombre_via")] if part).strip()
                _, number_xml = _fetch_catastro_xml(
                    CATRASTRO_NUMBER_SEARCH_URL,
                    {
                        "Provincia": provincia,
                        "Municipio": municipio,
                        "TipoVia": street.get("tipo_via", ""),
                        "NomVia": street.get("nombre_via", ""),
                        "Numero": parts["numero"],
                    },
                )
                number_result = extract_catastro_numbers_from_xml(number_xml, street_label=street_label)
                for candidate in number_result["candidates"]:
                    ref = candidate["referencia_catastral"]
                    if ref in seen_refs:
                        continue
                    seen_refs.add(ref)
                    all_candidates.append(candidate)
                if number_result["messages"]:
                    last_error = "; ".join(number_result["messages"])
            if all_candidates:
                exact_candidates = [
                    item
                    for item in all_candidates
                    if re.search(rf"\b{re.escape(parts['numero'])}[A-Z]?\b", item.get("label") or "")
                ]
                if not exact_candidates:
                    return {
                        "ok": True,
                        "direccion_consultada": direccion,
                        "direccion_normalizada": " ".join(
                            part for part in [parts["sigla"], parts["calle"], parts["numero"]] if part
                        ).strip(),
                        "codigo_postal": codigo_postal or "",
                        "provincia": provincia or "",
                        "municipio": municipio or "",
                        "candidates": [],
                        "referencia_catastral": "",
                        "match_unique": False,
                        "source_url": CATRASTRO_NUMBER_SEARCH_URL,
                        "messages": [
                            item
                            for item in [
                                last_error,
                                "Catastro no devolvió una coincidencia exacta para el número indicado. Revisa el número de portal.",
                            ]
                            if item
                        ],
                        "candidates_sugeridos": all_candidates[:10],
                    }
                selected = exact_candidates
                return {
                    "ok": True,
                    "direccion_consultada": direccion,
                    "direccion_normalizada": " ".join(
                        part for part in [parts["sigla"], parts["calle"], parts["numero"]] if part
                    ).strip(),
                    "codigo_postal": codigo_postal or "",
                    "provincia": provincia or "",
                    "municipio": municipio or "",
                    "candidates": selected,
                    "referencia_catastral": selected[0]["referencia_catastral"] if len(selected) == 1 else "",
                    "match_unique": len(selected) == 1,
                    "source_url": CATRASTRO_NUMBER_SEARCH_URL,
                    "messages": [last_error] if last_error else [],
                }
    except Exception as exc:
        last_error = str(exc)
    if direct_candidates:
        direct_candidates = _filter_candidates_by_number(direct_candidates, parts["numero"])
        if not direct_candidates:
            return {
                "ok": True,
                "direccion_consultada": direccion,
                "direccion_normalizada": " ".join(
                    part for part in [parts["sigla"], parts["calle"], parts["numero"]] if part
                ).strip(),
                "codigo_postal": codigo_postal or "",
                "provincia": provincia or "",
                "municipio": municipio or "",
                "candidates": [],
                "referencia_catastral": "",
                "match_unique": False,
                "source_url": CATRASTRO_LOOKUP_URLS[0],
                "messages": [
                    item
                    for item in [
                        last_error,
                        "Catastro devolvió coincidencias, pero ninguna corresponde al número indicado. Revisa el número de portal.",
                    ]
                    if item
                ],
            }
        return {
            "ok": True,
            "direccion_consultada": direccion,
            "direccion_normalizada": " ".join(
                part for part in [parts["sigla"], parts["calle"], parts["numero"]] if part
            ).strip(),
            "codigo_postal": codigo_postal or "",
            "provincia": provincia or "",
            "municipio": municipio or "",
            "candidates": direct_candidates,
            "referencia_catastral": direct_candidates[0]["referencia_catastral"] if len(direct_candidates) == 1 else "",
            "match_unique": len(direct_candidates) == 1,
            "source_url": CATRASTRO_LOOKUP_URLS[0],
            "messages": [last_error] if last_error else [],
        }
    raise RuntimeError(last_error or "no se pudo obtener respuesta del Catastro")


def resolve_owner_nifs_from_cliente_ids(conn, cliente_ids):
    normalized = []
    seen = set()
    for cliente_id in cliente_ids or []:
        row = conn.execute(
            "SELECT nif FROM clientes WHERE id = ? LIMIT 1",
            (cliente_id,),
        ).fetchone()
        nif = normalize_nif(row["nif"] if row else "")
        if nif and nif not in seen:
            seen.add(nif)
            normalized.append(nif)
    return normalized


def detect_inmobiliaria_duplicates(conn, empresa_id, *, direccion="", referencia_catastral="", owner_nifs=None, scope="captacion"):
    direccion_norm = normalize_inmobiliaria_address(direccion)
    ref_norm = clean_catastro_reference(referencia_catastral)
    owner_nifs = [normalize_nif(item) for item in (owner_nifs or []) if normalize_nif(item)]
    owner_nif_set = set(owner_nifs)
    duplicates = []

    inmueble_rows = conn.execute(
        """
        SELECT
          i.id AS inmueble_id,
          i.direccion,
          i.referencia,
          i.referencia_catastral,
          i.estado,
          cpt.id AS captacion_id,
          cpt.propietario,
          cpt.etapa,
          GROUP_CONCAT(DISTINCT c.nif) AS propietario_nifs
        FROM inmuebles i
        LEFT JOIN captaciones cpt ON cpt.inmueble_id = i.id
        LEFT JOIN inmueble_propietarios ip ON ip.inmueble_id = i.id
        LEFT JOIN clientes c ON c.id = ip.cliente_id
        WHERE i.empresa_id = ?
        GROUP BY i.id, cpt.id
        ORDER BY COALESCE(i.updated_at, i.created_at) DESC
        """,
        (empresa_id,),
    ).fetchall()
    for row in inmueble_rows:
        reasons = []
        if direccion_norm and normalize_inmobiliaria_address(row["direccion"]) == direccion_norm:
            reasons.append("misma dirección")
        if ref_norm and clean_catastro_reference(row["referencia_catastral"]) == ref_norm:
            reasons.append("misma referencia catastral")
        row_nifs = {
            normalize_nif(part)
            for part in re.split(r"[|,]", str(row["propietario_nifs"] or ""))
            if normalize_nif(part)
        }
        shared_nifs = sorted(row_nifs.intersection(owner_nif_set))
        if shared_nifs:
            reasons.append(f"mismo DNI/NIF de propietario ({', '.join(shared_nifs)})")
        if not reasons:
            continue
        duplicates.append(
            {
                "type": "inmueble",
                "id": row["inmueble_id"],
                "direccion": row["direccion"] or "",
                "label": row["direccion"] or row["referencia"] or "Inmueble existente",
                "subtype": "captacion" if row["captacion_id"] else "inmueble",
                "propietario": row["propietario"] or "",
                "referencia_catastral": row["referencia_catastral"] or "",
                "estado": row["estado"] or "",
                "reasons": reasons,
            }
        )

    if scope == "compraventa":
        operacion_rows = conn.execute(
            """
            SELECT
              id,
              direccion,
              fecha_escritura,
              propietario1_nombre,
              propietario1_nif,
              propietario2_nombre,
              propietario2_nif
            FROM operaciones_inmobiliarias
            WHERE empresa_id = ?
              AND LOWER(COALESCE(tipo_operacion, 'venta')) = 'venta'
            ORDER BY COALESCE(updated_at, created_at) DESC
            """,
            (empresa_id,),
        ).fetchall()
        for row in operacion_rows:
            reasons = []
            if direccion_norm and normalize_inmobiliaria_address(row["direccion"]) == direccion_norm:
                reasons.append("misma dirección en compraventa existente")
            row_nifs = {
                normalize_nif(row["propietario1_nif"]),
                normalize_nif(row["propietario2_nif"]),
            }
            row_nifs = {item for item in row_nifs if item}
            shared_nifs = sorted(row_nifs.intersection(owner_nif_set))
            if shared_nifs:
                reasons.append(f"mismo DNI/NIF de vendedor ({', '.join(shared_nifs)})")
            if not reasons:
                continue
            duplicates.append(
                {
                    "type": "compraventa",
                    "id": row["id"],
                    "direccion": row["direccion"] or "",
                    "label": row["direccion"] or "Compraventa existente",
                    "fecha_escritura": row["fecha_escritura"] or "",
                    "propietario": " | ".join(
                        [
                            item
                            for item in [
                                row["propietario1_nombre"] or "",
                                row["propietario2_nombre"] or "",
                            ]
                            if item
                        ]
                    ),
                    "reasons": reasons,
                }
            )

    deduped = []
    seen = set()
    for item in duplicates:
        signature = (
            item.get("type"),
            item.get("id"),
            tuple(item.get("reasons") or []),
        )
        if signature in seen:
            continue
        seen.add(signature)
        deduped.append(item)
    return deduped


def fetch_inmueble_for_empresa(conn, inmueble_id, empresa_id):
    iid = str(inmueble_id or "").strip()
    eid = str(empresa_id or "").strip()
    if not iid or not eid:
        return None
    return conn.execute(
        "SELECT * FROM inmuebles WHERE id = ? AND empresa_id = ? LIMIT 1",
        (iid, eid),
    ).fetchone()


def fetch_demanda_for_empresa(conn, demanda_id, empresa_id):
    did = str(demanda_id or "").strip()
    eid = str(empresa_id or "").strip()
    if not did or not eid:
        return None
    return conn.execute(
        "SELECT * FROM demandas WHERE id = ? AND empresa_id = ? LIMIT 1",
        (did, eid),
    ).fetchone()


def _inmo_match_text(value):
    return normalize_lookup_text(value or "")


def _inmo_match_contains(haystack, needle):
    hay = _inmo_match_text(haystack)
    ned = _inmo_match_text(needle)
    if not hay or not ned:
        return True
    return ned in hay or hay in ned


def score_inmobiliaria_demanda_inmueble_match(demanda, inmueble):
    demanda = dict(demanda or {})
    inmueble = dict(inmueble or {})
    reasons = []
    score = 0
    active = 0

    estado_inmueble = _inmo_match_text(inmueble.get("estado") or inmueble.get("situacion_comercial"))
    if estado_inmueble in {"vendido", "alquilado", "cerrado", "cerrada", "historico vendido", "histórico vendido"}:
        return {"score": -1, "reasons": ["inmueble_cerrado"]}

    demanda_estado = _inmo_match_text(demanda.get("estado"))
    demanda_fase = _inmo_match_text(demanda.get("fase"))
    if demanda_estado in {"cerrada", "cerrado", "descartada", "descartado"} or demanda_fase in {"cerrada", "cerrado", "no interesante"}:
        return {"score": -1, "reasons": ["demanda_cerrada"]}

    demanda_tipo = _inmo_match_text(demanda.get("tipo"))
    inmueble_operacion = _inmo_match_text(inmueble.get("tipo_operacion"))
    if demanda_tipo in {"compra", "comprar", "venta"} and inmueble_operacion and inmueble_operacion not in {"venta", "compraventa"}:
        return {"score": -1, "reasons": ["operacion_incompatible"]}
    if demanda_tipo in {"alquiler", "arrendamiento", "renta"} and inmueble_operacion and inmueble_operacion not in {"alquiler", "arrendamiento", "renta"}:
        return {"score": -1, "reasons": ["operacion_incompatible"]}
    if demanda_tipo:
        score += 4
        reasons.append("operacion")

    tipologia = demanda.get("tipologia")
    inmueble_tipo = inmueble.get("tipo_inmueble") or inmueble.get("tipologia")
    if str(tipologia or "").strip() and str(inmueble_tipo or "").strip():
        active += 1
        if _inmo_match_contains(inmueble_tipo, tipologia):
            score += 18
            reasons.append("tipologia")
        else:
            return {"score": -1, "reasons": ["tipologia_incompatible"]}

    subtipologia = demanda.get("subtipologia")
    inmueble_sub = inmueble.get("subtipologia")
    if str(subtipologia or "").strip() and str(inmueble_sub or "").strip():
        active += 1
        if _inmo_match_contains(inmueble_sub, subtipologia):
            score += 8
            reasons.append("subtipologia")
        else:
            return {"score": -1, "reasons": ["subtipologia_incompatible"]}

    zona = demanda.get("zona") or demanda.get("focalizacion")
    inmueble_zona = inmueble.get("zona") or inmueble.get("focalizacion") or inmueble.get("poblacion") or inmueble.get("localidad")
    if str(zona or "").strip() and str(inmueble_zona or "").strip():
        active += 1
        if _inmo_match_contains(inmueble_zona, zona):
            score += 22
            reasons.append("zona")
        else:
            return {"score": -1, "reasons": ["zona_incompatible"]}

    precio_max = parse_money_value(demanda.get("precio_max"))
    precio = parse_money_value(
        inmueble.get("precio_encargo")
        or inmueble.get("precio_objetivo")
        or inmueble.get("precio_pedido_cliente")
        or inmueble.get("precio_valoracion")
    )
    if precio_max and precio:
        active += 1
        if precio <= precio_max:
            ratio = max(0.0, min(1.0, float(precio) / float(precio_max)))
            score += 28 + int((1.0 - ratio) * 8)
            reasons.append("precio")
        else:
            return {"score": -1, "reasons": ["precio_superior"]}
    else:
        score += 5

    m2_min = parse_optional_float(demanda.get("m2_min"))
    m2 = parse_optional_float(inmueble.get("m2"))
    if m2_min and m2:
        active += 1
        if m2 >= m2_min:
            score += 12
            reasons.append("m2")
        else:
            return {"score": -1, "reasons": ["m2_insuficiente"]}

    habitaciones_min = parse_optional_int(demanda.get("habitaciones_min"))
    habitaciones = parse_optional_int(inmueble.get("habitaciones"))
    if habitaciones_min and habitaciones is not None:
        active += 1
        if habitaciones >= habitaciones_min:
            score += 8
            reasons.append("habitaciones")
        else:
            return {"score": -1, "reasons": ["habitaciones_insuficientes"]}

    banos_min = parse_optional_int(demanda.get("banos_min"))
    banos = parse_optional_int(inmueble.get("banos"))
    if banos_min and banos is not None:
        active += 1
        if banos >= banos_min:
            score += 6
            reasons.append("banos")
        else:
            return {"score": -1, "reasons": ["banos_insuficientes"]}

    if active == 0:
        score = max(score, 25)
        reasons.append("sin_restricciones")
    elif score > 100:
        score = 100
    return {"score": int(score), "reasons": reasons}


def fetch_inmueble_matches_for_demanda(conn, empresa_id, demanda_id, limit=50):
    demanda = fetch_demanda_for_empresa(conn, demanda_id, empresa_id)
    if not demanda:
        return None
    limit_val = max(1, min(int(limit or 50), 200))
    rows = conn.execute(
        """
        SELECT id, referencia, direccion, zona, focalizacion, poblacion, localidad, provincia,
               tipo_inmueble, subtipologia, precio_objetivo, precio_encargo,
               precio_pedido_cliente, precio_valoracion, m2, habitaciones, banos, estado,
               created_at, updated_at
        FROM inmuebles
        WHERE empresa_id = ?
        ORDER BY updated_at DESC, created_at DESC
        LIMIT 1000
        """,
        (empresa_id,),
    ).fetchall()
    out = []
    for row in rows:
        payload = dict(row)
        match = score_inmobiliaria_demanda_inmueble_match(dict(demanda), payload)
        if int(match.get("score", -1)) < 0:
            continue
        payload["score"] = int(match.get("score") or 0)
        payload["match_reasons"] = match.get("reasons") or []
        out.append(payload)
    out.sort(key=lambda item: (-int(item.get("score") or 0), str(item.get("updated_at") or item.get("created_at") or "")), reverse=False)
    return out[:limit_val]


def fetch_demanda_matches_for_inmueble(conn, inmueble_id, limit=100):
    inmueble = conn.execute("SELECT * FROM inmuebles WHERE id = ? LIMIT 1", (inmueble_id,)).fetchone()
    if not inmueble:
        return None
    limit_val = max(1, min(int(limit or 100), 300))
    rows = conn.execute(
        """
        SELECT d.id,
               d.id AS demanda_id,
               d.cliente_id,
               d.focalizacion,
               d.pedido,
               d.tipo,
               d.zona,
               d.tipologia,
               d.subtipologia,
               d.precio_max,
               d.m2_min,
               d.habitaciones_min,
               d.banos_min,
               d.estado,
               d.fase,
               d.prioridad,
               d.estado_contacto,
               d.responsable,
               d.notas,
               d.created_at,
               d.updated_at,
               c.nombre AS cliente
        FROM demandas d
        LEFT JOIN clientes c ON c.id = d.cliente_id
        WHERE d.empresa_id = ?
        ORDER BY d.updated_at DESC, d.created_at DESC
        LIMIT 1000
        """,
        (inmueble["empresa_id"],),
    ).fetchall()
    out = []
    inmueble_payload = dict(inmueble)
    for row in rows:
        payload = dict(row)
        match = score_inmobiliaria_demanda_inmueble_match(payload, inmueble_payload)
        if int(match.get("score", -1)) < 0:
            continue
        payload["score"] = int(match.get("score") or 0)
        payload["match_reasons"] = match.get("reasons") or []
        out.append(payload)
    out.sort(key=lambda item: (-int(item.get("score") or 0), str(item.get("updated_at") or item.get("created_at") or "")), reverse=False)
    return out[:limit_val]


def _portal_inmueble_photo_expr(conn, alias="i"):
    # Primera foto vigente del inmueble. Funciona en SQLite y Postgres con subquery escalar.
    return (
        "SELECT d.url FROM inmueble_docs d "
        f"WHERE d.inmueble_id = {alias}.id "
        "AND LOWER(COALESCE(d.estado, 'Vigente')) != 'reemplazado' "
        "AND (LOWER(COALESCE(d.tipo, '')) LIKE '%foto%' OR LOWER(COALESCE(d.url, '')) LIKE '%.jpg' "
        "OR LOWER(COALESCE(d.url, '')) LIKE '%.jpeg' OR LOWER(COALESCE(d.url, '')) LIKE '%.png' "
        "OR LOWER(COALESCE(d.url, '')) LIKE '%.webp') "
        "ORDER BY d.created_at ASC LIMIT 1"
    )


def portal_inmueble_row_to_public(row):
    data = dict(row or {})
    price = data.get("precio_encargo") or data.get("precio_objetivo") or data.get("precio_pedido_cliente") or data.get("precio_valoracion")
    title = data.get("titulo_anuncio") or data.get("titulo") or data.get("direccion") or "Inmueble Verifika2"
    description = data.get("descripcion_larga") or data.get("descripcion_corta") or data.get("descripcion")
    empresa_id = data.get("empresa_id")
    empresa_nombre_publico = "Grupo Modernia"
    empresa_logo_publico = "/assets/grupo_modernia_logo.png"
    return {
        "id": data.get("id"),
        "referencia": data.get("referencia"),
        "titulo": title,
        "titulo_anuncio": data.get("titulo_anuncio"),
        "direccion": data.get("direccion"),
        "zona": data.get("zona"),
        "poblacion": data.get("poblacion") or data.get("localidad"),
        "provincia": data.get("provincia"),
        "tipo_operacion": data.get("tipo_operacion") or "venta",
        "tipo_inmueble": data.get("tipo_inmueble"),
        "subtipologia": data.get("subtipologia"),
        "m2": data.get("m2"),
        "habitaciones": data.get("habitaciones"),
        "banos": data.get("banos"),
        "precio": price,
        "estado": data.get("estado"),
        "descripcion": description,
        "descripcion_corta": data.get("descripcion_corta"),
        "descripcion_larga": data.get("descripcion_larga"),
        "destacados": data.get("destacados"),
        "seo_slug": data.get("seo_slug"),
        "lat": data.get("lat"),
        "lon": data.get("lon"),
        "foto": data.get("foto"),
        "empresa_id": empresa_id,
        "empresa_nombre": empresa_nombre_publico,
        "empresa_logo": empresa_logo_publico,
        "inmobiliaria_nombre": empresa_nombre_publico,
        "inmobiliaria_logo": empresa_logo_publico,
        "certificado": int(data.get("certificado") or 0),
        "verificado": int(data.get("noticia_verificada") or 0),
        "publicado_at": data.get("portal_publicado_at"),
    }


def fetch_portal_inmuebles_public(conn, *, listing_id="", limit=100):
    try:
        ensure_column(conn, "inmuebles", "portal_publicado", "portal_publicado INTEGER NOT NULL DEFAULT 0")
        ensure_column(conn, "inmuebles", "portal_publicado_at", "portal_publicado_at TEXT")
        ensure_column(conn, "inmuebles", "portal_retirado_at", "portal_retirado_at TEXT")
        ensure_column(conn, "inmuebles", "certificado", "certificado INTEGER NOT NULL DEFAULT 0")
        ensure_column(conn, "inmuebles", "titulo_anuncio", "titulo_anuncio TEXT")
        ensure_column(conn, "inmuebles", "descripcion_corta", "descripcion_corta TEXT")
        ensure_column(conn, "inmuebles", "descripcion_larga", "descripcion_larga TEXT")
        ensure_column(conn, "inmuebles", "destacados", "destacados TEXT")
        ensure_column(conn, "inmuebles", "seo_slug", "seo_slug TEXT")
    except Exception:
        pass
    photo_expr = _portal_inmueble_photo_expr(conn, "i")
    where = [
        "COALESCE(i.portal_publicado, 0) = 1",
        """
        EXISTS (
          SELECT 1
          FROM captaciones cv
          WHERE cv.inmueble_id = i.id
            AND COALESCE(cv.noticia_verificada, 0) = 1
        )
        """,
        "LOWER(TRIM(COALESCE(i.estado, ''))) NOT IN ('vendido', 'alquilado', 'cerrado negativamente', 'historico vendido', 'histórico vendido')",
    ]
    values = []
    if listing_id:
        where.append("i.id = ?")
        values.append(str(listing_id).strip())
    limit_val = max(1, min(int(limit or 100), 300))
    rows = conn.execute(
        f"""
        SELECT
          i.id, i.empresa_id, i.referencia, i.titulo, i.direccion, i.zona, i.localidad, i.poblacion, i.provincia,
          i.tipo_operacion, i.tipo_inmueble, i.subtipologia, i.m2, i.habitaciones, i.banos,
          i.precio_objetivo, i.precio_encargo, i.precio_pedido_cliente, i.precio_valoracion,
          i.estado, i.descripcion, i.lat, i.lon, i.certificado, i.portal_publicado_at,
          i.titulo_anuncio, i.descripcion_corta, i.descripcion_larga, i.destacados, i.seo_slug,
          MAX(e.nombre) AS empresa_nombre, MAX(e.logo_url) AS empresa_logo,
          MAX(COALESCE(c.noticia_verificada, 0)) AS noticia_verificada,
          ({photo_expr}) AS foto
        FROM inmuebles i
        LEFT JOIN captaciones c ON c.inmueble_id = i.id
        LEFT JOIN empresas e ON e.id = i.empresa_id
        WHERE {' AND '.join(where)}
        GROUP BY i.id
        ORDER BY COALESCE(NULLIF(i.portal_publicado_at, ''), i.updated_at, i.created_at) DESC
        LIMIT ?
        """,
        (*values, limit_val),
    ).fetchall()
    return [portal_inmueble_row_to_public(row) for row in rows]


def build_inmueble_anuncio_copy(inmueble):
    data = dict(inmueble or {})

    def text(*keys):
        for key in keys:
            value = str(data.get(key) or "").strip()
            if value:
                return value
        return ""

    def num(key):
        try:
            value = float(data.get(key) or 0)
        except Exception:
            value = 0.0
        return int(value) if value and value.is_integer() else value

    tipo = text("tipo_inmueble") or "Inmueble"
    subtipo = text("subtipologia")
    operacion = normalize_lookup_text(text("tipo_operacion") or "venta")
    zona = text("zona")
    poblacion = text("poblacion", "localidad")
    provincia = text("provincia")
    ubicacion = " en ".join([part for part in [zona, poblacion] if part]) or poblacion or provincia
    location_phrase = f" en {ubicacion}" if ubicacion else ""
    m2 = num("m2")
    habitaciones = num("habitaciones")
    banos = num("banos")
    estado = text("estado_inmueble", "estado")
    ocupacion = text("situacion_ocupacion")
    precio = data.get("precio_encargo") or data.get("precio_objetivo") or data.get("precio_pedido_cliente") or data.get("precio_valoracion")

    tipo_label = f"{subtipo} {tipo}".strip() if subtipo and subtipo.lower() not in tipo.lower() else tipo
    op_label = "alquiler" if operacion in {"alquiler", "arrendamiento", "renta"} else "venta"
    title_parts = [tipo_label, location_phrase.strip()]
    title = " ".join([part for part in title_parts if part]).strip()
    if not title:
        title = text("titulo") or text("direccion") or "Inmueble Verifika2"
    title = title[:120]

    feature_bits = []
    if m2:
        feature_bits.append(f"{m2} m2")
    if habitaciones:
        feature_bits.append(f"{habitaciones} dormitorio{'s' if int(habitaciones) != 1 else ''}")
    if banos:
        feature_bits.append(f"{banos} baño{'s' if int(banos) != 1 else ''}")
    if estado:
        feature_bits.append(f"estado {estado.lower()}")
    if ocupacion:
        feature_bits.append(f"ocupacion: {ocupacion.lower()}")

    short = f"{tipo_label}{location_phrase}"
    if feature_bits:
        short = f"{short} con {', '.join(feature_bits[:3])}"
    if precio:
        short = f"{short}. Precio de {op_label} disponible en ficha."
    else:
        short = f"{short}. Solicita mas informacion y visita."

    paragraphs = [
        f"Verifika2 presenta este {tipo_label.lower()}{location_phrase}, una oportunidad pensada para quienes buscan una operacion de {op_label} con informacion clara y contrastada.",
    ]
    if feature_bits:
        paragraphs.append(f"La vivienda cuenta con {', '.join(feature_bits)}.")
    base_desc = text("descripcion")
    if base_desc:
        paragraphs.append(base_desc)
    paragraphs.append("Contacta con nuestro equipo para ampliar informacion, resolver dudas y coordinar una visita.")
    long = "\n\n".join(paragraphs).strip()

    highlights = []
    if m2:
        highlights.append(f"{m2} m2 construidos")
    if habitaciones:
        highlights.append(f"{habitaciones} dormitorios")
    if banos:
        highlights.append(f"{banos} banos")
    if ubicacion:
        highlights.append(ubicacion)
    if estado:
        highlights.append(estado)
    if not highlights:
        highlights.append("Inmueble verificado")

    slug_source = " ".join([title, poblacion, provincia]).strip() or text("referencia") or text("id")
    return {
        "titulo_anuncio": title,
        "descripcion_corta": short[:280],
        "descripcion_larga": long[:4000],
        "destacados": " | ".join(highlights[:8]),
        "seo_slug": slugify_text(slug_source)[:140],
    }


def validate_portal_publication_requirements(conn, inmueble_id):
    inmueble_id = str(inmueble_id or "").strip()
    if not inmueble_id:
        return {"ok": False, "missing": ["inmueble_id"], "checks": {}, "row": None}
    try:
        for col_name, col_sql in {
            "portal_publicado": "portal_publicado INTEGER NOT NULL DEFAULT 0",
            "certificado": "certificado INTEGER NOT NULL DEFAULT 0",
            "titulo_anuncio": "titulo_anuncio TEXT",
            "descripcion_corta": "descripcion_corta TEXT",
            "descripcion_larga": "descripcion_larga TEXT",
            "destacados": "destacados TEXT",
            "seo_slug": "seo_slug TEXT",
        }.items():
            ensure_column(conn, "inmuebles", col_name, col_sql)
    except Exception:
        pass
    row = conn.execute("SELECT * FROM inmuebles WHERE id = ? LIMIT 1", (inmueble_id,)).fetchone()
    if not row:
        return {"ok": False, "missing": ["inmueble"], "checks": {}, "row": None}
    captacion = conn.execute(
        """
        SELECT COALESCE(MAX(noticia_verificada), 0) AS noticia_verificada
        FROM captaciones
        WHERE inmueble_id = ?
        """,
        (inmueble_id,),
    ).fetchone()
    photo = conn.execute(
        """
        SELECT id
        FROM inmueble_docs
        WHERE inmueble_id = ?
          AND LOWER(COALESCE(estado, 'Vigente')) NOT IN ('eliminado', 'borrado')
          AND (
            LOWER(COALESCE(tipo, '')) LIKE '%foto%'
            OR LOWER(COALESCE(nombre, '')) LIKE '%.jpg'
            OR LOWER(COALESCE(nombre, '')) LIKE '%.jpeg'
            OR LOWER(COALESCE(nombre, '')) LIKE '%.png'
            OR LOWER(COALESCE(nombre, '')) LIKE '%.webp'
            OR LOWER(COALESCE(url, '')) LIKE '%.jpg'
            OR LOWER(COALESCE(url, '')) LIKE '%.jpeg'
            OR LOWER(COALESCE(url, '')) LIKE '%.png'
            OR LOWER(COALESCE(url, '')) LIKE '%.webp'
          )
        LIMIT 1
        """,
        (inmueble_id,),
    ).fetchone()
    price = row["precio_encargo"] or row["precio_objetivo"] or row["precio_pedido_cliente"] or row["precio_valoracion"]
    state_norm = normalize_lookup_text(row["estado"])
    description = str(row["descripcion_larga"] or row["descripcion_corta"] or row["descripcion"] or "").strip()
    noticia_verificada = 0
    if captacion:
        try:
            noticia_verificada = int(row_value(captacion, "noticia_verificada", 0) or 0)
        except Exception:
            noticia_verificada = 0
    checks = {
        "verificado": noticia_verificada == 1,
        "estado_publicable": state_norm not in {"vendido", "alquilado", "cerrado negativamente", "historico vendido", "histórico vendido"},
        "precio": parse_money_value(price) > 0,
        "ubicacion": bool(str(row["direccion"] or "").strip() and (str(row["poblacion"] or row["localidad"] or row["zona"] or "").strip())),
        "tipo": bool(str(row["tipo_inmueble"] or "").strip()),
        "descripcion": bool(description),
        "foto": bool(photo),
    }
    labels = {
        "verificado": "Noticia verificada",
        "estado_publicable": "Estado publicable",
        "precio": "Precio",
        "ubicacion": "Ubicación",
        "tipo": "Tipo de inmueble",
        "descripcion": "Texto/descripción de anuncio",
        "foto": "Foto principal",
    }
    missing = [labels[key] for key, ok in checks.items() if not ok]
    return {"ok": not missing, "missing": missing, "checks": checks, "row": row}


def create_portal_inmueble_lead(conn, payload, now):
    if not isinstance(payload, dict):
        return {"error": "payload inválido"}, 400
    listing_payload = payload.get("listing") if isinstance(payload.get("listing"), dict) else {}
    listing_id = str(
        payload.get("listing_id")
        or payload.get("inmueble_id")
        or payload.get("id")
        or listing_payload.get("id")
        or ""
    ).strip()
    if not listing_id:
        return {"error": "listing_id requerido"}, 400
    listing_rows = fetch_portal_inmuebles_public(conn, listing_id=listing_id, limit=1)
    if not listing_rows:
        return {"error": "Inmueble no publicado"}, 404
    inmueble = conn.execute("SELECT * FROM inmuebles WHERE id = ? LIMIT 1", (listing_id,)).fetchone()
    if not inmueble:
        return {"error": "Inmueble no encontrado"}, 404
    contact = str(payload.get("contact") or "").strip()
    nombre = normalize_person_name(payload.get("nombre") or payload.get("name"))
    telefono = str(payload.get("telefono") or payload.get("phone") or "").strip()
    email = normalize_email(payload.get("email"))
    if contact and "@" in contact and not email:
        email = normalize_email(contact)
    elif contact and not telefono:
        telefono = contact
    notas = str(payload.get("mensaje") or payload.get("notas") or payload.get("message") or payload.get("note") or "").strip()
    if not nombre and not telefono and not email:
        return {"error": "nombre, teléfono o email requerido"}, 400
    empresa_id = inmueble["empresa_id"]
    workspace_id = str(
        payload.get("workspace_id")
        or listing_payload.get("workspace_id")
        or row_value(inmueble, "workspace_id")
        or ""
    ).strip()
    if not workspace_id:
        try:
            rows = conn.execute(
                """
                SELECT workspace_id
                FROM workspace_companies
                WHERE legacy_empresa_id = ?
                  AND COALESCE(activo, 1) = 1
                UNION
                SELECT workspace_id
                FROM workspace_empresas
                WHERE empresa_id = ?
                """,
                (empresa_id, empresa_id),
            ).fetchall()
            candidates = [
                str(row_value(r, "workspace_id") or row_value(r, 0) or "").strip()
                for r in (rows or [])
            ]
            candidates = [c for c in candidates if c]
            if len(set(candidates)) == 1:
                workspace_id = candidates[0]
        except Exception:
            workspace_id = ""
    if not workspace_id:
        workspace_id = str(os.environ.get("PORTAL_LEADS_WORKSPACE_ID") or "").strip()
    if not workspace_id:
        # Workspace de producción del CRM inmobiliario de Grupo Modernia.
        workspace_id = "6e63e1d1205c4c2a85dde7e20d5409f0"
    cliente_id = ensure_cliente_for_inmobiliaria(
        conn,
        empresa_id,
        nombre or email or telefono,
        payload.get("nif"),
        now,
        {"telefono": telefono, "email": email},
    )
    existing = conn.execute(
        """
        SELECT
          ic.id AS comprador_id,
          ic.demanda_id,
          d.id AS demanda_id_resolved
        FROM inmueble_compradores ic
        LEFT JOIN demandas d ON d.id = ic.demanda_id
        WHERE ic.inmueble_id = ?
          AND COALESCE(ic.cliente_id, d.cliente_id) = ?
        ORDER BY ic.updated_at DESC
        LIMIT 1
        """,
        (listing_id, cliente_id),
    ).fetchone()
    if existing:
        demanda_id = str(existing["demanda_id"] or existing["demanda_id_resolved"] or "").strip()
        conn.execute(
            """
            UPDATE inmueble_compradores
            SET estado = COALESCE(NULLIF(estado, ''), 'Pendiente'),
                fecha_ultimo_contacto = date('now'),
                notas = ?,
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                notas or "Nuevo contacto recibido desde portal Verifika2",
                now,
                existing["comprador_id"],
            ),
        )
        if demanda_id:
            conn.execute(
                """
                UPDATE demandas
                SET estado = COALESCE(NULLIF(estado, ''), 'Activa'),
                    fase = CASE
                      WHEN COALESCE(NULLIF(fase, ''), '') = '' THEN 'Portal'
                      ELSE fase
                    END,
                    estado_contacto = 'Pendiente',
                    notas = CASE
                      WHEN ? = '' THEN notas
                      WHEN COALESCE(notas, '') = '' THEN ?
                      ELSE notas || char(10) || ?
                    END,
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (notas, notas, f"Nuevo contacto portal: {notas}", now, demanda_id),
            )
        conn.commit()
        return {"ok": True, "listing_id": listing_id, "cliente_id": cliente_id, "demanda_id": demanda_id, "updated": True}, 200

    demanda_id = os.urandom(16).hex()
    d_cols = table_columns(conn, "demandas") or set()
    demanda_payload = {
        "id": demanda_id,
        "empresa_id": empresa_id,
        "cliente_id": cliente_id,
        "workspace_id": workspace_id,
        "focalizacion": "Portal Verifika2",
        "pedido": f"Lead portal Verifika2 · {inmueble['direccion'] or inmueble['referencia'] or listing_id}",
        "tipo": "Compra" if normalize_lookup_text(inmueble["tipo_operacion"]) not in {"alquiler", "arrendamiento", "renta"} else "Alquiler",
        "zona": inmueble["zona"] or inmueble["poblacion"] or inmueble["localidad"],
        "tipologia": inmueble["tipo_inmueble"],
        "subtipologia": inmueble["subtipologia"],
        "precio_max": inmueble["precio_encargo"] or inmueble["precio_objetivo"] or inmueble["precio_pedido_cliente"],
        "m2_min": inmueble["m2"],
        "habitaciones_min": inmueble["habitaciones"],
        "banos_min": inmueble["banos"],
        "estado": "Activa",
        "fase": "Portal",
        "prioridad": "Alta",
        "origen": "Portal Verifika2",
        "pedido_web": 1,
        "anuncio_mi_cartera": 1,
        "presentacion_servicio": 0,
        "fecha_insercion": datetime.now(timezone.utc).date().isoformat(),
        "estado_contacto": "Pendiente",
        "notas": "\n".join(
            part
            for part in [
                notas,
                f"Inmueble: {listing_id}",
                f"Lead Hub: {payload.get('hub_lead_id')}" if payload.get("hub_lead_id") else "",
            ]
            if str(part or "").strip()
        ).strip(),
        "created_at": now,
        "updated_at": now,
    }
    keys = [key for key in demanda_payload if key in d_cols]
    conn.execute(
        f"INSERT INTO demandas ({', '.join(keys)}) VALUES ({', '.join(['?'] * len(keys))})",
        [demanda_payload[key] for key in keys],
    )
    ic_cols = table_columns(conn, "inmueble_compradores") or set()
    if ic_cols:
        ic_payload = {
            "id": os.urandom(16).hex(),
            "empresa_id": empresa_id,
            "workspace_id": workspace_id,
            "inmueble_id": listing_id,
            "demanda_id": demanda_id,
            "cliente_id": cliente_id,
            "estado": "Pendiente",
            "fecha_ultimo_contacto": datetime.now(timezone.utc).date().isoformat(),
            "notas": "Lead recibido desde portal Verifika2",
            "created_at": now,
            "updated_at": now,
        }
        ic_keys = [key for key in ic_payload if key in ic_cols]
        conn.execute(
            f"INSERT INTO inmueble_compradores ({', '.join(ic_keys)}) VALUES ({', '.join(['?'] * len(ic_keys))})",
            [ic_payload[key] for key in ic_keys],
        )
    # Persistimos el lead antes de crear acciones auxiliares. En Postgres, si una
    # acción opcional falla, el wrapper hace rollback de la transacción activa.
    conn.commit()
    try:
        conn.execute(
            """
            INSERT INTO acciones (
              id, empresa_id, servicio, cliente_id, inmueble_id, demanda_id, cliente_nombre,
              fecha, hora, tipo, asunto, estado, notas, created_at, updated_at
            ) VALUES (
              ?, ?, 'inmobiliaria', ?, ?, ?, ?, date('now'), '10:00', 'Lead portal',
              ?, 'Pendiente', ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                cliente_id,
                listing_id,
                demanda_id,
                nombre or email or telefono,
                f"Lead portal · {inmueble['direccion'] or inmueble['referencia'] or listing_id}",
                notas or "Contacto recibido desde portal Verifika2",
                now,
                now,
            ),
        )
    except Exception:
        pass
    audit_event(conn, empresa_id, "portal_leads", demanda_id, "Lead portal Verifika2", usuario="Portal", detalles={"inmueble_id": listing_id}, now=now)
    conn.commit()
    return {"ok": True, "listing_id": listing_id, "cliente_id": cliente_id, "demanda_id": demanda_id}, 200


def infer_operacion_estado_documental(payload):
    checks = [
        ("nota de encargo", payload.get("doc_nota_encargo_path")),
        ("propuesta", payload.get("doc_propuesta_path")),
        ("escritura", payload.get("doc_escritura_path")),
        ("nota simple", payload.get("doc_nota_simple_path")),
    ]
    missing = [label for label, value in checks if not str(value or "").strip()]
    return "Completo" if not missing else f"Falta: {', '.join(missing)}"


def iso_month_label(value):
    parsed = parse_iso_date(value)
    if not parsed:
        return ""
    labels = {
        1: "enero",
        2: "febrero",
        3: "marzo",
        4: "abril",
        5: "mayo",
        6: "junio",
        7: "julio",
        8: "agosto",
        9: "septiembre",
        10: "octubre",
        11: "noviembre",
        12: "diciembre",
    }
    return labels.get(parsed.month, "")


def autolink_uploaded_seguros_for_cliente(conn, cliente_id, empresa_id, now):
    if not cliente_id or not empresa_id:
        return {"linked": 0, "docs": 0}
    cliente = conn.execute(
        "SELECT id, nombre FROM clientes WHERE id = ?",
        (cliente_id,),
    ).fetchone()
    if not cliente:
        return {"linked": 0, "docs": 0}
    wanted_tokens = {t for t in normalize_lookup_text(cliente["nombre"] or "").split(" ") if len(t) >= 3}
    if not wanted_tokens:
        return {"linked": 0, "docs": 0}
    rows = conn.execute(
        f"""
        SELECT *
        FROM seguros
        WHERE empresa_id = ?
          AND ({uploaded_policy_filter()})
          AND (
            cliente_id IS NULL OR TRIM(cliente_id) = '' OR cliente_id = ?
          )
          AND tomador IS NOT NULL AND TRIM(tomador) <> ''
        ORDER BY COALESCE(fecha_efecto, created_at) DESC
        """,
        (empresa_id, cliente_id),
    ).fetchall()
    to_link = []
    for row in rows:
        cand_tokens = {t for t in normalize_lookup_text(row["tomador"] or "").split(" ") if len(t) >= 3}
        if not cand_tokens:
            continue
        if wanted_tokens.issubset(cand_tokens):
            to_link.append(row["id"])
            continue
        overlap = len(wanted_tokens.intersection(cand_tokens))
        if overlap >= 2 and (overlap / max(1, len(wanted_tokens))) >= 0.8:
            to_link.append(row["id"])
    linked = 0
    if to_link:
        conn.executemany(
            "UPDATE seguros SET cliente_id = ?, updated_at = datetime(?) WHERE id = ?",
            [(cliente_id, now, sid) for sid in to_link],
        )
        linked = len(to_link)
    docs = 0
    linked_rows = conn.execute(
        f"""
        SELECT *
        FROM seguros
        WHERE empresa_id = ?
          AND cliente_id = ?
          AND ({uploaded_policy_filter()})
        """,
        (empresa_id, cliente_id),
    ).fetchall()
    for row in linked_rows:
        doc_id = ensure_seguro_doc_link(conn, row, now)
        if doc_id:
            docs += 1
    if linked_rows:
        ensure_cliente_servicio_link(conn, cliente_id, empresa_id, "seguros", now)
    return {"linked": linked, "docs": docs}


def ensure_seguro_doc_link(conn, seguro_row, now, calidad_ocr=None, campos_ocr=""):
    if not seguro_row:
        return None
    cliente_id = seguro_row["cliente_id"]
    empresa_id = seguro_row["empresa_id"]
    poliza_key = (seguro_row["poliza_key"] or "").strip()
    poliza_url = (seguro_row["poliza_url"] or "").strip()
    if not cliente_id or not empresa_id or (not poliza_key and not poliza_url):
        return None
    where = [
        "cliente_id = ?",
        "empresa_id = ?",
        "(LOWER(TRIM(COALESCE(referencia_tipo, ''))) = 'seguros' OR LOWER(TRIM(COALESCE(tipo, ''))) = 'seguros')",
    ]
    values = [cliente_id, empresa_id]
    key_or_url = []
    if poliza_key:
        key_or_url.append("doc_key = ?")
        values.append(poliza_key)
    if poliza_url:
        key_or_url.append("doc_url = ?")
        values.append(poliza_url)
    if key_or_url:
        where.append(f"({' OR '.join(key_or_url)})")
    exists = conn.execute(
        f"SELECT id FROM gestoria_docs WHERE {' AND '.join(where)} LIMIT 1",
        values,
    ).fetchone()
    if exists:
        conn.execute(
            """
            UPDATE gestoria_docs
            SET referencia_id = COALESCE(?, referencia_id),
                referencia_tipo = COALESCE(NULLIF(referencia_tipo, ''), 'seguros'),
                nombre = COALESCE(NULLIF(?, ''), nombre),
                tipo = COALESCE(NULLIF(?, ''), tipo),
                fecha = COALESCE(NULLIF(?, ''), fecha),
                estado = COALESCE(NULLIF(?, ''), estado),
                notas = COALESCE(NULLIF(?, ''), notas),
                doc_key = COALESCE(NULLIF(?, ''), doc_key),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                calidad_ocr = COALESCE(NULLIF(?, ''), calidad_ocr),
                campos_ocr = COALESCE(NULLIF(?, ''), campos_ocr),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                seguro_row["id"],
                seguro_row["poliza_numero"] or seguro_row["tomador"] or "Póliza seguro",
                "Seguros",
                seguro_row["fecha_efecto"] or seguro_row["mes_creacion"] or "",
                "Recibido" if (poliza_key or poliza_url) else (seguro_row["estado"] or "En vigor"),
                " · ".join([value for value in (seguro_row["compania"], seguro_row["ramo"]) if value]),
                poliza_key or "",
                poliza_url or "",
                str(calidad_ocr or ""),
                str(campos_ocr or ""),
                now,
                exists["id"],
            ),
        )

        try:
            _maybe_update_seguro_matricula(conn, seguro_row, campos_ocr, now)
        except Exception:
            pass
        return exists["id"]
    # Fallback: si ya existe doc por referencia de la póliza, actualizarlo.
    by_ref = conn.execute(
        """
        SELECT id FROM gestoria_docs
        WHERE (LOWER(TRIM(COALESCE(referencia_tipo, ''))) = 'seguros' OR LOWER(TRIM(COALESCE(tipo, ''))) = 'seguros')
          AND referencia_id = ?
        LIMIT 1
        """,
        (seguro_row["id"],),
    ).fetchone()
    if by_ref:
        conn.execute(
            """
            UPDATE gestoria_docs
            SET cliente_id = ?,
                empresa_id = ?,
                referencia_tipo = COALESCE(NULLIF(referencia_tipo, ''), 'seguros'),
                doc_key = COALESCE(NULLIF(?, ''), doc_key),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                estado = COALESCE(NULLIF(?, ''), estado),
                calidad_ocr = COALESCE(NULLIF(?, ''), calidad_ocr),
                campos_ocr = COALESCE(NULLIF(?, ''), campos_ocr),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                cliente_id,
                empresa_id,
                poliza_key or "",
                poliza_url or "",
                "Recibido" if (poliza_key or poliza_url) else "",
                str(calidad_ocr or ""),
                str(campos_ocr or ""),
                now,
                by_ref["id"],
            ),
        )

        try:
            _maybe_update_seguro_matricula(conn, seguro_row, campos_ocr, now)
        except Exception:
            pass
        return by_ref["id"]
    nombre_doc = seguro_row["poliza_numero"] or seguro_row["tomador"] or "Póliza seguro"
    notas_doc = " · ".join([value for value in (seguro_row["compania"], seguro_row["ramo"]) if value])
    doc_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_docs (
          id, empresa_id, cliente_id, referencia_tipo, referencia_id,
          nombre, tipo, fecha, estado, notas, doc_key, doc_url,
          calidad_ocr, campos_ocr, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            doc_id,
            empresa_id,
            cliente_id,
            "seguros",
            seguro_row["id"],
            nombre_doc,
            "Seguros",
            seguro_row["fecha_efecto"] or seguro_row["mes_creacion"],
            seguro_row["estado"] or "En vigor",
            notas_doc,
            poliza_key or None,
            poliza_url or None,
            calidad_ocr,
            campos_ocr or "",
            now,
            now,
        ),
    )
    return doc_id


def parse_renta_detalles_payload(raw):
    text = str(raw or "").strip()
    if not text:
        return {
            "notes": "",
            "entries": [],
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    try:
        payload = json.loads(text)
    except Exception:
        return {
            "notes": text,
            "entries": [],
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    if isinstance(payload, list):
        return {
            "notes": "",
            "entries": payload,
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    if not isinstance(payload, dict):
        return {
            "notes": "",
            "entries": [],
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    notes = str(payload.get("notes") or "").strip()
    entries = payload.get("entries")
    if not isinstance(entries, list):
        entries = []
    return {
        "notes": notes,
        "entries": entries,
        "related_cliente_id": str(payload.get("related_cliente_id") or "").strip(),
        "related_relation_id": str(payload.get("related_relation_id") or "").strip(),
        "declaracion_conjunta": 1 if str(payload.get("declaracion_conjunta") or "").strip().lower() in {"1", "true", "yes", "si", "sí"} else 0,
    }


def normalize_renta_presentacion_status(value):
    text = normalize_lookup_text(value or "")
    if not text:
        # Si no hay estado explícito, lo tratamos como pendiente de presentación.
        return "Borrador"
    if "BORR" in text:
        return "Borrador"
    if "PRESEN" in text:
        return "Presentada"
    # Fallback conservador: si no se reconoce, lo consideramos pendiente.
    return "Borrador"


def renta_dni_label(entry):
    if not isinstance(entry, dict):
        return "Caducidad DNI"
    if str(entry.get("dni_permanente") or "").strip().lower() in {"1", "true", "yes", "si", "sí"}:
        return "DNI permanente"
    return "Caducidad DNI"


def sort_renta_entries(entries):
    def entry_key(entry):
        if not isinstance(entry, dict):
            return ("", "", "")
        ejercicio = str(entry.get("ejercicio") or "")
        fecha = str(entry.get("presentacion_fecha") or "")
        entry_id = str(entry.get("id") or "")
        return (ejercicio, fecha, entry_id)

    return sorted(
        [entry for entry in entries if isinstance(entry, dict)],
        key=entry_key,
        reverse=True,
    )


RENTA_MAX_REASONABLE_AMOUNT = 1_000_000.0
RENTA_OUTLIER_RATIO = 50.0
RENTA_MAJOR_AMOUNT_FLOOR = 1000.0


def coerce_renta_money(value):
    if value is None:
        return None
    if isinstance(value, str) and not value.strip():
        return None
    number = parse_money_value(value)
    if number is None:
        return None
    return round(number, 2)


def is_reasonable_renta_amount(value, allow_zero=True):
    number = coerce_renta_money(value)
    if number is None:
        return False
    if allow_zero and abs(number) < 0.0001:
        return True
    return abs(number) <= RENTA_MAX_REASONABLE_AMOUNT


def is_renta_amount_outlier(value, reference):
    candidate = coerce_renta_money(value)
    ref = coerce_renta_money(reference)
    if candidate is None or ref is None:
        return False
    if abs(candidate) < 0.0001 or abs(ref) < RENTA_MAJOR_AMOUNT_FLOOR:
        return False
    ratio = max(abs(candidate), abs(ref)) / max(min(abs(candidate), abs(ref)), 0.01)
    return ratio > RENTA_OUTLIER_RATIO and min(abs(candidate), abs(ref)) < RENTA_MAJOR_AMOUNT_FLOOR


def first_reasonable_renta_amount(values, reference=None, allow_zero=True):
    for raw in values:
        number = coerce_renta_money(raw)
        if number is None:
            continue
        if not is_reasonable_renta_amount(number, allow_zero=allow_zero):
            continue
        if reference is not None and is_renta_amount_outlier(number, reference):
            continue
        return number
    return None


def sanitize_renta_entry(entry):
    if not isinstance(entry, dict):
        return {}
    sanitized = dict(entry)
    ejercicio = str(entry.get("ejercicio") or "").strip()
    if not ejercicio:
        ejercicio = str(sanitized.get("ejercicio") or "").strip()
    if not re.match(r"^20[0-9]{2}$", ejercicio or ""):
        entry_id = str(sanitized.get("id") or entry.get("id") or "").strip()
        match = re.match(r"^renta-(20[0-9]{2})-", entry_id)
        if match:
            ejercicio = match.group(1)
    if ejercicio:
        sanitized["ejercicio"] = ejercicio

    # Normaliza fecha de presentación (para cards/listados).
    raw_presentacion = str(
        entry.get("presentacion_fecha")
        or entry.get("fecha_presentacion")
        or entry.get("doc_fecha")
        or entry.get("fecha")
        or entry.get("presentacion")
        or ""
    ).strip()
    presentacion_fecha = ""
    if raw_presentacion:
        # ISO (o ISO datetime)
        match_iso = re.match(r"^(20[0-9]{2}\-[0-9]{2}\-[0-9]{2})", raw_presentacion)
        if match_iso:
            presentacion_fecha = match_iso.group(1)
        else:
            presentacion_fecha = _parse_date_ddmmyyyy_to_iso(raw_presentacion)
    sanitized["presentacion_fecha"] = presentacion_fecha

    raw_work = coerce_renta_money(entry.get("rendimientos_trabajo_total"))
    raw_activities = coerce_renta_money(entry.get("rendimientos_actividades_economicas_total"))
    raw_cap_inm = coerce_renta_money(entry.get("rendimientos_capital_inmobiliario_total"))
    raw_cap_mob = coerce_renta_money(entry.get("rendimientos_capital_mobiliario_total"))
    raw_base_general = coerce_renta_money(entry.get("base_imponible_general"))
    raw_base_liquidable = coerce_renta_money(entry.get("base_liquidable_general"))
    raw_casilla_505 = coerce_renta_money(entry.get("casilla_505"))

    major_reference = first_reasonable_renta_amount(
        [
            raw_casilla_505,
            raw_base_liquidable,
            raw_base_general,
            raw_work,
            raw_activities,
            raw_cap_inm,
            raw_cap_mob,
        ],
        allow_zero=False,
    )

    sanitized["rendimientos_trabajo_total"] = first_reasonable_renta_amount(
        [raw_work],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["rendimientos_actividades_economicas_total"] = first_reasonable_renta_amount(
        [raw_activities],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["rendimientos_capital_inmobiliario_total"] = first_reasonable_renta_amount(
        [raw_cap_inm],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["rendimientos_capital_mobiliario_total"] = first_reasonable_renta_amount(
        [raw_cap_mob],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["base_imponible_general"] = first_reasonable_renta_amount([raw_base_general], allow_zero=True)
    sanitized["base_liquidable_general"] = first_reasonable_renta_amount([raw_base_liquidable], allow_zero=True)

    income_reference = first_reasonable_renta_amount(
        [
            sanitized.get("rendimientos_trabajo_total"),
            sanitized.get("rendimientos_actividades_economicas_total"),
            sanitized.get("rendimientos_capital_inmobiliario_total"),
            sanitized.get("rendimientos_capital_mobiliario_total"),
            sanitized.get("base_liquidable_general"),
            sanitized.get("base_imponible_general"),
            raw_casilla_505,
        ],
        allow_zero=False,
    )

    sanitized["casilla_505"] = first_reasonable_renta_amount(
        [raw_casilla_505, raw_base_liquidable, raw_base_general],
        reference=income_reference,
        allow_zero=True,
    )
    sanitized["resultado_declaracion"] = first_reasonable_renta_amount(
        [entry.get("resultado_declaracion")],
        allow_zero=True,
    )
    sanitized["ingresos_principales_total"] = first_reasonable_renta_amount(
        [
            entry.get("ingresos_principales_total"),
            sanitized.get("rendimientos_trabajo_total"),
            sanitized.get("rendimientos_actividades_economicas_total"),
            sanitized.get("rendimientos_capital_inmobiliario_total"),
            sanitized.get("rendimientos_capital_mobiliario_total"),
            sanitized.get("casilla_505"),
            sanitized.get("base_liquidable_general"),
            sanitized.get("base_imponible_general"),
        ],
        reference=sanitized.get("casilla_505") or major_reference,
        allow_zero=True,
    )
    sanitized["estado_presentacion"] = normalize_renta_presentacion_status(
        entry.get("estado_presentacion") or entry.get("doc_status")
    )
    sanitized["doc_status"] = sanitized["estado_presentacion"]
    sanitized["dni_expedicion"] = str(entry.get("dni_expedicion") or "").strip()
    sanitized["dni_caducidad"] = str(entry.get("dni_caducidad") or "").strip()
    sanitized["dni_permanente"] = 1 if str(entry.get("dni_permanente") or "").strip().lower() in {"1", "true", "yes", "si", "sí"} else 0
    sanitized["dni_label"] = renta_dni_label(sanitized)
    sanitized["pendiente_presentacion"] = 1 if sanitized["estado_presentacion"] == "Borrador" else 0
    # Cobro/estado (regla negocio): Renta ejercicio 2024 se considera cobrada (histórico).
    cobrada_raw = entry.get("cobrada")
    cobrada_val = 1 if str(cobrada_raw or "").strip().lower() in {"1", "true", "yes", "si", "sí", "on"} else 0
    if ejercicio == "2024":
        cobrada_val = 1
    sanitized["cobrada"] = cobrada_val
    sanitized["forma_cobro"] = str(entry.get("forma_cobro") or "").strip()
    remesada_raw = entry.get("remesada")
    remesada_val = 1 if str(remesada_raw or "").strip().lower() in {"1", "true", "yes", "si", "sí", "on"} else 0
    if "REMESA" not in normalize_lookup_text(sanitized["forma_cobro"]):
        remesada_val = 0
    sanitized["remesada"] = remesada_val
    sanitized["precio_servicio"] = coerce_renta_money(entry.get("precio_servicio"))
    sanitized["responsable"] = str(entry.get("responsable") or "").strip()
    sanitized["fecha_cobro"] = str(entry.get("fecha_cobro") or "").strip()
    return sanitized


def sanitize_renta_entries(entries):
    return [sanitize_renta_entry(entry) for entry in entries if isinstance(entry, dict)]


def collect_gestoria_renta_card_items(conn, empresa_id, q="", estado="", limit=50, ejercicio="", *, include_docs=True):
    def renta_ref_id_for_entry(ejercicio: object, entry_id: object) -> str:
        ejercicio_s = str(ejercicio or "").strip()
        entry_s = str(entry_id or "").strip()
        if not entry_s:
            return ""
        # Compat: en algunas versiones `entry.id` ya viene como "renta-YYYY-<...>".
        if entry_s.lower().startswith("renta-"):
            return entry_s
        return f"renta-{ejercicio_s}-{entry_s}" if ejercicio_s else entry_s

    empresa_ids = empresa_id if isinstance(empresa_id, (list, tuple, set)) else [empresa_id]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return []

    q_raw = str(q or "").strip()
    q_lookup = normalize_lookup_text(q_raw)
    estado_norm = normalize_lookup_text(estado or "")
    ejercicio_raw = str(ejercicio or "").strip()
    ejercicio_val = ejercicio_raw if re.match(r"^20[0-9]{2}$", ejercicio_raw or "") else ""
    try:
        limit_val = int(limit)
    except Exception:
        limit_val = 50
    limit_val = max(1, min(limit_val, 200))

    # Protección: no buscamos por 1–2 letras (demasiados resultados y lento).
    if q_lookup and len(q_lookup) < 3:
        return []
    # Note: `estado` filtering normalizes accents/spaces; we keep it in Python for portability
    # and to avoid backend-specific collation issues (SQLite vs Postgres).
    # Prefetch:
    # - sin filtros: solo necesitamos un "top N" reciente, así que evitamos bajar 1200+ filas innecesarias
    # - con `estado`/`ejercicio`: filtramos en Python y necesitamos margen
    # - con búsqueda (`q`): no podemos usar SQL `LIKE` con colación portable (acentos), así que prefetch amplio
    if q_lookup:
        prefetch_limit = min(max(limit_val * 40, 500), 15000)
        order_by = "LOWER(COALESCE(c.nombre, '')) ASC, COALESCE(c.updated_at, c.created_at) DESC"
    elif estado_norm or ejercicio_val:
        prefetch_mult = 12 if include_docs else 6
        prefetch_limit = min(max(limit_val * prefetch_mult, 200), 2500)
        order_by = "COALESCE(c.updated_at, c.created_at) DESC, LOWER(COALESCE(c.nombre, '')) ASC"
    else:
        prefetch_mult = 4 if include_docs else 3
        prefetch_limit = min(max(limit_val * prefetch_mult, 200), 600)
        order_by = "COALESCE(c.updated_at, c.created_at) DESC, LOWER(COALESCE(c.nombre, '')) ASC"
    # Importante: `clientes_empresas.servicio` puede venir como etiqueta libre (p.ej. "Gestoría", "Gestoria - ...",
    # "Administración Fincas", etc.). Usamos un filtro laxo por substring para no dejar el conteo a 0.
    # Nota: `LOWER()` no elimina tildes; "gestoría" sigue conteniendo "gestor", así que `LIKE '%gestor%'` funciona.
    service_filter = gestoria_service_sql_condition("ce")
    service_filter_exists = gestoria_service_sql_condition("ce2")
    placeholders_emp = ",".join(["?"] * len(empresa_ids))
    where = [
        "COALESCE(cg.mod_renta, 0) = 1",
        f"""EXISTS (
            SELECT 1
            FROM clientes_empresas ce
            WHERE ce.empresa_id IN ({placeholders_emp})
              AND ce.cliente_id = c.id
              AND {service_filter}
          )""",
    ]
    values = list(empresa_ids)
    where_clause = " AND ".join(where) if where else "1=1"

    rows = conn.execute(
        f"""
        SELECT
          c.id AS cliente_id,
          c.nombre,
          c.nif,
          c.telefono,
          c.email,
          c.estado AS cliente_estado,
          c.fecha_nacimiento,
          c.poblacion,
          c.provincia,
          cg.tipo_cliente,
          cg.renta_detalles,
          (
            SELECT ce2.estado
            FROM clientes_empresas ce2
            WHERE ce2.empresa_id IN ({placeholders_emp})
              AND ce2.cliente_id = c.id
              AND {service_filter_exists}
            ORDER BY
              CASE
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'activo' THEN 3
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'alta' THEN 2
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'pendiente' THEN 1
                ELSE 0
              END DESC,
              ce2.updated_at DESC
            LIMIT 1
          ) AS servicio_estado
            FROM cliente_gestoria cg
            JOIN clientes c ON c.id = cg.cliente_id
            WHERE {where_clause}
            ORDER BY {order_by}
            LIMIT ?
            """,
            tuple(values + values + [prefetch_limit]),
        ).fetchall()
    items = []
    selected_cliente_ids = []
    renta_doc_id_owner = {}
    renta_ref_owner = {}
    renta_doc_ids_by_cliente = {}
    renta_ref_ids_by_cliente = {}
    # Prefetch responsable desde trabajos de gestoría (por cliente + ejercicio) para
    # campañas importadas que no lo traen en el JSON de `renta_detalles`.
    trabajo_responsable_by_cliente_year = {}
    for row in rows:
        servicio_estado = str(row["servicio_estado"] or row["cliente_estado"] or "").strip()
        if estado_norm and normalize_lookup_text(servicio_estado) != estado_norm:
            continue
        if q_lookup:
            try:
                haystacks = (
                    row["nombre"],
                    row["nif"],
                    row["email"],
                    row["telefono"],
                    row["poblacion"],
                    row["provincia"],
                )
                matched = False
                for value in haystacks:
                    if q_lookup in normalize_lookup_text(value or ""):
                        matched = True
                        break
                if not matched:
                    continue
            except Exception:
                continue
        renta_payload = parse_renta_detalles_payload(row["renta_detalles"])
        entries = sanitize_renta_entries(sort_renta_entries(renta_payload.get("entries") or []))
        if ejercicio_val:
            entries = [e for e in entries if str(e.get("ejercicio") or "").strip() == ejercicio_val]
            if not entries:
                continue
        latest = entries[0] if entries else {}
        try:
            latest_year = str(latest.get("ejercicio") or "").strip()
        except Exception:
            latest_year = ""
        if latest and not str(latest.get("responsable") or "").strip() and latest_year:
            cache_key = f"{row['cliente_id']}::{latest_year}"
            cached = trabajo_responsable_by_cliente_year.get(cache_key)
            if cached is None:
                try:
                    trow = conn.execute(
                        f"""
                        SELECT responsable
                        FROM gestoria_trabajos
                        WHERE empresa_id IN ({placeholders_emp})
                          AND cliente_id = ?
                          AND tipo_trabajo = 'Declaración en periodo'
                          AND COALESCE(notas, '') LIKE ?
                        ORDER BY updated_at DESC, created_at DESC
                        LIMIT 1
                        """,
                        tuple([*empresa_ids, row["cliente_id"], f"%Renta {latest_year}%"]),
                    ).fetchone()
                except Exception:
                    trow = None
                value = str((trow["responsable"] if trow else "") or "").strip()
                trabajo_responsable_by_cliente_year[cache_key] = value
                cached = value
            if cached:
                latest = dict(latest)
                latest["responsable"] = cached
        cliente_id = row["cliente_id"]
        for entry in entries:
            try:
                entry_id = str(entry.get("id") or "").strip()
                ejercicio = str(entry.get("ejercicio") or "").strip()
                ref_id = renta_ref_id_for_entry(ejercicio, entry_id)
                if ref_id:
                    renta_ref_owner[ref_id.lower()] = cliente_id
                    renta_ref_ids_by_cliente.setdefault(cliente_id, set()).add(ref_id.lower())
                for field in ("doc_borrador_id", "doc_presentada_id"):
                    doc_id = str(entry.get(field) or "").strip()
                    if doc_id:
                        renta_doc_id_owner[doc_id] = cliente_id
                        renta_doc_ids_by_cliente.setdefault(cliente_id, set()).add(doc_id)
            except Exception:
                continue
        pending_presentacion = 1 if latest and normalize_renta_presentacion_status(latest.get("estado_presentacion")) == "Borrador" else 0
        items.append(
            {
                "cliente_id": cliente_id,
                "nombre": row["nombre"],
                "nif": row["nif"],
                "telefono": row["telefono"],
                "email": row["email"],
                "fecha_nacimiento": row["fecha_nacimiento"],
                "poblacion": row["poblacion"],
                "provincia": row["provincia"],
                "tipo_cliente": row["tipo_cliente"],
                "estado": servicio_estado or "Alta",
                "renta_notes": renta_payload.get("notes") or "",
                "renta_entries": entries,
                "renta_latest": latest,
                "renta_entry_count": len(entries),
                "renta_pendiente_presentacion": pending_presentacion,
                "docs": [],
                "doc_count": 0,
                "preview_doc": {},
            }
        )
        selected_cliente_ids.append(cliente_id)
        if len(items) >= limit_val:
            break

    if not items:
        return []

    if not include_docs:
        # Dashboard/overview: no cargamos docs (coste alto) y devolvemos solo el estado de renta.
        for item in items:
            try:
                item["docs"] = []
                item["doc_count"] = int(item.get("doc_count") or 0)
                item["preview_doc"] = item.get("preview_doc") or {}
                latest = item.get("renta_latest") or {}
                doc_key = str(latest.get("doc_key") or "").strip()
                doc_url = str(latest.get("doc_url") or "").strip()
                if doc_key or doc_url:
                    ejercicio2 = str(latest.get("ejercicio") or "").strip()
                    entry_id2 = str(latest.get("id") or "").strip()
                    item["doc_count"] = 1
                    item["preview_doc"] = {
                        "id": "",
                        "cliente_id": item.get("cliente_id") or "",
                        "nombre": str(latest.get("doc_nombre") or f"Renta {ejercicio2}.pdf").strip(),
                        "tipo": "Modelo 100",
                        "fecha": str(latest.get("doc_fecha") or ejercicio2).strip(),
                        "estado": "",
                        "notas": "",
                        "doc_key": doc_key,
                        "doc_url": doc_url,
                        "referencia_tipo": "renta",
                        "referencia_id": renta_ref_id_for_entry(ejercicio2, entry_id2),
                        "updated_at": "",
                    }
            except Exception:
                continue
        return items

    # include_docs=True: adjunta documentos de gestoria_docs (renta) y un preview para la última entrada.
    try:
        placeholders_emp_docs = ",".join(["?"] * len(empresa_ids))
        placeholders_cli = ",".join(["?"] * len(selected_cliente_ids))
        docs_rows = conn.execute(
            f"""
            SELECT
              id,
              empresa_id,
              cliente_id,
              referencia_tipo,
              referencia_id,
              nombre,
              tipo,
              fecha,
              estado,
              notas,
              doc_url,
              created_at,
              updated_at
            FROM gestoria_docs
            WHERE empresa_id IN ({placeholders_emp_docs})
              AND cliente_id IN ({placeholders_cli})
              AND LOWER(COALESCE(referencia_tipo, '')) = 'renta'
            ORDER BY COALESCE(fecha, '') DESC, COALESCE(updated_at, created_at) DESC
            """,
            tuple([*empresa_ids, *selected_cliente_ids]),
        ).fetchall()
    except Exception:
        docs_rows = []

    docs_by_cliente: dict[str, list[dict]] = {}
    for row in docs_rows or []:
        try:
            cliente_id = str(row["cliente_id"] or "").strip()
        except Exception:
            cliente_id = ""
        if not cliente_id:
            continue
        try:
            docs_by_cliente.setdefault(cliente_id, []).append(dict(row))
        except Exception:
            try:
                docs_by_cliente.setdefault(cliente_id, []).append(
                    {
                        "id": row_value(row, "id", ""),
                        "empresa_id": row_value(row, "empresa_id", ""),
                        "cliente_id": cliente_id,
                        "referencia_tipo": row_value(row, "referencia_tipo", ""),
                        "referencia_id": row_value(row, "referencia_id", ""),
                        "nombre": row_value(row, "nombre", ""),
                        "tipo": row_value(row, "tipo", ""),
                        "fecha": row_value(row, "fecha", ""),
                        "estado": row_value(row, "estado", ""),
                        "notas": row_value(row, "notas", ""),
                        "doc_url": row_value(row, "doc_url", ""),
                        "created_at": row_value(row, "created_at", ""),
                        "updated_at": row_value(row, "updated_at", ""),
                    }
                )
            except Exception:
                continue

    for item in items:
        try:
            cliente_id = str(item.get("cliente_id") or "").strip()
        except Exception:
            cliente_id = ""
        docs = docs_by_cliente.get(cliente_id, []) if cliente_id else []
        item["docs"] = docs
        item["doc_count"] = int(len(docs))

        preview = {}
        latest = item.get("renta_latest") or {}
        try:
            entry_id = str(latest.get("id") or "").strip()
            year = str(latest.get("ejercicio") or "").strip()
        except Exception:
            entry_id = ""
            year = ""
        candidates = set()
        if entry_id:
            candidates.add(entry_id.lower())
        ref_id = renta_ref_id_for_entry(year, entry_id)
        if ref_id:
            candidates.add(ref_id.lower())
        for doc in docs:
            rid = str(doc.get("referencia_id") or "").strip().lower()
            if rid and (rid in candidates):
                preview = doc
                break
        if not preview and docs:
            preview = docs[0]
        item["preview_doc"] = preview or {}

    return items


def compute_workspace_rrhh_productividad_renta(conn, workspace_id, empresa_id, persona_id, ejercicio=""):
    ejercicio_val = str(ejercicio or "").strip()
    if not re.match(r"^20[0-9]{2}$", ejercicio_val or ""):
        ejercicio_val = ""

    persona = conn.execute(
        """
        SELECT id, nombre, usuario_id
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    if not persona:
        return {"kpis": {}, "items": []}

    usuario_id = str(persona["usuario_id"] or "").strip()
    user = None
    if usuario_id:
        try:
            user = conn.execute(
                "SELECT id, usuario, email, nombre, apellido FROM usuarios WHERE id = ? LIMIT 1",
                (usuario_id,),
            ).fetchone()
        except Exception:
            user = None
    # Fallback: si el trabajador no está vinculado a un `usuarios.id`, intentamos resolverlo por nombre.
    # Motivo: en rentas el campo `responsable` suele almacenar el `usuarios.usuario` (no el nombre completo),
    # y sin el vínculo no podemos atribuir correctamente.
    if not user:
        persona_nombre = str(persona["nombre"] or "").strip()
        if persona_nombre:
            try:
                user = conn.execute(
                    """
                    SELECT id, usuario, email, nombre, apellido
                    FROM usuarios
                    WHERE TRIM(UPPER(COALESCE(nombre,'') || ' ' || COALESCE(apellido,''))) = TRIM(UPPER(?))
                    LIMIT 1
                    """,
                    (persona_nombre,),
                ).fetchone()
            except Exception:
                user = None
        if not user and persona_nombre:
            parts = [p for p in re.split(r"\s+", persona_nombre) if p]
            if len(parts) >= 2:
                first = parts[0]
                last = parts[-1]
                try:
                    user = conn.execute(
                        """
                        SELECT id, usuario, email, nombre, apellido
                        FROM usuarios
                        WHERE UPPER(COALESCE(nombre,'')) LIKE UPPER(?)
                          AND UPPER(COALESCE(apellido,'')) LIKE UPPER(?)
                        ORDER BY COALESCE(updated_at, created_at) DESC
                        LIMIT 1
                        """,
                        (f"{first}%", f"{last}%"),
                    ).fetchone()
                except Exception:
                    user = None

    def add_matcher(out_set, raw):
        key = normalize_lookup_text(raw or "")
        if key:
            out_set.add(key)

    def build_initial_surname_alias(full_name):
        parts = [p for p in re.split(r"\s+", str(full_name or "").strip()) if p]
        if len(parts) < 2:
            return ""
        first = parts[0]
        last = parts[-1]
        if not first or not last:
            return ""
        return f"{first[0]}{last}"

    matchers = set()
    add_matcher(matchers, persona["nombre"])
    # Alias tipo "MPEREZ" (inicial+apellido) para casos donde en rentas guardan el responsable como usuario corto.
    add_matcher(matchers, build_initial_surname_alias(persona["nombre"]))
    if user:
        add_matcher(matchers, user["usuario"])
        add_matcher(matchers, user["email"])
        full_name = f"{user['nombre'] or ''} {user['apellido'] or ''}".strip()
        add_matcher(matchers, full_name)
        add_matcher(matchers, build_initial_surname_alias(full_name))

    # Si no podemos construir matchers, no podemos atribuir productividad automáticamente.
    if not matchers:
        return {"kpis": {}, "items": []}

    # `clientes_empresas.servicio` es texto libre y a menudo incluye sufijos ("Gestoría - ...", "Fincas ...").
    # Usamos un filtro laxo por substring para no dejar la productividad a 0.
    # Nota: `LOWER()` no elimina tildes, pero "gestoría" sigue conteniendo "gestor", así que funciona.
    service_filter = gestoria_service_sql_condition("ce")
    rows = conn.execute(
        f"""
            SELECT
              c.id AS cliente_id,
              c.nombre,
              c.nif,
              cg.renta_detalles,
              COALESCE(
                NULLIF((
                  SELECT ce_link.captado_por_user_id
                  FROM clientes_empresas ce_link
                  WHERE ce_link.empresa_id = ?
                    AND ce_link.cliente_id = c.id
                    AND {service_filter.replace("ce.", "ce_link.")}
                  LIMIT 1
                ), ''),
                COALESCE(c.captado_por_user_id, ''),
                ''
              ) AS captado_por_user_id,
              COALESCE(
                NULLIF((
                  SELECT ce_link2.procedencia_canal
                  FROM clientes_empresas ce_link2
                  WHERE ce_link2.empresa_id = ?
                    AND ce_link2.cliente_id = c.id
                    AND {service_filter.replace("ce.", "ce_link2.")}
                  LIMIT 1
                ), ''),
                COALESCE(c.procedencia_canal, ''),
                ''
              ) AS canal
            FROM cliente_gestoria cg
            JOIN clientes c ON c.id = cg.cliente_id
            WHERE COALESCE(cg.mod_renta, 0) = 1
          AND EXISTS (
            SELECT 1
            FROM clientes_empresas ce
            WHERE ce.empresa_id = ?
              AND ce.cliente_id = c.id
              AND {service_filter}
          )
        """,
        (empresa_id, empresa_id, empresa_id),
    ).fetchall()

    items = []
    presentadas = 0
    cobradas = 0
    facturado_total = 0.0
    comision_total = 0.0
    comision_presentadas = 0.0
    comision_cobradas = 0.0

    for row in rows or []:
        row_dict = dict(row) if not isinstance(row, dict) else row
        captado_por_user_id = str(row_dict.get("captado_por_user_id") or "").strip()
        captado_by_me = bool(usuario_id) and bool(captado_por_user_id) and captado_por_user_id == usuario_id
        renta_payload = parse_renta_detalles_payload(row_dict.get("renta_detalles"))
        entries = sanitize_renta_entries(sort_renta_entries(renta_payload.get("entries") or []))
        if ejercicio_val:
            entries = [e for e in entries if str(e.get("ejercicio") or "").strip() == ejercicio_val]
        for entry in entries:
            if not captado_by_me:
                responsable = normalize_lookup_text(entry.get("responsable") or "")
                if not responsable or responsable not in matchers:
                    continue
            estado = normalize_renta_presentacion_status(
                entry.get("estado_presentacion") or entry.get("doc_status") or ""
            )
            is_presentada = estado == "Presentada"
            is_cobrada = int(entry.get("cobrada") or 0) == 1

            precio = parse_money_value(entry.get("precio_servicio"))
            iva_pct = entry.get("iva_pct")
            try:
                iva_pct_val = float(iva_pct) if iva_pct is not None and str(iva_pct).strip() != "" else 21.0
            except Exception:
                iva_pct_val = 21.0
            denom = 1.0 + (iva_pct_val / 100.0 if iva_pct_val else 0.0)
            base_imponible = precio / denom if denom else precio
            comision = base_imponible * 0.30
            facturado_total += base_imponible
            comision_total += comision
            if is_presentada:
                presentadas += 1
                comision_presentadas += comision
            if is_cobrada:
                cobradas += 1
                comision_cobradas += comision
            items.append(
                {
                    "cliente_id": row_dict.get("cliente_id"),
                    "cliente_nombre": row_dict.get("nombre"),
                    "cliente_nif": row_dict.get("nif"),
                    "ejercicio": str(entry.get("ejercicio") or "").strip(),
                    "estado_presentacion": estado or "-",
                    "presentacion_fecha": str(
                        entry.get("presentacion_fecha")
                        or entry.get("fecha_presentacion")
                        or entry.get("doc_fecha")
                        or ""
                    ).strip(),
                    "cobrada": 1 if is_cobrada else 0,
                    "precio_servicio": round(precio, 2),
                    "base_imponible": round(base_imponible, 2),
                    "comision": round(comision, 2),
                    "canal": str(row_dict.get("canal") or "").strip(),
                    "responsable": str(entry.get("responsable") or "").strip(),
                }
            )

    # Orden: más reciente primero (si hay fecha); fallback por ejercicio.
    try:
        items.sort(
            key=lambda it: (
                parse_date_to_timestamp(it.get("presentacion_fecha") or "") or 0,
                int(str(it.get("ejercicio") or "0")[:4] or "0"),
            ),
            reverse=True,
        )
    except Exception:
        pass

    return {
        "kpis": {
            "presentadas": int(presentadas),
            "cobradas": int(cobradas),
            "facturado_total": round(facturado_total, 2),
            "comision_total": round(comision_total, 2),
            "comision_presentadas": round(comision_presentadas, 2),
            "comision_cobradas": round(comision_cobradas, 2),
        },
        "items": items,
    }


def compute_workspace_rrhh_productividad_seguros(conn, workspace_id, empresa_id, persona_id, ejercicio=""):
    ejercicio_val = str(ejercicio or "").strip()
    if not re.match(r"^20[0-9]{2}$", ejercicio_val or ""):
        ejercicio_val = ""

    persona = conn.execute(
        """
        SELECT id, nombre, usuario_id
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    if not persona:
        return {"kpis": {}, "items": []}

    usuario_id = str(persona["usuario_id"] or "").strip()
    user = None
    if usuario_id:
        try:
            user = conn.execute(
                "SELECT id, usuario, email, nombre, apellido FROM usuarios WHERE id = ? LIMIT 1",
                (usuario_id,),
            ).fetchone()
        except Exception:
            user = None

    def add_matcher(out_set, raw):
        key = normalize_lookup_text(raw or "")
        if key:
            out_set.add(key)

    matchers = set()
    add_matcher(matchers, persona["nombre"])
    if user:
        add_matcher(matchers, user["usuario"])
        add_matcher(matchers, user["email"])
        full_name = f"{user['nombre'] or ''} {user['apellido'] or ''}".strip()
        add_matcher(matchers, full_name)
    if not matchers:
        return {"kpis": {}, "items": []}

    fecha_efecto_date = seguro_date_sql("fecha_efecto", "s")
    year_expr = f"COALESCE(STRFTIME('%Y', {fecha_efecto_date}), STRFTIME('%Y', s.created_at))"
    where = ["s.empresa_id = ?"]
    values = [empresa_id]
    if ejercicio_val:
        where.append(f"{year_expr} = ?")
        values.append(ejercicio_val)

    rows = conn.execute(
        f"""
        SELECT
          s.id,
          s.cliente_id,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(s.compania, '') AS compania,
          COALESCE(s.ramo, '') AS ramo,
          COALESCE(s.poliza_numero, '') AS poliza_numero,
          COALESCE(s.produccion, '') AS responsable,
          COALESCE(s.estado_poliza, s.estado, '') AS estado,
              s.comision,
              s.prima_total,
                  COALESCE(s.fecha_efecto, '') AS fecha_efecto,
                  COALESCE(s.fecha_vencimiento, '') AS fecha_vencimiento,
                  COALESCE(ce.captado_por_user_id, c.captado_por_user_id, '') AS captado_por_user_id,
                  COALESCE(ce.procedencia_canal, c.procedencia_canal, '') AS canal
                FROM seguros s
                LEFT JOIN clientes c ON c.id = s.cliente_id
                LEFT JOIN clientes_empresas ce
              ON ce.cliente_id = s.cliente_id
             AND ce.empresa_id = s.empresa_id
             AND LOWER(COALESCE(ce.servicio, '')) LIKE '%seguro%'
            WHERE {' AND '.join(where)}
        """,
        values,
    ).fetchall()

    items = []
    count_total = 0
    count_cobradas = 0
    comision_total = 0.0
    comision_cobradas = 0.0

    for row in rows or []:
        row_dict = dict(row) if not isinstance(row, dict) else row
        captado_por_user_id = str(row_dict.get("captado_por_user_id") or "").strip()
        captado_by_me = bool(usuario_id) and bool(captado_por_user_id) and captado_por_user_id == usuario_id
        if not captado_by_me:
            if usuario_id and captado_por_user_id:
                continue
            responsable = normalize_lookup_text(row_dict.get("responsable") or "")
            if not responsable or responsable not in matchers:
                continue
        comision_cobrada = parse_money_value(row_dict.get("comision"))
        if comision_cobrada <= 0:
            continue
        # En seguros tratamos la comision como "cobrada" si la póliza no está de baja/cancelada.
        try:
            bucket = seguro_estado_bucket_value(row_dict)
        except Exception:
            bucket = ""
        # Tratamos como "cobrada" si la póliza está en vigor/contratada (heurística).
        is_cobrada = str(bucket or "").strip().lower() in {"en_vigor", "contratada"}
        comision_trabajador = comision_cobrada * 0.10
        count_total += 1
        comision_total += comision_trabajador
        if is_cobrada:
            count_cobradas += 1
            comision_cobradas += comision_trabajador
        items.append(
            {
                "service": "seguros",
                "ref_id": row_dict.get("id"),
                "cliente_id": row_dict.get("cliente_id"),
                "cliente_nombre": row_dict.get("cliente_nombre"),
                "cliente_nif": row_dict.get("cliente_nif"),
                "compania": row_dict.get("compania"),
                "ramo": row_dict.get("ramo"),
                "poliza_numero": row_dict.get("poliza_numero"),
                "fecha": str(row_dict.get("fecha_efecto") or "").strip()
                or str(row_dict.get("fecha_vencimiento") or "").strip(),
                "estado": str(row_dict.get("estado") or "").strip() or "-",
                    "cobrada": 1 if is_cobrada else 0,
                    "comision_cobrada": round(comision_cobrada, 2),
                    "comision": round(comision_trabajador, 2),
                    "canal": str(row_dict.get("canal") or "").strip(),
                    "responsable": str(row_dict.get("responsable") or "").strip(),
                }
            )

    try:
        items.sort(key=lambda it: (parse_date_to_timestamp(it.get("fecha") or "") or 0), reverse=True)
    except Exception:
        pass

    return {
        "kpis": {
            "items": int(count_total),
            "cobradas": int(count_cobradas),
            "comision_total": round(comision_total, 2),
            "comision_cobradas": round(comision_cobradas, 2),
        },
        "items": items,
    }


def compute_workspace_rrhh_productividad_hipotecas(conn, workspace_id, empresa_id, persona_id, ejercicio=""):
    ejercicio_val = str(ejercicio or "").strip()
    if not re.match(r"^20[0-9]{2}$", ejercicio_val or ""):
        ejercicio_val = ""

    persona = conn.execute(
        """
        SELECT id, nombre, usuario_id
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    if not persona:
        return {"kpis": {}, "items": []}

    usuario_id = str(persona["usuario_id"] or "").strip()
    user = None
    if usuario_id:
        try:
            user = conn.execute(
                "SELECT id, usuario, email, nombre, apellido FROM usuarios WHERE id = ? LIMIT 1",
                (usuario_id,),
            ).fetchone()
        except Exception:
            user = None

    def add_matcher(out_set, raw):
        key = normalize_lookup_text(raw or "")
        if key:
            out_set.add(key)

    matchers = set()
    add_matcher(matchers, persona["nombre"])
    if user:
        add_matcher(matchers, user["usuario"])
        add_matcher(matchers, user["email"])
        full_name = f"{user['nombre'] or ''} {user['apellido'] or ''}".strip()
        add_matcher(matchers, full_name)
    if not matchers:
        return {"kpis": {}, "items": []}

    where = ["h.empresa_id = ?"]
    values = [empresa_id]
    if ejercicio_val:
        where.append("COALESCE(CAST(h.anio AS TEXT), SUBSTR(NULLIF(h.fecha_firma,''),1,4), '') = ?")
        values.append(ejercicio_val)

    rows = conn.execute(
        f"""
        SELECT
          h.id,
          h.cliente_id,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(h.banco, '') AS banco,
          COALESCE(h.oficina, '') AS oficina,
          COALESCE(h.inmobiliaria_compra, '') AS inmobiliaria_compra,
          COALESCE(h.asesor, '') AS responsable,
          COALESCE(h.estado, '') AS estado,
          COALESCE(h.fecha_firma, '') AS fecha_firma,
                  h.comision_modernia,
                  h.comision,
                  h.cesion,
                  h.comision_juan,
                  COALESCE(ce.captado_por_user_id, c.captado_por_user_id, '') AS captado_por_user_id,
                  COALESCE(ce.procedencia_canal, c.procedencia_canal, '') AS canal
                FROM hipotecas h
                LEFT JOIN clientes c ON c.id = h.cliente_id
                LEFT JOIN clientes_empresas ce
              ON ce.cliente_id = h.cliente_id
             AND ce.empresa_id = h.empresa_id
             AND (
               LOWER(COALESCE(ce.servicio, '')) LIKE '%hipotec%'
               OR LOWER(COALESCE(ce.servicio, '')) LIKE '%financ%'
             )
            WHERE {' AND '.join(where)}
            """,
            values,
        ).fetchall()

    items = []
    count_total = 0
    count_cobradas = 0
    comision_total = 0.0
    comision_cobradas = 0.0

    for row in rows or []:
        row_dict = dict(row) if not isinstance(row, dict) else row
        captado_por_user_id = str(row_dict.get("captado_por_user_id") or "").strip()
        captado_by_me = bool(usuario_id) and bool(captado_por_user_id) and captado_por_user_id == usuario_id
        if not captado_by_me:
            if usuario_id and captado_por_user_id:
                continue
            responsable = normalize_lookup_text(row_dict.get("responsable") or "")
            if not responsable or responsable not in matchers:
                continue
        # "Nos deja 700€" -> usamos comision_modernia si existe; si no comision.
        comision_cobrada = parse_money_value(row_dict.get("comision_modernia"))
        if comision_cobrada <= 0:
            comision_cobrada = parse_money_value(row_dict.get("comision"))
        if comision_cobrada <= 0:
            continue
        estado_norm = normalize_lookup_text(row_dict.get("estado") or "")
        is_cobrada = "FIRM" in estado_norm or str(row_dict.get("fecha_firma") or "").strip() != ""
        comision_trabajador = comision_cobrada * 0.10
        count_total += 1
        comision_total += comision_trabajador
        if is_cobrada:
            count_cobradas += 1
            comision_cobradas += comision_trabajador
        items.append(
            {
                "service": "hipotecas",
                "ref_id": row_dict.get("id"),
                "cliente_id": row_dict.get("cliente_id"),
                "cliente_nombre": row_dict.get("cliente_nombre"),
                "cliente_nif": row_dict.get("cliente_nif"),
                "banco": row_dict.get("banco"),
                "oficina": row_dict.get("oficina"),
                "inmobiliaria_compra": row_dict.get("inmobiliaria_compra"),
                "fecha": str(row_dict.get("fecha_firma") or "").strip(),
                "estado": str(row_dict.get("estado") or "").strip() or "-",
                    "cobrada": 1 if is_cobrada else 0,
                    "comision_cobrada": round(comision_cobrada, 2),
                    "comision": round(comision_trabajador, 2),
                    "canal": str(row_dict.get("canal") or "").strip(),
                    "responsable": str(row_dict.get("responsable") or "").strip(),
                }
            )

    try:
        items.sort(key=lambda it: (parse_date_to_timestamp(it.get("fecha") or "") or 0), reverse=True)
    except Exception:
        pass

    return {
        "kpis": {
            "items": int(count_total),
            "cobradas": int(count_cobradas),
            "comision_total": round(comision_total, 2),
            "comision_cobradas": round(comision_cobradas, 2),
        },
        "items": items,
    }


def compute_workspace_rrhh_productividad_facturacion_anual(conn, workspace_id, empresa_id, persona_id, *, servicio_keys, ejercicio=""):
    ejercicio_val = str(ejercicio or "").strip()
    if not re.match(r"^20[0-9]{2}$", ejercicio_val or ""):
        ejercicio_val = ""

    persona = conn.execute(
        """
        SELECT id, nombre, usuario_id
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    if not persona:
        return {"kpis": {}, "items": []}

    usuario_id = str(persona["usuario_id"] or "").strip()
    user = None
    if usuario_id:
        try:
            user = conn.execute(
                "SELECT id, usuario, email, nombre, apellido FROM usuarios WHERE id = ? LIMIT 1",
                (usuario_id,),
            ).fetchone()
        except Exception:
            user = None

    def add_matcher(out_set, raw):
        key = normalize_lookup_text(raw or "")
        if key:
            out_set.add(key)

    matchers = set()
    add_matcher(matchers, persona["nombre"])
    if user:
        add_matcher(matchers, user["usuario"])
        add_matcher(matchers, user["email"])
        full_name = f"{user['nombre'] or ''} {user['apellido'] or ''}".strip()
        add_matcher(matchers, full_name)
    if not matchers:
        return {"kpis": {}, "items": []}

        keys = [str(k or "").strip().lower() for k in (servicio_keys or []) if str(k or "").strip()]
        # Dedup para reducir placeholders y joins.
        try:
            keys = list(dict.fromkeys(keys))
        except Exception:
            pass
        if not keys:
            return {"kpis": {}, "items": []}
        placeholders = ",".join(["?"] * len(keys))

        where = ["f.workspace_id = ?", "f.empresa_id = ?", f"LOWER(TRIM(COALESCE(f.servicio,''))) IN ({placeholders})"]
        values = [workspace_id, empresa_id, *keys]
    if ejercicio_val:
        where.append("SUBSTR(NULLIF(f.fecha_emision,''), 1, 4) = ?")
        values.append(ejercicio_val)

        rows = conn.execute(
            f"""
            SELECT
              f.cliente_id,
                  COALESCE(c.nombre, '') AS cliente_nombre,
                  COALESCE(c.nif, '') AS cliente_nif,
                  COALESCE(f.responsable, '') AS responsable,
                  COALESCE(ce.captado_por_user_id, c.captado_por_user_id, '') AS captado_por_user_id,
                  MAX(COALESCE(ce.procedencia_canal, c.procedencia_canal, '')) AS canal,
                  SUM(COALESCE(f.subtotal, 0)) AS total_facturado,
                  MIN(COALESCE(f.fecha_emision,'')) AS first_fecha,
                  MAX(COALESCE(f.fecha_emision,'')) AS last_fecha,
              COUNT(*) AS num_facturas,
              SUM(CASE WHEN COALESCE(f.cobrada, 0) = 1 THEN 1 ELSE 0 END) AS num_cobradas
            FROM workspace_facturacion f
            LEFT JOIN clientes c ON c.id = f.cliente_id
            LEFT JOIN clientes_empresas ce
              ON ce.cliente_id = f.cliente_id
             AND ce.empresa_id = f.empresa_id
             AND LOWER(TRIM(COALESCE(ce.servicio,''))) IN ({placeholders})
            WHERE {' AND '.join(where)}
              AND COALESCE(f.cliente_id,'') != ''
            GROUP BY f.cliente_id, COALESCE(f.responsable,''), COALESCE(ce.captado_por_user_id, c.captado_por_user_id, '')
            """,
            values + keys,
        ).fetchall()

    items = []
    clientes = 0
    facturado_total = 0.0
    comision_total = 0.0

    for row in rows or []:
        row_dict = dict(row) if not isinstance(row, dict) else row
        captado_por_user_id = str(row_dict.get("captado_por_user_id") or "").strip()
        captado_by_me = bool(usuario_id) and bool(captado_por_user_id) and captado_por_user_id == usuario_id
        if not captado_by_me:
            if usuario_id and captado_por_user_id:
                continue
            responsable = normalize_lookup_text(row_dict.get("responsable") or "")
            if not responsable or responsable not in matchers:
                continue
        total_facturado = parse_money_value(row_dict.get("total_facturado"))
        if total_facturado <= 0:
            continue
        num_facturas = int(row_dict.get("num_facturas") or 0)
        num_cobradas = int(row_dict.get("num_cobradas") or 0)
        pendientes = max(0, num_facturas - num_cobradas)
        is_cobrada = num_facturas > 0 and pendientes == 0
        comision = total_facturado * 0.10
        clientes += 1
        facturado_total += total_facturado
        comision_total += comision
        items.append(
            {
                "service": "facturacion",
                "cliente_id": row_dict.get("cliente_id"),
                "cliente_nombre": row_dict.get("cliente_nombre"),
                "cliente_nif": row_dict.get("cliente_nif"),
                "fecha": str(row_dict.get("last_fecha") or row_dict.get("first_fecha") or "").strip(),
                "facturado_anual": round(total_facturado, 2),
                "comision": round(comision, 2),
                "num_facturas": num_facturas,
                "num_cobradas": num_cobradas,
                "pendientes": pendientes,
                "cobrada": 1 if is_cobrada else 0,
                "canal": str(row_dict.get("canal") or "").strip(),
                "responsable": str(row_dict.get("responsable") or "").strip(),
            }
        )

    try:
        items.sort(key=lambda it: (parse_money_value(it.get("facturado_anual"))), reverse=True)
    except Exception:
        pass

    return {
        "kpis": {
            "clientes": int(clientes),
            "facturado_total": round(facturado_total, 2),
            "comision_total": round(comision_total, 2),
        },
        "items": items,
    }


def compute_workspace_rrhh_productividad(conn, workspace_id, empresa_id, persona_id, servicio, ejercicio=""):
    service_key = normalize_lookup_text(servicio or "")
    if service_key in {"renta", "rentas"}:
        return compute_workspace_rrhh_productividad_renta(conn, workspace_id, empresa_id, persona_id, ejercicio=ejercicio)
    if service_key in {"seguro", "seguros"}:
        return compute_workspace_rrhh_productividad_seguros(conn, workspace_id, empresa_id, persona_id, ejercicio=ejercicio)
    if service_key in {"hipoteca", "hipotecas", "financiacion", "financiaciones"}:
        return compute_workspace_rrhh_productividad_hipotecas(conn, workspace_id, empresa_id, persona_id, ejercicio=ejercicio)
    if service_key in {"gestoria", "gestoría"}:
        return compute_workspace_rrhh_productividad_facturacion_anual(
            conn,
            workspace_id,
            empresa_id,
            persona_id,
            servicio_keys={"gestoria", "gestoría"},
            ejercicio=ejercicio,
        )
    if service_key in {"fincas", "administracion fincas", "administración fincas"}:
        return compute_workspace_rrhh_productividad_facturacion_anual(
            conn,
            workspace_id,
            empresa_id,
            persona_id,
            servicio_keys={"administracion fincas", "administración fincas"},
            ejercicio=ejercicio,
        )
    return {"kpis": {}, "items": []}


def fetch_workspace_rrhh_productividad_manual(conn, workspace_id, persona_id, *, service="", ejercicio=""):
    service_key = str(service or "").strip().lower()
    ejercicio_val = str(ejercicio or "").strip()
    if ejercicio_val and not re.match(r"^20[0-9]{2}$", ejercicio_val):
        ejercicio_val = ""
    rows = []
    try:
        sql = """
          SELECT
            id,
            service,
            ejercicio,
            cliente_nombre,
            cliente_nif,
            descripcion,
            importe_base,
            comision_pct,
            comision,
            cobrada,
            estado_cobro,
            importe_cobrado,
            fecha,
            fecha_cobro,
            justificante_key,
            justificante_url,
            created_at,
            updated_at
          FROM workspace_rrhh_productividad_manual
          WHERE workspace_id = ?
            AND persona_id = ?
        """
        args = [str(workspace_id or "").strip(), str(persona_id or "").strip()]
        if service_key:
            sql += " AND LOWER(COALESCE(service,'')) = ?"
            args.append(service_key)
        if ejercicio_val:
            sql += " AND CAST(COALESCE(ejercicio, 0) AS TEXT) = ?"
            args.append(ejercicio_val)
        sql += " ORDER BY COALESCE(fecha, '') DESC, updated_at DESC"
        rows = conn.execute(sql, tuple(args)).fetchall()
    except Exception:
        rows = []

    items = []
    for row in rows or []:
        d = dict(row)
        try:
            d["service"] = str(d.get("service") or "").strip().lower()
            d["ejercicio"] = str(d.get("ejercicio") or "").strip()
            d["cliente_nombre"] = str(d.get("cliente_nombre") or "").strip()
            d["cliente_nif"] = str(d.get("cliente_nif") or "").strip()
            d["descripcion"] = str(d.get("descripcion") or "").strip()
            d["importe_base"] = float(d.get("importe_base") or 0)
            d["comision_pct"] = float(d.get("comision_pct") or 0)
            d["comision"] = float(d.get("comision") or 0)
            d["cobrada"] = 1 if int(d.get("cobrada") or 0) == 1 else 0
            d["estado_cobro"] = str(d.get("estado_cobro") or "").strip().lower()
            d["importe_cobrado"] = float(d.get("importe_cobrado") or 0)
            d["fecha"] = str(d.get("fecha") or "").strip()
            d["fecha_cobro"] = str(d.get("fecha_cobro") or "").strip()
            d["justificante_key"] = str(d.get("justificante_key") or "").strip()
            d["justificante_url"] = str(d.get("justificante_url") or "").strip()
        except Exception:
            pass
        d["source"] = "manual"
        items.append(d)
    return items


def upsert_workspace_rrhh_productividad_manual(conn, workspace_id, persona_id, payload, *, actor_user_id=""):
    workspace_id = str(workspace_id or "").strip()
    persona_id = str(persona_id or "").strip()
    if not workspace_id or not persona_id:
        raise ValueError("workspace_id y persona_id requeridos")

    raw = payload or {}
    entry_id = str(raw.get("id") or "").strip()
    service_key = str(raw.get("service") or "").strip().lower()
    ejercicio_val = str(raw.get("ejercicio") or "").strip()
    if ejercicio_val and not re.match(r"^20[0-9]{2}$", ejercicio_val):
        raise ValueError("ejercicio inválido")
    if not service_key:
        raise ValueError("service requerido")

    cliente_nombre = str(raw.get("cliente_nombre") or "").strip()
    cliente_nif = str(raw.get("cliente_nif") or "").strip()
    descripcion = str(raw.get("descripcion") or "").strip()
    fecha = str(raw.get("fecha") or "").strip()
    cobrada_raw = 1 if str(raw.get("cobrada") or "").strip() in {"1", "true", "True"} else 0
    estado_cobro = str(raw.get("estado_cobro") or "").strip().lower()
    fecha_cobro = str(raw.get("fecha_cobro") or "").strip()
    justificante_key = str(raw.get("justificante_key") or "").strip()
    justificante_url = str(raw.get("justificante_url") or "").strip()
    try:
        importe_base = float(raw.get("importe_base") or 0)
    except Exception:
        importe_base = 0.0
    try:
        comision_pct = float(raw.get("comision_pct") or 0)
    except Exception:
        comision_pct = 0.0
    try:
        comision = float(raw.get("comision") or 0)
    except Exception:
        comision = 0.0
    if comision <= 0 and importe_base > 0 and comision_pct > 0:
        comision = round((importe_base * comision_pct) / 100.0, 2)

    try:
        importe_cobrado = float(raw.get("importe_cobrado") or 0)
    except Exception:
        importe_cobrado = 0.0

    if estado_cobro not in {"pendiente", "parcial", "cobrado", "anulado", ""}:
        raise ValueError("estado_cobro inválido")
    if not estado_cobro:
        if cobrada_raw == 1:
            estado_cobro = "cobrado"
        elif importe_cobrado and importe_cobrado > 0:
            estado_cobro = "parcial"
        else:
            estado_cobro = "pendiente"
    if estado_cobro == "cobrado":
        cobrada = 1
        if importe_cobrado <= 0:
            importe_cobrado = float(comision or 0)
    else:
        cobrada = 0
        if estado_cobro == "pendiente":
            importe_cobrado = 0.0

    now = datetime.utcnow().isoformat()
    if not entry_id:
        entry_id = uuid.uuid4().hex
        conn.execute(
            """
            INSERT INTO workspace_rrhh_productividad_manual
              (id, workspace_id, persona_id, service, ejercicio, cliente_nombre, cliente_nif, descripcion,
               importe_base, comision_pct, comision, cobrada, estado_cobro, importe_cobrado, fecha, fecha_cobro,
               justificante_key, justificante_url, created_at, updated_at, created_by)
            VALUES
              (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                entry_id,
                workspace_id,
                persona_id,
                service_key,
                int(ejercicio_val) if ejercicio_val else 0,
                cliente_nombre,
                cliente_nif,
                descripcion,
                float(importe_base or 0),
                float(comision_pct or 0),
                float(comision or 0),
                int(cobrada or 0),
                estado_cobro,
                float(importe_cobrado or 0),
                fecha,
                fecha_cobro,
                justificante_key,
                justificante_url,
                now,
                now,
                str(actor_user_id or "").strip(),
            ),
        )
        return {"ok": True, "id": entry_id}

    conn.execute(
        """
        UPDATE workspace_rrhh_productividad_manual
        SET service = ?,
            ejercicio = ?,
            cliente_nombre = ?,
            cliente_nif = ?,
            descripcion = ?,
            importe_base = ?,
            comision_pct = ?,
            comision = ?,
            cobrada = ?,
            estado_cobro = ?,
            importe_cobrado = ?,
            fecha = ?,
            fecha_cobro = ?,
            justificante_key = ?,
            justificante_url = ?,
            updated_at = ?
        WHERE workspace_id = ? AND persona_id = ? AND id = ?
        """,
        (
            service_key,
            int(ejercicio_val) if ejercicio_val else 0,
            cliente_nombre,
            cliente_nif,
            descripcion,
            float(importe_base or 0),
            float(comision_pct or 0),
            float(comision or 0),
            int(cobrada or 0),
            estado_cobro,
            float(importe_cobrado or 0),
            fecha,
            fecha_cobro,
            justificante_key,
            justificante_url,
            now,
            workspace_id,
            persona_id,
            entry_id,
        ),
    )
    return {"ok": True, "id": entry_id}


def bulk_update_workspace_rrhh_productividad_manual(conn, workspace_id, persona_id, entry_ids, patch, *, actor_user_id=""):
    workspace_id = str(workspace_id or "").strip()
    persona_id = str(persona_id or "").strip()
    if not workspace_id or not persona_id:
        raise ValueError("workspace_id y persona_id requeridos")
    ids = [str(x or "").strip() for x in (entry_ids or []) if str(x or "").strip()]
    if not ids:
        raise ValueError("ids requeridos")
    p = patch or {}
    estado_cobro = str(p.get("estado_cobro") or "").strip().lower()
    fecha_cobro = str(p.get("fecha_cobro") or "").strip()
    try:
        importe_cobrado = float(p.get("importe_cobrado") or 0)
    except Exception:
        importe_cobrado = 0.0
    if estado_cobro not in {"pendiente", "parcial", "cobrado", "anulado"}:
        raise ValueError("estado_cobro inválido")
    cobrada = 1 if estado_cobro == "cobrado" else 0
    now = datetime.utcnow().isoformat()
    placeholders = ",".join(["?"] * len(ids))
    # Para "cobrado" con importe_cobrado vacío/0, usamos la comisión calculada de cada fila.
    # Para "pendiente", forzamos importe_cobrado a 0.
    # Para "parcial"/"anulado", mantenemos el existente salvo que venga uno explícito.
    importe_mode = "keep"
    if estado_cobro == "cobrado":
        importe_mode = "auto"
    elif estado_cobro == "pendiente":
        importe_mode = "zero"
    conn.execute(
        f"""
        UPDATE workspace_rrhh_productividad_manual
        SET cobrada = ?,
            estado_cobro = ?,
            importe_cobrado = CASE
              WHEN ? = 'zero' THEN 0
              WHEN ? = 'auto' AND (? <= 0) THEN COALESCE(comision, 0)
              WHEN ? = 'keep' AND (? <= 0) THEN COALESCE(importe_cobrado, 0)
              ELSE ?
            END,
            fecha_cobro = ?,
            updated_at = ?,
            created_by = COALESCE(NULLIF(TRIM(COALESCE(created_by,'')), ''), ?)
        WHERE workspace_id = ?
          AND persona_id = ?
          AND id IN ({placeholders})
        """,
        tuple(
            [
                cobrada,
                estado_cobro,
                importe_mode,
                importe_mode,
                float(importe_cobrado or 0),
                importe_mode,
                float(importe_cobrado or 0),
                float(importe_cobrado or 0),
                float(importe_cobrado or 0),
                fecha_cobro,
                now,
                str(actor_user_id or "").strip(),
                workspace_id,
                persona_id,
            ]
            + ids
        ),
    )
    return {"ok": True, "updated": len(ids)}


def fetch_workspace_rrhh_nominas(conn, workspace_id, persona_id, *, year=0, month=0, limit=120):
    workspace_id = str(workspace_id or "").strip()
    persona_id = str(persona_id or "").strip()
    year_i = int(year or 0) if str(year or "").strip() else 0
    month_i = int(month or 0) if str(month or "").strip() else 0
    limit_i = max(1, min(int(limit or 120), 400))
    params = [workspace_id, persona_id]
    where = "workspace_id = ? AND persona_id = ?"
    if year_i > 0:
        where += " AND year = ?"
        params.append(year_i)
    if month_i > 0:
        where += " AND month = ?"
        params.append(month_i)
    rows = conn.execute(
        f"""
        SELECT
          id, workspace_id, empresa_id, persona_id, year, month,
          empleado_nombre, empleado_nif,
          bruto, neto, irpf_pct, ss_trabajador, ss_empresa,
          doc_key, doc_url,
          ocr_status, ocr_confidence,
          created_by, created_at, updated_at
        FROM workspace_rrhh_nominas
        WHERE {where}
        ORDER BY year DESC, month DESC, created_at DESC
        LIMIT {limit_i}
        """,
        tuple(params),
    ).fetchall()
    return [dict(r) for r in (rows or [])]


def upsert_workspace_rrhh_nomina(conn, workspace_id, persona_id, payload, *, actor_user_id="", now=""):
    workspace_id = str(workspace_id or "").strip()
    persona_id = str(persona_id or "").strip()
    if not workspace_id or not persona_id:
        raise ValueError("workspace_id y persona_id requeridos")
    now = now or datetime.now(timezone.utc).isoformat()
    rec_id = str(payload.get("id") or "").strip()
    empresa_id = str(payload.get("empresa_id") or "").strip() or None
    year_i = int(payload.get("year") or payload.get("ejercicio") or 0) if str(payload.get("year") or payload.get("ejercicio") or "").strip() else 0
    month_i = int(payload.get("month") or payload.get("mes") or 0) if str(payload.get("month") or payload.get("mes") or "").strip() else 0
    empleado_nombre = str(payload.get("empleado_nombre") or payload.get("nombre") or "").strip() or None
    empleado_nif = normalize_nif(payload.get("empleado_nif") or payload.get("nif") or payload.get("dni") or "") or None
    bruto = round(parse_money_value(payload.get("bruto") or 0), 2)
    neto = round(parse_money_value(payload.get("neto") or 0), 2)
    irpf_pct = round(parse_money_value(payload.get("irpf_pct") or payload.get("irpf") or 0), 4)
    ss_trabajador = round(parse_money_value(payload.get("ss_trabajador") or payload.get("seg_social_trabajador") or 0), 2)
    ss_empresa = round(parse_money_value(payload.get("ss_empresa") or payload.get("seg_social_empresa") or 0), 2)
    doc_key = str(payload.get("doc_key") or payload.get("s3_key") or "").strip() or None
    doc_url = str(payload.get("doc_url") or payload.get("public_url") or "").strip() or None

    do_ocr = str(payload.get("do_ocr") or payload.get("ocr") or "").strip().lower() in {"1", "true", "si", "sí", "on"}

    ocr_status = None
    ocr_confidence = None
    ocr_text = None
    ocr_json = None
    if do_ocr and doc_key:
        ocr = ocr_nomina_from_s3(doc_key, filename=str(payload.get("filename") or "").strip() or "nomina.pdf")
        if not ocr.get("error"):
            parsed = ocr.get("fields") or {}
            ocr_status = str(ocr.get("status") or "").strip() or None
            try:
                ocr_confidence = float(ocr.get("confidence") or 0.0)
            except Exception:
                ocr_confidence = 0.0
            ocr_text = str(ocr.get("text") or "").strip() or None
            try:
                ocr_json = json.dumps(parsed or {}, ensure_ascii=False)
            except Exception:
                ocr_json = None
            if not empleado_nif:
                empleado_nif = normalize_nif(parsed.get("empleado_nif") or "") or empleado_nif
            if not empleado_nombre:
                empleado_nombre = str(parsed.get("empleado_nombre") or "").strip() or empleado_nombre
            if not year_i and parsed.get("year"):
                try:
                    year_i = int(parsed.get("year") or 0)
                except Exception:
                    year_i = year_i
            if not month_i and parsed.get("month"):
                try:
                    month_i = int(parsed.get("month") or 0)
                except Exception:
                    month_i = month_i
            if bruto <= 0 and parsed.get("bruto") not in (None, ""):
                try:
                    bruto = round(float(parsed.get("bruto") or 0.0), 2)
                except Exception:
                    pass
            if neto <= 0 and parsed.get("neto") not in (None, ""):
                try:
                    neto = round(float(parsed.get("neto") or 0.0), 2)
                except Exception:
                    pass
            if irpf_pct <= 0 and parsed.get("irpf_pct") not in (None, ""):
                try:
                    irpf_pct = round(float(parsed.get("irpf_pct") or 0.0), 4)
                except Exception:
                    pass
            if ss_trabajador <= 0 and parsed.get("ss_trabajador") not in (None, ""):
                try:
                    ss_trabajador = round(float(parsed.get("ss_trabajador") or 0.0), 2)
                except Exception:
                    pass
            if ss_empresa <= 0 and parsed.get("ss_empresa") not in (None, ""):
                try:
                    ss_empresa = round(float(parsed.get("ss_empresa") or 0.0), 2)
                except Exception:
                    pass
        else:
            ocr_status = "error"
            ocr_confidence = 0.0
            ocr_text = str(ocr.get("text") or "").strip() or None
            try:
                ocr_json = json.dumps({"error": ocr.get("error")}, ensure_ascii=False)
            except Exception:
                ocr_json = None

    if rec_id:
        conn.execute(
            """
            UPDATE workspace_rrhh_nominas
            SET empresa_id = COALESCE(NULLIF(?, ''), empresa_id),
                year = COALESCE(NULLIF(?, 0), year),
                month = COALESCE(NULLIF(?, 0), month),
                empleado_nombre = COALESCE(NULLIF(?, ''), empleado_nombre),
                empleado_nif = COALESCE(NULLIF(?, ''), empleado_nif),
                bruto = COALESCE(NULLIF(?, 0), bruto),
                neto = COALESCE(NULLIF(?, 0), neto),
                irpf_pct = COALESCE(NULLIF(?, 0), irpf_pct),
                ss_trabajador = COALESCE(NULLIF(?, 0), ss_trabajador),
                ss_empresa = COALESCE(NULLIF(?, 0), ss_empresa),
                doc_key = COALESCE(NULLIF(?, ''), doc_key),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                ocr_status = COALESCE(NULLIF(?, ''), ocr_status),
                ocr_confidence = COALESCE(NULLIF(?, 0), ocr_confidence),
                ocr_text = COALESCE(NULLIF(?, ''), ocr_text),
                ocr_json = COALESCE(NULLIF(?, ''), ocr_json),
                updated_at = datetime(?)
            WHERE id = ? AND workspace_id = ? AND persona_id = ?
            """,
            (
                empresa_id or "",
                year_i,
                month_i,
                empleado_nombre or "",
                empleado_nif or "",
                bruto,
                neto,
                irpf_pct,
                ss_trabajador,
                ss_empresa,
                doc_key or "",
                doc_url or "",
                ocr_status or "",
                float(ocr_confidence or 0.0),
                (ocr_text or "")[:200000],
                (ocr_json or "")[:200000],
                now,
                rec_id,
                workspace_id,
                persona_id,
            ),
        )
        return {"ok": True, "id": rec_id}

    rec_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO workspace_rrhh_nominas (
          id, workspace_id, empresa_id, persona_id,
          year, month,
          empleado_nombre, empleado_nif,
          bruto, neto, irpf_pct, ss_trabajador, ss_empresa,
          doc_key, doc_url,
          ocr_status, ocr_confidence, ocr_text, ocr_json,
          created_by, created_at, updated_at
        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,datetime(?),datetime(?))
        """,
        (
            rec_id,
            workspace_id,
            empresa_id,
            persona_id,
            year_i,
            month_i,
            empleado_nombre,
            empleado_nif,
            bruto,
            neto,
            irpf_pct,
            ss_trabajador,
            ss_empresa,
            doc_key,
            doc_url,
            ocr_status,
            float(ocr_confidence or 0.0),
            (ocr_text or "")[:200000] if ocr_text else None,
            (ocr_json or "")[:200000] if ocr_json else None,
            str(actor_user_id or "").strip() or None,
            now,
            now,
        ),
    )
    return {"ok": True, "id": rec_id}


