def gestoria_renta_doc_sql_condition(alias="d"):
    prefix = f"{alias}." if alias else ""
    return f"""
      (
        (
          COALESCE(TRIM(COALESCE({prefix}tipo_documento, '')), '') <> ''
          AND LOWER(COALESCE({prefix}tipo_documento, '')) IN (
            'modelo_100', 'renta', 'renta_auxiliar', 'datos_fiscales', 'borrador_renta',
            'dni', 'firma', 'autorizacion', 'certificado', 'justificante', 'pendiente_asignar'
          )
        )
        OR (
          COALESCE(TRIM(COALESCE({prefix}tipo_documento, '')), '') = ''
          AND (
            LOWER(COALESCE({prefix}referencia_tipo, '')) IN ('renta', 'gestoria_renta', 'gestoria-renta')
            OR LOWER(COALESCE({prefix}referencia_id, '')) LIKE 'renta-%'
            OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%renta%'
            OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%renta%'
            OR LOWER(COALESCE({prefix}notas, '')) LIKE '%renta%'
            OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%modelo 100%'
            OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%modelo 100%'
            OR LOWER(COALESCE({prefix}notas, '')) LIKE '%modelo 100%'
          )
        )
      )
    """


def gestoria_renta_doc_pending_assign_sql_condition(alias="d", client_alias="c"):
    prefix = f"{alias}." if alias else ""
    client_prefix = f"{client_alias}." if client_alias else ""
    return f"""
      (
        LOWER(COALESCE({prefix}estado_revision, '')) IN ('pendiente_asignar', 'conflicto_cliente')
        OR LOWER(COALESCE({prefix}tipo_documento, '')) = 'pendiente_asignar'
        OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%pendiente asignar%'
        OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%pendiente asignar%'
        OR LOWER(COALESCE({prefix}estado, '')) LIKE '%pendiente asignar%'
        OR LOWER(COALESCE({client_prefix}nombre, '')) IN ('rentas clientes', 'pendiente asignar gestoria')
        OR COALESCE(TRIM(COALESCE({prefix}cliente_id, '')), '') = ''
      )
    """


def gestoria_modelo100_doc_sql_condition(alias="d"):
    prefix = f"{alias}." if alias else ""
    positive = f"""
      (
        (
          COALESCE(TRIM(COALESCE({prefix}tipo_documento, '')), '') <> ''
          AND LOWER(COALESCE({prefix}tipo_documento, '')) = 'modelo_100'
        )
        OR (
          COALESCE(TRIM(COALESCE({prefix}tipo_documento, '')), '') = ''
          AND (
            LOWER(COALESCE({prefix}tipo, '')) IN ('modelo 100', 'renta', 'renta presentada', 'declaracion presentada', 'declaración presentada')
            OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%modelo 100%'
            OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%modelo 100%'
            OR LOWER(COALESCE({prefix}notas, '')) LIKE '%modelo 100%'
            OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%irpf%'
            OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%irpf%'
            OR LOWER(COALESCE({prefix}notas, '')) LIKE '%irpf%'
            OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%renta presentad%'
            OR LOWER(COALESCE({prefix}nombre, '')) LIKE 'renta %'
          )
        )
      )
    """
    auxiliary = f"""
      (
        LOWER(COALESCE({prefix}tipo_documento, '')) IN ('dni', 'firma', 'autorizacion', 'certificado', 'justificante', 'datos_fiscales', 'borrador_renta', 'renta_auxiliar')
        OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%dni%'
        OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%dni%'
        OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%firma%'
        OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%firma%'
        OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%autoriz%'
        OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%autoriz%'
        OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%certificado%'
        OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%certificado%'
        OR LOWER(COALESCE({prefix}tipo, '')) LIKE '%justificante%'
        OR LOWER(COALESCE({prefix}nombre, '')) LIKE '%justificante%'
      )
    """
    return f"(({positive}) AND NOT ({auxiliary}) AND LOWER(COALESCE({prefix}estado_revision, '')) NOT IN ('duplicado', 'conflicto_cliente', 'pendiente_asignar'))"


def gestoria_renta_doc_year_sql_condition(alias="d"):
    prefix = f"{alias}." if alias else ""
    text_exprs = [
        f"LOWER(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE({prefix}{col}, ''), '·', ' '), '_', ' '), '-', ' '), '.', ' '))"
        for col in ("referencia_id", "nombre", "tipo", "notas")
    ]
    fiscal_current = " OR ".join(
        [
            f"LOWER(COALESCE({prefix}referencia_id, '')) LIKE ?",
            *[f"{expr} LIKE ?" for expr in text_exprs for _ in range(6)],
        ]
    )
    fiscal_year_block = " OR ".join(
        [
            f"LOWER(COALESCE({prefix}referencia_id, '')) LIKE ?",
            *[f"{expr} LIKE ?" for expr in text_exprs for _ in range(6)],
        ]
    )
    fiscal_any_year = " OR ".join([f"({fiscal_year_block})" for _year in range(2020, 2036)])
    return f"""
      (
        COALESCE(TRIM(COALESCE({prefix}ejercicio_fiscal, '')), '') = ?
        OR (
          COALESCE(TRIM(COALESCE({prefix}ejercicio_fiscal, '')), '') = ''
          AND (
            ({fiscal_current})
            OR (
              NOT ({fiscal_any_year})
              AND (
                COALESCE({prefix}fecha, '') LIKE ?
                OR COALESCE({prefix}created_at, '') LIKE ?
                OR COALESCE({prefix}updated_at, '') LIKE ?
              )
            )
          )
        )
      )
    """


def gestoria_renta_doc_year_values(ejercicio_val):
    ref_like = f"renta-{ejercicio_val}-%".lower()
    try:
        campaign_upload_year = str(int(ejercicio_val) + 1)
    except Exception:
        campaign_upload_year = ""
    fiscal_patterns = [
        f"%renta {ejercicio_val}%",
        f"%{ejercicio_val} renta%",
        f"%modelo 100 {ejercicio_val}%",
        f"%{ejercicio_val} modelo 100%",
        f"%irpf {ejercicio_val}%",
        f"%{ejercicio_val} irpf%",
    ]
    current_values = [ref_like]
    for _col in ("referencia_id", "nombre", "tipo", "notas"):
        current_values.extend(fiscal_patterns)

    any_year_values = []
    for year in range(2020, 2036):
        year_s = str(year)
        any_year_values.append(f"renta-{year_s}-%")
        other_patterns = [
            f"%renta {year_s}%",
            f"%{year_s} renta%",
            f"%modelo 100 {year_s}%",
            f"%{year_s} modelo 100%",
            f"%irpf {year_s}%",
            f"%{year_s} irpf%",
        ]
        for _col in ("referencia_id", "nombre", "tipo", "notas"):
            any_year_values.extend(other_patterns)
    return [
        str(ejercicio_val or "").strip(),
        *current_values,
        *any_year_values,
        f"{ejercicio_val}%",
        f"{campaign_upload_year}%",
        f"{campaign_upload_year}%",
    ]


def classify_gestoria_renta_document(
    conn,
    *,
    cliente_id="",
    ejercicio="",
    nombre="",
    tipo="",
    notas="",
    referencia_id="",
    estado="",
    archivo_hash="",
    doc_key="",
    exclude_doc_id="",
):
    text = normalize_lookup_text(" ".join(str(v or "") for v in (nombre, tipo, notas, referencia_id, estado)))
    ejercicio_val = str(ejercicio or "").strip()
    if not re.match(r"^20[0-9]{2}$", ejercicio_val or ""):
        year_values = re.findall(r"20[0-9]{2}", " ".join(str(v or "") for v in (referencia_id, nombre, tipo, notas)))
        ejercicio_val = year_values[0] if year_values else ""
    aux_patterns = (
        " DNI",
        "FIRMA",
        "AUTORIZ",
        "CERTIFICADO",
        "JUSTIFICANTE",
        "DATOS FISCALES",
        "BORRADOR",
        "CONTRATO",
        "POLIZA",
        "PÓLIZA",
        "FACTURA",
        "IBI",
        "MODELO 650",
        "MODELO 660",
        "MODELO 390",
    )
    is_pending = (
        "PENDIENTE ASIGNAR" in text
        or normalize_lookup_text(nombre) in {"RENTAS CLIENTES", "PENDIENTE ASIGNAR GESTORIA"}
        or not str(cliente_id or "").strip()
    )
    is_aux = any(p in f" {text} " for p in aux_patterns)
    is_modelo100 = (
        not is_aux
        and (
            "MODELO 100" in text
            or "IRPF" in text
            or "RENTA PRESENTAD" in text
            or normalize_lookup_text(tipo) in {"MODELO 100", "RENTA", "RENTA PRESENTADA", "DECLARACION PRESENTADA", "DECLARACIÓN PRESENTADA"}
        )
    )
    if is_pending:
        tipo_documento = "pendiente_asignar"
        estado_revision = "pendiente_asignar"
    elif is_modelo100:
        tipo_documento = "modelo_100"
        estado_revision = "ok"
    elif is_aux:
        if "DNI" in text:
            tipo_documento = "dni"
        elif "FIRMA" in text:
            tipo_documento = "firma"
        elif "AUTORIZ" in text:
            tipo_documento = "autorizacion"
        elif "DATOS FISCALES" in text:
            tipo_documento = "datos_fiscales"
        elif "BORRADOR" in text:
            tipo_documento = "borrador_renta"
        elif "JUSTIFICANTE" in text:
            tipo_documento = "justificante"
        else:
            tipo_documento = "renta_auxiliar"
        estado_revision = "ok"
    else:
        tipo_documento = "renta_auxiliar" if "RENTA" in text else ""
        estado_revision = "revisar" if tipo_documento else ""

    duplicate_of = ""
    hash_value = str(archivo_hash or "").strip()
    key_value = str(doc_key or "").strip()
    cid = str(cliente_id or "").strip()
    if hash_value or key_value:
        where = []
        args = []
        if hash_value:
            where.append("COALESCE(archivo_hash, '') = ?")
            args.append(hash_value)
        if key_value:
            where.append("COALESCE(doc_key, '') = ?")
            args.append(key_value)
        if where:
            sql = f"""
                SELECT id, COALESCE(cliente_id, '') AS cliente_id
                FROM gestoria_docs
                WHERE ({' OR '.join(where)})
                  AND COALESCE(id, '') <> ?
                ORDER BY updated_at DESC
                LIMIT 1
            """
            try:
                row = conn.execute(sql, tuple([*args, str(exclude_doc_id or "").strip()])).fetchone()
            except Exception:
                row = None
            if row:
                duplicate_of = str(row_value(row, "id", "") or "").strip()
                other_cid = str(row_value(row, "cliente_id", "") or "").strip()
                if duplicate_of:
                    if cid and other_cid and cid != other_cid:
                        estado_revision = "conflicto_cliente"
                    else:
                        estado_revision = "duplicado"
    return {
        "ejercicio_fiscal": ejercicio_val,
        "tipo_documento": tipo_documento,
        "estado_revision": estado_revision,
        "duplicate_of": duplicate_of,
    }


def compute_gestoria_renta_dashboard(conn, empresa_id, ejercicio=""):
    empresa_ids = empresa_id if isinstance(empresa_id, (list, tuple, set)) else [empresa_id]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return {"ejercicio": "", "counts": {}, "responsables": [], "campaigns": [], "unpaid": [], "unassigned": [], "missing": [], "months": []}

    ejercicio_raw = str(ejercicio or "").strip()
    ejercicio_val = ejercicio_raw if re.match(r"^20[0-9]{2}$", ejercicio_raw or "") else ""
    if not ejercicio_val:
        try:
            ejercicio_val = str(datetime.now().year - 1)
        except Exception:
            ejercicio_val = ""
    prev_val = ""
    try:
        prev_val = str(int(ejercicio_val) - 1)
    except Exception:
        prev_val = ""

    service_filter = gestoria_service_sql_condition("ce")
    service_filter_exists = gestoria_service_sql_condition("ce2")

    placeholders_emp = ",".join(["?"] * len(empresa_ids))
    rows = conn.execute(
        f"""
        SELECT
          c.id AS cliente_id,
          c.nombre,
          c.nif,
          c.estado AS cliente_estado,
          cg.renta_detalles,
          cg.updated_at AS cg_updated_at,
          c.empresa_id AS cliente_empresa_id,
          CASE
            WHEN EXISTS (
              SELECT 1
              FROM clientes_empresas ce
              WHERE ce.empresa_id IN ({placeholders_emp})
                AND ce.cliente_id = c.id
                AND {service_filter}
            ) THEN 1
            ELSE 0
          END AS has_servicio_link,
          (
            SELECT ce2.estado
            FROM clientes_empresas ce2
            WHERE ce2.empresa_id IN ({placeholders_emp})
              AND ce2.cliente_id = c.id
              AND {service_filter_exists}
            ORDER BY
              CASE
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'activo' THEN 3
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'alta' THEN 2
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'pendiente' THEN 1
                ELSE 0
              END DESC,
              ce2.updated_at DESC
            LIMIT 1
          ) AS servicio_estado
        FROM cliente_gestoria cg
        JOIN clientes c ON c.id = cg.cliente_id
        WHERE COALESCE(cg.mod_renta, 0) = 1
          AND (
            COALESCE(c.empresa_id, '') IN ({placeholders_emp})
            OR EXISTS (
              SELECT 1
              FROM clientes_empresas ce
              WHERE ce.empresa_id IN ({placeholders_emp})
                AND ce.cliente_id = c.id
                AND {service_filter}
            )
          )
        ORDER BY LOWER(COALESCE(c.nombre, '')) ASC
        """,
        tuple([*empresa_ids, *empresa_ids, *empresa_ids, *empresa_ids]),
    ).fetchall()

    campaigns = []
    campaigns_prev = []
    missing = []
    sin_vincular_rows = []
    for row in rows:
        row_dict = dict(row)
        cliente_id = str(row_dict.get("cliente_id") or "").strip()
        nombre = str(row_dict.get("nombre") or "").strip()
        nif = str(row_dict.get("nif") or "").strip()
        servicio_estado = str(row_dict.get("servicio_estado") or row_dict.get("cliente_estado") or "").strip()
        cg_updated_at = str(row_dict.get("cg_updated_at") or "").strip()
        has_link = int(row_dict.get("has_servicio_link") or 0) == 1
        payload = parse_renta_detalles_payload(row_dict.get("renta_detalles"))
        entries = sanitize_renta_entries(sort_renta_entries(payload.get("entries") or []))
        entry = None
        entry_prev = None
        for e in entries:
            if str(e.get("ejercicio") or "").strip() == ejercicio_val:
                entry = e
                break
        if prev_val:
            for e in entries:
                if str(e.get("ejercicio") or "").strip() == prev_val:
                    entry_prev = e
                    break
        if entry_prev:
            try:
                estado_p = normalize_renta_presentacion_status(entry_prev.get("estado_presentacion") or entry_prev.get("doc_status"))
                responsable_raw_p = str(entry_prev.get("responsable") or "").strip()
                responsable_label_p = responsable_raw_p or "Sin responsable"
                responsable_key_p = normalize_lookup_text(responsable_label_p) or "sin-responsable"
                precio_p = coerce_renta_money(entry_prev.get("precio_servicio")) or 0.0
                cobrada_p = 1 if parse_boolish(entry_prev.get("cobrada")) else 0
                forma_cobro_p = str(entry_prev.get("forma_cobro") or "").strip()
                remesada_p = 1 if parse_boolish(entry_prev.get("remesada")) else 0
                presentacion_fecha_p = str(entry_prev.get("presentacion_fecha") or "").strip()
                parsed_pres_p = parse_iso_date(presentacion_fecha_p)
                month_p = parsed_pres_p.strftime("%Y-%m") if parsed_pres_p else ""
                if not month_p:
                    parsed_fallback_p = parse_iso_date(cg_updated_at)
                    month_p = parsed_fallback_p.strftime("%Y-%m") if parsed_fallback_p else ""
                fecha_cobro_p = str(entry_prev.get("fecha_cobro") or "").strip()
                parsed_cobro_p = parse_iso_date(fecha_cobro_p)
                month_cobro_p = parsed_cobro_p.strftime("%Y-%m") if parsed_cobro_p else ""
                campaigns_prev.append(
                    {
                        "cliente_id": cliente_id,
                        "cliente": nombre,
                        "nif": nif,
                        "estado_servicio": servicio_estado,
                        "ejercicio": prev_val,
                        "estado_presentacion": estado_p,
                        "presentacion_fecha": presentacion_fecha_p,
                        "mes": month_p,
                        "fecha_cobro": fecha_cobro_p,
                        "mes_cobro": month_cobro_p,
                        "responsable": responsable_raw_p,
                        "responsable_label": responsable_label_p,
                        "responsable_key": responsable_key_p,
                        "precio_servicio": round(float(precio_p or 0.0), 2),
                        "cobrada": cobrada_p,
                        "forma_cobro": forma_cobro_p,
                        "remesada": remesada_p,
                    }
                )
            except Exception:
                pass
        if not entry:
            missing.append({"cliente_id": cliente_id, "cliente": nombre, "nif": nif, "estado_servicio": servicio_estado})
            if not has_link and len(sin_vincular_rows) < 250:
                sin_vincular_rows.append({"cliente_id": cliente_id, "cliente": nombre, "nif": nif, "estado_servicio": servicio_estado})
            continue
        estado = normalize_renta_presentacion_status(entry.get("estado_presentacion") or entry.get("doc_status"))
        responsable_raw = str(entry.get("responsable") or "").strip()
        responsable_label = responsable_raw or "Sin responsable"
        responsable_key = normalize_lookup_text(responsable_label) or "sin-responsable"
        precio = coerce_renta_money(entry.get("precio_servicio")) or 0.0
        cobrada = 1 if parse_boolish(entry.get("cobrada")) else 0
        forma_cobro = str(entry.get("forma_cobro") or "").strip()
        remesada = 1 if parse_boolish(entry.get("remesada")) else 0
        presentacion_fecha = str(entry.get("presentacion_fecha") or "").strip()
        parsed_pres = parse_iso_date(presentacion_fecha)
        month = parsed_pres.strftime("%Y-%m") if parsed_pres else ""
        if not month:
            parsed_fallback = parse_iso_date(cg_updated_at)
            month = parsed_fallback.strftime("%Y-%m") if parsed_fallback else ""
        fecha_cobro = str(entry.get("fecha_cobro") or "").strip()
        parsed_cobro = parse_iso_date(fecha_cobro)
        month_cobro = parsed_cobro.strftime("%Y-%m") if parsed_cobro else ""
        campaigns.append(
            {
                "cliente_id": cliente_id,
                "cliente": nombre,
                "nif": nif,
                "estado_servicio": servicio_estado,
                "ejercicio": ejercicio_val,
                "estado_presentacion": estado,
                "presentacion_fecha": presentacion_fecha,
                "mes": month,
                "fecha_cobro": fecha_cobro,
                "mes_cobro": month_cobro,
                "responsable": responsable_raw,
                "responsable_label": responsable_label,
                "responsable_key": responsable_key,
                "precio_servicio": round(float(precio or 0.0), 2),
                "cobrada": cobrada,
                "forma_cobro": forma_cobro,
                "remesada": remesada,
            }
        )

    counts = {
        "clientes_renta": len(rows),
        "campanas_ejercicio": len(campaigns),
        "sin_campana": max(len(rows) - len(campaigns), 0),
        "sin_vincular_servicio": 0,
        # Documentos subidos/importados (gestoria_docs) para el ejercicio.
        "docs_total": 0,
        "clientes_con_doc": 0,
        "presentadas": 0,
        "borrador": 0,
        "con_precio": 0,
        "sin_precio": 0,
        "cobradas": 0,
        "sin_cobrar": 0,
        "cobradas_con_precio": 0,
        "sin_cobrar_con_precio": 0,
        "sin_responsable": 0,
        "remesadas": 0,
        "no_remesadas": 0,
        "remesadas_total": 0.0,
        "cobros_sin_fecha": 0,
        "cobros_sin_fecha_total": 0.0,
        "facturacion_total": 0.0,
        "cobrado_total": 0.0,
        "pendiente_cobro_total": 0.0,
    }
    responsables = {}
    months = {}
    cobros_months = {}
    cobros_sin_fecha_total = 0.0
    for item in campaigns:
        estado = item.get("estado_presentacion") or ""
        if estado == "Borrador":
            counts["borrador"] += 1
        else:
            counts["presentadas"] += 1
        is_cobrada = int(item.get("cobrada") or 0) == 1
        if is_cobrada:
            counts["cobradas"] += 1
        else:
            counts["sin_cobrar"] += 1
        precio = float(item.get("precio_servicio") or 0.0)
        if precio > 0.0001:
            counts["con_precio"] += 1
            counts["facturacion_total"] += precio
            if is_cobrada:
                counts["cobradas_con_precio"] += 1
                counts["cobrado_total"] += precio
                cobro_month = str(item.get("mes_cobro") or "").strip()
                if cobro_month:
                    cobros_months.setdefault(cobro_month, {"mes": cobro_month, "cobradas": 0, "cobrado": 0.0})
                    cobros_months[cobro_month]["cobradas"] += 1
                    cobros_months[cobro_month]["cobrado"] += precio
                else:
                    cobros_sin_fecha_total += precio
                    counts["cobros_sin_fecha"] += 1
                    counts["cobros_sin_fecha_total"] += precio
            else:
                counts["sin_cobrar_con_precio"] += 1
                counts["pendiente_cobro_total"] += precio
        else:
            counts["sin_precio"] += 1
        if int(item.get("remesada") or 0) == 1:
            counts["remesadas"] += 1
            if precio > 0.0001:
                counts["remesadas_total"] += precio
        else:
            counts["no_remesadas"] += 1
        resp_raw = str(item.get("responsable") or "").strip()
        resp_key = str(item.get("responsable_key") or "").strip()
        resp_key_norm = normalize_action_key(resp_key) or resp_key
        resp_text_norm = normalize_lookup_text(resp_raw)
        resp_action_norm = normalize_action_key(resp_raw)
        is_unassigned_resp = (
            (not resp_raw)
            or resp_key_norm in {"sin-responsable", "sin_responsable", "sinresponsable", "sresponsable"}
            or resp_action_norm in {"sin_responsable", "sinresponsable", "sresponsable", "sin_asignar", "sin_asignacion"}
            or resp_text_norm in {
                "SIN RESPONSABLE",
                "SIN ASIGNAR",
                "SIN ASIGNACION",
                "SIN ASIGNACIÓN",
                "SELECCIONA RESPONSABLE",
                "SELECCIONAR RESPONSABLE",
            }
        )
        if is_unassigned_resp:
            counts["sin_responsable"] += 1
        key = str(item.get("responsable_key") or "sin-responsable")
        bucket = responsables.get(key)
        if not bucket:
            bucket = {
                "responsable_key": key,
                "responsable": item.get("responsable_label") or "Sin responsable",
                "campanas": 0,
                "borrador": 0,
                "presentadas": 0,
                "sin_cobrar": 0,
                "facturacion": 0.0,
                "cobrado": 0.0,
                "pendiente": 0.0,
            }
            responsables[key] = bucket
        bucket["campanas"] += 1
        if estado == "Borrador":
            bucket["borrador"] += 1
        else:
            bucket["presentadas"] += 1
        if precio > 0.0001:
            bucket["facturacion"] += precio
            if int(item.get("cobrada") or 0) == 1:
                bucket["cobrado"] += precio
            else:
                bucket["sin_cobrar"] += 1
                bucket["pendiente"] += precio
        month = str(item.get("mes") or "").strip()
        if month:
            months.setdefault(month, {"mes": month, "campanas": 0, "presentadas": 0, "borrador": 0})
            months[month]["campanas"] += 1
            if estado == "Borrador":
                months[month]["borrador"] += 1
            else:
                months[month]["presentadas"] += 1

    # Calidad de datos: clientes con renta pero sin vínculo explícito clientes_empresas para Gestoría.
    try:
        sin_link = conn.execute(
            f"""
            SELECT COUNT(*) AS total
            FROM cliente_gestoria cg
            JOIN clientes c ON c.id = cg.cliente_id
            WHERE COALESCE(cg.mod_renta, 0) = 1
              AND COALESCE(c.empresa_id, '') IN ({placeholders_emp})
              AND NOT EXISTS (
                SELECT 1 FROM clientes_empresas ce
                WHERE ce.cliente_id = c.id
                  AND ce.empresa_id IN ({placeholders_emp})
                  AND {service_filter}
              )
            """,
            tuple([*empresa_ids, *empresa_ids]),
        ).fetchone()
        counts["sin_vincular_servicio"] = int(row_value(sin_link, "total", 0) or 0)
    except Exception:
        counts["sin_vincular_servicio"] = 0

    # Documentos de Renta asociados al ejercicio (PDFs subidos). Esto se usa en el
    # dashboard para diferenciar "campañas" (encargos), declaraciones únicas y
    # documentos brutos. No usamos documentos brutos como proxy de Modelos 100.
    try:
        renta_filter = gestoria_renta_doc_sql_condition("d")
        modelo100_filter = gestoria_modelo100_doc_sql_condition("d")
        year_filter = gestoria_renta_doc_year_sql_condition("d")
        pending_filter = gestoria_renta_doc_pending_assign_sql_condition("d", "c")
        docs_row = conn.execute(
            f"""
            WITH renta_docs AS (
              SELECT
                d.id,
                COALESCE(d.cliente_id, '') AS cliente_id,
                COALESCE(d.archivo_hash, '') AS archivo_hash,
                CASE WHEN {pending_filter} THEN 1 ELSE 0 END AS pendiente_asignar,
                CASE WHEN {modelo100_filter} THEN 1 ELSE 0 END AS es_modelo100
              FROM gestoria_docs d
              LEFT JOIN clientes c ON c.id = d.cliente_id
              WHERE (
                  d.empresa_id IN ({placeholders_emp})
                  OR EXISTS (
                    SELECT 1
                    FROM cliente_gestoria cg
                    WHERE cg.cliente_id = d.cliente_id
                      AND (
                        COALESCE(cg.mod_renta, 0) = 1
                        OR COALESCE(TRIM(cg.renta_detalles), '') NOT IN ('', '{{}}', '[]')
                      )
                  )
                )
                AND {renta_filter}
                AND {year_filter}
            ),
            shared_hashes AS (
              SELECT archivo_hash
              FROM renta_docs
              WHERE COALESCE(TRIM(archivo_hash), '') <> ''
              GROUP BY archivo_hash
              HAVING COUNT(DISTINCT NULLIF(TRIM(cliente_id), '')) > 1
            )
            SELECT
              COUNT(*) AS docs_total,
              COUNT(DISTINCT NULLIF(TRIM(cliente_id), '')) AS clientes_con_doc,
              SUM(CASE WHEN pendiente_asignar = 1 THEN 1 ELSE 0 END) AS docs_pendiente_asignar,
              SUM(CASE WHEN pendiente_asignar = 0 AND es_modelo100 = 1 THEN 1 ELSE 0 END) AS modelo100_docs_total,
              COUNT(DISTINCT CASE WHEN pendiente_asignar = 0 AND es_modelo100 = 1 THEN NULLIF(TRIM(cliente_id), '') ELSE NULL END) AS modelo100_unicos,
              (SELECT COUNT(*) FROM shared_hashes) AS hash_compartido_grupos
            FROM renta_docs
            """,
            tuple([*empresa_ids, *gestoria_renta_doc_year_values(ejercicio_val)]),
        ).fetchone()
        counts["docs_total"] = int(row_value(docs_row, "docs_total", 0) or 0)
        counts["clientes_con_doc"] = int(row_value(docs_row, "clientes_con_doc", 0) or 0)
        counts["modelo100_docs_total"] = int(row_value(docs_row, "modelo100_docs_total", 0) or 0)
        counts["modelo100_unicos"] = int(row_value(docs_row, "modelo100_unicos", 0) or 0)
        counts["declaraciones_docs_total"] = counts["modelo100_docs_total"]
        counts["declaraciones_unicas"] = counts["modelo100_unicos"]
        counts["docs_pendiente_asignar"] = int(row_value(docs_row, "docs_pendiente_asignar", 0) or 0)
        counts["hash_compartido_grupos"] = int(row_value(docs_row, "hash_compartido_grupos", 0) or 0)
    except Exception:
        counts["docs_total"] = 0
        counts["clientes_con_doc"] = 0
        counts["modelo100_docs_total"] = 0
        counts["modelo100_unicos"] = 0
        counts["declaraciones_docs_total"] = 0
        counts["declaraciones_unicas"] = 0
        counts["docs_pendiente_asignar"] = 0
        counts["hash_compartido_grupos"] = 0

    unpaid = [
        item for item in campaigns if float(item.get("precio_servicio") or 0.0) > 0.0001 and int(item.get("cobrada") or 0) != 1
    ]
    unpaid.sort(key=lambda x: (-float(x.get("precio_servicio") or 0.0), str(x.get("cliente") or "")))
    unassigned = []
    for item in campaigns:
        resp_raw = str(item.get("responsable") or "").strip()
        resp_key = str(item.get("responsable_key") or "").strip()
        resp_key_norm = normalize_action_key(resp_key) or resp_key
        resp_text_norm = normalize_lookup_text(resp_raw)
        resp_action_norm = normalize_action_key(resp_raw)
        if (
            (not resp_raw)
            or resp_key_norm in {"sin-responsable", "sin_responsable", "sinresponsable", "sresponsable"}
            or resp_action_norm in {"sin_responsable", "sinresponsable", "sresponsable", "sin_asignar", "sin_asignacion"}
            or resp_text_norm in {
                "SIN RESPONSABLE",
                "SIN ASIGNAR",
                "SIN ASIGNACION",
                "SIN ASIGNACIÓN",
                "SELECCIONA RESPONSABLE",
                "SELECCIONAR RESPONSABLE",
            }
        ):
            unassigned.append(item)
    unassigned.sort(key=lambda x: (-float(x.get("precio_servicio") or 0.0), str(x.get("cliente") or "")))

    responsables_list = list(responsables.values())
    responsables_list.sort(key=lambda x: (-float(x.get("pendiente") or 0.0), -int(x.get("campanas") or 0)))
    months_list = list(months.values())
    months_list.sort(key=lambda x: str(x.get("mes") or ""))
    cobros_months_list = list(cobros_months.values())
    cobros_months_list.sort(key=lambda x: str(x.get("mes") or ""))

    # Serie del ejercicio actual (facturación/cobro/pendiente por mes).
    # Importante: en muchos casos se marca "cobrada" pero no se informa `fecha_cobro`.
    # Para no dejar el gráfico vacío, usamos el mes de presentación como fallback.
    cobro_series_out = {"labels": [], "facturacion": [], "cobrado": [], "pendiente": []}
    try:
        month_labels = [f"{m:02d}" for m in range(1, 13)]
        fact_m = {m: 0.0 for m in month_labels}
        cob_m = {m: 0.0 for m in month_labels}
        pen_m = {m: 0.0 for m in month_labels}
        for item in campaigns:
            precio = float(item.get("precio_servicio") or 0.0)
            if precio <= 0.0001:
                continue
            ym_pres = str(item.get("mes") or "").strip()
            ym_cobro = str(item.get("mes_cobro") or "").strip()
            month_fact = ym_pres[5:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}$", ym_pres) else ""
            if not month_fact:
                month_fact = ym_cobro[5:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}$", ym_cobro) else ""
            if month_fact not in month_labels:
                continue
            fact_m[month_fact] += precio
            is_cobrada = int(item.get("cobrada") or 0) == 1
            month_cob = ym_cobro[5:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}$", ym_cobro) else ""
            month_cob = month_cob if month_cob in month_labels else month_fact
            if is_cobrada:
                cob_m[month_cob] += precio
            else:
                pen_m[month_fact] += precio
        cobro_series_out = {
            "labels": month_labels,
            "facturacion": [round(float(fact_m[m]), 2) for m in month_labels],
            "cobrado": [round(float(cob_m[m]), 2) for m in month_labels],
            "pendiente": [round(float(pen_m[m]), 2) for m in month_labels],
        }
    except Exception:
        cobro_series_out = {"labels": [], "facturacion": [], "cobrado": [], "pendiente": []}

    # Ejercicio anterior: cobros por mes y serie fact/cobro/pendiente (para comparativa).
    cobros_prev_months = {}
    cobro_prev_series_out = {"labels": [], "facturacion": [], "cobrado": [], "pendiente": []}
    if prev_val and campaigns_prev:
        try:
            month_labels = [f"{m:02d}" for m in range(1, 13)]
            fact_m = {m: 0.0 for m in month_labels}
            cob_m = {m: 0.0 for m in month_labels}
            pen_m = {m: 0.0 for m in month_labels}
            for item in campaigns_prev:
                precio = float(item.get("precio_servicio") or 0.0)
                if precio <= 0.0001:
                    continue
                ym_pres = str(item.get("mes") or "").strip()
                ym_cobro = str(item.get("mes_cobro") or "").strip()
                month_fact = ym_pres[5:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}$", ym_pres) else ""
                if not month_fact:
                    month_fact = ym_cobro[5:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}$", ym_cobro) else ""
                if month_fact not in month_labels:
                    continue
                fact_m[month_fact] += precio
                is_cobrada = int(item.get("cobrada") or 0) == 1
                month_cob = ym_cobro[5:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}$", ym_cobro) else ""
                month_cob = month_cob if month_cob in month_labels else month_fact
                if is_cobrada:
                    cob_m[month_cob] += precio
                    key = f"{prev_val}-{month_cob}"
                    cobros_prev_months.setdefault(key, {"mes": key, "cobradas": 0, "cobrado": 0.0})
                    cobros_prev_months[key]["cobradas"] += 1
                    cobros_prev_months[key]["cobrado"] += precio
                else:
                    pen_m[month_fact] += precio
            cobro_prev_series_out = {
                "labels": month_labels,
                "facturacion": [round(float(fact_m[m]), 2) for m in month_labels],
                "cobrado": [round(float(cob_m[m]), 2) for m in month_labels],
                "pendiente": [round(float(pen_m[m]), 2) for m in month_labels],
            }
        except Exception:
            cobro_prev_series_out = {"labels": [], "facturacion": [], "cobrado": [], "pendiente": []}
    cobros_prev_months_list = list(cobros_prev_months.values())
    cobros_prev_months_list.sort(key=lambda x: str(x.get("mes") or ""))

    # `campaigns` puede ser grande, pero es un payload de dashboard (no se usa en cards).
    # Limitamos a un máximo razonable para habilitar vistas filtradas en frontend sin otra llamada.
    campaigns_sorted = list(campaigns)
    campaigns_sorted.sort(key=lambda x: (str(x.get("cliente") or ""), str(x.get("nif") or "")))
    return {
        "ejercicio": ejercicio_val,
        "counts": {
            **counts,
            "facturacion_total": round(float(counts["facturacion_total"]), 2),
            "cobrado_total": round(float(counts["cobrado_total"]), 2),
            "pendiente_cobro_total": round(float(counts["pendiente_cobro_total"]), 2),
            "remesadas_total": round(float(counts["remesadas_total"]), 2),
            "cobros_sin_fecha_total": round(float(counts["cobros_sin_fecha_total"]), 2),
        },
        "responsables": [
            {
                **row,
                "facturacion": round(float(row.get("facturacion") or 0.0), 2),
                "cobrado": round(float(row.get("cobrado") or 0.0), 2),
                "pendiente": round(float(row.get("pendiente") or 0.0), 2),
            }
            for row in responsables_list
        ],
        "campaigns": campaigns_sorted[:2000],
        "unpaid": unpaid[:400],
        "unassigned": unassigned[:400],
        "missing": missing[:400],
        "sin_vincular": sin_vincular_rows[:250],
        "months": months_list,
        "cobros": {
            "months": [
                {**row, "cobrado": round(float(row.get("cobrado") or 0.0), 2)}
                for row in cobros_months_list
            ],
            "sin_fecha_total": round(float(cobros_sin_fecha_total or 0.0), 2),
        },
        "cobro_series": cobro_series_out,
        "prev": {
            "ejercicio": prev_val,
            "cobros_months": [
                {**row, "cobrado": round(float(row.get("cobrado") or 0.0), 2)}
                for row in cobros_prev_months_list
            ],
            "cobro_series": cobro_prev_series_out,
        },
    }


def collect_gestoria_renta_campaign_rows(conn, empresa_id, ejercicio="", q=""):
    empresa_ids = empresa_id if isinstance(empresa_id, (list, tuple, set)) else [empresa_id]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return [], []
    ejercicio_raw = str(ejercicio or "").strip()
    ejercicio_val = ejercicio_raw if re.match(r"^20[0-9]{2}$", ejercicio_raw or "") else ""
    if not ejercicio_val:
        try:
            ejercicio_val = str(datetime.now().year - 1)
        except Exception:
            ejercicio_val = ""
    q_raw = str(q or "").strip()
    q_norm = normalize_lookup_text(q_raw)

    service_filter = gestoria_service_sql_condition("ce")
    service_filter_exists = gestoria_service_sql_condition("ce2")

    placeholders_emp = ",".join(["?"] * len(empresa_ids))
    rows = conn.execute(
        f"""
        SELECT
          c.id AS cliente_id,
          c.nombre,
          c.nif,
          c.telefono,
          c.movil,
          c.email,
          c.fecha_nacimiento,
          c.direccion,
          c.codigo_postal,
          c.poblacion,
          c.provincia,
          c.estado AS cliente_estado,
          cg.renta_detalles,
          (
            SELECT ce2.estado
            FROM clientes_empresas ce2
            WHERE ce2.empresa_id IN ({placeholders_emp})
              AND ce2.cliente_id = c.id
              AND {service_filter_exists}
            ORDER BY
              CASE
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'activo' THEN 3
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'alta' THEN 2
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'pendiente' THEN 1
                ELSE 0
              END DESC,
              ce2.updated_at DESC
            LIMIT 1
          ) AS servicio_estado
        FROM cliente_gestoria cg
        JOIN clientes c ON c.id = cg.cliente_id
        WHERE COALESCE(cg.mod_renta, 0) = 1
          AND EXISTS (
            SELECT 1
            FROM clientes_empresas ce
            WHERE ce.empresa_id IN ({placeholders_emp})
              AND ce.cliente_id = c.id
              AND {service_filter}
          )
        ORDER BY LOWER(COALESCE(c.nombre, '')) ASC
        """,
        tuple([*empresa_ids, *empresa_ids]),
    ).fetchall()

    campaigns = []
    missing = []
    for row in rows:
        row_dict = dict(row)
        cliente_id = str(row_dict.get("cliente_id") or "").strip()
        nombre = str(row_dict.get("nombre") or "").strip()
        nif = str(row_dict.get("nif") or "").strip()
        servicio_estado = str(row_dict.get("servicio_estado") or row_dict.get("cliente_estado") or "").strip()
        telefono = str(row_dict.get("telefono") or "").strip()
        movil = str(row_dict.get("movil") or "").strip()
        email = str(row_dict.get("email") or "").strip()
        fecha_nacimiento = str(row_dict.get("fecha_nacimiento") or "").strip()
        direccion = str(row_dict.get("direccion") or "").strip()
        codigo_postal = str(row_dict.get("codigo_postal") or "").strip()
        poblacion = str(row_dict.get("poblacion") or "").strip()
        provincia = str(row_dict.get("provincia") or "").strip()
        payload = parse_renta_detalles_payload(row_dict.get("renta_detalles"))
        entries = sanitize_renta_entries(sort_renta_entries(payload.get("entries") or []))
        entry = None
        for e in entries:
            if str(e.get("ejercicio") or "").strip() == ejercicio_val:
                entry = e
                break
        if not entry:
            missing.append({"cliente_id": cliente_id, "cliente": nombre, "nif": nif, "estado_servicio": servicio_estado})
            continue
        estado = normalize_renta_presentacion_status(entry.get("estado_presentacion") or entry.get("doc_status"))
        responsable_raw = str(entry.get("responsable") or "").strip()
        responsable_label = responsable_raw or "Sin responsable"
        responsable_key = normalize_lookup_text(responsable_label) or "sin-responsable"
        precio = coerce_renta_money(entry.get("precio_servicio")) or 0.0
        cobrada = 1 if parse_boolish(entry.get("cobrada")) else 0
        forma_cobro = str(entry.get("forma_cobro") or "").strip()
        remesada = 1 if parse_boolish(entry.get("remesada")) else 0
        presentacion_fecha = str(entry.get("presentacion_fecha") or "").strip()
        month = presentacion_fecha[:7] if re.match(r"^20[0-9]{2}\-[0-9]{2}\-", presentacion_fecha) else ""
        resultado = entry.get("resultado_declaracion")
        casilla_505 = entry.get("casilla_505")
        hijos_count = entry.get("hijos_count")
        estado_civil = str(entry.get("estado_civil") or "").strip()
        conyuge_nif = str(entry.get("conyuge_nif") or "").strip()
        cuentas_detectadas = entry.get("cuentas_detectadas") or []
        if not isinstance(cuentas_detectadas, list):
            cuentas_detectadas = []
        cuentas_str = ", ".join(str(x or "").strip() for x in cuentas_detectadas if str(x or "").strip())
        campaigns.append(
            {
                "cliente_id": cliente_id,
                "cliente": nombre,
                "nif": nif,
                "telefono": telefono,
                "movil": movil,
                "email": email,
                "fecha_nacimiento": fecha_nacimiento,
                "direccion": direccion,
                "codigo_postal": codigo_postal,
                "poblacion": poblacion,
                "provincia": provincia,
                "estado_servicio": servicio_estado,
                "ejercicio": ejercicio_val,
                "estado_presentacion": estado,
                "presentacion_fecha": presentacion_fecha,
                "mes": month,
                "responsable": responsable_raw,
                "responsable_label": responsable_label,
                "responsable_key": responsable_key,
                "precio_servicio": round(float(precio or 0.0), 2),
                "cobrada": cobrada,
                "forma_cobro": forma_cobro,
                "remesada": remesada,
                "resultado_declaracion": resultado if resultado is not None else "",
                "casilla_505": casilla_505 if casilla_505 is not None else "",
                "hijos_count": hijos_count if hijos_count is not None else "",
                "estado_civil": estado_civil,
                "conyuge_nif": conyuge_nif,
                "cuentas_detectadas": cuentas_str,
            }
        )

    if q_norm:
        filtered = []
        for item in campaigns:
            hay = normalize_lookup_text(
                " ".join(
                    [
                        str(item.get("cliente") or ""),
                        str(item.get("nif") or ""),
                        str(item.get("estado_presentacion") or ""),
                        str(item.get("responsable_label") or ""),
                        str(item.get("forma_cobro") or ""),
                    ]
                )
            )
            if q_norm in hay:
                filtered.append(item)
        campaigns = filtered
        missing = [
            m
            for m in missing
            if q_norm
            in normalize_lookup_text(
                " ".join(
                    [
                        str(m.get("cliente") or ""),
                        str(m.get("nif") or ""),
                        str(m.get("estado_servicio") or ""),
                    ]
                )
            )
        ]

    campaigns.sort(key=lambda x: (str(x.get("cliente") or ""), str(x.get("nif") or "")))
    missing.sort(key=lambda x: (str(x.get("cliente") or ""), str(x.get("nif") or "")))
    return campaigns, missing


def compute_gestoria_renta_pending_summary(conn, empresa_id, ejercicio="", *, limit=12):
    """
    Resumen ligero de renta para el dashboard de gestoría.

    Evita `collect_gestoria_renta_card_items()` en el panel/resumen para no provocar timeouts
    (prefetch alto + parseo de docs). Devuelve:
    - `count`: número total de campañas en Borrador (ejercicio)
    - `rows`: preview (top N) para mostrar en el dashboard
    """
    empresa_ids = empresa_id if isinstance(empresa_id, (list, tuple, set)) else [empresa_id]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return {"ejercicio": "", "count": 0, "rows": []}

    ejercicio_raw = str(ejercicio or "").strip()
    ejercicio_val = ejercicio_raw if re.match(r"^20[0-9]{2}$", ejercicio_raw or "") else ""
    if not ejercicio_val:
        try:
            ejercicio_val = str(datetime.now().year - 1)
        except Exception:
            ejercicio_val = ""
    try:
        limit_val = int(limit)
    except Exception:
        limit_val = 12
    limit_val = max(1, min(limit_val, 100))

    service_filter = gestoria_service_sql_condition("ce")
    service_filter_exists = gestoria_service_sql_condition("ce2")
    placeholders_emp = ",".join(["?"] * len(empresa_ids))

    rows = conn.execute(
        f"""
        SELECT
          c.id AS cliente_id,
          c.nombre,
          c.nif,
          c.estado AS cliente_estado,
          cg.renta_detalles,
          (
            SELECT ce2.estado
            FROM clientes_empresas ce2
            WHERE ce2.empresa_id IN ({placeholders_emp})
              AND ce2.cliente_id = c.id
              AND {service_filter_exists}
            ORDER BY
              CASE
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'activo' THEN 3
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'alta' THEN 2
                WHEN LOWER(COALESCE(ce2.estado, '')) = 'pendiente' THEN 1
                ELSE 0
              END DESC,
              ce2.updated_at DESC
            LIMIT 1
          ) AS servicio_estado
        FROM cliente_gestoria cg
        JOIN clientes c ON c.id = cg.cliente_id
        WHERE COALESCE(cg.mod_renta, 0) = 1
          AND EXISTS (
            SELECT 1
            FROM clientes_empresas ce
            WHERE ce.empresa_id IN ({placeholders_emp})
              AND ce.cliente_id = c.id
              AND {service_filter}
          )
        ORDER BY LOWER(COALESCE(c.nombre, '')) ASC
        """,
        tuple([*empresa_ids, *empresa_ids]),
    ).fetchall()

    pending_count = 0
    total_count = 0
    presentadas_count = 0
    preview = []
    for row in rows:
        row_dict = dict(row)
        payload = parse_renta_detalles_payload(row_dict.get("renta_detalles"))
        entries = sanitize_renta_entries(sort_renta_entries(payload.get("entries") or []))
        entry = None
        for e in entries:
            if str(e.get("ejercicio") or "").strip() == ejercicio_val:
                entry = e
                break
        if not entry:
            continue
        estado = normalize_renta_presentacion_status(entry.get("estado_presentacion") or entry.get("doc_status"))
        total_count += 1
        if estado == "Borrador":
            pending_count += 1
        else:
            presentadas_count += 1
        if estado != "Borrador":
            continue
        if len(preview) >= limit_val:
            continue
        doc_count = 0
        try:
            doc_key = str(entry.get("doc_key") or "").strip()
            doc_url = str(entry.get("doc_url") or "").strip()
            if doc_key or doc_url:
                doc_count = 1
        except Exception:
            doc_count = 0
        preview.append(
            {
                "cliente_id": str(row_dict.get("cliente_id") or "").strip(),
                "cliente": str(row_dict.get("nombre") or "").strip(),
                "ejercicio": ejercicio_val,
                "nif": str(row_dict.get("nif") or "").strip(),
                "estado_servicio": str(row_dict.get("servicio_estado") or row_dict.get("cliente_estado") or "").strip(),
                "estado_presentacion": estado,
                "doc_count": doc_count,
            }
        )

    return {
        "ejercicio": ejercicio_val,
        "count": int(pending_count),
        "total": int(total_count),
        "presentadas": int(presentadas_count),
        "rows": preview,
    }


def compute_gestoria_renta_docs_summary(conn, empresa_id, ejercicio=""):
    empresa_ids = empresa_id if isinstance(empresa_id, (list, tuple, set)) else [empresa_id]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return {
            "ejercicio": "",
            "docs_total": 0,
            "clientes_con_doc": 0,
            "docs_presentados": 0,
            "modelo100_docs_total": 0,
            "modelo100_unicos": 0,
            "declaraciones_docs_total": 0,
            "declaraciones_unicas": 0,
            "docs_pendiente_asignar": 0,
            "hash_compartido_grupos": 0,
        }
    ejercicio_raw = str(ejercicio or "").strip()
    ejercicio_val = ejercicio_raw if re.match(r"^20[0-9]{2}$", ejercicio_raw or "") else ""
    if not ejercicio_val:
        try:
            ejercicio_val = str(datetime.now().year - 1)
        except Exception:
            ejercicio_val = ""
    placeholders_emp = ",".join(["?"] * len(empresa_ids))
    renta_filter = gestoria_renta_doc_sql_condition("d")
    modelo100_filter = gestoria_modelo100_doc_sql_condition("d")
    year_filter = gestoria_renta_doc_year_sql_condition("d")
    pending_filter = gestoria_renta_doc_pending_assign_sql_condition("d", "c")
    row = conn.execute(
        f"""
        WITH renta_docs AS (
          SELECT
            d.id,
            COALESCE(d.cliente_id, '') AS cliente_id,
            COALESCE(d.archivo_hash, '') AS archivo_hash,
            COALESCE(d.estado, '') AS estado,
            COALESCE(d.tipo, '') AS tipo,
            CASE WHEN {pending_filter} THEN 1 ELSE 0 END AS pendiente_asignar,
            CASE WHEN {modelo100_filter} THEN 1 ELSE 0 END AS es_modelo100
          FROM gestoria_docs d
          LEFT JOIN clientes c ON c.id = d.cliente_id
          WHERE (
              d.empresa_id IN ({placeholders_emp})
              OR EXISTS (
                SELECT 1
                FROM cliente_gestoria cg
                WHERE cg.cliente_id = d.cliente_id
                  AND (
                    COALESCE(cg.mod_renta, 0) = 1
                    OR COALESCE(TRIM(cg.renta_detalles), '') NOT IN ('', '{{}}', '[]')
                  )
              )
            )
            AND {renta_filter}
            AND {year_filter}
        ),
        shared_hashes AS (
          SELECT archivo_hash
          FROM renta_docs
          WHERE COALESCE(TRIM(archivo_hash), '') <> ''
          GROUP BY archivo_hash
          HAVING COUNT(DISTINCT NULLIF(TRIM(cliente_id), '')) > 1
        )
        SELECT
          COUNT(*) AS docs_total,
          COUNT(DISTINCT NULLIF(TRIM(cliente_id), '')) AS clientes_con_doc,
          SUM(
            CASE
              WHEN LOWER(COALESCE(estado, '')) LIKE 'present%'
                OR LOWER(COALESCE(tipo, '')) LIKE '%presentad%'
              THEN 1 ELSE 0
            END
          ) AS docs_presentados,
          SUM(CASE WHEN pendiente_asignar = 1 THEN 1 ELSE 0 END) AS docs_pendiente_asignar,
          SUM(CASE WHEN pendiente_asignar = 0 AND es_modelo100 = 1 THEN 1 ELSE 0 END) AS modelo100_docs_total,
          COUNT(DISTINCT CASE WHEN pendiente_asignar = 0 AND es_modelo100 = 1 THEN NULLIF(TRIM(cliente_id), '') ELSE NULL END) AS modelo100_unicos,
          (SELECT COUNT(*) FROM shared_hashes) AS hash_compartido_grupos
        FROM renta_docs
        """,
        tuple([
            *empresa_ids,
            *gestoria_renta_doc_year_values(ejercicio_val),
        ]),
    ).fetchone()
    return {
        "ejercicio": ejercicio_val,
        "docs_total": int(row_value(row, "docs_total", 0) or 0),
        "clientes_con_doc": int(row_value(row, "clientes_con_doc", 0) or 0),
        "docs_presentados": int(row_value(row, "docs_presentados", 0) or 0),
        "modelo100_docs_total": int(row_value(row, "modelo100_docs_total", 0) or 0),
        "modelo100_unicos": int(row_value(row, "modelo100_unicos", 0) or 0),
        "declaraciones_docs_total": int(row_value(row, "modelo100_docs_total", 0) or 0),
        "declaraciones_unicas": int(row_value(row, "modelo100_unicos", 0) or 0),
        "docs_pendiente_asignar": int(row_value(row, "docs_pendiente_asignar", 0) or 0),
        "hash_compartido_grupos": int(row_value(row, "hash_compartido_grupos", 0) or 0),
    }


def compute_gestoria_renta_campaigns_total(conn, empresa_id, ejercicio=""):
    """
    Conteo ligero de campañas de renta para un ejercicio (sin cargar docs ni construir dashboards).
    Se usa en el dashboard admin de Servicios para que "Rentas" no dependa de `gestoria_trabajos`.
    """
    empresa_ids = empresa_id if isinstance(empresa_id, (list, tuple, set)) else [empresa_id]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return {"ejercicio": "", "count": 0}

    ejercicio_raw = str(ejercicio or "").strip()
    ejercicio_val = ejercicio_raw if re.match(r"^20[0-9]{2}$", ejercicio_raw or "") else ""
    # Si no se especifica ejercicio, no asumimos (año-1) porque puede no existir aún
    # y entonces el dashboard mostraría 0. En ese caso inferimos el ejercicio más reciente
    # presente en los datos (20xx) y contamos sobre ese.
    infer_latest = not bool(ejercicio_val)

    service_filter = gestoria_service_sql_condition("ce")
    placeholders_emp = ",".join(["?"] * len(empresa_ids))
    rows = conn.execute(
        f"""
        SELECT cg.renta_detalles
        FROM cliente_gestoria cg
        JOIN clientes c ON c.id = cg.cliente_id
        WHERE COALESCE(cg.mod_renta, 0) = 1
          AND (
            COALESCE(c.empresa_id, '') IN ({placeholders_emp})
            OR EXISTS (
              SELECT 1
              FROM clientes_empresas ce
              WHERE ce.empresa_id IN ({placeholders_emp})
                AND ce.cliente_id = c.id
                AND {service_filter}
            )
          )
        """,
        tuple([*empresa_ids, *empresa_ids]),
    ).fetchall()

    total = 0
    year_counts = {}
    for row in rows:
        try:
            payload = parse_renta_detalles_payload(row_value(row, "renta_detalles", "") or "")
            entries = sanitize_renta_entries(sort_renta_entries(payload.get("entries") or []))
            for e in entries:
                year = str(e.get("ejercicio") or "").strip()
                if not re.match(r"^20[0-9]{2}$", year or ""):
                    continue
                if infer_latest:
                    year_counts[year] = year_counts.get(year, 0) + 1
                elif year == ejercicio_val:
                    total += 1
                    break
        except Exception:
            continue
    if infer_latest:
        if not year_counts:
            return {"ejercicio": "", "count": 0}
        latest_year = max(year_counts.keys())
        return {"ejercicio": latest_year, "count": int(year_counts.get(latest_year, 0))}
    return {"ejercicio": ejercicio_val, "count": int(total)}


def compute_gestoria_dashboard_segmentacion_trabajos(conn, empresa_ids):
    empresa_ids = empresa_ids if isinstance(empresa_ids, (list, tuple, set)) else [empresa_ids]
    empresa_ids = [str(eid or "").strip() for eid in empresa_ids]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if not empresa_ids:
        return {
            "herencias_total": 0,
            "trafico_total": 0,
            "expedientes_total": 0,
            "tasaciones_total": 0,
            "rentas_total": 0,
            "abiertos_total": 0,
        }

    placeholders_emp = ",".join(["?"] * len(empresa_ids))
    seg = conn.execute(
        f"""
            SELECT
              SUM(
                CASE
                  WHEN LOWER(COALESCE(NULLIF(gt.tipo_categoria,''), '')) = 'herencias' THEN 1
                  WHEN COALESCE(NULLIF(gt.tipo_categoria,''), '') = '' AND LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%herenc%' THEN 1
                  ELSE 0
                END
              ) AS herencias_total,
              SUM(
                CASE
                  WHEN LOWER(COALESCE(NULLIF(gt.tipo_categoria,''), '')) = 'trafico' THEN 1
                  WHEN COALESCE(NULLIF(gt.tipo_categoria,''), '') = '' AND (
                    LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%trafic%' OR LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%transfer%'
                  ) THEN 1
                  ELSE 0
                END
              ) AS trafico_total,
              SUM(
                CASE
                  WHEN LOWER(COALESCE(NULLIF(gt.tipo_categoria,''), '')) = 'expedientes' THEN 1
                  WHEN COALESCE(NULLIF(gt.tipo_categoria,''), '') = '' AND (
                    LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%expedient%' OR LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%administrat%'
                  ) THEN 1
                  ELSE 0
                END
              ) AS expedientes_total,
              SUM(
                CASE
                  WHEN LOWER(COALESCE(NULLIF(gt.tipo_categoria,''), '')) = 'tasaciones' THEN 1
                  WHEN COALESCE(NULLIF(gt.tipo_categoria,''), '') = '' AND LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%tasaci%' THEN 1
                  ELSE 0
                END
              ) AS tasaciones_total,
              SUM(
                CASE
                  WHEN LOWER(COALESCE(NULLIF(gt.tipo_categoria,''), '')) = 'rentas' THEN 1
                  WHEN COALESCE(NULLIF(gt.tipo_categoria,''), '') = '' AND LOWER(COALESCE(gt.tipo_trabajo,'')) LIKE '%renta%' THEN 1
                  ELSE 0
                END
              ) AS rentas_total,
              SUM(CASE WHEN (LOWER(COALESCE(gt.estado,'')) IN ('completado','finalizado','hecho','cerrado')) THEN 0 ELSE 1 END) AS abiertos_total
            FROM gestoria_trabajos gt
            WHERE gt.empresa_id IN ({placeholders_emp})
        """,
        tuple(empresa_ids),
    ).fetchone()
    return {
        "herencias_total": int(row_value(seg, "herencias_total", 0) or 0),
        "trafico_total": int(row_value(seg, "trafico_total", 0) or 0),
        "expedientes_total": int(row_value(seg, "expedientes_total", 0) or 0),
        "tasaciones_total": int(row_value(seg, "tasaciones_total", 0) or 0),
        "rentas_total": int(row_value(seg, "rentas_total", 0) or 0),
        "abiertos_total": int(row_value(seg, "abiertos_total", 0) or 0),
    }


def serialize_renta_detalles_payload(raw_value, existing_value=""):
    current = parse_renta_detalles_payload(existing_value)
    if isinstance(raw_value, dict):
        payload = raw_value
    else:
        text = str(raw_value or "").strip()
        if not text:
            payload = {"notes": "", "entries": current.get("entries", [])}
        else:
            try:
                payload = json.loads(text)
            except Exception:
                payload = {
                    "notes": text,
                    "entries": current.get("entries", []),
                }
    if isinstance(payload, list):
        payload = {"notes": current.get("notes", ""), "entries": payload}
    if not isinstance(payload, dict):
        payload = {
            "notes": current.get("notes", ""),
            "entries": current.get("entries", []),
            "related_cliente_id": current.get("related_cliente_id", ""),
            "related_relation_id": current.get("related_relation_id", ""),
            "declaracion_conjunta": current.get("declaracion_conjunta", 0),
        }
    notes = str(payload.get("notes") or "").strip()
    entries = payload.get("entries")
    if not isinstance(entries, list):
        entries = current.get("entries", [])
    related_cliente_id = str(
        payload["related_cliente_id"] if "related_cliente_id" in payload else current.get("related_cliente_id") or ""
    ).strip()
    related_relation_id = str(
        payload["related_relation_id"] if "related_relation_id" in payload else current.get("related_relation_id") or ""
    ).strip()
    declaracion_raw = (
        payload["declaracion_conjunta"]
        if "declaracion_conjunta" in payload
        else current.get("declaracion_conjunta", 0)
    )
    declaracion_conjunta = 1 if str(declaracion_raw or "").strip().lower() in {"1", "true", "yes", "si", "sí"} else 0
    return json.dumps(
        {
            "notes": notes,
            "entries": entries,
            "related_cliente_id": related_cliente_id,
            "related_relation_id": related_relation_id,
            "declaracion_conjunta": declaracion_conjunta,
        },
        ensure_ascii=False,
    )


def upsert_cliente_renta_entry(conn, cliente_id, entry_payload, now):
    row = conn.execute(
        "SELECT renta_detalles FROM cliente_gestoria WHERE cliente_id = ?",
        (cliente_id,),
    ).fetchone()
    current = parse_renta_detalles_payload(row["renta_detalles"] if row else "")
    entries = sanitize_renta_entries(current.get("entries") or [])
    entry_id = str(entry_payload.get("id") or "").strip()
    next_entries = []
    replaced = False
    for item in entries:
        same_entry = entry_id and str(item.get("id") or "").strip() == entry_id
        if same_entry:
            merged = dict(item)
            merged.update(entry_payload)
            merged["estado_presentacion"] = normalize_renta_presentacion_status(
                merged.get("estado_presentacion") or merged.get("doc_status")
            )
            merged["doc_status"] = merged["estado_presentacion"]
            next_entries.append(merged)
            replaced = True
        else:
            next_entries.append(item)
    if not replaced:
        fresh = dict(entry_payload)
        fresh["estado_presentacion"] = normalize_renta_presentacion_status(
            fresh.get("estado_presentacion") or fresh.get("doc_status")
        )
        fresh["doc_status"] = fresh["estado_presentacion"]
        next_entries.append(fresh)
    payload = {
        "notes": current.get("notes") or "",
        "entries": sort_renta_entries(next_entries),
        "related_cliente_id": current.get("related_cliente_id") or "",
        "related_relation_id": current.get("related_relation_id") or "",
        "declaracion_conjunta": current.get("declaracion_conjunta", 0),
    }
    serialized = json.dumps(payload, ensure_ascii=False)
    if row:
        conn.execute(
            """
            UPDATE cliente_gestoria
            SET mod_renta = 1, renta_detalles = ?, updated_at = datetime(?)
            WHERE cliente_id = ?
            """,
            (serialized, now, cliente_id),
        )
    else:
        conn.execute(
            """
            INSERT INTO cliente_gestoria (
              id, cliente_id, tipo_cliente, mod_fiscal, mod_laboral, mod_contable,
              mod_renta, mod_registro, mod_trafico, mod_puntuales, renta_detalles, created_at, updated_at
            ) VALUES (
              ?, ?, 'Particular', 0, 0, 0, 1, 0, 0, 0, ?, datetime(?), datetime(?)
            )
            """,
            (uuid.uuid4().hex, cliente_id, serialized, now, now),
        )
    return payload


def fetch_cliente_relaciones(conn, cliente_id):
    table_row = conn.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'cliente_relaciones'"
    ).fetchone()
    if not table_row:
        return []
    rows = conn.execute(
        """
        SELECT
          r.id,
          r.cliente_id,
          r.related_cliente_id,
          r.vinculo,
          r.notas,
          r.usar_en_renta,
          r.usar_en_seguros,
          r.usar_en_inmobiliaria,
          r.declaracion_conjunta,
          r.created_at,
          r.updated_at,
          c1.nombre AS cliente_nombre,
          c1.nif AS cliente_nif,
          c2.nombre AS related_cliente_nombre,
          c2.nif AS related_cliente_nif
        FROM cliente_relaciones r
        LEFT JOIN clientes c1 ON c1.id = r.cliente_id
        LEFT JOIN clientes c2 ON c2.id = r.related_cliente_id
        WHERE r.cliente_id = ? OR r.related_cliente_id = ?
        ORDER BY LOWER(COALESCE(r.vinculo, '')), LOWER(COALESCE(c1.nombre, '')), LOWER(COALESCE(c2.nombre, ''))
        """,
        (cliente_id, cliente_id),
    ).fetchall()
    items = []
    for row in rows:
        row_dict = dict(row)
        is_reverse = str(row_dict.get("related_cliente_id") or "") == str(cliente_id)
        counterpart_id = row_dict.get("cliente_id") if is_reverse else row_dict.get("related_cliente_id")
        counterpart_nombre = row_dict.get("cliente_nombre") if is_reverse else row_dict.get("related_cliente_nombre")
        counterpart_nif = row_dict.get("cliente_nif") if is_reverse else row_dict.get("related_cliente_nif")
        row_dict["counterpart_id"] = counterpart_id
        row_dict["counterpart_nombre"] = counterpart_nombre
        row_dict["counterpart_nif"] = counterpart_nif
        row_dict["is_reverse"] = is_reverse
        items.append(row_dict)
    return items


def build_cliente_ficha_payload(conn, cliente_id, services_filter=None):
    cliente = conn.execute("SELECT * FROM clientes WHERE id = ?", (cliente_id,)).fetchone()
    if not cliente:
        return None
    now = datetime.now(timezone.utc).isoformat()
    services_filter = services_filter or []
    if services_filter and not cliente_has_servicio(conn, cliente_id, services_filter):
        return {"error": "Cliente no disponible para este servicio"}
    empresas_query = """
        SELECT
          ce.id AS rel_id,
          ce.empresa_id,
          e.nombre AS empresa,
          ce.servicio,
          ce.captado_por_user_id,
          ce.procedencia_canal,
          ce.procedencia_cliente_id,
          ce.estado,
          ce.fecha_inicio,
          ce.fecha_fin
        FROM clientes_empresas ce
        LEFT JOIN empresas e ON e.id = ce.empresa_id
        WHERE ce.cliente_id = ?
    """
    values = [cliente_id]
    if services_filter:
        placeholders = ",".join(["?"] * len(services_filter))
        empresas_query += f" AND LOWER(ce.servicio) IN ({placeholders})"
        values.extend(services_filter)
    empresas_query += " ORDER BY e.nombre"
    try:
        empresas = [dict(r) for r in conn.execute(empresas_query, values).fetchall()]
    except Exception as exc:
        msg = str(exc).lower()
        if ("no such column" not in msg) and ("undefined column" not in msg):
            raise
        empresas_query = """
            SELECT
              ce.id AS rel_id,
              ce.empresa_id,
              e.nombre AS empresa,
              ce.servicio,
              ce.estado,
              ce.fecha_inicio,
              ce.fecha_fin
            FROM clientes_empresas ce
            LEFT JOIN empresas e ON e.id = ce.empresa_id
            WHERE ce.cliente_id = ?
        """
        values = [cliente_id]
        if services_filter:
            placeholders = ",".join(["?"] * len(services_filter))
            empresas_query += f" AND LOWER(ce.servicio) IN ({placeholders})"
            values.extend(services_filter)
        empresas_query += " ORDER BY e.nombre"
        empresas = [dict(r) for r in conn.execute(empresas_query, values).fetchall()]

    service_keys = []
    inmobiliaria_empresa_ids = []
    allowed_keys = {"gestoria", "seguros", "inmobiliaria", "financiaciones"}
    for row in empresas:
        service_key = normalize_service_key(row.get("servicio"))
        active = is_active_service_state(row.get("estado"), row.get("fecha_fin"))
        row["servicio_key"] = service_key
        row["is_active"] = active
        if not active:
            continue
        if service_key == "hipotecas":
            service_key = "financiaciones"
        if service_key in allowed_keys and service_key not in service_keys:
            service_keys.append(service_key)
        if service_key == "inmobiliaria" and row.get("empresa_id"):
            inmobiliaria_empresa_ids.append(str(row["empresa_id"]))
    empresa_ids = [row["empresa_id"] for row in empresas if row.get("empresa_id")]
    for empresa_id in sorted(set(inmobiliaria_empresa_ids)):
        autolink_inmueble_docs_for_cliente(conn, cliente_id, empresa_id, now)

    seguros_rows = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, cliente_id, empresa_id, compania, ramo, poliza_numero, fecha_efecto, fecha_vencimiento,
                   estado, prima_neta, prima_total, tomador, estado_renovacion, renovacion_fecha,
                   nueva_poliza_ref, colaborador, produccion, mes_creacion,
                   poliza_key, poliza_url, fecha_baja, motivo_baja
            FROM seguros
            WHERE cliente_id = ?
            ORDER BY COALESCE(fecha_efecto, created_at) DESC
            """,
            (cliente_id,),
        ).fetchall()
    ]
    for row in seguros_rows:
        row.update(compute_seguro_display(row))

    docs_rows = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, empresa_id, cliente_id, referencia_tipo, referencia_id, nombre, tipo, fecha,
                   estado, notas, doc_key, doc_url
            FROM gestoria_docs
            WHERE cliente_id = ?
            ORDER BY created_at DESC
            """,
            (cliente_id,),
        ).fetchall()
    ]
    docs_by_service = {"seguros": [], "gestoria": [], "financiaciones": [], "inmobiliaria": [], "otros": []}
    for row in docs_rows:
        key = normalize_service_key(row.get("referencia_tipo") or row.get("tipo"))
        if key not in docs_by_service:
            key = "otros"
        docs_by_service[key].append(row)

    facturas = []
    if empresa_ids:
        placeholders = ",".join(["?"] * len(empresa_ids))
        raw_facturas = conn.execute(
            f"""
            SELECT id, empresa_id, cliente_id, cliente_ids_json, fecha, concepto, gestion, tipo, importe, notas
            FROM gestoria_contabilidad
            WHERE empresa_id IN ({placeholders})
            ORDER BY fecha DESC, created_at DESC
            LIMIT 1000
            """,
            [*empresa_ids],
        ).fetchall()
        for raw_row in raw_facturas:
            row = dict(raw_row)
            asignados = parse_cliente_ids_payload(row.get("cliente_ids_json"))
            if not asignados and row.get("cliente_id"):
                asignados = [str(row.get("cliente_id")).strip()]
            if cliente_id not in asignados:
                continue
            reparto = 1.0 / max(1, len(asignados))
            importe_original = parse_money_value(row.get("importe"))
            row["importe_asignado"] = round(importe_original * reparto, 2)
            row["clientes_reparto"] = asignados
            facturas.append(row)
        facturas = facturas[:500]
    fact_total = sum(
        parse_money_value(row.get("importe_asignado") if row.get("importe_asignado") not in (None, "") else row.get("importe"))
        for row in facturas
        if normalize_lookup_text(row.get("tipo")) != "GASTO"
    )

    trabajos = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, empresa_id, cliente_id, tipo_trabajo, estado, fecha_inicio, fecha_fin, responsable, importe, notas
            FROM gestoria_trabajos
            WHERE cliente_id = ?
            ORDER BY COALESCE(fecha_fin, fecha_inicio, created_at) DESC
            LIMIT 500
            """,
            (cliente_id,),
        ).fetchall()
    ]

    acciones = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, empresa_id, cliente_id, fecha, hora, tipo, responsable, estado, notas, servicio, recordatorio_min
            FROM acciones
            WHERE cliente_id = ?
            ORDER BY fecha DESC, hora DESC
            LIMIT 500
            """,
            (cliente_id,),
        ).fetchall()
    ]

    historico = []
    for row in trabajos:
        historico.append(
            {
                "fecha": row.get("fecha_fin") or row.get("fecha_inicio") or "",
                "servicio": "gestoria",
                "concepto": row.get("tipo_trabajo") or "Trabajo",
                "estado": row.get("estado") or "-",
                "importe": row.get("importe"),
            }
        )
    for row in seguros_rows:
        historico.append(
            {
                "fecha": row.get("vencimiento_display") or row.get("fecha_efecto") or "",
                "servicio": "seguros",
                "concepto": f"{row.get('compania') or 'Seguro'} {row.get('poliza_numero') or ''}".strip(),
                "estado": row.get("estado_display") or row.get("estado") or "-",
                "importe": row.get("prima_total"),
            }
        )
    historico.sort(key=lambda r: str(r.get("fecha") or ""), reverse=True)

    pendientes_trabajos = sum(
        1
        for row in trabajos
        if "FINAL" not in normalize_lookup_text(row.get("estado"))
        and "CANCEL" not in normalize_lookup_text(row.get("estado"))
    )
    pendientes_acciones = sum(
        1
        for row in acciones
        if all(
            token not in normalize_lookup_text(row.get("estado"))
            for token in ("HECHO", "FINAL", "CANCEL")
        )
    )
    today = datetime.now(timezone.utc).date()
    citas_programadas = [
        row
        for row in acciones
        if parse_iso_date(row.get("fecha")) and parse_iso_date(row.get("fecha")) >= today
    ]
    primas_total = sum(parse_money_value(row.get("prima_total")) for row in seguros_rows)
    realizado = sum(
        parse_money_value(row.get("importe"))
        for row in trabajos
        if "FINAL" in normalize_lookup_text(row.get("estado"))
    )
    cobrado = fact_total
    rentabilidad = cobrado - realizado

    profesionales = {
        "gestoria": {},
        "seguros": {
            "polizas_total": len(seguros_rows),
            "companias": sorted(
                {str(row.get("compania") or "").strip() for row in seguros_rows if str(row.get("compania") or "").strip()}
            ),
        },
    }
    gestoria_row = conn.execute(
        """
        SELECT tipo_cliente, mod_fiscal, mod_laboral, mod_contable, mod_renta, mod_registro, mod_trafico, mod_puntuales, renta_detalles
        FROM cliente_gestoria
        WHERE cliente_id = ?
        """,
        (cliente_id,),
    ).fetchone()
    if gestoria_row:
        gestoria_payload = dict(gestoria_row)
        renta_payload = parse_renta_detalles_payload(gestoria_payload.get("renta_detalles"))
        gestoria_payload["renta_notes"] = renta_payload.get("notes", "")
        gestoria_payload["renta_entries"] = sanitize_renta_entries(renta_payload.get("entries", []))
        gestoria_payload["renta_related_cliente_id"] = renta_payload.get("related_cliente_id", "")
        gestoria_payload["renta_related_relation_id"] = renta_payload.get("related_relation_id", "")
        gestoria_payload["renta_declaracion_conjunta"] = renta_payload.get("declaracion_conjunta", 0)
        profesionales["gestoria"] = gestoria_payload
    renta_entries = profesionales.get("gestoria", {}).get("renta_entries") or []
    renta_docs = [
        row
        for row in docs_rows
        if normalize_service_key(row.get("referencia_tipo") or row.get("tipo")) in {"gestoria", "renta"}
        and (
            normalize_lookup_text(row.get("referencia_tipo")) == "RENTA"
            or "RENTA" in normalize_lookup_text(row.get("tipo"))
            or "RENTA" in normalize_lookup_text(row.get("nombre"))
            or "MODELO 100" in normalize_lookup_text(row.get("tipo"))
            or "MODELO 100" in normalize_lookup_text(row.get("nombre"))
        )
    ]
    modelo100_docs = [
        row
        for row in renta_docs
        if "MODELO 100" in normalize_lookup_text(row.get("tipo"))
        or "MODELO 100" in normalize_lookup_text(row.get("nombre"))
        or normalize_lookup_text(row.get("referencia_tipo")) == "RENTA"
    ]

    def _renta_year_from_doc(row):
        text = " ".join(
            str(row.get(key) or "")
            for key in ("nombre", "tipo", "referencia_id", "notas", "fecha")
        )
        match = re.search(r"\b(20[0-9]{2})\b", text)
        return match.group(1) if match else ""

    renta_years = {
        str(entry.get("ejercicio") or "").strip()
        for entry in renta_entries
        if re.match(r"^20[0-9]{2}$", str(entry.get("ejercicio") or "").strip())
    }
    renta_years.update(
        year
        for year in (_renta_year_from_doc(row) for row in modelo100_docs)
        if re.match(r"^20[0-9]{2}$", year or "")
    )
    latest_renta_year = sorted(renta_years, reverse=True)[0] if renta_years else ""
    priced_rentas = [
        entry
        for entry in renta_entries
        if (parse_money_value(entry.get("precio_servicio")) or 0) > 0
    ]
    unpaid_rentas = [
        entry
        for entry in priced_rentas
        if str(entry.get("cobrada") or "").strip().lower() not in {"1", "true", "yes", "si", "sí", "on"}
    ]
    paid_rentas = [entry for entry in priced_rentas if entry not in unpaid_rentas]
    renta_pending_presentation = [
        entry
        for entry in renta_entries
        if normalize_renta_presentacion_status(entry.get("estado_presentacion") or entry.get("doc_status")) == "Borrador"
    ]
    gestoria_open_work = [
        row
        for row in trabajos
        if "FINAL" not in normalize_lookup_text(row.get("estado"))
        and "CANCEL" not in normalize_lookup_text(row.get("estado"))
    ]
    gestoria_open_actions = [
        row
        for row in acciones
        if normalize_service_key(row.get("servicio")) == "gestoria"
        and all(
            token not in normalize_lookup_text(row.get("estado"))
            for token in ("HECHO", "FINAL", "CANCEL")
        )
    ]
    renta_docs_with_file = [row for row in renta_docs if row.get("doc_key") or row.get("doc_url")]
    renta_docs_without_file = [row for row in renta_docs if not (row.get("doc_key") or row.get("doc_url"))]
    gestoria_alerts = []
    if profesionales.get("gestoria") and not modelo100_docs:
        gestoria_alerts.append({"level": "warning", "label": "Sin Modelo 100 en documentación"})
    if renta_pending_presentation:
        gestoria_alerts.append({"level": "warning", "label": f"{len(renta_pending_presentation)} renta(s) pendientes de presentación"})
    if unpaid_rentas:
        gestoria_alerts.append({"level": "warning", "label": f"{len(unpaid_rentas)} renta(s) pendientes de cobro"})
    if gestoria_open_work:
        gestoria_alerts.append({"level": "info", "label": f"{len(gestoria_open_work)} trabajo(s) abiertos"})
    if renta_docs_without_file:
        gestoria_alerts.append({"level": "warning", "label": f"{len(renta_docs_without_file)} documento(s) sin PDF"})
    cliente_missing_fields = [
        label
        for field, label in (
            ("nif", "NIF"),
            ("telefono", "teléfono"),
            ("email", "email"),
        )
        if not str(cliente[field] if field in cliente.keys() else "").strip()
    ]
    if cliente_missing_fields:
        gestoria_alerts.append({"level": "warning", "label": f"Falta {', '.join(cliente_missing_fields)}"})
    if unpaid_rentas:
        status_global = "Pendiente cobro"
    elif renta_pending_presentation:
        status_global = "Pendiente presentación"
    elif renta_docs_without_file or not modelo100_docs:
        status_global = "Pendiente documentación"
    elif gestoria_open_work or gestoria_open_actions:
        status_global = "En curso"
    elif profesionales.get("gestoria"):
        status_global = "Al día"
    else:
        status_global = "Sin gestoría"

    def _doc_match(*tokens):
        normalized_tokens = [normalize_lookup_text(token) for token in tokens if str(token or "").strip()]
        if not normalized_tokens:
            return False
        for row in docs_rows:
            haystack = normalize_lookup_text(
                " ".join(str(row.get(key) or "") for key in ("referencia_tipo", "nombre", "tipo", "estado", "notas"))
            )
            if all(token in haystack for token in normalized_tokens):
                return True
        return False

    checklist = [
        {
            "key": "modelo100",
            "label": "Modelo 100",
            "done": bool(modelo100_docs),
            "count": len(modelo100_docs),
            "action": "Subir o revisar Modelo 100",
        },
        {
            "key": "dni",
            "label": "DNI/NIE",
            "done": _doc_match("DNI") or bool(str(cliente["nif"] if "nif" in cliente.keys() else "").strip()),
            "count": 1 if (_doc_match("DNI") or bool(str(cliente["nif"] if "nif" in cliente.keys() else "").strip())) else 0,
            "action": "Solicitar DNI/NIE actualizado",
        },
        {
            "key": "datos_fiscales",
            "label": "Datos fiscales",
            "done": _doc_match("DATOS FISCALES"),
            "count": 1 if _doc_match("DATOS FISCALES") else 0,
            "action": "Solicitar datos fiscales",
        },
        {
            "key": "autorizacion",
            "label": "Autorización / firma",
            "done": _doc_match("AUTORIZ") or _doc_match("FIRMA"),
            "count": 1 if (_doc_match("AUTORIZ") or _doc_match("FIRMA")) else 0,
            "action": "Solicitar autorización o firma",
        },
        {
            "key": "cobro",
            "label": "Cobro renta",
            "done": not unpaid_rentas,
            "count": len(paid_rentas),
            "action": "Marcar o reclamar cobro",
        },
    ]
    checklist_done = sum(1 for item in checklist if item.get("done"))
    next_actions = []
    if unpaid_rentas:
        next_actions.append({
            "priority": "alta",
            "label": "Reclamar cobro de renta",
            "meta": f"{len(unpaid_rentas)} pendiente(s) · {sum(parse_money_value(entry.get('precio_servicio')) or 0 for entry in unpaid_rentas):.2f} €",
            "target": "renta",
        })
    if renta_pending_presentation:
        next_actions.append({
            "priority": "alta",
            "label": "Presentar renta pendiente",
            "meta": f"{len(renta_pending_presentation)} borrador(es)",
            "target": "renta",
        })
    for item in checklist:
        if not item.get("done"):
            next_actions.append({
                "priority": "media",
                "label": item.get("action") or item.get("label"),
                "meta": item.get("label"),
                "target": "docs",
            })
    for row in gestoria_open_work[:3]:
        next_actions.append({
            "priority": "media",
            "label": row.get("tipo_trabajo") or "Trabajo abierto",
            "meta": " · ".join(str(row.get(key) or "").strip() for key in ("estado", "responsable", "fecha_fin") if str(row.get(key) or "").strip()),
            "target": "trabajos",
        })
    for row in gestoria_open_actions[:3]:
        next_actions.append({
            "priority": "media",
            "label": row.get("tipo") or "Acción abierta",
            "meta": " · ".join(str(row.get(key) or "").strip() for key in ("fecha", "hora", "responsable") if str(row.get(key) or "").strip()),
            "target": "agenda",
        })

    timeline = []
    for row in modelo100_docs[:20]:
        timeline.append({
            "date": row.get("fecha") or "",
            "kind": "documento",
            "title": row.get("nombre") or "Modelo 100",
            "meta": row.get("estado") or row.get("tipo") or "",
        })
    for entry in renta_entries[:20]:
        timeline.append({
            "date": entry.get("presentacion_fecha") or entry.get("fecha_cobro") or "",
            "kind": "renta",
            "title": f"Renta {entry.get('ejercicio') or ''}".strip(),
            "meta": " · ".join(str(value).strip() for value in (entry.get("estado_presentacion") or entry.get("doc_status"), entry.get("responsable")) if str(value or "").strip()),
        })
    for row in trabajos[:20]:
        timeline.append({
            "date": row.get("fecha_fin") or row.get("fecha_inicio") or "",
            "kind": "trabajo",
            "title": row.get("tipo_trabajo") or "Trabajo",
            "meta": row.get("estado") or "",
        })
    for row in acciones[:20]:
        if normalize_service_key(row.get("servicio")) != "gestoria":
            continue
        timeline.append({
            "date": row.get("fecha") or "",
            "kind": "accion",
            "title": row.get("tipo") or "Acción",
            "meta": " · ".join(str(row.get(key) or "").strip() for key in ("hora", "estado", "responsable") if str(row.get(key) or "").strip()),
        })
    timeline = sorted(
        timeline,
        key=lambda item: str(item.get("date") or ""),
        reverse=True,
    )[:12]
    gestoria_summary = {
        "activo": bool(profesionales.get("gestoria")),
        "status_global": status_global,
        "mod_renta": int(profesionales.get("gestoria", {}).get("mod_renta") or 0),
        "latest_renta_year": latest_renta_year,
        "rentas_total": len(renta_entries),
        "rentas_presentadas": len([entry for entry in renta_entries if normalize_renta_presentacion_status(entry.get("estado_presentacion") or entry.get("doc_status")) == "Presentada"]),
        "rentas_pendientes_presentacion": len(renta_pending_presentation),
        "rentas_con_precio": len(priced_rentas),
        "rentas_cobradas": len(paid_rentas),
        "rentas_pendientes_cobro": len(unpaid_rentas),
        "importe_rentas": sum(parse_money_value(entry.get("precio_servicio")) or 0 for entry in priced_rentas),
        "importe_rentas_cobrado": sum(parse_money_value(entry.get("precio_servicio")) or 0 for entry in paid_rentas),
        "importe_rentas_pendiente": sum(parse_money_value(entry.get("precio_servicio")) or 0 for entry in unpaid_rentas),
        "renta_docs_total": len(renta_docs),
        "modelo100_docs_total": len(modelo100_docs),
        "renta_docs_con_pdf": len(renta_docs_with_file),
        "renta_docs_sin_pdf": len(renta_docs_without_file),
        "trabajos_abiertos": len(gestoria_open_work),
        "acciones_abiertas": len(gestoria_open_actions),
        "alerts": gestoria_alerts[:6],
        "checklist": checklist,
        "checklist_done": checklist_done,
        "checklist_total": len(checklist),
        "next_actions": next_actions[:8],
        "timeline": timeline,
    }
    relaciones = fetch_cliente_relaciones(conn, cliente_id)
    asesoramientos_table = conn.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'asesoramientos_financiacion'"
    ).fetchone()
    datos_economicos = None
    if asesoramientos_table:
        datos_economicos = conn.execute(
            """
            SELECT *
            FROM asesoramientos_financiacion
            WHERE cliente1_id = ? OR cliente2_id = ?
            ORDER BY datetime(COALESCE(updated_at, created_at)) DESC
            LIMIT 1
            """,
            (cliente_id, cliente_id),
        ).fetchone()

    return {
        "cliente": dict(cliente),
        "datos_personales": dict(cliente),
        "empresas": empresas,
        "relaciones": relaciones,
        "servicios_activos": service_keys,
        "datos_profesionales_por_servicio": profesionales,
        "datos_economicos": dict(datos_economicos) if datos_economicos else {},
        "servicios": {
            "seguros": seguros_rows,
            "gestoria_trabajos": trabajos,
            "acciones": acciones,
        },
        "documentacion": {
            "all": docs_rows,
            "by_service": docs_by_service,
        },
        "facturas": facturas,
        "historico": historico[:500],
        "dashboard": {
            "rentabilidad": {
                "realizado": realizado,
                "cobrado": cobrado,
                "margen": rentabilidad,
            },
            "primas_total": primas_total,
            "tareas_pendientes": pendientes_trabajos + pendientes_acciones,
            "citas_programadas": len(citas_programadas),
            "proxima_cita": min(
                [row["fecha"] for row in citas_programadas if row.get("fecha")],
                default="",
            ),
            "gestoria": gestoria_summary,
            "series": {
                "rentabilidad": [
                    {"label": "Realizado", "value": realizado},
                    {"label": "Cobrado", "value": cobrado},
                    {"label": "Margen", "value": rentabilidad},
                ],
                "actividad": [
                    {"label": "Primas", "value": primas_total},
                    {"label": "Pendientes", "value": pendientes_trabajos + pendientes_acciones},
                    {"label": "Citas", "value": len(citas_programadas)},
                ],
            },
        },
    }

def ensure_cliente_for_financiacion(conn, empresa_id, nombre, nif, now, extra=None):
    if not nombre:
        return None
    try:
        ensure_column(conn, "clientes", "empresa_id", "empresa_id TEXT")
    except Exception:
        pass
    empresa_id = str(empresa_id or "").strip()
    nombre = normalize_person_name(nombre or "")
    nif = normalize_nif(nif or "")
    extra = extra or {}
    cliente = None
    if nif:
        cliente = conn.execute(
            """
            SELECT c.id
            FROM clientes c
            LEFT JOIN clientes_empresas ce
              ON ce.cliente_id = c.id
             AND ce.empresa_id = ?
             AND LOWER(TRIM(COALESCE(ce.servicio, ''))) = 'financiaciones'
            WHERE c.nif = ?
              AND (c.empresa_id = ? OR ce.id IS NOT NULL OR COALESCE(TRIM(c.empresa_id), '') = '')
            LIMIT 1
            """,
            (empresa_id, nif, empresa_id),
        ).fetchone()
    if not cliente:
        cliente = conn.execute(
            """
            SELECT c.id
            FROM clientes c
            LEFT JOIN clientes_empresas ce
              ON ce.cliente_id = c.id
             AND ce.empresa_id = ?
             AND LOWER(TRIM(COALESCE(ce.servicio, ''))) = 'financiaciones'
            WHERE LOWER(TRIM(COALESCE(c.nombre, ''))) = LOWER(TRIM(?))
              AND (c.empresa_id = ? OR ce.id IS NOT NULL OR COALESCE(TRIM(c.empresa_id), '') = '')
            LIMIT 1
            """,
            (empresa_id, nombre, empresa_id),
        ).fetchone()
    if not cliente:
        tipo_persona = None
        if nif:
            if re.match(r"^[0-9]{8}[A-Z]$", nif):
                tipo_persona = "Física"
            elif re.match(r"^[A-Z][0-9]{7}[0-9A-Z]$", nif):
                tipo_persona = "Jurídica"
        cliente_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO clientes (
              id, empresa_id, nombre, tipo_persona, nif, telefono, email, fecha_nacimiento, direccion,
              procedencia_canal, procedencia_detalle, procedencia_user_id,
              estado, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                cliente_id,
                empresa_id or None,
                nombre,
                tipo_persona,
                nif or None,
                extra.get("telefono"),
                extra.get("email"),
                extra.get("fecha_nacimiento"),
                extra.get("direccion"),
                "",
                "",
                None,
                "Activo",
                now,
                now,
            ),
        )
    else:
        cliente_id = cliente["id"]
        updates = {}
        if empresa_id:
            try:
                conn.execute(
                    """
                    UPDATE clientes
                    SET empresa_id = COALESCE(NULLIF(TRIM(COALESCE(empresa_id, '')), ''), ?),
                        updated_at = datetime(?)
                    WHERE id = ?
                    """,
                    (empresa_id, now, cliente_id),
                )
            except Exception:
                pass
        if nif:
            updates["nif"] = nif
        for key in ("telefono", "email", "fecha_nacimiento", "direccion"):
            value = extra.get(key)
            if value:
                updates[key] = value
        if updates:
            set_clause = ", ".join([f"{key} = COALESCE({key}, ?)" for key in updates])
            values = list(updates.values()) + [now, cliente_id]
            conn.execute(
                f"UPDATE clientes SET {set_clause}, updated_at = datetime(?) WHERE id = ?",
                values,
            )
    link = conn.execute(
        """
        SELECT id FROM clientes_empresas
        WHERE cliente_id = ? AND empresa_id = ? AND LOWER(servicio) = 'financiaciones'
        LIMIT 1
        """,
        (cliente_id, empresa_id),
    ).fetchone()
    if not link:
        conn.execute(
            """
            INSERT INTO clientes_empresas (
              id, cliente_id, empresa_id, servicio, estado,
              fecha_inicio, fecha_fin, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                cliente_id,
                empresa_id,
                "financiaciones",
                "Activo",
                None,
                None,
                now,
                now,
            ),
        )
    return cliente_id


def get_empresa_by_nombre(conn, nombre):
    nombre = str(nombre or "").strip()
    if not nombre:
        return None
    return conn.execute(
        "SELECT * FROM empresas WHERE nombre = ? LIMIT 1",
        (nombre,),
    ).fetchone()


def build_financiacion_context_note(inmueble_row, action_row):
    parts = []
    direccion = str((inmueble_row or {}).get("direccion") or "").strip()
    if direccion:
        parts.append(f"Inmueble: {direccion}")
    if inmueble_row:
        precio = parse_money_value(inmueble_row.get("precio_objetivo"))
        if precio > 0:
            parts.append(f"Precio objetivo: {precio:.2f} EUR")
    if action_row:
        fecha = str(action_row.get("fecha") or "").strip()
        if fecha:
            parts.append(f"Cita origen: {fecha}")
    return " | ".join(parts)


def ensure_financiacion_opportunity_from_inmo(
    conn,
    fin_empresa_id,
    inmueble_row,
    cliente_row,
    action_row,
    now,
):
    cliente_id = str((cliente_row or {}).get("id") or "").strip()
    inmueble_id = str((inmueble_row or {}).get("id") or "").strip()
    action_id = str((action_row or {}).get("id") or "").strip()
    if not fin_empresa_id or not cliente_id:
        return None
    existing = conn.execute(
        """
        SELECT id
        FROM acciones
        WHERE servicio = 'financiaciones'
          AND empresa_id = ?
          AND cliente_id = ?
          AND inmueble_id = ?
          AND tipo = 'Oportunidad hipotecaria'
          AND notas LIKE ?
        LIMIT 1
        """,
        (fin_empresa_id, cliente_id, inmueble_id or None, f"%Acción origen: {action_id}%"),
    ).fetchone()
    if existing:
        return existing["id"]
    context_note = build_financiacion_context_note(inmueble_row, action_row)
    notas = f"Lead generado desde visita inmobiliaria. Acción origen: {action_id}."
    if context_note:
        notas = f"{notas} {context_note}"
    opportunity_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO acciones (
          id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
          fecha, hora, tipo, responsable, estado, notas, created_at, updated_at
        ) VALUES (
          ?, ?, 'financiaciones', ?, ?, ?, date('now'), '10:00', ?, ?, 'Pendiente', ?, datetime(?), datetime(?)
        )
        """,
        (
            opportunity_id,
            fin_empresa_id,
            cliente_id,
            inmueble_id or None,
            str((cliente_row or {}).get("nombre") or "").strip(),
            "Oportunidad hipotecaria",
            str((action_row or {}).get("responsable") or "").strip() or None,
            notas,
            now,
            now,
        ),
    )
    return opportunity_id


def ensure_financiacion_asesoramiento_from_inmo(
    conn,
    fin_empresa_id,
    inmueble_row,
    cliente_row,
    action_row,
    now,
    *,
    fin_data=None,
):
    cliente_id = str((cliente_row or {}).get("id") or "").strip()
    inmueble_id = str((inmueble_row or {}).get("id") or "").strip()
    action_id = str((action_row or {}).get("id") or "").strip()
    if not fin_empresa_id or not cliente_id:
        return None, []
    existing = conn.execute(
        """
        SELECT *
        FROM asesoramientos_financiacion
        WHERE empresa_id = ?
          AND cliente1_id = ?
          AND COALESCE(inmueble_id, '') = ?
          AND COALESCE(accion_origen_id, '') = ?
        LIMIT 1
        """,
        (fin_empresa_id, cliente_id, inmueble_id, action_id),
    ).fetchone()
    profesion = conn.execute(
        """
        SELECT actividad
        FROM cliente_profesional
        WHERE cliente_id = ?
        ORDER BY principal DESC, created_at ASC
        LIMIT 1
        """,
        (cliente_id,),
    ).fetchone()
    fin_data = fin_data or {}
    context_note = build_financiacion_context_note(inmueble_row, action_row)
    notas = "Asesoramiento generado desde Inmobiliaria."
    if context_note:
        notas = f"{notas} {context_note}"
    notas_extra = str(fin_data.get("notas") or "").strip()
    if notas_extra:
        notas = f"{notas} {notas_extra}"
    ingreso1_val = parse_money_value(fin_data.get("cliente1_ingresos"))
    ingreso2_val = parse_money_value(fin_data.get("cliente2_ingresos"))
    ingresos_conjuntos_val = parse_money_value(fin_data.get("ingresos_conjuntos"))
    if ingresos_conjuntos_val <= 0:
        ingresos_conjuntos_val = round((ingreso1_val or 0.0) + (ingreso2_val or 0.0), 2)
    aportacion_val = parse_money_value(fin_data.get("aportacion_cv"))
    if existing:
        updates = {}
        for field in (
            "cliente1_nombre",
            "cliente1_dni",
            "cliente1_telefono",
            "cliente1_email",
            "cliente1_fecha_nacimiento",
            "cliente1_estado_civil",
            "cliente1_hijos",
            "cliente1_profesion",
            "cliente1_tipo_contrato",
            "cliente1_tiempo_contrato",
            "cliente1_patrimonio",
            "cliente1_prestamos",
            "cliente2_nombre",
            "cliente2_dni",
            "cliente2_telefono",
            "cliente2_email",
            "cliente2_fecha_nacimiento",
            "cliente2_estado_civil",
            "cliente2_hijos",
            "cliente2_profesion",
            "cliente2_tipo_contrato",
            "cliente2_tiempo_contrato",
            "cliente2_patrimonio",
            "cliente2_prestamos",
            "entidades_financieras",
            "avalistas",
        ):
            incoming = str(fin_data.get(field) or "").strip()
            if incoming and not str(existing[field] or "").strip():
                updates[field] = incoming
        if ingreso1_val > 0 and not parse_money_value(existing["cliente1_ingresos"]):
            updates["cliente1_ingresos"] = ingreso1_val
        if ingreso2_val > 0 and not parse_money_value(existing["cliente2_ingresos"]):
            updates["cliente2_ingresos"] = ingreso2_val
        if ingresos_conjuntos_val > 0 and not parse_money_value(existing["ingresos_conjuntos"]):
            updates["ingresos_conjuntos"] = ingresos_conjuntos_val
        if aportacion_val > 0 and not parse_money_value(existing["aportacion_cv"]):
            updates["aportacion_cv"] = aportacion_val
        if not str(existing["cliente1_profesion"] or "").strip() and profesion and str(profesion["actividad"] or "").strip():
            updates["cliente1_profesion"] = str(profesion["actividad"] or "").strip()
        if notas and not str(existing["notas"] or "").strip():
            updates["notas"] = notas
        if updates:
            set_clause = ", ".join([f"{key} = ?" for key in updates])
            values = list(updates.values()) + [now, existing["id"]]
            conn.execute(
                f"UPDATE asesoramientos_financiacion SET {set_clause}, updated_at = datetime(?) WHERE id = ?",
                values,
            )
        asesoramiento_id = existing["id"]
    else:
        asesoramiento_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO asesoramientos_financiacion (
              id, empresa_id, origen, inmueble_id, accion_origen_id, inmobiliaria_asesor, asesor, fecha, estado,
              cliente1_id, cliente1_nombre, cliente1_dni, cliente1_telefono, cliente1_email,
              cliente1_fecha_nacimiento, cliente1_estado_civil, cliente1_hijos, cliente1_profesion, cliente1_tipo_contrato,
              cliente1_tiempo_contrato, cliente1_ingresos, cliente1_patrimonio, cliente1_prestamos,
              cliente2_nombre, cliente2_dni, cliente2_telefono, cliente2_email, cliente2_fecha_nacimiento,
              cliente2_estado_civil, cliente2_hijos, cliente2_profesion, cliente2_tipo_contrato, cliente2_tiempo_contrato,
              cliente2_ingresos, cliente2_patrimonio, cliente2_prestamos,
              ingresos_conjuntos, entidades_financieras, avalistas, aportacion_cv, notas, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                asesoramiento_id,
                fin_empresa_id,
                "Inmobiliaria",
                inmueble_id or None,
                action_id or None,
                str((action_row or {}).get("responsable") or "").strip() or None,
                None,
                str((action_row or {}).get("fecha") or "").strip() or datetime.now().strftime("%Y-%m-%d"),
                "En estudio",
                cliente_id,
                str(fin_data.get("cliente1_nombre") or (cliente_row or {}).get("nombre") or "").strip() or None,
                normalize_nif(fin_data.get("cliente1_dni") or (cliente_row or {}).get("nif")),
                str(fin_data.get("cliente1_telefono") or (cliente_row or {}).get("telefono") or "").strip() or None,
                normalize_email(fin_data.get("cliente1_email") or (cliente_row or {}).get("email")),
                str(fin_data.get("cliente1_fecha_nacimiento") or (cliente_row or {}).get("fecha_nacimiento") or "").strip() or None,
                str(fin_data.get("cliente1_estado_civil") or "").strip() or None,
                str(fin_data.get("cliente1_hijos") or "").strip() or None,
                str(fin_data.get("cliente1_profesion") or (profesion["actividad"] if profesion else "") or "").strip() or None,
                str(fin_data.get("cliente1_tipo_contrato") or "").strip() or None,
                str(fin_data.get("cliente1_tiempo_contrato") or "").strip() or None,
                ingreso1_val or None,
                str(fin_data.get("cliente1_patrimonio") or "").strip() or None,
                str(fin_data.get("cliente1_prestamos") or "").strip() or None,
                str(fin_data.get("cliente2_nombre") or "").strip() or None,
                normalize_nif(fin_data.get("cliente2_dni")),
                str(fin_data.get("cliente2_telefono") or "").strip() or None,
                normalize_email(fin_data.get("cliente2_email")),
                str(fin_data.get("cliente2_fecha_nacimiento") or "").strip() or None,
                str(fin_data.get("cliente2_estado_civil") or "").strip() or None,
                str(fin_data.get("cliente2_hijos") or "").strip() or None,
                str(fin_data.get("cliente2_profesion") or "").strip() or None,
                str(fin_data.get("cliente2_tipo_contrato") or "").strip() or None,
                str(fin_data.get("cliente2_tiempo_contrato") or "").strip() or None,
                ingreso2_val or None,
                str(fin_data.get("cliente2_patrimonio") or "").strip() or None,
                str(fin_data.get("cliente2_prestamos") or "").strip() or None,
                ingresos_conjuntos_val or None,
                str(fin_data.get("entidades_financieras") or "").strip() or None,
                str(fin_data.get("avalistas") or "").strip() or None,
                aportacion_val or None,
                notas,
                now,
                now,
            ),
        )
    row = conn.execute(
        "SELECT * FROM asesoramientos_financiacion WHERE id = ? LIMIT 1",
        (asesoramiento_id,),
    ).fetchone()
    missing = fin_missing_fields(row) if row else []
    fin_sync_missing_action(
        conn,
        fin_empresa_id,
        asesoramiento_id,
        cliente_id,
        str((cliente_row or {}).get("nombre") or "").strip(),
        missing,
        now,
    )
    return asesoramiento_id, missing

