def ensure_crm_trash_schema(conn):
    """
    Tabla de "papelera" para recuperar borrados accidentales.
    No implementa soft-delete; simplemente guarda un snapshot JSON antes de un DELETE.
    """
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS crm_trash (
              id TEXT PRIMARY KEY,
              table_name TEXT NOT NULL,
              row_id TEXT NOT NULL,
              empresa_id TEXT,
              workspace_id TEXT,
              deleted_by TEXT,
              reason TEXT,
              row_json TEXT NOT NULL,
              created_at TEXT NOT NULL
            )
            """
        )
    except Exception:
        return
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_crm_trash_table_row ON crm_trash (table_name, row_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_crm_trash_empresa ON crm_trash (empresa_id, created_at)")
    except Exception:
        pass


def _row_to_dict(row):
    if row is None:
        return {}
    try:
        return dict(row)
    except Exception:
        try:
            if hasattr(row, "keys"):
                return {k: row[k] for k in row.keys()}
        except Exception:
            pass
    return {}


def trash_backup_row(conn, table_name, row_id, *, empresa_id=None, workspace_id=None, deleted_by=None, reason=None, now="now"):
    """
    Guarda en `crm_trash` el registro actual antes de borrarlo.
    Best-effort: nunca debe romper el borrado si falla el backup.
    """
    try:
        ensure_crm_trash_schema(conn)
    except Exception:
        return
    try:
        table = str(table_name or "").strip()
        rid = str(row_id or "").strip()
        if not table or not rid:
            return
        row = conn.execute(f"SELECT * FROM {table} WHERE id = ? LIMIT 1", (rid,)).fetchone()
        if not row:
            return
        payload = _row_to_dict(row)
        conn.execute(
            """
            INSERT INTO crm_trash (
              id, table_name, row_id, empresa_id, workspace_id, deleted_by, reason, row_json, created_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                table,
                rid,
                str(empresa_id or payload.get("empresa_id") or "").strip() or None,
                str(workspace_id or "").strip() or None,
                str(deleted_by or "").strip() or None,
                str(reason or "").strip() or None,
                json.dumps(payload, ensure_ascii=False, default=str),
                now,
            ),
        )
    except Exception:
        return


def ensure_usuarios_schema(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS usuarios (
          id TEXT PRIMARY KEY,
          nombre TEXT NOT NULL,
          apellido TEXT,
          usuario TEXT UNIQUE,
          email TEXT UNIQUE,
          servicio TEXT,
          rol TEXT,
          registro_horario_activo INTEGER DEFAULT 0,
          password_hash TEXT,
          activo INTEGER DEFAULT 1,
          invite_token TEXT,
          invite_expires_at TEXT,
          invite_sent_at TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        )
        """
    )
    ensure_column(conn, "usuarios", "apellido", "apellido TEXT")
    ensure_column(conn, "usuarios", "usuario", "usuario TEXT")
    ensure_column(conn, "usuarios", "email", "email TEXT")
    ensure_column(conn, "usuarios", "servicio", "servicio TEXT")
    ensure_column(conn, "usuarios", "registro_horario_activo", "registro_horario_activo INTEGER DEFAULT 0")
    ensure_column(conn, "usuarios", "password_hash", "password_hash TEXT")
    ensure_column(conn, "usuarios", "invite_token", "invite_token TEXT")
    ensure_column(conn, "usuarios", "invite_expires_at", "invite_expires_at TEXT")
    ensure_column(conn, "usuarios", "invite_sent_at", "invite_sent_at TEXT")
    users_count = conn.execute("SELECT COUNT(*) AS total FROM usuarios").fetchone()
    total_users = 0
    if users_count:
        try:
            total_users = users_count["total"]
        except (TypeError, KeyError, IndexError):
            total_users = users_count[0]
    if total_users == 0:
        conn.execute(
            "INSERT INTO usuarios (id, nombre, apellido, usuario, email, servicio, rol, activo, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))",
            (os.urandom(16).hex(), "Administrador", "General", "admin", "admin@liv.local", "Administración", "Administrador", 1),
        )
    flagged_count_row = conn.execute(
        "SELECT COUNT(*) AS total FROM usuarios WHERE COALESCE(registro_horario_activo, 0) = 1"
    ).fetchone()
    flagged_total = 0
    if flagged_count_row:
        try:
            flagged_total = int(flagged_count_row["total"] or 0)
        except (TypeError, KeyError, IndexError, ValueError):
            flagged_total = int(flagged_count_row[0] or 0)
    if flagged_total == 0:
        conn.execute(
            """
            UPDATE usuarios
            SET registro_horario_activo = 1
            WHERE COALESCE(activo, 1) = 1
              AND (
                LOWER(COALESCE(servicio, '')) LIKE '%gestor%'
                OR LOWER(COALESCE(servicio, '')) LIKE '%inmobili%'
                OR LOWER(COALESCE(servicio, '')) LIKE '%seguro%'
                OR LOWER(COALESCE(servicio, '')) LIKE '%finca%'
                OR LOWER(COALESCE(servicio, '')) LIKE '%financia%'
                OR LOWER(COALESCE(servicio, '')) LIKE '%obra%'
                OR LOWER(COALESCE(servicio, '')) LIKE '%reforma%'
              )
            """
        )
    # Unicidad por "usuario/email" ignorando mayúsculas/espacios: mejor esfuerzo (puede fallar si ya hay duplicados).
    try:
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_usuarios_usuario_ci ON usuarios(LOWER(TRIM(usuario)))")
    except Exception:
        pass
    try:
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_usuarios_email_ci ON usuarios(LOWER(TRIM(email)))")
    except Exception:
        pass


def ensure_ocr_tables(db_path):
    conn = open_sqlite_conn(db_path, with_row_factory=False)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS ocr_jobs (
              id TEXT PRIMARY KEY,
              kind TEXT,
              status TEXT,
              payload_json TEXT,
              result_json TEXT,
              error TEXT,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL,
              started_at TEXT,
              finished_at TEXT
            )
            """
        )
        conn.commit()
    finally:
        try:
            conn.close()
        except Exception:
            pass


def ensure_auth_invites_table(conn):
    """
    Tabla de invitaciones para activación de contraseña.
    Compatible con SQLite y Postgres (vía capa de compatibilidad).
    """
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS auth_invites (
              token TEXT PRIMARY KEY,
              user_id TEXT NOT NULL,
              expires_at TEXT,
              created_at TEXT NOT NULL,
              sent_at TEXT,
              used_at TEXT,
              revoked_at TEXT,
              notes TEXT
            )
            """
        )
    except Exception:
        return
    # Best-effort: evolutivo
    try:
        ensure_column(conn, "auth_invites", "expires_at", "expires_at TEXT")
        ensure_column(conn, "auth_invites", "sent_at", "sent_at TEXT")
        ensure_column(conn, "auth_invites", "used_at", "used_at TEXT")
        ensure_column(conn, "auth_invites", "revoked_at", "revoked_at TEXT")
        ensure_column(conn, "auth_invites", "notes", "notes TEXT")
    except Exception:
        pass
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_auth_invites_user_id ON auth_invites(user_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_auth_invites_expires ON auth_invites(expires_at, used_at, revoked_at)")
    except Exception:
        pass
    # Importante: este helper NO debe cerrar la conexión recibida.
    # El caller gestiona el ciclo de vida (SQLite/Postgres).


def fetch_workspace_rows(conn):
    rows = conn.execute(
        """
        SELECT
          w.id,
          w.nombre,
          w.slug,
          w.estado,
          w.plan,
          w.kind,
          w.descripcion,
          w.logo_url,
          w.primary_color,
          w.accent_color,
          COUNT(DISTINCT we.empresa_id) AS empresas_total,
          COUNT(DISTINCT CASE WHEN COALESCE(wm.enabled, 0) = 1 THEN wm.modulo_key END) AS modulos_activos
        FROM workspaces w
        LEFT JOIN workspace_empresas we ON we.workspace_id = w.id
        LEFT JOIN workspace_modulos wm ON wm.workspace_id = w.id
        GROUP BY w.id, w.nombre, w.slug, w.estado, w.plan, w.kind, w.descripcion, w.logo_url, w.primary_color, w.accent_color
        ORDER BY w.nombre COLLATE NOCASE ASC
        """
    ).fetchall()
    return [dict(row) for row in rows]


def fetch_workspace_rows_for_user(conn, session):
    """
    Legacy: si no activamos el enforcement multi-tenant, devolvemos todo como siempre.
    En modo enforce: admins ven todo; resto ve solo workspaces donde es miembro.
    """
    if workspace_actor_is_privileged(conn, session):
        return fetch_workspace_rows(conn)
    user_id = str((session or {}).get("user_id") or "").strip()
    if not user_id:
        return [] if WORKSPACE_MEMBERSHIP_ENFORCE else fetch_workspace_rows(conn)

    membership_rows = []
    try:
        membership_rows = conn.execute(
            """
            SELECT
              w.id,
              w.nombre,
              w.slug,
              w.estado,
              w.plan,
              w.kind,
              w.descripcion,
              w.logo_url,
              w.primary_color,
              w.accent_color,
              COALESCE(mem.rol, '') AS member_role,
              COUNT(DISTINCT we.empresa_id) AS empresas_total,
              COUNT(DISTINCT CASE WHEN COALESCE(wm.enabled, 0) = 1 THEN wm.modulo_key END) AS modulos_activos
            FROM workspaces w
            JOIN workspace_miembros mem ON mem.workspace_id = w.id AND mem.usuario_id = ?
            LEFT JOIN workspace_empresas we ON we.workspace_id = w.id
            LEFT JOIN workspace_modulos wm ON wm.workspace_id = w.id
            GROUP BY w.id, w.nombre, w.slug, w.estado, w.plan, w.kind, w.descripcion, w.logo_url, w.primary_color, w.accent_color, mem.rol
            ORDER BY w.nombre COLLATE NOCASE ASC
            """,
            (user_id,),
        ).fetchall()
    except Exception:
        membership_rows = []

    if WORKSPACE_MEMBERSHIP_ENFORCE:
        return [dict(row) for row in (membership_rows or [])]

    # Soft membership: si ya existen filas de miembros para el usuario, devolvemos solo esas (evita que un
    # usuario no admin "caiga" en el primer workspace por orden alfabético cuando hay varios clientes).
    if membership_rows:
        return [dict(row) for row in membership_rows]

    return fetch_workspace_rows(conn)


