def fetch_workspace_portal_requests(conn, workspace_id, limit=40):
    rows = conn.execute(
        """
        SELECT
          r.id,
          r.workspace_id,
          r.portal_cliente_id,
          r.cliente_id,
          r.servicio,
          r.titulo,
          r.descripcion,
          r.clasificacion,
          r.prioridad,
          r.estado,
          r.fecha_limite,
          r.completed_at,
          r.resolved_doc_id,
          r.created_at,
          r.updated_at,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(p.email_acceso, '') AS email_acceso
        FROM workspace_portal_requerimientos r
        LEFT JOIN workspace_portal_clientes p ON p.id = r.portal_cliente_id
        LEFT JOIN clientes c ON c.id = r.cliente_id
        WHERE r.workspace_id = ?
        ORDER BY
          CASE COALESCE(r.estado, 'Pendiente')
            WHEN 'Pendiente' THEN 0
            WHEN 'Enviado' THEN 1
            WHEN 'Recibido' THEN 2
            WHEN 'Completado' THEN 3
            ELSE 9
          END,
          COALESCE(r.fecha_limite, r.created_at) ASC
        LIMIT ?
        """,
        (workspace_id, max(1, min(int(limit or 40), 100))),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def parse_hhmm_to_minutes(value):
    text = str(value or "").strip()
    if not text:
        return None
    try:
        hours_str, minutes_str = text.split(":", 1)
        hours = int(hours_str)
        minutes = int(minutes_str[:2])
        if hours < 0 or hours > 23 or minutes < 0 or minutes > 59:
            return None
        return hours * 60 + minutes
    except Exception:
        return None


def format_minutes_hhmm(total_minutes):
    minutes = int(total_minutes or 0)
    sign = "-" if minutes < 0 else ""
    minutes = abs(minutes)
    return f"{sign}{minutes // 60:02d}:{minutes % 60:02d}"


def compute_worked_minutes(hora_inicio, hora_fin, pausa_min=0):
    start = parse_hhmm_to_minutes(hora_inicio)
    end = parse_hhmm_to_minutes(hora_fin)
    if start is None or end is None:
        return 0
    worked = end - start - max(0, int(pausa_min or 0))
    return max(0, worked)


def normalize_time_entry_state(raw_state, hora_fin):
    state = normalize_lookup_text(raw_state)
    if state in {"incidencia", "error"}:
        return "Incidencia"
    if not str(hora_fin or "").strip():
        return "Abierto"
    if state in {"validado", "cerrado"}:
        return "Validado"
    return "Cerrado"


def normalize_shift_type(raw_value):
    value = normalize_lookup_text(raw_value)
    if value in {"parcial", "tiempo parcial", "part-time"}:
        return "Parcial"
    return "Completa"


def infer_workspace_time_company_id(conn, workspace_id, service_raw="", empresa_id=None):
    company_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not company_ids:
        return None
    company_rows = conn.execute(
        f"""
        SELECT id, nombre
        FROM empresas
        WHERE id IN ({",".join("?" for _ in company_ids)})
        """,
        company_ids,
    ).fetchall()
    company_by_name = {
        normalize_lookup_text(row["nombre"] or ""): str(row["id"] or "")
        for row in company_rows
        if row["id"]
    }
    service_tokens = [
        normalize_lookup_text(token)
        for token in re.split(r"[;,/|]+", str(service_raw or ""))
        if normalize_lookup_text(token)
    ]
    for token in service_tokens:
        company_candidates = WORKSPACE_TIME_SERVICE_COMPANY_MAP.get(token.lower(), [])
        for company_name in company_candidates:
            company_id = company_by_name.get(normalize_lookup_text(company_name))
            if company_id:
                return company_id
    return company_ids[0] if company_ids else None


def sync_workspace_time_personal_from_users(conn, workspace_id, empresa_id=None):
    company_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not company_ids:
        return []
    user_rows = conn.execute(
        """
        SELECT id, nombre, apellido, usuario, email, servicio, activo,
               COALESCE(registro_horario_activo, 0) AS registro_horario_activo
        FROM usuarios
        WHERE COALESCE(activo, 1) = 1
        ORDER BY nombre COLLATE NOCASE ASC, apellido COLLATE NOCASE ASC
        """
    ).fetchall()
    synced_ids = []
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for user in user_rows:
        tracking_enabled = int(user["registro_horario_activo"] or 0) == 1
        existing = conn.execute(
            """
            SELECT id, empresa_id, COALESCE(empresa_manual, 0) AS empresa_manual,
                   tipo_jornada, horas_pactadas_dia, horas_pactadas_semana, fecha_alta, fecha_baja,
                   activo, notas, nif, telefono
            FROM workspace_registro_personal
            WHERE workspace_id = ? AND usuario_id = ?
            LIMIT 1
            """,
            (workspace_id, user["id"]),
        ).fetchone()
        if not tracking_enabled:
            if existing:
                conn.execute(
                    """
                    UPDATE workspace_registro_personal
                    SET activo = 0, updated_at = datetime(?)
                    WHERE id = ? AND workspace_id = ?
                    """,
                    (now, existing["id"], workspace_id),
                )
            continue
        empresa_vinculada = infer_workspace_time_company_id(
            conn,
            workspace_id,
            service_raw=user["servicio"] or "",
            empresa_id=empresa_id,
        )
        if not empresa_vinculada:
            continue
        full_name = " ".join(
            part.strip()
            for part in [str(user["nombre"] or "").strip(), str(user["apellido"] or "").strip()]
            if part and str(part).strip()
        ).strip()
        if not full_name:
            full_name = str(user["usuario"] or user["email"] or "").strip()
        if not full_name:
            continue
        if existing:
            manual_company = int(existing["empresa_manual"] or 0) == 1
            current_company = str(existing["empresa_id"] or "").strip()
            empresa_to_set = current_company if manual_company and current_company else empresa_vinculada
            conn.execute(
                """
                UPDATE workspace_registro_personal
                SET empresa_id = ?, nombre = ?, email = ?, activo = 1, updated_at = datetime(?)
                WHERE id = ? AND workspace_id = ?
                """,
                (
                    empresa_to_set,
                    full_name,
                    str(user["email"] or "").strip() or None,
                    now,
                    existing["id"],
                    workspace_id,
                ),
            )
            synced_ids.append(existing["id"])
        else:
            record_id = os.urandom(16).hex()
            conn.execute(
                """
                INSERT INTO workspace_registro_personal (
                  id, workspace_id, empresa_id, empresa_manual, usuario_id, usuario_manual, source, nombre, nif, email, telefono, tipo_jornada,
                  horas_pactadas_dia, horas_pactadas_semana, fecha_alta, fecha_baja, activo, notas, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
                """,
                (
                    record_id,
                    workspace_id,
                    empresa_vinculada,
                    0,
                    user["id"],
                    0,
                    "auto",
                    full_name,
                    None,
                    str(user["email"] or "").strip() or None,
                    None,
                    "Completa",
                    None,
                    None,
                    date.today().isoformat(),
                    None,
                    1,
                    "Sincronizado automáticamente desde usuarios.",
                    now,
                    now,
                ),
            )
            synced_ids.append(record_id)
    if synced_ids:
        conn.commit()
    return synced_ids


def fetch_workspace_personal(conn, workspace_id, empresa_id=None, only_active=False, limit=200):
    requested_company = str(empresa_id or "").strip()
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=requested_company or None)
    where = [
        "p.workspace_id = ?",
        "COALESCE(p.source, 'manual') != 'auto'",
    ]
    params = [workspace_id]
    # Seguridad multi-workspace: si una ficha está vinculada a un usuario del sistema,
    # ese usuario debe ser miembro del workspace. Esto evita que aparezca personal de otro
    # workspace por vinculaciones accidentales o por payloads manipulados.
    join_member = "LEFT JOIN workspace_miembros mem ON mem.workspace_id = p.workspace_id AND mem.usuario_id = p.usuario_id"
    where.append("(p.usuario_id IS NULL OR TRIM(COALESCE(p.usuario_id, '')) = '' OR mem.usuario_id IS NOT NULL)")
    if requested_company:
        # En vistas por empresa solo consideramos asignaciones confirmadas manualmente.
        if not empresa_ids or requested_company not in {str(x) for x in empresa_ids}:
            return {"rows": []}
        where.append("COALESCE(p.empresa_manual, 0) = 1")
        where.append("p.empresa_id = ?")
        params.append(requested_company)
    else:
        # En RRHH (vista de equipo) queremos ver también fichas sin empresa asignada.
        # A la vez, evitamos devolver registros que apunten a empresas fuera del workspace.
        workspace_company_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=None)
        if workspace_company_ids:
            where.append(
                f"(p.empresa_id IS NULL OR TRIM(COALESCE(p.empresa_id, '')) = '' OR p.empresa_id IN ({','.join('?' for _ in workspace_company_ids)}))"
            )
            params.extend(workspace_company_ids)
    if only_active:
        where.append("COALESCE(p.activo, 1) = 1")
    rows = conn.execute(
        f"""
        SELECT
          p.id,
          p.workspace_id,
          COALESCE(p.empresa_id, '') AS empresa_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(p.usuario_id, '') AS usuario_id,
          COALESCE(p.usuario_manual, 0) AS usuario_manual,
          COALESCE(p.empresa_manual, 0) AS empresa_manual,
          COALESCE(p.source, 'manual') AS source,
          p.nombre,
          p.nif,
          p.email,
          p.telefono,
          p.foto_url,
          p.fecha_nacimiento,
          p.tipo_contrato,
          p.kiosk_token,
          p.tipo_jornada,
          p.horas_pactadas_dia,
          p.horas_pactadas_semana,
          p.fecha_alta,
          p.fecha_baja,
          p.activo,
          p.notas,
          p.created_at,
          p.updated_at
        FROM workspace_registro_personal p
        LEFT JOIN empresas e ON e.id = p.empresa_id
        {join_member}
        WHERE {' AND '.join(where)}
        ORDER BY COALESCE(p.activo, 1) DESC, p.nombre COLLATE NOCASE ASC
        LIMIT ?
        """,
        (*params, max(1, min(int(limit or 200), 500))),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def fetch_workspace_time_users(conn, workspace_id, empresa_id=None, only_enabled=False, limit=200):
    company_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    # Importante (multi-tenant): los usuarios visibles en RRHH/Registro horario deben ser
    # los miembros del workspace, no el listado global del sistema.
    #
    # Nota: en algunos entornos legacy puede fallar el conteo de workspaces (por migraciones parciales).
    # Para evitar mezclar usuarios entre workspaces, priorizamos la tabla `workspace_miembros`
    # siempre que existan membresías para este workspace.
    join_sql = ""
    member_where = ""
    member_params = []
    members_count = 0
    try:
        ensure_workspace_core_tables(conn)
        row = conn.execute(
            "SELECT COUNT(*) AS total FROM workspace_miembros WHERE workspace_id = ?",
            (workspace_id,),
        ).fetchone()
        members_count = int(row_value(row, "total", 0) or row_value(row, 0) or 0)
    except Exception:
        members_count = 0
    if members_count > 0:
        join_sql = "JOIN workspace_miembros mem ON mem.usuario_id = u.id"
        member_where = " AND mem.workspace_id = ?"
        member_params = [workspace_id]
    else:
        # Modo estricto: si el workspace no tiene miembros, NO hacemos fallback al listado global.
        # Esto evita que RRHH muestre usuarios de otros workspaces por accidente.
        # La gestión de miembros se realiza en Workspaces → Usuarios (o Admin global).
        return {"rows": []}
    company_name_map = {}
    if company_ids:
        company_rows = conn.execute(
            f"""
            SELECT id, nombre
            FROM empresas
            WHERE id IN ({",".join("?" for _ in company_ids)})
            """,
            company_ids,
        ).fetchall()
        company_name_map = {str(row["id"]): str(row["nombre"] or "") for row in company_rows}
    where = ["COALESCE(u.activo, 1) = 1"]
    params = list(member_params)
    if only_enabled:
        where.append("COALESCE(u.registro_horario_activo, 0) = 1")
    rows = conn.execute(
        f"""
        SELECT
          u.id,
          u.nombre,
          u.apellido,
          u.usuario,
          u.email,
          u.servicio,
          u.rol,
          u.activo,
          COALESCE(u.registro_horario_activo, 0) AS registro_horario_activo
        FROM usuarios u
        {join_sql}
        WHERE {" AND ".join(where)}{member_where}
        ORDER BY u.nombre COLLATE NOCASE ASC, u.apellido COLLATE NOCASE ASC
        LIMIT ?
        """,
        (*params, max(1, min(int(limit or 200), 500))),
    ).fetchall()
    default_company_id = str(empresa_id or "").strip() or (company_ids[0] if company_ids else "")
    payload_rows = []
    for row in rows:
        mapped_company_id = ""
        if company_ids:
            mapped_company_id = infer_workspace_time_company_id(conn, workspace_id, service_raw=row["servicio"] or "", empresa_id=empresa_id)
            if not mapped_company_id:
                mapped_company_id = default_company_id
        payload = dict(row)
        payload["empresa_id"] = mapped_company_id
        payload["empresa_nombre"] = company_name_map.get(str(mapped_company_id), "") if mapped_company_id else ""
        payload_rows.append(payload)
    return {"rows": payload_rows}


def fetch_workspace_time_entries(conn, workspace_id, empresa_id=None, limit=40, month=None, persona_id=None):
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {"rows": []}
    where = ["t.workspace_id = ?", f"t.empresa_id IN ({','.join('?' for _ in empresa_ids)})"]
    params = [workspace_id, *empresa_ids]
    month_text = str(month or "").strip()
    if month_text:
        where.append("substr(t.fecha, 1, 7) = ?")
        params.append(month_text[:7])
    persona_text = str(persona_id or "").strip()
    if persona_text:
        where.append("t.persona_id = ?")
        params.append(persona_text)
    rows = conn.execute(
        f"""
        SELECT
          t.id,
          t.workspace_id,
          t.empresa_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          t.persona_id,
          t.usuario_id,
          t.persona_nombre,
          COALESCE(p.nif, '') AS persona_nif,
          COALESCE(p.email, '') AS persona_email,
          t.tipo_jornada,
          t.horas_pactadas_dia,
          t.fecha,
          t.hora_inicio,
          t.hora_fin,
          t.pausa_min,
          t.minutos_trabajados,
          t.metodo_registro,
          t.geo_in_lat,
          t.geo_in_lon,
          t.geo_in_acc,
          t.geo_in_source,
          t.geo_in_at,
          t.geo_out_lat,
          t.geo_out_lon,
          t.geo_out_acc,
          t.geo_out_source,
          t.geo_out_at,
          t.estado,
          t.notas,
          t.created_at,
          t.updated_at
        FROM workspace_registro_horario t
        LEFT JOIN empresas e ON e.id = t.empresa_id
        LEFT JOIN workspace_registro_personal p ON p.workspace_id = t.workspace_id AND p.id = t.persona_id
        WHERE {' AND '.join(where)}
        ORDER BY COALESCE(t.fecha, t.created_at) DESC, t.hora_inicio DESC
        LIMIT ?
        """,
        # Subimos el tope: el export y los resúmenes mensuales necesitan más de 300 filas (p.ej. 20 empleados × 22 días).
        (*params, max(1, min(int(limit or 40), 5000))),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def workspace_time_company_allowed(conn, workspace_id, empresa_id):
    ws_id = str(workspace_id or "").strip()
    eid = str(empresa_id or "").strip()
    if not ws_id or not eid:
        return False
    try:
        return eid in {str(item) for item in resolve_workspace_company_ids(conn, ws_id, empresa_id=eid)}
    except Exception:
        return False


def find_duplicate_open_time_entry(conn, workspace_id, empresa_id, fecha, persona_id=None, exclude_id=None):
    ws_id = str(workspace_id or "").strip()
    eid = str(empresa_id or "").strip()
    day = str(fecha or "").strip()
    pid = str(persona_id or "").strip()
    excluded = str(exclude_id or "").strip()
    if not ws_id or not eid or not day:
        return None
    where = [
        "workspace_id = ?",
        "empresa_id = ?",
        "fecha = ?",
        "COALESCE(persona_id, '') = ?",
        "COALESCE(hora_fin, '') = ''",
    ]
    params = [ws_id, eid, day, pid]
    if excluded:
        where.append("id != ?")
        params.append(excluded)
    return conn.execute(
        f"""
        SELECT id
        FROM workspace_registro_horario
        WHERE {' AND '.join(where)}
        LIMIT 1
        """,
        params,
    ).fetchone()


def workspace_time_retention_cutoff_date(now_dt=None):
    current = now_dt or app_now()
    if isinstance(current, datetime):
        current_date = current.date()
    elif isinstance(current, date):
        current_date = current
    else:
        current_date = app_now().date()
    try:
        return current_date.replace(year=current_date.year - WORKSPACE_TIME_RETENTION_YEARS).isoformat()
    except ValueError:
        return current_date.replace(year=current_date.year - WORKSPACE_TIME_RETENTION_YEARS, day=28).isoformat()


def protected_workspace_time_where(alias=""):
    prefix = f"{alias}." if alias else ""
    return f"(TRIM(COALESCE({prefix}fecha, '')) = '' OR substr({prefix}fecha, 1, 10) >= ?)"


def count_protected_workspace_time_entries(conn, workspace_id, persona_id=None):
    ws_id = str(workspace_id or "").strip()
    if not ws_id:
        return 0
    where = ["workspace_id = ?", protected_workspace_time_where()]
    params = [ws_id, workspace_time_retention_cutoff_date()]
    pid = str(persona_id or "").strip()
    if pid:
        where.append("persona_id = ?")
        params.append(pid)
    row = conn.execute(
        f"SELECT COUNT(*) AS total FROM workspace_registro_horario WHERE {' AND '.join(where)}",
        params,
    ).fetchone()
    return int(row_value(row, "total", 0) or row_value(row, 0) or 0)


def fetch_protected_workspace_time_persona_ids(conn, workspace_id, persona_ids=None):
    ws_id = str(workspace_id or "").strip()
    if not ws_id:
        return set()
    where = [
        "workspace_id = ?",
        "TRIM(COALESCE(persona_id, '')) != ''",
        protected_workspace_time_where(),
    ]
    params = [ws_id, workspace_time_retention_cutoff_date()]
    ids = [str(item or "").strip() for item in (persona_ids or []) if str(item or "").strip()]
    if ids:
        where.append(f"persona_id IN ({','.join('?' for _ in ids)})")
        params.extend(ids)
    rows = conn.execute(
        f"SELECT DISTINCT persona_id FROM workspace_registro_horario WHERE {' AND '.join(where)}",
        params,
    ).fetchall()
    return {
        str(row_value(row, "persona_id") or row_value(row, 0) or "").strip()
        for row in (rows or [])
        if str(row_value(row, "persona_id") or row_value(row, 0) or "").strip()
    }


def soft_deactivate_workspace_personas_for_retention(conn, workspace_id, persona_ids, now):
    ids = [str(item or "").strip() for item in (persona_ids or []) if str(item or "").strip()]
    if not workspace_id or not ids:
        return 0
    today = (str(now or "")[:10] or app_now().date().isoformat())
    note = f"Ficha desactivada; registros horarios conservados por retencion legal {WORKSPACE_TIME_RETENTION_YEARS} anos."
    placeholders = ",".join("?" for _ in ids)
    cur = conn.execute(
        f"""
        UPDATE workspace_registro_personal
        SET activo = 0,
            fecha_baja = COALESCE(NULLIF(fecha_baja, ''), ?),
            notas = CASE
              WHEN TRIM(COALESCE(notas, '')) = '' THEN ?
              WHEN instr(COALESCE(notas, ''), ?) > 0 THEN notas
              ELSE notas || char(10) || ?
            END,
            updated_at = datetime(?)
        WHERE workspace_id = ? AND id IN ({placeholders})
        """,
        (today, note, note, note, now, workspace_id, *ids),
    )
    try:
        return int(cur.rowcount or 0)
    except Exception:
        return 0


def build_workspace_payroll_summary_csv(rows, month=""):
    import io

    string_io = io.StringIO()
    writer = csv.writer(string_io)
    writer.writerow(
        [
            "mes",
            "empresa",
            "persona_id",
            "persona",
            "dni",
            "email",
            "tipo_jornada",
            "horas_pactadas_dia",
            "minutos_trabajados",
            "horas_trabajadas_hhmm",
            "dias_registrados",
            "entradas_abiertas",
            "incidencias",
            "vacaciones_aprobadas_dias",
            "ausencias_aprobadas_dias",
        ]
    )
    for row in rows or []:
        writer.writerow(
            [
                month or "",
                row.get("empresa_nombre") or "",
                row.get("persona_id") or "",
                row.get("persona_nombre") or "",
                row.get("nif") or "",
                row.get("email") or "",
                row.get("tipo_jornada") or "",
                row.get("horas_pactadas_dia") or "",
                int(row.get("minutos_trabajados") or 0),
                row.get("horas_trabajadas_hhmm") or "",
                int(row.get("dias_registrados") or 0),
                int(row.get("entradas_abiertas") or 0),
                int(row.get("incidencias") or 0),
                float(row.get("vacaciones_aprobadas_dias") or 0) or 0,
                float(row.get("ausencias_aprobadas_dias") or 0) or 0,
            ]
        )
    return string_io.getvalue().encode("utf-8-sig")


def fetch_workspace_payroll_summary(conn, workspace_id, *, empresa_id=None, month=""):
    workspace_id = str(workspace_id or "").strip()
    month_text = str(month or "").strip()[:7]
    if not workspace_id or not month_text:
        return {"rows": []}

    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {"rows": []}
    where = ["t.workspace_id = ?", f"t.empresa_id IN ({','.join('?' for _ in empresa_ids)})", "substr(t.fecha, 1, 7) = ?"]
    params = [workspace_id, *empresa_ids, month_text]
    grouped = conn.execute(
        f"""
        SELECT
          t.persona_id,
          COALESCE(t.persona_nombre, '') AS persona_nombre,
          t.empresa_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(MAX(t.tipo_jornada), '') AS tipo_jornada,
          COALESCE(MAX(t.horas_pactadas_dia), '') AS horas_pactadas_dia,
          COUNT(*) AS dias_registrados,
          SUM(COALESCE(t.minutos_trabajados, 0)) AS minutos_trabajados,
          SUM(CASE WHEN COALESCE(t.hora_fin, '') = '' THEN 1 ELSE 0 END) AS entradas_abiertas,
          SUM(CASE WHEN LOWER(COALESCE(t.estado, '')) = 'incidencia' THEN 1 ELSE 0 END) AS incidencias
        FROM workspace_registro_horario t
        LEFT JOIN empresas e ON e.id = t.empresa_id
        WHERE {' AND '.join(where)}
        GROUP BY t.persona_id, t.empresa_id, e.nombre, t.persona_nombre
        ORDER BY COALESCE(e.nombre, '') COLLATE NOCASE ASC, COALESCE(t.persona_nombre, '') COLLATE NOCASE ASC
        """,
        params,
    ).fetchall()
    people = [dict(r) for r in grouped]

    # Enriquecemos con NIF/email desde la ficha (si existe).
    personal_rows = conn.execute(
        """
        SELECT id, COALESCE(nif, '') AS nif, COALESCE(email, '') AS email
        FROM workspace_registro_personal
        WHERE workspace_id = ?
        """,
        (workspace_id,),
    ).fetchall()
    personal_map = {str(r["id"] or ""): dict(r) for r in personal_rows if str(r["id"] or "").strip()}

    # Ausencias aprobadas (vacaciones/permisos) en el mes.
    # Nota: contamos días laborables L-V dentro del mes (sin festivos por ahora).
    try:
        month_start = datetime.strptime(f"{month_text}-01", "%Y-%m-%d").date()
        if month_start.month == 12:
            month_end = date(month_start.year + 1, 1, 1) - timedelta(days=1)
        else:
            month_end = date(month_start.year, month_start.month + 1, 1) - timedelta(days=1)
    except Exception:
        month_start = None
        month_end = None

    aus_rows = conn.execute(
        """
        SELECT persona_id, empresa_id, tipo, estado, fecha_inicio, fecha_fin
        FROM workspace_rrhh_ausencias
        WHERE workspace_id = ?
          AND estado = 'Aprobada'
          AND (substr(fecha_inicio, 1, 7) = ? OR substr(fecha_fin, 1, 7) = ?)
        """,
        (workspace_id, month_text, month_text),
    ).fetchall()
    empresa_ids = {str(r["empresa_id"] or "").strip() for r in aus_rows if str(r["empresa_id"] or "").strip()}
    vac_mode_map = _fetch_empresa_vacaciones_modo_map(conn, empresa_ids)
    vac_days = {}
    abs_days = {}
    for r in aus_rows:
        pid = str(r["persona_id"] or "").strip()
        if not pid:
            continue
        start = _parse_iso_date(r["fecha_inicio"])
        end = _parse_iso_date(r["fecha_fin"])
        if not start or not end:
            continue
        if month_start and month_end:
            start = max(start, month_start)
            end = min(end, month_end)
        tipo = str(r["tipo"] or "").strip().lower()
        if tipo == "vacaciones":
            modo = vac_mode_map.get(str(r["empresa_id"] or "").strip(), "habiles")
            days = _count_absence_days(start, end, modo)
        else:
            days = _count_business_days(start, end)
        if days <= 0:
            continue
        if tipo == "vacaciones":
            vac_days[pid] = vac_days.get(pid, 0) + days
        else:
            abs_days[pid] = abs_days.get(pid, 0) + days

    for item in people:
        pid = str(item.get("persona_id") or "").strip()
        ficha = personal_map.get(pid) or {}
        item["nif"] = ficha.get("nif") or ""
        item["email"] = ficha.get("email") or ""
        item["tipo_jornada"] = normalize_shift_type(item.get("tipo_jornada") or "")
        item["horas_trabajadas_hhmm"] = format_minutes_hhmm(item.get("minutos_trabajados") or 0)
        item["vacaciones_aprobadas_dias"] = float(vac_days.get(pid, 0) or 0)
        item["ausencias_aprobadas_dias"] = float(abs_days.get(pid, 0) or 0)
    return {"rows": people}


def build_workspace_time_summary(rows, month=""):
    grouped = {}
    total_minutes = 0
    total_expected = 0
    open_entries = 0
    partial_people = set()
    for row in rows:
        person_key = str(row.get("persona_id") or row.get("persona_nombre") or "").strip()
        if not person_key:
            continue
        worked = int(row.get("minutos_trabajados") or 0)
        expected = int(round(float(row.get("horas_pactadas_dia") or 0) * 60))
        if not row.get("hora_fin"):
            open_entries += 1
        if normalize_shift_type(row.get("tipo_jornada")) == "Parcial":
            partial_people.add(person_key)
        bucket = grouped.setdefault(
            person_key,
            {
                "persona_id": row.get("persona_id"),
                "persona_nombre": row.get("persona_nombre") or "-",
                "empresa_nombre": row.get("empresa_nombre") or "-",
                "tipo_jornada": normalize_shift_type(row.get("tipo_jornada")),
                "dias_registrados": 0,
                "minutos_trabajados": 0,
                "minutos_pactados": 0,
                "minutos_pausa": 0,
                "incidencias": 0,
                "entradas_abiertas": 0,
            },
        )
        bucket["dias_registrados"] += 1
        bucket["minutos_trabajados"] += worked
        bucket["minutos_pactados"] += expected
        bucket["minutos_pausa"] += int(row.get("pausa_min") or 0)
        if normalize_lookup_text(row.get("estado")) == "incidencia":
            bucket["incidencias"] += 1
        if not row.get("hora_fin"):
            bucket["entradas_abiertas"] += 1
        total_minutes += worked
        total_expected += expected
    people = sorted(grouped.values(), key=lambda item: (item["empresa_nombre"], item["persona_nombre"]))
    for item in people:
        item["horas_trabajadas_hhmm"] = format_minutes_hhmm(item["minutos_trabajados"])
        item["horas_pactadas_hhmm"] = format_minutes_hhmm(item["minutos_pactados"])
        item["desviacion_hhmm"] = format_minutes_hhmm(item["minutos_trabajados"] - item["minutos_pactados"])
    return {
        "month": month,
        "personas_total": len(people),
        "personas_parciales": len(partial_people),
        "entradas_abiertas": open_entries,
        "horas_totales_hhmm": format_minutes_hhmm(total_minutes),
        "horas_pactadas_hhmm": format_minutes_hhmm(total_expected),
        "desviacion_hhmm": format_minutes_hhmm(total_minutes - total_expected),
        "rows": people,
    }


