def build_workspace_time_xlsx(rows, workspace=None, company=None, persona=None, month=""):
    workspace = workspace or {}
    company = company or {}
    persona = persona or {}
    # Generate a minimal .xlsx (OOXML) without external dependencies (openpyxl).
    # Excel can open this file normally.
    import zipfile
    from xml.sax.saxutils import escape as xml_escape

    def col_letter(idx):
        idx = int(idx)
        letters = ""
        while idx > 0:
            idx, rem = divmod(idx - 1, 26)
            letters = chr(65 + rem) + letters
        return letters

    def cell_ref(row_idx, col_idx):
        return f"{col_letter(col_idx)}{row_idx}"

    def xml_cell(row_idx, col_idx, value):
        ref = cell_ref(row_idx, col_idx)
        if value is None:
            return f'<c r="{ref}"/>'
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return f'<c r="{ref}"><v>{value}</v></c>'
        text = str(value)
        # Keep newlines; Excel supports them in inline strings.
        text = xml_escape(text)
        return f'<c r="{ref}" t="inlineStr"><is><t xml:space="preserve">{text}</t></is></c>'

    lines = []
    worker_name = persona.get("persona_nombre") or persona.get("nombre") or ""
    worker_nif = persona.get("nif") or persona.get("persona_nif") or ""
    worker_email = persona.get("email") or persona.get("persona_email") or ""
    lines.append(["Workspace", workspace.get("nombre") or ""])
    lines.append(["Empresa", company.get("nombre") or ""])
    lines.append(["Trabajador", worker_name])
    if worker_nif:
        lines.append(["DNI/NIF", worker_nif])
    if worker_email:
        lines.append(["Email", worker_email])
    lines.append(["Mes", month or ""])
    lines.append(["Zona horaria", APP_TIMEZONE])
    lines.append(["Generado", app_now().strftime("%Y-%m-%d %H:%M:%S")])
    lines.append(["Retencion legal", f"{WORKSPACE_TIME_RETENTION_YEARS} anos"])
    lines.append(["Base legal", "art. 34.9 Estatuto de los Trabajadores"])
    lines.append([])
    lines.append(
        [
            "Fecha",
            "Inicio",
            "Fin",
            "Pausa (min)",
            "Minutos trabajados",
            "Horas (HH:MM)",
            "Método",
            "Geo entrada",
            "Geo salida",
            "Estado",
            "Notas",
            "Creado",
            "Actualizado",
        ]
    )
    for row in rows or []:
        minutos = int(row.get("minutos_trabajados") or 0)
        geo_in = ""
        if row.get("geo_in_lat") not in (None, "") and row.get("geo_in_lon") not in (None, ""):
            geo_in = f"{row.get('geo_in_lat')},{row.get('geo_in_lon')}" + (f" ±{row.get('geo_in_acc')}m" if row.get("geo_in_acc") not in (None, "") else "")
        geo_out = ""
        if row.get("geo_out_lat") not in (None, "") and row.get("geo_out_lon") not in (None, ""):
            geo_out = f"{row.get('geo_out_lat')},{row.get('geo_out_lon')}" + (f" ±{row.get('geo_out_acc')}m" if row.get("geo_out_acc") not in (None, "") else "")
        lines.append(
            [
                row.get("fecha") or "",
                row.get("hora_inicio") or "",
                row.get("hora_fin") or "",
                int(row.get("pausa_min") or 0),
                minutos,
                format_minutes_hhmm(minutos),
                row.get("metodo_registro") or "",
                geo_in,
                geo_out,
                row.get("estado") or "",
                row.get("notas") or "",
                row.get("created_at") or "",
                row.get("updated_at") or "",
            ]
        )

    sheet_rows = []
    for r_idx, row in enumerate(lines, start=1):
        if not row:
            sheet_rows.append(f'<row r="{r_idx}"></row>')
            continue
        cells = []
        for c_idx, val in enumerate(row, start=1):
            cells.append(xml_cell(r_idx, c_idx, val))
        sheet_rows.append(f'<row r="{r_idx}">{"".join(cells)}</row>')

    sheet_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        "<sheetData>"
        + "".join(sheet_rows)
        + "</sheetData>"
        "</worksheet>"
    )

    workbook_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        "<sheets>"
        '<sheet name="Registro horario" sheetId="1" r:id="rId1"/>'
        "</sheets>"
        "</workbook>"
    )

    rels_root = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
        "</Relationships>"
    )

    rels_wb = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
        '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
        "</Relationships>"
    )

    # Minimal styles (required by some Excel versions to avoid warnings).
    styles_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        "<fonts count=\"1\"><font><sz val=\"11\"/><color rgb=\"FF000000\"/><name val=\"Calibri\"/><family val=\"2\"/></font></fonts>"
        "<fills count=\"1\"><fill><patternFill patternType=\"none\"/></fill></fills>"
        "<borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders>"
        "<cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs>"
        "<cellXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyFont=\"1\"/></cellXfs>"
        "<cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles>"
        "</styleSheet>"
    )

    content_types = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
        '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
        '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
        "</Types>"
    )

    buffer = BytesIO()
    with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("[Content_Types].xml", content_types)
        zf.writestr("_rels/.rels", rels_root)
        zf.writestr("xl/workbook.xml", workbook_xml)
        zf.writestr("xl/_rels/workbook.xml.rels", rels_wb)
        zf.writestr("xl/worksheets/sheet1.xml", sheet_xml)
        zf.writestr("xl/styles.xml", styles_xml)
    return buffer.getvalue()


def fetch_workspace_alert_preferences(conn, workspace_id, persona_id=None):
    where = ["workspace_id = ?"]
    params = [workspace_id]
    if persona_id:
        where.append("persona_id = ?")
        params.append(persona_id)
    row = conn.execute(
        f"""
        SELECT * FROM workspace_registro_alerts
        WHERE {' AND '.join(where)}
        LIMIT 1
        """,
        params,
    ).fetchone()
    if row:
        return dict(row)
    # fallback to personal record (maps legacy column names to the alert schema)
    if persona_id:
        row = conn.execute(
            """
            SELECT *
            FROM workspace_registro_personal
            WHERE workspace_id = ? AND id = ?
            LIMIT 1
            """,
            (workspace_id, persona_id),
        ).fetchone()
        if row:
            record = dict(row)
            return {
                "workspace_id": workspace_id,
                "empresa_id": record.get("empresa_id"),
                "persona_id": record.get("id"),
                "alert_missing_checkin": record.get("alert_missing_checkin", 1),
                "alert_missing_checkout": record.get("alert_missing_checkout", 1),
                "notify_worker": record.get("alert_notify_worker", 1),
                "notify_admin": record.get("alert_notify_admin", 1),
                "admin_contact": record.get("alert_admin_contact") or "",
                "schedule": "",
            }
    return None


def upsert_workspace_alert_config(conn, workspace_id, persona_id, payload, now=None):
    now_ts = now or datetime.now().isoformat()
    existing = conn.execute(
        """
        SELECT id FROM workspace_registro_alerts
        WHERE workspace_id = ? AND persona_id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    values = (
        (payload.get("empresa_id") or "").strip() or None,
        0 if str(payload.get("alert_missing_checkin") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        0 if str(payload.get("alert_missing_checkout") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        0 if str(payload.get("notify_worker") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        0 if str(payload.get("notify_admin") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        (payload.get("admin_contact") or "").strip() or "",
        (payload.get("schedule") or "").strip() or "",
    )
    if existing:
        conn.execute(
            """
            UPDATE workspace_registro_alerts
            SET empresa_id = ?, alert_missing_checkin = ?, alert_missing_checkout = ?, notify_worker = ?, notify_admin = ?, admin_contact = ?, schedule = ?, updated_at = ?
            WHERE id = ? AND workspace_id = ?
            """,
            (*values, now_ts, existing["id"], workspace_id),
        )
        return existing["id"]
    record_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO workspace_registro_alerts (
          id, workspace_id, empresa_id, persona_id, alert_missing_checkin, alert_missing_checkout,
          notify_worker, notify_admin, admin_contact, schedule, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (record_id, workspace_id, values[0], persona_id, values[1], values[2], values[3], values[4], values[5], values[6], now_ts, now_ts),
    )
    return record_id


def fetch_workspace_notifications(conn, workspace_id, limit=40, persona_id=None):
    where = ["workspace_id = ?"]
    params = [workspace_id]
    persona_text = str(persona_id or "").strip()
    if persona_text:
        where.append("persona_id = ?")
        params.append(persona_text)
    rows = conn.execute(
        f"""
        SELECT id, workspace_id, persona_id, channel, payload, created_at
        FROM workspace_registro_notifications
        WHERE {' AND '.join(where)}
        ORDER BY created_at DESC
        LIMIT ?
        """,
        (*params, max(1, min(int(limit or 40), 200))),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}

def log_workspace_notification(conn, workspace_id, persona_id, channel, payload, now=None):
    now_ts = now or datetime.now().isoformat()
    notification_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO workspace_registro_notifications (
          id, workspace_id, persona_id, channel, payload, created_at
        ) VALUES (?, ?, ?, ?, ?, ?)
        """,
        (notification_id, workspace_id, persona_id, channel, json.dumps(payload, ensure_ascii=False), now_ts),
    )
    try:
        maybe_send_workspace_notification_email(conn, workspace_id, persona_id, notification_id, channel, payload, now=now_ts)
    except Exception:
        pass


def _mask_email(value):
    email_value = str(value or "").strip()
    if "@" not in email_value:
        return ""
    local, domain = email_value.split("@", 1)
    if len(local) <= 2:
        local_mask = local[:1] + "*"
    else:
        local_mask = local[:1] + "*" * (len(local) - 2) + local[-1:]
    return f"{local_mask}@{domain}"


def _extract_emails(value):
    raw = str(value or "").strip()
    if not raw:
        return []
    tokens = re.split(r"[,\s;]+", raw)
    emails = []
    for token in tokens:
        token = token.strip()
        if not token:
            continue
        if "@" not in token:
            continue
        emails.append(token)
    return emails


def send_email_smtp(subject, to_email, text_body, html_body=None):
    # Wrapper around the existing send_mail_smtp.
    if not to_email:
        return {"ok": False, "skipped": True, "error": "no_recipients"}
    try:
        send_mail_smtp(subject, to_email, text_body, html_body=html_body)
        return {"ok": True}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


def maybe_send_workspace_notification_email(conn, workspace_id, persona_id, notification_id, channel, payload, now=None):
    # SMTP is optional; if not configured, keep DB notification only.
    if not (os.environ.get("SMTP_HOST") or "").strip():
        return {"ok": False, "skipped": True}
    ch = str(channel or "").strip()
    is_admin = ch.startswith("admin_")
    is_worker = ch.startswith("worker_")
    if not (is_admin or is_worker):
        return {"ok": False, "skipped": True}

    prefs = fetch_workspace_alert_preferences(conn, workspace_id, persona_id=persona_id) or {}
    recipients = []
    if is_admin:
        recipients.extend(_extract_emails(prefs.get("admin_contact") or payload.get("admin_contact") or ""))
    if is_worker:
        person = conn.execute(
            "SELECT email, usuario_id FROM workspace_registro_personal WHERE workspace_id = ? AND id = ? LIMIT 1",
            (workspace_id, persona_id),
        ).fetchone()
        if person and str(person["email"] or "").strip():
            recipients.extend(_extract_emails(person["email"]))
        else:
            usuario_id = str(person["usuario_id"] or "").strip() if person else ""
            if usuario_id:
                user = conn.execute("SELECT email FROM usuarios WHERE id = ? LIMIT 1", (usuario_id,)).fetchone()
                if user and str(user["email"] or "").strip():
                    recipients.extend(_extract_emails(user["email"]))

    recipients = list(dict.fromkeys([r.strip() for r in recipients if r.strip()]))
    if not recipients:
        return {"ok": False, "skipped": True}

    persona_nombre = str(payload.get("persona_nombre") or "").strip() or "-"
    empresa_nombre = str(payload.get("empresa_nombre") or "").strip()
    fecha = str(payload.get("fecha") or "").strip()
    hora_inicio = str(payload.get("hora_inicio") or "").strip()
    hora_fin = str(payload.get("hora_fin") or "").strip()

    subject_map = {
        "admin_entry_log": "Registro horario: entrada registrada",
        "admin_exit_log": "Registro horario: salida registrada",
        "worker_entry_log": "Tu registro horario: entrada registrada",
        "worker_exit_log": "Tu registro horario: salida registrada",
        "admin_missing_checkin": "Registro horario: falta entrada",
        "admin_missing_checkout": "Registro horario: falta salida",
        "worker_missing_checkin": "Te falta registrar la entrada",
        "worker_missing_checkout": "Te falta registrar la salida",
    }
    subject = subject_map.get(ch, f"Notificación registro horario ({ch})")
    lines = [
        subject,
        "",
        f"Persona: {persona_nombre}",
    ]
    if empresa_nombre:
        lines.append(f"Empresa: {empresa_nombre}")
    if fecha:
        lines.append(f"Fecha: {fecha}")
    if hora_inicio:
        lines.append(f"Entrada: {hora_inicio}")
    if hora_fin:
        lines.append(f"Salida: {hora_fin}")
    lines.append("")
    lines.append("Mensaje generado automáticamente por Verifika².")
    body = "\n".join(lines)

    ok_any = True
    sent_to = []
    for addr in recipients:
        result = send_email_smtp(subject, addr, body)
        ok_any = ok_any and bool(result.get("ok"))
        sent_to.append(_mask_email(addr))

    # Store delivery traceability (masked).
    try:
        payload2 = dict(payload or {})
        payload2["delivery"] = {"method": "email", "to": sent_to, "ok": bool(ok_any)}
        conn.execute(
            "UPDATE workspace_registro_notifications SET payload = ? WHERE id = ?",
            (json.dumps(payload2, ensure_ascii=False), notification_id),
        )
    except Exception:
        pass
    return {"ok": bool(ok_any)}


def _normalize_month(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    if re.match(r"^\\d{4}-\\d{2}$", raw):
        return raw
    if len(raw) >= 7 and re.match(r"^\\d{4}-\\d{2}", raw):
        return raw[:7]
    return ""


def compute_workspace_time_period_digest(conn, workspace_id, month, empresa_id=None):
    month_key = _normalize_month(month)
    if not workspace_id or not month_key:
        return {"entries_total": 0, "minutos_total": 0, "digest_sha256": ""}
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {"entries_total": 0, "minutos_total": 0, "digest_sha256": ""}
    rows = conn.execute(
        f"""
        SELECT id, empresa_id, persona_id, usuario_id, persona_nombre, tipo_jornada, horas_pactadas_dia,
               fecha, hora_inicio, hora_fin, pausa_min, minutos_trabajados, metodo_registro, estado, COALESCE(notas,'') AS notas
        FROM workspace_registro_horario
        WHERE workspace_id = ?
          AND empresa_id IN ({",".join("?" for _ in empresa_ids)})
          AND substr(fecha, 1, 7) = ?
        ORDER BY fecha ASC, hora_inicio ASC, id ASC
        """,
        (workspace_id, *empresa_ids, month_key),
    ).fetchall()
    h = hashlib.sha256()
    total_min = 0
    for row in rows:
        d = dict(row)
        total_min += int(d.get("minutos_trabajados") or 0)
        h.update(json.dumps(d, ensure_ascii=False, sort_keys=True).encode("utf-8"))
        h.update(b"\n")
    return {"entries_total": len(rows), "minutos_total": int(total_min), "digest_sha256": h.hexdigest()}


def is_workspace_time_month_locked(conn, workspace_id, month, empresa_id=None):
    month_key = _normalize_month(month)
    if not workspace_id or not month_key:
        return False
    empresa_key = str(empresa_id or "").strip()
    row = conn.execute(
        """
        SELECT locked
        FROM workspace_registro_periodos
        WHERE workspace_id = ? AND COALESCE(empresa_id, '') = ? AND month = ?
        LIMIT 1
        """,
        (workspace_id, empresa_key, month_key),
    ).fetchone()
    if not row:
        return False
    return int(row["locked"] or 0) == 1


def fetch_workspace_registro_periodos(conn, workspace_id, empresa_id=None, limit=36):
    empresa_key = str(empresa_id or "").strip()
    where = ["workspace_id = ?"]
    params = [workspace_id]
    if empresa_key:
        where.append("COALESCE(empresa_id,'') = ?")
        params.append(empresa_key)
    rows = conn.execute(
        f"""
        SELECT id, workspace_id, empresa_id, month, locked, locked_at, locked_by, entries_total, minutos_total, digest_sha256, created_at, updated_at
        FROM workspace_registro_periodos
        WHERE {' AND '.join(where)}
        ORDER BY month DESC
        LIMIT ?
        """,
        (*params, max(1, min(int(limit or 36), 120))),
    ).fetchall()
    return {"rows": [dict(r) for r in rows]}


def upsert_workspace_registro_periodo_lock(conn, workspace_id, month, locked, actor_user_id="", empresa_id=None, now=None):
    now_ts = now or datetime.now().isoformat()
    month_key = _normalize_month(month)
    if not workspace_id or not month_key:
        return {"error": "workspace_id y month requeridos"}
    empresa_key = str(empresa_id or "").strip()
    existing = conn.execute(
        "SELECT id FROM workspace_registro_periodos WHERE workspace_id = ? AND COALESCE(empresa_id,'') = ? AND month = ? LIMIT 1",
        (workspace_id, empresa_key, month_key),
    ).fetchone()
    digest = compute_workspace_time_period_digest(conn, workspace_id, month_key, empresa_id=empresa_id)
    locked_int = 1 if int(locked or 0) == 1 else 0
    if existing:
        conn.execute(
            """
            UPDATE workspace_registro_periodos
            SET locked = ?, locked_at = ?, locked_by = ?, entries_total = ?, minutos_total = ?, digest_sha256 = ?, updated_at = datetime(?)
            WHERE id = ? AND workspace_id = ?
            """,
            (
                locked_int,
                now_ts if locked_int else None,
                actor_user_id or None,
                int(digest["entries_total"] or 0),
                int(digest["minutos_total"] or 0),
                digest["digest_sha256"] if locked_int else None,
                now_ts,
                existing["id"],
                workspace_id,
            ),
        )
        return {"id": existing["id"], "month": month_key, "locked": locked_int, **digest}
    record_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO workspace_registro_periodos (
          id, workspace_id, empresa_id, month, locked, locked_at, locked_by, entries_total, minutos_total, digest_sha256, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
        """,
        (
            record_id,
            workspace_id,
            empresa_key,
            month_key,
            locked_int,
            now_ts if locked_int else None,
            actor_user_id or None,
            int(digest["entries_total"] or 0),
            int(digest["minutos_total"] or 0),
            digest["digest_sha256"] if locked_int else None,
            now_ts,
            now_ts,
        ),
    )
    return {"id": record_id, "month": month_key, "locked": locked_int, **digest}


def _normalize_service_tokens(value):
    raw = str(value or "")
    if not raw.strip():
        return set()
    # servicios puede venir como string con comas: "Gestoría, Seguros"
    # o como "Gestoría - Administración Fincas"
    tokens = []
    for chunk in re.split(r"(?:\s+-\s+|[|,;/·]+)", raw):
        token = normalize_lookup_text(chunk or "")
        if token:
            tokens.append(token)
    return set(tokens)


def workspace_session_is_privileged(session):
    if not session:
        return False
    rol = normalize_lookup_text(session.get("rol") or "")
    # `normalize_lookup_text` devuelve tokens en MAYÚSCULAS (sin acentos).
    if rol in {"ADMINISTRADOR", "ADMIN", "DIRECCION", "CONTROL", "ADMINISTRACION"}:
        return True
    return False

def _parse_csv_tokens(value):
    raw = str(value or "").strip()
    if not raw:
        return set()
    parts = []
    for chunk in re.split(r"[,\n; ]+", raw):
        t = str(chunk or "").strip()
        if t:
            parts.append(t)
    return {p for p in parts if p}

def is_superadmin_actor(conn, session):
    """
    Superadmin por allowlist (env vars). Usado para permisos globales y bypass de membership.
    """
    if not session:
        return False
    allow_ids = _parse_csv_tokens(APP_SUPERADMIN_IDS)
    allow_users = {normalize_lookup_text(x) for x in _parse_csv_tokens(APP_SUPERADMIN_USERNAMES)}
    allow_emails = {normalize_email(x) for x in _parse_csv_tokens(APP_SUPERADMIN_EMAILS)}

    sid = str(session.get("user_id") or "").strip()
    susr = normalize_lookup_text(session.get("usuario") or "")
    semail = normalize_email(session.get("email") or "")

    # Si falta info en sesión, intentamos refrescar desde DB.
    if conn and sid and (not susr or not semail):
        try:
            row = conn.execute(
                "SELECT usuario, email, activo FROM usuarios WHERE id = ? LIMIT 1",
                (sid,),
            ).fetchone()
        except Exception:
            row = None
        if row:
            try:
                if int(row_value(row, "activo", 1) or 0) != 1:
                    return False
            except Exception:
                pass
            if not susr:
                susr = normalize_lookup_text(row_value(row, "usuario") or "")
            if not semail:
                semail = normalize_email(row_value(row, "email") or "")

    if allow_ids and sid and sid in allow_ids:
        return True
    if allow_users and susr and susr in allow_users:
        return True
    if allow_emails and semail and semail in allow_emails:
        return True
    return False

def workspace_actor_is_privileged(conn, session):
    """
    Determina permisos usando la sesión y el mecanismo seguro existente.
    No eleva privilegios a partir de `rol` o `servicio` leídos de la DB.
    """
    # Modo estricto: solo superadmin allowlisted puede hacer acciones globales.
    if APP_SUPERADMIN_ENFORCE:
        return is_superadmin_actor(conn, session)
    # Modo compat: superadmin allowlisted siempre tiene privilegios globales.
    if is_superadmin_actor(conn, session):
        return True
    if workspace_session_is_privileged(session):
        return True
    if not session or not conn:
        return False
    user_id = str(session.get("user_id") or "").strip()
    if not user_id:
        return False
    try:
        row = conn.execute(
            "SELECT activo FROM usuarios WHERE id = ? LIMIT 1",
            (user_id,),
        ).fetchone()
    except Exception:
        _rollback_best_effort(conn)
        row = None
    if not row:
        return False
    try:
        if int(row["activo"] or 0) != 1:
            return False
    except Exception:
        pass
    return False


def workspace_actor_can_manage_workspace(conn, session, workspace_id):
    """
    Permisos de administración limitados al workspace.
    - Admin global (usuarios.rol) puede gestionar cualquier workspace.
    - Owner/Admin en workspace_miembros puede gestionar ese workspace.
    """
    if workspace_actor_is_privileged(conn, session):
        return True
    if not conn or not session:
        return False
    ws_id = str(workspace_id or "").strip()
    user_id = str(session.get("user_id") or "").strip()
    if not ws_id or not user_id:
        return False
    try:
        ensure_workspace_core_tables(conn)
    except Exception:
        _rollback_best_effort(conn)
    member = fetch_workspace_member(conn, ws_id, user_id)
    if not member:
        return False
    role_norm = _normalize_workspace_member_role(member.get("rol") or "")
    return role_norm in {"Owner", "Admin"}


def _normalize_workspace_member_role(value):
    raw = normalize_lookup_text(value)
    if raw in {"OWNER", "PROPIETARIO"}:
        return "Owner"
    if raw in {"ADMIN", "ADMINISTRADOR"}:
        return "Admin"
    if raw in {"LECTURA", "READONLY", "READ_ONLY", "READ ONLY"}:
        return "Lectura"
    if raw in {"MIEMBRO", "MEMBER"}:
        return "Miembro"
    return (str(value or "").strip() or "Miembro")


def workspace_member_can_write(role):
    role_norm = _normalize_workspace_member_role(role)
    return role_norm in {"Owner", "Admin", "Miembro"}


def fetch_workspace_member(conn, workspace_id, user_id):
    ws_id = str(workspace_id or "").strip()
    uid = str(user_id or "").strip()
    if not ws_id or not uid:
        return None
    row = conn.execute(
        """
        SELECT id, workspace_id, usuario_id, rol
        FROM workspace_miembros
        WHERE workspace_id = ? AND usuario_id = ?
        LIMIT 1
        """,
        (ws_id, uid),
    ).fetchone()
    return dict(row) if row else None


def ensure_workspace_member(conn, workspace_id, user_id, role="Miembro", now=None):
    ws_id = str(workspace_id or "").strip()
    uid = str(user_id or "").strip()
    if not ws_id or not uid:
        return ""
    role_norm = _normalize_workspace_member_role(role)
    now_ts = now or datetime.now(timezone.utc).isoformat()
    record_id = os.urandom(16).hex()
    try:
        conn.execute(
            """
            INSERT OR IGNORE INTO workspace_miembros (
              id, workspace_id, usuario_id, rol, created_at, updated_at
            ) VALUES (?, ?, ?, ?, datetime(?), datetime(?))
            """,
            (record_id, ws_id, uid, role_norm, now_ts, now_ts),
        )
    except Exception:
        _rollback_best_effort(conn)
    # Return existing id if it already existed.
    existing = conn.execute(
        "SELECT id FROM workspace_miembros WHERE workspace_id = ? AND usuario_id = ? LIMIT 1",
        (ws_id, uid),
    ).fetchone()
    return str(row_value(existing, "id") or row_value(existing, 0) or record_id)


def normalize_workspace_kind(value):
    raw = normalize_lookup_text(value)
    if raw in {"GESTORIA", "HUB"}:
        return "Gestoría"
    if raw in {"CLIENTE", "DIRECTO", "DIRECT"}:
        return "Directo"
    return (str(value or "").strip() or "Directo")


def normalize_workspace_link_type(value):
    raw = normalize_lookup_text(value)
    if raw in {"GESTORIA", "GESTORIA_CLIENTE", "HUB", "PARTNER", "PROVIDER"}:
        return "gestoria_partner"
    return (str(value or "").strip() or "gestoria_partner")


def fetch_workspace_link_rows(conn, workspace_id):
    ws_id = str(workspace_id or "").strip()
    if not ws_id:
        return []
    ensure_workspace_core_tables(conn)
    rows = conn.execute(
        """
        SELECT
          l.id,
          l.source_workspace_id,
          ws.nombre AS source_nombre,
          ws.slug AS source_slug,
          l.target_workspace_id,
          wt.nombre AS target_nombre,
          wt.slug AS target_slug,
          l.link_type,
          COALESCE(l.role, '') AS role,
          COALESCE(l.enabled, 1) AS enabled,
          COALESCE(l.notes, '') AS notes,
          l.created_at,
          l.updated_at
        FROM workspace_links l
        LEFT JOIN workspaces ws ON ws.id = l.source_workspace_id
        LEFT JOIN workspaces wt ON wt.id = l.target_workspace_id
        WHERE (l.source_workspace_id = ? OR l.target_workspace_id = ?)
        ORDER BY COALESCE(l.updated_at, l.created_at) DESC
        LIMIT 200
        """,
        (ws_id, ws_id),
    ).fetchall()
    return [dict(r) for r in rows]


def ensure_partner_membership(conn, source_workspace_id, target_workspace_id, *, role="Miembro", now=None):
    """
    Al vincular una gestoría (source) con un cliente (target), damos acceso a:
    - miembros Owner/Admin del source
    - usuarios del source cuyo `usuarios.servicio` incluya Gestoría (o Administración de fincas)
    Additivo: no elimina permisos existentes.
    """
    src = str(source_workspace_id or "").strip()
    tgt = str(target_workspace_id or "").strip()
    if not src or not tgt or src == tgt:
        return 0
    now_ts = now or datetime.now(timezone.utc).isoformat()
    members = conn.execute(
        "SELECT usuario_id, rol FROM workspace_miembros WHERE workspace_id = ?",
        (src,),
    ).fetchall()
    user_ids = [
        str(row_value(row, "usuario_id") or row_value(row, 0) or "").strip()
        for row in (members or [])
        if str(row_value(row, "usuario_id") or row_value(row, 0) or "").strip()
    ]
    services_by_user_id = {}
    if user_ids:
        try:
            rows = conn.execute(
                f"SELECT id, COALESCE(servicio, '') AS servicio FROM usuarios WHERE id IN ({','.join('?' for _ in user_ids)})",
                user_ids,
            ).fetchall()
            for row in rows or []:
                uid = str(row_value(row, "id") or row_value(row, 0) or "").strip()
                servicio = str(row_value(row, "servicio") or row_value(row, 1) or "").strip()
                if uid:
                    services_by_user_id[uid] = servicio
        except Exception:
            services_by_user_id = {}
    added = 0
    for row in members or []:
        uid = str(row_value(row, "usuario_id") or row_value(row, 0) or "").strip()
        mrole = str(row_value(row, "rol") or row_value(row, 1) or "").strip()
        if not uid:
            continue
        mrole_norm = _normalize_workspace_member_role(mrole)
        services = _normalize_service_tokens(services_by_user_id.get(uid, ""))
        is_gestoria_staff = "GESTORIA" in services
        if mrole_norm not in {"Owner", "Admin"} and not is_gestoria_staff:
            continue
        before = fetch_workspace_member(conn, tgt, uid)
        ensure_workspace_member(conn, tgt, uid, role=role, now=now_ts)
        after = fetch_workspace_member(conn, tgt, uid)
        if (not before) and after:
            added += 1
    return added


def enforce_workspace_membership(conn, session, workspace_id, *, write=False):
    """
    En modo comercial multi-tenant, exige que el usuario pertenezca al workspace.
    Para no romper setups legacy, se puede desactivar con APP_WORKSPACE_MEMBERSHIP_ENFORCE=0.
    """
    if not WORKSPACE_MEMBERSHIP_ENFORCE:
        return True, ""
    if workspace_actor_is_privileged(conn, session):
        return True, ""
    if not session:
        return False, "No autorizado"
    uid = str(session.get("user_id") or "").strip()
    ws_id = str(workspace_id or "").strip()
    if not uid or not ws_id:
        return False, "No autorizado"
    member = fetch_workspace_member(conn, ws_id, uid)
    if not member:
        # Autoreparación (legacy / alta de usuarios):
        # cuando se activa APP_WORKSPACE_MEMBERSHIP_ENFORCE en instalaciones existentes,
        # puede haber usuarios válidos sin fila en workspace_miembros. Intentamos auto-vincular
        # en casos "seguros" para no bloquear el acceso (home, RRHH, servicios).
        try:
            user_row = conn.execute(
                """
                SELECT id, activo, servicio, rol, registro_horario_activo, email, nombre, apellido
                FROM usuarios
                WHERE id = ?
                LIMIT 1
                """,
                (uid,),
            ).fetchone()
        except Exception:
            _rollback_best_effort(conn)
            user_row = None
        if user_row and int(row_value(user_row, "activo", 0) or 0) == 1:
            user_email = normalize_email(row_value(user_row, "email") or "")
            user_full_name = " ".join(
                part
                for part in [
                    str(row_value(user_row, "nombre") or "").strip(),
                    str(row_value(user_row, "apellido") or "").strip(),
                ]
                if part
            ).strip()
            # Evidencias de pertenencia:
            has_persona = False
            try:
                if conn.execute(
                    """
                    SELECT 1
                    FROM workspace_registro_personal
                    WHERE workspace_id = ? AND COALESCE(activo, 1) = 1 AND usuario_id = ?
                    LIMIT 1
                    """,
                    (ws_id, uid),
                ).fetchone():
                    has_persona = True
            except Exception:
                _rollback_best_effort(conn)
                has_persona = False
            if not has_persona and user_email:
                try:
                    if conn.execute(
                        """
                        SELECT 1
                        FROM workspace_registro_personal
                        WHERE workspace_id = ?
                          AND COALESCE(activo, 1) = 1
                          AND LOWER(TRIM(COALESCE(email, ''))) = LOWER(TRIM(?))
                        LIMIT 1
                        """,
                        (ws_id, user_email),
                    ).fetchone():
                        has_persona = True
                except Exception:
                    _rollback_best_effort(conn)
            if not has_persona and user_full_name:
                try:
                    if conn.execute(
                        """
                        SELECT 1
                        FROM workspace_registro_personal
                        WHERE workspace_id = ?
                          AND COALESCE(activo, 1) = 1
                          AND LOWER(TRIM(COALESCE(nombre, ''))) = LOWER(TRIM(?))
                        LIMIT 1
                        """,
                        (ws_id, user_full_name),
                    ).fetchone():
                        has_persona = True
                except Exception:
                    _rollback_best_effort(conn)
            single_workspace = False
            try:
                ws_count_row = conn.execute("SELECT COUNT(*) AS total FROM workspaces").fetchone()
                ws_total = int(row_value(ws_count_row, "total", 0) or row_value(ws_count_row, 0) or 0)
                single_workspace = ws_total == 1
            except Exception:
                _rollback_best_effort(conn)
                single_workspace = False

            # IMPORTANTE: en modo multi-tenant no auto-vinculamos usuarios "por defecto" solo por tener servicios
            # o fichaje activo. Eso provoca contaminación de miembros entre workspaces (usuarios acaban apareciendo
            # en RRHH/Equipo de un workspace al que no pertenecen).
            #
            # Auto-vinculación segura:
            # - instalaciones legacy con un único workspace
            # - o evidencia explícita de pertenencia (tiene ficha/registro personal dentro del workspace)
            should_autojoin = bool(single_workspace or has_persona)
            if should_autojoin:
                try:
                    ensure_workspace_core_tables(conn)
                except Exception:
                    _rollback_best_effort(conn)
                now_ts = datetime.now(timezone.utc).isoformat()
                ensure_workspace_member(conn, ws_id, uid, role="Miembro", now=now_ts)
                try:
                    conn.commit()
                except Exception:
                    _rollback_best_effort(conn)
                member = fetch_workspace_member(conn, ws_id, uid)
    if not member:
        return False, "No autorizado"
    if write and not workspace_member_can_write(member.get("rol")):
        return False, "No autorizado"
    return True, ""


def enforce_empresa_membership(conn, session, empresa_id, *, write=False):
    """
    Enforce that the authenticated user belongs to at least one workspace linked
    to the given empresa (when APP_WORKSPACE_MEMBERSHIP_ENFORCE is enabled).

    This closes a common gap for endpoints that only receive `empresa_id`
    (e.g. PDF generators) and not an explicit `workspace_id`.
    """
    if not WORKSPACE_MEMBERSHIP_ENFORCE:
        return True, ""
    if workspace_actor_is_privileged(conn, session):
        return True, ""
    eid = str(empresa_id or "").strip()
    if not eid:
        return False, "No autorizado"
    try:
        ws_rows = conn.execute(
            """
            SELECT workspace_id
            FROM workspace_empresas
            WHERE empresa_id = ?
            """,
            (eid,),
        ).fetchall()
    except Exception:
        _rollback_best_effort(conn)
        ws_rows = []
    workspace_ids = [
        str(row_value(r, "workspace_id") or row_value(r, 0) or "").strip()
        for r in (ws_rows or [])
        if str(row_value(r, "workspace_id") or row_value(r, 0) or "").strip()
    ]
    if not workspace_ids:
        # Legacy safety: if there is a single workspace, treat it as the implicit container.
        try:
            ws_count_row = conn.execute("SELECT COUNT(*) AS total FROM workspaces").fetchone()
            ws_total = int(row_value(ws_count_row, "total", 0) or row_value(ws_count_row, 0) or 0)
        except Exception:
            _rollback_best_effort(conn)
            ws_total = 0
        if ws_total == 1:
            try:
                one = conn.execute("SELECT id FROM workspaces LIMIT 1").fetchone()
                only_id = str(row_value(one, "id") or row_value(one, 0) or "").strip()
            except Exception:
                _rollback_best_effort(conn)
                only_id = ""
            if only_id:
                return enforce_workspace_membership(conn, session, only_id, write=write)
        return False, "Empresa sin workspace vinculado"
    last_err = ""
    for ws_id in workspace_ids:
        ok, err = enforce_workspace_membership(conn, session, ws_id, write=write)
        if ok:
            return True, ""
        last_err = err or last_err
    return False, last_err or "No autorizado"


def infer_workspace_id_for_empresa(conn, session, empresa_id):
    """
    Devuelve el workspace_id más probable para una empresa, a partir del usuario autenticado.
    Útil cuando el frontend no envía workspace_id (estado perdido).

    - Si hay 1 candidato: devuelve (workspace_id, []).
    - Si hay varios: devuelve ("", [candidatos]).
    - Si no hay: devuelve ("", []).
    """
    if not workspace_actor_is_privileged(conn, session):
        return "", []
    uid = str((session or {}).get("user_id") or "").strip()
    eid = str(empresa_id or "").strip()
    if not uid or not eid:
        return "", []
    rows = conn.execute(
        """
        SELECT DISTINCT mem.workspace_id
        FROM workspace_miembros mem
        JOIN workspace_empresas we ON we.workspace_id = mem.workspace_id
        WHERE mem.usuario_id = ? AND we.empresa_id = ?
        LIMIT 8
        """,
        (uid, eid),
    ).fetchall()
    candidates = [str(row_value(r, "workspace_id") or row_value(r, 0) or "").strip() for r in rows]
    candidates = [c for c in candidates if c]
    if len(candidates) == 1:
        return candidates[0], []
    return "", candidates


def fetch_api_usuarios(conn, session, *, workspace_id="", privileged=False):
    """
    Devuelve el listado de usuarios para `/api/usuarios`, aplicando scoping por workspace.

    - Usuarios no privilegiados: nunca ven el directorio global. Se limita al workspace indicado
      o, si no se indica, a los workspaces en los que el usuario es miembro. No incluye emails.
    - Usuarios privilegiados: puede ver el global, pero si el frontend envía workspace_id se filtra
      al directorio de ese workspace para evitar mezclar tenants. Incluye emails.
    """
    if not conn or not session:
        return []
    ws_id = str(workspace_id or "").strip()
    uid = str((session or {}).get("user_id") or "").strip()

    if not privileged:
        scope_ws_ids = []
        if ws_id:
            ok, err = enforce_workspace_membership(conn, session, ws_id)
            if not ok:
                raise PermissionError(err or "No autorizado")
            scope_ws_ids = [ws_id]
        elif uid:
            try:
                ws_rows = conn.execute(
                    "SELECT DISTINCT workspace_id FROM workspace_miembros WHERE usuario_id = ?",
                    (uid,),
                ).fetchall()
                scope_ws_ids = [
                    str(row_value(r, "workspace_id") or row_value(r, 0) or "").strip() for r in (ws_rows or [])
                ]
                scope_ws_ids = [w for w in scope_ws_ids if w]
            except Exception:
                scope_ws_ids = []

        if scope_ws_ids:
            placeholders = ",".join(["?"] * len(scope_ws_ids))
            rows = conn.execute(
                f"""
                SELECT DISTINCT
                       u.id, u.nombre, u.apellido, u.usuario, u.servicio, u.rol, u.activo,
                       COALESCE(u.registro_horario_activo, 0) AS registro_horario_activo
                FROM usuarios u
                JOIN workspace_miembros mem ON mem.usuario_id = u.id
                WHERE mem.workspace_id IN ({placeholders})
                  AND COALESCE(u.activo, 1) = 1
                ORDER BY u.nombre, u.apellido
                """,
                tuple(scope_ws_ids),
            ).fetchall()
            return [dict(r) for r in rows]

        if uid:
            rows = conn.execute(
                """
                SELECT id, nombre, apellido, usuario, servicio, rol, activo,
                       COALESCE(registro_horario_activo, 0) AS registro_horario_activo
                FROM usuarios
                WHERE id = ? AND COALESCE(activo, 1) = 1
                LIMIT 1
                """,
                (uid,),
            ).fetchall()
            return [dict(r) for r in rows]
        return []

    # Privileged
    if ws_id:
        rows = conn.execute(
            """
            SELECT DISTINCT
                   u.id, u.nombre, u.apellido, u.usuario, u.email, u.servicio, u.rol, u.activo,
                   COALESCE(u.registro_horario_activo, 0) AS registro_horario_activo
            FROM usuarios u
            JOIN workspace_miembros mem ON mem.usuario_id = u.id
            WHERE mem.workspace_id = ?
            ORDER BY u.nombre, u.apellido
            """,
            (ws_id,),
        ).fetchall()
        return [dict(r) for r in rows]

    # Si no se especifica workspace_id, evitamos devolver el directorio global: acotamos
    # a los workspaces en los que el actor es miembro (evita mezclar tenants).
    scope_ws_ids = []
    if uid:
        try:
            ws_rows = conn.execute(
                "SELECT DISTINCT workspace_id FROM workspace_miembros WHERE usuario_id = ?",
                (uid,),
            ).fetchall()
            scope_ws_ids = [
                str(row_value(r, "workspace_id") or row_value(r, 0) or "").strip() for r in (ws_rows or [])
            ]
            scope_ws_ids = [w for w in scope_ws_ids if w]
        except Exception:
            scope_ws_ids = []
    if not scope_ws_ids:
        return []
    placeholders = ",".join(["?"] * len(scope_ws_ids))
    rows = conn.execute(
        f"""
        SELECT DISTINCT
               u.id, u.nombre, u.apellido, u.usuario, u.email, u.servicio, u.rol, u.activo,
               COALESCE(u.registro_horario_activo, 0) AS registro_horario_activo
        FROM usuarios u
        JOIN workspace_miembros mem ON mem.usuario_id = u.id
        WHERE mem.workspace_id IN ({placeholders})
        ORDER BY u.nombre, u.apellido
        """,
        tuple(scope_ws_ids),
    ).fetchall()
    return [dict(r) for r in rows]


def resolve_legacy_empresa_id_from_workspace_company(conn, workspace_id, workspace_company_id):
    """
    En el modelo v2, la empresa operativa vive en `workspace_companies` (por workspace).
    Para compatibilidad con tablas legacy, resolvemos su `legacy_empresa_id` (empresas.id).
    """
    ws_id = str(workspace_id or "").strip()
    wc_id = str(workspace_company_id or "").strip()
    if not ws_id or not wc_id or not conn:
        return ""
    try:
        ensure_workspace_core_tables(conn)
    except Exception:
        _rollback_best_effort(conn)
    try:
        row = conn.execute(
            """
            SELECT legacy_empresa_id
            FROM workspace_companies
            WHERE workspace_id = ? AND id = ?
            LIMIT 1
            """,
            (ws_id, wc_id),
        ).fetchone()
    except Exception:
        _rollback_best_effort(conn)
        row = None
    legacy_id = str(row_value(row, "legacy_empresa_id") or row_value(row, 0) or "").strip() if row else ""
    return legacy_id


def resolve_request_legacy_empresa_id(conn, *, workspace_id="", empresa_id="", workspace_company_id=""):
    """
    Normaliza el id legacy de empresa para handlers que aceptan `workspace_company_id`.

    Mantiene la semántica existente:
    - `workspace_id` + `workspace_company_id` -> resuelve `legacy_empresa_id` cuando falta `empresa_id`.
    - `empresa_id` suelto -> si realmente apunta a `workspace_companies.id`, lo traduce a legacy.
    - cualquier otra combinación -> devuelve `empresa_id` tal cual.
    """
    ws_id = str(workspace_id or "").strip()
    eid = str(empresa_id or "").strip()
    wc_id = str(workspace_company_id or "").strip()
    if ws_id and wc_id and not eid:
        return resolve_legacy_empresa_id_from_workspace_company(conn, ws_id, wc_id) or ""
    if eid and not ws_id and not wc_id:
        try:
            ensure_workspace_core_tables(conn)
            row = conn.execute(
                """
                SELECT legacy_empresa_id
                FROM workspace_companies
                WHERE id = ?
                LIMIT 1
                """,
                (eid,),
            ).fetchone()
            legacy = str(row_value(row, "legacy_empresa_id") or row_value(row, 0) or "").strip() if row else ""
            if legacy:
                return legacy
        except Exception:
            _rollback_best_effort(conn)
    return eid


def resolve_payload_legacy_empresa_id(conn, session, payload, *, write=False):
    """
    Resuelve `empresa_id` legacy a partir de un payload que trae `workspace_id` y
    `workspace_company_id`.

    Devuelve (empresa_id_legacy, error_str). No infiere ni cae a platform; solo
    traduce la referencia v2 cuando ambas claves están presentes.
    """
    if not isinstance(payload, dict):
        return "", ""
    if str(payload.get("empresa_id") or "").strip():
        return "", ""
    ws_id = str(payload.get("workspace_id") or "").strip()
    wc_id = str(payload.get("workspace_company_id") or "").strip()
    if not ws_id or not wc_id:
        return "", ""
    try:
        eid_res, _wc, err = resolve_empresa_id_for_request(
            conn,
            session,
            workspace_id=ws_id,
            empresa_id="",
            workspace_company_id=wc_id,
            write=write,
        )
    except Exception:
        return "", "No autorizado"
    return str(eid_res or "").strip(), str(err or "").strip()


def resolve_empresa_id_for_request(conn, session, *, workspace_id="", empresa_id="", workspace_company_id="", write=False):
    """
    Resolución unificada:
    - Acepta `empresa_id` (legacy) o `workspace_company_id` (v2).
    - Enforce membership: si llega `workspace_id`, exige pertenencia del usuario.
    - Devuelve (empresa_id_legacy, workspace_company_id, error_str)
    """
    ws_id = str(workspace_id or "").strip()
    eid = str(empresa_id or "").strip()
    wc_id = str(workspace_company_id or "").strip()
    if ws_id:
        ok, err = enforce_workspace_membership(conn, session, ws_id, write=write)
        if not ok:
            return "", wc_id, err or "No autorizado"
    if ws_id and wc_id:
        resolved_eid = resolve_legacy_empresa_id_from_workspace_company(conn, ws_id, wc_id) or ""
        if not resolved_eid:
            return "", wc_id, "workspace_company_id no válido para workspace_id"
        if eid and eid != resolved_eid:
            return "", wc_id, "workspace_company_id no coincide con empresa_id"
        eid = resolved_eid
    return eid, wc_id, ""

def workspace_persona_id_for_user(conn, workspace_id, user_id):
    if not workspace_id or not user_id:
        return ""
    row = conn.execute(
        """
        SELECT id
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND usuario_id = ? AND COALESCE(activo, 1) = 1
        ORDER BY COALESCE(usuario_manual, 0) DESC, COALESCE(updated_at, created_at) DESC
        LIMIT 1
        """,
        (workspace_id, user_id),
    ).fetchone()
    if not row:
        return ""
    try:
        return str(row["id"] or "")
    except Exception:
        return str(row[0] or "")


def session_user_id(session):
    """
    Devuelve el id del usuario autenticado desde la sesión.
    Compatible con sesiones legacy que puedan usar otra clave.
    """
    if not isinstance(session, dict):
        return ""
    for key in ("user_id", "id", "usuario_id", "uid"):
        try:
            val = session.get(key)
        except Exception:
            val = None
        val = str(val or "").strip()
        if val:
            return val
    return ""


def ensure_workspace_persona_for_self(conn, workspace_id, session):
    """
    Garantiza que un usuario no privilegiado con `registro_horario_activo=1` tenga una ficha
    de `workspace_registro_personal` vinculada (usuario_id + usuario_manual=1) y con empresa_id,
    para poder fichar desde la app.
    """
    try:
        ws_id = str(workspace_id or "").strip()
        # Nota: aunque el usuario sea privilegiado (admin), esta función es segura porque solo crea/vincula
        # una ficha "self" para el `user_id` autenticado.
        if not ws_id or not session:
            return ""
        user_id = str(session.get("user_id") or "").strip()
        if not user_id:
            return ""
        user_row = conn.execute(
            """
            SELECT id, nombre, apellido, usuario, email, activo, servicio, registro_horario_activo
            FROM usuarios
            WHERE id = ?
            LIMIT 1
            """,
            (user_id,),
        ).fetchone()
        if not user_row:
            return ""
        if int(row_value(user_row, "activo", 1) or 0) != 1:
            return ""
        # Preferimos respetar fichas existentes: si ya hay una ficha vinculada (aunque sea legacy sin usuario_manual),
        # la promovemos y devolvemos.
        user_email = normalize_email(row_value(user_row, "email") or "")
        user_full_name = " ".join(
            part
            for part in [
                str(row_value(user_row, "nombre") or "").strip(),
                str(row_value(user_row, "apellido") or "").strip(),
            ]
            if part
        ).strip()

        # Empresa por defecto: usamos la primera empresa vinculada al workspace.
        # Importante: fetch_workspace_company_ids() hace backfill cuando workspace_empresas está vacío.
        empresa_ids = fetch_workspace_company_ids(conn, ws_id)
        empresa_default = str(empresa_ids[0] if empresa_ids else "").strip()

        now = datetime.now(timezone.utc).isoformat()

        # 0) Si ya tiene ficha con usuario_id (aunque usuario_manual=0), la promovemos.
        persona = conn.execute(
            """
            SELECT id, empresa_id, COALESCE(usuario_manual, 0) AS usuario_manual, COALESCE(source, '') AS source
            FROM workspace_registro_personal
            WHERE workspace_id = ? AND usuario_id = ? AND COALESCE(activo, 1) = 1
            ORDER BY COALESCE(usuario_manual, 0) DESC, COALESCE(updated_at, created_at) DESC
            LIMIT 1
            """,
            (ws_id, user_id),
        ).fetchone()
        if persona:
            persona_id = str(row_value(persona, "id") or row_value(persona, 0) or "").strip()
            if not persona_id:
                return ""
            updates = []
            params = []
            usuario_manual = int(row_value(persona, "usuario_manual", 0) or 0)
            if usuario_manual != 1:
                updates.append("usuario_manual = 1")
            source = str(row_value(persona, "source") or "").strip()
            if not source or source == "auto":
                updates.append("source = 'manual'")
            empresa_id = str(row_value(persona, "empresa_id") or "").strip()
            if not empresa_id and empresa_default:
                updates.append("empresa_id = ?")
                params.append(empresa_default)
                updates.append("empresa_manual = 1")
            if updates:
                conn.execute(
                    f"UPDATE workspace_registro_personal SET {', '.join(updates)}, updated_at = datetime(?) WHERE workspace_id = ? AND id = ?",
                    [*params, now, ws_id, persona_id],
                )
                try:
                    conn.commit()
                except Exception:
                    pass
            return persona_id

        # 1) Si existe una ficha con el mismo email (y sin usuario_id), la vinculamos.
        # Esto evita que el usuario vea "sin ficha" aunque RRHH ya haya creado su registro.
        if user_email:
            try:
                email_rows = conn.execute(
                    """
                    SELECT id, COALESCE(usuario_id, '') AS usuario_id,
                           COALESCE(empresa_id, '') AS empresa_id,
                           COALESCE(source, '') AS source
                    FROM workspace_registro_personal
                    WHERE workspace_id = ?
                      AND LOWER(TRIM(COALESCE(email, ''))) = LOWER(TRIM(?))
                      AND COALESCE(activo, 1) = 1
                    ORDER BY COALESCE(updated_at, created_at) DESC
                    LIMIT 6
                    """,
                    (ws_id, user_email),
                ).fetchall()
            except Exception:
                email_rows = []
            candidates = []
            for row in email_rows or []:
                cid = str(row_value(row, "id") or row_value(row, 0) or "").strip()
                existing_uid = str(row_value(row, "usuario_id") or "").strip()
                if not cid:
                    continue
                if existing_uid and existing_uid != user_id:
                    continue
                candidates.append(row)
            if len(candidates) == 1:
                candidate = candidates[0]
                candidate_id = str(row_value(candidate, "id") or row_value(candidate, 0) or "").strip()
                updates = ["usuario_id = ?", "usuario_manual = 1"]
                params = [user_id]
                source = str(row_value(candidate, "source") or "").strip()
                if not source or source == "auto":
                    updates.append("source = 'manual'")
                empresa_id = str(row_value(candidate, "empresa_id") or "").strip()
                if not empresa_id and empresa_default:
                    updates.append("empresa_id = ?")
                    params.append(empresa_default)
                    updates.append("empresa_manual = 1")
                conn.execute(
                    f"UPDATE workspace_registro_personal SET {', '.join(updates)}, updated_at = datetime(?) WHERE workspace_id = ? AND id = ?",
                    [*params, now, ws_id, candidate_id],
                )
                try:
                    conn.commit()
                except Exception:
                    pass
                return candidate_id

        # 2) Fallback: link por nombre completo exacto (evita casos con email vacío o compartido).
        if user_full_name:
            try:
                name_rows = conn.execute(
                    """
                    SELECT id, COALESCE(usuario_id, '') AS usuario_id,
                           COALESCE(empresa_id, '') AS empresa_id,
                           COALESCE(source, '') AS source
                    FROM workspace_registro_personal
                    WHERE workspace_id = ?
                      AND LOWER(TRIM(COALESCE(nombre, ''))) = LOWER(TRIM(?))
                      AND COALESCE(activo, 1) = 1
                    ORDER BY COALESCE(updated_at, created_at) DESC
                    LIMIT 6
                    """,
                    (ws_id, user_full_name),
                ).fetchall()
            except Exception:
                name_rows = []
            candidates = []
            for row in name_rows or []:
                cid = str(row_value(row, "id") or row_value(row, 0) or "").strip()
                existing_uid = str(row_value(row, "usuario_id") or "").strip()
                if not cid:
                    continue
                if existing_uid and existing_uid != user_id:
                    continue
                candidates.append(row)
            if len(candidates) == 1:
                candidate = candidates[0]
                candidate_id = str(row_value(candidate, "id") or row_value(candidate, 0) or "").strip()
                updates = ["usuario_id = ?", "usuario_manual = 1"]
                params = [user_id]
                source = str(row_value(candidate, "source") or "").strip()
                if not source or source == "auto":
                    updates.append("source = 'manual'")
                empresa_id = str(row_value(candidate, "empresa_id") or "").strip()
                if not empresa_id and empresa_default:
                    updates.append("empresa_id = ?")
                    params.append(empresa_default)
                    updates.append("empresa_manual = 1")
                conn.execute(
                    f"UPDATE workspace_registro_personal SET {', '.join(updates)}, updated_at = datetime(?) WHERE workspace_id = ? AND id = ?",
                    [*params, now, ws_id, candidate_id],
                )
                try:
                    conn.commit()
                except Exception:
                    pass
                return candidate_id

        # 3) Fallback robusto: match por tokens del nombre (ignora acentos y mayúsculas) cuando el nombre no coincide exacto.
        # Solo vinculamos si hay 1 candidato claro (evita enlaces erróneos).
        if user_full_name:
            try:
                target_tokens = [t for t in normalize_lookup_text(user_full_name).split() if t and t not in {"DE", "DEL", "LA", "LAS", "LOS", "Y"}]
            except Exception:
                target_tokens = []
            essential = []
            if target_tokens:
                essential.append(target_tokens[0])
                if len(target_tokens) > 1:
                    essential.append(target_tokens[-1])
            essential = [t for t in dict.fromkeys(essential) if t]
            if essential:
                try:
                    rows = conn.execute(
                        """
                        SELECT id, nombre, COALESCE(usuario_id, '') AS usuario_id,
                               COALESCE(empresa_id, '') AS empresa_id,
                               COALESCE(source, '') AS source
                        FROM workspace_registro_personal
                        WHERE workspace_id = ?
                          AND COALESCE(activo, 1) = 1
                          AND COALESCE(usuario_id, '') = ''
                        ORDER BY COALESCE(updated_at, created_at) DESC
                        LIMIT 1200
                        """,
                        (ws_id,),
                    ).fetchall()
                except Exception:
                    rows = []
                matches = []
                for row in rows or []:
                    name = str(row_value(row, "nombre") or "").strip()
                    if not name:
                        continue
                    try:
                        name_tokens = set(normalize_lookup_text(name).split())
                    except Exception:
                        name_tokens = set()
                    if not name_tokens:
                        continue
                    if all(tok in name_tokens for tok in essential):
                        matches.append(row)
                        if len(matches) > 2:
                            break
                if len(matches) == 1:
                    candidate = matches[0]
                    candidate_id = str(row_value(candidate, "id") or row_value(candidate, 0) or "").strip()
                    if candidate_id:
                        updates = ["usuario_id = ?", "usuario_manual = 1"]
                        params = [user_id]
                        source = str(row_value(candidate, "source") or "").strip()
                        if not source or source == "auto":
                            updates.append("source = 'manual'")
                        empresa_id = str(row_value(candidate, "empresa_id") or "").strip()
                        if not empresa_id and empresa_default:
                            updates.append("empresa_id = ?")
                            params.append(empresa_default)
                            updates.append("empresa_manual = 1")
                        conn.execute(
                            f"UPDATE workspace_registro_personal SET {', '.join(updates)}, updated_at = datetime(?) WHERE workspace_id = ? AND id = ?",
                            [*params, now, ws_id, candidate_id],
                        )
                        try:
                            conn.commit()
                        except Exception:
                            pass
                        return candidate_id

        # Si no existe ficha, solo auto-creamos si el usuario está habilitado para fichar.
        time_enabled = int(row_value(user_row, "registro_horario_activo", 0) or 0) == 1
        if not time_enabled:
            # Fallback: para evitar que nuevos usuarios se queden sin fichar, habilitamos
            # el auto-vínculo si su servicio parece "operativo" (inmobiliaria/gestoría/seguros/etc.).
            service_raw = str(row_value(user_row, "servicio", "") or "").strip().lower()
            if any(token in service_raw for token in ("gestor", "inmobili", "seguro", "finca", "financia", "obra", "reforma", "rrhh", "laboral")):
                time_enabled = True
        if not time_enabled:
            return ""

        # Sin ficha: creamos una mínima para permitir fichaje self.
        if not empresa_default:
            return ""
        full_name = user_full_name
        if not full_name:
            full_name = str(row_value(user_row, "usuario") or row_value(user_row, "email") or "Empleado").strip() or "Empleado"
        persona_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO workspace_registro_personal (
              id, workspace_id, empresa_id, empresa_manual,
              usuario_id, usuario_manual, source,
              nombre, nif, email, telefono,
              tipo_contrato, tipo_jornada, horas_pactadas_dia, horas_pactadas_semana,
              fecha_alta, fecha_baja, activo, notas,
              created_at, updated_at
            ) VALUES (
              ?, ?, ?, 1,
              ?, 1, 'manual',
              ?, NULL, ?, NULL,
              NULL, 'Completa', NULL, NULL,
              NULL, NULL, 1, ?,
              datetime(?), datetime(?)
            )
            """,
            (
                persona_id,
                ws_id,
                empresa_default,
                user_id,
                full_name,
                str(row_value(user_row, "email") or "").strip() or None,
                "Auto-creado para permitir fichaje (registro horario activo).",
                now,
                now,
            ),
        )
        try:
            conn.commit()
        except Exception:
            pass
        return persona_id
    except Exception:
        return ""


def log_workspace_registro_audit(conn, workspace_id, *, empresa_id=None, persona_id=None, entity_type="", entity_id="", action="", actor=None, before=None, after=None, now=None):
    now_ts = now or datetime.now().isoformat()
    session = actor or {}
    actor_user_id = str(session.get("user_id") or "").strip() or None
    actor_nombre = " ".join(
        part for part in [str(session.get("nombre") or "").strip(), str(session.get("apellido") or "").strip()] if part
    ).strip() or (str(session.get("usuario") or "").strip() or None)
    record_id = os.urandom(16).hex()
    before_json = json.dumps(before, ensure_ascii=False) if before is not None else None
    after_json = json.dumps(after, ensure_ascii=False) if after is not None else None
    conn.execute(
        """
        INSERT INTO workspace_registro_audit (
          id, workspace_id, empresa_id, persona_id, entity_type, entity_id, action,
          actor_user_id, actor_nombre, before_json, after_json, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            record_id,
            workspace_id,
            str(empresa_id or "").strip() or None,
            str(persona_id or "").strip() or None,
            str(entity_type or "").strip() or "registro",
            str(entity_id or "").strip() or None,
            str(action or "").strip() or "update",
            actor_user_id,
            actor_nombre,
            before_json,
            after_json,
            now_ts,
        ),
    )
    return record_id


