def _parse_iso_date(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.strptime(raw[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def _count_business_days(start_date, end_date):
    if not start_date or not end_date or end_date < start_date:
        return 0
    days = 0
    cursor = start_date
    while cursor <= end_date:
        if cursor.weekday() < 5:
            days += 1
        cursor += timedelta(days=1)
    return days


def _count_calendar_days(start_date, end_date):
    if not start_date or not end_date or end_date < start_date:
        return 0
    return (end_date - start_date).days + 1


def _count_absence_days(start_date, end_date, mode="habiles"):
    mode_key = str(mode or "").strip().lower()
    if mode_key in {"naturales", "natural", "calendario", "calendar"}:
        return _count_calendar_days(start_date, end_date)
    return _count_business_days(start_date, end_date)


def _fetch_empresa_vacaciones_modo_map(conn, empresa_ids):
    ids = [str(i or "").strip() for i in list(empresa_ids or []) if str(i or "").strip()]
    if not ids:
        return {}
    placeholders = ",".join(["?"] * len(ids))
    rows = conn.execute(
        f"SELECT id, COALESCE(NULLIF(vacaciones_modo,''), 'habiles') AS modo FROM empresas WHERE id IN ({placeholders})",
        ids,
    ).fetchall()
    return {str(r["id"]): str(r["modo"] or "habiles") for r in rows if str(r["id"] or "").strip()}


def fetch_workspace_rrhh_vacaciones_summary(conn, workspace_id, year=None):
    try:
        year_int = int(str(year or "").strip() or datetime.now().year)
    except Exception:
        year_int = datetime.now().year
    year_int = max(2000, min(year_int, 2100))
    year_start = date(year_int, 1, 1)
    year_end = date(year_int, 12, 31)

    # Totales por persona (si no hay perfil, asumimos 22).
    profile_rows = conn.execute(
        """
        SELECT persona_id, COALESCE(vacaciones_dias_anuales, 22) AS dias_total
        FROM workspace_rrhh_profile
        WHERE workspace_id = ?
        """,
        (workspace_id,),
    ).fetchall()
    total_map = {str(r["persona_id"]): float(r["dias_total"] or 22) for r in profile_rows if str(r["persona_id"] or "").strip()}

    # Personas del workspace (excluye legacy auto).
    personal_rows = conn.execute(
        """
        SELECT id AS persona_id
        FROM workspace_registro_personal
        WHERE workspace_id = ?
          AND COALESCE(source, 'manual') != 'auto'
        """,
        (workspace_id,),
    ).fetchall()
    persona_ids = [str(r["persona_id"]) for r in personal_rows if str(r["persona_id"] or "").strip()]

    # Vacaciones aprobadas del año.
    abs_rows = conn.execute(
        """
        SELECT persona_id, empresa_id, fecha_inicio, fecha_fin
        FROM workspace_rrhh_ausencias
        WHERE workspace_id = ?
          AND tipo = 'Vacaciones'
          AND estado = 'Aprobada'
          AND (substr(fecha_inicio, 1, 4) = ? OR substr(fecha_fin, 1, 4) = ?)
        """,
        (workspace_id, str(year_int), str(year_int)),
    ).fetchall()
    empresa_ids = {str(r["empresa_id"] or "").strip() for r in abs_rows if str(r["empresa_id"] or "").strip()}
    vac_mode_map = _fetch_empresa_vacaciones_modo_map(conn, empresa_ids)
    used_map = {pid: 0 for pid in persona_ids}
    for row in abs_rows:
        pid = str(row["persona_id"] or "").strip()
        if not pid:
            continue
        start = _parse_iso_date(row["fecha_inicio"])
        end = _parse_iso_date(row["fecha_fin"])
        if not start or not end:
            continue
        if end < year_start or start > year_end:
            continue
        clipped_start = max(start, year_start)
        clipped_end = min(end, year_end)
        modo = vac_mode_map.get(str(row["empresa_id"] or "").strip(), "habiles")
        used_map[pid] = used_map.get(pid, 0) + _count_absence_days(clipped_start, clipped_end, modo)

    rows = []
    for pid in persona_ids:
        total = float(total_map.get(pid, 22) or 22)
        used = float(used_map.get(pid, 0) or 0)
        pending = max(total - used, 0.0)
        rows.append(
            {
                "persona_id": pid,
                "year": year_int,
                "dias_total": round(total, 2),
                "dias_usados": round(used, 2),
                "dias_pendientes": round(pending, 2),
            }
        )
    return {"rows": rows}


def _parse_alert_last_sent(value):
    raw = str(value or "").strip()
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _update_alert_last_sent(conn, workspace_id, persona_id, updates, now=None):
    now_ts = now or app_now().isoformat()
    existing = conn.execute(
        """
        SELECT alert_last_sent
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    current = _parse_alert_last_sent(existing["alert_last_sent"] if existing else "")
    current.update({k: v for k, v in (updates or {}).items() if v})
    conn.execute(
        """
        UPDATE workspace_registro_personal
        SET alert_last_sent = ?, updated_at = datetime(?)
        WHERE workspace_id = ? AND id = ?
        """,
        (json.dumps(current, ensure_ascii=False), now_ts, workspace_id, persona_id),
    )


def _ensure_workspace_time_sweep_schema(conn):
    global WORKSPACE_TIME_SWEEP_SCHEMA_READY
    if WORKSPACE_TIME_SWEEP_SCHEMA_READY and _m5_migration_done(conn, "workspace_time_sweep_schema_v1"):
        return True
    with WORKSPACE_TIME_SWEEP_SCHEMA_LOCK:
        if WORKSPACE_TIME_SWEEP_SCHEMA_READY and _m5_migration_done(conn, "workspace_time_sweep_schema_v1"):
            return True
        try:
            ensure_workspace_product_tables(conn)
            _ensure_m5_perf_indexes(conn)
            _m5_migration_mark(conn, "workspace_time_sweep_schema_v1")
            WORKSPACE_TIME_SWEEP_SCHEMA_READY = True
            return True
        except Exception:
            return False


def _workspace_time_sweep_candidate_rows(conn, batch_size=None):
    active_states = ("Activo", "ACTIVO", "activo", "Activa", "ACTIVA", "activa")
    try:
        limit_val = max(1, min(int(batch_size or WORKSPACE_TIME_SWEEP_BATCH_SIZE), 500))
    except Exception:
        limit_val = WORKSPACE_TIME_SWEEP_BATCH_SIZE
    rows = conn.execute(
        f"""
        SELECT w.id
        FROM workspaces w
        WHERE COALESCE(w.estado, '') IN ({",".join(["?"] * len(active_states))})
          AND EXISTS (
            SELECT 1
            FROM workspace_modulos wm
            WHERE wm.workspace_id = w.id
              AND wm.modulo_key = 'registro_horario'
              AND COALESCE(wm.enabled, 0) = 1
          )
          AND EXISTS (
            SELECT 1
            FROM workspace_registro_personal p
            WHERE p.workspace_id = w.id
              AND COALESCE(p.activo, 1) = 1
          )
        ORDER BY COALESCE(w.updated_at, w.created_at) ASC, w.nombre COLLATE NOCASE ASC
        LIMIT ?
        """,
        [*active_states, limit_val],
    ).fetchall()
    return [str(row_value(row, "id") or row_value(row, 0) or "").strip() for row in rows if str(row_value(row, "id") or row_value(row, 0) or "").strip()]


def _run_workspace_time_sweep_cycle(conn, batch_size=None):
    started_at = time.perf_counter()
    if not WORKSPACE_TIME_SWEEP_LOCK.acquire(blocking=False):
        return {"skipped": True, "workspaces": 0, "notifications": 0, "errors": 0, "last_error": "", "queries": 0}
    workspaces_processed = 0
    notifications_total = 0
    error_count = 0
    last_error = ""
    try:
        if not _ensure_workspace_time_sweep_schema(conn):
            last_error = "workspace_time_sweep_schema_unavailable"
            error_count = 1
            result = {
                "skipped": False,
                "workspaces": 0,
                "notifications": 0,
                "errors": error_count,
                "last_error": last_error,
                "queries": 0,
            }
            _perf_log_operation(
                "workspace_time_sweep_loop",
                started_at,
                rows=0,
                queries=0,
            )
            return result
        try:
            conn.commit()
        except Exception:
            pass
        workspace_ids = _workspace_time_sweep_candidate_rows(conn, batch_size=batch_size)
        for workspace_id in workspace_ids:
            if not workspace_id:
                continue
            workspaces_processed += 1
            try:
                created = run_workspace_time_missing_sweep(conn, workspace_id)
                if created:
                    notifications_total += len(created)
                    try:
                        conn.commit()
                    except Exception:
                        pass
            except Exception as exc:
                error_count += 1
                last_error = f"{workspace_id}: {exc}"
                LOGGER.exception("workspace time sweep failed for workspace_id=%s", workspace_id)
                try:
                    conn.rollback()
                except Exception:
                    pass
                continue
        approx_queries = 1 + (workspaces_processed * 4)
        _perf_log_operation(
            "workspace_time_sweep_loop",
            started_at,
            rows=workspaces_processed,
            queries=approx_queries,
        )
        return {
            "skipped": False,
            "workspaces": workspaces_processed,
            "notifications": notifications_total,
            "errors": error_count,
            "last_error": last_error,
            "queries": approx_queries,
        }
    except Exception as exc:
        error_count += 1
        if not last_error:
            last_error = str(exc)
        LOGGER.exception("workspace time sweep cycle failed")
        approx_queries = 1 + (workspaces_processed * 4)
        _perf_log_operation(
            "workspace_time_sweep_loop",
            started_at,
            rows=workspaces_processed,
            queries=approx_queries,
        )
        return {
            "skipped": False,
            "workspaces": workspaces_processed,
            "notifications": notifications_total,
            "errors": error_count,
            "last_error": last_error,
            "queries": approx_queries,
        }
    finally:
        try:
            WORKSPACE_TIME_SWEEP_LOCK.release()
        except Exception:
            pass


def run_workspace_time_missing_sweep(conn, workspace_id, now=None):
    # Importante: Render suele ejecutar en UTC. Para alertas (faltan entrada/salida) usamos hora local.
    if now:
        now_ts = now
        now_dt = _parse_iso_dt_utc(now_ts) or app_now()
    else:
        now_dt = app_now()
        now_ts = now_dt.isoformat()
    today = now_dt.date().isoformat()
    weekday = now_dt.isoweekday()  # 1=Lunes .. 7=Domingo
    now_minutes = parse_hhmm_to_minutes(now_dt.strftime("%H:%M")) or 0
    personal = conn.execute(
        """
        SELECT id, workspace_id, empresa_id, nombre, horas_pactadas_dia,
               COALESCE(alert_missing_checkin, 1) AS alert_missing_checkin,
               COALESCE(alert_missing_checkout, 1) AS alert_missing_checkout,
               COALESCE(alert_notify_worker, 1) AS alert_notify_worker,
               COALESCE(alert_notify_admin, 1) AS alert_notify_admin,
               COALESCE(alert_admin_contact, '') AS alert_admin_contact,
               COALESCE(alert_last_sent, '') AS alert_last_sent
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND COALESCE(activo, 1) = 1
        ORDER BY nombre COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    created = []
    persona_ids = [str(row["id"] or "").strip() for row in personal if str(row["id"] or "").strip()]
    persona_placeholders = ",".join(["?"] * len(persona_ids)) if persona_ids else ""
    alerts_by_persona = {}
    if persona_ids:
        alert_rows = conn.execute(
            f"""
            SELECT workspace_id, empresa_id, persona_id, alert_missing_checkin, alert_missing_checkout,
                   notify_worker, notify_admin, admin_contact, schedule
            FROM workspace_registro_alerts
            WHERE workspace_id = ?
              AND persona_id IN ({persona_placeholders})
            """,
            [workspace_id, *persona_ids],
        ).fetchall()
        for alert_row in alert_rows:
            persona_key = str(alert_row["persona_id"] or "").strip()
            if persona_key:
                alerts_by_persona[persona_key] = dict(alert_row)
    turnos_by_persona = {}
    if persona_ids:
        turnos_rows = conn.execute(
            f"""
            SELECT persona_id, enabled, COALESCE(hora_inicio,'') AS hora_inicio, COALESCE(hora_fin,'') AS hora_fin
            FROM workspace_rrhh_turnos
            WHERE workspace_id = ?
              AND weekday = ?
              AND persona_id IN ({persona_placeholders})
            """,
            [workspace_id, int(weekday), *persona_ids],
        ).fetchall()
        for turno_row in turnos_rows:
            persona_key = str(turno_row["persona_id"] or "").strip()
            if persona_key:
                turnos_by_persona[persona_key] = dict(turno_row)
    today_entries = {}
    if persona_ids:
        entries_rows = conn.execute(
            f"""
            SELECT id, persona_id, hora_inicio, hora_fin
            FROM (
              SELECT
                id,
                persona_id,
                hora_inicio,
                hora_fin,
                ROW_NUMBER() OVER (
                  PARTITION BY persona_id
                  ORDER BY COALESCE(NULLIF(hora_inicio, ''), '00:00') DESC,
                           COALESCE(updated_at, created_at, id) DESC
                ) AS rn
              FROM workspace_registro_horario
              WHERE workspace_id = ?
                AND fecha = ?
                AND persona_id IN ({persona_placeholders})
            ) AS today_entries
            WHERE rn = 1
            """,
            [workspace_id, today, *persona_ids],
        ).fetchall()
        for entry_row in entries_rows:
            persona_key = str(entry_row["persona_id"] or "").strip()
            if persona_key:
                today_entries[persona_key] = dict(entry_row)
    for row in personal:
        persona_id = str(row["id"] or "").strip()
        if not persona_id:
            continue
        alert_row = alerts_by_persona.get(persona_id)
        if alert_row:
            prefs = dict(alert_row)
            prefs.setdefault("workspace_id", workspace_id)
            prefs.setdefault("empresa_id", row["empresa_id"])
            prefs.setdefault("persona_id", persona_id)
            prefs.setdefault("alert_missing_checkin", row["alert_missing_checkin"])
            prefs.setdefault("alert_missing_checkout", row["alert_missing_checkout"])
            prefs.setdefault("notify_worker", row["alert_notify_worker"])
            prefs.setdefault("notify_admin", row["alert_notify_admin"])
            prefs.setdefault("admin_contact", row["alert_admin_contact"] or "")
            prefs.setdefault("schedule", "")
        else:
            prefs = {
                "workspace_id": workspace_id,
                "empresa_id": row["empresa_id"],
                "persona_id": persona_id,
                "alert_missing_checkin": row["alert_missing_checkin"],
                "alert_missing_checkout": row["alert_missing_checkout"],
                "notify_worker": row["alert_notify_worker"],
                "notify_admin": row["alert_notify_admin"],
                "admin_contact": row["alert_admin_contact"] or "",
                "schedule": "",
            }
        turno = turnos_by_persona.get(persona_id)
        if turno is not None:
            try:
                if int(turno.get("enabled") or turno["enabled"] or 0) == 0:
                    continue
            except Exception:
                pass
        schedule = str(prefs.get("schedule") or "").strip() or "10:00"
        turno_inicio = str((turno.get("hora_inicio") if isinstance(turno, dict) else turno["hora_inicio"]) or "").strip() if turno is not None else ""
        turno_fin = str((turno.get("hora_fin") if isinstance(turno, dict) else turno["hora_fin"]) or "").strip() if turno is not None else ""
        checkin_deadline = parse_hhmm_to_minutes(turno_inicio) if turno_inicio else (parse_hhmm_to_minutes(schedule) or 600)
        horas_pactadas = row["horas_pactadas_dia"]
        try:
            horas_pactadas = float(horas_pactadas) if horas_pactadas not in (None, "") else 8.0
        except Exception:
            horas_pactadas = 8.0
        if turno_fin:
            checkout_deadline = (parse_hhmm_to_minutes(turno_fin) or (checkin_deadline + int(round(horas_pactadas * 60)))) + 30
        else:
            checkout_deadline = checkin_deadline + int(round(horas_pactadas * 60)) + 30
        last_sent = _parse_alert_last_sent(row["alert_last_sent"])
        worker_payload = {
            "persona_nombre": row["nombre"],
            "fecha": today,
            "empresa_id": row["empresa_id"],
            "admin_contact": prefs.get("admin_contact") or row["alert_admin_contact"] or "",
        }
        today_entry = today_entries.get(persona_id)
        has_checkin = bool(today_entry and str(today_entry["hora_inicio"] or "").strip())
        open_entry = bool(today_entry and not str(today_entry["hora_fin"] or "").strip())
        if not has_checkin and now_minutes >= checkin_deadline and int(prefs.get("alert_missing_checkin") or row["alert_missing_checkin"] or 0) == 1:
            if last_sent.get("missing_checkin") != today:
                if int(prefs.get("notify_worker") or row["alert_notify_worker"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "worker_missing_checkin", worker_payload, now=now_ts)
                    created.append("worker_missing_checkin")
                if int(prefs.get("notify_admin") or row["alert_notify_admin"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "admin_missing_checkin", worker_payload, now=now_ts)
                    created.append("admin_missing_checkin")
                _update_alert_last_sent(conn, workspace_id, persona_id, {"missing_checkin": today}, now=now_ts)
        if open_entry and now_minutes >= checkout_deadline and int(prefs.get("alert_missing_checkout") or row["alert_missing_checkout"] or 0) == 1:
            if last_sent.get("missing_checkout") != today:
                if int(prefs.get("notify_worker") or row["alert_notify_worker"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "worker_missing_checkout", worker_payload, now=now_ts)
                    created.append("worker_missing_checkout")
                if int(prefs.get("notify_admin") or row["alert_notify_admin"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "admin_missing_checkout", worker_payload, now=now_ts)
                    created.append("admin_missing_checkout")
                _update_alert_last_sent(conn, workspace_id, persona_id, {"missing_checkout": today}, now=now_ts)
    return created


def workspace_time_sweep_loop(db_path, interval_seconds=300):
    while True:
        conn = None
        try:
            conn = get_db(db_path)
            cycle = _run_workspace_time_sweep_cycle(conn, batch_size=WORKSPACE_TIME_SWEEP_BATCH_SIZE)
            if cycle.get("skipped"):
                time.sleep(max(60, int(interval_seconds or 300)))
                continue
            with WORKSPACE_TIME_SWEEP_STATE_LOCK:
                WORKSPACE_TIME_SWEEP_STATE["last_run_at"] = datetime.now().isoformat()
                WORKSPACE_TIME_SWEEP_STATE["last_error"] = str(cycle.get("last_error") or "")
                WORKSPACE_TIME_SWEEP_STATE["last_workspaces"] = int(cycle.get("workspaces") or 0)
                WORKSPACE_TIME_SWEEP_STATE["last_notifications"] = int(cycle.get("notifications") or 0)
        except Exception as exc:
            try:
                if conn is not None:
                    conn.close()
            except Exception:
                pass
            with WORKSPACE_TIME_SWEEP_STATE_LOCK:
                WORKSPACE_TIME_SWEEP_STATE["last_run_at"] = datetime.now().isoformat()
                WORKSPACE_TIME_SWEEP_STATE["last_error"] = str(exc)
        finally:
            try:
                if conn is not None:
                    conn.close()
            except Exception:
                pass
        time.sleep(max(60, int(interval_seconds or 300)))


def legal_radar_auto_scan_loop(db_path, interval_seconds=3600):
    # No usamos sync_knowledge aquí para evitar que un proceso background reescriba JSON del repo.
    # El "reservorio" principal es la tabla legal_radar_items; el admin puede sincronizar manualmente si lo desea.
    if LEGAL_RADAR_AUTO_SCAN_ON_START:
        time.sleep(5)
    while True:
        try:
            conn = get_db(db_path)
            now_ts = datetime.now(timezone.utc).isoformat()
            created_total = 0
            updated_total = 0
            imported_total = 0
            for area_key in list(LEGAL_AREA_DEFINITIONS.keys()):
                result = scan_legal_radar_sources(conn, area=area_key, now=now_ts, sync_knowledge=False)
                created_total += int(result.get("created") or 0)
                updated_total += int(result.get("updated") or 0)
                if LEGAL_RADAR_AUTO_IMPORT_ENABLED:
                    try:
                        imp = import_legal_radar_items_to_library(conn, area=area_key, limit=LEGAL_RADAR_AUTO_IMPORT_LIMIT, now=now_ts)
                        imported_total += int(imp.get("imported") or 0)
                    except Exception:
                        pass
            try:
                conn.commit()
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass
            with LEGAL_RADAR_AUTO_SCAN_LOCK:
                LEGAL_RADAR_AUTO_SCAN_STATE["last_run_at"] = now_ts
                LEGAL_RADAR_AUTO_SCAN_STATE["last_error"] = ""
                LEGAL_RADAR_AUTO_SCAN_STATE["last_created"] = created_total
                LEGAL_RADAR_AUTO_SCAN_STATE["last_updated"] = updated_total
                LEGAL_RADAR_AUTO_SCAN_STATE["last_imported"] = imported_total
        except Exception as exc:
            try:
                conn.close()
            except Exception:
                pass
            with LEGAL_RADAR_AUTO_SCAN_LOCK:
                LEGAL_RADAR_AUTO_SCAN_STATE["last_run_at"] = datetime.now(timezone.utc).isoformat()
                LEGAL_RADAR_AUTO_SCAN_STATE["last_error"] = str(exc)
        time.sleep(max(300, int(interval_seconds or 3600)))


def run_workspace_time_alerts(conn, workspace_id, entry, now=None):
    now_ts = now or datetime.now().isoformat()
    persona_id = entry.get("persona_id")
    persona_nombre = entry.get("persona_nombre")
    company_name = entry.get("empresa_nombre") or ""
    prefs = fetch_workspace_alert_preferences(conn, workspace_id, persona_id=persona_id)
    if not prefs:
        return []
    notifications = []
    worker_payload = {
        "persona_nombre": persona_nombre,
        "fecha": entry.get("fecha"),
        "hora_inicio": entry.get("hora_inicio") or "",
        "hora_fin": entry.get("hora_fin") or "",
        "empresa_nombre": company_name,
    }
    event = normalize_lookup_text(entry.get("event") or "")
    # Missing check-in/out alerts are computed by a periodic sweep endpoint (no background scheduler).
    if event in {"checkin", "entrada"}:
        if prefs.get("notify_admin"):
            log_workspace_notification(conn, workspace_id, persona_id, "admin_entry_log", worker_payload, now=now_ts)
            notifications.append("admin_entry_log")
        if prefs.get("notify_worker"):
            log_workspace_notification(conn, workspace_id, persona_id, "worker_entry_log", worker_payload, now=now_ts)
            notifications.append("worker_entry_log")
    if event in {"checkout", "salida", "cierre"}:
        if prefs.get("notify_admin"):
            log_workspace_notification(conn, workspace_id, persona_id, "admin_exit_log", worker_payload, now=now_ts)
            notifications.append("admin_exit_log")
        if prefs.get("notify_worker"):
            log_workspace_notification(conn, workspace_id, persona_id, "worker_exit_log", worker_payload, now=now_ts)
            notifications.append("worker_exit_log")
    return notifications


def fetch_workspace_time_sweep_status():
    with WORKSPACE_TIME_SWEEP_STATE_LOCK:
        return dict(WORKSPACE_TIME_SWEEP_STATE)


def build_workspace_time_xml(rows, persona_name="", company_name="", month=""):
    root = ET.Element(
        "registro_horario",
        workspace=normalize_lookup_text(persona_name or ""),
        empresa=company_name or "",
        mes=month or "",
        timezone=APP_TIMEZONE,
        generated_at=app_now().strftime("%Y-%m-%d %H:%M:%S"),
        retention_years=str(WORKSPACE_TIME_RETENTION_YEARS),
        legal_basis="art. 34.9 Estatuto de los Trabajadores",
    )
    for row in rows:
        entry = ET.SubElement(root, "entrada")
        ET.SubElement(entry, "fecha").text = row.get("fecha") or ""
        ET.SubElement(entry, "hora_inicio").text = row.get("hora_inicio") or ""
        ET.SubElement(entry, "hora_fin").text = row.get("hora_fin") or ""
        ET.SubElement(entry, "pausa_min").text = str(row.get("pausa_min") or 0)
        ET.SubElement(entry, "minutos_trabajados").text = str(row.get("minutos_trabajados") or 0)
        ET.SubElement(entry, "tipo_jornada").text = row.get("tipo_jornada") or ""
        ET.SubElement(entry, "estado").text = row.get("estado") or ""
        ET.SubElement(entry, "notas").text = row.get("notas") or ""
    return ET.tostring(root, encoding="utf-8", xml_declaration=True)


def build_workspace_time_pdf(persona, workspace, company, rows):
    month = persona.get("month") or ""
    worker_name = persona.get("persona_nombre") or persona.get("nombre") or "-"
    worker_nif = persona.get("nif") or persona.get("persona_nif") or ""
    worker_email = persona.get("email") or persona.get("persona_email") or ""
    company_nif = company.get("nif") or company.get("cif") or ""
    company_addr = company.get("direccion") or ""
    generated_at = app_now().strftime("%d/%m/%Y %H:%M:%S")
    sections = [
        (
            "Identificación",
            [
                ("Nombre", worker_name),
                ("DNI/NIF", worker_nif or "-"),
                ("Email", worker_email or "-"),
                ("Empresa", company.get("nombre") or "-"),
                ("CIF/NIF empresa", company_nif or "-"),
                ("Centro / dirección", company_addr or "-"),
                ("Workspace", workspace.get("nombre") or "-"),
                ("Mes", month or "Completo"),
                ("Zona horaria", APP_TIMEZONE),
                ("Generado", generated_at),
            ],
        ),
        (
            "Resumen",
            [
                ("Jornada", persona.get("tipo_jornada") or "-"),
                ("Horas pactadas", persona.get("horas_pactadas_hhmm") or "-"),
                ("Horas reales", persona.get("horas_trabajadas_hhmm") or "-"),
                ("Desviación", persona.get("desviacion_hhmm") or "-"),
            ],
        ),
        (
            "Detalle diario",
            [
                (
                    f"{row.get('fecha') or '-'} · Entrada {row.get('hora_inicio') or '-'} · Salida {row.get('hora_fin') or '-'}"
                    f" · Pausa {int(row.get('pausa_min') or 0)}m · Trabajado {format_minutes_hhmm(row.get('minutos_trabajados') or 0)}"
                    f" · Método {row.get('metodo_registro') or '-'} · Estado {row.get('estado') or '-'}"
                ).strip()
                for row in (rows or [])
            ]
            or ["Sin fichajes en el periodo seleccionado."],
        ),
        (
            "Firmas",
            [
                "Firma trabajador: ________________________________",
                "Firma empresa: ___________________________________",
            ],
        ),
    ]
    footer = [
        "Registro horario diario (art. 34.9 Estatuto de los Trabajadores). Conservar durante 4 años y mantener accesible para la persona trabajadora y la representación legal.",
        f"Las horas reflejadas están en hora local ({APP_TIMEZONE}).",
    ]
    return build_branded_document_pdf(
        "REGISTRO HORARIO",
        f"{company.get('nombre') or 'Empresa'} · {month or 'Periodo completo'}",
        sections,
        footer_lines=footer,
        brand_logo_url=company.get("logo_url"),
    )


def parse_non_negative_int(value):
    text = str(value or "").strip()
    if not text:
        return 0
    try:
        return max(0, int(float(text)))
    except Exception:
        return 0


def compute_fincas_cuota_sugerida(num_vecinos=0, num_locales=0, num_trasteros=0, num_aparcamientos=0):
    total = (
        parse_non_negative_int(num_vecinos) * 5
        + parse_non_negative_int(num_locales)
        + parse_non_negative_int(num_trasteros)
        + parse_non_negative_int(num_aparcamientos)
    )
    return round(max(60, total), 2)


def normalize_workspace_budget_state(value):
    raw = normalize_lookup_text(value)
    if raw in {"aceptado", "aceptada", "aceptar"}:
        return "Aceptado"
    if raw in {"estudio", "en estudio", "pendiente estudio"}:
        return "Estudio"
    if raw in {"rechazado", "rechazada", "rechazar", "descartado", "descartada"}:
        return "Rechazado"
    if raw in {"encargado", "contratado"}:
        return "Aceptado"
    return "Borrador"


def workspace_budget_followup_default(status, base_date=""):
    base = parse_iso_date(base_date) or datetime.now().date()
    if status == "Estudio":
        return (base + timedelta(days=7)).isoformat()
    if status == "Rechazado":
        return (base + timedelta(days=30)).isoformat()
    if status == "Aceptado":
        return base.isoformat()
    return ""


def workspace_budget_service_label(servicio):
    key = normalize_service_key(servicio or "")
    if key == "gestoria":
        return "Gestoría"
    if key in {"fincas", "administracion fincas"}:
        return "Administración de fincas"
    if key == "reformas":
        return "Reformas"
    return (servicio or "Gestión").strip() or "Gestión"


def workspace_budget_action_service(servicio):
    key = normalize_service_key(servicio or "")
    if key in {"gestoria", "fincas", "administracion fincas"}:
        return "gestoria"
    return key or "gestoria"


def upsert_workspace_budget_action(
    conn,
    *,
    action_id=None,
    empresa_id=None,
    servicio=None,
    cliente_id=None,
    cliente_nombre=None,
    fecha=None,
    tipo=None,
    responsable=None,
    estado="Pendiente",
    notas=None,
    now=None,
):
    if not empresa_id or not fecha or not tipo:
        return action_id or ""
    if action_id:
        existing = conn.execute("SELECT id FROM acciones WHERE id = ? LIMIT 1", (action_id,)).fetchone()
        if existing:
            conn.execute(
                """
                UPDATE acciones
                SET empresa_id = ?, servicio = ?, cliente_id = ?, cliente_nombre = ?, fecha = ?, tipo = ?,
                    responsable = ?, estado = ?, notas = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    empresa_id,
                    servicio,
                    cliente_id,
                    cliente_nombre,
                    fecha,
                    tipo,
                    responsable,
                    estado,
                    notas,
                    now,
                    action_id,
                ),
            )
            return action_id
    action_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO acciones (
          id, empresa_id, servicio, cliente_id, cliente_nombre, fecha, tipo, responsable, estado, notas, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
        """,
        (
            action_id,
            empresa_id,
            servicio,
            cliente_id,
            cliente_nombre,
            fecha,
            tipo,
            responsable,
            estado,
            notas,
            now,
            now,
        ),
    )
    return action_id


def close_workspace_budget_action(conn, action_id, now=None, status="Hecho"):
    if not action_id:
        return
    conn.execute(
        "UPDATE acciones SET estado = ?, updated_at = datetime(?) WHERE id = ?",
        (status, now, action_id),
    )


def ensure_workspace_budget_client(
    conn,
    *,
    workspace_id,
    empresa_id,
    servicio,
    cliente_id=None,
    cliente_lookup="",
    cliente_nif="",
    cliente_telefono="",
    cliente_email="",
    fecha_inicio="",
    now=None,
):
    lookup = re.sub(r"\s+", " ", str(cliente_lookup or "")).strip()
    nif = re.sub(r"\s+", "", str(cliente_nif or "")).upper()
    row = None
    if cliente_id:
        row = conn.execute(
            "SELECT id, nombre, COALESCE(nif, '') AS nif, COALESCE(telefono, '') AS telefono, COALESCE(email, '') AS email FROM clientes WHERE id = ? LIMIT 1",
            (cliente_id,),
        ).fetchone()
    if not row and nif:
        row = conn.execute(
            "SELECT id, nombre, COALESCE(nif, '') AS nif, COALESCE(telefono, '') AS telefono, COALESCE(email, '') AS email FROM clientes WHERE REPLACE(UPPER(COALESCE(nif, '')), ' ', '') = ? LIMIT 1",
            (nif,),
        ).fetchone()
    if not row and lookup:
        row = conn.execute(
            "SELECT id, nombre, COALESCE(nif, '') AS nif, COALESCE(telefono, '') AS telefono, COALESCE(email, '') AS email FROM clientes WHERE TRIM(UPPER(nombre)) = ? LIMIT 1",
            (lookup.upper(),),
        ).fetchone()
    if not row and lookup:
        cliente_id = os.urandom(16).hex()
        conn.execute(
            """
                INSERT INTO clientes (
                  id, nombre, tipo_persona, nif, telefono, email,
                  procedencia_canal, procedencia_detalle, procedencia_user_id,
                  estado, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
                """,
            (
                cliente_id,
                lookup,
                "Física",
                nif or None,
                str(cliente_telefono or "").strip() or None,
                str(cliente_email or "").strip() or None,
                "",
                "",
                None,
                "Lead",
                now,
                now,
            ),
        )
        row = conn.execute(
            "SELECT id, nombre, COALESCE(nif, '') AS nif, COALESCE(telefono, '') AS telefono, COALESCE(email, '') AS email FROM clientes WHERE id = ? LIMIT 1",
            (cliente_id,),
        ).fetchone()
    if row:
        updates = []
        values = []
        if nif and not str(row["nif"] or "").strip():
            updates.append("nif = ?")
            values.append(nif)
        if str(cliente_telefono or "").strip() and not str(row["telefono"] or "").strip():
            updates.append("telefono = ?")
            values.append(str(cliente_telefono or "").strip())
        if str(cliente_email or "").strip() and not str(row["email"] or "").strip():
            updates.append("email = ?")
            values.append(str(cliente_email or "").strip())
        if updates:
            values.extend([now, row["id"]])
            conn.execute(
                f"UPDATE clientes SET {', '.join(updates)}, updated_at = datetime(?) WHERE id = ?",
                values,
            )
        servicio_label = workspace_budget_service_label(servicio)
        existing_link = conn.execute(
            """
            SELECT id FROM clientes_empresas
            WHERE cliente_id = ? AND empresa_id = ? AND LOWER(servicio) = LOWER(?)
            LIMIT 1
            """,
            (row["id"], empresa_id, servicio_label),
        ).fetchone()
        if existing_link:
            conn.execute(
                """
                UPDATE clientes_empresas
                SET estado = COALESCE(?, estado), fecha_inicio = COALESCE(?, fecha_inicio), updated_at = datetime(?)
                WHERE id = ?
                """,
                ("Presupuesto", fecha_inicio or None, now, existing_link["id"]),
            )
        else:
            conn.execute(
                """
                INSERT INTO clientes_empresas (
                  id, cliente_id, empresa_id, servicio, estado, fecha_inicio, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
                """,
                (
                    os.urandom(16).hex(),
                    row["id"],
                    empresa_id,
                    servicio_label,
                    "Presupuesto",
                    fecha_inicio or None,
                    now,
                    now,
                ),
            )
        return row["id"], row["nombre"]
    return None, lookup


def parse_workspace_presupuesto_lineas(raw):
    if raw in (None, ""):
        return []
    parsed = raw
    if isinstance(raw, str):
        try:
            parsed = json.loads(raw)
        except Exception:
            parsed = []
    if not isinstance(parsed, list):
        return []
    lineas = []
    for index, item in enumerate(parsed, start=1):
        if not isinstance(item, dict):
            continue
        concepto = str(item.get("concepto") or "").strip()
        if not concepto:
            continue
        cantidad = float(item.get("cantidad") or 0) or 0.0
        precio_unitario = float(item.get("precio_unitario") or 0) or 0.0
        descuento_pct = float(item.get("descuento_pct") or 0) or 0.0
        bruto = max(cantidad, 0.0) * max(precio_unitario, 0.0)
        total_linea = round(bruto * (1 - max(min(descuento_pct, 100.0), 0.0) / 100.0), 2)
        lineas.append(
            {
                "orden": index,
                "categoria": str(item.get("categoria") or "").strip() or None,
                "concepto": concepto,
                "cantidad": round(max(cantidad, 0.0), 2),
                "unidad": str(item.get("unidad") or "").strip() or None,
                "precio_unitario": round(max(precio_unitario, 0.0), 2),
                "descuento_pct": round(max(min(descuento_pct, 100.0), 0.0), 2),
                "total_linea": total_linea,
            }
        )
    return lineas


def fetch_workspace_presupuestos(conn, workspace_id, limit=40):
    rows = conn.execute(
        """
        SELECT
          p.id,
          p.workspace_id,
          p.empresa_id,
          p.cliente_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(c.telefono, '') AS cliente_telefono,
          COALESCE(c.email, '') AS cliente_email,
          p.servicio,
          p.referencia_tipo,
          p.referencia_id,
          p.titulo,
          p.estado,
          p.fecha,
          p.fecha_seguimiento,
          p.motivo_estado,
          p.responsable,
          p.forma_pago,
          COALESCE(p.encargo_estado, '') AS encargo_estado,
          p.fecha_encargo,
          p.observaciones,
          p.subtotal,
          p.impuestos,
          p.total,
          p.calculo_json,
          p.seguimiento_accion_id,
          p.encargo_accion_id,
          p.created_at,
          p.updated_at,
          (
            SELECT COUNT(*)
            FROM workspace_presupuesto_lineas l
            WHERE l.presupuesto_id = p.id
          ) AS lineas_total
        FROM workspace_presupuestos p
        LEFT JOIN empresas e ON e.id = p.empresa_id
        LEFT JOIN clientes c ON c.id = p.cliente_id
        WHERE p.workspace_id = ?
        ORDER BY COALESCE(p.fecha, p.updated_at, p.created_at) DESC, p.updated_at DESC
        LIMIT ?
        """,
        (workspace_id, max(1, min(int(limit or 40), 100))),
    ).fetchall()
    items = [dict(row) for row in rows]
    if not items:
        return {"rows": []}
    ids = [item["id"] for item in items if item.get("id")]
    placeholders = ",".join(["?"] * len(ids))
    line_rows = conn.execute(
        f"""
        SELECT presupuesto_id, orden, categoria, concepto, cantidad, unidad, precio_unitario, descuento_pct, total_linea
        FROM workspace_presupuesto_lineas
        WHERE presupuesto_id IN ({placeholders})
        ORDER BY presupuesto_id, orden ASC, created_at ASC
        """,
        ids,
    ).fetchall()
    grouped = {}
    for row in line_rows:
        grouped.setdefault(row["presupuesto_id"], []).append(dict(row))
    for item in items:
        item["lineas"] = grouped.get(item["id"], [])
    return {"rows": items}


def fetch_empresa_presupuestos(conn, empresa_id, servicio=None, estado=None, limit=120):
    empresa_id = str(empresa_id or "").strip()
    if not empresa_id:
        return {"rows": []}
    servicio_key = normalize_service_key(servicio or "")
    estado_key = normalize_lookup_text(estado or "").lower().strip()
    where = ["p.empresa_id = ?"]
    params = [empresa_id]
    if servicio_key and servicio_key not in {"all", "*"}:
        if servicio_key == "fincas":
            where.append("LOWER(COALESCE(p.servicio, '')) IN ('fincas', 'administracion fincas', 'administracion de fincas')")
        elif servicio_key == "gestoria":
            where.append("LOWER(COALESCE(p.servicio, '')) IN ('gestoria', 'gestoría')")
        else:
            where.append("LOWER(COALESCE(p.servicio, '')) = ?")
            params.append(servicio_key)
    if estado_key and estado_key not in {"all", "*"}:
        where.append("LOWER(COALESCE(p.estado, '')) = ?")
        params.append(estado_key)
    rows = conn.execute(
        f"""
        SELECT
          p.id,
          p.workspace_id,
          p.empresa_id,
          p.cliente_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(c.nombre, '') AS cliente_nombre,
          p.servicio,
          p.titulo,
          p.estado,
          p.fecha,
          p.fecha_seguimiento,
          p.encargo_estado,
          p.fecha_encargo,
          p.total,
          p.created_at,
          p.updated_at,
          (
            SELECT COUNT(*)
            FROM workspace_presupuesto_lineas l
            WHERE l.presupuesto_id = p.id
          ) AS lineas_total
        FROM workspace_presupuestos p
        LEFT JOIN empresas e ON e.id = p.empresa_id
        LEFT JOIN clientes c ON c.id = p.cliente_id
        WHERE {" AND ".join(where)}
        ORDER BY COALESCE(p.fecha, p.updated_at, p.created_at) DESC, p.updated_at DESC
        LIMIT ?
        """,
        (*params, max(1, min(int(limit or 120), 300))),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def fetch_workspace_contratos(conn, workspace_id, empresa_id=None, limit=50):
    empresa_id = str(empresa_id or "").strip()
    where = ["ct.workspace_id = ?"]
    params = [workspace_id]
    if empresa_id:
        where.append("ct.empresa_id = ?")
        params.append(empresa_id)
    rows = conn.execute(
        f"""
        SELECT
          ct.id,
          ct.workspace_id,
          ct.empresa_id,
          ct.cliente_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(c.telefono, '') AS cliente_telefono,
          COALESCE(c.email, '') AS cliente_email,
          ct.servicio,
          ct.template_key,
          ct.titulo,
          ct.estado,
          ct.fecha,
          COALESCE(ct.body_json, '') AS body_json,
          COALESCE(ct.doc_url, '') AS doc_url,
          COALESCE(ct.doc_key, '') AS doc_key,
          COALESCE(ct.notas, '') AS notas,
          ct.created_at,
          ct.updated_at
        FROM workspace_contratos ct
        LEFT JOIN empresas e ON e.id = ct.empresa_id
        LEFT JOIN clientes c ON c.id = ct.cliente_id
        WHERE {" AND ".join(where)}
        ORDER BY COALESCE(ct.fecha, ct.updated_at, ct.created_at) DESC, ct.updated_at DESC
        LIMIT ?
        """,
        (*params, max(1, min(int(limit or 50), 200))),
    ).fetchall()
    items = [dict(row) for row in rows]
    for item in items:
        body_json = str(item.get("body_json") or "").strip()
        body = {}
        if body_json:
            try:
                body = json.loads(body_json)
                if not isinstance(body, dict):
                    body = {}
            except Exception:
                body = {}
        item["clausulas_extra"] = str(body.get("clausulas_extra") or "").strip()
        item["body_text"] = str(body.get("body_text") or "").strip()
        item.pop("body_json", None)
    return {"rows": items}


