def parse_workspace_automation_config(raw):
    if raw in (None, ""):
        return {}
    if isinstance(raw, dict):
        return raw
    try:
        value = json.loads(str(raw))
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _normalize_to_list(value):
    if value in (None, "", []):
        return []
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    return [item.strip() for item in str(value).split(",") if item.strip()]


def workspace_automation_matches(config, context):
    conditions = config.get("conditions") if isinstance(config.get("conditions"), dict) else {}
    servicios = {normalize_service_key(item) for item in _normalize_to_list(conditions.get("servicios"))}
    servicio = normalize_service_key(context.get("servicio") or "")
    if servicios and servicio not in servicios:
        return False, "servicio fuera de condición"
    metodos = {item.lower() for item in _normalize_to_list(conditions.get("metodos"))}
    metodo = str(context.get("metodo") or "").strip().lower()
    if metodos and metodo not in metodos:
        return False, "método fuera de condición"
    estados = {item.lower() for item in _normalize_to_list(conditions.get("estados"))}
    estado = str(context.get("estado") or "").strip().lower()
    if estados and estado not in estados:
        return False, "estado fuera de condición"
    required_keys = _normalize_to_list(conditions.get("required_keys"))
    for key in required_keys:
        if not context.get(key):
            return False, f"falta {key}"
    min_importe = conditions.get("min_importe")
    if min_importe not in (None, ""):
        if float(context.get("importe") or context.get("total") or 0.0) < float(min_importe):
            return False, "importe por debajo del mínimo"
    return True, ""


def apply_workspace_automation_effects(conn, workspace_id, automation_row, config, context, now):
    actions = config.get("actions") if isinstance(config.get("actions"), dict) else {}
    if not actions and any(key in config for key in ("inbox_estado", "portal_request", "create_action")):
        actions = dict(config)
    effect_count = 0
    if actions.get("create_action", True):
        empresa_id = context.get("empresa_id") or fetch_workspace_company_ids(conn, workspace_id)[:1]
        empresa_id = empresa_id[0] if isinstance(empresa_id, list) else empresa_id
        if empresa_id:
            detalle = (automation_row["action_summary"] or "").strip() or f"Automatización {automation_row['nombre']}"
            conn.execute(
                """
                INSERT INTO acciones (
                  id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
                  fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
                ) VALUES (
                  ?, ?, ?, ?, ?, ?, date(?), time(?), ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    empresa_id,
                    (automation_row["modulo_key"] or context.get("servicio") or "gestoria").strip(),
                    context.get("cliente_id"),
                    context.get("inmueble_id"),
                    context.get("cliente_nombre"),
                    now,
                    now,
                    automation_row["nombre"],
                    actions.get("responsable") or context.get("responsable"),
                    actions.get("action_estado") or "Pendiente",
                    detalle,
                    int(actions.get("recordatorio_min") or 60),
                    now,
                    now,
                ),
            )
            effect_count += 1
    inbox_estado = (actions.get("inbox_estado") or "").strip()
    if inbox_estado and context.get("document_id"):
        conn.execute(
            "UPDATE workspace_documentos_inbox SET estado = ?, updated_at = datetime(?) WHERE id = ? AND workspace_id = ?",
            (inbox_estado, now, context.get("document_id"), workspace_id),
        )
        effect_count += 1
    portal_request = actions.get("portal_request")
    if isinstance(portal_request, dict) and context.get("portal_cliente_id"):
        due_days = int(portal_request.get("days_due") or 0)
        due_date = None
        if due_days > 0:
            try:
                due_date = (datetime.fromisoformat(str(now).replace("Z", "")) + timedelta(days=due_days)).date().isoformat()
            except Exception:
                due_date = None
        conn.execute(
            """
            INSERT INTO workspace_portal_requerimientos (
              id, workspace_id, portal_cliente_id, cliente_id, servicio, titulo, descripcion,
              prioridad, estado, fecha_limite, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
            """,
            (
                os.urandom(16).hex(),
                workspace_id,
                context.get("portal_cliente_id"),
                context.get("cliente_id"),
                (portal_request.get("servicio") or context.get("servicio") or "").strip() or None,
                (portal_request.get("titulo") or automation_row["nombre"]).strip(),
                (portal_request.get("descripcion") or automation_row["action_summary"] or "").strip() or None,
                (portal_request.get("prioridad") or "Normal").strip(),
                (portal_request.get("estado") or "Pendiente").strip(),
                due_date or (portal_request.get("fecha_limite") or None),
                now,
                now,
            ),
        )
        effect_count += 1
    return effect_count


def run_workspace_automations(conn, workspace_id, trigger_key, context, now):
    rows = conn.execute(
        """
        SELECT id, nombre, trigger_key, modulo_key, enabled, action_summary, config_json
        FROM workspace_automatizaciones
        WHERE workspace_id = ? AND trigger_key = ? AND COALESCE(enabled, 1) = 1
        ORDER BY updated_at DESC, created_at DESC
        """,
        (workspace_id, trigger_key),
    ).fetchall()
    created = 0
    for row in rows:
        config = parse_workspace_automation_config(row["config_json"])
        matches, reason = workspace_automation_matches(config, context)
        detalle = (row["action_summary"] or "").strip() or f"Automatización {row['nombre']}"
        if matches:
            created += apply_workspace_automation_effects(conn, workspace_id, row, config, context, now)
        conn.execute(
            """
            INSERT INTO workspace_automatizacion_logs (
              id, workspace_id, automatizacion_id, trigger_key, estado, detalle, payload_json, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime(?))
            """,
            (
                os.urandom(16).hex(),
                workspace_id,
                row["id"],
                trigger_key,
                "ejecutada" if matches else "omitida",
                detalle if matches else f"{detalle} · {reason}",
                json.dumps(context, ensure_ascii=False),
                now,
            ),
        )
    return created


def fetch_workspace_portal_public(conn, token):
    row = conn.execute(
        """
        SELECT
          p.workspace_id,
          p.cliente_id,
          p.estado,
          COALESCE(p.importador_facturas, 0) AS importador_facturas,
          p.ultimo_acceso_at,
          c.nombre AS cliente_nombre,
          COALESCE(c.email, '') AS email,
          w.nombre AS workspace_nombre
        FROM workspace_portal_clientes p
        JOIN clientes c ON c.id = p.cliente_id
        JOIN workspaces w ON w.id = p.workspace_id
        WHERE p.token = ?
        LIMIT 1
        """,
        (token,),
    ).fetchone()
    if not row:
        return None
    conn.execute(
        "UPDATE workspace_portal_clientes SET ultimo_acceso_at = datetime(?) WHERE token = ?",
        (datetime.now(timezone.utc).isoformat(), token),
    )
    conn.commit()
    docs = conn.execute(
        """
        SELECT nombre, clasificacion, estado, created_at
        FROM workspace_documentos_inbox
        WHERE workspace_id = ? AND COALESCE(cliente_id, suggested_cliente_id) = ?
        ORDER BY updated_at DESC, created_at DESC
        LIMIT 10
        """,
        (row["workspace_id"], row["cliente_id"]),
    ).fetchall()
    bills = conn.execute(
        """
        SELECT id, concepto, fecha_emision, total, estado, cobrada
        FROM workspace_facturacion
        WHERE workspace_id = ? AND cliente_id = ?
        ORDER BY COALESCE(fecha_emision, created_at) DESC
        LIMIT 10
        """,
        (row["workspace_id"], row["cliente_id"]),
    ).fetchall()
    requests = conn.execute(
        """
        SELECT id, titulo, descripcion, clasificacion, prioridad, estado, fecha_limite, completed_at
        FROM workspace_portal_requerimientos
        WHERE workspace_id = ? AND cliente_id = ?
        ORDER BY
          CASE COALESCE(estado, 'Pendiente')
            WHEN 'Pendiente' THEN 0
            WHEN 'Enviado' THEN 1
            WHEN 'Recibido' THEN 2
            WHEN 'Completado' THEN 3
            ELSE 9
          END,
          COALESCE(fecha_limite, created_at) ASC
        LIMIT 12
        """,
        (row["workspace_id"], row["cliente_id"]),
    ).fetchall()
    empresa_ids = fetch_workspace_company_ids(conn, row["workspace_id"])
    facturas_recibidas = []
    seguros_polizas = []
    seguros_recibos = []
    seguros_siniestros = []
    seguros_renovaciones = []
    if empresa_ids:
        placeholders = ",".join(["?"] * len(empresa_ids))
        if int(row["importador_facturas"] or 0) == 1:
            try:
                facturas_recibidas = conn.execute(
                    f"""
                    SELECT
                      f.id,
                      f.fecha_emision,
                      f.numero,
                      f.tipo,
                      f.total,
                      COALESCE(f.estado_ocr, '') AS estado_ocr,
                      COALESCE(f.doc_key, '') AS doc_key,
                      COALESCE(t.nombre, f.descripcion, '') AS tercero
                    FROM gestoria_facturas f
                    LEFT JOIN gestoria_terceros t ON t.id = f.tercero_id
                    WHERE f.cliente_id = ?
                      AND f.empresa_id IN ({placeholders})
                    ORDER BY COALESCE(NULLIF(TRIM(COALESCE(f.fecha_emision,'')),''), f.updated_at, f.created_at) DESC
                    LIMIT 30
                    """,
                    [row["cliente_id"], *empresa_ids],
                ).fetchall()
            except Exception:
                facturas_recibidas = []
        try:
            seguros_polizas = conn.execute(
                f"""
                SELECT id, empresa_id, compania, ramo, poliza_numero, fecha_efecto, fecha_vencimiento, estado,
                       poliza_key, poliza_url
                FROM seguros
                WHERE cliente_id = ?
                  AND empresa_id IN ({placeholders})
                ORDER BY COALESCE(NULLIF(TRIM(COALESCE(fecha_vencimiento,'')),''), NULLIF(TRIM(COALESCE(fecha_efecto,'')),''), updated_at, created_at) DESC
                LIMIT 20
                """,
                [row["cliente_id"], *empresa_ids],
            ).fetchall()
        except Exception:
            seguros_polizas = []
        try:
            seguros_recibos = conn.execute(
                f"""
                SELECT id, seguro_id, referencia, poliza_numero, compania, ramo,
                       fecha_emision, fecha_vencimiento, fecha_cobro, estado, prima_total,
                       doc_key, doc_url
                FROM seguros_recibos
                WHERE cliente_id = ?
                  AND empresa_id IN ({placeholders})
                ORDER BY COALESCE(NULLIF(TRIM(COALESCE(fecha_vencimiento,'')),''), NULLIF(TRIM(COALESCE(fecha_emision,'')),''), updated_at, created_at) DESC
                LIMIT 12
                """,
                [row["cliente_id"], *empresa_ids],
            ).fetchall()
        except Exception:
            seguros_recibos = []
        try:
            seguros_siniestros = conn.execute(
                f"""
                SELECT id, seguro_id, numero_expediente, compania, ramo,
                       fecha_siniestro, fecha_apertura, fecha_cierre, estado, tipo, descripcion
                FROM seguros_siniestros
                WHERE cliente_id = ?
                  AND empresa_id IN ({placeholders})
                ORDER BY COALESCE(NULLIF(TRIM(COALESCE(fecha_apertura,'')),''), created_at) DESC
                LIMIT 12
                """,
                [row["cliente_id"], *empresa_ids],
            ).fetchall()
        except Exception:
            seguros_siniestros = []
        try:
            seguros_renovaciones = conn.execute(
                f"""
                SELECT
                  r.id,
                  r.estado,
                  r.fecha_vencimiento,
                  r.proxima_accion_fecha,
                  r.ultimo_contacto_fecha,
                  r.notas,
                  COALESCE(s.id, '') AS seguro_id,
                  COALESCE(s.poliza_numero, r.poliza_key) AS poliza_numero,
                  COALESCE(s.compania, '') AS compania,
                  COALESCE(s.ramo, '') AS ramo
                FROM seguros_renovaciones r
                LEFT JOIN seguros s
                  ON (s.id = r.poliza_id OR (r.poliza_id IS NULL AND TRIM(COALESCE(r.poliza_key,'')) != '' AND s.poliza_key = r.poliza_key))
                WHERE r.empresa_id IN ({placeholders})
                  AND s.cliente_id = ?
                ORDER BY COALESCE(NULLIF(TRIM(COALESCE(r.fecha_vencimiento,'')),''), r.updated_at, r.created_at) DESC
                LIMIT 12
                """,
                [*empresa_ids, row["cliente_id"]],
            ).fetchall()
        except Exception:
            seguros_renovaciones = []
    return {
        "workspace": row["workspace_nombre"],
        "cliente": row["cliente_nombre"],
        "estado": row["estado"],
        "importador_facturas": int(row["importador_facturas"] or 0),
        "email": row["email"],
        "docs": [dict(item) for item in docs],
        "facturas": [dict(item) for item in bills],
        "facturas_recibidas": [dict(item) for item in facturas_recibidas],
        "requerimientos": [dict(item) for item in requests],
        "seguros_polizas": [dict(item) for item in seguros_polizas],
        "seguros_recibos": [dict(item) for item in seguros_recibos],
        "seguros_siniestros": [dict(item) for item in seguros_siniestros],
        "seguros_renovaciones": [dict(item) for item in seguros_renovaciones],
    }


def build_gestoria_facturas_excel(template_path: Path, facturas_rows):
    import io
    import openpyxl

    wb = openpyxl.load_workbook(template_path)
    ws = wb.active
    start_row = 2

    rows = list(facturas_rows or [])
    for idx, row in enumerate(rows):
        r = start_row + idx
        fecha_asiento = (row.get("fecha_asiento") or row.get("fecha_emision") or "") or ""
        fecha_factura = (row.get("fecha_emision") or "") or ""
        numero = (row.get("numero") or "") or ""
        tercero_nif = (row.get("tercero_nif") or "") or ""
        tercero_nombre = (row.get("tercero_nombre") or row.get("tercero") or "") or ""
        base = row.get("base_imponible") or 0.0
        iva_pct = row.get("iva_pct") or 0.0
        cuota_iva = row.get("cuota_iva") or 0.0
        total = row.get("total") or 0.0
        subcuenta = (row.get("subcuenta") or "") or ""
        subcuenta_gi = (row.get("subcuenta_gastos_ingresos") or "") or ""

        ws.cell(r, 1).value = str(fecha_asiento)
        ws.cell(r, 2).value = str(fecha_factura)
        ws.cell(r, 3).value = str(numero)
        ws.cell(r, 4).value = f"=CONCATENATE(C{r},\" \",G{r})"
        ws.cell(r, 5).value = str(subcuenta)
        ws.cell(r, 6).value = str(tercero_nif)
        ws.cell(r, 7).value = str(tercero_nombre)
        ws.cell(r, 8).value = str(row.get("domicilio") or "")
        ws.cell(r, 9).value = str(row.get("localidad") or "")
        ws.cell(r, 10).value = str(row.get("provincia") or "")
        ws.cell(r, 11).value = str(row.get("codigo_postal") or "")
        ws.cell(r, 12).value = float(base) if base not in (None, "") else 0.0
        ws.cell(r, 13).value = float(iva_pct) if iva_pct not in (None, "") else 0.0
        ws.cell(r, 14).value = float(cuota_iva) if cuota_iva not in (None, "") else 0.0
        ws.cell(r, 15).value = str(subcuenta_gi)
        ws.cell(r, 16).value = float(total) if total not in (None, "") else 0.0

    buff = io.BytesIO()
    wb.save(buff)
    return buff.getvalue()


def fetch_workspace_invoice_pdf_payload(conn, invoice_id, workspace_id=None, token=None):
    portal_scope = None
    if token:
        portal_scope = conn.execute(
            """
            SELECT workspace_id, cliente_id
            FROM workspace_portal_clientes
            WHERE token = ?
            LIMIT 1
            """,
            (token,),
        ).fetchone()
        if not portal_scope:
            return None
        workspace_id = portal_scope["workspace_id"]
    if not invoice_id or not workspace_id:
        return None
    invoice = conn.execute(
        """
        SELECT
          wf.*,
          COALESCE(w.nombre, '') AS workspace_nombre,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(e.logo_url, '') AS empresa_logo_url,
          COALESCE(e.razon_social, '') AS empresa_razon_social,
          COALESCE(e.nif, '') AS empresa_nif,
          COALESCE(e.direccion, '') AS empresa_direccion,
          COALESCE(e.direccion_fiscal, '') AS empresa_direccion_fiscal,
          COALESCE(e.telefono, '') AS empresa_telefono,
          COALESCE(e.email, '') AS empresa_email,
          COALESCE(e.web, '') AS empresa_web,
          COALESCE(e.iban, '') AS empresa_iban,
          COALESCE(e.bic, '') AS empresa_bic,
          COALESCE(e.banco_nombre, '') AS empresa_banco_nombre,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(c.email, '') AS cliente_email,
          COALESCE(c.telefono, '') AS cliente_telefono
        FROM workspace_facturacion wf
        LEFT JOIN workspaces w ON w.id = wf.workspace_id
        LEFT JOIN empresas e ON e.id = wf.empresa_id
        LEFT JOIN clientes c ON c.id = wf.cliente_id
        WHERE wf.id = ? AND wf.workspace_id = ?
        LIMIT 1
        """,
        (invoice_id, workspace_id),
    ).fetchone()
    if not invoice:
        return None
    if portal_scope and str(invoice["cliente_id"] or "") != str(portal_scope["cliente_id"] or ""):
        return None
    collections = conn.execute(
        """
        SELECT fecha_cobro, metodo, importe, referencia
        FROM workspace_facturacion_cobros
        WHERE factura_id = ?
        ORDER BY COALESCE(fecha_cobro, created_at) ASC
        """,
        (invoice_id,),
    ).fetchall()
    return {
        "invoice": dict(invoice),
        "workspace": {"nombre": invoice["workspace_nombre"]},
        "company": {
            "nombre": invoice["empresa_nombre"],
            "logo_url": invoice["empresa_logo_url"],
            "razon_social": invoice["empresa_razon_social"],
            "nif": invoice["empresa_nif"],
            "direccion": invoice["empresa_direccion"],
            "direccion_fiscal": invoice["empresa_direccion_fiscal"],
            "telefono": invoice["empresa_telefono"],
            "email": invoice["empresa_email"],
            "web": invoice["empresa_web"],
            "iban": invoice["empresa_iban"],
            "bic": invoice["empresa_bic"],
            "banco_nombre": invoice["empresa_banco_nombre"],
        },
        "client": {
            "nombre": invoice["cliente_nombre"],
            "nif": invoice["cliente_nif"],
            "email": invoice["cliente_email"],
            "telefono": invoice["cliente_telefono"],
        },
        "collections": [dict(row) for row in collections],
    }


def fetch_workspace_budget_pdf_payload(conn, budget_id, workspace_id=None):
    if not budget_id or not workspace_id:
        return None
    budget = conn.execute(
        """
        SELECT
          p.*,
          COALESCE(w.nombre, '') AS workspace_nombre,
          COALESCE(w.primary_color, '') AS workspace_primary_color,
          COALESCE(w.accent_color, '') AS workspace_accent_color,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(e.logo_url, '') AS empresa_logo_url,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(c.email, '') AS cliente_email,
          COALESCE(c.telefono, '') AS cliente_telefono
        FROM workspace_presupuestos p
        LEFT JOIN workspaces w ON w.id = p.workspace_id
        LEFT JOIN empresas e ON e.id = p.empresa_id
        LEFT JOIN clientes c ON c.id = p.cliente_id
        WHERE p.id = ? AND p.workspace_id = ?
        LIMIT 1
        """,
        (budget_id, workspace_id),
    ).fetchone()
    if not budget:
        return None
    lineas = conn.execute(
        """
        SELECT orden, categoria, concepto, cantidad, unidad, precio_unitario, descuento_pct, total_linea
        FROM workspace_presupuesto_lineas
        WHERE presupuesto_id = ?
        ORDER BY orden ASC, created_at ASC
        """,
        (budget_id,),
    ).fetchall()
    return {
        "budget": dict(budget),
        "workspace": {
            "nombre": budget["workspace_nombre"],
            "primary_color": budget["workspace_primary_color"],
            "accent_color": budget["workspace_accent_color"],
        },
        "company": {"nombre": budget["empresa_nombre"], "logo_url": budget["empresa_logo_url"]},
        "client": {
            "nombre": budget["cliente_nombre"],
            "nif": budget["cliente_nif"],
            "email": budget["cliente_email"],
            "telefono": budget["cliente_telefono"],
        },
        "lineas": [dict(row) for row in lineas],
    }


def fetch_workspace_presupuesto_share(conn, token):
    token = str(token or "").strip()
    if not token:
        return None
    try:
        row = conn.execute(
            """
            SELECT token, workspace_id, presupuesto_id, expires_at, last_access_at, created_at, updated_at
            FROM workspace_presupuesto_shares
            WHERE token = ?
            LIMIT 1
            """,
            (token,),
        ).fetchone()
    except Exception:
        return None
    return dict(row) if row else None


def fetch_workspace_budget_encargo_payload(conn, budget_id, workspace_id=None):
    return fetch_workspace_budget_pdf_payload(conn, budget_id, workspace_id=workspace_id)


def fetch_workspace_detail(conn, workspace_id):
    workspace = conn.execute(
        """
        SELECT id, nombre, slug, estado, plan, kind, descripcion, logo_url, primary_color, accent_color
        FROM workspaces
        WHERE id = ?
        LIMIT 1
        """,
        (workspace_id,),
    ).fetchone()
    if not workspace:
        return None
    # Enforce membership for non-admin users when enabled.
    # (Admins can see all workspaces.)
    # Note: some public endpoints call fetch_workspace_detail without a session; enforcement is handled in request layer.
    # Backfill: si el workspace aún no tiene empresas linkadas (p. ej. tras migraciones),
    # las asociamos automáticamente para que RRHH y formularios tengan el desplegable de empresa.
    try:
        fetch_workspace_company_ids(conn, workspace_id)
    except Exception:
        pass
    companies = conn.execute(
        """
        SELECT
          e.id,
          e.nombre,
          COALESCE(e.razon_social, '') AS razon_social,
          COALESCE(e.nif, '') AS nif,
          COALESCE(e.direccion, '') AS direccion,
          COALESCE(e.direccion_fiscal, '') AS direccion_fiscal,
          COALESCE(e.telefono, '') AS telefono,
          COALESCE(e.email, '') AS email,
          COALESCE(e.web, '') AS web,
          COALESCE(e.contacto_nombre, '') AS contacto_nombre,
          COALESCE(e.contacto_email, '') AS contacto_email,
          COALESCE(e.contacto_telefono, '') AS contacto_telefono,
          COALESCE(e.iban, '') AS iban,
          COALESCE(e.bic, '') AS bic,
          COALESCE(e.banco_nombre, '') AS banco_nombre,
          COALESCE(e.sector, '') AS sector,
          COALESCE(e.cnae, '') AS cnae,
          COALESCE(e.cnaes_json, '') AS cnaes_json,
          COALESCE(e.convenio_key, '') AS convenio_key,
          COALESCE(e.convenio_nombre, '') AS convenio_nombre,
          COALESCE(e.vacaciones_modo, '') AS vacaciones_modo,
          COALESCE(CAST(e.vacaciones_dias_anuales AS TEXT), '') AS vacaciones_dias_anuales,
          COALESCE(e.logo_url, '') AS logo_url,
          COALESCE(we.rol, '') AS rol,
          COALESCE(e.activo, 1) AS activo
        FROM workspace_empresas we
        JOIN empresas e ON e.id = we.empresa_id
        WHERE we.workspace_id = ?
        ORDER BY e.nombre COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    # v2 (tenant-native): empresas dentro del workspace (evita depender de `empresas` global).
    # Si aún no hay filas, hacemos backfill best-effort desde workspace_empresas para no romper pantallas.
    try:
        ensure_workspace_core_tables(conn)
    except Exception:
        pass
    try:
        existing = conn.execute(
            "SELECT COUNT(*) AS total FROM workspace_companies WHERE workspace_id = ?",
            (workspace_id,),
        ).fetchone()
        total_existing = int(row_value(existing, "total", 0) or row_value(existing, 0) or 0)
    except Exception:
        total_existing = 0
    if total_existing == 0:
        try:
            # Backfill desde joins legacy. No borra/edita nada si ya existe.
            now_ts = datetime.now(timezone.utc).isoformat()
            legacy = conn.execute(
                """
                SELECT we.empresa_id, we.rol, e.nombre, e.nif, e.direccion, e.logo_url, e.primary_color, e.accent_color, COALESCE(e.activo, 1) AS activo
                FROM workspace_empresas we
                JOIN empresas e ON e.id = we.empresa_id
                WHERE we.workspace_id = ?
                """,
                (workspace_id,),
            ).fetchall()
            for row in legacy or []:
                legacy_id = str(row_value(row, "empresa_id") or "").strip()
                if not legacy_id:
                    continue
                if conn.execute(
                    "SELECT 1 FROM workspace_companies WHERE workspace_id = ? AND legacy_empresa_id = ? LIMIT 1",
                    (workspace_id, legacy_id),
                ).fetchone():
                    continue
                conn.execute(
                    """
                    INSERT INTO workspace_companies (
                      id, workspace_id, legacy_empresa_id, nombre, nif, direccion,
                      logo_url, primary_color, accent_color, activo, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        uuid.uuid4().hex,
                        workspace_id,
                        legacy_id,
                        str(row_value(row, "nombre") or "").strip() or "-",
                        str(row_value(row, "nif") or "").strip(),
                        str(row_value(row, "direccion") or "").strip(),
                        str(row_value(row, "logo_url") or "").strip(),
                        str(row_value(row, "primary_color") or "").strip(),
                        str(row_value(row, "accent_color") or "").strip(),
                        int(row_value(row, "activo") or 1),
                        now_ts,
                        now_ts,
                    ),
                )
            try:
                conn.commit()
            except Exception:
                pass
        except Exception:
            pass
    try:
        companies_v2 = conn.execute(
            """
            SELECT
              id,
              workspace_id,
              COALESCE(legacy_empresa_id, '') AS legacy_empresa_id,
              nombre,
              COALESCE(nif, '') AS nif,
              COALESCE(direccion, '') AS direccion,
              COALESCE(logo_url, '') AS logo_url,
              COALESCE(primary_color, '') AS primary_color,
              COALESCE(accent_color, '') AS accent_color,
              COALESCE(activo, 1) AS activo
            FROM workspace_companies
            WHERE workspace_id = ?
            ORDER BY nombre COLLATE NOCASE ASC
            """,
            (workspace_id,),
        ).fetchall()
    except Exception:
        companies_v2 = []
    modules = conn.execute(
        """
        SELECT id, modulo_key, modulo_nombre, categoria, enabled, sort_order, config_json
        FROM workspace_modulos
        WHERE workspace_id = ?
        ORDER BY sort_order ASC, modulo_nombre COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    module_rows = [dict(row) for row in modules]
    enabled_keys = [row["modulo_key"] for row in module_rows if int(row.get("enabled") or 0) == 1]
    plan_name = str(workspace["plan"] or "Enterprise")
    package = dict(WORKSPACE_PLAN_PACKAGES.get(plan_name, WORKSPACE_PLAN_PACKAGES["Enterprise"]))
    package["enabled_focus_total"] = sum(1 for key in package.get("focus", []) if key in enabled_keys)
    package["enabled_modules_total"] = len(enabled_keys)
    permission_matrix = []
    profiles = [
        ("Dirección", {"crm360", "dashboard", "documental", "gestoria", "seguros", "inmobiliaria", "financiacion", "fincas", "facturacion", "facturas_recibidas", "portal_cliente", "registro_horario", "rrhh", "automatizaciones"}),
        ("Operaciones", {"crm360", "dashboard", "documental", "gestoria", "facturacion", "facturas_recibidas", "portal_cliente", "registro_horario", "rrhh"}),
        ("Comercial", {"crm360", "dashboard", "documental", "seguros", "inmobiliaria", "financiacion", "portal_cliente"}),
        ("Backoffice", {"crm360", "documental", "gestoria", "facturacion", "facturas_recibidas", "fincas", "registro_horario", "rrhh"}),
        ("RRHH", {"crm360", "documental", "registro_horario", "rrhh"}),
    ]
    for role_name, allowed_modules in profiles:
        granted = [row["modulo_nombre"] for row in module_rows if row["modulo_key"] in enabled_keys and row["modulo_key"] in allowed_modules]
        permission_matrix.append(
            {
                "perfil": role_name,
                "modules_total": len(granted),
                "modules": granted,
            }
        )
    return {
        "workspace": dict(workspace),
        "companies": [dict(row) for row in companies],
        "companies_v2": [dict(row) for row in companies_v2],
        "modules": module_rows,
        "commercial_package": package,
        "permission_matrix": permission_matrix,
    }


def ensure_workspace_default_company(conn, workspace_id, nombre=None):
    """
    DEPRECATED (service-first): la operativa ya no debe depender de empresas.
    Se mantiene como stub por compatibilidad con instalaciones antiguas, pero NO crea ni vincula nada.
    """
    return None


def get_platform_empresa_id(conn) -> str:
    """
    Service-first compat: algunas tablas legacy aún exigen `empresa_id NOT NULL`.
    Para que la operativa no dependa de empresas por workspace, usamos una única empresa técnica
    (Verifika2) como fallback interno.
    """
    try:
        # 1) cache en meta
        try:
            row = conn.execute("SELECT value FROM crm_meta WHERE key = ?", ("platform_empresa_id",)).fetchone()
            cached = ""
            if row:
                try:
                    cached = str(row.get("value") or "")
                except Exception:
                    cached = str(row[0] or "")
            cached = (cached or "").strip()
            if cached:
                exists = conn.execute("SELECT 1 FROM empresas WHERE id = ? LIMIT 1", (cached,)).fetchone()
                if exists:
                    return cached
        except Exception:
            _rollback_best_effort(conn)

        # 2) busca por nombre
        row2 = conn.execute(
            "SELECT id FROM empresas WHERE LOWER(TRIM(nombre)) IN ('verifika2', 'verifika²') ORDER BY created_at ASC LIMIT 1"
        ).fetchone()
        if row2:
            eid = str(row_value(row2, "id") or row_value(row2, 0) or "").strip()
            if eid:
                backend = getattr(conn, "__crm_backend__", "") or ""
                if backend == "postgres":
                    conn.execute(
                        """
                        INSERT INTO crm_meta (key, value, updated_at)
                        VALUES (%s, %s, NOW())
                        ON CONFLICT (key) DO UPDATE
                        SET value = EXCLUDED.value,
                            updated_at = EXCLUDED.updated_at
                        """,
                        ("platform_empresa_id", eid),
                    )
                else:
                    conn.execute(
                        "INSERT OR REPLACE INTO crm_meta (key, value, updated_at) VALUES (?, ?, datetime('now'))",
                        ("platform_empresa_id", eid),
                    )
                try:
                    conn.commit()
                except Exception:
                    _rollback_best_effort(conn)
                return eid

        # 3) crea
        eid = uuid.uuid4().hex
        now_ts = datetime.now(timezone.utc).isoformat()
        backend = getattr(conn, "__crm_backend__", "") or ""
        if backend == "postgres":
            conn.execute(
                """
                INSERT INTO empresas (id, nombre, activo, logo_url, nif, direccion, created_at, updated_at)
                VALUES (%s, 'Verifika2', 1, '', '', '', %s, %s)
                """,
                (eid, now_ts, now_ts),
            )
            conn.execute(
                """
                INSERT INTO crm_meta (key, value, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (key) DO UPDATE
                SET value = EXCLUDED.value,
                    updated_at = EXCLUDED.updated_at
                """,
                ("platform_empresa_id", eid),
            )
        else:
            conn.execute(
                """
                INSERT INTO empresas (id, nombre, activo, logo_url, nif, direccion, created_at, updated_at)
                VALUES (?, 'Verifika2', 1, '', '', '', datetime(?), datetime(?))
                """,
                (eid, now_ts, now_ts),
            )
            conn.execute(
                "INSERT OR REPLACE INTO crm_meta (key, value, updated_at) VALUES (?, ?, datetime('now'))",
                ("platform_empresa_id", eid),
            )
        try:
            conn.commit()
        except Exception:
            _rollback_best_effort(conn)
        return eid
    except Exception:
        _rollback_best_effort(conn)
        return ""


def fetch_workspace_billing_summary(conn, workspace_id):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {
            "facturas_emitidas": 0,
            "facturacion_total": 0.0,
            "cobrado_total": 0.0,
            "pendiente_total": 0.0,
            "potencial_operativo": 0.0,
            "cobros_registrados": 0,
            "remesas_total": 0.0,
            "servicios": [],
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    fact_rows = conn.execute(
        f"""
        SELECT
          COALESCE(servicio, 'sin_servicio') AS servicio,
          COUNT(*) AS total_facturas,
          SUM(COALESCE(total, 0)) AS total_facturado,
          SUM(CASE WHEN COALESCE(cobrada, 0) = 1 THEN COALESCE(total, 0) ELSE 0 END) AS total_cobrado
        FROM workspace_facturacion
        WHERE workspace_id = ?
          AND empresa_id IN ({placeholders})
        GROUP BY COALESCE(servicio, 'sin_servicio')
        ORDER BY total_facturado DESC
        """,
        [workspace_id, *empresa_ids],
    ).fetchall()
    facturas_emitidas = sum(int(row["total_facturas"] or 0) for row in fact_rows)
    facturacion_total = round(sum(float(row["total_facturado"] or 0.0) for row in fact_rows), 2)
    cobrado_total = round(sum(float(row["total_cobrado"] or 0.0) for row in fact_rows), 2)
    pendiente_total = round(max(facturacion_total - cobrado_total, 0.0), 2)

    potential_rows = []
    seguros = conn.execute(
        f"""
        SELECT 'seguros' AS servicio, SUM(COALESCE(comision, 0)) AS total
        FROM seguros
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if seguros and seguros["total"] is not None:
        potential_rows.append({"servicio": "seguros", "total": float(seguros["total"] or 0.0)})
    inmo = conn.execute(
        f"""
        SELECT 'inmobiliaria' AS servicio, SUM(COALESCE(honorarios, 0)) AS total
        FROM operaciones_inmobiliarias
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if inmo and inmo["total"] is not None:
        potential_rows.append({"servicio": "inmobiliaria", "total": float(inmo["total"] or 0.0)})
    fin = conn.execute(
        f"""
        SELECT 'financiacion' AS servicio, SUM(COALESCE(comision, 0)) AS total
        FROM hipotecas
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if fin and fin["total"] is not None:
        potential_rows.append({"servicio": "financiacion", "total": float(fin["total"] or 0.0)})
    gest = conn.execute(
        f"""
        SELECT 'gestoria' AS servicio, SUM(COALESCE(importe, 0)) AS total
        FROM gestoria_trabajos
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if gest and gest["total"] is not None:
        potential_rows.append({"servicio": "gestoria", "total": float(gest["total"] or 0.0)})
    potencial_operativo = round(sum(float(item["total"] or 0.0) for item in potential_rows), 2)
    cobros = conn.execute(
        """
        SELECT COUNT(*) AS total_cobros, SUM(CASE WHEN COALESCE(metodo, '') = 'Remesa' THEN COALESCE(importe, 0) ELSE 0 END) AS total_remesas
        FROM workspace_facturacion_cobros
        WHERE workspace_id = ?
        """,
        (workspace_id,),
    ).fetchone()
    services = [
        {
            "servicio": row["servicio"],
            "facturas": int(row["total_facturas"] or 0),
            "facturado": round(float(row["total_facturado"] or 0.0), 2),
            "cobrado": round(float(row["total_cobrado"] or 0.0), 2),
        }
        for row in fact_rows
    ]
    potential_map = {item["servicio"]: round(float(item["total"] or 0.0), 2) for item in potential_rows}
    for service_name, total in potential_map.items():
        existing = next((item for item in services if item["servicio"] == service_name), None)
        if existing:
            existing["potencial"] = total
        else:
            services.append(
                {
                    "servicio": service_name,
                    "facturas": 0,
                    "facturado": 0.0,
                    "cobrado": 0.0,
                    "potencial": total,
                }
            )
    services.sort(key=lambda item: float(item.get("facturado") or item.get("potencial") or 0.0), reverse=True)
    return {
        "facturas_emitidas": facturas_emitidas,
        "facturacion_total": facturacion_total,
        "cobrado_total": cobrado_total,
        "pendiente_total": pendiente_total,
        "potencial_operativo": potencial_operativo,
        "cobros_registrados": int((cobros["total_cobros"] if cobros else 0) or 0),
        "remesas_total": round(float((cobros["total_remesas"] if cobros else 0) or 0.0), 2),
        "servicios": services,
    }


def fetch_workspace_billing_rows(conn, workspace_id, limit=25):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {"rows": []}
    try:
        placeholders = ",".join(["?"] * len(empresa_ids))
        rows = conn.execute(
            f"""
            SELECT
              wf.id,
              wf.workspace_id,
              wf.empresa_id,
              wf.cliente_id,
              wf.servicio,
              wf.origen_tipo,
              wf.origen_id,
              wf.serie,
              wf.numero,
              wf.fecha_emision,
              wf.fecha_vencimiento,
              wf.concepto,
              wf.subtotal,
              wf.impuestos,
              wf.total,
              wf.estado,
              wf.remesa_id,
              wf.conciliacion_estado,
              wf.cobrada,
              wf.fecha_cobro,
              wf.forma_cobro,
              wf.responsable,
              wf.notas,
              wf.created_at,
              wf.updated_at,
              COALESCE(e.nombre, '') AS empresa_nombre,
              COALESCE(c.nombre, '') AS cliente_nombre,
              COALESCE(c.nif, '') AS cliente_nif,
              COALESCE((SELECT SUM(COALESCE(col.importe, 0)) FROM workspace_facturacion_cobros col WHERE col.factura_id = wf.id AND COALESCE(col.estado, 'Aplicado') != 'Devuelto'), 0) AS cobrado_total,
              CASE
                WHEN (COALESCE(wf.total, 0) - COALESCE((SELECT SUM(COALESCE(col.importe, 0)) FROM workspace_facturacion_cobros col WHERE col.factura_id = wf.id AND COALESCE(col.estado, 'Aplicado') != 'Devuelto'), 0)) < 0
                  THEN 0
                ELSE (COALESCE(wf.total, 0) - COALESCE((SELECT SUM(COALESCE(col.importe, 0)) FROM workspace_facturacion_cobros col WHERE col.factura_id = wf.id AND COALESCE(col.estado, 'Aplicado') != 'Devuelto'), 0))
              END AS saldo_pendiente
            FROM workspace_facturacion wf
            LEFT JOIN empresas e ON e.id = wf.empresa_id
            LEFT JOIN clientes c ON c.id = wf.cliente_id
            WHERE wf.workspace_id = ?
              AND wf.empresa_id IN ({placeholders})
            ORDER BY COALESCE(wf.fecha_emision, wf.created_at) DESC, wf.updated_at DESC
            LIMIT ?
            """,
            [workspace_id, *empresa_ids, max(1, min(int(limit or 25), 100))],
        ).fetchall()
        return {"rows": [dict(row) for row in rows]}
    except Exception:
        return {"rows": []}


def fetch_workspace_health(conn, workspace_id):
    def _safe(fn, fallback):
        try:
            return fn()
        except Exception:
            return fallback

    workspace_detail = fetch_workspace_detail(conn, workspace_id)
    if not workspace_detail:
        return None
    workspace = workspace_detail["workspace"]
    modules = workspace_detail["modules"]
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {
            "readiness_score": 0,
            "checklist": [],
            "module_health": [],
            "summary": {
                "clientes": 0,
                "documentos": 0,
                "facturas": 0,
            },
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    clientes_total_row = _safe(
        lambda: conn.execute(
            f"""
            SELECT COUNT(DISTINCT ce.cliente_id) AS total
            FROM clientes_empresas ce
            WHERE ce.empresa_id IN ({placeholders})
            """,
            empresa_ids,
        ).fetchone(),
        None,
    )
    clientes_total = int(row_value(clientes_total_row, "total", 0) or 0)
    docs_summary = (_safe(lambda: fetch_workspace_document_hub(conn, workspace_id, limit=5), {"summary": {"documentos_total": 0}}).get("summary") or {})
    billing_rows = (_safe(lambda: fetch_workspace_billing_rows(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    presupuesto_rows = (_safe(lambda: fetch_workspace_presupuestos(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    inbox_rows = (_safe(lambda: fetch_workspace_inbox_queue(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    portal_rows = (_safe(lambda: fetch_workspace_portal_clients(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    portal_requests = (_safe(lambda: fetch_workspace_portal_requests(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    automation_rows = (_safe(lambda: fetch_workspace_automations(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    billing_collections = (_safe(lambda: fetch_workspace_billing_collections(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    remittance_rows = (_safe(lambda: fetch_workspace_remesas(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    time_rows = (_safe(lambda: fetch_workspace_time_entries(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    fincas_communities = (_safe(lambda: fetch_workspace_fincas_comunidades(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    fincas_incidents = (_safe(lambda: fetch_workspace_fincas_incidencias(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    fincas_providers = (_safe(lambda: fetch_workspace_fincas_proveedores(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    fincas_meetings = (_safe(lambda: fetch_workspace_fincas_juntas(conn, workspace_id, limit=5), {"rows": []}).get("rows") or [])
    series_rows = (_safe(lambda: fetch_workspace_series(conn, workspace_id), {"rows": []}).get("rows") or [])
    facturas_total_row = _safe(
        lambda: conn.execute(
            f"""
            SELECT COUNT(*) AS total
            FROM workspace_facturacion
            WHERE workspace_id = ? AND empresa_id IN ({placeholders})
            """,
            [workspace_id, *empresa_ids],
        ).fetchone(),
        None,
    )
    facturas_total = int(row_value(facturas_total_row, "total", 0) or 0)
    seguros_total_row = _safe(
        lambda: conn.execute(
            f"SELECT COUNT(*) AS total FROM seguros WHERE empresa_id IN ({placeholders})",
            empresa_ids,
        ).fetchone(),
        None,
    )
    seguros_total = int(row_value(seguros_total_row, "total", 0) or 0)
    gestoria_total_row = _safe(
        lambda: conn.execute(
            f"SELECT COUNT(*) AS total FROM gestoria_trabajos WHERE empresa_id IN ({placeholders})",
            empresa_ids,
        ).fetchone(),
        None,
    )
    gestoria_total = int(row_value(gestoria_total_row, "total", 0) or 0)
    inmuebles_total_row = _safe(
        lambda: conn.execute(
            f"SELECT COUNT(*) AS total FROM inmuebles WHERE empresa_id IN ({placeholders})",
            empresa_ids,
        ).fetchone(),
        None,
    )
    inmuebles_total = int(row_value(inmuebles_total_row, "total", 0) or 0)
    operaciones_total_row = _safe(
        lambda: conn.execute(
            f"SELECT COUNT(*) AS total FROM operaciones_inmobiliarias WHERE empresa_id IN ({placeholders})",
            empresa_ids,
        ).fetchone(),
        None,
    )
    operaciones_total = int(row_value(operaciones_total_row, "total", 0) or 0)
    hipotecas_total_row = _safe(
        lambda: conn.execute(
            f"SELECT COUNT(*) AS total FROM hipotecas WHERE empresa_id IN ({placeholders})",
            empresa_ids,
        ).fetchone(),
        None,
    )
    hipotecas_total = int(row_value(hipotecas_total_row, "total", 0) or 0)
    facturas_recibidas_total_row = _safe(
        lambda: conn.execute(
            f"SELECT COUNT(*) AS total FROM gestoria_facturas WHERE empresa_id IN ({placeholders})",
            empresa_ids,
        ).fetchone(),
        None,
    )
    facturas_recibidas_total = int(row_value(facturas_recibidas_total_row, "total", 0) or 0)
    enabled_modules = [row for row in modules if int(row.get("enabled") or 0) == 1]
    branding_ready = bool((workspace.get("descripcion") or "").strip() and (workspace.get("primary_color") or "").strip())
    checklist = [
        {
            "label": "Branding",
            "done": 1 if branding_ready else 0,
            "hint": "Nombre, descripción y colores definidos.",
        },
        {
            "label": "Empresas",
            "done": 1 if len(empresa_ids) > 0 else 0,
            "hint": f"{len(empresa_ids)} sociedades vinculadas al tenant.",
        },
        {
            "label": "Módulos activos",
            "done": 1 if len(enabled_modules) >= 3 else 0,
            "hint": f"{len(enabled_modules)} módulos habilitados.",
        },
        {
            "label": "Base CRM",
            "done": 1 if int(clientes_total or 0) > 0 else 0,
            "hint": f"{int(clientes_total or 0)} clientes dentro del workspace.",
        },
        {
            "label": "Documental",
            "done": 1 if int(docs_summary.get('documentos_total') or 0) > 0 else 0,
            "hint": f"{int(docs_summary.get('documentos_total') or 0)} documentos agregados.",
        },
        {
            "label": "Facturación",
            "done": 1 if int(facturas_total or 0) > 0 else 0,
            "hint": f"{int(facturas_total or 0)} movimientos transversales registrados.",
        },
        {
            "label": "Presupuestos",
            "done": 1 if len(presupuesto_rows) > 0 else 0,
            "hint": f"{len(presupuesto_rows)} propuestas comerciales cargadas.",
        },
        {
            "label": "Series",
            "done": 1 if len(series_rows) > 0 else 0,
            "hint": f"{len(series_rows)} series de facturación configuradas.",
        },
        {
            "label": "Portal cliente",
            "done": 1 if len(portal_rows) > 0 else 0,
            "hint": f"{len(portal_rows)} accesos de portal activados.",
        },
        {
            "label": "Automatizaciones",
            "done": 1 if len(automation_rows) > 0 else 0,
            "hint": f"{len(automation_rows)} reglas definidas en el workspace.",
        },
        {
            "label": "Inbox entrada",
            "done": 1 if len(inbox_rows) > 0 else 0,
            "hint": f"{len(inbox_rows)} documentos registrados en la bandeja de entrada.",
        },
    ]
    readiness_score = round((sum(item["done"] for item in checklist) / max(len(checklist), 1)) * 100)
    onboarding_actions = []
    if not branding_ready:
        onboarding_actions.append({"label": "Completar branding del tenant", "target": "workspaceForm", "priority": "alta"})
    if len(enabled_modules) < 3:
        onboarding_actions.append({"label": "Activar módulos núcleo y verticales mínimas", "target": "workspaceModules", "priority": "alta"})
    if int(clientes_total or 0) == 0:
        onboarding_actions.append({"label": "Cargar primeros clientes del tenant", "target": "workspaceLauncher", "priority": "alta"})
    if int(docs_summary.get("documentos_total") or 0) == 0:
        onboarding_actions.append({"label": "Subir documentación inicial al inbox", "target": "workspaceInboxForm", "priority": "media"})
    if int(facturas_total or 0) == 0:
        onboarding_actions.append({"label": "Emitir la primera factura transversal", "target": "workspaceBillingForm", "priority": "media"})
    if len(portal_rows) == 0:
        onboarding_actions.append({"label": "Invitar al menos un cliente al portal", "target": "workspacePortalForm", "priority": "media"})
    if len(automation_rows) == 0:
        onboarding_actions.append({"label": "Configurar la primera automatización del tenant", "target": "workspaceAutomationForm", "priority": "media"})
    go_live_status = "listo" if readiness_score >= 85 else ("implantacion" if readiness_score >= 60 else "bloqueado")
    metrics_by_module = {
        "crm360": (clientes_total, "clientes activos en el tenant", "Importar o crear clientes base."),
        "documental": (docs_summary.get("documentos_total") or 0, "documentos unificados", "Subir documentos y revisar asignaciones."),
        "dashboard": (len(billing_rows) + len(presupuesto_rows) + int(clientes_total or 0), "fuentes listas para cuadros de mando", "Conectar más datos operativos y facturación."),
        "gestoria": (gestoria_total, "trabajos de gestoría", "Cargar trabajos/campañas y responsables."),
        "seguros": (seguros_total, "pólizas o expedientes de seguros", "Importar cartera o cargar pólizas activas."),
        "inmobiliaria": (inmuebles_total + operaciones_total, "inmuebles y operaciones", "Cargar captaciones, inmuebles u operaciones."),
        "financiacion": (hipotecas_total, "hipotecas registradas", "Activar expedientes y pipeline financiero."),
        "fincas": (len(fincas_communities) + len(fincas_incidents) + len(fincas_providers) + len(fincas_meetings), "comunidades, incidencias y operativa de fincas", "Cargar comunidades, proveedores e incidencias."),
        "facturacion": (facturas_total + len(remittance_rows) + len(billing_collections), "facturas, cobros y remesas", "Emitir primeras facturas del tenant."),
        "facturas_recibidas": (facturas_recibidas_total + len(inbox_rows), "facturas recibidas o inbox", "Activar inbox de proveedores."),
        "portal_cliente": (len(portal_rows) + len(portal_requests), "clientes y requerimientos de portal", "Invitar clientes clave y crear requerimientos."),
        "registro_horario": (len(time_rows), "fichajes registrados", "Activar fichajes y política laboral."),
        "automatizaciones": (len(automation_rows), "automatizaciones configuradas", "Definir reglas por evento."),
    }
    module_health = []
    for module in modules:
        key = module.get("modulo_key") or ""
        metric_value, metric_label, next_step = metrics_by_module.get(key, (0, "sin métrica", "Completar configuración."))
        enabled = int(module.get("enabled") or 0) == 1
        status = "disabled"
        if enabled and metric_value:
            status = "operativo"
        elif enabled:
            status = "configuracion"
        module_health.append(
            {
                "key": key,
                "nombre": module.get("modulo_nombre") or key,
                "enabled": 1 if enabled else 0,
                "status": status,
                "metric_value": int(metric_value or 0),
                "metric_label": metric_label,
                "next_step": next_step,
            }
        )
    return {
        "readiness_score": readiness_score,
        "checklist": checklist,
        "go_live_status": go_live_status,
        "onboarding_actions": onboarding_actions[:6],
        "module_health": module_health,
        "summary": {
            "clientes": int(clientes_total or 0),
            "documentos": int(docs_summary.get("documentos_total") or 0),
            "facturas": int(facturas_total or 0),
            "presupuestos": len(presupuesto_rows),
            "cobros": len(billing_collections),
            "portal_requerimientos": len(portal_requests),
            "fichajes": len(time_rows),
            "comunidades": len(fincas_communities),
            "remesas": len(remittance_rows),
        },
    }


def suggest_workspace_document_cliente(candidates, text):
    normalized_text = normalize_lookup_text(text)
    if len(normalized_text) < 6:
        return None
    best = None
    best_score = 0
    stopwords = {"DE", "DEL", "LA", "LAS", "LOS", "Y", "EL"}
    for candidate in candidates:
        name = candidate.get("nombre") or ""
        nif = normalize_lookup_text(candidate.get("nif") or "")
        name_norm = normalize_lookup_text(name)
        score = 0
        if nif and len(nif) >= 6 and nif in normalized_text:
            score = 1000 + len(nif)
        elif name_norm and len(name_norm) >= 8 and name_norm in normalized_text:
            score = 100 + len(name_norm)
        else:
            tokens = [token for token in name_norm.split() if len(token) >= 4 and token not in stopwords]
            matched = [token for token in tokens if token in normalized_text]
            if len(matched) >= 2:
                score = sum(len(token) for token in matched)
        if score > best_score:
            best_score = score
            best = candidate
    if best_score < 8:
        return None
    return {
        "id": best["id"],
        "nombre": best.get("nombre") or "",
        "nif": best.get("nif") or "",
        "score": best_score,
    }


def fetch_workspace_document_hub(conn, workspace_id, limit=20):
    started_at = time.perf_counter()
    query_count = 0
    processed_rows = []
    pending_assignments = 0
    try:
        empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
        if not empresa_ids:
            return {"rows": [], "summary": {"documentos_total": 0}}
        placeholders = ",".join(["?"] * len(empresa_ids))
        limit_val = max(1, min(int(limit or 20), 100))
        rows = conn.execute(
            f"""
            SELECT *
            FROM (
              SELECT
                d.id,
                'gestoria_docs' AS source_table,
                d.empresa_id,
                COALESCE(e.nombre, '') AS empresa,
                COALESCE(c.nombre, '') AS cliente,
                d.cliente_id,
                COALESCE(NULLIF(d.referencia_tipo, ''), 'gestoria') AS referencia_tipo,
                COALESCE(NULLIF(d.referencia_tipo, ''), d.tipo, 'gestoria') AS servicio,
                d.nombre,
                d.tipo,
                d.fecha,
                d.estado,
                d.notas,
                d.doc_key,
                d.doc_url,
                d.created_at AS sort_date
              FROM gestoria_docs d
              LEFT JOIN clientes c ON c.id = d.cliente_id
              LEFT JOIN empresas e ON e.id = d.empresa_id
              WHERE d.empresa_id IN ({placeholders})
              UNION ALL
              SELECT
                idoc.id,
                'inmueble_docs' AS source_table,
                i.empresa_id,
                COALESCE(e.nombre, '') AS empresa,
                COALESCE(i.direccion, '') AS cliente,
                NULL AS cliente_id,
                'inmobiliaria' AS referencia_tipo,
                'inmobiliaria' AS servicio,
                COALESCE(idoc.nombre, 'Documento inmueble') AS nombre,
                COALESCE(idoc.tipo, 'Inmueble') AS tipo,
                COALESCE(idoc.created_at, '') AS fecha,
                '' AS estado,
                '' AS notas,
                NULL AS doc_key,
                COALESCE(idoc.url, '') AS doc_url,
                idoc.created_at AS sort_date
              FROM inmueble_docs idoc
              JOIN inmuebles i ON i.id = idoc.inmueble_id
              LEFT JOIN empresas e ON e.id = i.empresa_id
              WHERE i.empresa_id IN ({placeholders})
            )
            ORDER BY COALESCE(fecha, sort_date) DESC, sort_date DESC
            LIMIT ?
            """,
            [*empresa_ids, *empresa_ids, limit_val],
        ).fetchall()
        query_count += 1
        processed_rows = []
        needs_candidate_rows = False
        for row in rows:
            item = dict(row)
            item["assignable"] = 1 if item.get("source_table") == "gestoria_docs" else 0
            item["suggested_cliente_id"] = ""
            item["suggested_cliente"] = ""
            if item["assignable"] and not item.get("cliente_id"):
                needs_candidate_rows = True
            processed_rows.append(item)
        candidate_rows = []
        if needs_candidate_rows:
            candidates = conn.execute(
                f"""
                SELECT DISTINCT c.id, c.nombre, COALESCE(c.nif, '') AS nif
                FROM clientes c
                JOIN clientes_empresas ce ON ce.cliente_id = c.id
                WHERE ce.empresa_id IN ({placeholders})
                ORDER BY LENGTH(COALESCE(c.nombre, '')) DESC, c.nombre COLLATE NOCASE ASC
                LIMIT 500
                """,
                empresa_ids,
            ).fetchall()
            query_count += 1
            candidate_rows = [dict(row) for row in candidates]
            if candidate_rows:
                processed_rows = []
                pending_assignments = 0
                for row in rows:
                    item = dict(row)
                    item["assignable"] = 1 if item.get("source_table") == "gestoria_docs" else 0
                    item["suggested_cliente_id"] = ""
                    item["suggested_cliente"] = ""
                    if item["assignable"] and not item.get("cliente_id"):
                        suggestion = suggest_workspace_document_cliente(
                            candidate_rows,
                            " ".join(
                                part
                                for part in [item.get("nombre"), item.get("notas"), item.get("tipo"), item.get("servicio")]
                                if part
                            ),
                        )
                        if suggestion:
                            item["suggested_cliente_id"] = suggestion["id"]
                            item["suggested_cliente"] = suggestion["nombre"]
                            pending_assignments += 1
                    processed_rows.append(item)
        total_docs = conn.execute(
            f"""
            SELECT
              (SELECT COUNT(*) FROM gestoria_docs WHERE empresa_id IN ({placeholders}))
              +
              (SELECT COUNT(*) FROM inmueble_docs idoc JOIN inmuebles i ON i.id = idoc.inmueble_id WHERE i.empresa_id IN ({placeholders}))
              AS total
            """,
            [*empresa_ids, *empresa_ids],
        ).fetchone()
        query_count += 1
        return {
            "rows": processed_rows,
            "summary": {
                "documentos_total": int(total_docs["total"] or 0) if total_docs else 0,
                "pendientes_asignacion": pending_assignments,
            },
        }
    except Exception:
        return {"rows": [], "summary": {"documentos_total": 0, "pendientes_asignacion": 0}}
    finally:
        _perf_log_operation(
            "fetch_workspace_document_hub",
            started_at,
            workspace_id=str(workspace_id or "").strip() or None,
            rows=len(processed_rows),
            queries=query_count,
        )


def json_response(handler, data, status=200, cookies=None, extra_headers=None):
    def _resolve_cors_origin():
        """
        CORS hardening:
        - Si la request trae `Origin` y coincide con nuestro `Host`, reflejamos ese origin y permitimos credenciales.
        - En caso contrario, usamos `*` (sin credenciales).
        Esto evita errores de Safari/WebKit cuando hace checks CORS incluso en algunos flows same-origin
        y, a la vez, no abre la puerta a orígenes arbitrarios con cookies.
        """
        try:
            origin = str(handler.headers.get("Origin") or "").strip()
        except Exception:
            origin = ""
        if not origin:
            return ("*", False)
        try:
            parsed = urllib.parse.urlparse(origin)
            origin_host = (parsed.hostname or "").strip().lower()
        except Exception:
            origin_host = ""
        try:
            host_header = str(handler.headers.get("Host") or "").strip()
            host_only = host_header.split(":")[0].strip().lower()
        except Exception:
            host_only = ""
        if origin_host and host_only and origin_host == host_only:
            return (origin, True)
        return ("*", False)

    def _json_default(value):  # noqa: ANN001
        # Postgres puede devolver Decimal (NUMERIC/ROUND/AVG). JSON estándar no lo soporta.
        if isinstance(value, Decimal):
            try:
                if value == value.to_integral_value():
                    return int(value)
            except Exception:
                pass
            try:
                return float(value)
            except Exception:
                return str(value)
        if isinstance(value, (datetime, date)):
            try:
                return value.isoformat()
            except Exception:
                return str(value)
        return str(value)

    payload = json.dumps(data, ensure_ascii=False, default=_json_default).encode("utf-8")
    handler.send_response(status)
    cors_origin, cors_creds = _resolve_cors_origin()
    handler.send_header("Access-Control-Allow-Origin", cors_origin)
    if cors_creds:
        handler.send_header("Access-Control-Allow-Credentials", "true")
    handler.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
    handler.send_header("Access-Control-Allow-Headers", "Content-Type")
    # Debug/trace: permite identificar la instancia que respondió (útil con múltiples réplicas detrás de proxy).
    try:
        handler.send_header("X-App-Pid", str(os.getpid()))
        handler.send_header("X-App-Started-At", str(getattr(handler.__class__, "_started_at", "") or getattr(handler, "_started_at", "") or ""))
    except Exception:
        pass
    for key, value in (extra_headers or []):
        handler.send_header(key, value)
    for cookie_value in (cookies or []):
        handler.send_header("Set-Cookie", cookie_value)
    handler.send_header("Content-Type", "application/json; charset=utf-8")

    # Gzip JSON si compensa (reduce mucho tiempo en iOS/PWA y conexiones lentas).
    try:
        accept_encoding = (handler.headers.get("Accept-Encoding") or "").lower()
        can_gzip = "gzip" in accept_encoding
        if can_gzip and payload and len(payload) > 1200:
            gz = gzip.compress(payload, compresslevel=6)
            if len(gz) + 80 < len(payload):
                payload = gz
                handler.send_header("Content-Encoding", "gzip")
                handler.send_header("Vary", "Accept-Encoding")
    except Exception:
        pass

    handler.send_header("Content-Length", str(len(payload)))
    handler.end_headers()
    handler.wfile.write(payload)


def binary_response(handler, data, content_type="application/octet-stream", filename=None, status=200):
    payload = data or b""
    handler.send_response(status)
    try:
        cors_origin, cors_creds = (("*", False))
        try:
            origin = str(handler.headers.get("Origin") or "").strip()
        except Exception:
            origin = ""
        if origin:
            try:
                parsed = urllib.parse.urlparse(origin)
                origin_host = (parsed.hostname or "").strip().lower()
            except Exception:
                origin_host = ""
            try:
                host_header = str(handler.headers.get("Host") or "").strip()
                host_only = host_header.split(":")[0].strip().lower()
            except Exception:
                host_only = ""
            if origin_host and host_only and origin_host == host_only:
                cors_origin, cors_creds = (origin, True)
        handler.send_header("Access-Control-Allow-Origin", cors_origin)
        if cors_creds:
            handler.send_header("Access-Control-Allow-Credentials", "true")
    except Exception:
        handler.send_header("Access-Control-Allow-Origin", "*")
    handler.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
    handler.send_header("Access-Control-Allow-Headers", "Content-Type")
    handler.send_header("Content-Type", content_type)
    if filename:
        handler.send_header("Content-Disposition", f'attachment; filename="{filename}"')
    handler.send_header("Content-Length", str(len(payload)))
    handler.end_headers()
    handler.wfile.write(payload)


def _pdf_escape(value):
    return runtime_pdf_utils._pdf_escape(value)


def format_eur(value):
    amount = float(value or 0.0)
    raw = f"{amount:,.2f}"
    return raw.replace(",", "X").replace(".", ",").replace("X", ".") + " €"


def build_workspace_invoice_pdf(invoice, workspace, company, client, collections):
    invoice_ref = "-".join(part for part in [invoice.get("serie"), invoice.get("numero")] if part) or invoice.get("id") or "-"
    company_name = company.get("nombre") or workspace.get("nombre") or "Empresa"
    cobrado = 0.0
    try:
        cobrado = sum(float(item.get("importe") or 0.0) for item in (collections or []))
    except Exception:
        cobrado = 0.0
    try:
        total_val = float(invoice.get("total") or 0.0)
    except Exception:
        total_val = 0.0
    pendiente = max(total_val - cobrado, 0.0)

    sections = [
        (
            "Emisor",
            [
                ("Empresa", company_name),
                ("Razón social", company.get("razon_social") or company_name),
                ("CIF/NIF", company.get("nif") or "-"),
                ("Dirección", company.get("direccion_fiscal") or company.get("direccion") or "-"),
                ("Teléfono", company.get("telefono") or "-"),
                ("Email", company.get("email") or "-"),
                ("Web", company.get("web") or "-"),
                ("IBAN", company.get("iban") or "-"),
                ("BIC/SWIFT", company.get("bic") or "-"),
            ],
        ),
        (
            "Factura",
            [
                ("Número", invoice_ref),
                ("Fecha emisión", invoice.get("fecha_emision") or "-"),
                ("Fecha vencimiento", invoice.get("fecha_vencimiento") or "-"),
                ("Estado", invoice.get("estado") or "-"),
                ("Servicio", invoice.get("servicio") or "-"),
                ("Concepto", invoice.get("concepto") or "-"),
            ],
        ),
        (
            "Cliente",
            [
                ("Nombre", client.get("nombre") or "-"),
                ("CIF/NIF", client.get("nif") or "-"),
                ("Teléfono", client.get("telefono") or "-"),
                ("Email", client.get("email") or "-"),
            ],
        ),
        (
            "Importes",
            [
                ("Subtotal", format_eur(invoice.get("subtotal") or 0)),
                ("Impuestos", format_eur(invoice.get("impuestos") or 0)),
                ("Total", format_eur(invoice.get("total") or 0)),
                ("Cobrado", format_eur(cobrado)),
                ("Pendiente", format_eur(pendiente)),
            ],
        ),
    ]
    if collections:
        sections.append(
            (
                "Cobros aplicados",
                [
                    f"{item.get('fecha_cobro') or '-'} · {item.get('metodo') or '-'} · {format_eur(item.get('importe') or 0)}"
                    for item in (collections or [])[:12]
                ],
            )
        )
    notas = str(invoice.get("notas") or "").strip()
    if notas:
        sections.append(("Notas", [notas]))
    footer = [
        f"Documento emitido por {company_name}.",
        "Esta factura se genera desde el motor de facturación del workspace y debe revisarse antes de su envío definitivo.",
    ]
    return build_branded_document_pdf(
        "FACTURA",
        f"{company_name} · {invoice_ref}",
        sections,
        footer,
        brand_logo_url=company.get("logo_url"),
    )


def build_workspace_budget_pdf(budget, workspace, company, client, lineas):
    def hex_to_rgb(value, fallback):
        raw = str(value or "").strip().lstrip("#")
        if len(raw) == 3:
            raw = "".join(ch * 2 for ch in raw)
        if len(raw) != 6:
            return fallback
        try:
            return tuple(int(raw[i:i + 2], 16) for i in (0, 2, 4))
        except Exception:
            return fallback

    def draw_label_value(draw, x, y, width, label, value, label_font, value_font, label_fill, value_fill):
        draw.text((x, y), str(label or "").upper(), fill=label_fill, font=label_font)
        label_box = draw.textbbox((x, y), str(label or "").upper(), font=label_font)
        current_y = label_box[3] + 8
        wrapped = _pdf_wrap_lines(value, width=max(20, int(width / 11)))
        draw.multiline_text((x, current_y), "\n".join(wrapped), fill=value_fill, font=value_font, spacing=6)
        sample_box = draw.textbbox((x, current_y), "Ag", font=value_font)
        line_height = sample_box[3] - sample_box[1] + 6
        return current_y + max(line_height * len(wrapped), line_height)

    calc = {}
    try:
        calc = json.loads(budget.get("calculo_json") or "{}") if budget.get("calculo_json") else {}
        if not isinstance(calc, dict):
            calc = {}
    except Exception:
        calc = {}
    primary = hex_to_rgb(workspace.get("primary_color"), (60, 110, 113))
    accent = hex_to_rgb(workspace.get("accent_color"), (143, 155, 116))
    ink = (35, 40, 44)
    muted = (104, 111, 117)
    soft = (244, 246, 247)
    border = (223, 228, 231)
    page_width, page_height = 1240, 1754
    margin_x, top_margin, bottom_margin = 84, 72, 84
    servicio_key = normalize_service_key(budget.get("servicio") or "")
    fincas_logo = _load_asset_logo("logos/fincas-velazquez.png", max_width=420) if servicio_key == "fincas" else None
    colegio_logo = _load_asset_logo("logos/colegio-administradores-v2.png", max_width=260) if servicio_key == "fincas" else None
    brand_logo = _load_brand_logo(company.get("logo_url"), max_width=420 if servicio_key == "fincas" else 360)
    # En Fincas, forzamos marca Fincas Velazquez (la empresa emisora puede tener un logo genérico/legacy).
    logo = fincas_logo if servicio_key == "fincas" and fincas_logo else (brand_logo or fincas_logo)
    # Foto de equipo bajo la cabecera del presupuesto (opcional).
    # Para activarla, guarda la imagen en `assets/photos/equipo-modernia.jpg`.
    team_photo = _load_asset_logo("photos/equipo-modernia.jpg", max_width=1100)
    emoji_icons = {
        "house": _load_asset_logo("emoji/house.png", max_width=22),
        "shop": _load_asset_logo("emoji/shop.png", max_width=22),
        "box": _load_asset_logo("emoji/box.png", max_width=22),
        "car": _load_asset_logo("emoji/car.png", max_width=22),
    }
    font_title = _document_font(44, bold=True)
    font_subtitle = _document_font(20, bold=False)
    font_subtitle_bold = _document_font(20, bold=True)
    font_chip = _document_font(16, bold=True)
    font_section = _document_font(22, bold=True)
    font_label = _document_font(14, bold=True)
    font_value = _document_font(20, bold=False)
    font_table_head = _document_font(15, bold=True)
    font_table = _document_font(16, bold=False)
    font_table_bold = _document_font(16, bold=True)
    font_total = _document_font(28, bold=True)
    font_footer = _document_font(14, bold=False)
    # Emojis (opcional): en macOS intentamos Apple Color Emoji; si no se puede renderizar, usaremos PNGs.
    font_emoji = None
    try:
        apple_paths = [
            "/System/Library/Fonts/Apple Color Emoji.ttc",
            "/System/Library/Fonts/Apple Color Emoji.ttf",
            "/Library/Fonts/Apple Color Emoji.ttc",
            "/Library/Fonts/Apple Color Emoji.ttf",
        ]
        for p in apple_paths:
            if os.path.exists(p):
                font_emoji = ImageFont.truetype(p, 18)
                break
    except Exception:
        font_emoji = None
    pages = []
    servicio_label = servicio_key or "-"
    ref_label = budget.get("id") or "-"

    def _trim_transparent(img):
        if not img:
            return None
        try:
            if img.mode not in ("RGBA", "LA"):
                img = img.convert("RGBA")
            alpha = img.split()[-1]
            bbox = alpha.getbbox()
            if not bbox:
                return img
            # Ignore near-full bboxes (no meaningful transparency trimming).
            if bbox == (0, 0, img.width, img.height):
                return img
            return img.crop(bbox)
        except Exception:
            return img

    def _fit_image_to_box(img, max_w, max_h, *, trim=True):
        if not img:
            return None
        out = img.copy()
        if trim:
            out = _trim_transparent(out) or out
        try:
            out.thumbnail((int(max_w), int(max_h)), Image.LANCZOS)
        except Exception:
            pass
        return out

    def _paste_logo_box(image, draw, logo_img, box, *, padding=14):
        if not logo_img:
            return
        x0, y0, x1, y1 = [int(v) for v in box]
        # Caja blanca para que el logo no "ensucie" la cabecera, y para un layout estable.
        draw.rounded_rectangle((x0, y0, x1, y1), radius=22, fill=(255, 255, 255), outline=border)
        inner_w = max(10, (x1 - x0) - (padding * 2))
        inner_h = max(10, (y1 - y0) - (padding * 2))
        fitted = _fit_image_to_box(logo_img, inner_w, inner_h, trim=True)
        if not fitted:
            return
        px = x0 + padding + int((inner_w - fitted.width) / 2)
        py = y0 + padding + int((inner_h - fitted.height) / 2)
        image.paste(fitted, (px, py), fitted)

    page_index = 0

    def _draw_inline_text(draw, x, y, parts, *, fill):
        cursor_x = x
        for part in parts:
            text = str(part.get("text") or "")
            if not text:
                continue
            font = part.get("font") or font_table
            draw.text((cursor_x, y), text, fill=fill, font=font)
            bbox = draw.textbbox((cursor_x, y), text, font=font)
            cursor_x = bbox[2]
        return cursor_x

    def _draw_small_icon(draw, x, y, kind, *, size=18, fill=(35, 40, 44)):
        x = int(x)
        y = int(y)
        s = int(size)
        try:
            if kind == "house":
                # Roof
                draw.polygon([(x + s // 2, y), (x, y + s // 2), (x + s, y + s // 2)], fill=fill)
                # Body
                draw.rectangle((x + 3, y + s // 2, x + s - 3, y + s), outline=fill, width=2)
                # Door
                door_w = max(4, s // 4)
                draw.rectangle((x + s // 2 - door_w // 2, y + s - (s // 3), x + s // 2 + door_w // 2, y + s), outline=fill, width=2)
            elif kind == "shop":
                draw.rectangle((x + 2, y + 4, x + s - 2, y + s), outline=fill, width=2)
                draw.rectangle((x, y, x + s, y + 6), fill=fill)
            elif kind == "box":
                draw.rectangle((x + 2, y + 2, x + s - 2, y + s - 2), outline=fill, width=2)
                draw.line((x + 2, y + s // 2, x + s - 2, y + s // 2), fill=fill, width=2)
                draw.line((x + s // 2, y + 2, x + s // 2, y + s - 2), fill=fill, width=2)
            elif kind == "car":
                draw.rectangle((x + 3, y + s // 2, x + s - 3, y + s - 4), outline=fill, width=2)
                draw.polygon([(x + 5, y + s // 2), (x + s // 2, y + 4), (x + s - 5, y + s // 2)], outline=fill, fill=None, width=2)
                r = max(2, s // 7)
                draw.ellipse((x + 5, y + s - 2 * r - 2, x + 5 + 2 * r, y + s - 2), outline=fill, width=2)
                draw.ellipse((x + s - 5 - 2 * r, y + s - 2 * r - 2, x + s - 5, y + s - 2), outline=fill, width=2)
        except Exception:
            return

    def _make_map_placeholder(width, height, *, title, subtitle):
        img = Image.new("RGB", (int(width), int(height)), (246, 248, 250))
        d = ImageDraw.Draw(img)
        # Light "street" strokes
        for i in range(0, img.width, 70):
            d.line((i, 0, i + 70, img.height), fill=(232, 236, 240), width=3)
        for j in range(0, img.height, 60):
            d.line((0, j, img.width, j + 30), fill=(235, 239, 243), width=2)
        # Pin
        cx = img.width // 2
        cy = img.height // 2 - 10
        d.ellipse((cx - 12, cy - 12, cx + 12, cy + 12), fill=(215, 62, 54), outline=(180, 40, 35), width=2)
        d.polygon([(cx, cy + 26), (cx - 10, cy + 8), (cx + 10, cy + 8)], fill=(215, 62, 54), outline=(180, 40, 35))
        # Text
        d.text((16, 14), title, fill=(35, 40, 44), font=_document_font(16, True))
        note = "Vista previa (sin conexión). Escanee el QR para abrir el mapa exacto."
        d.text((16, 38), note, fill=(88, 96, 104), font=_document_font(13, False))
        d.text((16, 60), subtitle, fill=(88, 96, 104), font=_document_font(14, False))
        return img

    def _paste_photo_cover(image, draw, photo_img, box):
        if not photo_img:
            return
        x0, y0, x1, y1 = [int(v) for v in box]
        try:
            w = max(10, x1 - x0)
            h = max(10, y1 - y0)
            bg = Image.new("RGB", (w, h), "white")
            photo = photo_img.convert("RGB")
            photo.thumbnail((w, h), Image.LANCZOS)
            px = int((w - photo.width) / 2)
            py = int((h - photo.height) / 2)
            bg.paste(photo, (px, py))
            image.paste(bg, (x0, y0))
        except Exception:
            return
        draw.rounded_rectangle((x0, y0, x1, y1), radius=22, outline=border, width=2)

    def new_page(include_cards=False):
        nonlocal page_index
        image = Image.new("RGB", (page_width, page_height), "white")
        draw = ImageDraw.Draw(image)
        header_h = 210
        draw.rounded_rectangle((0, 0, page_width, header_h), radius=0, fill=primary)
        draw.polygon([(page_width - 200, 0), (page_width, 0), (page_width, 160)], fill=accent)
        draw.text((margin_x, top_margin), "PRESUPUESTO", fill="white", font=font_title)
        # Empresa en negrita (evita que pase desapercibida).
        draw.text(
            (margin_x, top_margin + 62),
            company.get("nombre") or workspace.get("nombre") or "Workspace",
            fill=(240, 246, 248),
            font=font_subtitle_bold,
        )
        # Chips de cabecera: útiles en presupuestos generales, pero en Fincas ensucian el diseño.
        if servicio_key != "fincas":
            chip_y = top_margin + 112
            chips = [
                f"REF {ref_label[:12]}",
                f"FECHA {budget.get('fecha') or '-'}",
                f"ESTADO {budget.get('estado') or 'Borrador'}",
                f"SERVICIO {servicio_label.upper()}",
            ]
            chip_x = margin_x
            for chip in chips:
                box = draw.textbbox((chip_x, chip_y), chip, font=font_chip)
                chip_w = (box[2] - box[0]) + 30
                draw.rounded_rectangle(
                    (chip_x, chip_y - 8, chip_x + chip_w, chip_y + 26),
                    radius=18,
                    fill=(94, 137, 139),
                    outline=(255, 255, 255),
                )
                draw.text((chip_x + 15, chip_y), chip, fill="white", font=font_chip)
                chip_x += chip_w + 12
        if logo:
            # Logo en caja fija para evitar solapes con chips/títulos.
            _paste_logo_box(
                image,
                draw,
                logo,
                (page_width - margin_x - 340, 34, page_width - margin_x, 34 + 126),
                padding=14,
            )
        current_y = header_h + 36
        # Foto de equipo solo en la primera página del presupuesto (no en la portada especial de Fincas).
        if page_index == 0 and team_photo and servicio_key != "fincas":
            photo_y = 266
            photo_h = 190
            photo_box = (margin_x, photo_y, page_width - margin_x, photo_y + photo_h)
            draw.rounded_rectangle(photo_box, radius=22, fill=(255, 255, 255), outline=border)
            _paste_photo_cover(image, draw, team_photo, (photo_box[0] + 2, photo_box[1] + 2, photo_box[2] - 2, photo_box[3] - 2))
            current_y = photo_box[3] + 26
        if include_cards:
            left = (margin_x, current_y, margin_x + 560, current_y + 250)
            right = (page_width - margin_x - 420, current_y, page_width - margin_x, current_y + 250)
            draw.rounded_rectangle(left, radius=28, fill=soft, outline=border)
            draw.rounded_rectangle(right, radius=28, fill=(250, 247, 240), outline=border)
            draw.text((left[0] + 24, left[1] + 22), "CLIENTE", fill=primary, font=font_section)
            y_client = left[1] + 64
            y_client = draw_label_value(draw, left[0] + 24, y_client, 500, "Nombre", client.get("nombre") or "-", font_label, font_value, muted, ink)
            y_client = draw_label_value(draw, left[0] + 24, y_client + 10, 220, "NIF", client.get("nif") or "-", font_label, font_value, muted, ink)
            y_client = draw_label_value(draw, left[0] + 250, left[1] + 64, 250, "Teléfono", client.get("telefono") or "-", font_label, font_value, muted, ink)
            draw_label_value(draw, left[0] + 250, left[1] + 150, 250, "Email", client.get("email") or "-", font_label, _document_font(16, False), muted, ink)
            draw.text((right[0] + 24, right[1] + 22), "RESUMEN ECONÓMICO", fill=primary, font=font_section)
            draw.text((right[0] + 24, right[1] + 82), "TOTAL", fill=muted, font=font_label)
            draw.text((right[0] + 24, right[1] + 108), format_eur(budget.get("total") or 0), fill=ink, font=font_total)
            draw.text((right[0] + 24, right[1] + 170), f"Subtotal {format_eur(budget.get('subtotal') or 0)}", fill=ink, font=font_table)
            draw.text((right[0] + 24, right[1] + 198), f"Impuestos {format_eur(budget.get('impuestos') or 0)}", fill=ink, font=font_table)
            draw.text((right[0] + 24, right[1] + 226), f"Pago {budget.get('forma_pago') or 'Pendiente'}", fill=ink, font=font_table)
            current_y = left[3] + 34
        page_index += 1
        return image, draw, current_y

    if servicio_key == "fincas":
        cover = Image.new("RGB", (page_width, page_height), "white")
        cover_draw = ImageDraw.Draw(cover)
        cover_draw.rounded_rectangle((0, 0, page_width, 240), radius=0, fill=primary)
        cover_draw.polygon([(page_width - 240, 0), (page_width, 0), (page_width, 200)], fill=accent)
        # Cabecera limpia: el texto de carta/propuesta se mueve al cuerpo (debajo de la cabecera).
        cover_title = "PRESUPUESTO"
        subtitle = "Administración de fincas · Propuesta de servicios"
        title_x = margin_x
        # Reserva espacio a derecha para el sello/colegio: evita que el título "pise" la cabecera.
        colegio_box = (page_width - margin_x - 340, 24, page_width - margin_x, 24 + 90)
        right_limit = colegio_box[0] - 18 if colegio_logo else (page_width - margin_x)
        if logo:
            # Evita que el logo se monte sobre el título.
            _paste_logo_box(
                cover,
                cover_draw,
                logo,
                (margin_x, 20, margin_x + 250, 20 + 90),
                padding=10,
            )
            title_x = margin_x + 270

        def _draw_cover_text(draw, x, y, text, *, font, fill, max_w, spacing=6, prefer_split=None):
            """
            Dibuja texto (1-2 líneas) asegurando que no sobrepase `max_w`.
            Priorizamos partir en dos líneas antes que reducir tipografía (layout estable).
            """
            try:
                box = draw.textbbox((x, y), text, font=font)
                if (box[2] - box[0]) <= max_w:
                    draw.text((x, y), text, fill=fill, font=font)
                    return 1
            except Exception:
                pass
            parts = [p for p in (text or "").split(" ") if p]
            if len(parts) <= 1:
                draw.text((x, y), text, fill=fill, font=font)
                return 1
            # Permite split determinista para títulos conocidos (p.ej. "CARTA DE PRESENTACIÓN").
            if prefer_split and isinstance(prefer_split, (tuple, list)) and len(prefer_split) == 2:
                line1, line2 = str(prefer_split[0] or "").strip(), str(prefer_split[1] or "").strip()
                if line1 and line2:
                    draw.multiline_text((x, y), f"{line1}\n{line2}", fill=fill, font=font, spacing=spacing)
                    return 2
            # Split simple en 2 líneas por espacio.
            mid = max(1, int(len(parts) / 2))
            line1 = " ".join(parts[:mid]).strip()
            line2 = " ".join(parts[mid:]).strip()
            draw.multiline_text((x, y), f"{line1}\n{line2}", fill=fill, font=font, spacing=spacing)
            return 2

        max_title_w = max(200, int(right_limit - title_x))
        _draw_cover_text(
            cover_draw,
            title_x,
            top_margin + 12,
            cover_title,
            font=font_title,
            fill="white",
            max_w=max_title_w,
            spacing=10,
        )
        # Subtítulo NO en cabecera (se renderiza abajo, en la carta).
        if colegio_logo:
            _paste_logo_box(cover, cover_draw, colegio_logo, colegio_box, padding=10)
            colegiado = str(calc.get("colegiado_numero") or "3079").strip() or "3079"
            cover_draw.text(
                (colegio_box[0], colegio_box[3] + 10),
                f"Colegiado nº {colegiado}",
                fill=(240, 246, 248),
                font=_document_font(16, True),
            )
        else:
            cover_draw.text((page_width - margin_x - 360, 44), "Colegio de Administradores", fill=(240, 246, 248), font=font_subtitle)

        client_name = str(calc.get("comunidad_denominacion") or client.get("nombre") or budget.get("titulo") or "").strip() or "Comunidad"
        fecha_txt = str(budget.get("fecha") or "").strip() or datetime.now().date().isoformat()
        try:
            fecha_txt = format_spanish_long_date_capitalized(fecha_txt)
        except Exception:
            pass
        # Carta de presentación (tono comercial y clara, encima de la foto del equipo).
        intro_lines = [
            "Gracias por solicitar nuestra propuesta. En Modernia llevamos más de 40 años administrando comunidades con un enfoque cercano y muy práctico.",
            "Trabajamos con un despacho multidisciplinar: laboral, fiscal y contable, mediación de seguros, administrador de fincas colegiado y apoyo jurídico.",
            "Nuestro objetivo es sencillo: tranquilidad para la comunidad. Respuesta ágil ante incidencias, control de costes y proveedores, y transparencia en cada decisión.",
            "Entregamos información clara y periódica (cuentas, situación de morosidad e incidencias) para que el presidente y la junta puedan decidir con seguridad.",
            "Si lo desea, concertamos una visita y revisamos su documentación actual para afinar la cuota y proponer mejoras inmediatas sin compromiso.",
        ]
        cuerpo = [
            subtitle,
            "",
            f"{fecha_txt}",
            "",
            f"A la atención de {client_name}:",
            "",
            *intro_lines,
            "",
            "Le remitimos nuestra propuesta de servicios de administración de fincas para su comunidad, con una cuota calculada de forma objetiva a partir de las unidades del edificio.",
        ]
        extra_letter = str(calc.get("carta_presentacion") or "").strip()
        if extra_letter:
            cuerpo.extend(["", "Información adicional:", ""])
            cuerpo.extend([line.rstrip() for line in extra_letter.splitlines()])
        cuerpo.extend([
            "",
            "Atentamente,",
            f"{company.get('nombre') or workspace.get('nombre') or 'Fincas Velazquez'}",
        ])
        # Layout portada: carta (arriba) + foto de equipo (abajo).
        y_cover = 262
        letter_h = 470
        photo_h = 360
        gap = 22
        # La carta va directamente "sobre el folio" (sin recuadro), para un look más editorial.
        letter_box = (margin_x, y_cover, page_width - margin_x, y_cover + letter_h)
        text_x = margin_x
        text_y = y_cover
        max_letter_w = max(200, int(letter_box[2] - text_x))

        def _should_justify_line(txt):
            t = str(txt or "").strip()
            if not t:
                return False
            if t.endswith(":"):
                return False
            if any(k in t for k in ("·", "×")):
                return False
            if t.lower().startswith(("a la atención", "atentamente", "información adicional")):
                return False
            if t.lower().startswith(("cálculo base:", "cuota mensual", "total anual")):
                return False
            return len(t.split()) >= 7

        for idx, line in enumerate(cuerpo):
            if not str(line).strip():
                text_y += 16
                continue
            # Primer bloque (subtitle) más destacado.
            use_font = font_section if idx == 0 else font_table
            if idx == 0 or not _should_justify_line(line):
                wrapped = _pdf_wrap_lines_px(cover_draw, line, use_font, max_letter_w if idx != 0 else int(max_letter_w * 0.78))
                cover_draw.multiline_text((text_x, text_y), "\n".join(wrapped), fill=ink, font=use_font, spacing=6, align="left")
                sample_box = cover_draw.textbbox((text_x, text_y), "Ag", font=use_font)
                text_y += (sample_box[3] - sample_box[1] + 8) * len(wrapped)
            else:
                text_y = _pdf_draw_justified_paragraph(
                    cover_draw,
                    text_x,
                    text_y,
                    max_letter_w,
                    line,
                    use_font,
                    ink,
                    line_spacing=6,
                )
            if text_y > letter_box[3] - 26:
                break

        photo_y = letter_box[3] + gap
        photo_box = (margin_x, photo_y, page_width - margin_x, min(page_height - bottom_margin - 22, photo_y + photo_h))
        if team_photo:
            try:
                # Mejor look: foto a sangre dentro del cuadro (sin márgenes), con recorte suave.
                cover_draw.rounded_rectangle(photo_box, radius=28, fill=(255, 255, 255), outline=border)
                w = max(10, photo_box[2] - photo_box[0] - 6)
                h = max(10, photo_box[3] - photo_box[1] - 6)
                photo = team_photo.convert("RGB")
                # Rellenar "de punta a punta" evitando cortar por abajo:
                # Sin recorte del sujeto (contain) pero sin márgenes "vacíos":
                # rellenamos el rectángulo con un fondo a sangre (cover) desenfocado
                # y encima colocamos la foto completa centrada.
                bg = ImageOps.fit(photo, (w, h), method=Image.LANCZOS, centering=(0.5, 0.5))
                try:
                    bg = bg.filter(ImageFilter.GaussianBlur(radius=18))
                    bg = ImageEnhance.Brightness(bg).enhance(0.95)
                    bg = ImageEnhance.Contrast(bg).enhance(0.95)
                except Exception:
                    pass
                fg = ImageOps.contain(photo, (w, h), method=Image.LANCZOS)
                bg.paste(fg, ((w - fg.width) // 2, (h - fg.height) // 2))
                cover.paste(bg, (photo_box[0] + 3, photo_box[1] + 3))
            except Exception:
                pass
        footer_cover = "Documento generado automáticamente desde el CRM. La propuesta económica se detalla en las páginas siguientes."
        cover_draw.multiline_text((margin_x, page_height - bottom_margin), "\n".join(_pdf_wrap_lines(footer_cover, width=108)), fill=muted, font=font_footer, spacing=4)
        pages.append(cover)

    image, draw, y = new_page(include_cards=True)
    usable_bottom = page_height - bottom_margin

    def ensure_space(required_height):
        nonlocal image, draw, y
        if y + required_height <= usable_bottom:
            return
        pages.append(image)
        image, draw, y = new_page(include_cards=False)

    if servicio_key == "fincas":
        ensure_space(120)
        box = (margin_x, y, page_width - margin_x, y + 100)
        draw.rounded_rectangle(box, radius=24, fill=(247, 250, 242), outline=border)
        draw.text((box[0] + 24, box[1] + 18), "BASE DE CÁLCULO COMUNIDAD", fill=primary, font=font_section)
        base_y = box[1] + 58
        cursor_x = box[0] + 24
        icon_y = base_y - 2
        icon_size = 18
        sep = " · "
        items = [
            ("house", calc.get("num_vecinos") or 0),
            ("shop", calc.get("num_locales") or 0),
            ("box", calc.get("num_trasteros") or 0),
            ("car", calc.get("num_aparcamientos") or 0),
        ]
        emoji_chars = {"house": "🏠", "shop": "🏬", "box": "📦", "car": "🚗"}
        for idx, (kind, value) in enumerate(items):
            if font_emoji:
                ch = emoji_chars.get(kind) or ""
                if ch:
                    cursor_x = _draw_inline_text(draw, cursor_x, base_y, [{"text": f"{ch} ", "font": font_emoji}], fill=ink)
                else:
                    _draw_small_icon(draw, cursor_x, icon_y, kind, size=icon_size, fill=ink)
                    cursor_x += icon_size + 8
            else:
                icon = emoji_icons.get(kind)
                if icon:
                    try:
                        image.paste(icon, (int(cursor_x), int(base_y - 4)), icon)
                    except Exception:
                        pass
                    cursor_x += icon.width + 8
                else:
                    _draw_small_icon(draw, cursor_x, icon_y, kind, size=icon_size, fill=ink)
                    cursor_x += icon_size + 8
            cursor_x = _draw_inline_text(draw, cursor_x, base_y, [{"text": f"{value}", "font": font_table_bold}], fill=ink)
            if idx != len(items) - 1:
                cursor_x = _draw_inline_text(draw, cursor_x, base_y, [{"text": sep, "font": font_table}], fill=ink)
        cursor_x = _draw_inline_text(draw, cursor_x, base_y, [{"text": " · Base sugerida ", "font": font_table}], fill=ink)
        _draw_inline_text(
            draw,
            cursor_x,
            base_y,
            [{"text": f"{format_eur(calc.get('cuota_sugerida') or 0)}", "font": font_table_bold}],
            fill=ink,
        )
        y = box[3] + 24

        ensure_space(240)
        box2 = (margin_x, y, page_width - margin_x, y + 210)
        draw.rounded_rectangle(box2, radius=24, fill=(252, 252, 252), outline=border)
        draw.text((box2[0] + 24, box2[1] + 18), "DATOS COMUNIDAD / SOLICITANTE", fill=primary, font=font_section)
        lines = [
            f"Comunidad: {str(calc.get('comunidad_denominacion') or client.get('nombre') or '-').strip() or '-'}",
            f"Dirección: {str(calc.get('comunidad_direccion') or '-').strip() or '-'}",
            f"CIF: {str(calc.get('comunidad_cif') or client.get('nif') or '-').strip() or '-'}",
            f"Referencia catastral: {str(calc.get('referencia_catastral') or '-').strip() or '-'}",
            f"Solicitante: {str(calc.get('solicitante_nombre') or '-').strip() or '-'} · DNI {str(calc.get('solicitante_dni') or '-').strip() or '-'}",
            f"Teléfono: {str(calc.get('solicitante_telefono') or client.get('telefono') or '-').strip() or '-'} · Email: {str(calc.get('solicitante_email') or client.get('email') or '-').strip() or '-'}",
        ]
        y_txt = box2[1] + 58
        for line in lines:
            wrapped = _pdf_wrap_lines(line, width=104)
            draw.multiline_text((box2[0] + 24, y_txt), "\n".join(wrapped), fill=ink, font=font_table, spacing=4)
            sample_box = draw.textbbox((box2[0] + 24, y_txt), "Ag", font=font_table)
            y_txt += (sample_box[3] - sample_box[1] + 8) * len(wrapped)
        y = max(box2[3], y_txt + 10) + 24

        addr_for_map = str(calc.get("comunidad_direccion") or "").strip()
        photo_key = str(calc.get("edificio_foto_key") or "").strip()
        map_url = ""
        map_img = None
        qr_img = None
        if addr_for_map:
            normalized_addr = addr_for_map if re.search(r"(españa|spain)\b", addr_for_map, flags=re.I) else f"{addr_for_map}, España"
            # Si el front ya resolvió coordenadas, las reutilizamos (evita fallos por direcciones incompletas como "Jalón 25").
            lat = None
            lon = None
            try:
                lat_raw = str(calc.get("map_lat") or "").strip()
                lon_raw = str(calc.get("map_lon") or "").strip()
                if lat_raw and lon_raw:
                    lat = float(lat_raw.replace(",", "."))
                    lon = float(lon_raw.replace(",", "."))
            except Exception:
                lat = None
                lon = None
            map_url = (
                f"https://www.google.com/maps/search/?api=1&query={urllib.parse.quote(normalized_addr)}"
                if (lat is None or lon is None)
                else f"https://www.google.com/maps/search/?api=1&query={urllib.parse.quote(f'{lat},{lon}')}"
            )
            try:
                import qrcode

                qr_img = qrcode.make(map_url).convert("RGBA").resize((180, 180))
            except Exception:
                qr_img = None
            # Intentamos incluir un "mapa" visible en el PDF, no solo el QR.
            # Usamos geocodificación ya existente + staticmap de OpenStreetMap (server-side, sin CORS).
            try:
                coords = None
                if lat is None or lon is None:
                    coords = fetch_geocode_coordinates(normalized_addr)
                    if coords and coords.get("ok"):
                        lat = float(coords.get("lat"))
                        lon = float(coords.get("lon"))
                if lat is not None and lon is not None:
                    params = urllib.parse.urlencode(
                        {
                            "center": f"{lat},{lon}",
                            "zoom": "16",
                            "size": "660x210",
                            "maptype": "mapnik",
                            "markers": f"{lat},{lon},red-pushpin",
                        }
                    )
                    headers = {
                        "User-Agent": "Verifika2CRM/1.0 (contacto@grupomodernia.es)",
                        "Accept": "image/png,image/*;q=0.9,*/*;q=0.8",
                    }
                    # staticmap.openstreetmap.de a veces falla por rate-limit / red; probamos espejos.
                    candidates = [
                        f"https://staticmap.openstreetmap.de/staticmap.php?{params}",
                        f"https://staticmap.openstreetmap.fr/staticmap.php?{params}",
                    ]
                    for url in candidates:
                        try:
                            req = urllib.request.Request(url, headers=headers)
                            with urllib.request.urlopen(req, timeout=10) as response:
                                raw = response.read()
                            if raw:
                                map_img = Image.open(BytesIO(raw)).convert("RGB")
                                break
                        except Exception:
                            map_img = None
            except Exception:
                map_img = None
        building_photo = None
        if photo_key:
            try:
                raw_bytes, _err = s3_get_object_bytes(photo_key)
                if raw_bytes:
                    building_photo = Image.open(BytesIO(raw_bytes))
            except Exception:
                building_photo = None
        if qr_img or building_photo or map_img:
            # Altura dinámica: permite mostrar mapa + foto de edificio en la misma sección.
            photo_w = 660
            map_h = 140 if (map_img and building_photo) else 210
            building_h = 140 if (map_img and building_photo) else 210
            stack_gap = 14
            left_h = map_h
            if map_img and building_photo:
                left_h = map_h + stack_gap + building_h
            elif building_photo and not map_img:
                left_h = building_h
            inner_h = max(180, left_h)
            box_h = 62 + inner_h + 24
            ensure_space(box_h + 30)
            box_media = (margin_x, y, page_width - margin_x, y + box_h)
            draw.rounded_rectangle(box_media, radius=24, fill=(247, 248, 252), outline=border)
            draw.text((box_media[0] + 24, box_media[1] + 18), "MAPA / EDIFICIO", fill=primary, font=font_section)
            inner_left = box_media[0] + 24
            inner_top = box_media[1] + 62
            photo_h = inner_h
            gap = 24
            qr_x = inner_left
            if map_img:
                try:
                    # Si también hay foto de edificio, apilamos ambas (mapa arriba, edificio abajo).
                    if building_photo:
                        map_fit = ImageOps.fit(map_img, (photo_w, map_h), method=Image.LANCZOS)
                        image.paste(map_fit, (inner_left, inner_top))
                        draw.rounded_rectangle(
                            (inner_left, inner_top, inner_left + photo_w, inner_top + map_h),
                            radius=20,
                            outline=border,
                            width=2,
                        )
                        try:
                            photo = building_photo.convert("RGB")
                            photo = ImageOps.fit(photo, (photo_w, building_h), method=Image.LANCZOS)
                            by = inner_top + map_h + stack_gap
                            image.paste(photo, (inner_left, by))
                            draw.rounded_rectangle(
                                (inner_left, by, inner_left + photo_w, by + building_h),
                                radius=20,
                                outline=border,
                                width=2,
                            )
                        except Exception:
                            building_photo = None
                    else:
                        map_fit = ImageOps.fit(map_img, (photo_w, photo_h), method=Image.LANCZOS)
                        image.paste(map_fit, (inner_left, inner_top))
                        draw.rounded_rectangle(
                            (inner_left, inner_top, inner_left + photo_w, inner_top + photo_h),
                            radius=20,
                            outline=border,
                            width=2,
                        )
                except Exception:
                    map_img = None
                qr_x = inner_left + photo_w + gap
            elif building_photo:
                try:
                    photo = building_photo.convert("RGB")
                    photo = ImageOps.fit(photo, (photo_w, photo_h), method=Image.LANCZOS)
                    image.paste(photo, (inner_left, inner_top))
                    draw.rounded_rectangle(
                        (inner_left, inner_top, inner_left + photo_w, inner_top + photo_h),
                        radius=20,
                        outline=border,
                        width=2,
                    )
                except Exception:
                    building_photo = None
                qr_x = inner_left + photo_w + gap
            elif addr_for_map:
                # Fallback robusto: si no podemos descargar un mapa real (red/rate-limit),
                # generamos un "mapa" de cortesía para que siempre se vea algo en el PDF.
                try:
                    placeholder = _make_map_placeholder(photo_w, photo_h, title="Mapa (vista previa)", subtitle=addr_for_map)
                    image.paste(placeholder, (inner_left, inner_top))
                    draw.rounded_rectangle(
                        (inner_left, inner_top, inner_left + photo_w, inner_top + photo_h),
                        radius=20,
                        outline=border,
                        width=2,
                    )
                except Exception:
                    pass
                qr_x = inner_left + photo_w + gap
            if qr_img:
                image.paste(qr_img, (qr_x, inner_top), qr_img)
                draw.text((qr_x + 200, inner_top + 6), "Escanea para ver el mapa", fill=ink, font=font_table)
                addr_lines = _pdf_wrap_lines(addr_for_map or "-", width=34)
                draw.multiline_text((qr_x + 200, inner_top + 40), "\n".join(addr_lines[:4]), fill=muted, font=font_footer, spacing=4)
            y = box_media[3] + 24

        servicios_incluidos = calc.get("servicios_incluidos") if isinstance(calc, dict) else None
        if isinstance(servicios_incluidos, list) and servicios_incluidos:
            service_lines = []
            for item in servicios_incluidos[:10]:
                text = str(item or "").strip()
                if not text:
                    continue
                service_lines.extend(_pdf_wrap_lines(f"• {text}", width=104))
            if service_lines:
                # Altura dinámica robusta: evita que el texto "pise" otras secciones cuando el font/spacing cambia.
                try:
                    sample_box = draw.textbbox((0, 0), "Ag", font=font_table)
                    line_h = max(18, int(sample_box[3] - sample_box[1])) + 6
                except Exception:
                    line_h = 22
                # Evita que un listado enorme desborde la página (mejor truncar y dejar nota).
                max_lines = 18
                if len(service_lines) > max_lines:
                    remaining = max(0, len(service_lines) - max_lines)
                    service_lines = service_lines[:max_lines]
                    service_lines.append(f"• … y {remaining} líneas más")
                required_h = 64 + len(service_lines) * line_h
                ensure_space(required_h + 24)
                box3 = (margin_x, y, page_width - margin_x, y + required_h)
                draw.rounded_rectangle(box3, radius=24, fill=(247, 248, 252), outline=border)
                draw.text((box3[0] + 24, box3[1] + 18), "SERVICIOS INCLUIDOS", fill=primary, font=font_section)
                draw.multiline_text((box3[0] + 24, box3[1] + 58), "\n".join(service_lines), fill=ink, font=font_table, spacing=4)
                y = box3[3] + 24

    # En presupuestos de Fincas, la tabla de partidas debe ir siempre en su propia página (la 3),
    # para evitar que el encabezado quede colgando al final de la ficha.
    if servicio_key == "fincas":
        pages.append(image)
        image, draw, y = new_page(include_cards=False)

    ensure_space(70)
    draw.text((margin_x, y), "PARTIDAS PRESUPUESTADAS", fill=primary, font=font_section)
    y += 42
    # Columnas de la tabla: se calculan dinámicamente para respetar márgenes.
    # Antes estaban "hardcoded" y la columna TOTAL se salía del área útil (se recortaba en PDF).
    table_left = margin_x
    table_right = page_width - margin_x
    table_w = max(600, int(table_right - table_left))
    col_gap = 12
    col_w_qty = 150
    col_w_price = 150
    col_w_dto = 100
    col_w_total = 150
    col_w_concept = table_w - (col_w_qty + col_w_price + col_w_dto + col_w_total + col_gap * 4)
    # Salvaguarda: si el espacio es menor (fuente/escala), recortamos columnas numéricas.
    if col_w_concept < 380:
        short = 380 - col_w_concept
        take_each = int((short + 3) / 4)
        col_w_qty = max(120, col_w_qty - take_each)
        col_w_price = max(120, col_w_price - take_each)
        col_w_dto = max(84, col_w_dto - take_each)
        col_w_total = max(120, col_w_total - take_each)
        col_w_concept = table_w - (col_w_qty + col_w_price + col_w_dto + col_w_total + col_gap * 4)
    x_concept = table_left
    x_qty = x_concept + col_w_concept + col_gap
    x_price = x_qty + col_w_qty + col_gap
    x_dto = x_price + col_w_price + col_gap
    x_total = x_dto + col_w_dto + col_gap
    columns = {
        "concepto": (x_concept, col_w_concept),
        "cantidad": (x_qty, col_w_qty),
        "precio": (x_price, col_w_price),
        "dto": (x_dto, col_w_dto),
        "total": (x_total, col_w_total),
    }
    cell_pad_x = 14

    def _draw_cell_text(draw, col_key, y0, text, *, font, fill, align="left", extra_x=0):
        x0, w = columns[col_key]
        text = str(text or "").replace("\xa0", " ")
        if align == "right":
            # anchor="ra" evita descuadres por mediciones diferentes de textbbox (fuentes/símbolos).
            draw.text((x0 + w - cell_pad_x + extra_x, y0), text, fill=fill, font=font, anchor="ra")
            return
        if align == "center":
            draw.text((x0 + int(w / 2) + extra_x, y0), text, fill=fill, font=font, anchor="ma")
            return
        draw.text((x0 + cell_pad_x + extra_x, y0), text, fill=fill, font=font)
    header_h = 40
    draw.rounded_rectangle((margin_x, y, page_width - margin_x, y + header_h), radius=16, fill=primary)
    draw.text((columns["concepto"][0] + 18, y + 10), "PARTIDA", fill="white", font=font_table_head)
    _draw_cell_text(draw, "cantidad", y + 10, "CANT.", font=font_table_head, fill="white", align="center")
    _draw_cell_text(draw, "precio", y + 10, "PRECIO", font=font_table_head, fill="white", align="center")
    _draw_cell_text(draw, "dto", y + 10, "DTO", font=font_table_head, fill="white", align="center")
    _draw_cell_text(draw, "total", y + 10, "TOTAL", font=font_table_head, fill="white", align="center")
    y += header_h + 10
    row_fill = (249, 250, 251)
    for index, line in enumerate(lineas or [{"categoria": "Partida", "concepto": budget.get("titulo") or "-", "cantidad": 1, "unidad": "", "precio_unitario": budget.get("subtotal") or budget.get("total") or 0, "descuento_pct": 0, "total_linea": budget.get("subtotal") or budget.get("total") or 0}], start=1):
        concept = f"{line.get('categoria') or 'Partida'} · {line.get('concepto') or '-'}"
        concept_lines = _pdf_wrap_lines(concept, width=54)
        row_h = 54 + max(0, len(concept_lines) - 1) * 20
        ensure_space(row_h + 12)
        fill = row_fill if index % 2 else (255, 255, 255)
        draw.rounded_rectangle((margin_x, y, page_width - margin_x, y + row_h), radius=14, fill=fill, outline=border)
        draw.multiline_text((columns["concepto"][0] + 18, y + 12), "\n".join(concept_lines), fill=ink, font=font_table, spacing=4)
        qty_text = f"{_pdf_format_number(line.get('cantidad'), 2) or '0'} {line.get('unidad') or ''}".strip()
        qty_text = qty_text.replace("\xa0", " ")
        _draw_cell_text(draw, "cantidad", y + 16, qty_text, font=font_table, fill=ink, align="right")
        _draw_cell_text(draw, "precio", y + 16, format_eur(line.get("precio_unitario") or 0), font=font_table, fill=ink, align="right")
        _draw_cell_text(draw, "dto", y + 16, f"{_pdf_format_number(line.get('descuento_pct'), 2) or '0'}%", font=font_table, fill=ink, align="right")
        _draw_cell_text(draw, "total", y + 16, format_eur(line.get("total_linea") or 0), font=font_table, fill=ink, align="right")
        y += row_h + 10

    ensure_space(180)
    # Caja de cierre con posición robusta: si el listado de partidas llega abajo, evitamos que se "corte" el total.
    totals_h = 160
    totals_top = y + 10
    max_top = (page_height - bottom_margin) - totals_h - 36
    if totals_top > max_top:
        pages.append(image)
        image, draw, y = new_page(include_cards=False)
        totals_top = y + 10
    totals_box = (page_width - margin_x - 360, totals_top, page_width - margin_x, totals_top + totals_h)
    draw.rounded_rectangle(totals_box, radius=26, fill=soft, outline=border)
    draw.text((totals_box[0] + 24, totals_box[1] + 22), "CIERRE ECONÓMICO", fill=primary, font=font_section)
    # Valores alineados a la derecha para evitar descuadres con importes largos.
    val_right = totals_box[2] - 24
    draw.text((totals_box[0] + 24, totals_box[1] + 76), "Subtotal", fill=ink, font=font_table)
    draw.text((val_right, totals_box[1] + 76), f"{format_eur(budget.get('subtotal') or 0)}", fill=ink, font=font_table, anchor="ra")
    draw.text((totals_box[0] + 24, totals_box[1] + 106), "Impuestos", fill=ink, font=font_table)
    draw.text((val_right, totals_box[1] + 106), f"{format_eur(budget.get('impuestos') or 0)}", fill=ink, font=font_table, anchor="ra")
    draw.text((totals_box[0] + 24, totals_box[1] + 136), "Total", fill=ink, font=_document_font(20, True))
    draw.text((val_right, totals_box[1] + 136), f"{format_eur(budget.get('total') or 0)}", fill=ink, font=_document_font(20, True), anchor="ra")
    left_text_top = totals_top + 8
    draw.text((margin_x, left_text_top), "RESPONSABLE", fill=muted, font=font_label)
    draw.text((margin_x, left_text_top + 24), budget.get("responsable") or "-", fill=ink, font=font_table)
    draw.text((margin_x, left_text_top + 68), "FORMA DE PAGO", fill=muted, font=font_label)
    draw.text((margin_x, left_text_top + 92), budget.get("forma_pago") or "Pendiente de definir", fill=ink, font=font_table)
    y = totals_box[3] + 24

    if budget.get("observaciones"):
        ensure_space(160)
        draw.text((margin_x, y), "OBSERVACIONES", fill=primary, font=font_section)
        y += 36
        obs_lines = _pdf_wrap_lines(budget.get("observaciones"), width=98)
        draw.rounded_rectangle((margin_x, y, page_width - margin_x, y + 38 + len(obs_lines) * 22), radius=20, fill=(252, 252, 252), outline=border)
        draw.multiline_text((margin_x + 20, y + 18), "\n".join(obs_lines), fill=ink, font=font_table, spacing=6)
        y += 50 + len(obs_lines) * 22

    footer_text = f"Documento emitido por {company.get('nombre') or workspace.get('nombre') or 'Workspace'}. Presupuesto editable y sujeto a aceptación expresa del cliente."
    footer_lines = _pdf_wrap_lines(footer_text, width=108)
    draw.line((margin_x, page_height - bottom_margin - 28, page_width - margin_x, page_height - bottom_margin - 28), fill=border, width=2)
    draw.multiline_text((margin_x, page_height - bottom_margin), "\n".join(footer_lines), fill=muted, font=font_footer, spacing=4)

    pages.append(image)
    buffer = BytesIO()
    if len(pages) == 1:
        pages[0].save(buffer, format="PDF", resolution=150.0)
    else:
        pages[0].save(buffer, format="PDF", resolution=150.0, save_all=True, append_images=pages[1:])
    return buffer.getvalue()


