def _pdf_form_value(value, fallback=""):
    raw = str(value or "").replace("\r", "").strip()
    return raw if raw else str(fallback or "").strip()


def _build_acroform_overlay_pdf(pagesize_list, fields_by_page):
    """
    Devuelve bytes PDF con solo campos AcroForm (sin bordes/relleno) para superponer sobre un template.
    `fields_by_page`: {page_index: [ {name,x,y,width,height,value,multiline?} ]}
    """
    if rl_canvas is None or rl_colors is None:
        return None
    pagesize_list = pagesize_list or [(595.0, 842.0)]

    def build_one_page(size, fields):
        buf = BytesIO()
        c = rl_canvas.Canvas(buf, pagesize=size)
        form = c.acroForm
        text_color = rl_colors.black
        for field in fields or []:
            try:
                name = str(field.get("name") or "").strip()
                if not name:
                    continue
                x = float(field.get("x") or 0)
                y = float(field.get("y") or 0)
                w = float(field.get("width") or field.get("w") or 0)
                h = float(field.get("height") or field.get("h") or 0)
                value = _pdf_form_value(field.get("value") or "")
                multiline = bool(field.get("multiline"))
                font_size = field.get("fontSize") or field.get("fontsize") or 10
                try:
                    font_size = float(font_size)
                except Exception:
                    font_size = 10
                font_name = str(field.get("fontName") or field.get("font_name") or "Helvetica").strip() or "Helvetica"
                flags = 4096 if multiline else 0  # Multiline
                form.textfield(
                    name=name,
                    x=x,
                    y=y,
                    width=max(10.0, w),
                    height=max(10.0, h),
                    value=value,
                    forceBorder=False,
                    borderWidth=0,
                    borderColor=None,
                    fillColor=None,
                    textColor=text_color,
                    fontName=font_name,
                    fontSize=font_size,
                    fieldFlags=flags,
                )
            except Exception:
                continue
        # Finaliza la página antes de guardar: necesario para que ReportLab resuelva referencias de AcroForm.
        # (Si no se llama, algunas versiones lanzan "forward reference to Page1 not resolved".)
        try:
            c.showPage()
        except Exception:
            pass
        c.save()
        return buf.getvalue()

    if len(pagesize_list) > 1 and (PdfReader is not None and PdfWriter is not None):
        writer = PdfWriter()
        for idx, size in enumerate(pagesize_list):
            try:
                page_bytes = build_one_page(size, (fields_by_page or {}).get(idx, []))
                reader = PdfReader(BytesIO(page_bytes))
                writer.add_page(reader.pages[0])
            except Exception:
                try:
                    writer.add_blank_page(width=float(size[0]), height=float(size[1]))
                except Exception:
                    pass
        out = BytesIO()
        try:
            writer.write(out)
        except Exception:
            return None
        return out.getvalue()

    try:
        return build_one_page(pagesize_list[0], (fields_by_page or {}).get(0, []))
    except Exception:
        return None


def _build_static_text_overlay_pdf(pagesize_list, fields_by_page, font_name="Helvetica", font_size=10, leading=12):
    """
    Devuelve bytes PDF con texto "plano" (no editable) para superponer sobre un template.
    `fields_by_page`: {page_index: [ {x,y,width,height,value,multiline?} ]}
    """
    if rl_canvas is None or rl_colors is None:
        return None
    buffer = BytesIO()
    first_size = pagesize_list[0] if pagesize_list else (595, 842)
    c = rl_canvas.Canvas(buffer, pagesize=first_size)

    def _safe_string_width(text, fs):
        try:
            return float(c.stringWidth(str(text or ""), font_name, float(fs)))
        except Exception:
            try:
                return float(c.stringWidth(str(text or ""), "Helvetica", float(fs)))
            except Exception:
                return float(len(str(text or "")) * (float(fs) * 0.55))

    def _truncate_to_width(text, max_width, fs, ellipsis="…"):
        raw = str(text or "")
        if max_width <= 0:
            return raw
        if _safe_string_width(raw, fs) <= max_width:
            return raw
        if _safe_string_width(ellipsis, fs) > max_width:
            return ""
        lo, hi = 0, len(raw)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            candidate = raw[:mid] + ellipsis
            if _safe_string_width(candidate, fs) <= max_width:
                lo = mid
            else:
                hi = mid - 1
        return (raw[:lo] + ellipsis) if lo > 0 else ellipsis

    def _fit_single_line(text, max_width, fs, min_fs=6.0):
        raw = str(text or "")
        if max_width <= 0 or not raw:
            return raw, fs
        fs_try = float(fs)
        while fs_try > float(min_fs) and _safe_string_width(raw, fs_try) > max_width:
            fs_try -= 0.5
        if _safe_string_width(raw, fs_try) > max_width:
            raw = _truncate_to_width(raw, max_width, fs_try)
        return raw, fs_try

    def _with_clip_rect(x, y, w, h):
        if w <= 0 or h <= 0:
            return False
        try:
            path = c.beginPath()
            path.rect(x, y, w, h)
            c.saveState()
            c.clipPath(path, stroke=0, fill=0)
            return True
        except Exception:
            return False

    def _end_clip(active):
        if not active:
            return
        try:
            c.restoreState()
        except Exception:
            pass

    try:
        c.setFillColor(rl_colors.black)
    except Exception:
        pass
    for idx, size in enumerate(pagesize_list or [first_size]):
        try:
            c.setPageSize(size)
        except Exception:
            pass
        for field in (fields_by_page or {}).get(idx, []):
            try:
                value = _pdf_form_value(field.get("value") or "")
                if not value:
                    continue
                x = float(field.get("x") or 0)
                y = float(field.get("y") or 0)
                w = float(field.get("width") or field.get("w") or 0)
                h = float(field.get("height") or field.get("h") or 0)
                is_multiline = bool(field.get("multiline"))
                fs = float(field.get("fontSize") or font_size or 10)
                lead = float(field.get("leading") or leading or (fs + 2))
                try:
                    c.setFont(font_name, fs)
                except Exception:
                    c.setFont("Helvetica", fs)
                if is_multiline:
                    # Dibuja desde arriba del bbox hacia abajo.
                    lines = [line for line in str(value).replace("\r", "").split("\n") if line is not None]
                    cursor_y = y + max(0.0, h - fs)
                    max_lines = int(max(1, (h / lead))) if h else len(lines)
                    clip_active = _with_clip_rect(x, y, w, h)
                    try:
                        max_width = max(0.0, w - 2.0)
                        for line in lines[:max_lines]:
                            safe_line = _truncate_to_width(str(line), max_width, fs)
                            c.drawString(x + 1.0, cursor_y, safe_line)
                            cursor_y -= lead
                    finally:
                        _end_clip(clip_active)
                else:
                    # Alineación simple dentro del bbox.
                    max_width = max(0.0, w - 2.0)
                    safe_value, fs_fit = _fit_single_line(str(value), max_width, fs)
                    try:
                        c.setFont(font_name, fs_fit)
                    except Exception:
                        c.setFont("Helvetica", fs_fit)
                    clip_active = _with_clip_rect(x, y, w, h)
                    try:
                        c.drawString(x + 1.0, y + 3.0, safe_value)
                    finally:
                        _end_clip(clip_active)
            except Exception:
                continue
        if idx < len(pagesize_list) - 1:
            c.showPage()
    c.save()
    return buffer.getvalue()


def _merge_template_with_overlay_pdf(template_bytes, overlay_bytes):
    if PdfReader is None or PdfWriter is None:
        return None
    try:
        template_reader = PdfReader(BytesIO(template_bytes))
        overlay_reader = PdfReader(BytesIO(overlay_bytes))
    except Exception:
        return None
    writer = PdfWriter()
    for idx, tpage in enumerate(template_reader.pages):
        if idx < len(overlay_reader.pages):
            try:
                tpage.merge_page(overlay_reader.pages[idx])
            except Exception:
                pass
        writer.add_page(tpage)
    out = BytesIO()
    try:
        writer.write(out)
    except Exception:
        return None
    return out.getvalue()


def _merge_template_with_overlay_acroform(template_bytes, overlay_bytes):
    if PdfReader is None or PdfWriter is None or NameObject is None:
        return None
    try:
        template_reader = PdfReader(BytesIO(template_bytes))
        overlay_reader = PdfReader(BytesIO(overlay_bytes))
    except Exception:
        return None

    def _strip_widget_appearance(page_obj):
        """
        macOS Preview puede "duplicar" el texto (solape) cuando un widget ya trae /AP.
        Forzamos a que el visor regenere apariencias eliminando /AP y /AS.
        """
        try:
            annots = page_obj.get("/Annots")
        except Exception:
            annots = None
        if not annots:
            return
        for aref in list(annots):
            try:
                aobj = aref.get_object()
            except Exception:
                aobj = None
            if not aobj:
                continue
            try:
                if aobj.get("/Subtype") == NameObject("/Widget"):
                    if "/AP" in aobj:
                        del aobj["/AP"]
                    if "/AS" in aobj:
                        del aobj["/AS"]
            except Exception:
                continue
    writer = PdfWriter()
    for idx, tpage in enumerate(template_reader.pages):
        if idx < len(overlay_reader.pages):
            opage = overlay_reader.pages[idx]
            _strip_widget_appearance(opage)
            try:
                tpage.merge_page(opage)
            except Exception:
                pass
            try:
                oann = opage.get("/Annots")
                if oann:
                    tann = tpage.get("/Annots")
                    if tann:
                        # Evita duplicados: algunos visores/implementaciones pueden copiar /Annots al hacer merge_page().
                        try:
                            existing = set()
                            for a in list(tann):
                                try:
                                    key = (getattr(a, "idnum", None), getattr(a, "generation", None))
                                except Exception:
                                    key = None
                                if not key or key == (None, None):
                                    key = repr(a)
                                existing.add(key)
                            for a in list(oann):
                                try:
                                    key = (getattr(a, "idnum", None), getattr(a, "generation", None))
                                except Exception:
                                    key = None
                                if not key or key == (None, None):
                                    key = repr(a)
                                if key in existing:
                                    continue
                                tann.append(a)
                                existing.add(key)
                        except Exception:
                            try:
                                tann.extend(oann)
                            except Exception:
                                tpage[NameObject("/Annots")] = oann
                    else:
                        tpage[NameObject("/Annots")] = oann
            except Exception:
                pass
        writer.add_page(tpage)
    # Construye AcroForm a partir de las anotaciones /FT (campos).
    try:
        fields = ArrayObject()
        for page in writer.pages:
            annots = page.get("/Annots")
            if not annots:
                continue
            for a in annots:
                try:
                    obj = a.get_object()
                except Exception:
                    obj = None
                if obj and obj.get("/FT"):
                    fields.append(a)
        acro = DictionaryObject()
        acro[NameObject("/Fields")] = fields
        acro[NameObject("/NeedAppearances")] = BooleanObject(True)
        # Copia recursos de la AcroForm del overlay (fuentes /DA) si están disponibles.
        try:
            o_root = overlay_reader.trailer.get("/Root") if overlay_reader and overlay_reader.trailer else None
            o_acro = o_root.get("/AcroForm") if o_root else None
            if o_acro:
                try:
                    o_acro = o_acro.get_object()
                except Exception:
                    pass
                for key in ("/DA", "/DR", "/Q"):
                    try:
                        if key in o_acro and key not in acro:
                            acro[NameObject(key)] = o_acro[key]
                    except Exception:
                        continue
        except Exception:
            pass
        writer._root_object.update({NameObject("/AcroForm"): writer._add_object(acro)})
    except Exception:
        pass
    out = BytesIO()
    try:
        writer.write(out)
    except Exception:
        return None
    return out.getvalue()


def _pdf_fix_acroform_preview_overlap(pdf_bytes):
    """
    Normaliza PDFs con formularios AcroForm para evitar solapes en macOS Preview:
    - elimina /AP y /AS de los widgets (Preview puede dibujar "doble")
    - fuerza /NeedAppearances (mejor compatibilidad de render)
    - si el documento no trae /AcroForm (fallback), lo reconstruye a partir de /Annots
    """
    if not pdf_bytes or PdfReader is None or PdfWriter is None or NameObject is None:
        return pdf_bytes
    try:
        reader = PdfReader(BytesIO(pdf_bytes))
    except Exception:
        return pdf_bytes

    writer = PdfWriter()
    cloned_root = False
    try:
        writer.clone_document_from_reader(reader)
        cloned_root = True
    except Exception:
        # Fallback: al menos copiamos páginas (puede perder root objects como /AcroForm).
        try:
            for page in reader.pages:
                writer.add_page(page)
        except Exception:
            return pdf_bytes

    # Strip widget appearances on writer pages.
    widget_annots = 0
    try:
        for page in writer.pages:
            annots = page.get("/Annots")
            if not annots:
                continue
            for aref in list(annots):
                try:
                    aobj = aref.get_object()
                except Exception:
                    aobj = None
                if not aobj:
                    continue
                try:
                    if str(aobj.get("/Subtype")) == "/Widget":
                        widget_annots += 1
                        if "/AP" in aobj:
                            del aobj["/AP"]
                        if "/AS" in aobj:
                            del aobj["/AS"]
                except Exception:
                    continue
    except Exception:
        pass

    # Force NeedAppearances if AcroForm exists.
    try:
        acro = writer._root_object.get("/AcroForm")
        if acro:
            try:
                acro = acro.get_object()
            except Exception:
                pass
            try:
                acro[NameObject("/NeedAppearances")] = BooleanObject(True)
            except Exception:
                pass
    except Exception:
        acro = None

    # If we couldn't clone the root and we have widgets, rebuild a minimal AcroForm.
    try:
        if (not cloned_root) and widget_annots and (not writer._root_object.get("/AcroForm")):
            fields = ArrayObject()
            seen = set()
            for page in writer.pages:
                annots = page.get("/Annots")
                if not annots:
                    continue
                for a in annots:
                    try:
                        obj = a.get_object()
                    except Exception:
                        obj = None
                    if not obj or not obj.get("/FT"):
                        continue
                    try:
                        key = (getattr(a, "idnum", None), getattr(a, "generation", None))
                    except Exception:
                        key = None
                    if not key or key == (None, None):
                        key = repr(a)
                    if key in seen:
                        continue
                    seen.add(key)
                    fields.append(a)
            if fields:
                acro = DictionaryObject()
                acro[NameObject("/Fields")] = fields
                acro[NameObject("/NeedAppearances")] = BooleanObject(True)
                writer._root_object.update({NameObject("/AcroForm"): writer._add_object(acro)})
    except Exception:
        pass

    out = BytesIO()
    try:
        writer.write(out)
    except Exception:
        return pdf_bytes
    return out.getvalue()


def build_inmueble_nota_encargo_pdf_editable(company, inmueble, captacion, owners, extra=None):
    """
    Nota de encargo basada en PDF plantilla (Modernia) con campos rellenables.
    Fallback: documento PDF simple (no editable) si faltan dependencias/plantilla.
    """
    extra = extra or {}
    owners = owners or []

    def normalize_tipo_operacion(value):
        raw = str(value or "").strip().lower()
        if raw in {"alquiler", "arrendamiento", "renta"}:
            return "alquiler"
        return "venta"

    tipo_operacion = normalize_tipo_operacion(extra.get("tipo_operacion") or extra.get("tipo"))
    template_path = INMO_NOTA_ENCARGO_ALQUILER_TEMPLATE if tipo_operacion == "alquiler" else INMO_NOTA_ENCARGO_VENTA_TEMPLATE
    if not template_path.exists():
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    if rl_canvas is None or PdfReader is None:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    try:
        template_bytes = template_path.read_bytes()
        reader = PdfReader(BytesIO(template_bytes))
    except Exception:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)

    pagesizes = []
    for page in reader.pages:
        try:
            pagesizes.append((float(page.mediabox.width), float(page.mediabox.height)))
        except Exception:
            pagesizes.append((595.0, 842.0))

    direccion = _pdf_form_value(inmueble.get("direccion"))
    cp = _pdf_form_value(inmueble.get("codigo_postal"), "")
    poblacion = _pdf_form_value(inmueble.get("poblacion"), "")
    provincia = _pdf_form_value(inmueble.get("provincia"), "")
    locality = " ".join([p for p in [cp, poblacion] if p]).strip()
    provincia_clean = provincia
    if provincia_clean and poblacion and provincia_clean.strip().lower() == poblacion.strip().lower():
        provincia_clean = ""
    direccion_full = ", ".join([part for part in [direccion, locality, provincia_clean] if part]).strip() or direccion

    def _style_value(value):
        raw = _pdf_form_value(value, "")
        return raw.upper() if raw else raw

    direccion_full = _style_value(direccion_full)
    ref_catastral = _style_value(inmueble.get("referencia_catastral"))
    datos_registrales = _style_value(extra.get("datos_registrales"))
    m2_construidos = _style_value(inmueble.get("m2"))
    m2_utiles = _style_value(extra.get("m2_utiles"))
    otros = _style_value(extra.get("otros"))
    cargas = _style_value(extra.get("cargas") or "NADA")

    owner1 = owners[0] if len(owners) > 0 else {}
    owner2 = owners[1] if len(owners) > 1 else {}

    def owner_block(owner):
        if not owner:
            return ""
        parts = []
        nombre = _style_value(owner.get("nombre"))
        nif = _style_value(owner.get("nif"))
        dom = _style_value(owner.get("direccion") or owner.get("domicilio"))
        tel = _style_value(owner.get("telefono"))
        email_val = _style_value(owner.get("email"))
        if nombre:
            parts.append(nombre)
        # Compactamos para que encaje en las cajas del template (evita solaparse).
        if dom:
            parts.append(dom)
        meta_bits = []
        if nif:
            meta_bits.append(f"NIF: {nif}")
        if tel:
            meta_bits.append(f"Tel: {tel}")
        if email_val:
            meta_bits.append(f"Email: {email_val}")
        if meta_bits:
            parts.append(" · ".join(meta_bits))
        # Máximo 3 líneas para no invadir texto del template.
        return "\n".join(parts[:3])

    owner1_text = owner_block(owner1)
    owner2_text = owner_block(owner2)

    def _normalize_owner_city(owner):
        owner = owner or {}
        for key in ("poblacion", "localidad", "ciudad", "municipio"):
            val = str(owner.get(key) or "").strip()
            if val:
                return val
        return ""

    def _normalize_owner_street(owner, city_hint=""):
        owner = owner or {}
        raw = str(owner.get("direccion") or owner.get("domicilio") or "").replace("\n", " ").strip()
        if not raw:
            return ""
        city_hint = str(city_hint or "").strip()
        if city_hint:
            try:
                if raw.strip().lower().startswith(city_hint.lower()):
                    raw = raw.strip()[len(city_hint) :].lstrip(" ,.-")
            except Exception:
                pass
        if city_hint:
            try:
                raw = re.sub(rf",?\s*{re.escape(city_hint)}\b.*$", "", raw, flags=re.IGNORECASE).strip()
            except Exception:
                pass
        raw = re.sub(r"\b\d{5}\b.*$", "", raw).strip()
        raw = re.sub(r"^\s*(c/|c\.|calle)\s*", "", raw, flags=re.IGNORECASE).strip()
        raw = re.sub(r"^\s*c\s*/\s*", "", raw, flags=re.IGNORECASE).strip()
        raw = re.sub(r"\b\d{5}\b", "", raw).strip()
        if city_hint:
            try:
                raw = re.sub(rf"\b{re.escape(city_hint)}\b", "", raw, flags=re.IGNORECASE).strip(" ,")
            except Exception:
                pass
        return raw.strip(" ,")

    def _owner_fields(owner):
        owner = owner or {}
        has_any = any(
            str(owner.get(k) or "").strip()
            for k in (
                "nombre",
                "nif",
                "telefono",
                "email",
                "direccion",
                "domicilio",
                "poblacion",
                "localidad",
                "ciudad",
                "municipio",
            )
        )
        if not has_any:
            return {"nombre": "", "nif": "", "telefono": "", "email": "", "ciudad": "", "calle": ""}
        nombre = _pdf_form_value(owner.get("nombre"), "")
        nif_val = _pdf_form_value(owner.get("nif"), "")
        tel_val = _pdf_form_value(owner.get("telefono"), "")
        email_val = _pdf_form_value(owner.get("email"), "")
        city = _normalize_owner_city(owner) or str(inmueble.get("poblacion") or "").strip()
        street = _normalize_owner_street(owner, city_hint=city)
        return {
            "nombre": nombre,
            "nif": nif_val,
            "telefono": tel_val,
            "email": email_val,
            "ciudad": city,
            "calle": street,
        }

    if tipo_operacion == "alquiler":
        precio = _style_value(extra.get("renta_mensual") or extra.get("precio_alquiler") or captacion.get("precio_objetivo") or inmueble.get("precio_objetivo"))
        honorarios = _style_value(extra.get("honorarios_mensualidades") or extra.get("honorarios_text"))
        plazo = _style_value(extra.get("plazo_arrendamiento"))
    else:
        precio = _style_value(extra.get("precio_venta") or inmueble.get("precio_encargo") or inmueble.get("precio_objetivo") or captacion.get("precio_objetivo"))
        honorarios = _style_value(extra.get("honorarios_text") or extra.get("honorarios_pct"))
        plazo = ""

    fecha_venta_desde = _style_value(extra.get("fecha_venta_desde"))
    fecha_venta_antes = _style_value(extra.get("fecha_venta_antes"))
    fecha_inicio = _style_value(extra.get("fecha_inicio"))
    fecha_fin = _style_value(extra.get("fecha_fin"))
    lugar_firma = _style_value(extra.get("lugar_firma") or poblacion or provincia)
    fecha_firma = _style_value(extra.get("fecha_firma"))

    fields = {}

    if tipo_operacion == "venta":
        w, h = pagesizes[0]
        # Coordenadas calculadas sobre plantilla Modernia venta (A4) usando bbox.
        fields[0] = [
            {"name": "direccion", "x": 80, "y": h - 157.08, "width": w - 100, "height": 14, "value": direccion_full, "fontName": "Helvetica-Bold"},
            {"name": "datos_registrales", "x": 110, "y": h - 171.84, "width": 310, "height": 14, "value": datos_registrales, "fontName": "Helvetica-Bold"},
            {"name": "ref_catastral", "x": 90, "y": h - 186.60, "width": 130, "height": 14, "value": ref_catastral, "fontName": "Helvetica-Bold"},
            {"name": "m2_utiles", "x": 265, "y": h - 186.60, "width": 40, "height": 14, "value": m2_utiles, "fontName": "Helvetica-Bold"},
            {"name": "m2_construidos", "x": 385, "y": h - 186.60, "width": 85, "height": 14, "value": m2_construidos, "fontName": "Helvetica-Bold"},
            {"name": "otros", "x": 60, "y": h - 201.36, "width": w - 90, "height": 14, "value": otros, "fontName": "Helvetica-Bold"},
            {"name": "owner1", "x": 60, "y": h - 262.0, "width": w - 90, "height": 44, "value": owner1_text.upper(), "multiline": True, "fontSize": 9, "fontName": "Helvetica-Bold"},
            {"name": "owner2", "x": 60, "y": h - 321.3, "width": w - 90, "height": 44, "value": owner2_text.upper(), "multiline": True, "fontSize": 9, "fontName": "Helvetica-Bold"},
            {"name": "cargas", "x": 445, "y": h - 496.85, "width": 130, "height": 14, "value": cargas, "fontName": "Helvetica-Bold"},
            {"name": "precio_venta", "x": 270, "y": h - 511.49, "width": 300, "height": 14, "value": precio, "fontName": "Helvetica-Bold"},
            {"name": "fecha_venta_desde", "x": 466, "y": h - 526.3, "width": 80, "height": 14, "value": fecha_venta_desde, "fontName": "Helvetica-Bold"},
            {"name": "fecha_venta_antes", "x": 198, "y": h - 540.9, "width": 90, "height": 14, "value": fecha_venta_antes, "fontName": "Helvetica-Bold"},
            {"name": "honorarios", "x": 340, "y": h - 599.93, "width": 160, "height": 14, "value": honorarios, "fontName": "Helvetica-Bold"},
            {"name": "fecha_inicio", "x": 270, "y": h - 703.16, "width": 95, "height": 14, "value": fecha_inicio, "fontName": "Helvetica-Bold"},
            {"name": "fecha_fin", "x": 382, "y": h - 703.16, "width": 95, "height": 14, "value": fecha_fin, "fontName": "Helvetica-Bold"},
        ]
        if len(pagesizes) > 1:
            w2, h2 = pagesizes[1]
            fields[1] = [
                {"name": "lugar_firma", "x": 200, "y": h2 - 608.40, "width": 70, "height": 14, "value": lugar_firma, "fontName": "Helvetica-Bold"},
                {"name": "fecha_firma", "x": 270, "y": h2 - 608.40, "width": w2 - 285, "height": 14, "value": fecha_firma, "fontName": "Helvetica-Bold"},
            ]
    else:
        w, h = pagesizes[0]
        o1 = _owner_fields(owner1)
        o2 = _owner_fields(owner2)
        # Coordenadas calculadas sobre plantilla Modernia arrendamiento (letter).
        # Evitamos bloques multilinea en propietarios para que no solapen etiquetas/punteados.
        fields[0] = [
            {"name": "direccion", "x": 106, "y": 355, "width": w - 135, "height": 12, "value": direccion_full, "fontSize": 9},
            {"name": "datos_registrales", "x": 148, "y": 343, "width": 360, "height": 12, "value": datos_registrales, "fontSize": 9},
            {"name": "ref_catastral", "x": 150, "y": 331, "width": 200, "height": 12, "value": ref_catastral, "fontSize": 9},
            {"name": "m2_construidos", "x": 430, "y": 331, "width": 55, "height": 12, "value": m2_construidos, "fontSize": 9},
            {"name": "m2_utiles", "x": 514, "y": 331, "width": 55, "height": 12, "value": m2_utiles, "fontSize": 9},
            {"name": "otros", "x": 100, "y": 319, "width": w - 135, "height": 12, "value": otros, "fontSize": 9},
            # Cláusula 4 (renta mensual)
            {"name": "precio_mensual", "x": 425, "y": 276, "width": 95, "height": 12, "value": precio, "fontSize": 9},
            # Cláusula 5 (plazo)
            {"name": "plazo_arr", "x": 325, "y": 263, "width": 95, "height": 12, "value": plazo, "fontSize": 9},
            # Cláusula 8 (honorarios)
            {"name": "honorarios", "x": 330, "y": 129, "width": 110, "height": 12, "value": honorarios, "fontSize": 9},
            # Propietario 1
            {"name": "owner1_nombre", "x": 120, "y": 653, "width": 410, "height": 12, "value": o1["nombre"], "fontSize": 9},
            {"name": "owner1_ciudad", "x": 210, "y": 639, "width": 170, "height": 12, "value": o1["ciudad"], "fontSize": 9},
            {"name": "owner1_calle", "x": 405, "y": 639, "width": 165, "height": 12, "value": o1["calle"], "fontSize": 9},
            {"name": "owner1_tel", "x": 397, "y": 625, "width": 130, "height": 12, "value": o1["telefono"], "fontSize": 9},
            {"name": "owner1_email", "x": 130, "y": 611, "width": 170, "height": 12, "value": o1["email"], "fontSize": 9},
            {"name": "owner1_nif", "x": 305, "y": 611, "width": 220, "height": 12, "value": o1["nif"], "fontSize": 9},
            # Propietario 2 (opcional)
            {"name": "owner2_nombre", "x": 120, "y": 572, "width": 410, "height": 12, "value": o2["nombre"], "fontSize": 9},
            {"name": "owner2_ciudad", "x": 210, "y": 558, "width": 170, "height": 12, "value": o2["ciudad"], "fontSize": 9},
            {"name": "owner2_calle", "x": 405, "y": 558, "width": 165, "height": 12, "value": o2["calle"], "fontSize": 9},
            {"name": "owner2_tel", "x": 397, "y": 544, "width": 130, "height": 12, "value": o2["telefono"], "fontSize": 9},
            {"name": "owner2_email", "x": 130, "y": 531, "width": 170, "height": 12, "value": o2["email"], "fontSize": 9},
            {"name": "owner2_nif", "x": 305, "y": 531, "width": 220, "height": 12, "value": o2["nif"], "fontSize": 9},
        ]

    overlay_bytes = _build_acroform_overlay_pdf(pagesizes, fields)
    if not overlay_bytes:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    merged = _merge_template_with_overlay_acroform(template_bytes, overlay_bytes)
    if not merged:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    return _pdf_fix_acroform_preview_overlap(merged)


def build_inmueble_nota_encargo_pdf_final(company, inmueble, captacion, owners, extra=None):
    """
    Nota de encargo basada en PDF plantilla (Modernia) pero "plana" (no editable).
    Fallback: documento PDF simple si faltan dependencias/plantilla.
    """
    extra = extra or {}
    owners = owners or []

    def normalize_tipo_operacion(value):
        raw = str(value or "").strip().lower()
        if raw in {"alquiler", "arrendamiento", "renta"}:
            return "alquiler"
        return "venta"

    tipo_operacion = normalize_tipo_operacion(extra.get("tipo_operacion") or extra.get("tipo"))
    template_path = INMO_NOTA_ENCARGO_ALQUILER_TEMPLATE if tipo_operacion == "alquiler" else INMO_NOTA_ENCARGO_VENTA_TEMPLATE
    if not template_path.exists():
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    if rl_canvas is None or PdfReader is None:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    try:
        template_bytes = template_path.read_bytes()
        reader = PdfReader(BytesIO(template_bytes))
    except Exception:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)

    pagesizes = []
    for page in reader.pages:
        try:
            pagesizes.append((float(page.mediabox.width), float(page.mediabox.height)))
        except Exception:
            pagesizes.append((595.0, 842.0))

    direccion = _pdf_form_value(inmueble.get("direccion"))
    cp = _pdf_form_value(inmueble.get("codigo_postal"), "")
    poblacion = _pdf_form_value(inmueble.get("poblacion"), "")
    provincia = _pdf_form_value(inmueble.get("provincia"), "")
    locality = " ".join([p for p in [cp, poblacion] if p]).strip()
    provincia_clean = provincia
    if provincia_clean and poblacion and provincia_clean.strip().lower() == poblacion.strip().lower():
        provincia_clean = ""
    direccion_full = ", ".join([part for part in [direccion, locality, provincia_clean] if part]).strip() or direccion

    def _style_value(value):
        raw = _pdf_form_value(value, "")
        return raw.upper() if raw else raw

    direccion_full = _style_value(direccion_full)
    ref_catastral = _style_value(inmueble.get("referencia_catastral"))
    datos_registrales = _style_value(extra.get("datos_registrales"))
    m2_construidos = _style_value(inmueble.get("m2"))
    m2_utiles = _style_value(extra.get("m2_utiles"))
    otros = _style_value(extra.get("otros"))
    cargas = _style_value(extra.get("cargas") or "NADA")

    owner1 = owners[0] if len(owners) > 0 else {}
    owner2 = owners[1] if len(owners) > 1 else {}

    def owner_block(owner):
        if not owner:
            return ""
        parts = []
        nombre = _style_value(owner.get("nombre"))
        nif = _style_value(owner.get("nif"))
        dom = _style_value(owner.get("direccion") or owner.get("domicilio"))
        tel = _style_value(owner.get("telefono"))
        email_val = _style_value(owner.get("email"))
        if nombre:
            parts.append(nombre)
        if dom:
            parts.append(dom)
        meta_bits = []
        if nif:
            meta_bits.append(f"NIF: {nif}")
        if tel:
            meta_bits.append(f"Tel: {tel}")
        if email_val:
            meta_bits.append(f"Email: {email_val}")
        if meta_bits:
            parts.append(" · ".join(meta_bits))
        return "\n".join(parts[:3])

    owner1_text = owner_block(owner1)
    owner2_text = owner_block(owner2)

    def _normalize_owner_city(owner):
        owner = owner or {}
        for key in ("poblacion", "localidad", "ciudad", "municipio"):
            val = str(owner.get(key) or "").strip()
            if val:
                return val
        return ""

    def _normalize_owner_street(owner, city_hint=""):
        owner = owner or {}
        raw = str(owner.get("direccion") or owner.get("domicilio") or "").replace("\n", " ").strip()
        if not raw:
            return ""
        city_hint = str(city_hint or "").strip()
        if city_hint:
            try:
                if raw.strip().lower().startswith(city_hint.lower()):
                    raw = raw.strip()[len(city_hint) :].lstrip(" ,.-")
            except Exception:
                pass
        if city_hint:
            try:
                raw = re.sub(rf",?\s*{re.escape(city_hint)}\b.*$", "", raw, flags=re.IGNORECASE).strip()
            except Exception:
                pass
        raw = re.sub(r"\b\d{5}\b.*$", "", raw).strip()
        raw = re.sub(r"^\s*(c/|c\.|calle)\s*", "", raw, flags=re.IGNORECASE).strip()
        raw = re.sub(r"^\s*c\s*/\s*", "", raw, flags=re.IGNORECASE).strip()
        raw = re.sub(r"\b\d{5}\b", "", raw).strip()
        if city_hint:
            try:
                raw = re.sub(rf"\b{re.escape(city_hint)}\b", "", raw, flags=re.IGNORECASE).strip(" ,")
            except Exception:
                pass
        return raw.strip(" ,")

    def _owner_fields(owner):
        owner = owner or {}
        has_any = any(
            str(owner.get(k) or "").strip()
            for k in (
                "nombre",
                "nif",
                "telefono",
                "email",
                "direccion",
                "domicilio",
                "poblacion",
                "localidad",
                "ciudad",
                "municipio",
            )
        )
        if not has_any:
            return {"nombre": "", "nif": "", "telefono": "", "email": "", "ciudad": "", "calle": ""}
        nombre = _pdf_form_value(owner.get("nombre"), "")
        nif_val = _pdf_form_value(owner.get("nif"), "")
        tel_val = _pdf_form_value(owner.get("telefono"), "")
        email_val = _pdf_form_value(owner.get("email"), "")
        city = _normalize_owner_city(owner) or str(inmueble.get("poblacion") or "").strip()
        street = _normalize_owner_street(owner, city_hint=city)
        return {
            "nombre": nombre,
            "nif": nif_val,
            "telefono": tel_val,
            "email": email_val,
            "ciudad": city,
            "calle": street,
        }

    if tipo_operacion == "alquiler":
        precio = _style_value(extra.get("renta_mensual") or extra.get("precio_alquiler") or captacion.get("precio_objetivo") or inmueble.get("precio_objetivo"))
        honorarios = _style_value(extra.get("honorarios_mensualidades") or extra.get("honorarios_text"))
        plazo = _style_value(extra.get("plazo_arrendamiento"))
    else:
        precio = _style_value(extra.get("precio_venta") or inmueble.get("precio_encargo") or inmueble.get("precio_objetivo") or captacion.get("precio_objetivo"))
        honorarios = _style_value(extra.get("honorarios_text") or extra.get("honorarios_pct"))
        plazo = ""

    fecha_venta_desde = _style_value(extra.get("fecha_venta_desde"))
    fecha_venta_antes = _style_value(extra.get("fecha_venta_antes"))
    fecha_inicio = _style_value(extra.get("fecha_inicio"))
    fecha_fin = _style_value(extra.get("fecha_fin"))
    lugar_firma = _style_value(extra.get("lugar_firma") or poblacion or provincia)
    fecha_firma = _style_value(extra.get("fecha_firma"))

    fields = {}
    if tipo_operacion == "venta":
        w, h = pagesizes[0]
        fields[0] = [
            {"x": 80, "y": h - 157.08, "width": w - 100, "height": 14, "value": direccion_full},
            {"x": 110, "y": h - 171.84, "width": 310, "height": 14, "value": datos_registrales},
            {"x": 90, "y": h - 186.60, "width": 130, "height": 14, "value": ref_catastral},
            {"x": 265, "y": h - 186.60, "width": 40, "height": 14, "value": m2_utiles},
            {"x": 385, "y": h - 186.60, "width": 85, "height": 14, "value": m2_construidos},
            {"x": 60, "y": h - 201.36, "width": w - 90, "height": 14, "value": otros},
            {"x": 60, "y": h - 262.0, "width": w - 90, "height": 44, "value": owner1_text, "multiline": True, "fontSize": 9, "leading": 11},
            {"x": 60, "y": h - 321.3, "width": w - 90, "height": 44, "value": owner2_text, "multiline": True, "fontSize": 9, "leading": 11},
            {"x": 445, "y": h - 496.85, "width": 130, "height": 14, "value": cargas},
            {"x": 270, "y": h - 511.49, "width": 300, "height": 14, "value": precio},
            {"x": 466, "y": h - 526.3, "width": 80, "height": 14, "value": fecha_venta_desde},
            {"x": 198, "y": h - 540.9, "width": 90, "height": 14, "value": fecha_venta_antes},
            {"x": 340, "y": h - 599.93, "width": 160, "height": 14, "value": honorarios},
            {"x": 270, "y": h - 703.16, "width": 95, "height": 14, "value": fecha_inicio},
            {"x": 382, "y": h - 703.16, "width": 95, "height": 14, "value": fecha_fin},
        ]
        if len(pagesizes) > 1:
            w2, h2 = pagesizes[1]
            fields[1] = [
                {"x": 200, "y": h2 - 608.40, "width": 70, "height": 14, "value": lugar_firma},
                {"x": 270, "y": h2 - 608.40, "width": w2 - 285, "height": 14, "value": fecha_firma},
            ]
    else:
        w, h = pagesizes[0]
        o1 = _owner_fields(owner1)
        o2 = _owner_fields(owner2)
        fields[0] = [
            {"x": 106, "y": 355, "width": w - 135, "height": 12, "value": direccion_full, "fontSize": 9},
            {"x": 148, "y": 343, "width": 360, "height": 12, "value": datos_registrales, "fontSize": 9},
            {"x": 150, "y": 331, "width": 200, "height": 12, "value": ref_catastral, "fontSize": 9},
            {"x": 430, "y": 331, "width": 55, "height": 12, "value": m2_construidos, "fontSize": 9},
            {"x": 514, "y": 331, "width": 55, "height": 12, "value": m2_utiles, "fontSize": 9},
            {"x": 100, "y": 319, "width": w - 135, "height": 12, "value": otros, "fontSize": 9},
            # Cláusula 4 (renta mensual)
            {"x": 425, "y": 276, "width": 95, "height": 12, "value": precio, "fontSize": 9},
            # Cláusula 5 (plazo)
            {"x": 325, "y": 263, "width": 95, "height": 12, "value": plazo, "fontSize": 9},
            # Cláusula 8 (honorarios)
            {"x": 330, "y": 129, "width": 110, "height": 12, "value": honorarios, "fontSize": 9},
            # Propietario 1
            {"x": 120, "y": 653, "width": 410, "height": 12, "value": o1["nombre"], "fontSize": 9},
            {"x": 210, "y": 639, "width": 170, "height": 12, "value": o1["ciudad"], "fontSize": 9},
            {"x": 405, "y": 639, "width": 165, "height": 12, "value": o1["calle"], "fontSize": 9},
            {"x": 397, "y": 625, "width": 130, "height": 12, "value": o1["telefono"], "fontSize": 9},
            {"x": 130, "y": 611, "width": 170, "height": 12, "value": o1["email"], "fontSize": 9},
            {"x": 305, "y": 611, "width": 220, "height": 12, "value": o1["nif"], "fontSize": 9},
            # Propietario 2
            {"x": 120, "y": 572, "width": 410, "height": 12, "value": o2["nombre"], "fontSize": 9},
            {"x": 210, "y": 558, "width": 170, "height": 12, "value": o2["ciudad"], "fontSize": 9},
            {"x": 405, "y": 558, "width": 165, "height": 12, "value": o2["calle"], "fontSize": 9},
            {"x": 397, "y": 544, "width": 130, "height": 12, "value": o2["telefono"], "fontSize": 9},
            {"x": 130, "y": 531, "width": 170, "height": 12, "value": o2["email"], "fontSize": 9},
            {"x": 305, "y": 531, "width": 220, "height": 12, "value": o2["nif"], "fontSize": 9},
        ]

    overlay_bytes = _build_static_text_overlay_pdf(pagesizes, fields, font_name="Helvetica-Bold")
    if not overlay_bytes:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    merged = _merge_template_with_overlay_pdf(template_bytes, overlay_bytes)
    if not merged:
        return build_inmueble_nota_encargo_pdf(company, inmueble, captacion, owners, extra=extra)
    return merged


def build_inmueble_visit_sheet_pdf(company, inmueble, captacion, owners, buyer, demanda=None):
    if rl_canvas is None or rl_colors is None:
        buyer_name = str((buyer or {}).get("nombre") or "").strip() or "-"
        buyer_nif = str((buyer or {}).get("nif") or "").strip() or "-"
        buyer_phone = str((buyer or {}).get("telefono") or "").strip() or "-"
        buyer_email = str((buyer or {}).get("email") or "").strip() or "-"
        sections = [
            (
                "Datos del inmueble",
                [
                    ("Fecha emisión", format_export_date(datetime.now(timezone.utc).date().isoformat())),
                    ("Dirección", inmueble.get("direccion") or "-"),
                    ("Población / provincia", " · ".join([part for part in [inmueble.get("poblacion"), inmueble.get("provincia")] if part]) or "-"),
                    ("Tipo", inmueble.get("tipo_inmueble") or "-"),
                    ("Estado comercial", captacion.get("situacion_comercial") or inmueble.get("estado") or "-"),
                    ("Precio objetivo", format_eur(inmueble.get("precio_objetivo") or captacion.get("precio_objetivo") or 0)),
                ],
            ),
            ("Datos del cliente visitante", [("Nombre", buyer_name), ("DNI / NIF", buyer_nif), ("Teléfono", buyer_phone), ("Email", buyer_email)]),
        ]
        return build_company_branded_document_pdf(
            company,
            "HOJA DE VISITA",
            "Documento comercial de visita vinculado al expediente del inmueble",
            sections,
            [],
        )

    def u(value, fallback=""):
        raw = str(value or "").strip()
        raw = raw if raw else str(fallback or "").strip()
        return raw.upper() if raw else raw

    def _fit_text(canvas, text, max_width, font_name, font_size):
        raw = str(text or "")
        if not raw:
            return raw
        try:
            if canvas.stringWidth(raw, font_name, font_size) <= max_width:
                return raw
        except Exception:
            return raw
        ell = "…"
        lo, hi = 0, len(raw)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            cand = raw[:mid] + ell
            try:
                ok = canvas.stringWidth(cand, font_name, font_size) <= max_width
            except Exception:
                ok = True
            if ok:
                lo = mid
            else:
                hi = mid - 1
        return (raw[:lo] + ell) if lo > 0 else ell

    def _wrap(canvas, text, max_width, font_name, font_size):
        words = str(text or "").split()
        if not words:
            return [""]
        lines = []
        current = ""
        for w in words:
            candidate = (current + " " + w).strip() if current else w
            try:
                width = canvas.stringWidth(candidate, font_name, font_size)
            except Exception:
                width = len(candidate) * (font_size * 0.55)
            if width <= max_width:
                current = candidate
                continue
            if current:
                lines.append(current)
            current = w
        if current:
            lines.append(current)
        return lines

    company_name = str((company or {}).get("nombre") or "MODERNIA").strip() or "MODERNIA"
    company_cif = str((company or {}).get("cif") or (company or {}).get("nif") or "").strip()
    company_addr = str((company or {}).get("direccion") or "").strip()
    company_phone = str((company or {}).get("telefono") or "").strip()

    buyer = buyer or {}
    buyer_name = u(buyer.get("nombre"), "—")
    buyer_nif = u(buyer.get("nif"), "—")
    buyer_addr = u(buyer.get("direccion") or buyer.get("domicilio") or "")
    buyer_phone = u(buyer.get("telefono") or "")
    buyer_email = u(buyer.get("email") or "")

    direccion = str((inmueble or {}).get("direccion") or "").strip()
    cp = str((inmueble or {}).get("codigo_postal") or "").strip()
    poblacion = str((inmueble or {}).get("poblacion") or "").strip()
    provincia = str((inmueble or {}).get("provincia") or "").strip()
    locality = " ".join([p for p in [cp, poblacion] if p]).strip()
    direccion_full = ", ".join([p for p in [direccion, locality, provincia] if p]).strip() or direccion or "—"

    fecha = format_export_date(datetime.now(timezone.utc).date().isoformat())

    w, h = (595.27, 841.89)  # A4
    margin = 42
    sidebar_w = 16
    accent = rl_colors.HexColor("#C8A24A")
    ink = rl_colors.HexColor("#111827")
    muted = rl_colors.HexColor("#4B5563")
    line = rl_colors.HexColor("#D1D5DB")

    buf = BytesIO()
    c = rl_canvas.Canvas(buf, pagesize=(w, h))

    # Sidebar
    c.setFillColor(accent)
    c.rect(0, 0, sidebar_w, h, stroke=0, fill=1)

    # Header
    c.setFillColor(ink)
    if _company_uses_modernia_pdf_brand(company):
        try:
            from reportlab.lib.utils import ImageReader  # type: ignore
            logo = _load_brand_logo("/assets/grupo_modernia_logo.png", max_width=240)
            if logo:
                img_buf = BytesIO()
                logo.convert("RGBA").save(img_buf, format="PNG")
                img_buf.seek(0)
                c.drawImage(ImageReader(img_buf), margin, h - 66, width=logo.width * 0.45, height=logo.height * 0.45, mask="auto")
        except Exception:
            c.setFont("Helvetica-Bold", 18)
            c.drawString(margin, h - 48, company_name)
    else:
        c.setFont("Helvetica-Bold", 18)
        c.drawString(margin, h - 48, company_name)
    c.setFont("Helvetica", 8)
    header_right = []
    if company_cif:
        header_right.append(f"CIF: {company_cif}")
    if company_addr:
        header_right.append(company_addr)
    if company_phone:
        header_right.append(f"Tel: {company_phone}")
    if header_right:
        ty = h - 42
        for line_txt in header_right[:3]:
            c.drawRightString(w - margin, ty, line_txt)
            ty -= 10

    # Title band
    c.setFillColor(accent)
    c.rect(margin, h - 84, w - margin * 2, 18, stroke=0, fill=1)
    c.setFillColor(rl_colors.white)
    c.setFont("Helvetica-Bold", 10)
    c.drawCentredString(w / 2, h - 80, "HOJA DE VISITA - COMPRAVENTA")

    y = h - 120

    def field_row(label, value, y_row):
        label_font = ("Helvetica-Bold", 9)
        value_font = ("Helvetica-Bold", 9)
        label_x = margin
        value_x = margin + 92
        line_x1 = value_x
        line_x2 = w - margin
        c.setFillColor(ink)
        c.setFont(*label_font)
        c.drawString(label_x, y_row, label)
        c.setStrokeColor(line)
        c.setLineWidth(0.8)
        c.line(line_x1, y_row - 2, line_x2, y_row - 2)
        c.setFillColor(ink)
        c.setFont(*value_font)
        fitted = _fit_text(c, value, (line_x2 - line_x1) - 4, value_font[0], value_font[1])
        c.drawString(value_x + 2, y_row, fitted)

    # Cliente (C1)
    c.setFillColor(muted)
    c.setFont("Helvetica-Bold", 8)
    c.drawString(margin, y + 10, "CLIENTE (C1)")
    field_row("D./Dª:", buyer_name, y)
    y -= 18
    field_row("DNI/NIF:", buyer_nif, y)
    y -= 18
    field_row("DIRECCIÓN:", buyer_addr, y)
    y -= 18
    field_row("TELÉFONO:", buyer_phone, y)
    y -= 18
    field_row("E-MAIL:", buyer_email, y)
    y -= 28

    # Inmueble
    c.setFillColor(muted)
    c.setFont("Helvetica-Bold", 8)
    c.drawString(margin, y + 10, "INMUEBLE VISITADO")
    field_row("DIRECCIÓN:", u(direccion_full), y)
    y -= 26

    # Texto legal (resumen)
    c.setFillColor(ink)
    c.setFont("Helvetica", 9)
    legal = (
        "El cliente declara haber recibido información y haber visitado el inmueble indicado, "
        "con intermediación de la agencia. Cualquier negociación o acuerdo posterior sobre el inmueble "
        "deberá canalizarse a través de la agencia, salvo pacto en contrario por escrito."
    )
    max_w = w - margin * 2
    lines = _wrap(c, legal, max_w, "Helvetica", 9)
    ty = y
    for line_txt in lines:
        c.drawString(margin, ty, line_txt)
        ty -= 12
    y = ty - 12

    # Fecha / lugar / firmas
    c.setFillColor(ink)
    c.setFont("Helvetica", 9)
    c.drawString(margin, y, f"EN {u(poblacion or provincia or '—')}, A {fecha}.")
    y -= 26

    c.setStrokeColor(line)
    c.setLineWidth(0.8)
    col_w = (w - margin * 2 - 24) / 2
    c.line(margin, y, margin + col_w, y)
    c.line(margin + col_w + 24, y, margin + col_w + 24 + col_w, y)
    c.setFillColor(muted)
    c.setFont("Helvetica", 8)
    c.drawString(margin, y - 12, "FIRMA CLIENTE (C1)")
    c.drawString(margin + col_w + 24, y - 12, "FIRMA AGENCIA")

    c.save()
    return buf.getvalue()


