def _load_image_from_bytes(raw_bytes, max_width=520):
    if not raw_bytes:
        return None
    logo = None
    try:
        logo = Image.open(BytesIO(raw_bytes)).convert("RGBA")
    except Exception:
        logo = None
    if logo is None and cairosvg is not None:
        try:
            svg_kwargs = {}
            if max_width and max_width > 0:
                svg_kwargs["output_width"] = int(max_width)
            png_bytes = cairosvg.svg2png(bytestring=raw_bytes, **svg_kwargs)
            logo = Image.open(BytesIO(png_bytes)).convert("RGBA")
        except Exception:
            logo = None
    if logo is None:
        return None
    if logo.width > max_width:
        ratio = max_width / float(logo.width)
        logo = logo.resize((int(logo.width * ratio), int(logo.height * ratio)), Image.LANCZOS)
    return logo


def _load_image_from_path(logo_path, max_width=520):
    if not logo_path or not logo_path.exists():
        return None
    try:
        raw_bytes = logo_path.read_bytes()
    except Exception:
        return None
    return _load_image_from_bytes(raw_bytes, max_width=max_width)


def _load_brand_logo(logo_url=None, max_width=520):
    raw = str(logo_url).strip() if logo_url else ""
    logo_path = None
    logo = None

    if raw:
        if raw.startswith("/assets/"):
            candidate = ASSETS / raw.replace("/assets/", "", 1)
            if candidate.exists():
                logo_path = candidate
                logo = _load_image_from_path(candidate, max_width=max_width)
        elif raw.startswith("assets/"):
            candidate = ROOT / raw
            if candidate.exists():
                logo_path = candidate
                logo = _load_image_from_path(candidate, max_width=max_width)
        else:
            # Permite logos subidos a S3 (solo prefijo company_logos/).
            safe_key = ""
            try:
                if raw.startswith("s3://"):
                    safe_key = _normalize_s3_key(raw[5:])
                elif raw.startswith("/api/s3_redirect") or raw.startswith("/api/s3_url") or raw.startswith("/api/s3_uri"):
                    parsed = urllib.parse.urlparse(raw)
                    key = urllib.parse.parse_qs(parsed.query or "").get("key", [""])[0]
                    safe_key = _normalize_s3_key(key)
                else:
                    parsed = urllib.parse.urlparse(raw)
                    host = str(parsed.hostname or "").lower()
                    if host.endswith("amazonaws.com") and ("s3" in host):
                        safe_key = _normalize_s3_key(urllib.parse.unquote(parsed.path or "").lstrip("/"))
            except Exception:
                safe_key = ""
            if safe_key and safe_key.startswith("company_logos/"):
                raw_bytes, _err = s3_get_object_bytes(safe_key)
                if raw_bytes:
                    logo = _load_image_from_bytes(raw_bytes, max_width=max_width)

    if logo is None:
        if logo_path is None:
            logo_path = ASSETS / "verifika2" / "verifika2_wordmark_check_green_transparent.png"
            if not logo_path.exists():
                logo_path = ASSETS / "verifika2" / "verifika2_wordmark_check_green.png"
        if not logo_path.exists():
            logo = None
        else:
            logo = _load_image_from_path(logo_path, max_width=max_width)
        if logo is None:
            badge_info = _logo_badge_info_from_path(raw)
            if badge_info:
                try:
                    logo = _build_logo_badge_image(
                        badge_info.get("label") or "Logo",
                        color=badge_info.get("color") or "#824c45",
                        short=badge_info.get("short") or "",
                        logo_on_dark=bool(badge_info.get("logo_on_dark")),
                        max_width=max_width,
                    )
                except Exception:
                    logo = None
        if logo is None:
            return None
    return logo


def _load_asset_logo(asset_rel=None, max_width=520):
    raw = str(asset_rel or "").strip().lstrip("/")
    if not raw:
        return None
    candidate = ASSETS / raw
    if not candidate.exists():
        return None
    return _load_image_from_path(candidate, max_width=max_width)


