            def _count(table, where_sql, params):
                try:
                    row = conn.execute(f"SELECT COUNT(*) AS n FROM {table} WHERE {where_sql}", params).fetchone()
                    return int(row_value(row, "n") or row_value(row, 0) or 0)
                except Exception:
                    return 0

