            # Normaliza tipos
            if "activo" in fields:
                try:
                    fields["activo"] = 1 if int(fields["activo"] or 0) else 0
                except Exception:
                    fields["activo"] = 1
            set_parts = []
            values = []
            for k, v in fields.items():
                set_parts.append(f"{k} = ?")
                values.append(v if v is not None else "")
