                ("Bsalazar", "", "B", "Salazar", "Seguros, Inmobiliaria", "Lectura", ws_modernia, "Miembro"),
                ("AMelgar", "", "A", "Melgar", "Gestoría", "Lectura", ws_modernia, "Miembro"),
                ("JBernal", "", "J", "Bernal", "Financiaciones", "Lectura", ws_modernia, "Miembro"),
