                if not dry_run:
                    try:
                        client.put_object(Bucket=bucket, Key=key, Body=pdf_part, ContentType="application/pdf")
                        _s3_grant_key(session, key, conn=conn)
                    except Exception as exc:
                        errors += 1
                        results.append({"nif": nif, "status": "s3_error", "error": str(exc)})
                        continue

                now_local = now
