        if path == "/api/inmueble_signature_public":
            token = _request_token_param(self, params, "token")
            if not token:
                json_response(self, {"error": "token requerido"}, status=400)
                return
            ensure_inmueble_signature_schema(conn)
            row = _signature_request_row_by_token(conn, token)
            if not row:
                json_response(self, {"error": "Solicitud no encontrada"}, status=404)
                return
            data = dict(row)
            expires_dt = _parse_iso_dt_utc(data.get("expires_at"))
            now_value = datetime.now(timezone.utc).isoformat()
            if expires_dt and expires_dt < datetime.now(timezone.utc) and data.get("status") not in {"signed", "rejected", "expired"}:
                conn.execute(
                    "UPDATE inmueble_signature_requests SET status = 'expired', updated_at = datetime(?) WHERE id = ?",
                    (now_value, data["id"]),
                )
                record_signature_event(conn, data["id"], "expired", handler=self, now=now_value)
                conn.commit()
                row = conn.execute("SELECT * FROM inmueble_signature_requests WHERE id = ? LIMIT 1", (data["id"],)).fetchone()
                data = dict(row)
            if str(data.get("status") or "").strip().lower() == "pending" and not str(data.get("opened_at") or "").strip():
                conn.execute(
                    """
                    UPDATE inmueble_signature_requests
                    SET status = 'opened', opened_at = datetime(?), updated_at = datetime(?)
                    WHERE id = ?
                    """,
                    (now_value, now_value, data["id"]),
                )
                record_signature_event(conn, data["id"], "opened", handler=self, now=now_value)
                conn.commit()
                row = conn.execute("SELECT * FROM inmueble_signature_requests WHERE id = ? LIMIT 1", (data["id"],)).fetchone()
            json_response(self, {"ok": True, "request": signature_request_public_payload(row, token=token)})
            return

        if path == "/api/inmueble_signature_document":
            token = _request_token_param(self, params, "token")
            if not token:
                json_response(self, {"error": "token requerido"}, status=400)
                return
            ensure_inmueble_signature_schema(conn)
            row = _signature_request_row_by_token(conn, token)
            if not row:
                json_response(self, {"error": "Solicitud no encontrada"}, status=404)
                return
            data = dict(row)
            if str(data.get("status") or "").strip().lower() in {"rejected", "expired"}:
                json_response(self, {"error": "Solicitud no disponible"}, status=410)
                return
            expires_dt = _parse_iso_dt_utc(data.get("expires_at"))
            if expires_dt and expires_dt < datetime.now(timezone.utc):
                json_response(self, {"error": "Solicitud caducada"}, status=410)
                return
            path_obj = _signature_url_to_local_path(data.get("doc_url"))
            if not path_obj or not path_obj.exists():
                json_response(self, {"error": "Documento no disponible"}, status=404)
                return
            record_signature_event(conn, data["id"], "document_viewed", handler=self, now=datetime.now(timezone.utc).isoformat())
            conn.commit()
            send_file(self, path_obj, filename=str(data.get("doc_nombre") or "documento.pdf"))
            return

        if path == "/api/workspace_portal_facturas_excel":
            token = _request_token_param(self, params, "token")
            if not token:
                json_response(self, {"error": "token requerido"}, status=400)
                return
            portal = conn.execute(
                """
                SELECT id, workspace_id, cliente_id, COALESCE(importador_facturas, 0) AS importador_facturas
                FROM workspace_portal_clientes
                WHERE token = ?
                LIMIT 1
                """,
                (token,),
            ).fetchone()
            if not portal:
                json_response(self, {"error": "portal no encontrado"}, status=404)
                return
            if int(portal["importador_facturas"] or 0) != 1:
                json_response(self, {"error": "Importador Facturas no activo para este portal"}, status=403)
                return
            empresa_ids = fetch_workspace_company_ids(conn, portal["workspace_id"])
            if not empresa_ids:
                json_response(self, {"error": "workspace sin empresa operativa"}, status=400)
                return
            # Filtro opcional por periodo o rango.
            periodo = (params.get("periodo", [""])[0] or "").strip()
            date_from = (params.get("from", [""])[0] or "").strip()
            date_to = (params.get("to", [""])[0] or "").strip()
            if periodo and (not date_from and not date_to):
                match = re.match(r"^([0-9]{4})-([0-9]{2})$", periodo)
                if match:
                    year = int(match.group(1))
                    month = int(match.group(2))
                    try:
                        start = datetime(year, month, 1).date()
                        if month == 12:
                            end = datetime(year + 1, 1, 1).date() - timedelta(days=1)
                        else:
                            end = datetime(year, month + 1, 1).date() - timedelta(days=1)
                        date_from = start.isoformat()
                        date_to = end.isoformat()
                    except Exception:
                        date_from = ""
                        date_to = ""
            where = ["f.cliente_id = ?"]
            values = [portal["cliente_id"]]
            placeholders = ",".join(["?"] * len(empresa_ids))
            where.append(f"f.empresa_id IN ({placeholders})")
            values.extend(list(empresa_ids))
            if date_from:
                where.append("date(COALESCE(NULLIF(f.fecha_emision,''), f.created_at)) >= date(?)")
                values.append(date_from)
            if date_to:
                where.append("date(COALESCE(NULLIF(f.fecha_emision,''), f.created_at)) <= date(?)")
                values.append(date_to)
            rows = conn.execute(
                f"""
                SELECT
                  f.fecha_emision,
                  COALESCE(a.fecha, f.fecha_emision) AS fecha_asiento,
                  f.numero,
                  f.base_imponible,
                  f.iva_pct,
                  f.cuota_iva,
                  f.total,
                  COALESCE(t.nif, '') AS tercero_nif,
                  COALESCE(t.nombre, '') AS tercero_nombre,
                  COALESCE(t.cuenta_contable, '') AS subcuenta,
                  COALESCE((
                    SELECT al.cuenta
                    FROM gestoria_asiento_lineas al
                    WHERE al.asiento_id = a.id
                      AND LOWER(COALESCE(al.descripcion, '')) IN ('gasto', 'ingreso')
                    LIMIT 1
                  ), '') AS subcuenta_gastos_ingresos
                FROM gestoria_facturas f
                LEFT JOIN gestoria_terceros t ON t.id = f.tercero_id
                LEFT JOIN gestoria_asientos a ON a.factura_id = f.id
                WHERE {" AND ".join(where)}
                ORDER BY COALESCE(NULLIF(TRIM(COALESCE(f.fecha_emision,'')),''), f.updated_at, f.created_at) ASC
                """,
                values,
            ).fetchall()
            template_path = ROOT.parent / "templates" / "Plantilla conversor asientos facturas.xlsx"
            try:
                excel_bytes = build_gestoria_facturas_excel(template_path, [dict(r) for r in (rows or [])])
            except Exception as exc:
                json_response(self, {"error": f"No se pudo generar Excel: {str(exc)}"}, status=500)
                return
            filename = "asientos_facturas.xlsx"
            if periodo:
                filename = f"asientos_facturas_{periodo}.xlsx"
            binary_response(
                self,
                excel_bytes,
                content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                filename=filename,
            )
            return

        if path == "/api/workspace_portal_s3_url":
            token = _request_token_param(self, params, "token")
            key = (params.get("key", [""])[0] or "").strip()
            if not token or not key:
                json_response(self, {"error": "token y key requeridos"}, status=400)
                return
            key = _normalize_s3_key(key)
            portal = conn.execute(
                """
                SELECT id, workspace_id
                FROM workspace_portal_clientes
                WHERE token = ?
                LIMIT 1
                """,
                (token,),
            ).fetchone()
            if not portal:
                json_response(self, {"error": "portal no encontrado"}, status=404)
                return
            allowed_prefix = f"portal/{portal['workspace_id']}/{portal['id']}/"
            if not key.startswith(allowed_prefix):
                json_response(self, {"error": "key fuera de alcance del portal"}, status=403)
                return
