        if path == "/api/ocr_job":
            job_id = params.get("id", [""])[0]
            if not job_id:
                json_response(self, {"error": "id requerido"}, status=400)
                return
            try:
                ocr_conn = open_sqlite_conn(self.ocr_db_path, with_row_factory=True)
                self._track_conn(ocr_conn)
                row = ocr_conn.execute(
                    """
                    SELECT id, kind, status, result_json, error, created_at, started_at, finished_at
                    FROM ocr_jobs
                    WHERE id = ?
                    """,
                    (job_id,),
                ).fetchone()
            except Exception as exc:
                # UX/robustez: si la DB de OCR está bloqueada/no disponible, devolvemos 200 con status "queued"
                # para evitar "Failed to fetch / Failed to load resource" en el navegador y permitir backoff.
                json_response(
                    self,
                    {
                        "id": job_id,
                        "kind": "",
                        "status": "queued",
                        "result": None,
                        "error": "OCR temporalmente no disponible",
                        "detail": Handler._safe_exc_detail(exc),
                    },
                    status=200,
                    extra_headers=[("Cache-Control", "no-store")],
                )
                return
            if not row:
                json_response(self, {"error": "job no encontrado"}, status=404)
                return
            result = None
            if row["result_json"]:
                try:
                    result = json.loads(row["result_json"])
                except Exception:
                    result = None
            json_response(
                self,
                {
                    "id": row["id"],
                    "kind": row["kind"],
                    "status": row["status"],
                    "result": result,
                    "error": row["error"],
                    "created_at": row["created_at"],
                    "started_at": row["started_at"],
                    "finished_at": row["finished_at"],
                },
                extra_headers=[("Cache-Control", "no-store")],
            )
            return

