        if path == "/api/seguros_recibos":
            workspace_id = (params.get("workspace_id", [""])[0] or "").strip()
            empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
            seguro_id = params.get("seguro_id", [""])[0]
            cliente_id = params.get("cliente_id", [""])[0]
            q = (params.get("q", [""])[0] or "").strip().lower()
            estado = (params.get("estado", [""])[0] or "").strip().lower()
            date_from = (params.get("from", [""])[0] or "").strip()
            date_to = (params.get("to", [""])[0] or "").strip()
            if workspace_id:
                session = getattr(self, "auth_session", None) or self._current_session()
                ok, err = enforce_workspace_membership(conn, session, workspace_id)
                if not ok:
                    json_response(self, {"error": err or "No autorizado"}, status=403)
                    return
            if not empresa_id and not workspace_id:
                json_response(self, {"error": "workspace_id o empresa_id requerido"}, status=400)
                return
            scope_clause, scope_values = build_service_scope_filter(conn, "seguros_recibos", "r", workspace_id, empresa_id)
            where = [scope_clause]
            values = list(scope_values)
            if seguro_id:
                where.append("r.seguro_id = ?")
                values.append(seguro_id)
            if cliente_id:
                where.append("r.cliente_id = ?")
                values.append(cliente_id)
            if q:
                where.append(
                    "("
                    "LOWER(COALESCE(r.referencia,'')) LIKE ? OR LOWER(COALESCE(r.poliza_numero,'')) LIKE ? "
                    "OR LOWER(COALESCE(r.compania,'')) LIKE ? OR LOWER(COALESCE(r.ramo,'')) LIKE ? "
                    "OR LOWER(COALESCE(c.nombre,'')) LIKE ?"
                    ")"
                )
                like = f"%{q}%"
                values.extend([like, like, like, like, like])
            if estado:
                where.append("LOWER(COALESCE(r.estado,'')) = ?")
                values.append(estado)
            if date_from:
                where.append("DATE(COALESCE(NULLIF(TRIM(COALESCE(r.fecha_emision,'')), ''), r.created_at)) >= DATE(?)")
                values.append(date_from)
            if date_to:
                where.append("DATE(COALESCE(NULLIF(TRIM(COALESCE(r.fecha_emision,'')), ''), r.created_at)) <= DATE(?)")
                values.append(date_to)
            rows = conn.execute(
                f"""
                SELECT
                  r.id, r.empresa_id, r.seguro_id, r.cliente_id,
                  r.referencia, r.poliza_numero, r.compania, r.ramo,
                  r.fecha_emision, r.fecha_vencimiento, r.fecha_cobro, r.estado,
                  r.prima_total, r.comision, r.comision_pct, r.importe_liquidacion,
                  r.notas, r.doc_key, r.doc_url,
                  COALESCE(c.nombre, '') AS cliente,
                  COALESCE(s.produccion, '') AS produccion
                FROM seguros_recibos r
                LEFT JOIN clientes c ON c.id = r.cliente_id
                LEFT JOIN seguros s ON s.id = r.seguro_id
                WHERE {" AND ".join(where)}
                ORDER BY COALESCE(NULLIF(TRIM(COALESCE(r.fecha_emision,'')), ''), r.created_at) DESC
                LIMIT 500
                """,
                values,
            ).fetchall()
            raw_rows = [dict(r) for r in rows]
            reglas = conn.execute(
                """
                SELECT compania, ramo, porcentaje, vigencia_desde, vigencia_hasta, notas
                FROM seguros_comisiones
                """
            ).fetchall()
            reglas_rows = [dict(r) for r in reglas]
            reglas_by_comp = defaultdict(list)
            for rr in reglas_rows:
                key = normalize_company_key(rr.get("compania") or "")
                if not key:
                    continue
                reglas_by_comp[key].append(rr)
            for row in raw_rows:
                compania = row.get("compania") or ""
                comp_key = normalize_company_key(compania)
                candidates = reglas_by_comp.get(comp_key) or []
                pick = pick_seguros_comision_rule(
                    candidates,
                    compania,
                    row.get("ramo") or "",
                    produccion=row.get("produccion") or "",
                    fecha_ref=row.get("fecha_emision") or "",
                )
                if pick:
                    try:
                        prima_num = float(row.get("prima_total") or 0.0)
                    except Exception:
                        prima_num = 0.0
                    expected = round((prima_num * float(pick["pct"])) / 100.0, 2) if prima_num else 0.0
                    row["comision_esperada_pct"] = round(float(pick["pct"]), 6)
                    row["comision_esperada"] = expected
                    row["comision_esperada_source"] = pick.get("source") or ""
                    actual = row.get("comision")
                    if actual is None:
                        row["comision_desviacion"] = None
                    else:
                        try:
                            actual_num = float(actual or 0.0)
                        except Exception:
                            actual_num = 0.0
                        row["comision_desviacion"] = round(actual_num - expected, 2)
                else:
                    row["comision_esperada_pct"] = None
                    row["comision_esperada"] = None
                    row["comision_esperada_source"] = ""
                    row["comision_desviacion"] = None
                row.pop("produccion", None)
            json_response(self, {"rows": raw_rows})
            return

