        if path == "/api/gestoria_docs":
            cliente_id = params.get("cliente_id", [""])[0]
            workspace_id = (params.get("workspace_id", [""])[0] or "").strip()
            empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
            service = (params.get("service", [""])[0] or "").strip().lower()
            limit = params.get("limit", [""])[0]
            if not cliente_id and not empresa_id and not workspace_id:
                json_response(self, {"error": "cliente_id, empresa_id o workspace_id requerido"}, status=400)
                return

            if cliente_id:
                # Enriquecimiento: si hay campañas de renta con doc_key/doc_url, pero el registro `gestoria_docs`
                # quedó con `notas` (ruta local) y sin enlaces públicos, inyectamos el enlace desde la campaña
                # para que el botón "Ver" funcione.
                def renta_ref_id_for_entry(ejercicio: object, entry_id: object) -> str:
                    ejercicio_s = str(ejercicio or "").strip()
                    entry_s = str(entry_id or "").strip()
                    if not entry_s:
                        return ""
                    if entry_s.lower().startswith("renta-"):
                        return entry_s
                    return f"renta-{ejercicio_s}-{entry_s}" if ejercicio_s else entry_s

                renta_doc_by_doc_id = {}
                renta_doc_by_ref_id = {}
                renta_doc_ids = []
                renta_ref_ids = []
                try:
                    cg_row = conn.execute(
                        "SELECT renta_detalles FROM cliente_gestoria WHERE cliente_id = ?",
                        (cliente_id,),
                    ).fetchone()
                    renta_payload = parse_renta_detalles_payload(cg_row["renta_detalles"] if cg_row else "")
                    entries = sanitize_renta_entries(renta_payload.get("entries") or [])
                    for entry in entries:
                        entry_id = str(entry.get("id") or "").strip()
                        ejercicio = str(entry.get("ejercicio") or "").strip()
                        ref_id = renta_ref_id_for_entry(ejercicio, entry_id)
                        if ref_id:
                            renta_ref_ids.append(ref_id.lower())
                        for field in ("doc_borrador_id", "doc_presentada_id"):
                            doc_id = str(entry.get(field) or "").strip()
                            if doc_id:
                                renta_doc_ids.append(doc_id)
                        doc_key = _normalize_doc_key_for_ui(entry.get("doc_key") or "")
                        doc_url = str(entry.get("doc_url") or "").strip()
                        if not doc_key and not _is_public_doc_url(doc_url):
                            continue
                        ref_id = f"renta-{ejercicio}-{entry_id}" if ejercicio and entry_id else ""
                        ref_id = renta_ref_id_for_entry(ejercicio, entry_id)
                        if ref_id:
                            renta_doc_by_ref_id[ref_id.lower()] = (doc_key, doc_url)
                        for field in ("doc_borrador_id", "doc_presentada_id"):
                            doc_id = str(entry.get(field) or "").strip()
                            if doc_id:
                                renta_doc_by_doc_id[doc_id] = (doc_key, doc_url)
                except Exception:
                    renta_doc_by_doc_id = {}
                    renta_doc_by_ref_id = {}
                    renta_doc_ids = []
                    renta_ref_ids = []

                renta_doc_ids = [d for d in dict.fromkeys(renta_doc_ids) if d]
                renta_ref_ids = [r for r in dict.fromkeys(renta_ref_ids) if r]

                where = ["cliente_id = ?"]
                values = [cliente_id]
                if service:
                    if normalize_lookup_text(service) == "GESTORIA":
                        renta_gestoria_filter = gestoria_renta_doc_sql_condition("")
                        gestoria_filter = f"""
                          (
                            LOWER(COALESCE(referencia_tipo, '')) IN ('gestoria', 'gestoría')
                            OR LOWER(COALESCE(tipo, '')) IN ('gestoria', 'gestoría')
                            OR {renta_gestoria_filter}
                          )
                        """
                        # Fallback: incluir documentos de renta referenciados por campañas aunque
                        # estén mal vinculados (cliente_id NULL o referencia_tipo incompleta).
                        doc_ids = []
                        ref_ids = []
                        try:
                            cg_row = conn.execute(
                                "SELECT renta_detalles FROM cliente_gestoria WHERE cliente_id = ?",
                                (cliente_id,),
                            ).fetchone()
                            renta_payload = parse_renta_detalles_payload(cg_row["renta_detalles"] if cg_row else "")
                            entries = sanitize_renta_entries(renta_payload.get("entries") or [])
                            for entry in entries:
                                entry_id = str(entry.get("id") or "").strip()
                                ejercicio = str(entry.get("ejercicio") or "").strip()
                                ref_id = renta_ref_id_for_entry(ejercicio, entry_id)
                                if ref_id:
                                    ref_ids.append(ref_id.lower())
                                for field in ("doc_borrador_id", "doc_presentada_id"):
                                    doc_id = str(entry.get(field) or "").strip()
                                    if doc_id:
                                        doc_ids.append(doc_id)
                        except Exception:
                            doc_ids = []
                            ref_ids = []
                        doc_ids = [d for d in dict.fromkeys(doc_ids) if d]
                        ref_ids = [r for r in dict.fromkeys(ref_ids) if r]
                        extra_clause = ""
                        extra_values = []
                        extra_clause_parts = []
                        if doc_ids:
                            extra_clause_parts.append(f"id IN ({','.join(['?'] * len(doc_ids))})")
                            extra_values.extend(doc_ids)
                        if ref_ids:
                            extra_clause_parts.append(
                                f"LOWER(COALESCE(referencia_id,'')) IN ({','.join(['?'] * len(ref_ids))})"
                            )
                            extra_values.extend(ref_ids)
                        if extra_clause_parts:
                            extra_clause = " OR ".join(extra_clause_parts)
                            where_clause = f"((cliente_id = ? AND {gestoria_filter}) OR ({extra_clause}))"
                            values = [cliente_id, *extra_values]
                            where = [where_clause]
                        else:
                            where.append(gestoria_filter)
                    else:
                        where.append(
                            "(LOWER(COALESCE(referencia_tipo, '')) = ? OR LOWER(COALESCE(tipo, '')) = ?)"
                        )
                        values.extend([service, service])
                else:
                    # Sin filtro de servicio: incluimos también documentos de renta referenciados por campañas
                    # aunque estén mal vinculados (cliente_id NULL).
                    extra_clause_parts = []
                    extra_values = []
                    if renta_doc_ids:
                        extra_clause_parts.append(f"id IN ({','.join(['?'] * len(renta_doc_ids))})")
                        extra_values.extend(renta_doc_ids)
                    if renta_ref_ids:
                        extra_clause_parts.append(f"LOWER(COALESCE(referencia_id,'')) IN ({','.join(['?'] * len(renta_ref_ids))})")
                        extra_values.extend(renta_ref_ids)
                    if extra_clause_parts:
                        extra_clause = " OR ".join(extra_clause_parts)
                        where = [f"(cliente_id = ? OR ({extra_clause}))"]
                        values = [cliente_id, *extra_values]

                where_clause = " AND ".join(where)
                rows = conn.execute(
                    f"""
                    SELECT id, nombre, tipo, fecha, estado, notas, repo_key, doc_key, doc_url,
                           referencia_tipo, referencia_id
                    FROM gestoria_docs
                    WHERE {where_clause}
                    ORDER BY created_at DESC
                    """,
                    values,
                ).fetchall()
                # Deduplicar por id si usamos fallback.
                out = []
                seen = set()
                for r in rows:
                    payload = dict(r)
                    # Sanitiza links: algunos syncs antiguos guardaron rutas locales o "doc_key" placeholder.
                    # Evitamos enseñar botón "Ver" si no hay un enlace abrible desde el navegador.
                    try:
                        rid = str(payload.get("id") or "").strip()
                        ref_id = str(payload.get("referencia_id") or "").strip().lower()
                        injected = renta_doc_by_doc_id.get(rid) or renta_doc_by_ref_id.get(ref_id)
                        if injected:
                            injected_key, injected_url = injected
                            if not payload.get("doc_key") and injected_key:
                                payload["doc_key"] = injected_key
                            if (not _is_public_doc_url(payload.get("doc_url"))) and _is_public_doc_url(injected_url):
                                payload["doc_url"] = injected_url
                    except Exception:
                        pass
                    if not _is_public_doc_url(payload.get("doc_url")):
                        payload["doc_url"] = ""
                    if _looks_like_placeholder_doc_key(payload.get("doc_key")) and not payload.get("doc_url"):
                        payload["doc_key"] = ""
                    rid = str(payload.get("id") or "").strip()
                    if rid and rid in seen:
                        continue
                    if rid:
                        seen.add(rid)
                    out.append(payload)
                json_response(self, {"rows": out})
                return

            limit_clause = "LIMIT 50"
            if limit.isdigit():
                limit_clause = f"LIMIT {int(limit)}"
            # Cache corto para evitar saturar el pool en dashboards que recargan a menudo.
            try:
                limit_key = int(limit) if str(limit or "").isdigit() else 50
            except Exception:
                limit_key = 50
            limit_key = max(1, min(200, int(limit_key)))
            cache_key = (str(workspace_id or "").strip(), str(empresa_id or "").strip(), str(service or "").strip(), int(limit_key))
            now_ts = time.time()
            try:
                with Handler._gestoria_docs_recent_lock:
                    cached = Handler._gestoria_docs_recent_cache.get(cache_key)
                    if cached and float(cached[0] or 0.0) > now_ts:
                        json_response(self, cached[1] or {"rows": []})
                        return
            except Exception:
                pass
            # Service-first: permitir listado por workspace sin empresa explícita.
            scope_clause, scope_values = build_service_scope_filter(conn, "gestoria_docs", "d", workspace_id, empresa_id)
            service_clause = ""
            service_values = []
            if normalize_lookup_text(service) == "GESTORIA":
                renta_gestoria_filter = gestoria_renta_doc_sql_condition("d")
                service_clause = f"""
                  AND (
                    LOWER(COALESCE(d.referencia_tipo, '')) IN ('gestoria', 'gestoría')
                    OR LOWER(COALESCE(d.tipo, '')) IN ('gestoria', 'gestoría')
                    OR {renta_gestoria_filter}
                  )
                """
            elif service:
                service_clause = """
                  AND (
                    LOWER(COALESCE(d.referencia_tipo, '')) = ?
                    OR LOWER(COALESCE(d.tipo, '')) = ?
                  )
                """
                service_values.extend([service, service])
            rows = conn.execute(
                f"""
                SELECT d.id, d.nombre, d.tipo, d.fecha, d.estado, d.notas, d.repo_key,
                       COALESCE(c.nombre, '') AS cliente
                FROM gestoria_docs d
                LEFT JOIN clientes c ON c.id = d.cliente_id
                WHERE {scope_clause}
                {service_clause}
                ORDER BY d.fecha DESC
                {limit_clause}
                """,
                [*scope_values, *service_values],
            ).fetchall()
            payload = {"rows": [dict(r) for r in rows]}
            try:
                with Handler._gestoria_docs_recent_lock:
                    Handler._gestoria_docs_recent_cache[cache_key] = (now_ts + 3.0, payload)
                    if len(Handler._gestoria_docs_recent_cache) > 500:
                        # best-effort cleanup de entradas expiradas
                        for k, (exp, _val) in list(Handler._gestoria_docs_recent_cache.items())[:200]:
                            if float(exp or 0.0) <= now_ts:
                                Handler._gestoria_docs_recent_cache.pop(k, None)
            except Exception:
                pass
            json_response(self, payload)
            return

        if path == "/api/gestoria_contabilidad":
            try:
                workspace_id = (params.get("workspace_id", [""])[0] or "").strip()
                empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
                if workspace_id:
                    session = getattr(self, "auth_session", None) or self._current_session()
                    ok, err = enforce_workspace_membership(conn, session, workspace_id)
                    if not ok:
                        json_response(self, {"error": err or "No autorizado"}, status=403)
                        return
                if not empresa_id and not workspace_id:
                    json_response(self, {"error": "workspace_id o empresa_id requerido"}, status=400)
                    return
                empresa_id_effective = empresa_id
                if not empresa_id_effective:
                    try:
                        empresa_id_effective = get_platform_empresa_id(conn) or ""
                    except Exception:
                        empresa_id_effective = ""
                q = params.get("q", [""])[0].strip()
                limit_raw = (params.get("limit", ["300"])[0] or "300").strip()
                try:
                    limit = int(limit_raw)
                except ValueError:
                    limit = 300
                limit = max(1, min(limit, 1000))
                seguros_only = _bool_param(params, "seguros_only", default=False)
                hipotecas_only = _bool_param(params, "hipotecas_only", default=False)
                want_sync = _bool_param(params, "sync", default=False)
                sync_state = {}
                seguros_sync_state = {}
                # Importante: NO ejecutar sync pesado dentro del request (provoca 502/timeouts).
                if hipotecas_only and (want_sync or _hipotecas_sync_enabled()):
                    try:
                        sync_state = schedule_hipotecas_contabilidad_sync(self.db_path, empresa_id_effective)
                    except Exception:
                        sync_state = {"scheduled": False, "reason": "schedule_failed"}
                if seguros_only and (want_sync or _seguros_sync_enabled()):
                    try:
                        seguros_sync_state = schedule_seguros_contabilidad_sync(self.db_path, empresa_id_effective)
                    except Exception:
                        seguros_sync_state = {"scheduled": False, "reason": "schedule_failed"}

                scope_clause, scope_values = build_service_scope_filter(conn, "gestoria_contabilidad", "gc", workspace_id, empresa_id)
                where = [scope_clause]
                values = list(scope_values)
                if seguros_only:
                    where.append(seguros_contabilidad_where_clause("gc"))
                if hipotecas_only:
                    where.append(hipotecas_contabilidad_where_clause("gc"))
                if q:
                    where.append("(gc.concepto LIKE ? OR c.nombre LIKE ? OR h.cliente LIKE ? OR h.banco LIKE ?)")
                    values.extend([f"%{q}%", f"%{q}%", f"%{q}%", f"%{q}%"])
                where_clause = " AND ".join(where)
                summary = None
                try:
                    summary = conn.execute(
                        f"""
                        SELECT
                          COUNT(*) AS total_rows,
                          SUM(CASE WHEN LOWER(TRIM(COALESCE(gc.tipo, ''))) = 'gasto' THEN COALESCE(gc.importe, 0) ELSE 0 END) AS gastos,
                          SUM(CASE WHEN LOWER(TRIM(COALESCE(gc.tipo, ''))) = 'gasto' THEN 0 ELSE COALESCE(gc.importe, 0) END) AS ingresos
                        FROM gestoria_contabilidad gc
                        LEFT JOIN clientes c ON c.id = gc.cliente_id
                        LEFT JOIN seguros s ON s.id = gc.seguro_id
                        LEFT JOIN hipotecas h ON h.id = gc.hipoteca_id
                        WHERE {where_clause}
                        """,
                        values,
                    ).fetchone()
                except Exception as exc:
                    Handler._record_api_error("/api/gestoria_contabilidad:summary", exc)
                    summary = {"total_rows": 0, "gastos": 0, "ingresos": 0}

                rows = []
                try:
                    rows = conn.execute(
                        f"""
                        SELECT gc.id, gc.fecha, gc.concepto, gc.gestion, gc.tipo, gc.importe, gc.notas,
                               gc.cliente_id, gc.cliente_ids_json, gc.seguro_id, gc.hipoteca_id, s.cliente_id AS seguro_cliente_id,
                               COALESCE(NULLIF(gc.poliza_numero, ''), s.poliza_numero, '') AS poliza_numero,
                               COALESCE(c.nombre, h.cliente, '') AS cliente,
                               COALESCE(h.cliente, '') AS hipoteca_cliente,
                               COALESCE(h.banco, '') AS hipoteca_banco,
                               COALESCE(h.estado, '') AS hipoteca_estado,
                               COALESCE(h.fecha_firma, '') AS hipoteca_fecha_firma
                        FROM gestoria_contabilidad gc
                        LEFT JOIN clientes c ON c.id = gc.cliente_id
                        LEFT JOIN seguros s ON s.id = gc.seguro_id
                        LEFT JOIN hipotecas h ON h.id = gc.hipoteca_id
                        WHERE {where_clause}
                        ORDER BY gc.fecha DESC
                        LIMIT ?
                        """,
                        [*values, limit],
                    ).fetchall()
                except Exception as exc:
                    Handler._record_api_error("/api/gestoria_contabilidad:rows", exc)
                    json_response(self, {"error": "Base de datos ocupada. Reintenta.", "detail": "gestoria_contabilidad_rows_failed"}, status=503)
                    return

                out_rows = []
                for raw in rows:
                    row = dict(raw)
                    seguro_cliente_id = str(row.get("seguro_cliente_id") or "").strip()
                    notas_up = str(row.get("notas") or "").upper()
                    if seguro_cliente_id and notas_up.startswith("AUTO CRM SEGUROS"):
                        assigned = parse_cliente_ids_payload(row.get("cliente_ids_json"))
                        if not assigned and row.get("cliente_id"):
                            assigned = [str(row.get("cliente_id")).strip()]
                        if len(assigned) != 1 or assigned[0] != seguro_cliente_id:
                            row["cliente_id"] = seguro_cliente_id
                            row["cliente_ids_json"] = json.dumps([seguro_cliente_id], ensure_ascii=False)
                    row.pop("seguro_cliente_id", None)
                    out_rows.append(row)

                ingresos = round(parse_money_value(row_value(summary, "ingresos", 0) if summary else 0), 2)
                gastos = round(parse_money_value(row_value(summary, "gastos", 0) if summary else 0), 2)
                total_rows = int(row_value(summary, "total_rows", 0) if summary else 0)
                resultado = round(ingresos - gastos, 2)
                rentabilidad_ratio = round(resultado / gastos, 4) if abs(gastos) >= 0.005 else None
                json_response(
                    self,
                    {
                        "rows": out_rows,
                        "total_rows": total_rows,
                        "summary": {
                            "ingresos": ingresos,
                            "gastos": gastos,
                            "resultado": resultado,
                            "rentabilidad_ratio": rentabilidad_ratio,
                        },
                        "hipotecas_sync": sync_state if hipotecas_only else {},
                        "seguros_sync": seguros_sync_state if seguros_only else {},
                    },
                )
                return
            except Exception as exc:
                Handler._record_api_error("/api/gestoria_contabilidad", exc)
                json_response(self, {"error": "Error interno"}, status=500)
                return

        if path == "/api/gestoria_facturas":
            cliente_id = params.get("cliente_id", [""])[0]
            empresa_id = params.get("empresa_id", [""])[0]
            conciliar = _bool_param(params, "conciliar", default=False)
            if not cliente_id and not empresa_id:
                json_response(self, {"error": "cliente_id o empresa_id requerido"}, status=400)
                return
            where = []
            values = []
            if cliente_id:
                where.append("f.cliente_id = ?")
                values.append(cliente_id)
            if empresa_id:
                where.append("f.empresa_id = ?")
                values.append(empresa_id)
            where_clause = " AND ".join(where) if where else "1=1"
            rows = conn.execute(
                f"""
                SELECT
                  f.id,
                  f.fecha_emision,
                  f.numero,
                  f.tipo,
                  f.total,
                  f.estado_ocr,
                  f.doc_key,
                  COALESCE(t.nombre, '') AS tercero,
                  COALESCE(a.id, '') AS asiento_id,
                  COALESCE(a.fecha, '') AS asiento_fecha,
                  COALESCE(a.referencia, '') AS asiento_referencia,
                  COALESCE(a.concepto, '') AS asiento_concepto,
                  CASE WHEN a.id IS NOT NULL THEN 1 ELSE 0 END AS conciliada
                FROM gestoria_facturas f
                LEFT JOIN gestoria_terceros t ON t.id = f.tercero_id
                LEFT JOIN gestoria_asientos a ON a.factura_id = f.id
                WHERE {where_clause}
                ORDER BY f.created_at DESC
                LIMIT 300
                """,
                values,
            ).fetchall()
            facturas = [dict(r) for r in rows]
            if conciliar and facturas:
                changed = False
                for factura_row in facturas:
                    try:
                        result = reconcile_gestoria_factura_asiento(
                            conn,
                            factura_row,
                            datetime.utcnow().isoformat(),
                            auto_link=True,
                            historico_cerrado=True,
                        )
                        changed = changed or bool(result and result.get("linked"))
                    except Exception:
                        continue
                if changed:
                    try:
                        conn.commit()
                    except Exception:
                        pass
                    rows = conn.execute(
                        f"""
                        SELECT
                          f.id,
                          f.fecha_emision,
                          f.numero,
                          f.tipo,
                          f.total,
                          f.estado_ocr,
                          f.doc_key,
                          COALESCE(t.nombre, '') AS tercero,
                          COALESCE(a.id, '') AS asiento_id,
                          COALESCE(a.fecha, '') AS asiento_fecha,
                          COALESCE(a.referencia, '') AS asiento_referencia,
                          COALESCE(a.concepto, '') AS asiento_concepto,
                          CASE WHEN a.id IS NOT NULL THEN 1 ELSE 0 END AS conciliada
                        FROM gestoria_facturas f
                        LEFT JOIN gestoria_terceros t ON t.id = f.tercero_id
                        LEFT JOIN gestoria_asientos a ON a.factura_id = f.id
                        WHERE {where_clause}
                        ORDER BY f.created_at DESC
                        LIMIT 300
                        """,
                        values,
                    ).fetchall()
                    facturas = [dict(r) for r in rows]
            json_response(self, {"rows": facturas})
            return

        if path == "/api/gestoria_import_lotes":
            empresa_id = params.get("empresa_id", [""])[0]
            workspace_id = params.get("workspace_id", [""])[0]
            cliente_id = params.get("cliente_id", [""])[0]
            empresa_ids = resolve_empresa_ids_for_request(conn, empresa_id=empresa_id, workspace_id=workspace_id)
            if not empresa_ids:
                json_response(self, {"error": "workspace_id o empresa_id requerido"}, status=400)
                return
            placeholders = ",".join(["?"] * len(empresa_ids))
            rows = conn.execute(
                f"""
                SELECT l.id, l.empresa_id, l.cliente_id, l.origen, l.estado, l.periodo,
                       l.carpeta_origen, l.template_path, l.total_documentos, l.total_ok,
                       l.total_revisar, l.total_duplicado, l.total_error,
                       l.valoracion_estado, l.valoracion_json, l.valoracion_notas,
                       l.valoracion_total_asientos, l.valoracion_total_terceros,
                       l.valoracion_total_cuentas, l.valoracion_total_pendientes,
                       l.valoracion_cerrada_at, l.valoracion_cerrada_by,
                       l.notas, l.created_at, l.updated_at, COALESCE(c.nombre, '') AS cliente
                FROM gestoria_import_lotes l
                LEFT JOIN clientes c ON c.id = l.cliente_id
                WHERE l.empresa_id IN ({placeholders})
                  AND (? = '' OR COALESCE(l.cliente_id, '') = ?)
                ORDER BY l.created_at DESC
                LIMIT 200
                """,
                tuple([*empresa_ids, cliente_id, cliente_id]),
            ).fetchall()
            json_response(self, {"rows": [dict(r) for r in rows]})
            return

        if path == "/api/gestoria_import_lote_valoracion":
            lote_id = str(payload.get("lote_id") or "").strip()
            if not lote_id:
                json_response(self, {"error": "lote_id requerido"}, status=400)
                return
            lote = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ? LIMIT 1", (lote_id,)).fetchone()
            if not lote:
                json_response(self, {"error": "lote no encontrado"}, status=404)
                return
            estado = str(payload.get("valoracion_estado") or lote["valoracion_estado"] or "abierta").strip().lower() or "abierta"
            notas = str(payload.get("valoracion_notas") or "").strip() or None
            def _int_field(key, current):
                raw = payload.get(key)
                if raw in (None, ""):
                    return int(current or 0)
                try:
                    return max(0, int(float(raw)))
                except Exception:
                    return int(current or 0)
            total_asientos = _int_field("valoracion_total_asientos", lote["valoracion_total_asientos"])
            total_terceros = _int_field("valoracion_total_terceros", lote["valoracion_total_terceros"])
            total_cuentas = _int_field("valoracion_total_cuentas", lote["valoracion_total_cuentas"])
            total_pendientes = _int_field("valoracion_total_pendientes", lote["valoracion_total_pendientes"])
            current_json = {}
            try:
                current_json = json.loads(lote["valoracion_json"] or "{}") if lote["valoracion_json"] else {}
                if not isinstance(current_json, dict):
                    current_json = {}
            except Exception:
                current_json = {}
            cerrar = _bool_param(payload, "cerrar", default=False)
            cerrada_at = lote["valoracion_cerrada_at"]
            cerrada_by = lote["valoracion_cerrada_by"]
            if cerrar:
                estado = "cerrada"
                cerrada_at = now
                cerrada_by = str((payload.get("valoracion_cerrada_by") or payload.get("usuario") or "").strip()) or None
            current_json.update(
                {
                    "estado": estado,
                    "asientos": total_asientos,
                    "terceros": total_terceros,
                    "cuentas": total_cuentas,
                    "pendientes": total_pendientes,
                    "notas": notas or current_json.get("notas") or "",
                    "cerrada_at": cerrada_at,
                    "cerrada_by": cerrada_by,
                }
            )
            conn.execute(
                """
                UPDATE gestoria_import_lotes
                SET valoracion_estado = ?,
                    valoracion_json = ?,
                    valoracion_notas = ?,
                    valoracion_total_asientos = ?,
                    valoracion_total_terceros = ?,
                    valoracion_total_cuentas = ?,
                    valoracion_total_pendientes = ?,
                    valoracion_cerrada_at = ?,
                    valoracion_cerrada_by = ?,
                    estado = ?,
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    estado,
                    json.dumps(current_json, ensure_ascii=False),
                    notas,
                    total_asientos,
                    total_terceros,
                    total_cuentas,
                    total_pendientes,
                    cerrada_at,
                    cerrada_by,
                    estado,
                    now,
                    lote_id,
                ),
            )
            conn.commit()
            row = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
            json_response(self, {"ok": True, "row": dict(row) if row else {}})
            return

        if path == "/api/gestoria_import_documentos":
            lote_id = params.get("lote_id", [""])[0]
            estado_raw = (params.get("estado", [""])[0] or "").strip()
            estado = normalize_import_review_state(estado_raw) if estado_raw else ""
            if not lote_id:
                json_response(self, {"error": "lote_id requerido"}, status=400)
                return
            values = [lote_id]
            where_estado = ""
            if estado:
                where_estado = " AND d.estado_revision = ?"
                values.append(estado)
            rows = conn.execute(
                f"""
                SELECT d.*, COALESCE(f.numero, '') AS factura_numero,
                       COALESCE(f.fecha_emision, '') AS factura_fecha,
                       COALESCE(f.total, 0) AS factura_total,
                       COALESCE(t.nombre, '') AS tercero_nombre,
                       COALESCE(a.id, '') AS asiento_id,
                       COALESCE(a.fecha, '') AS asiento_fecha,
                       COALESCE(a.referencia, '') AS asiento_referencia,
                       COALESCE(a.concepto, '') AS asiento_concepto,
                       COALESCE(a.diario, '') AS asiento_diario
                FROM gestoria_import_documentos d
                LEFT JOIN gestoria_facturas f ON f.id = d.factura_id
                LEFT JOIN gestoria_terceros t ON t.id = COALESCE(d.tercero_id, f.tercero_id)
                LEFT JOIN gestoria_asientos a ON a.factura_id = f.id
                WHERE d.lote_id = ?
                {where_estado}
                ORDER BY d.fecha_detectada DESC, d.created_at DESC
                LIMIT 500
                """,
                values,
            ).fetchall()
            rows = [dict(r) for r in rows]
            for row in rows:
                row.setdefault("validado_manual_at", "")
                row.setdefault("validado_manual_by", "")
                try:
                    factura_id = str(row.get("factura_id") or "").strip()
                    if factura_id:
                        factura_row = conn.execute(
                            """
                            SELECT
                              f.*,
                              COALESCE(t.nombre, '') AS tercero_nombre,
                              COALESCE(t.nif, '') AS tercero_nif,
                              COALESCE(t.cuenta_contable, '') AS tercero_cuenta
                            FROM gestoria_facturas f
                            LEFT JOIN gestoria_terceros t ON t.id = f.tercero_id
                            WHERE f.id = ?
                            LIMIT 1
                            """,
                            (factura_id,),
                        ).fetchone()
                        if factura_row:
                            result = reconcile_gestoria_factura_asiento(
                                conn,
                                dict(factura_row),
                                now,
                                auto_link=False,
                                historico_cerrado=True,
                            )
                            row["compatibilidad_pct"] = max(0, min(100, int(round(float(result.get("score") or 0)))))
                            row["compatibilidad_estado"] = str(result.get("reason") or "").strip() or ("matched" if result.get("matched") else "pendiente")
                            row["asiento_id"] = result.get("asiento_id") or row.get("asiento_id") or ""
                            row["asiento_fecha"] = result.get("asiento_fecha") or row.get("asiento_fecha") or ""
                            row["asiento_referencia"] = result.get("asiento_referencia") or row.get("asiento_referencia") or ""
                            row["asiento_concepto"] = result.get("asiento_concepto") or row.get("asiento_concepto") or ""
                        else:
                            row["compatibilidad_pct"] = 0
                            row["compatibilidad_estado"] = "sin_factura"
                    else:
                        row["compatibilidad_pct"] = 0
                        row["compatibilidad_estado"] = "pendiente"
                except Exception:
                    row["compatibilidad_pct"] = 0
                    row["compatibilidad_estado"] = "error"
            summary = conn.execute(
                """
                SELECT
                  COUNT(*) AS total_documentos,
                  SUM(CASE WHEN estado_revision = 'OK' THEN 1 ELSE 0 END) AS total_ok,
                  SUM(CASE WHEN estado_revision = 'REVISAR' THEN 1 ELSE 0 END) AS total_revisar,
                  SUM(CASE WHEN estado_revision = 'DUPLICADO' THEN 1 ELSE 0 END) AS total_duplicado,
                  SUM(CASE WHEN estado_revision = 'ERROR' THEN 1 ELSE 0 END) AS total_error
                FROM gestoria_import_documentos
                WHERE lote_id = ?
                """,
                (lote_id,),
            ).fetchone()
            json_response(
                self,
                {
                    "rows": rows,
                    "summary": {
                        "total_documentos": int(summary["total_documentos"] or 0) if summary else 0,
                        "total_ok": int(summary["total_ok"] or 0) if summary else 0,
                        "total_revisar": int(summary["total_revisar"] or 0) if summary else 0,
                        "total_duplicado": int(summary["total_duplicado"] or 0) if summary else 0,
                        "total_error": int(summary["total_error"] or 0) if summary else 0,
                    },
                },
            )
            return

        if path == "/api/gestoria_import_excel":
            lote_id = params.get("lote_id", [""])[0]
            if not lote_id:
                json_response(self, {"error": "lote_id requerido"}, status=400)
                return
            if not OPENPYXL_AVAILABLE:
                json_response(self, {"error": "openpyxl no disponible en servidor"}, status=500)
                return
            lote = conn.execute(
                """
                SELECT l.*, COALESCE(c.nombre, '') AS cliente
                FROM gestoria_import_lotes l
                LEFT JOIN clientes c ON c.id = l.cliente_id
                WHERE l.id = ?
                LIMIT 1
                """,
                (lote_id,),
            ).fetchone()
            if not lote:
                json_response(self, {"error": "lote no encontrado"}, status=404)
                return
            try:
                session_tmp = getattr(self, "auth_session", None) or self._current_session()
                if session_tmp and not workspace_actor_is_privileged(conn, session_tmp):
                    ok, err = enforce_empresa_membership(conn, session_tmp, str(lote["empresa_id"] or ""), write=False)
                    if not ok:
                        json_response(self, {"error": err or "No autorizado"}, status=403)
                        return
            except Exception:
                pass
            docs = conn.execute(
                """
                SELECT *
                FROM gestoria_import_documentos
                WHERE lote_id = ? AND estado_revision = 'OK'
                ORDER BY fecha_detectada ASC, created_at ASC
                """,
                (lote_id,),
            ).fetchall()
            wb = load_workbook(GESTORIA_EXCEL_TEMPLATE) if GESTORIA_EXCEL_TEMPLATE.exists() else Workbook()
            ws = wb["Hoja1"] if "Hoja1" in wb.sheetnames else wb.active
            ws.title = "Hoja1"
            if ws.max_row < 1:
                headers = [
                    "FECHA ASIENTO",
                    "FECHA FACTURA",
                    "Nº FACTURA",
                    "CONCEPTO",
                    "SUBCUENTA",
                    "NIF",
                    "NOMBRE",
                    "DOMICILIO",
                    "LOCALIDAD",
                    "PROVINCIA",
                    "CODIGO POSTAL",
                    "BASE IMPONIBLE",
                    "% IVA",
                    "IMPORTE IVA",
                    "SUBCUENTA GASTOS/INGRESOS",
                    "IMPORTE (TOTAL)",
                ]
                ws.append(headers)
                ws.append([None] * 16)
            style_row_idx = 2
            style_cells = [ws.cell(style_row_idx, col) for col in range(1, 17)]
            for row_idx in range(2, max(ws.max_row, style_row_idx) + 1):
                for col in range(1, 17):
                    ws.cell(row_idx, col).value = None
            for offset, doc in enumerate(docs, start=0):
                row_idx = 2 + offset
                for col in range(1, 17):
                    target = ws.cell(row_idx, col)
                    source = style_cells[col - 1]
                    target._style = shallow_copy(source._style)
                    target.number_format = source.number_format
                    target.protection = shallow_copy(source.protection)
                    target.alignment = shallow_copy(source.alignment)
                    target.font = shallow_copy(source.font)
                    target.fill = shallow_copy(source.fill)
                    target.border = shallow_copy(source.border)
                tipo = normalize_service_key(doc["tipo_detectado"] or "")
                base = round(parse_money_value(doc["base_detectada"]), 2)
                iva = round(parse_money_value(doc["cuota_iva_detectada"]), 2)
                total = round(parse_money_value(doc["total_detectado"]), 2)
                iva_pct = round((iva / base) * 100.0, 2) if base and iva else ""
                subcuenta_tercero = "430000000" if tipo == "venta" else "400000000"
                subcuenta_gi = "700000000" if tipo == "venta" else str(doc["cuenta_sugerida"] or "629000000")
                ws.cell(row_idx, 1).value = doc["fecha_detectada"] or ""
                ws.cell(row_idx, 2).value = doc["fecha_detectada"] or ""
                ws.cell(row_idx, 3).value = doc["numero_detectado"] or ""
                ws.cell(row_idx, 4).value = f'=CONCATENATE(C{row_idx}," ",G{row_idx})'
                ws.cell(row_idx, 5).value = subcuenta_tercero
                ws.cell(row_idx, 6).value = doc["nif_detectado"] or ""
                ws.cell(row_idx, 7).value = doc["tercero_detectado"] or ""
                ws.cell(row_idx, 12).value = base if base else ""
                ws.cell(row_idx, 13).value = iva_pct
                ws.cell(row_idx, 14).value = iva if iva else ""
                ws.cell(row_idx, 15).value = subcuenta_gi
                ws.cell(row_idx, 16).value = total if total else ""
            bio = BytesIO()
            wb.save(bio)
            payload = bio.getvalue()
            cliente_slug = re.sub(r"[^A-Za-z0-9]+", "_", str(lote["cliente"] or "cliente")).strip("_") or "cliente"
            periodo_slug = re.sub(r"[^A-Za-z0-9]+", "_", str(lote["periodo"] or "lote")).strip("_") or "lote"
            filename = f"miconversor_{cliente_slug}_{periodo_slug}.xlsx"
            self.send_response(200)
            self.send_header("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
            self.send_header("Content-Length", str(len(payload)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(payload)
            return

