        if path == "/api/inmueble_timeline":
            inmueble_id = params.get("inmueble_id", [""])[0]
            if not inmueble_id:
                json_response(self, {"error": "inmueble_id requerido"}, status=400)
                return
            try:
                cap_row = conn.execute(
                    "SELECT id FROM captaciones WHERE inmueble_id = ? LIMIT 1",
                    (inmueble_id,),
                ).fetchone()
                captacion_id = str(row_value(cap_row, "id", "") or "").strip()
            except Exception:
                captacion_id = ""
            try:
                ensure_crm_stage_events_schema(conn)
                stage_rows = conn.execute(
                    """
                    SELECT id, from_etapa, to_etapa, usuario, responsable, created_at
                    FROM crm_stage_events
                    WHERE inmueble_id = ?
                    ORDER BY created_at DESC
                    LIMIT 120
                    """,
                    (inmueble_id,),
                ).fetchall()
            except Exception:
                stage_rows = []
            oper_rows = conn.execute(
                """
                SELECT
                  id,
                  tipo_operacion,
                  estado,
                  fecha_encargo,
                  fecha_propuesta,
                  fecha_contrato,
                  fecha_escritura,
                  fecha_operacion,
                  precio_encargo,
                  precio_propuesta,
                  precio_contrato,
                  precio_escritura,
                  precio_renta,
                  created_at,
                  updated_at
                FROM operaciones_inmobiliarias
                WHERE inmueble_id = ?
                ORDER BY COALESCE(NULLIF(fecha_escritura, ''), NULLIF(fecha_operacion, ''), updated_at, created_at) DESC
                LIMIT 50
                """,
                (inmueble_id,),
            ).fetchall()
            docs_rows = conn.execute(
                """
                SELECT id, nombre, tipo, estado, version, url, created_at, updated_at
                FROM inmueble_docs
                WHERE inmueble_id = ?
                """,
                (inmueble_id,),
            ).fetchall()
            action_rows = conn.execute(
                """
                SELECT id, tipo, estado, resultado_cierre, responsable, fecha, hora, created_at, updated_at
                FROM acciones
                WHERE inmueble_id = ?
                """,
                (inmueble_id,),
            ).fetchall()
            audit_rows = conn.execute(
                """
                SELECT id, entidad, entidad_id, accion, usuario, detalles, created_at
                FROM auditoria
                WHERE (entidad = 'inmueble' AND entidad_id = ?)
                   OR (entidad = 'captacion' AND entidad_id = ?)
                   OR (entidad = 'accion' AND entidad_id IN (SELECT id FROM acciones WHERE inmueble_id = ?))
                   OR (entidad = 'inmueble_docs' AND entidad_id IN (SELECT id FROM inmueble_docs WHERE inmueble_id = ?))
                ORDER BY created_at DESC
                LIMIT 200
                """,
                (inmueble_id, captacion_id, inmueble_id, inmueble_id),
            ).fetchall()
            items = []
            for row in stage_rows:
                try:
                    from_etapa = row.get("from_etapa") if isinstance(row, dict) else row["from_etapa"]
                except Exception:
                    from_etapa = ""
                try:
                    to_etapa = row.get("to_etapa") if isinstance(row, dict) else row["to_etapa"]
                except Exception:
                    to_etapa = ""
                try:
                    created_at = row.get("created_at") if isinstance(row, dict) else row["created_at"]
                except Exception:
                    created_at = ""
                try:
                    usuario = row.get("usuario") if isinstance(row, dict) else row["usuario"]
                except Exception:
                    usuario = ""
                try:
                    responsable = row.get("responsable") if isinstance(row, dict) else row["responsable"]
                except Exception:
                    responsable = ""
                items.append(
                    {
                        "kind": "transicion",
                        "id": row["id"] if not isinstance(row, dict) else row.get("id"),
                        "title": "Transición etapa",
                        "status": to_etapa or "",
                        "meta": {"from": from_etapa, "to": to_etapa, "usuario": usuario, "responsable": responsable},
                        "date": created_at,
                    }
                )
            for row in oper_rows:
                try:
                    tipo_op = str(row.get("tipo_operacion") or row["tipo_operacion"] or "").strip().lower()
                except Exception:
                    tipo_op = ""
                label = "Compraventa" if tipo_op != "alquiler" else "Alquiler"
                try:
                    fecha = (
                        row.get("fecha_escritura")
                        or row.get("fecha_operacion")
                        or row.get("fecha_contrato")
                        or row.get("fecha_propuesta")
                        or row.get("fecha_encargo")
                        or ""
                    )
                except Exception:
                    try:
                        fecha = row["fecha_escritura"] or row["fecha_operacion"] or row["fecha_contrato"] or row["fecha_propuesta"] or row["fecha_encargo"] or ""
                    except Exception:
                        fecha = ""
                try:
                    precio = row.get("precio_escritura") or row.get("precio_contrato") or row.get("precio_propuesta") or row.get("precio_renta") or row.get("precio_encargo")
                except Exception:
                    try:
                        precio = row["precio_escritura"] or row["precio_contrato"] or row["precio_propuesta"] or row["precio_renta"] or row["precio_encargo"]
                    except Exception:
                        precio = None
                items.append(
                    {
                        "kind": "operacion",
                        "id": row["id"],
                        "title": f"{label} (histórico)",
                        "status": row["estado"] or "Histórico",
                        "meta": {"responsable": "Histórico", "resultado": f"{fecha} · {precio}" if (fecha or precio) else ""},
                        "date": row["updated_at"] or row["created_at"] or fecha,
                    }
                )
            for row in docs_rows:
                items.append({
                    "kind": "documento",
                    "id": row["id"],
                    "title": row["nombre"] or row["tipo"] or "Documento",
                    "status": row["estado"] or "Vigente",
                    "meta": {"tipo": row["tipo"], "version": row["version"], "url": row["url"]},
                    "date": row["created_at"] or row["updated_at"],
                })
            for row in action_rows:
                items.append({
                    "kind": "accion",
                    "id": row["id"],
                    "title": row["tipo"] or "Acción",
                    "status": row["estado"] or "Pendiente",
                    "meta": {"resultado": row["resultado_cierre"], "responsable": row["responsable"], "fecha": row["fecha"], "hora": row["hora"]},
                    "date": row["updated_at"] or row["created_at"],
                })
            for row in audit_rows:
                accion = str(row["accion"] or "").strip()
                detalles_raw = row["detalles"]
                if accion == "Cambio campo":
                    parsed = None
                    if isinstance(detalles_raw, str) and detalles_raw and detalles_raw.strip().startswith(("{", "[")):
                        try:
                            parsed = json.loads(detalles_raw)
                        except Exception:
                            parsed = None
                    if isinstance(parsed, dict):
                        field_name = str(parsed.get("campo") or "").strip()
                        items.append(
                            {
                                "kind": "campo",
                                "id": row["id"],
                                "title": field_name or "Cambio campo",
                                "status": str(parsed.get("origen") or "inmueble"),
                                "meta": {
                                    "field": field_name,
                                    "from": parsed.get("from"),
                                    "to": parsed.get("to"),
                                    "usuario": row["usuario"],
                                },
                                "date": row["created_at"],
                            }
                        )
                    else:
                        items.append(
                            {
                                "kind": "campo",
                                "id": row["id"],
                                "title": "Cambio campo",
                                "status": row["entidad"] or "",
                                "meta": {"usuario": row["usuario"], "detalles": detalles_raw, "entidad_id": row["entidad_id"]},
                                "date": row["created_at"],
                            }
                        )
                    continue
                if accion == "Transición etapa":
                    continue
                items.append(
                    {
                        "kind": "auditoria",
                        "id": row["id"],
                        "title": accion or "Evento",
                        "status": row["entidad"] or "",
                        "meta": {"usuario": row["usuario"], "detalles": detalles_raw, "entidad_id": row["entidad_id"]},
                        "date": row["created_at"],
                    }
                )
            items.sort(key=lambda item: str(item.get("date") or ""), reverse=True)
            json_response(self, {"rows": items[:250]})
            return

        if path == "/api/demandas":
            workspace_id = (params.get("workspace_id", [""])[0] or "").strip()
            empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
            d_cols = table_columns(conn, "demandas") or set()
            where = []
            values = []
