        if path == "/api/hipoteca_stats":
            workspace_id = (params.get("workspace_id", [""])[0] or "").strip()
            empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
            if workspace_id:
                session = getattr(self, "auth_session", None) or self._current_session()
                ok, err = enforce_workspace_membership(conn, session, workspace_id)
                if not ok:
                    json_response(self, {"error": err or "No autorizado"}, status=403)
                    return
            if not empresa_id and not workspace_id:
                json_response(self, {"error": "workspace_id o empresa_id requerido"}, status=400)
                return
            closed_expr = "LOWER(TRIM(COALESCE(estado, ''))) IN ('firmado', 'firmada', 'indemnización', 'indemnizacion')"
            signed_expr = "fecha_firma IS NOT NULL AND TRIM(fecha_firma) <> ''"
            scope_clause, scope_values = build_service_scope_filter(conn, "hipotecas", "h", workspace_id, empresa_id)

            total = conn.execute(
                f"SELECT COUNT(*) AS total FROM hipotecas h WHERE {scope_clause}",
                scope_values,
            ).fetchone()

            firmadas_mes = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas h
                WHERE """
                + scope_clause
                + """
                  AND """
                + signed_expr
                + """
                  AND """
                + closed_expr
                + """
                  AND fecha_firma IS NOT NULL
                  AND length(fecha_firma) >= 7
                  AND substr(NULLIF(fecha_firma, ''), 1, 7) = substr(datetime('now','localtime'), 1, 7)
                """,
                scope_values,
            ).fetchone()

            averages = conn.execute(
                """
                SELECT
                  AVG(
                    CASE
                      WHEN precio IS NOT NULL AND precio > 0 AND importe_hipoteca IS NOT NULL
                        THEN (importe_hipoteca * 100.0 / precio)
                      WHEN porcentaje IS NOT NULL AND porcentaje > 0 AND porcentaje <= 1 THEN porcentaje * 100.0
                      WHEN porcentaje IS NOT NULL AND porcentaje > 1 THEN porcentaje
                      ELSE NULL
                    END
                  ) AS porcentaje_medio,
                  AVG(COALESCE(comision, 0)) AS comision_media
                FROM hipotecas h
                WHERE """
                + scope_clause
                + """
                  AND """
                + signed_expr
                + """
                  AND """
                + closed_expr
                + """
                """,
                scope_values,
            ).fetchone()

            json_response(
                self,
                {
                    "total": total["total"] if total else 0,
                    "firmadas_mes": firmadas_mes["total"] if firmadas_mes else 0,
                    "porcentaje_medio": averages["porcentaje_medio"] if averages else 0,
                    "comision_media": averages["comision_media"] if averages else 0,
                },
            )
            return

        if path == "/api/hipoteca_dashboard":
            empresa_id = params.get("empresa_id", [""])[0]
            workspace_id = params.get("workspace_id", [""])[0]
            requested_year = (params.get("year", [""])[0] or "").strip()
            if not empresa_id and workspace_id:
                empresa_ids = resolve_empresa_ids_for_request(conn, empresa_id=empresa_id, workspace_id=workspace_id)
                if empresa_ids:
                    # Compat: dashboard legacy funciona por empresa. En modo workspace usamos la primera para no bloquear.
                    empresa_id = empresa_ids[0]
            if not empresa_id:
                json_response(self, {"error": "empresa_id o workspace_id requerido"}, status=400)
                return
            now_ts = time.time()
            cache_key = (
                str(empresa_id or "").strip(),
                requested_year if (requested_year.isdigit() and len(requested_year) == 4) else "",
            )
            cached_payload = None
            try:
                with Handler._hipoteca_dashboard_lock:
                    cached = Handler._hipoteca_dashboard_cache.get(cache_key)
                    if cached and isinstance(cached[1], dict):
                        # TTL corto: evita avalancha de queries si el front reintenta por 502/503.
                        if cached[0] > now_ts:
                            json_response(self, cached[1])
                            return
                        cached_payload = cached[1]
            except Exception:
                cached_payload = None
            # No ejecutes sync pesado dentro del request: puede tardar mucho y provocar 502/timeouts.
            try:
                sync_state = schedule_hipotecas_contabilidad_sync(self.db_path, empresa_id)
            except Exception:
                sync_state = {"scheduled": False, "reason": "schedule_failed"}

            # Evita depender de funciones SQLite (strftime/datetime) en Postgres: además, algunos valores de fecha
            # pueden venir como DD/MM/YYYY. Extraemos año/mes de forma robusta con substr/LIKE.
            current_year = str(datetime.now().year)
            current_month = datetime.now().strftime("%Y-%m")

            def _year_from_expr(expr):
                value = f"TRIM(COALESCE({expr}, ''))"
                head = f"substr({value}, 1, 10)"
                return (
                    "CASE "
                    f"WHEN {head} LIKE '____-__-__' THEN substr({head}, 1, 4) "
                    f"WHEN {head} LIKE '__/__/____' THEN substr({head}, 7, 4) "
                    "ELSE NULL END"
                )

            def _month_from_expr(expr):
                value = f"TRIM(COALESCE({expr}, ''))"
                head = f"substr({value}, 1, 10)"
                return (
                    "CASE "
                    f"WHEN {head} LIKE '____-__-__' THEN substr({head}, 1, 7) "
                    f"WHEN {head} LIKE '__/__/____' THEN substr({head}, 7, 4) || '-' || substr({head}, 4, 2) "
                    "ELSE NULL END"
                )

            fallback_date_expr = "COALESCE(NULLIF(fecha_firma, ''), NULLIF(fecha_encargo, ''), created_at)"
            computed_year_expr = _year_from_expr(fallback_date_expr)
            year_expr = (
                "COALESCE("
                "NULLIF(TRIM(COALESCE(CAST(anio AS TEXT), '')), ''), "
                + computed_year_expr
                + ")"
            )
            signed_year_expr = _year_from_expr("NULLIF(fecha_firma, '')")
            signed_month_expr = _month_from_expr("NULLIF(fecha_firma, '')")
            closed_expr = "LOWER(TRIM(COALESCE(estado, ''))) IN ('firmado', 'firmada', 'indemnización', 'indemnizacion')"
            signed_expr = "fecha_firma IS NOT NULL AND TRIM(fecha_firma) <> ''"
            signed_closed_expr = (
                "LOWER(TRIM(COALESCE(estado, ''))) IN ('firmado', 'firmada', 'indemnización', 'indemnizacion')"
                " AND fecha_firma IS NOT NULL AND TRIM(fecha_firma) <> ''"
            )
            # Encargo: solo hipotecas en estado "Encargo" (no el check/campo `encargo`).
            encargo_expr = "LOWER(TRIM(COALESCE(estado, ''))) IN ('encargo', 'encargado', 'encargada')"
            estudio_expr = encargo_expr
            descartada_expr = "LOWER(TRIM(COALESCE(estado, ''))) IN ('rechazado', 'rechazada', 'cancelado', 'cancelada', 'anulado', 'anulada')"
            # Pendientes de firma: no firmadas/indemnización y no descartadas.
            pendientes_firma_expr = f"NOT ({closed_expr}) AND NOT ({descartada_expr})"

            # julianday() existe en SQLite pero NO en Postgres.
            if db_is_postgres_enabled():

                def _pg_date_expr(field):
                    value = f"TRIM(COALESCE({field}, ''))"
                    head = f"substr({value}, 1, 10)"
                    iso_ok = (
                        f"{head} ~ '^[0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}}$'"
                        f" AND substr({head}, 6, 2) BETWEEN '01' AND '12'"
                        f" AND substr({head}, 9, 2) BETWEEN '01' AND '31'"
                    )
                    dmy_ok = (
                        f"{head} ~ '^[0-9]{{2}}/[0-9]{{2}}/[0-9]{{4}}$'"
                        f" AND substr({head}, 4, 2) BETWEEN '01' AND '12'"
                        f" AND substr({head}, 1, 2) BETWEEN '01' AND '31'"
                    )
                    # Acepta YYYY-MM-DD (y timestamps) y DD/MM/YYYY, evitando que `to_date` falle con valores inválidos.
                    return (
                        "CASE "
                        f"WHEN {iso_ok} THEN to_date({head}, 'YYYY-MM-DD') "
                        f"WHEN {dmy_ok} THEN to_date({head}, 'DD/MM/YYYY') "
                        "ELSE NULL END"
                    )

                firma_date = _pg_date_expr("fecha_firma")
                encargo_date = _pg_date_expr("fecha_encargo")
                duration_expr = (
                    "CASE "
                    "WHEN fecha_encargo IS NOT NULL AND TRIM(fecha_encargo) <> '' "
                    " AND fecha_firma IS NOT NULL AND TRIM(fecha_firma) <> '' "
                    f" AND {firma_date} IS NOT NULL AND {encargo_date} IS NOT NULL "
                    f"THEN ({firma_date} - {encargo_date})::double precision "
                    "ELSE NULL END"
                )
            else:
                duration_expr = (
                    "CASE "
                    "WHEN fecha_encargo IS NOT NULL AND TRIM(fecha_encargo) <> '' "
                    " AND fecha_firma IS NOT NULL AND TRIM(fecha_firma) <> '' "
                    " AND julianday(fecha_firma) IS NOT NULL AND julianday(fecha_encargo) IS NOT NULL "
                    "THEN julianday(fecha_firma) - julianday(fecha_encargo) "
                    "ELSE NULL END"
                )

            available_years = conn.execute(
                """
                SELECT """
                + signed_year_expr
                + """ AS year, COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_closed_expr
                + """
                  AND """
                + signed_year_expr
                + """ IS NOT NULL
                GROUP BY """
                + signed_year_expr
                + """
                ORDER BY """
                + signed_year_expr
                + """
                """,
                (empresa_id,),
            ).fetchall()
            available_set = {str(r["year"]) for r in available_years if r["year"] is not None}
            selected_year = requested_year or current_year
            if selected_year not in available_set and available_years:
                selected_year = str(available_years[-1]["year"])

            current = conn.execute(
                """
                SELECT
                  COUNT(*) AS total,
                  AVG(
                    CASE
                      WHEN precio IS NOT NULL AND precio > 0 AND importe_hipoteca IS NOT NULL
                        THEN (importe_hipoteca * 100.0 / precio)
                      WHEN porcentaje IS NOT NULL AND porcentaje > 0 AND porcentaje <= 1 THEN porcentaje * 100.0
                      WHEN porcentaje IS NOT NULL AND porcentaje > 1 THEN porcentaje
                      ELSE NULL
                    END
                  ) AS porcentaje_medio,
                  AVG(COALESCE(comision, 0)) AS comision_media,
                  SUM(COALESCE(comision, 0)) AS comision_total,
                  SUM(COALESCE(importe_hipoteca, 0)) AS volumen_total,
                  AVG("""
                + duration_expr
                + """) AS plazo_medio_dias
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_year_expr
                + """ = ?
                  AND """
                + signed_closed_expr
                + """
                """,
                (empresa_id, selected_year),
            ).fetchone()

            totals = conn.execute(
                """
                SELECT
                  COUNT(*) AS total,
                  AVG(
                    CASE
                      WHEN precio IS NOT NULL AND precio > 0 AND importe_hipoteca IS NOT NULL
                        THEN (importe_hipoteca * 100.0 / precio)
                      WHEN porcentaje IS NOT NULL AND porcentaje > 0 AND porcentaje <= 1 THEN porcentaje * 100.0
                      WHEN porcentaje IS NOT NULL AND porcentaje > 1 THEN porcentaje
                      ELSE NULL
                    END
                  ) AS porcentaje_medio,
                  AVG(COALESCE(comision, 0)) AS comision_media,
                  SUM(COALESCE(comision, 0)) AS comision_total,
                  SUM(COALESCE(importe_hipoteca, 0)) AS volumen_total,
                  AVG("""
                + duration_expr
                + """) AS plazo_medio_dias
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_closed_expr
                + """
                """,
                (empresa_id,),
            ).fetchone()

            firmadas_anio = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_year_expr
                + """ = ?
                  AND """
                + signed_closed_expr
                + """
                """,
                (empresa_id, selected_year),
            ).fetchone()

            estudio_anio = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + year_expr
                + """ = ?
                  AND """
                + estudio_expr
                + """
                """,
                (empresa_id, selected_year),
            ).fetchone()

            estudio_total = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + estudio_expr
                + """
                """,
                (empresa_id,),
            ).fetchone()

            pendientes_firma_anio = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + year_expr
                + """ = ?
                  AND """
                + pendientes_firma_expr
                + """
                """,
                (empresa_id, selected_year),
            ).fetchone()

            pendientes_firma_total = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + pendientes_firma_expr
                + """
                """,
                (empresa_id,),
            ).fetchone()

            encargos_anio = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + year_expr
                + """ = ?
                  AND """
                + encargo_expr
                + """
                """,
                (empresa_id, selected_year),
            ).fetchone()

            encargos_total = conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + encargo_expr
                + """
                """,
                (empresa_id,),
            ).fetchone()

            firmadas_mes = conn.execute(
                f"""
                SELECT COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND {signed_expr}
                  AND {closed_expr}
                  AND {signed_month_expr} = ?
                """,
                (empresa_id, current_month),
            ).fetchone()

            series_totales = available_years

            series_volumen = conn.execute(
                """
                SELECT """
                + signed_year_expr
                + """ AS year, SUM(COALESCE(importe_hipoteca, 0)) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_closed_expr
                + """
                  AND """
                + signed_year_expr
                + """ IS NOT NULL
                GROUP BY """
                + signed_year_expr
                + """
                ORDER BY """
                + signed_year_expr
                + """
                """,
                (empresa_id,),
            ).fetchall()

            series_plazo = conn.execute(
                """
                SELECT """
                + signed_year_expr
                + """ AS year, AVG("""
                + duration_expr
                + """) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_closed_expr
                + """
                  AND """
                + signed_year_expr
                + """ IS NOT NULL
                GROUP BY """
                + signed_year_expr
                + """
                ORDER BY """
                + signed_year_expr
                + """
                """,
                (empresa_id,),
            ).fetchall()

            series_comision = compute_hipotecas_commission_series(conn, empresa_id)

            series_porcentaje = conn.execute(
                """
                SELECT """
                + signed_year_expr
                + """ AS year,
                       AVG(
                         CASE
                           WHEN precio IS NOT NULL AND precio > 0 AND importe_hipoteca IS NOT NULL
                             THEN (importe_hipoteca * 100.0 / precio)
                           WHEN porcentaje IS NOT NULL AND porcentaje > 0 AND porcentaje <= 1 THEN porcentaje * 100.0
                           WHEN porcentaje IS NOT NULL AND porcentaje > 1 THEN porcentaje
                           ELSE NULL
                         END
                       ) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND """
                + signed_closed_expr
                + """
                  AND """
                + signed_year_expr
                + """ IS NOT NULL
                GROUP BY """
                + signed_year_expr
                + """
                ORDER BY """
                + signed_year_expr
                + """
                """,
                (empresa_id,),
            ).fetchall()

            entity_total_rows = conn.execute(
                """
                SELECT banco AS label, COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND banco IS NOT NULL
                  AND TRIM(banco) != ''
                  AND """
                + signed_closed_expr
                + """
                GROUP BY banco
                ORDER BY COUNT(*) DESC
                LIMIT 8
                """,
                (empresa_id,),
            ).fetchall()

            entity_year_rows = conn.execute(
                """
                SELECT banco AS label, COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND banco IS NOT NULL
                  AND TRIM(banco) != ''
                  AND """
                + signed_year_expr
                + """ = ?
                  AND """
                + signed_closed_expr
                + """
                GROUP BY banco
                ORDER BY COUNT(*) DESC
                LIMIT 12
                """,
                (empresa_id, selected_year),
            ).fetchall()

            entity_data = build_hipoteca_dashboard_entity_rows(entity_total_rows, entity_year_rows)
            entity_total_rows = entity_data["series_entidades"]
            entity_total_map = entity_data["entity_total_map"]
            entity_year_merged = entity_data["entity_year_rows"]
            entity_total_aliases = entity_data["entity_total_aliases"]
            entity_year_aliases = entity_data["entity_year_aliases"]
            commission_by_bank_year = compute_hipotecas_commission_by_bank(conn, empresa_id, selected_year)
            entities = []
            for row in entity_year_merged[:12]:
                label = str(row.get("label") or "").strip()
                base = entity_total_map.get(label, {"total": 0})
                raw_aliases = sorted(list((entity_year_aliases.get(label) or set()) | (entity_total_aliases.get(label) or set())))
                where_bank = "banco = ?"
                bank_values = [label]
                if raw_aliases:
                    placeholders = ",".join(["?"] * len(raw_aliases))
                    where_bank = f"banco IN ({placeholders})"
                    bank_values = raw_aliases
                metrics = conn.execute(
                    """
                    SELECT
                      SUM(COALESCE(importe_hipoteca, 0)) AS volumen_total,
                      AVG("""
                    + duration_expr
                    + """) AS plazo_medio_dias
                    FROM hipotecas
                    WHERE empresa_id = ?
                      AND """
                    + where_bank
                    + """
                      AND """
                    + signed_year_expr
                    + """ = ?
                      AND """
                    + signed_closed_expr
                    + """
                    """,
                    tuple([empresa_id] + bank_values + [selected_year]),
                ).fetchone()
                entities.append(
                    {
                        "label": label,
                        "year_total": row.get("total") or 0,
                        "total": base.get("total") or 0,
                        "volumen_total": metrics["volumen_total"] if metrics and metrics["volumen_total"] is not None else 0,
                        "plazo_medio_dias": metrics["plazo_medio_dias"] if metrics and metrics["plazo_medio_dias"] is not None else 0,
                        "comision_total": commission_by_bank_year.get(label, 0),
                    }
                )

            series_oficinas = conn.execute(
                """
                SELECT oficina AS label, COUNT(*) AS total
                FROM hipotecas
                WHERE empresa_id = ?
                  AND oficina IS NOT NULL
                  AND TRIM(oficina) != ''
                  AND """
                + signed_closed_expr
                + """
                GROUP BY oficina
                ORDER BY COUNT(*) DESC
                """,
                (empresa_id,),
            ).fetchall()

            conta_year = compute_hipotecas_contabilidad_totals(conn, empresa_id, selected_year)
            conta_total = compute_hipotecas_contabilidad_totals(conn, empresa_id)

            try:
                payload = {
                    "current": {
                        "total": current["total"] if current else 0,
                        "porcentaje_medio": current["porcentaje_medio"] if current else 0,
                        "comision_media": current["comision_media"] if current else 0,
                        "comision_total": conta_year["comision_cliente"],
                        "volumen_total": current["volumen_total"] if current else 0,
                        "plazo_medio_dias": current["plazo_medio_dias"] if current else 0,
                        "firmadas_anio": firmadas_anio["total"] if firmadas_anio else 0,
                        "firmadas_mes": firmadas_mes["total"] if firmadas_mes else 0,
                        "operaciones_estudio": estudio_anio["total"] if estudio_anio else 0,
                        "pendientes_firma": pendientes_firma_anio["total"] if pendientes_firma_anio else 0,
                        "encargos": encargos_anio["total"] if encargos_anio else 0,
                        "ingresos": conta_year["ingresos"],
                        "gastos": conta_year["gastos"],
                        "resultado": conta_year["resultado"],
                        "rentabilidad_ratio": conta_year["rentabilidad_ratio"],
                    },
                    "totals": {
                        "total": totals["total"] if totals else 0,
                        "porcentaje_medio": totals["porcentaje_medio"] if totals else 0,
                        "comision_media": totals["comision_media"] if totals else 0,
                        "comision_total": conta_total["comision_cliente"],
                        "volumen_total": totals["volumen_total"] if totals else 0,
                        "plazo_medio_dias": totals["plazo_medio_dias"] if totals else 0,
                        "operaciones_estudio": estudio_total["total"] if estudio_total else 0,
                        "pendientes_firma": pendientes_firma_total["total"] if pendientes_firma_total else 0,
                        "encargos": encargos_total["total"] if encargos_total else 0,
                        "ingresos": conta_total["ingresos"],
                        "gastos": conta_total["gastos"],
                        "resultado": conta_total["resultado"],
                        "rentabilidad_ratio": conta_total["rentabilidad_ratio"],
                    },
                    "current_year": selected_year,
                    "available_years": [str(r["year"]) for r in available_years if r["year"] is not None],
                    "series_totales": [dict(r) for r in series_totales],
                    "series_comision": [dict(r) for r in series_comision],
                    "series_porcentaje": [dict(r) for r in series_porcentaje],
                    "series_volumen": [dict(r) for r in series_volumen],
                    "series_plazo": [dict(r) for r in series_plazo],
                    "series_entidades": [dict(r) for r in entity_total_rows],
                    "entity_kpis": entities,
                    "series_oficinas": [dict(r) for r in series_oficinas],
                    "hipotecas_sync": sync_state,
                }
                try:
                    with Handler._hipoteca_dashboard_lock:
                        Handler._hipoteca_dashboard_cache[cache_key] = (now_ts + 6.0, payload)
                        if len(Handler._hipoteca_dashboard_cache) > 200:
                            for k, (exp, _val) in list(Handler._hipoteca_dashboard_cache.items())[:80]:
                                if exp <= now_ts:
                                    Handler._hipoteca_dashboard_cache.pop(k, None)
                except Exception:
                    pass
                json_response(self, payload)
                return
            except Exception as exc:
                try:
                    Handler._record_api_error("/api/hipoteca_dashboard:build_payload", exc)
                except Exception:
                    pass
                if cached_payload:
                    json_response(self, cached_payload)
                    return
                json_response(self, {"error": "Base de datos ocupada. Reintenta."}, status=503)
                return

        if path == "/api/hipoteca_bdt":
            empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
            record_id = (params.get("id", [""])[0] or "").strip()
            q = (params.get("q", [""])[0] or "").strip()
            limit_raw = (params.get("limit", ["1000"])[0] or "1000").strip()
            include_json = (params.get("include_json", ["0"])[0] or "0").strip() in ("1", "true", "yes")
            if not empresa_id:
                json_response(self, {"error": "empresa_id requerido"}, status=400)
                return
            try:
                limit = int(limit_raw)
            except ValueError:
                limit = 1000
            limit = max(1, min(limit, 5000))

            all_columns = sorted([str(c) for c in (table_columns(conn, "hipotecas") or set()) if str(c).strip()])
            # Campos internos/ruidosos. Los *_json pueden ser voluminosos: solo se incluyen si se piden explícitamente.
            hidden = {"empresa_id", "created_at", "updated_at"}
            if not include_json:
                hidden.update({"cliente_inmueble_json", "hipoteca_detalle_json", "liquidacion_json"})
            columns = [col for col in all_columns if col not in hidden]
            if "id" in columns:
                columns = ["id"] + [c for c in columns if c != "id"]
            text_columns = [col for col in columns if col != "id"]

            def quote_ident(value: str) -> str:
                return '"' + str(value or "").replace('"', '""') + '"'

            where = ["empresa_id = ?"]
            values: list[object] = [empresa_id]
            if record_id:
                where.append("id = ?")
                values.append(record_id)
            if q and text_columns:
                # En Postgres, columnas numéricas necesitan CAST para usar LIKE.
                likes = " OR ".join([f"CAST({quote_ident(col)} AS TEXT) LIKE ?" for col in text_columns])
                where.append(f"({likes})")
                values.extend([f"%{q}%"] * len(text_columns))
            elif q and not text_columns:
                json_response(self, {"columns": columns, "rows": []})
                return

            select_cols = ", ".join([quote_ident(col) for col in columns])
            where_clause = " AND ".join(where)
            meta_rows = conn.execute(
                f"""
                SELECT anio, fecha_firma, fecha_encargo, estado
                FROM hipotecas
                WHERE {where_clause}
                """,
                values,
            ).fetchall()
            filters = collect_hipoteca_bdt_filter_options(meta_rows)
            rows = conn.execute(
                f"""
                SELECT {select_cols}
                FROM hipotecas
                WHERE {where_clause}
                ORDER BY COALESCE(NULLIF(fecha_firma, ''), NULLIF(fecha_encargo, ''), updated_at, created_at) DESC
                LIMIT {limit}
                """,
                values,
            ).fetchall()
            json_response(self, {"columns": columns, "rows": [row_to_cells(r, columns) for r in rows], "filters": filters})
            return

        if path == "/api/hipotecas_audit_descuadres":
            empresa_id = (params.get("empresa_id", [""])[0] or "").strip()
            empresa_nombre = (params.get("empresa_nombre", [""])[0] or "").strip()
            limit_raw = (params.get("limit", ["2000"])[0] or "2000").strip()
            only_mismatch = (params.get("only_mismatch", ["1"])[0] or "1").strip().lower() in ("1", "true", "yes")
            include_incomplete = (params.get("include_incomplete", ["1"])[0] or "1").strip().lower() in ("1", "true", "yes")
            if not empresa_id and empresa_nombre:
                empresa = get_empresa_by_nombre(conn, empresa_nombre)
                if empresa:
                    empresa_id = str(empresa["id"] or "").strip()
            if not empresa_id:
                json_response(self, {"error": "empresa_id o empresa_nombre requerido"}, status=400)
                return
            try:
                limit = int(limit_raw)
            except ValueError:
                limit = 2000
            limit = max(1, min(limit, 10000))

            rows = conn.execute(
                """
                SELECT *
                FROM hipotecas
                WHERE empresa_id = ?
                ORDER BY COALESCE(NULLIF(fecha_firma, ''), NULLIF(fecha_encargo, ''), updated_at, created_at) DESC
                LIMIT ?
                """,
                (empresa_id, limit),
            ).fetchall()

            counts = {"total": len(rows), "ok": 0, "mismatch": 0, "incomplete": 0}
            items = []
            for row in rows:
                record_id = str(row["id"] or "").strip()
                cliente = str(row["cliente"] or "").strip()
                banco = str(row["banco"] or "").strip()
                fecha_firma = str(row["fecha_firma"] or "").strip()
                estado = str(row["estado"] or "").strip()

                liquidacion_raw = {}
                try:
                    if "liquidacion_json" in row.keys():
                        liquidacion_raw = _safe_json_object(row["liquidacion_json"] or "{}")
                except Exception:
                    liquidacion_raw = {}

                export_row = build_hipoteca_export_row(conn, row)
                computed = compute_hipoteca_liquidacion_print_data(export_row, liquidacion_raw)
                liq = computed.get("liq") if isinstance(computed.get("liq"), dict) else {}
                flags = computed.get("flags") if isinstance(computed.get("flags"), dict) else {}

                comprador = liq.get("comprador") if isinstance(liq.get("comprador"), dict) else {}
                cuadre = liq.get("cuadre") if isinstance(liq.get("cuadre"), dict) else {}

                sobran_comprador = parse_money_value(comprador.get("sobran_en_cuenta") or 0)
                sobran_cuadre = parse_money_value(cuadre.get("sobran_en_cuenta") or 0)
                delta_sobrante = _round2(sobran_comprador - sobran_cuadre)
                diff_medios_pago = parse_money_value(cuadre.get("diferencia_medios_pago") or 0)

                issues = []
                precio_compra = parse_money_value(comprador.get("precio_compra") or 0)
                escriturado = parse_money_value(comprador.get("escriturado") or 0)
                if abs(delta_sobrante) > 0.01:
                    issues.append(f"Descuadre sobrante: Δ {delta_sobrante:.2f}.")
                if abs(diff_medios_pago) > 0.01:
                    issues.append(f"Medios de pago no cuadran: Δ {diff_medios_pago:.2f}.")

                incomplete_issues = []
                if not precio_compra or precio_compra <= 0:
                    incomplete_issues.append("Falta precio_compra.")
                if not escriturado or escriturado <= 0:
                    incomplete_issues.append("Falta escriturado.")

                if incomplete_issues:
                    status = "incomplete"
                    counts["incomplete"] += 1
                    issues = incomplete_issues + issues
                elif issues:
                    status = "mismatch"
                    counts["mismatch"] += 1
                else:
                    status = "ok"
                    counts["ok"] += 1

                if only_mismatch and status == "ok":
                    continue
                if not include_incomplete and status == "incomplete":
                    continue

                items.append(
                    {
                        "id": record_id,
                        "cliente": cliente,
                        "banco": banco,
                        "estado": estado,
                        "fecha_firma": fecha_firma,
                        "status": status,
                        "sobran_comprador": sobran_comprador,
                        "sobran_cuadre": sobran_cuadre,
                        "delta_sobrante": delta_sobrante,
                        "diferencia_medios_pago": diff_medios_pago,
                        "cuadre_sobrante_ok": bool(flags.get("cuadre_sobrante_ok")),
                        "issues": issues,
                    }
                )

                if len(items) >= 500:
                    break

            json_response(self, {"counts": counts, "items": items})
            return

